  private resolveEntityFilePath(name: string): string | null {
    if (typeof name !== "string") return null;
    const filePath = path.resolve(this.entitiesDir, `${name}.md`);
    const relative = path.relative(this.entitiesDir, filePath);
    if (relative === "" || relative.startsWith("..") || path.isAbsolute(relative)) {
      return null;
    }
    return filePath;
  }
  private readStorageSecureFile(filePath: string): Promise<string> {
    return readMaybeEncryptedFile(filePath, this._secureStoreKey, this.baseDir);
  }
  async readDependencyPropagationQueueFile(filePath: string): Promise<string> {
    const target = await resolveSafeStoragePath(
      this.baseDir,
      path.relative(
        this.baseDir,
        this.assertManagedStoragePath(filePath, "storage.readDependencyPropagationQueueFile"),
      ),
    );
    return this.readStorageSecureFile(target);
  }
  async writeDependencyPropagationQueueFile(filePath: string, content: string): Promise<void> {
    const target = await resolveSafeStoragePath(
      this.baseDir,
      path.relative(
        this.baseDir,
        this.assertManagedStoragePath(filePath, "storage.writeDependencyPropagationQueueFile"),
      ),
    );
    return this.writeStorageSecureFile(target, content);
  }
  protected writeStorageSecureFile(
    filePath: string,
    content: string | Buffer,
    forceEncrypt = false,
    secureOptions?: { aadFilePath?: string }
  ): Promise<void> {
    assertNotOkfReservedBasename(filePath);
    const writeKey = this.resolveWriteKey(forceEncrypt);
    return writeMaybeEncryptedFile(filePath, content, writeKey, secureOptions ?? {}, this.baseDir).then(() => {
      // No manual sniff-cache update needed (issue #1909 round 10): this rewrite
      // changes the file's (size, mtime), so isEncryptedFileHeader re-sniffs on
      // the next append when its identity check misses. Identity validation also
      // covers PEER rewrites that this hook never sees.
      this.notifyCatalogWriteForPath(filePath);
    });
  }

  protected assertManagedStoragePath(filePath: string, method: string): string {
    const resolved = path.resolve(filePath);
    const base = path.resolve(this.baseDir);
    const rel = path.relative(base, resolved);
    if (rel === "" || rel === ".." || rel.startsWith(`..${path.sep}`) || path.isAbsolute(rel)) {
      throw new Error(`${method}: file path escapes memory dir`);
    }
    return resolved;
  }
