  async cleanExpiredCommitments(decayDays: number): Promise<MemoryFile[]> {
    const memories = await this.readAllMemories();
    const cutoff = Date.now() - decayDays * 24 * 60 * 60 * 1000;
    const deleted: MemoryFile[] = [];

    for (const m of memories) {
      if (m.frontmatter.category !== "commitment") continue;
      // Only decay commitments that have been marked as resolved/expired
      // (indicated by tags containing "fulfilled" or "expired")
      const isResolved = m.frontmatter.tags.some((t) => t === "fulfilled" || t === "expired");
      if (!isResolved) continue;

      const updatedAt = new Date(m.frontmatter.updated).getTime();
      if (updatedAt >= cutoff) continue;
      try {
        const removed = await this.deleteMemoryForMaintenance(m, (current) => {
          const currentResolved = current.frontmatter.tags.some((tag) => tag === "fulfilled" || tag === "expired");
          const currentUpdatedAt = new Date(current.frontmatter.updated).getTime();
          return currentResolved && currentUpdatedAt < cutoff;
        });
        if (removed) {
          deleted.push(removed);
          log.debug(`cleaned expired commitment ${removed.frontmatter.id}`);
        }
      } catch {
        // Ignore
      }
    }

    if (deleted.length > 0) {
      this.bumpMemoryStatusVersion();
    }

    return deleted;
  }

  // ---------------------------------------------------------------------------
  // Access Tracking (Phase 1A)
  // ---------------------------------------------------------------------------

  /**
   * Flush batched access tracking updates to disk.
   * Called during consolidation or when buffer exceeds max size.
   */
  async flushAccessTracking(entries: AccessTrackingEntry[]): Promise<number> {
    if (entries.length === 0) return 0;

    const memories = await this.readAllMemories();
    const memoryMap = new Map(memories.map((m) => [m.frontmatter.id, m]));
    const memoryPathMap = new Map(memories.map((m) => [path.resolve(m.path), m]));
    let updated = 0;
    // Corpus version and warmth are snapshotted before the writes (#1902).
    const prevVersion = this.getMemoryCorpusVersion();
    let entityRefMoved = false;
    // Snapshot the secure-store key identity once (Cursor Medium #1902), mirroring
    // readAllMemories/patchHotMemoriesCache: a mid-flush setSecureStoreKey change
    // would otherwise let loop patches or the re-keyed entry be stored under a
    // different identity than the one that decrypted this corpus.
    const keyId = this.hotCacheKeyId();
    const warm =
      this.hotMemoriesCacheEnabled &&
      getCachedMemories(this.baseDir, prevVersion, keyId, this.hotCacheTtlMs()) !== null;
    // Record each applied patch so the end-of-flush re-key can re-apply them on
    // top of whatever is cached at prevVersion — robust to a concurrent scan
    // that republished an UNpatched corpus mid-flush (Cursor Medium #1902).
    const appliedPatches = new Map<string, { accessCount: number; lastAccessed: string }>();

    for (const entry of entries) {
      const memory = entry.memoryPath
        ? memoryPathMap.get(path.resolve(entry.memoryPath))
        : memoryMap.get(entry.memoryId);
      if (!memory) continue;

      try {
        const applied = await this.withTombstoneBlockedMemoryPathLock(memory.path, async (current) => {
          if (current?.frontmatter.id !== entry.memoryId) return null;
          const rowIds = this.currentHistoricalIds();
          const newFm: MemoryFrontmatter = entityRefs.canonicalizeEntityRefOption(
            { ...current.frontmatter, accessCount: entry.newCount, lastAccessed: entry.lastAccessed },
            rowIds
          );
          const fileContent = `${serializeFrontmatter(this.withOkfType(newFm))}\n\n${current.content}\n`;
          await this.writeTombstoneBlockedFrontmatter(current, fileContent, newFm);
          if (typeof current.frontmatter.entityRef === "string") {
            await this.entityRefRepair.repair(
              current.path,
              newFm,
              current.frontmatter.entityRef,
              rowIds,
              current.content,
              { onFailRestore: current }
            );
          }
          if (!entityMentionEpoch.neutral(current.frontmatter, newFm)) entityRefMoved = true;
          return { current, newFm };
        });
        if (applied === null) continue;
        if (warm) {
          updateCacheOnWrite(this.baseDir, { ...applied.current, frontmatter: applied.newFm }, keyId);
        }
        appliedPatches.set(path.resolve(memory.path), {
          accessCount: entry.newCount,
          lastAccessed: entry.lastAccessed,
        });
        updated++;
      } catch (err) {
        log.debug(`failed to update access tracking for ${entry.memoryId}: ${err}`);
      }
    }

    if (updated > 0) {
      // Advance the corpus sentinel so peers rescan (#1902). Re-key local patches
      // only when this bump was exclusive; a peer write must rescan instead.
      const { produced, exclusive } = this.bumpMemoryCorpusVersionExclusive({
        indexedText: entityRefMoved ? undefined : false,
      });
      // Drop the in-flight read slot after the bump (parity with
      // patchHotMemoriesCache, Cursor Medium #1902): a readAllMemories scan that
      // started before the flush would otherwise keep awaiting a pre-flush scan
      // and could republish it at the old version, clobbering our patches. New
      // readers now start a fresh scan at the bumped version.
      deleteInFlightReadsForDir(this.baseDir);
      if (
        warm &&
        exclusive &&
        !entityRefMoved &&
        produced === prevVersion + 1 &&
        this.getMemoryCorpusVersion() === produced &&
        this.hotCacheKeyId() === keyId
      ) {
        const cur = getCachedMemories(this.baseDir, prevVersion, keyId);
        if (cur) {
          // Re-apply our patches on top of whatever is cached at prevVersion
          // before re-keying (Cursor Medium #1902): a concurrent readAllMemories
          // that finished in the prevVersion epoch may have republished a full
          // UNpatched corpus via its publish guard, clobbering our in-loop
          // updateCacheOnWrite patches. Re-applying is idempotent and makes the
          // re-key robust to that race; the publish guard blocks any scan
          // finishing AFTER our bump, so this is the only window.
          const reapplied = cur.map((m) => {
            const patch = appliedPatches.get(path.resolve(m.path));
            return patch
              ? {
                  ...m,
                  frontmatter: { ...m.frontmatter, accessCount: patch.accessCount, lastAccessed: patch.lastAccessed },
                }
              : m;
          });
          setCachedMemories(this.baseDir, reapplied, produced, keyId, this.hotCacheTtlMs());
        }
      }
      // Evict the derived (episode/rule) + global (QMD recall/search) layers,
      // mirroring patchHotMemoriesCache (Cursor Medium, #1902). The hot layer is
      // patched + re-keyed above; without this the derived caches linger at
      // prevVersion and the QMD recall bundle keeps pre-flush accessCount-based
      // boost ordering until an unrelated mutation invalidates them.
      invalidateDerivedAndGlobalForDir(this.baseDir);
      log.debug(`flushed access tracking for ${updated} memories`);
    }
    return updated;
  }

  async getMemoryById(id: string): Promise<MemoryFile | null> {
    const memories = await this.readAllMemories();
    return memories.find((m) => m.frontmatter.id === id) ?? null;
  }

  async getMemoryByIdIncludingArchived(id: string): Promise<MemoryFile | null> {
    const active = await this.getMemoryById(id);
    return active ?? (await this.readAllColdMemories()).find((memory) => memory.frontmatter.id === id) ??
      (await this.readArchivedMemories()).find((memory) => memory.frontmatter.id === id) ?? null;
  }

  /** Resolve existing active memory IDs through a lightweight directory scan. */
  async findExistingMemoryPaths(
    ids: string[],
    preferredPaths: Map<string, string[]> = new Map()
  ): Promise<Map<string, string[]>> {
    if (ids.length === 0) return new Map();
    const wantedIds = new Set(ids);
    const filePaths = await this.collectActiveMemoryPaths();
    const pathsById = new Map<string, string[]>();
    const filePathsById = new Map<string, string[]>();
    for (const filePath of filePaths) {
      const memoryId = path.basename(filePath, ".md");
      if (!wantedIds.has(memoryId)) continue;
      const paths = filePathsById.get(memoryId) ?? [];
      paths.push(filePath);
      filePathsById.set(memoryId, paths);
    }
    for (const id of wantedIds) {
      const existingPaths = filePathsById.get(id) ?? [];
      const preferred = preferredPaths.get(id) ?? [];
      const preferredMatches: string[] = [];
      for (const preferredPath of preferred) {
        const directCandidates = new Set(qmdResultPathCandidates(this.baseDir, preferredPath));
        const directMatch = existingPaths.find((filePath) => directCandidates.has(path.resolve(filePath)));
        if (directMatch) {
          preferredMatches.push(directMatch);
          continue;
        }

        const candidates = new Set<string>();
        const parts = qmdCollectionPathParts(preferredPath);
        if (parts) {
          for (const candidate of qmdResultPathCandidates(this.baseDir, parts.relativePath)) {
            candidates.add(candidate);
          }
        }
        const match = existingPaths.find((filePath) => candidates.has(path.resolve(filePath)));
        if (match) preferredMatches.push(match);
      }
      if (preferredMatches.length > 0) {
        pathsById.set(id, preferredMatches);
      } else if (existingPaths.length > 0) {
        pathsById.set(id, existingPaths);
      }
    }
    return pathsById;
  }

  /**
   * Check which of the given memory IDs actually exist on disk.
   */
  async filterExistingMemoryIds(ids: string[]): Promise<Set<string>> {
    return new Set((await this.findExistingMemoryPaths(ids)).keys());
  }

  async getProjectedMemoryState(id: string): Promise<MemoryProjectionCurrentState | null> {
    const projected = readProjectedMemoryState(this.baseDir, id);
    if (projected) return projected;
    warnProjectionFallback(this.baseDir, "getProjectedMemoryState");
    const active = await this.getMemoryById(id);
    if (active) return this.toProjectedCurrentState(active, "active");

    const archived = (await this.readArchivedMemories()).find((memory) => memory.frontmatter.id === id);
    if (!archived) return null;

    return this.toProjectedCurrentState(archived, "archived");
  }

  async browseProjectedMemories(options: ProjectedMemoryBrowseOptions): Promise<ProjectedMemoryBrowsePage | null> {
    return (
      readProjectedMemoryBrowse(this.baseDir, options) ??
      warnProjectionFallback(this.baseDir, "browseProjectedMemories")
    );
  }

  async getProjectedGovernanceRecord(): Promise<ReturnType<typeof readProjectedGovernanceRecord>> {
    return readProjectedGovernanceRecord(this.baseDir);
  }

  private toProjectedCurrentState(memory: MemoryFile, fallbackStatus: MemoryStatus): MemoryProjectionCurrentState {
    const pathRel = toMemoryPathRel(this.baseDir, memory.path);
    return {
      memoryId: memory.frontmatter.id,
      category: memory.frontmatter.category,
      status: inferCurrentStateStatus(memory.frontmatter, pathRel, fallbackStatus),
      lifecycleState: memory.frontmatter.lifecycleState,
      path: memory.path,
      pathRel,
      created: memory.frontmatter.created,
      updated: memory.frontmatter.updated,
      archivedAt: memory.frontmatter.archivedAt,
      supersededAt: memory.frontmatter.supersededAt,
      entityRef: memory.frontmatter.entityRef,
      source: memory.frontmatter.source,
      confidence: memory.frontmatter.confidence,
      confidenceTier: memory.frontmatter.confidenceTier,
      memoryKind: memory.frontmatter.memoryKind,
      accessCount: memory.frontmatter.accessCount,
      lastAccessed: memory.frontmatter.lastAccessed,
      tags: normalizeProjectionTags(memory.frontmatter.tags),
      preview: normalizeProjectionPreview(memory.content),
      privateRecord: isSupportPassportPrivateMemory(memory),
    };
  }

  async getMemoryTimeline(memoryId: string, limit: number = 200): Promise<MemoryLifecycleEvent[]> {
    const cappedLimit = Math.max(0, Math.floor(limit));
    if (cappedLimit === 0) return [];

    const projected = readProjectedMemoryTimeline(this.baseDir, memoryId, cappedLimit);
    if (projected && projected.length > 0) return projected;
    return this.projectionLedgerLagManager.resolveTimelineWithLag({
      baseDir: this.baseDir,
      ledgerPath: this.memoryLifecycleLedgerPath,
      memoryId,
      cappedLimit,
      readSecureFile: (p) => this.readStorageSecureFile(p),
      projectionAge: () => formatProjectionAge(readProjectionRebuiltAt(this.baseDir)),
    });
  }

  // ---------------------------------------------------------------------------
  // Chunking (Phase 2A)
  // ---------------------------------------------------------------------------

  /**
   * Write a memory chunk with parent reference.
   * Chunk IDs follow format: {parentId}-chunk-{index}
   */
  async writeChunk(
    parentId: string,
    chunkIndex: number,
    chunkTotal: number,
    category: MemoryCategory,
    content: string,
    options: {
      confidence?: number;
      tags?: string[];
      entityRef?: string;
      source?: string;
      importance?: ImportanceScore;
      intentGoal?: string;
      intentActionType?: string;
      intentEntityTypes?: string[];
      memoryKind?: MemoryFrontmatter["memoryKind"];
      validAt?: string;
      /** Lifecycle status (issue #1576): pending_review chunks stay out of active recall. */
      status?: import("./types.js").MemoryStatus;
      /**
       * Tombstone block provenance (issue #1645): when the parent fact was
       * tombstone-blocked, propagate the tombstone id onto each chunk so an
       * independently-surfaced chunk (memory_get/x-ray/doctor) reveals the block
       * and the chunk stays pending_review, never an active resurrection.
       */
      blockedBy?: string;
      /** Faithfulness gate verdict (issue #1576), propagated from the parent fact. */
      faithfulness?: import("./types.js").FaithfulnessFrontmatter;
      /** Claim-level provenance spans (issue #1575 PR 2), propagated from the parent fact so a chunk surfaced independently (memory_get/x-ray) preserves them (chatgpt-codex-connector thread Ocvmo). */
      sources?: ProvenanceSource[];
      /** Coarse provenance tag (issue #1575 PR 2), propagated from the parent. */
      provenance?: "verified" | "unverified" | "none";
      // Issue #1578 — bi-temporal bounds + ingestion provenance propagated from
      // the parent fact so an independently-surfaced chunk expires at the same
      // invalid_at window and carries the same observed-at anchor.
      invalidAt?: string;
      observedAt?: string;
      eventTimeSource?: "extracted" | "assumed";
      sourceConnector?: string;
      origin?: string;
      toolScoped?: true;
    } = {}
  ): Promise<string> {
    await this.ensureDirectories();
    const rawEntityRef = options.entityRef;
    let refIds = typeof options.entityRef === "string" ? this.currentHistoricalIds() : null;
    if (refIds) options = entityRefs.canonicalizeEntityRefOption(options, refIds);
    const now = new Date();
    const today = now.toISOString().slice(0, 10);
    const id = `${parentId}-chunk-${chunkIndex}`;
    const conf = options.confidence ?? 0.8;
    const tier = confidenceTier(conf);
    const validAt = normalizeMemoryWriteTimestamp("validAt", options.validAt);
    const chunkInvalidAt = normalizeMemoryWriteTimestamp("invalidAt", options.invalidAt);
    const chunkObservedAt = normalizeMemoryWriteTimestamp("observedAt", options.observedAt);
    const sanitized = sanitizeMemoryContent(content);
    if (!sanitized.clean) {
      log.warn(`chunk content sanitized for ${id}; violations=${sanitized.violations.join(", ")}`);
    }

    const fm: MemoryFrontmatter = {
      id,
      category,
      created: now.toISOString(),
      updated: now.toISOString(),
      source: options.source ?? "chunking",
      confidence: conf,
      confidenceTier: tier,
      tags: options.tags ?? [],
      entityRef: options.entityRef,
      importance: options.importance,
      parentId,
      chunkIndex,
      chunkTotal,
      intentGoal: options.intentGoal,
      intentActionType: options.intentActionType,
      intentEntityTypes: options.intentEntityTypes,
      memoryKind: options.memoryKind,
      valid_at: validAt,
      invalid_at: chunkInvalidAt,
      observedAt: chunkObservedAt,
      eventTimeSource: options.eventTimeSource,
      ...(options.status ? { status: options.status } : {}),
      ...(options.blockedBy ? { blockedBy: options.blockedBy } : {}),
      ...(options.faithfulness ? { faithfulness: options.faithfulness } : {}),
      ...(options.sources ? { sources: options.sources } : {}),
      ...(options.provenance ? { provenance: options.provenance } : {}),
      ...(options.sourceConnector ? { sourceConnector: options.sourceConnector } : {}),
      ...(options.origin ? { origin: parseOriginClass(options.origin) } : {}),
      ...(options.toolScoped ||
      withholdToolScopedFromSharedNamespace({
        content: sanitized.text,
        sourceConnector: options.sourceConnector,
      })
        ? { toolScoped: true as const }
        : {}),
    };

    const filePath = await this.resolveCategoryWritePath(category, id, today);
    const fileContent = `${serializeFrontmatter(this.withOkfType(fm))}\n\n${sanitized.text}\n`;

    const written = await this.writeTombstoneBlockedChunk(
      filePath,
      fileContent,
      fm,
      sanitized.text,
      () => this.findExistingTombstoneBlockedMemory(sanitized.text, category, fm.sourceConnector),
      async (priorChunk) => {
        if (refIds && typeof rawEntityRef === "string") {
          await this.entityRefRepair.repair(filePath, fm, rawEntityRef, refIds, sanitized.text, {
            regateFact: true,
            ...(priorChunk ? { onFailRestore: priorChunk } : { onFailRemove: filePath }),
          });
        }
        // Keep the version-keyed hot-memories cache coherent with the new chunk
        // file (issue #1902) — same single-file patch path writeMemory uses.
        await this.patchHotMemoriesCache({ addedPath: filePath }, "memory-create");
        log.debug(`wrote chunk ${id} (${chunkIndex + 1}/${chunkTotal}) to ${filePath}`);
      }
    );
    return written;
  }

  /**
   * Get all chunks for a given parent memory ID.
   * Returns chunks sorted by chunkIndex.
   */
  async getChunksForParent(parentId: string): Promise<MemoryFile[]> {
    const memories = await this.readAllMemories();
    return memories
      .filter((m) => m.frontmatter.parentId === parentId)
      .sort((a, b) => (a.frontmatter.chunkIndex ?? 0) - (b.frontmatter.chunkIndex ?? 0));
  }

  async supersedeMemory(
    oldMemoryId: string,
    newMemoryId: string,
    reason: string,
    supersessionMetadata?: Pick<MemoryFrontmatter, "supersessionCause" | "invalidatedBy">,
    options: {
      actor?: string; requireActive?: boolean; acceptExactReplay?: boolean;
      expectedSnapshot?: Pick<MemoryFile, "content" | "frontmatter"> & Partial<Pick<MemoryFile, "path">>;
      audit?: SupersessionAuditOptions;
    } = {},
  ): Promise<boolean> {
    const matchesSupersession = (memory: MemoryFile): boolean =>
      memory.frontmatter.status === "superseded" &&
      memory.frontmatter.supersededBy === newMemoryId &&
      (supersessionMetadata === undefined ||
        (memory.frontmatter.supersessionCause === supersessionMetadata.supersessionCause &&
          memory.frontmatter.invalidatedBy === supersessionMetadata.invalidatedBy));
    const isExactReplay = (memory: MemoryFile): boolean =>
      options.acceptExactReplay === true && matchesSupersession(memory);
    let oldMemory: MemoryFile | undefined;
    if (options.expectedSnapshot?.path) {
      const selected = await this.readMemoryByPath(options.expectedSnapshot.path);
      if (!selected || selected.frontmatter.id !== oldMemoryId) {
        return false;
      }
      if (
        invalidationCommitFingerprint(selected) !== invalidationCommitFingerprint(options.expectedSnapshot) &&
        !isExactReplay(selected)
      ) {
        return false;
      }
      oldMemory = selected;
    } else {
      const memories = [
        ...(await this.readAllMemories()),
        ...(await this.readAllColdMemories()),
        ...(await this.readArchivedMemories()),
      ];
      const candidates = memories.filter((memory) => memory.frontmatter.id === oldMemoryId);
      oldMemory =
        candidates.find(
          (memory) =>
            inferMemoryStatus(memory.frontmatter, toMemoryPathRel(this.baseDir, memory.path)) === "active",
        ) ??
        candidates.find(isExactReplay) ??
        candidates[0];
      if (
        oldMemory &&
        options.expectedSnapshot &&
        invalidationCommitFingerprint(oldMemory) !== invalidationCommitFingerprint(options.expectedSnapshot) &&
        !isExactReplay(oldMemory)
      ) {
        return false;
      }
    }
    if (!oldMemory) return false;
    const requireActiveAtWrite =
      options.requireActive === true ||
      inferMemoryStatus(oldMemory.frontmatter, toMemoryPathRel(this.baseDir, oldMemory.path)) === "active";

    const operationId = createHash("sha256")
      .update(
        JSON.stringify({
          oldMemoryId,
          newMemoryId,
          reason,
          supersessionMetadata: supersessionMetadata ?? null,
        }),
      )
      .digest("hex");
    const initialNow = new Date().toISOString();
    let currentBefore = oldMemory;
    let updatedFm = oldMemory.frontmatter;
    let exactReplay = false;

    try {
      const written = await this.withTombstoneBlockedMemoryPathLock(oldMemory.path, async (current) => {
        if (current?.frontmatter.id !== oldMemoryId) return false;
        if (matchesSupersession(current)) {
          currentBefore = current;
          updatedFm = current.frontmatter;
          return options.acceptExactReplay === true ? "exact-replay" : false;
        }
        if (
          options.expectedSnapshot &&
          invalidationCommitFingerprint(current) !== invalidationCommitFingerprint(options.expectedSnapshot)
        ) {
          return false;
        }
        if (
          current.frontmatter.supersededBy !== undefined ||
          (requireActiveAtWrite &&
            inferMemoryStatus(current.frontmatter, toMemoryPathRel(this.baseDir, current.path)) !== "active")
        ) {
          return false;
        }
        currentBefore = current;
        const refIdsAtWrite = this.currentHistoricalIds();
        updatedFm = entityRefs.canonicalizeEntityRefOption(
          {
            ...current.frontmatter,
            ...supersessionMetadata,
            status: "superseded",
            supersededBy: newMemoryId,
            supersededAt: initialNow,
            updated: initialNow,
          },
          refIdsAtWrite
        );
        const fileContent = `${serializeFrontmatter(this.withOkfType(updatedFm))}\n\n${current.content}\n`;
        await this.writeTombstoneBlockedFrontmatter(current, fileContent, updatedFm);
        if (this.isColdOrArchiveTierPath(current.path)) this.invalidateColdMemoriesCache();
        if (typeof current.frontmatter.entityRef === "string") {
          await this.entityRefRepair.repair(
            current.path,
            updatedFm,
            current.frontmatter.entityRef,
            refIdsAtWrite,
            current.content,
            { onFailRestore: current }
          );
        }
        return true;
      });
      if (!written) return false;
      exactReplay = written === "exact-replay";
      const mentionBefore = { entityRef: currentBefore.frontmatter.entityRef, origin: currentBefore.frontmatter.origin };
      if (exactReplay && typeof updatedFm.entityRef === "string") {
        await this.entityRefRepair.repair(
          currentBefore.path,
          updatedFm,
          updatedFm.entityRef,
          this.currentHistoricalIds(),
          currentBefore.content,
          { onFailRestore: currentBefore },
        );
      }
      const mentionUnchanged = entityMentionEpoch.neutral(mentionBefore, updatedFm);
      const supersededAt = updatedFm.supersededAt ?? initialNow;
      const beforeState = this.summarizeLifecycleState(
        currentBefore.frontmatter,
        currentBefore.path,
      );
      const afterState = this.summarizeLifecycleState(updatedFm, currentBefore.path);
      const sideEffectsComplete = await runSupersessionSideEffects({
        oldMemoryId,
        newMemoryId,
        reason,
        now: supersededAt,
        operationId,
        exactReplay,
        currentBefore,
        updatedFm,
        actor: options.actor, audit: options.audit,
        citationTemplate: this.citationTemplate,
        correctionsDir: this.correctionsDir,
        readMemoryByPath: (filePath) => this.readMemoryByPath(filePath),
        isColdOrArchiveTierPath: (memoryPath) => this.isColdOrArchiveTierPath(memoryPath),
        invalidateColdMemoriesCache: () => this.invalidateColdMemoriesCache(),
        invalidateAllMemoriesCache: () => this.invalidateAllMemoriesCache({ indexedText: mentionUnchanged ? false : undefined }),
        bumpMemoryCorpusVersion: () => this.bumpMemoryCorpusVersion({ indexedText: mentionUnchanged ? false : undefined }),
        appendLifecycleEvent: async () => {
          let lifecycleEvents: MemoryLifecycleEvent[] = [];
          try {
            lifecycleEvents = await this.getMemoryTimeline(oldMemoryId, 200);
          } catch (error) {
            log.warn(`supersession lifecycle replay check failed for ${oldMemoryId}: ${error}`);
          }
          if (
            lifecycleEvents.some(
              (event) =>
                event.memoryId === oldMemoryId &&
                event.eventType === "superseded" &&
                (event.correlationId === operationId ||
                  (event.correlationId === undefined &&
                    event.reasonCode === reason &&
                    event.timestamp === supersededAt &&
                    event.relatedMemoryIds?.includes(newMemoryId))),
            )
          ) {
            return;
          }
          await this.appendGeneratedMemoryLifecycleEventFailOpen("storage.supersedeMemory", {
            memoryId: oldMemoryId,
            eventType: "superseded",
            timestamp: supersededAt,
            actor: options.actor ?? "storage.supersedeMemory",
            reasonCode: reason,
            before: exactReplay ? { ...beforeState, status: "active" } : beforeState,
            after: afterState,
            relatedMemoryIds: [newMemoryId],
            correlationId: operationId,
          });
        },
        bumpMemoryStatusVersion: () => this.bumpMemoryStatusVersion(),
        hasExactTombstone: (input) => this.hasExactTombstone(input),
        appendTombstone: (input) => this.appendTombstone(input),
        writeSealedMemory: (envelope, extras) => this.writeSealedMemory(envelope, extras),
      });
      return sideEffectsComplete || options.acceptExactReplay !== true;
    } catch (err) {
      log.error(`failed to supersede memory ${oldMemoryId}:`, err);
      return false;
    }
  }

  private get summariesDir(): string {
    return path.join(this.baseDir, "summaries");
  }

  async writeSummary(summary: MemorySummary): Promise<void> {
    await mkdir(this.summariesDir, { recursive: true });
    const filePath = path.join(this.summariesDir, `${summary.id}.json`);
    await this.writeStorageSecureFile(filePath, JSON.stringify(summary, null, 2));
    log.debug(`wrote summary ${summary.id}`);
  }

  async readSummaries(): Promise<MemorySummary[]> {
    try {
      const files = await readdir(this.summariesDir);
      const summaries: MemorySummary[] = [];

      for (const file of files) {
        if (isMacOsReplicationJunkBasename(file) || !file.endsWith(".json")) continue;
        const filePath = path.join(this.summariesDir, file);
        const raw = await this.readStorageSecureFile(filePath);
        summaries.push(JSON.parse(raw) as MemorySummary);
      }

      return summaries;
    } catch (err) {
      if (err instanceof SecureStoreLockedError) throw err;
      if (!isErrnoCode(err, "ENOENT")) throw err;
      return [];
    }
  }

  async archiveMemories(memoryIds: string[], summaryId: string): Promise<number> {
    const memories = await this.readAllMemories();
    const memoryMap = new Map(memories.map((m) => [m.frontmatter.id, m]));
    let archived = 0;

    for (const id of memoryIds) {
      const memory = memoryMap.get(id);
      if (!memory) continue;

      const now = new Date().toISOString();
      let currentBefore = memory;
      let updatedFm = memory.frontmatter;

      try {
        const written = await this.withTombstoneBlockedMemoryPathLock(memory.path, async (current) => {
          if (current?.frontmatter.id !== id) return false;
          currentBefore = current;
          const rowIds = this.currentHistoricalIds();
          updatedFm = entityRefs.canonicalizeEntityRefOption(
            { ...current.frontmatter, status: "archived", archivedAt: now, updated: now },
            rowIds
          );
          const fileContent = `${serializeFrontmatter(this.withOkfType(updatedFm))}\n\n${current.content}\n`;
          await this.writeTombstoneBlockedFrontmatter(current, fileContent, updatedFm);
          if (typeof current.frontmatter.entityRef === "string") {
            await this.entityRefRepair.repair(
              current.path,
              updatedFm,
              current.frontmatter.entityRef,
              rowIds,
              current.content,
              { onFailRestore: current }
            );
          }
          return true;
        });
        if (!written) continue;
        // Corpus bump before the lifecycle append (#1902). Epoch moves only if repair changed entityRef or origin.
        this.bumpMemoryCorpusVersion({ indexedText: entityMentionEpoch.neutral(currentBefore.frontmatter, updatedFm) ? false : undefined });
        await this.appendGeneratedMemoryLifecycleEventFailOpen("storage.archiveMemories", {
          memoryId: id,
          eventType: "archived",
          timestamp: updatedFm.archivedAt ?? updatedFm.updated,
          actor: "storage.archiveMemories",
          reasonCode: `summary:${summaryId}`,
          before: this.summarizeLifecycleState(currentBefore.frontmatter, currentBefore.path),
          after: this.summarizeLifecycleState(updatedFm, currentBefore.path),
          relatedMemoryIds: [summaryId],
        });
        archived++;
      } catch {
        // Ignore individual failures
      }
    }

    if (archived > 0) {
      this.bumpMemoryStatusVersion();
      log.debug(`archived ${archived} memories for summary ${summaryId}`);
    }
    return archived;
  }

  async saveTopics(topics: TopicScore[]): Promise<void> {
    const metaPath = path.join(this.stateDir, "topics.json");
    await mkdir(this.stateDir, { recursive: true });
    await this.writeStorageSecureFile(metaPath, JSON.stringify({ topics, updatedAt: new Date().toISOString() }, null, 2));
    log.debug(`saved ${topics.length} topic scores`);
  }

  async loadTopics(): Promise<{ topics: TopicScore[]; updatedAt: string | null }> {
    const metaPath = path.join(this.stateDir, "topics.json");
    try {
      const raw = await this.readStorageSecureFile(metaPath);
      return JSON.parse(raw) as { topics: TopicScore[]; updatedAt: string | null };
    } catch (err) {
      if (err instanceof SecureStoreLockedError) throw err;
      if (!isErrnoCode(err, "ENOENT")) throw err;
      return { topics: [], updatedAt: null };
    }
  }

  async addLinksToMemory(
    memoryId: string,
    links: MemoryLink[],
    lifecycle?: MemoryLifecycleEventWriteOptions
  ): Promise<boolean> {
    const memories = await this.readAllMemories();
    const memory = memories.find((m) => m.frontmatter.id === memoryId);
    if (!memory) return false;

    const existingLinks = memory.frontmatter.links ?? [];
    const mergedLinks = [...existingLinks];

    for (const link of links) {
      if (!mergedLinks.some((l) => l.targetId === link.targetId && l.linkType === link.linkType)) {
        mergedLinks.push(link);
      }
    }

    try {
      await this.writeMemoryFrontmatter(
        memory,
        {
          links: mergedLinks,
          updated: new Date().toISOString(),
        },
        lifecycle
      );
      log.debug(`added ${links.length} links to memory ${memoryId}`);
      return true;
    } catch (err) {
      log.error(`failed to add links to memory ${memoryId}:`, err);
      return false;
    }
  }

  private summarizeLifecycleState(frontmatter: MemoryFrontmatter, filePath: string): MemoryLifecycleStateSummary {
    return {
      category: frontmatter.category,
      path: filePath,
      status: frontmatter.status ?? "active",
      lifecycleState: frontmatter.lifecycleState,
    };
  }

  private frontmatterPatchEventType(before: MemoryFrontmatter, after: MemoryFrontmatter): MemoryLifecycleEventType {
    const beforeStatus = before.status ?? "active";
    const afterStatus = after.status ?? "active";
    if (beforeStatus !== "archived" && afterStatus === "archived") return "archived";
    if (beforeStatus !== "superseded" && afterStatus === "superseded") return "superseded";
    if (beforeStatus !== "rejected" && afterStatus === "rejected") return "rejected";
    if (beforeStatus !== "active" && afterStatus === "active") {
      return "restored";
    }
    return "updated";
  }

  private async appendGeneratedMemoryLifecycleEvent(
    input: Omit<MemoryLifecycleEvent, "eventId" | "ruleVersion">,
    ruleVersion = "memory-lifecycle-ledger.v1"
  ): Promise<void> {
    await this.appendMemoryLifecycleEvents([
      {
        ...input,
        eventId: this.generateId("mle"),
        ruleVersion,
      },
    ]);
  }

  private async appendGeneratedMemoryLifecycleEventFailOpen(
    operation: string,
    input: Omit<MemoryLifecycleEvent, "eventId" | "ruleVersion">,
    ruleVersion?: string
  ): Promise<void> {
    try {
      await this.appendGeneratedMemoryLifecycleEvent(input, ruleVersion);
    } catch (appendErr) {
      log.warn(`${operation} completed but failed to append lifecycle event: ${appendErr}`);
    }
  }
}

/**
 * Chunked trigger-drain for the extraction pipeline.
 *
 * Split out of `turn-ingestion.ts`: that file is at the structural ratchet's
 * line cap (issue #1995), and the drain is a self-contained unit — it only
 * needs the host's `runExtraction`, the buffer drop, the storage side-file
 * copy and the preemption hook.
 */

import { createHash } from "node:crypto";
import { isAbortError, preemptedExtractionError } from "../abort-error.js";
import { describeError } from "../buffer-turn-helpers.js";
import { chunkExtractionWindow, classifyDrainResult, mergeDrainResults } from "../extraction-window-drain.js";
import { log } from "../logger.js";
import type { BufferTurn } from "../types.js";
import type { ExtractionPreemptHandle } from "./extraction-queue-coordinator.js";
import type { ExtractionRunCoordinator, ExtractionRunResult } from "./extraction-run.js";

type RunOptions = Parameters<ExtractionRunCoordinator["runExtraction"]>[1];

/** The `runExtraction` options the drain forwards, with the ones it reads made required. */
export type DrainRunOptions = RunOptions & {
  bufferKey: string;
  clearBufferAfterExtraction: boolean;
  skipUserTurnThreshold: boolean;
  failOnExtractionFailure: boolean;
  forceExtractionAttempt: boolean;
};

/** What the drain needs from its host (structurally satisfied by `TurnIngestionDeps`). */
export interface ExtractionDrainDeps {
  config: {
    extractionMinUserTurns: number;
    extractionMinChars: number;
    extractionMaxTurnChars: number;
    extractionChunkDropAfterFailures: number;
  };
  extractionWindowBudgetChars?(): number;
  /**
   * Rendered-size oracle: the exact character count the extraction renderer
   * produces for these turns (renderExtractionConversation — the same
   * derivation extract() uses). When present, chunk sizing is render-aware:
   * chunks are guaranteed to fit the model input budget AFTER rendering, so
   * no turn can be silently truncated away by the model-input clamp.
   * Absent → raw-content sizing (prior behavior).
   */
  measureRenderedTurns?(turns: readonly BufferTurn[]): number;
  runExtraction(turns: BufferTurn[], options: RunOptions): Promise<ExtractionRunResult>;
  getStorage(): Promise<{
    saveDroppedExtractionChunk(bufferKey: string, reason: string, turns: readonly BufferTurn[]): Promise<string>;
  }>;
  buffer: {
    dropExtractionChunk(bufferKey: string, turns: readonly BufferTurn[], options?: { allowNonPrefix?: boolean }): Promise<number>;
  };
}

/** Identity of a chunk: its failure count must not follow a buffer key to different content. */
function chunkFingerprint(chunk: readonly BufferTurn[]): string {
  const hash = createHash("sha256");
  for (const turn of chunk) hash.update(`${turn.role}\u0000${turn.timestamp}\u0000${turn.content}\u0001`);
  return hash.digest("hex");
}

export class ExtractionDrain {
  /**
   * Consecutive failed attempts on the head chunk, per buffer key. In memory on
   * purpose (a restart re-counts from zero). Bound to the chunk's content: a
   * count recorded for one chunk never applies to a different one, so a force
   * flush that clears a failing chunk cannot make unrelated content inherit its
   * failures.
   */
  private readonly failures = new Map<string, { fingerprint: string; count: number }>();

  /**
   * Buffer key to the first turn of the chunk a qualified window stopped on.
   * The rest of such a window stays eligible on the next attempt even when it
   * is assistant-only or short: the window passed the thresholds as a whole,
   * and re-judging its tail would clear it unextracted. Cleared when the
   * window drains; one entry per key.
   */
  private readonly qualified = new Map<string, string>();

  /**
   * The claim drain runs with `dropFailedChunks: false`: a chunk that keeps
   * failing stays in its claim as durable retryable backlog — no side-file
   * recovery copy may move the original backlog aside.
   */
  private readonly dropFailedChunks: boolean;

  private readonly deps: ExtractionDrainDeps;

  constructor(deps: ExtractionDrainDeps, options?: { dropFailedChunks?: boolean }) {
    this.deps = deps;
    this.dropFailedChunks = options?.dropFailedChunks !== false;
  }

  /** Characters the coordinator would count for this window: user/assistant text, trimmed and capped per turn, context-only turns left out. */
  private windowChars(turns: readonly BufferTurn[]): number {
    let total = 0;
    for (const turn of turns) {
      if ((turn.role !== "user" && turn.role !== "assistant") || turn.extractionContextOnly === true) continue;
      total += turn.content.trim().slice(0, this.deps.config.extractionMaxTurnChars).length;
    }
    return total;
  }

  private failureCount(bufferKey: string, chunk: readonly BufferTurn[]): number {
    const entry = this.failures.get(bufferKey);
    return entry && entry.fingerprint === chunkFingerprint(chunk) ? entry.count : 0;
  }

  private setFailureCount(bufferKey: string, chunk: readonly BufferTurn[], count: number): void {
    if (count <= 0) this.failures.delete(bufferKey);
    else this.failures.set(bufferKey, { fingerprint: chunkFingerprint(chunk), count });
  }

  /**
   * Run `runExtraction` over the trigger-drain window. When the window outgrows
   * the extraction model's input budget (the stall that keeps a session's buffer
   * growing forever: every observe re-fires the trigger on a window that can
   * never extract), split it into budget-fitting chunks and drain them in
   * order; each successful run clears its chunk, so the buffer shrinks across
   * observes. A chunk that fails `extractionChunkDropAfterFailures` times in a
   * row is dropped (side-file copy first). Breaker/backoff retention results
   * stop the drain without counting as chunk failures.
   *
   * Explicit drains (replay/import `clearBufferAfterExtraction: false`, force
   * flush, fail-closed callers, accepted captures) and windows that fit the
   * budget (or hosts without the budget accessor) take the single-run path.
   *
   * `preemptable`: the run was queued as preemptable automatic work. Each chunk's
   * persist step ends the host's preemption registration, so the drain registers
   * it again before every later chunk; a fail-closed flush can then abort the
   * next chunk's model request instead of waiting behind the whole window.
   * `preemptHandle`: the queue task's own preemption slot (per task, so two
   * concurrent automatic extractions cannot clobber each other's registration).
   */
  async run(
    turns: BufferTurn[],
    runOptions: DrainRunOptions,
    preemptable = false,
    preemptHandle?: ExtractionPreemptHandle,
  ): Promise<ExtractionRunResult> {
    const budgetChars = this.deps.extractionWindowBudgetChars?.() ?? Number.POSITIVE_INFINITY;
    const plan = this.chunkPlan(turns, runOptions, budgetChars);
    // The tail of a window that already qualified goes through the chunk loop even when it now fits in one
    // chunk, so its failures still count toward the drop threshold.
    if (plan.singleRun) return await this.deps.runExtraction(turns, runOptions);
    // Eligibility (minimum user turns and characters) belongs to the whole
    // window: a window that never qualified keeps the single-run path, which
    // judges it exactly as before.
    if (!plan.resumed && this.windowBelowThreshold(turns, runOptions)) {
      return await this.deps.runExtraction(turns, runOptions);
    }
    return await this.runChunked(plan.chunks, runOptions, preemptable, preemptHandle);
  }

  /**
   * Chunking plan for one trigger-drain window. Accepted-capture groups
   * chunk too when their turns clear by IDENTITY (clearMatchingTurns — the
   * pinned-capture and claim-drain paths): a whole-window single run would
   * truncate at the model budget and ack turns the model never saw. Without
   * identity clears the single-run prefix clear stays (existing behavior).
   */
  private chunkPlan(
    turns: readonly BufferTurn[],
    runOptions: DrainRunOptions,
    budgetChars: number,
  ): { singleRun: boolean; chunks: BufferTurn[][]; resumed: boolean } {
    const chunks = this.chunkable(runOptions, turns, budgetChars)
      ? this.deps.measureRenderedTurns !== undefined
        ? this.chunkByRenderedSize(turns, budgetChars)
        : chunkExtractionWindow(turns, budgetChars)
      : [];
    const resumed = chunks.length > 0 && this.qualified.get(runOptions.bufferKey) === chunkFingerprint(chunks[0].slice(0, 1));
    return { singleRun: chunks.length <= 1 && !resumed, chunks, resumed };
  }

  /** Automatic chunking needs a clearable window, no fail-closed/forced
   *  caller, and a real budget to chunk against. */
  private chunkable(runOptions: DrainRunOptions, turns: readonly BufferTurn[], budgetChars: number): boolean {
    return (
      runOptions.clearBufferAfterExtraction &&
      !runOptions.forceExtractionAttempt &&
      !runOptions.failOnExtractionFailure &&
      this.identityCleared(runOptions, turns) &&
      Number.isFinite(budgetChars) &&
      budgetChars > 0
    );
  }

  /** A native group clears its turns by identity (a pinned capture can sit
   *  in front); a drop must find them the same way. */
  private identityCleared(runOptions: DrainRunOptions, turns: readonly BufferTurn[]): boolean {
    return runOptions.clearMatchingTurns === true || !turns.some((turn) => turn.acceptedCapture === true);
  }

  /** Eligibility (minimum user turns and characters) belongs to the whole
   *  window: a window that never qualified keeps the single-run path, which
   *  judges it exactly as before. */
  private windowBelowThreshold(turns: readonly BufferTurn[], runOptions: DrainRunOptions): boolean {
    const windowUserTurns = turns.filter((turn) => turn.role === "user").length;
    const belowChars = !runOptions.skipCharThreshold && this.windowChars(turns) < this.deps.config.extractionMinChars;
    return (!runOptions.skipUserTurnThreshold && windowUserTurns < this.deps.config.extractionMinUserTurns) || belowChars;
  }

  /** The window qualified as a whole; its chunks must not be re-judged one by
   *  one (an assistant-only or short chunk would be cleared unextracted). */
  private async runChunked(
    chunks: readonly BufferTurn[][],
    runOptions: DrainRunOptions,
    preemptable: boolean,
    preemptHandle?: ExtractionPreemptHandle,
  ): Promise<ExtractionRunResult> {
    const baseOptions = { ...runOptions, skipCharThreshold: true, skipUserTurnThreshold: true };
    const bufferKey = runOptions.bufferKey;
    // A native group clears its turns by identity (a pinned capture can sit in front); a drop must find them the same way.
    const byIdentity = runOptions.clearMatchingTurns === true;
    const dropAfter = this.deps.config.extractionChunkDropAfterFailures;
    let aggregate: ExtractionRunResult | null = null;
    for (const [position, chunk] of chunks.entries()) {
      this.qualified.set(bufferKey, chunkFingerprint(chunk.slice(0, 1)));
      const { options: chunkOptions, preempt } = this.chunkOptionsFor(chunks, position, baseOptions, runOptions, preemptable, preemptHandle);
      let failures = this.failureCount(bufferKey, chunk);
      let result: ExtractionRunResult;
      try {
        result = await this.deps.runExtraction(chunk, chunkOptions);
      } catch (err) {
        this.rethrowChunkAbort(err, preempt, runOptions.abortSignal?.aborted === true);
        // A successfully dropped thrown chunk does not end the drain: later
        // chunks still run this pass (live drop policy).
        aggregate = await this.settleThrownChunk(bufferKey, chunk, failures, dropAfter, err, byIdentity, aggregate);
        continue;
      }
      const settled = this.settleVerdict(bufferKey, chunk, result, aggregate);
      if (settled.action === "continue") {
        aggregate = settled.result;
        continue;
      }
      if (settled.action === "return") return settled.result;
      const failed = await this.settleFailedChunk({
        bufferKey,
        chunk,
        failures,
        dropAfter,
        result: settled.result,
        byIdentity,
        aggregate: settled.aggregate,
      });
      if (failed.action === "continue") {
        aggregate = failed.result;
        continue;
      }
      return failed.result;
    }
    this.qualified.delete(bufferKey);
    return aggregate ?? { status: "skipped", persistedCount: 0, durableOutputCount: 0 };
  }

  /** retentionWindow: the chunks processed so far. A chunk's deferred
   *  retention replaces theirs (retained turns do not pile up across chunks)
   *  and leaves the retained turns of chunks not yet processed in the
   *  buffer. The chunk-local abort leaves the outer signal untouched, so
   *  later chunks get their own preemption registration. */
  private chunkOptionsFor(
    chunks: readonly BufferTurn[][],
    position: number,
    baseOptions: DrainRunOptions,
    runOptions: DrainRunOptions,
    preemptable: boolean,
    preemptHandle?: ExtractionPreemptHandle,
  ): { options: DrainRunOptions; preempt?: AbortController } {
    let options: DrainRunOptions = { ...baseOptions, retentionWindow: chunks.slice(0, position + 1).flat() };
    let preempt: AbortController | undefined;
    if (preemptable && position > 0) {
      preempt = this.armChunkPreempt(preemptHandle);
      options = {
        ...options,
        abortSignal: runOptions.abortSignal ? AbortSignal.any([runOptions.abortSignal, preempt.signal]) : preempt.signal,
      };
    }
    return { options, preempt };
  }

  /** A chunk-local abort controller so a fail-closed flush can abort the
   *  next chunk instead of waiting behind the whole window. */
  private armChunkPreempt(preemptHandle?: ExtractionPreemptHandle): AbortController {
    const local = new AbortController();
    preemptHandle?.arm(() => local.abort(preemptedExtractionError()));
    return local;
  }

  /** An abort error is rethrown (the chunk-local abort leaves the outer
   *  signal untouched, so the host gets the preemption reason it looks for,
   *  as it does for the first chunk). */
  private rethrowChunkAbort(err: unknown, preempt: AbortController | undefined, outerAborted: boolean): void {
    if (!isAbortError(err)) return;
    throw preempt && preempt.signal.aborted && !outerAborted ? preempt.signal.reason : err;
  }

  /** A chunk whose extraction THREW: count the failure; below the drop
   *  threshold (or on a no-drop drain) rethrow so the window is retained;
   *  at the threshold a chunk that keeps throwing is dropped like one that
   *  keeps failing, so later chunks are not stuck behind it. */
  private async settleThrownChunk(
    bufferKey: string,
    chunk: readonly BufferTurn[],
    failures: number,
    dropAfter: number,
    err: unknown,
    byIdentity: boolean,
    aggregate: ExtractionRunResult | null,
  ): Promise<ExtractionRunResult> {
    failures += 1;
    if (failures < dropAfter || !this.dropFailedChunks) {
      this.setFailureCount(bufferKey, chunk, failures);
      throw err;
    }
    const thrown: ExtractionRunResult = {
      status: "skipped",
      reason: `thrown: ${describeError(err)}`,
      persistedCount: 0,
      durableOutputCount: 0,
    };
    if (!(await this.dropFailedChunk(bufferKey, chunk, dropAfter, thrown, byIdentity))) {
      this.setFailureCount(bufferKey, chunk, failures);
      throw err;
    }
    this.setFailureCount(bufferKey, chunk, 0);
    return mergeDrainResults(aggregate, thrown);
  }

  /** Map one chunk result to the drain-loop action: drained chunks continue
   *  to the next chunk; breaker/backoff retention and provider faults keep
   *  everything for retry without counting a chunk failure. */
  private settleVerdict(
    bufferKey: string,
    chunk: readonly BufferTurn[],
    result: ExtractionRunResult,
    aggregate: ExtractionRunResult | null,
  ): { action: "continue" | "return" | "failed"; result: ExtractionRunResult; aggregate: ExtractionRunResult | null } {
    const verdict = classifyDrainResult(result);
    if (verdict === "drained") {
      this.setFailureCount(bufferKey, chunk, 0);
      return { action: "continue", result: mergeDrainResults(aggregate, result), aggregate };
    }
    // Provider breaker/backoff retention: keep everything for retry.
    if (verdict === "deferred") return { action: "return", result: mergeDrainResults(aggregate, result), aggregate };
    // An outage or a bad key is not the chunk's fault: keep the chunk and do not count toward dropping it.
    if (result.failureClass === "provider_retryable" || result.failureClass === "auth_config") {
      return { action: "return", result: mergeDrainResults(aggregate, result), aggregate };
    }
    return { action: "failed", result, aggregate };
  }

  /** The failed-verdict tail: count the failure and either drop the chunk
   *  (live drains, recovery copy first) or keep it as durable retryable
   *  backlog (claim drains, dropFailedChunks: false — no-drop). No-drop
   *  drains retain the remaining window for the next trigger (existing
   *  behavior); the failure count still gates future drop decisions. */
  private async settleFailedChunk(args: {
    bufferKey: string;
    chunk: readonly BufferTurn[];
    failures: number;
    dropAfter: number;
    result: ExtractionRunResult;
    byIdentity: boolean;
    aggregate: ExtractionRunResult | null;
  }): Promise<{ action: "continue" | "return"; result: ExtractionRunResult }> {
    const failures = args.failures + 1;
    if (failures >= args.dropAfter && this.dropFailedChunks) {
      if (!(await this.dropFailedChunk(args.bufferKey, args.chunk, args.dropAfter, args.result, args.byIdentity))) {
        // No recovery copy: keep the only buffered copy and retry later.
        this.setFailureCount(args.bufferKey, args.chunk, failures);
        return { action: "return", result: mergeDrainResults(args.aggregate, args.result) };
      }
      this.setFailureCount(args.bufferKey, args.chunk, 0);
      return { action: "continue", result: mergeDrainResults(args.aggregate, args.result) };
    }
    this.setFailureCount(args.bufferKey, args.chunk, failures);
    return { action: "return", result: mergeDrainResults(args.aggregate, args.result) };
  }

  /**
   * Greedy chunking sized by the RENDERED conversation (the oracle the model
   * input clamp actually enforces), not raw content sums: a chunk grows while
   * its rendered size fits the budget, else it closes. A single oversized
   * turn still forms its own chunk (the renderer clamps per-turn content).
   * Render-exact, so no turn can silently fall past the model-input budget.
   */
  private chunkByRenderedSize(turns: readonly BufferTurn[], budgetChars: number): BufferTurn[][] {
    const measure = this.deps.measureRenderedTurns!;
    const chunks: BufferTurn[][] = [];
    let current: BufferTurn[] = [];
    for (const turn of turns) {
      if (current.length > 0 && measure([...current, turn]) > budgetChars) {
        chunks.push(current);
        current = [];
      }
      current.push(turn);
    }
    if (current.length > 0) chunks.push(current);
    return chunks;
  }

  /** Side-file copy first (content survives a failed drop), then remove the failing chunk from the buffer. Never throws:
   *  the drop must not fail the extraction task that already settled its result. */
  private async dropFailedChunk(
    bufferKey: string,
    chunk: readonly BufferTurn[],
    dropAfter: number,
    result: ExtractionRunResult,
    byIdentity: boolean,
  ): Promise<boolean> {
    const reason =
      `dropped after ${dropAfter} repeated extraction failures ` +
      `(last result: status=${result.status} reason=${result.reason ?? "n/a"})`;
    const copyPath = await this.saveRecoveryCopy(bufferKey, reason, chunk);
    if (copyPath === null) return false;
    log.warn(`buffer[${bufferKey}]: dropping ${chunk.length} turns — ${reason}; copy saved to ${copyPath}`);
    try {
      const dropped = await this.deps.buffer.dropExtractionChunk(bufferKey, chunk, { allowNonPrefix: byIdentity });
      if (dropped > 0) {
        log.warn(`buffer[${bufferKey}]: removed ${dropped} buffered turns — ${reason}`);
        return true;
      }
      // Nothing removed (the live turns changed): the chunk is still buffered, so this is not a drop.
      log.warn(`buffer[${bufferKey}]: dropped chunk no longer matches the buffer; keeping it and its failure count`);
    } catch (err) {
      log.warn(
        `buffer[${bufferKey}]: failed to remove dropped chunk from buffer (will retry next trigger): ${describeError(err)}`,
      );
    }
    return false;
  }

  /** The recovery side-file copy for a dropped chunk. null = the copy could
   *  not be written — the caller must keep the only buffered copy. */
  private async saveRecoveryCopy(
    bufferKey: string,
    reason: string,
    chunk: readonly BufferTurn[],
  ): Promise<string | null> {
    try {
      const storage = await this.deps.getStorage();
      return await storage.saveDroppedExtractionChunk(bufferKey, reason, chunk);
    } catch (err) {
      // Never destroy the only buffered copy without a recovery file.
      log.warn(
        `buffer[${bufferKey}]: could not save the dropped-chunk recovery copy; keeping the chunk in the buffer: ${describeError(err)}`,
      );
      return null;
    }
  }
}

export interface LoggerBackend {
  info(msg: string, ...args: unknown[]): void;
  warn(msg: string, ...args: unknown[]): void;
  error(msg: string, ...args: unknown[]): void;
  debug?(msg: string, ...args: unknown[]): void;
}

const NOOP_LOGGER: LoggerBackend = {
  info() {},
  warn() {},
  error() {},
  debug() {},
};

export interface LoggerOptions {
  /** Prefix each emitted line with an ISO 8601 timestamp. Defaults to true. */
  timestamps?: boolean;
  /** Clock source for the timestamp prefix; injectable for tests. */
  clock?: () => string;
}

let _backend: LoggerBackend = NOOP_LOGGER;
let _debug = false;
let _timestamps = true;
let _clock: () => string = () => new Date().toISOString();

// Coerce a boolean-like env string. Empty/whitespace-only and unrecognized
// values return undefined so callers fall through to the default (timestamps
// on) rather than silently disabling — an empty env var reads as "unset".
function coerceBool(value: string | undefined): boolean | undefined {
  if (value === undefined) return undefined;
  const s = value.trim().toLowerCase();
  if (s === "") return undefined;
  if (s === "0" || s === "false" || s === "no" || s === "off") return false;
  if (s === "1" || s === "true" || s === "yes" || s === "on") return true;
  return undefined;
}

// Late-bind console.* rather than capturing references at module import
// time. In production this is behaviour-identical to the pre-bound
// `.bind(console)` form — `console.info(msg, ...)` resolves `this` to
// `console` whether called directly or via an arrow wrapper — but it lets
// harnesses that swap console methods (e.g. runCli in @remnic/cli) route
// logger output through their capture sinks. With the old pre-bound form,
// any command that called initLogger() pinned the logger to the original
// console methods before the harness could swap them, so log.warn /
// log.info output escaped the capture buffer.
const CONSOLE_LOGGER: LoggerBackend = {
  info: (msg, ...args) => console.info(msg, ...args),
  warn: (msg, ...args) => console.warn(msg, ...args),
  error: (msg, ...args) => console.error(msg, ...args),
  debug: (msg, ...args) => console.debug(msg, ...args),
};

export function initLogger(backend?: LoggerBackend, debug?: boolean, options?: LoggerOptions): void {
  _backend = backend ?? CONSOLE_LOGGER;
  _debug = debug ?? false;
  // Precedence: explicit option > REMNIC_LOG_TIMESTAMPS env > default (on).
  _timestamps = options?.timestamps ?? coerceBool(process.env.REMNIC_LOG_TIMESTAMPS) ?? true;
  _clock = options?.clock ?? (() => new Date().toISOString());
}

// Whether a real backend has been installed via initLogger. Lets diagnostics
// that must not be swallowed (config misconfiguration warnings) fall back to
// console when a host-agnostic consumer uses core without calling initLogger.
export function isLoggerInitialized(): boolean {
  return _backend !== NOOP_LOGGER;
}

// Restore the pristine no-op backend (as at module load, before initLogger).
// Primarily a test seam for exercising the standalone/no-host path.
export function resetLogger(): void {
  _backend = NOOP_LOGGER;
  _debug = false;
  _timestamps = true;
  _clock = () => new Date().toISOString();
}

// Format one log line: "<iso> remnic: <msg>" when timestamps are enabled,
// otherwise the legacy "remnic: <msg>". Timestamp is per-call.
function fmt(msg: string, label = "remnic"): string {
  const ts = _timestamps ? `${_clock()} ` : "";
  return `${ts}${label}: ${msg}`;
}

export const log = {
  info(msg: string, ...args: unknown[]): void {
    _backend.info(fmt(msg), ...args);
  },
  warn(msg: string, ...args: unknown[]): void {
    _backend.warn(fmt(msg), ...args);
  },
  error(msg: string, err?: unknown): void {
    const detail = err instanceof Error ? err.message : err ? String(err) : "";
    _backend.error(fmt(`${msg}${detail ? ` — ${detail}` : ""}`));
  },
  debug(msg: string, ...args: unknown[]): void {
    if (!_debug) return;
    const fn = _backend.debug ?? _backend.info;
    fn(fmt(msg, "remnic [debug]"), ...args);
  },
};

/**
 * Shared abort-error helpers.
 *
 * Consolidates the `throwIfAborted` / `abortError` / `isAbortError`
 * patterns that were independently implemented across
 * `direct-answer-wiring.ts`, `harmonic-retrieval.ts`, and `qmd.ts`
 * (plus a private pair in `orchestrator.ts`).  A single helper
 * means future changes to the abort-error convention are applied
 * consistently across the codebase.
 *
 * The convention (matching Web / Node): throw a standard `Error`
 * with `name === "AbortError"`.  Callers dispatch on name rather
 * than a specific class so error propagation across async
 * boundaries continues to classify correctly.
 */

/**
 * Build an Error whose `name` is `"AbortError"`.  Uses
 * `Object.defineProperty` so the name is non-enumerable and
 * mirrors the shape of `DOMException("AbortError")` where that
 * is available.
 */
export function abortError(message: string): Error {
  const err = new Error(message);
  Object.defineProperty(err, "name", { value: "AbortError" });
  return err;
}

/** Return true iff `err` is an Error whose `name` is `"AbortError"`. */
export function isAbortError(err: unknown): boolean {
  return err instanceof Error && err.name === "AbortError";
}

const PREEMPTED_EXTRACTION = "extraction preempted for force-flush";

export function preemptedExtractionError(): Error {
  return abortError(PREEMPTED_EXTRACTION);
}

export function isPreemptedExtraction(err: Error): boolean {
  return err.name === "AbortError" && err.message === PREEMPTED_EXTRACTION;
}

/**
 * Throw an AbortError when the given signal has fired.  No-op
 * when the signal is absent or not yet aborted.  The default
 * message matches the prior in-module implementations.
 */
export function throwIfAborted(
  signal?: AbortSignal,
  message = "operation aborted",
): void {
  if (signal?.aborted) {
    throw abortError(message);
  }
}

export function raceAbort<T>(
  promise: Promise<T>,
  signal?: AbortSignal,
  message = "operation aborted",
): Promise<T> {
  if (!signal) return promise;
  if (signal.aborted) return Promise.reject(abortError(message));
  let onAbort: (() => void) | undefined;
  const aborted = new Promise<never>((_resolve, reject) => {
    onAbort = () => reject(abortError(message));
    signal.addEventListener("abort", onAbort, { once: true });
  });
  return Promise.race([promise, aborted]).finally(() => {
    if (onAbort) signal.removeEventListener("abort", onAbort);
  });
}

import type { SignalLevel, SignalScanResult } from "./types.js";

const BUILTIN_HIGH_PATTERNS: RegExp[] = [
  /\bactually,?\s+(i|my|we)\b/i,
  /\bno,?\s+(i|my|we|that'?s)\s+(not|wrong|incorrect)\b/i,
  /\bthat'?s\s+not\s+right\b/i,
  /\bwhy\s+did\s+you\s+say\s+that\b/i,
  /\bi\s+(?:always|never|prefer|hate|love|want|need)\b/i,
  /\bdon'?t\s+(?:use|do|call|say|make)\b/i,
  /\bplease\s+(?:always|never|remember|note)\b/i,
  /\bcorrection:?\b/i,
  /\bimportant:?\s+/i,
  /\bfyi:?\b/i,
  /\bfor\s+(?:the\s+)?record\b/i,
  /\bmy\s+(?:name|email|company|role|title|preference)\s+is\b/i,
  /\bi\s+(?:work|live|am)\s+(?:at|in|from|a)\b/i,
  /\bwe\s+(?:decided|agreed|chose|picked)\b/i,
  /\bthe\s+decision\s+(?:is|was)\b/i,
  /\bgoing\s+forward\b/i,
  /\bfrom\s+now\s+on\b/i,
];

const MEDIUM_PATTERNS: RegExp[] = [
  /\bi\s+(?:think|believe|feel)\b/i,
  /\busually\b/i,
  /\btypically\b/i,
  /\bi\s+(?:like|dislike)\b/i,
  /\bmy\s+(?:team|project|stack|setup)\b/i,
];

const DISAGREEMENT_PATTERNS: RegExp[] = [
  /\bthat'?s\s+not\s+right\b/i,
  /\bwhy\s+did\s+you\s+say\s+that\b/i,
  /\bthat'?s\s+wrong\b/i,
  /\bnot\s+correct\b/i,
];

export function isDisagreementPrompt(text: string): boolean {
  for (const rx of DISAGREEMENT_PATTERNS) {
    if (rx.test(text)) return true;
  }
  return false;
}

export function scanSignals(
  text: string,
  customPatterns: string[] = [],
): SignalScanResult {
  const matched: string[] = [];

  const customRegexes: RegExp[] = [];
  for (const pattern of customPatterns) {
    try {
      customRegexes.push(new RegExp(pattern, "i"));
    } catch {
      // Invalid custom patterns should not make the scan path fail closed.
    }
  }

  for (const rx of customRegexes) {
    if (rx.test(text)) {
      matched.push(`custom:${rx.source}`);
    }
  }

  for (const rx of BUILTIN_HIGH_PATTERNS) {
    if (rx.test(text)) {
      matched.push(`high:${rx.source}`);
    }
  }

  if (matched.length > 0) {
    return { level: "high", patterns: matched };
  }

  const mediumMatched: string[] = [];
  for (const rx of MEDIUM_PATTERNS) {
    if (rx.test(text)) {
      mediumMatched.push(`medium:${rx.source}`);
    }
  }

  if (mediumMatched.length >= 2) {
    return { level: "medium", patterns: mediumMatched };
  }
  if (mediumMatched.length === 1) {
    return { level: "low", patterns: mediumMatched };
  }

  return { level: "none", patterns: [] };
}

import type { BufferEntryState, BufferState, BufferSurpriseEvent, BufferTurn } from "./types.js";
import type { BufferSessionSaveOutcome } from "./storage/buffer-drain-claims.js";

/**
 * The buffer persistence surface SmartBuffer depends on.
 *
 * `saveBufferSession` / `deleteBufferSession` are the per-session incremental
 * writes (one file per session); when a storage backend does not provide
 * them, the buffer falls back to the whole-state `saveBuffer`. Both are
 * optional in the type so a storage double only has to implement what it
 * actually supports.
 */
export interface BufferStorage {
  loadBuffer(): Promise<BufferState>;
  saveBuffer(state: BufferState): Promise<void>;
  /** Reports "handed_over" when the session is claimed by `remnic buffer drain` and the entry moved into the claim instead of a session file. Legacy doubles may return void (treated as "saved"). */
  saveBufferSession?(key: string, entry: BufferEntryState): Promise<BufferSessionSaveOutcome | void>;
  deleteBufferSession?(key: string): Promise<void>;
  /** Sync claim check for the extraction gate; omitted when the backend has no drain-claim store. */
  isBufferSessionClaimed?(key: string): boolean;
  /** Optional surprise-telemetry sink; older storage and test doubles omit it. */
  appendBufferSurpriseEvents?(events: BufferSurpriseEvent[]): Promise<number>;
}

/** What one persist pass changed beyond plain writes. */
export interface BufferPersistOutcome {
  /** Sessions whose in-memory entry moved into a drain claim: the caller must evict them (a claimed session no longer lives in this process). */
  handedOver: string[];
  /** Per session, the turns a drain already extracted: the caller subtracts them from its in-memory copy. */
  drainedTurns: Map<string, BufferTurn[]>;
}

/**
 * Tracks which sessions' persisted files are stale and writes only those.
 *
 * Marks are cleared only after a durable write of that session. All calls
 * happen under SmartBuffer's serialized mutation chain: one writer.
 */
export class BufferSessionPersistence {
  private readonly dirty = new Set<string>();
  private readonly deleted = new Set<string>();

  markDirty(key: string): void {
    this.dirty.add(key);
    this.deleted.delete(key);
  }

  markDeleted(key: string): void {
    this.deleted.add(key);
    this.dirty.delete(key);
  }

  /** Eviction removed `key` from memory: its session file must go, any pending write is moot. */
  markEvicted(keys: readonly string[]): void {
    for (const key of keys) this.markDeleted(key);
  }

  hasPending(): boolean {
    return this.dirty.size > 0 || this.deleted.size > 0;
  }

  /**
   * Persist buffer state. On session-capable storage this writes ONLY the
   * sessions whose state changed since the last successful persist and
   * deletes files for evicted/reset sessions, so the observe path never
   * re-serializes other sessions' turns. On legacy storage it falls back to
   * the whole-state saveBuffer. Files are deleted before dirty writes: a
   * crash mid-persist can then only resurrect already-evicted data (the same
   * exposure as a whole-file rewrite), never drop sessions the state says
   * exist.
   */
  async persist(
    storage: BufferStorage,
    state: BufferState,
    peekEntry: (key: string) => BufferEntryState | undefined,
  ): Promise<BufferPersistOutcome> {
    const saveSession = storage.saveBufferSession?.bind(storage);
    const deleteSession = storage.deleteBufferSession?.bind(storage);
    if (!saveSession || !deleteSession) {
      await storage.saveBuffer(state);
      this.dirty.clear();
      this.deleted.clear();
      return { handedOver: [], drainedTurns: new Map() };
    }
    const handedOver: string[] = [];
    const drainedTurns = new Map<string, BufferTurn[]>();
    for (const key of [...this.deleted]) {
      await deleteSession(key);
      this.deleted.delete(key);
    }
    for (const key of [...this.dirty]) {
      const entry = peekEntry(key);
      if (!entry) {
        // A dirty key without state must not be written from a fabricated
        // empty entry: treat it as a deletion instead.
        this.markDeleted(key);
        continue;
      }
      const outcome = await saveSession(key, entry);
      this.dirty.delete(key);
      // "handed_over": the entry moved into a drain claim. Content is durable
      // in the claim, so this key's pending state is settled — the caller
      // evicts the in-memory entry on its side.
      if (outcome?.status === "handed_over") handedOver.push(key);
      // A drain tombstone: the turns it extracted must leave this process's
      // copy too, or the owner would extract them a second time.
      if (outcome?.drainedTurns && outcome.drainedTurns.length > 0) drainedTurns.set(key, outcome.drainedTurns);
    }
    return { handedOver, drainedTurns };
  }
}

import type { BufferEntryState } from "./types.js";

const EMPTY_ENTRY: BufferEntryState = { turns: [], lastExtractionAt: null, extractionCount: 0 };

export interface BufferEvictionHooks {
  /** Last activity time (ms) of an entry; older entries are evicted first. */
  activityAt(entry: BufferEntryState): number;
  /** Accepted captures exit via refusal/backpressure, never eviction (#3251). */
  holdsAcceptedCapture(entry: BufferEntryState | undefined): boolean;
}

/**
 * Pick the keys to evict so `entries` returns to `maxCount`: the oldest empty
 * sessions first; retained failed extractions (#1908) keep their turns, so if
 * empty entries alone cannot reach the cap the oldest NON-empty sessions go
 * too rather than growing unboundedly. "default", the retained keys and
 * entries holding an accepted capture are never chosen.
 */
export function selectEvictedBufferKeys(
  entries: Readonly<Record<string, BufferEntryState>>,
  retainKeys: readonly string[],
  maxCount: number,
  hooks: BufferEvictionHooks,
): string[] {
  const keys = Object.keys(entries);
  if (keys.length <= maxCount) return [];

  const insertionOrder = new Map(keys.map((key, index) => [key, index]));
  const byOldestActivity = (left: string, right: string): number => {
    const leftAt = hooks.activityAt(entries[left] ?? EMPTY_ENTRY);
    const rightAt = hooks.activityAt(entries[right] ?? EMPTY_ENTRY);
    if (leftAt !== rightAt) return leftAt - rightAt;
    return (insertionOrder.get(left) ?? 0) - (insertionOrder.get(right) ?? 0);
  };
  const candidates = keys.filter(
    (key) => key !== "default" && !retainKeys.includes(key) && !hooks.holdsAcceptedCapture(entries[key]),
  );
  const emptyRemovable = candidates
    .filter((key) => (entries[key]?.turns.length ?? 0) === 0)
    .sort(byOldestActivity);

  const removableCount = Math.max(0, keys.length - maxCount);
  const evicted = emptyRemovable.slice(0, removableCount);
  if (evicted.length < removableCount) {
    const nonEmptyRemovable = candidates
      .filter((key) => (entries[key]?.turns.length ?? 0) > 0)
      .sort(byOldestActivity);
    return evicted.concat(nonEmptyRemovable.slice(0, removableCount - evicted.length));
  }
  return evicted;
}

/**
 * CapabilitySet — recall-operation feature gates resolved once, then threaded.
 *
 * Issue #1523 (Phase 1 of epic #1520). Root cause this addresses: 161+
 * scattered `config.<flag>Enabled` reads mean each gate is re-derived at every
 * call site, and reviews keep finding parallel code paths where one branch
 * checks a gate the other forgot (CLAUDE.md rule 39 — the "gate divergence"
 * defect class). The fix is to resolve a frozen capability projection ONCE at
 * the top of the recall operation and pass it down explicitly.
 *
 * Scope of THIS module (first migration PR): only the recall-operation-scoped
 * flags below. Flags that are also read in graph construction, writes, CLI, or
 * the summarizer are deliberately deferred to a follow-up so we never leave a
 * single flag half-migrated (some sites on `caps.`, some on `config.`).
 *
 * Field naming: each field is the config flag name with the trailing `Enabled`
 * removed (`recallMmrEnabled` → `recallMmr`).
 *
 * This is plumbing, not a feature — there is deliberately NO `enabled` gate for
 * the CapabilitySet itself (rule 30 governs behavior changes; resolving and
 * threading a capability projection must stay behavior-preserving).
 *
 * Flag-retirement audit (#1780, 2026-07-08): all projected fields verified for
 * live consumers; dead projections removed.
 */

import type { PluginConfig } from "./types.js";
import type { InjectionScreenProfile } from "./security/injection-screen.js";

/**
 * Frozen projection of recall-operation feature gates.
 *
 * Every field is `readonly boolean`. The composition that maps a config flag to
 * a capability (including default-when-undefined semantics for optional flags)
 * lives ONLY in {@link resolveCapabilities} — call sites must read the
 * capability, never re-derive it from raw config.
 */
export interface CapabilitySet {
  /** `rerankCacheEnabled` — cache reranker scores across recall passes. */
  readonly rerankCache: boolean;
  /** `recallDirectAnswerEnabled` — observation-mode direct-answer tier. */
  readonly recallDirectAnswer: boolean;
  /** `recallMemoryWorthFilterEnabled` — Memory-Worth score reweighting. */
  readonly recallMemoryWorthFilter: boolean;
  /** `trustScoreEnabled` — unified TrustScore recall stage (issue #1577). */
  readonly recallTrustScore: boolean;
  /** `recallMmrEnabled` — maximal-marginal-relevance diversification. */
  readonly recallMmr: boolean;
  /** `recallReasoningTraceBoostEnabled` — boost reasoning-trace memories. */
  readonly recallReasoningTraceBoost: boolean;
  /** `recallPlannerLlmEnabled` — LLM-backed recall-mode planner. */
  readonly recallPlannerLlm: boolean;
  /** `recallPlannerEnabled` — recall-mode planner (heuristic + optional LLM). */
  readonly recallPlanner: boolean;
  /** `recallConfidenceGateEnabled` — Synapse-style confidence gate. */
  readonly recallConfidenceGate: boolean;
  /** `graphRecallEnabled` — graph-mode recall tier (gates planner graph mode). */
  readonly graphRecall: boolean;
  /** `graphAssistInFullModeEnabled` — graph-assist overlay in full mode. */
  readonly graphAssistInFullMode: boolean;
  /** `graphExpandedIntentEnabled` — promote broad-intent asks to graph mode. */
  readonly graphExpandedIntent: boolean;
  // --- Issue #1566 Cluster C: mixed-operation flags (recall + summarizer/CLI/writes) ---
  /** `rerankEnabled` — optional LLM reranking of recall candidates. */
  readonly rerank: boolean;
  /** `harmonicRetrievalEnabled` — abstraction-node harmonic retrieval tier. */
  readonly harmonicRetrieval: boolean;
  /** `parallelRetrievalEnabled` — three-agent parallel retrieval (DirectFact + Contextual + Temporal). */
  readonly parallelRetrieval: boolean;
}

/**
 * Resolve the recall-operation {@link CapabilitySet} from parsed config.
 *
 * Call this ONCE per recall operation (at the `recall()` / `recallInternal`
 * entry) and thread the result down. Composition lives here and only here.
 *
 * Session toggles are intentionally not a parameter yet: `session-toggles.ts`
 * is agent-scoped (per session/agent enable-disable of the whole plugin), not
 * flag-scoped — none of the flags projected here have a per-session override,
 * so there is nothing for a toggle argument to compose at this layer.
 */
export function resolveCapabilities(config: PluginConfig): CapabilitySet {
  return Object.freeze({
    rerankCache: config.rerankCacheEnabled,
    recallDirectAnswer: config.recallDirectAnswerEnabled,
    recallMemoryWorthFilter: config.recallMemoryWorthFilterEnabled,
    // Issue #1577: TrustScore subsumes the Memory Worth multiplier when on;
    // the orchestrator runs exactly one of the two (mutual exclusion, rule 39).
    recallTrustScore: config.trustScoreEnabled === true,
    recallMmr: config.recallMmrEnabled,
    recallReasoningTraceBoost: config.recallReasoningTraceBoostEnabled,
    recallPlannerLlm: config.recallPlannerLlmEnabled,
    recallPlanner: config.recallPlannerEnabled,
    recallConfidenceGate: config.recallConfidenceGateEnabled,
    graphRecall: config.graphRecallEnabled,
    // Optional flags: preserve the exact default-when-undefined semantics the
    // migrated call sites used (`!== false` = default-on, `=== true` = default-off).
    graphAssistInFullMode: config.graphAssistInFullModeEnabled !== false,
    graphExpandedIntent: config.graphExpandedIntentEnabled === true,
    // Issue #1566 Cluster C: mixed-operation flags resolved once per recall op.
    rerank: config.rerankEnabled,
    harmonicRetrieval: config.harmonicRetrievalEnabled,
    parallelRetrieval: config.parallelRetrievalEnabled,
  });
}

// ---------------------------------------------------------------------------
// Graph-construction capability set (issue #1566 Cluster A).
//
// The recall CapabilitySet above covers flags whose EVERY read site lives on
// the recall call chain. The five flags below are read on graph-construction,
// write/extraction, AND recall paths — so they cannot join the recall set
// without leaving some sites on `caps.` and others on `config.` (the exact
// divergence #1523 forbade). They get their own projection, resolved at graph
// build/write entry (and alongside `caps` when recall reads them).
// ---------------------------------------------------------------------------

/**
 * Frozen projection of graph-construction feature gates.
 *
 * Every field is `readonly boolean`. Composition (including default-when-
 * undefined semantics for the optional `graphWriteSessionAdjacencyEnabled`)
 * lives ONLY in {@link resolveGraphConstructionCapabilities}.
 */
export interface GraphConstructionCapabilitySet {
  /** `entityGraphEnabled` — maintain entity co-reference graph edges. */
  readonly entityGraph: boolean;
  /** `timeGraphEnabled` — maintain thread-adjacency graph edges. */
  readonly timeGraph: boolean;
  /** `causalGraphEnabled` — maintain causal-language graph edges. */
  readonly causalGraph: boolean;
  /** `multiGraphMemoryEnabled` — master switch for multi-graph writes/traversal. */
  readonly multiGraphMemory: boolean;
  /** `graphWriteSessionAdjacencyEnabled` — session-adjacency fallback for time edges (default-on). */
  readonly graphWriteSessionAdjacency: boolean;
}

/**
 * Resolve the {@link GraphConstructionCapabilitySet} from parsed config.
 *
 * Call this ONCE at graph build/write entry (extraction, recall graph
 * expansion, graph-health/repair) and thread the result down — exactly the
 * pattern {@link resolveCapabilities} established for recall.
 */
export type GraphConstructionConfigProjection = Pick<
  PluginConfig,
  | "entityGraphEnabled"
  | "timeGraphEnabled"
  | "causalGraphEnabled"
  | "multiGraphMemoryEnabled"
  | "graphWriteSessionAdjacencyEnabled"
>;

export function resolveGraphConstructionCapabilities(
  config: GraphConstructionConfigProjection,
): GraphConstructionCapabilitySet {
  return Object.freeze({
    entityGraph: config.entityGraphEnabled,
    timeGraph: config.timeGraphEnabled,
    causalGraph: config.causalGraphEnabled,
    multiGraphMemory: config.multiGraphMemoryEnabled,
    // Optional flag: preserve the exact default-when-undefined semantics the
    // migrated call site used (`!== false` = default-on).
    graphWriteSessionAdjacency: config.graphWriteSessionAdjacencyEnabled !== false,
  });
}

// ---------------------------------------------------------------------------
// Access-setup capability set (issue #1566 Cluster B).
//
// These two flags gate cross-namespace recall budgeting and anomaly-detection
// auditing. Resolved once at access-service handler entry (and the operator
// doctor check) rather than re-derived from raw config at each site.
// ---------------------------------------------------------------------------

/**
 * Frozen projection of access-setup feature gates (issue #1566 Cluster B).
 *
 * Every field is `readonly boolean`. Composition (including the default-off
 * semantics for the optional `recallAuditAnomalyDetectionEnabled`) lives ONLY
 * in {@link resolveAccessSetupCapabilities}.
 */
export interface AccessSetupCapabilitySet {
  /** `recallCrossNamespaceBudgetEnabled` — rolling cross-namespace recall budget. */
  readonly recallCrossNamespaceBudget: boolean;
  /** `recallAuditAnomalyDetectionEnabled` — access-audit anomaly detection (default-off). */
  readonly recallAuditAnomalyDetection: boolean;
  readonly recallSingleFlight: boolean;
}

/** Resolve the {@link AccessSetupCapabilitySet} from parsed config. Call ONCE at
 *  access-service handler entry and thread the result down. */
export type AccessSetupConfigProjection = Pick<
  PluginConfig,
  "recallCrossNamespaceBudgetEnabled" | "recallAuditAnomalyDetectionEnabled" | "recallSingleFlightEnabled"
>;

export function resolveAccessSetupCapabilities(
  config: AccessSetupConfigProjection,
): AccessSetupCapabilitySet {
  return Object.freeze({
    recallCrossNamespaceBudget: config.recallCrossNamespaceBudgetEnabled,
    // Optional/default-off flag: preserve `=== true` semantics.
    recallAuditAnomalyDetection: config.recallAuditAnomalyDetectionEnabled === true,
    recallSingleFlight: config.recallSingleFlightEnabled === true,
  });
}

// ---------------------------------------------------------------------------
// Memory-lifecycle capability set (issue #1523 batch 3).
//
// The flags below gate memory WRITE/EXTRACTION (extraction judge, scope
// classification, dedupe, telemetry prefilter), temporal supersession of
// stored facts, and the lifecycle policy pass (promotion / decay / stale
// filtering). They are read on the persistExtraction write path, the recall
// candidate-filter path, and the maintenance / lifecycle-pass path — so, like
// the graph-construction set above, they get their own projection resolved
// ONCE at each operation entry that reads them (never re-derived from raw
// config mid-operation — the gate-divergence defect class #1523 targets).
//
// Every field projects from an already-resolved PluginConfig boolean (defaults
// are applied at the config-parse boundary, rule 36), so the resolver is a
// pure projection — no `!== false` / `=== true` re-coercion here.
// ---------------------------------------------------------------------------

/**
 * Frozen projection of memory-lifecycle feature gates (issue #1523 batch 3).
 *
 * Resolved once per write / recall-filter / maintenance operation and threaded
 * down. Composition lives ONLY in {@link resolveMemoryLifecycleCapabilities}.
 */
export interface MemoryLifecycleCapabilitySet {
  /** `temporalSupersessionEnabled` — supersede stale structured facts on write, filter on recall. */
  readonly temporalSupersession: boolean;
  /** `temporalMemoryTreeEnabled` — temporal-memory-tree build + recall tier. */
  readonly temporalMemoryTree: boolean;
  /** `lifecyclePolicyEnabled` — lifecycle promotion / decay metadata pass. */
  readonly lifecyclePolicy: boolean;
  /** `lifecycleFilterStaleEnabled` — filter stale-lifecycle memories from recall. */
  readonly lifecycleFilterStale: boolean;
  /** `lifecycleMetricsEnabled` — emit lifecycle-pass metrics. */
  readonly lifecycleMetrics: boolean;
  /** `extractionScopeClassificationEnabled` — LLM classifies each fact's scope. */
  readonly extractionScopeClassification: boolean;
  /** `extractionJudgeEnabled` — LLM-as-judge fact-worthiness gate. */
  readonly extractionJudge: boolean;
  /** `extractionDedupeEnabled` — dedupe against recent extractions. */
  readonly extractionDedupe: boolean;
  /** `extractionTelemetryPrefilterEnabled` — skip mechanical-telemetry transcripts. */
  readonly extractionTelemetryPrefilter: boolean;
  /** `extractionJudgeTelemetryEnabled` — collect judge verdict telemetry. */
  readonly extractionJudgeTelemetry: boolean;
  /** `embeddingFallbackEnabled` — semantic-dedup / archive-search embedding fallback. */
  readonly embeddingFallback: boolean;
  /** `extractionRetryEnabled` — per-fingerprint backoff + provider circuit breaker on the extraction retry path. */
  readonly extractionRetry: boolean;  /** `projectionRebuildEnabled` — scheduled memory-projection rebuild (#2119). */
  readonly projectionRebuild: boolean;
}

/**
 * Config projection consumed by {@link resolveMemoryLifecycleCapabilities}.
 */
export type MemoryLifecycleConfigProjection = Pick<
  PluginConfig,
  | "temporalSupersessionEnabled"
  | "temporalMemoryTreeEnabled"
  | "lifecyclePolicyEnabled"
  | "lifecycleFilterStaleEnabled"
  | "lifecycleMetricsEnabled"
  | "extractionScopeClassificationEnabled"
  | "extractionJudgeEnabled"
  | "extractionDedupeEnabled"
  | "extractionTelemetryPrefilterEnabled"
  | "extractionJudgeTelemetryEnabled"
  | "embeddingFallbackEnabled"
  | "extractionRetryEnabled"
  | "projectionRebuildEnabled"
>;

/**
 * Resolve the {@link MemoryLifecycleCapabilitySet} from parsed config.
 *
 * Call this ONCE per write / recall-filter / maintenance operation entry and
 * thread the result down — exactly the pattern {@link resolveCapabilities}
 * established for recall.
 */
export function resolveMemoryLifecycleCapabilities(
  config: MemoryLifecycleConfigProjection,
): MemoryLifecycleCapabilitySet {
  return Object.freeze({
    temporalSupersession: config.temporalSupersessionEnabled,
    temporalMemoryTree: config.temporalMemoryTreeEnabled,
    lifecyclePolicy: config.lifecyclePolicyEnabled,
    lifecycleFilterStale: config.lifecycleFilterStaleEnabled,
    lifecycleMetrics: config.lifecycleMetricsEnabled,
    extractionScopeClassification: config.extractionScopeClassificationEnabled,
    extractionJudge: config.extractionJudgeEnabled,
    extractionDedupe: config.extractionDedupeEnabled,
    extractionTelemetryPrefilter: config.extractionTelemetryPrefilterEnabled,
    extractionJudgeTelemetry: config.extractionJudgeTelemetryEnabled,
    embeddingFallback: config.embeddingFallbackEnabled,
    extractionRetry: config.extractionRetryEnabled,
    projectionRebuild: config.projectionRebuildEnabled,
  });
}

