/**
 * Narrow storage seam satisfied by `StorageManager`. Promotion reuses the
 * existing in-place `pending_review -> active` machinery rather than adding
 * a parallel write path.
 */
export interface SeedGraduationStorage {
  promoteWearableMemory(
    id: string,
    attributeUpdates: Record<string, string>,
    confidence?: number,
  ): Promise<boolean>;
}

export interface SeedGraduationPassInput {
  /** Full memory corpus for the namespace being swept (same input the lifecycle policy pass takes). */
  memories: readonly MemoryFile[];
  storage: SeedGraduationStorage;
  config?: SeedGraduationConfig;
  recalledBySession?: SeedRecallEchoLookup;
}

export interface SeedGraduationPassSummary {
  evaluated: number;
  promoted: number;
  held: number;
  /** Held specifically because a contradiction was observed in the window. */
  contradictionHeld: number;
  echoSuppressed: number;
  disabled: boolean;
}

/** Audit attribute stamped on every graduated row, naming the evidence. */
function graduationAttributes(evaluation: SeedGraduationEvaluation): Record<string, string> {
  const ids = evaluation.corroborating
    .map((entry) => entry.memoryId)
    .join(",")
    .slice(0, STRUCTURED_ATTRIBUTE_LIMITS.maxValueLength);
  return {
    graduatedBy: "independent-corroboration",
    corroborationCount: String(evaluation.corroborationCount),
    corroboratingMemoryIds: ids,
  };
}

/**
 * Sweep every `pending_review` seed and graduate the corroborated ones.
 * Zero behavior while disabled (default) — review-mode promotion is
 * untouched until an operator opts in.
 */
export async function runSeedGraduationPass(
  input: SeedGraduationPassInput,
): Promise<SeedGraduationPassSummary> {
  const config = input.config ?? SEED_GRADUATION_DEFAULTS;
  if (!config.enabled) {
    return { evaluated: 0, promoted: 0, held: 0, contradictionHeld: 0, echoSuppressed: 0, disabled: true };
  }
  const corpus = excludeSupportPassportPrivateMemories(input.memories);
  const evidencePool = corpus.filter((memory) => isGraduationEvidence(memory));

  let promoted = 0;
  let held = 0;
  let contradictionHeld = 0;
  let echoSuppressed = 0;
  let evaluated = 0;

  for (const seed of corpus) {
    if (seed.frontmatter.status !== "pending_review") continue;
    if (seed.frontmatter.verificationState === "disputed") continue;
    // Tombstone-blocked rows need revokeTombstone first; the promotion
    // method refuses them anyway, so skip before evaluating.
    if (seed.frontmatter.blockedBy !== undefined) continue;
    evaluated += 1;

    const evaluation = evaluateSeedGraduation(seed, evidencePool, {
      config,
      recalledBySession: input.recalledBySession,
    });
    echoSuppressed += evaluation.echoSuppressedCount;

    if (evaluation.decision === "hold") {
      held += 1;
      if (evaluation.contradicting.length > 0) contradictionHeld += 1;
      continue;
    }
    // A concurrent review resolution wins: promoteWearableMemory returns
    // false when the row is no longer pending_review.
    const wrote = await input.storage.promoteWearableMemory(
      seed.frontmatter.id,
      graduationAttributes(evaluation),
    );
    if (wrote) promoted += 1;
    else held += 1;
  }

  return { evaluated, promoted, held, contradictionHeld, echoSuppressed, disabled: false };
}

import { coerceBool, coerceNumber } from "./connectors/coerce.js";

/** Configuration for the nightly contradiction-scan cron (issue #520). */
export interface ContradictionScanConfig {
  /** Master switch for the contradiction scan cron. Default true. */
  enabled: boolean;
  /** Embedding cosine similarity floor for candidate pair generation. Default 0.82. */
  similarityFloor: number;
  /** Minimum topic-token Jaccard overlap for unstructured pairs. Default 0.4. */
  topicOverlapFloor: number;
  /** Cap on candidate pairs evaluated per cron run. Default 500. */
  maxPairsPerRun: number;
  /** Cooldown in days before re-evaluating a pair judged independent/both-valid. Default 14. */
  cooldownDays: number;
  /** When true, pairs judged "duplicates" are auto-flagged for dedup (still need user approval). Default false. */
  autoMergeDuplicates: boolean;
}

export interface ContradictionLocalizationConfig {
  /** Enable the entity/category anchor pass before QMD search. */
  anchorEnabled: boolean;
  /** Maximum anchor candidates. Zero disables the anchor pass. */
  anchorCandidates: number;
  /** Maximum QMD search candidates. Zero disables text search. */
  searchCandidates: number;
  /** Maximum merged candidates passed to contradiction verification. */
  maxCandidates: number;
}

export function parseContradictionScanConfig(raw: unknown): ContradictionScanConfig {
  if (!raw || typeof raw !== "object") {
    return {
      enabled: false,
      similarityFloor: 0.82,
      topicOverlapFloor: 0.4,
      maxPairsPerRun: 500,
      cooldownDays: 14,
      autoMergeDuplicates: false,
    };
  }
  const src = raw as Record<string, unknown>;
  const simFloor = coerceNumber(src.similarityFloor) ?? 0.82;
  const topicFloor = coerceNumber(src.topicOverlapFloor) ?? 0.4;
  const maxPairs = coerceNumber(src.maxPairsPerRun) ?? 500;
  const cooldown = coerceNumber(src.cooldownDays) ?? 14;
  return {
    enabled: coerceBool(src.enabled) === true,
    similarityFloor: Math.min(1, Math.max(0, simFloor)),
    topicOverlapFloor: Math.min(1, Math.max(0, topicFloor)),
    maxPairsPerRun: Math.max(1, maxPairs),
    cooldownDays: Math.max(0, cooldown),
    autoMergeDuplicates: coerceBool(src.autoMergeDuplicates) === true,
  };
}

export function parseContradictionLocalizationConfig(raw: unknown): ContradictionLocalizationConfig {
  const defaults: ContradictionLocalizationConfig = {
    anchorEnabled: true,
    anchorCandidates: 5,
    searchCandidates: 5,
    maxCandidates: 8,
  };
  if (raw === undefined || raw === null) return defaults;
  if (typeof raw !== "object" || Array.isArray(raw)) {
    throw new Error("contradictionLocalization must be an object");
  }
  const src = raw as Record<string, unknown>;
  const rawEnabled = src.anchorEnabled;
  const anchorEnabled = rawEnabled === undefined || rawEnabled === null ? true : coerceBool(rawEnabled);
  if (anchorEnabled === undefined) {
    throw new Error("contradictionLocalization.anchorEnabled must be a boolean-like value");
  }

  const parseCap = (
    key: keyof Pick<ContradictionLocalizationConfig, "anchorCandidates" | "searchCandidates" | "maxCandidates">,
  ): number => {
    const rawValue = src[key];
    if (rawValue === undefined) return defaults[key];
    const parsed = coerceNumber(rawValue);
    if (parsed === undefined || !Number.isInteger(parsed) || parsed < 0) {
      throw new Error(`contradictionLocalization.${key} must be an integer >= 0`);
    }
    return parsed;
  };

  return {
    anchorEnabled,
    anchorCandidates: parseCap("anchorCandidates"),
    searchCandidates: parseCap("searchCandidates"),
    maxCandidates: parseCap("maxCandidates"),
  };
}

import { coerceBool, coerceNumber } from "./connectors/coerce.js";

export interface GraphPathScoringConfig {
  enabled: boolean;
  invalidNodePenalty: number;
  includePathInProvenance: boolean;
}

function resolveBooleanConfig(value: unknown, defaultValue: boolean, keyName: string): boolean {
  if (value === undefined || value === null) return defaultValue;
  const coerced = coerceBool(value);
  if (coerced === undefined) {
    throw new Error(
      `${keyName} must be a boolean-like value (true/false/1/0/yes/no/on/off); got ${JSON.stringify(value)}`,
    );
  }
  return coerced;
}

export function parseGraphPathScoringConfig(
  cfg: Record<string, unknown> | undefined,
): GraphPathScoringConfig {
  if (cfg !== undefined && (typeof cfg !== "object" || Array.isArray(cfg))) {
    throw new Error("graphPathScoring must be a plain object");
  }
  const block = cfg ?? {};
  const invalidNodePenalty = coerceNumber(block.invalidNodePenalty);
  if (
    invalidNodePenalty === undefined ||
    !Number.isFinite(invalidNodePenalty) ||
    invalidNodePenalty <= 0 ||
    invalidNodePenalty > 1
  ) {
    if (block.invalidNodePenalty !== undefined && block.invalidNodePenalty !== null) {
      throw new Error(
        `graphPathScoring.invalidNodePenalty must be a number in (0,1]; got ${JSON.stringify(block.invalidNodePenalty)}`,
      );
    }
  }
  return {
    enabled: resolveBooleanConfig(block.enabled, false, "graphPathScoring.enabled"),
    invalidNodePenalty:
      invalidNodePenalty !== undefined &&
      Number.isFinite(invalidNodePenalty) &&
      invalidNodePenalty > 0 &&
      invalidNodePenalty <= 1
        ? invalidNodePenalty
        : 0.2,
    includePathInProvenance: resolveBooleanConfig(
      block.includePathInProvenance,
      true,
      "graphPathScoring.includePathInProvenance",
    ),
  };
}

import { coerceBooleanLike, coerceNumber } from "../connectors/coerce.js";
import { connectorMatchesScope, normalizeConnectorScope } from "./connector-scope.js";

/**
 * Embedding-density novelty gate (issue #1953, SAGE).
 *
 * score = 1 - mean(cosine of k nearest). Higher score = more novel.
 *   score >= noveltyAddThreshold  → add (skip semantic/LLM dedup)
 *   score <= noveltyNoopThreshold → noop (drop; do not touch contentHashIndex)
 *   else                          → uncertain (fall through to semantic dedup)
 *
 * Defaults keep a wide UNCERTAIN band. noveltyGateEnabled defaults false.
 * Backend failure is not handled here — callers treat a thrown lookup as uncertain.
 */
export const DEFAULT_NOVELTY_ADD_THRESHOLD = 0.55;
export const DEFAULT_NOVELTY_NOOP_THRESHOLD = 0.15;
export const DEFAULT_NOVELTY_K = 5;

export interface NoveltyNeighbor {
  id: string;
  embedding: number[];
}

export interface NoveltyDecision {
  score: number;
  decision: "add" | "noop" | "uncertain";
  neighborId?: string;
}

export interface NoveltyThresholds {
  addThreshold?: number;
  noopThreshold?: number;
  k?: number;
}

export interface WritePathDedupConfig {
  semanticDedupEnabled: boolean;
  semanticDedupThreshold: number;
  semanticDedupCandidates: number;
  noveltyGateEnabled: boolean;
  noveltyAddThreshold: number;
  noveltyNoopThreshold: number;
}

function clamp01(value: number | undefined, fallback: number): number {
  return value !== undefined && Number.isFinite(value) ? Math.min(1, Math.max(0, value)) : fallback;
}

function cosine(a: number[], b: number[]): number {
  if (a.length === 0 || a.length !== b.length) return 0;
  let dot = 0;
  let magA = 0;
  let magB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    magA += a[i] * a[i];
    magB += b[i] * b[i];
  }
  const denom = Math.sqrt(magA) * Math.sqrt(magB);
  if (denom === 0) return 0;
  const raw = dot / denom;
  if (!Number.isFinite(raw)) return 0;
  if (raw < 0) return 0;
  if (raw > 1) return 1;
  return raw;
}

/** The semantic-dedup threshold exactly as `parseWritePathDedupConfig` resolves it. */
export function semanticDedupThresholdFrom(cfg: Record<string, unknown>): number {
  return clamp01(coerceNumber(cfg.semanticDedupThreshold, "semanticDedupThreshold"), 0.92);
}

export function parseWritePathDedupConfig(cfg: Record<string, unknown>): WritePathDedupConfig {
  const rawCandidates = coerceNumber(cfg.semanticDedupCandidates, "semanticDedupCandidates");
  let semanticDedupCandidates = 5;
  if (rawCandidates !== undefined && rawCandidates >= 0) {
    const n = Math.floor(rawCandidates);
    semanticDedupCandidates = rawCandidates > 0 && n === 0 ? 1 : n;
  }
  return {
    semanticDedupEnabled: coerceBooleanLike(cfg.semanticDedupEnabled, "semanticDedupEnabled") !== false,
    semanticDedupThreshold: semanticDedupThresholdFrom(cfg),
    semanticDedupCandidates,
    noveltyGateEnabled: coerceBooleanLike(cfg.noveltyGateEnabled, "noveltyGateEnabled") === true,
    noveltyAddThreshold: clamp01(
      coerceNumber(cfg.noveltyAddThreshold, "noveltyAddThreshold"),
      DEFAULT_NOVELTY_ADD_THRESHOLD,
    ),
    noveltyNoopThreshold: clamp01(
      coerceNumber(cfg.noveltyNoopThreshold, "noveltyNoopThreshold"),
      DEFAULT_NOVELTY_NOOP_THRESHOLD,
    ),
  };
}

export function embeddingsFromCosineHits(
  hits: ReadonlyArray<{ id: string; score: number; sourceConnector?: string }>,
  opts: { candidateConnector?: string } = {},
): { embedding: number[]; neighborhood: NoveltyNeighbor[] } {
  // Connector-aware scoping (PR #2564 review finding on 54d865cb9): a
  // neighbor from a different (or unattributed) connector must not drive a
  // noop — the shared contract in `connector-scope.ts`, also applied by the
  // semantic skip gate and merge-on-write. Candidates without a connector
  // keep the unscoped neighborhood.
  const scope = normalizeConnectorScope(opts.candidateConnector);
  const scoped = hits.filter((hit) => connectorMatchesScope(hit.sourceConnector, scope));
  return {
    embedding: [1, 0],
    neighborhood: scoped.map((hit) => {
      const s = Number.isFinite(hit.score) ? Math.min(1, Math.max(-1, hit.score)) : 0;
      return { id: hit.id, embedding: [s, Math.sqrt(Math.max(0, 1 - s * s))] };
    }),
  };
}

export function scoreNovelty(
  embedding: number[],
  neighborhood: NoveltyNeighbor[],
  thresholds: NoveltyThresholds = {},
): NoveltyDecision {
  const addThreshold = clamp01(thresholds.addThreshold ?? DEFAULT_NOVELTY_ADD_THRESHOLD, DEFAULT_NOVELTY_ADD_THRESHOLD);
  const noopThreshold = clamp01(thresholds.noopThreshold ?? DEFAULT_NOVELTY_NOOP_THRESHOLD, DEFAULT_NOVELTY_NOOP_THRESHOLD);
  const k = thresholds.k !== undefined && Number.isFinite(thresholds.k) && thresholds.k > 0
    ? Math.floor(thresholds.k)
    : DEFAULT_NOVELTY_K;

  if (neighborhood.length === 0) {
    return { score: 1, decision: "add" };
  }

  const ranked = neighborhood
    .map((neighbor) => ({
      id: neighbor.id,
      cosine: cosine(embedding, neighbor.embedding),
    }))
    .sort((a, b) => b.cosine - a.cosine);
  const nearest = ranked.slice(0, Math.max(1, k));
  const density = nearest.reduce((sum, row) => sum + row.cosine, 0) / nearest.length;
  const score = 1 - density;
  const neighborId = ranked[0]?.id;

  if (score >= addThreshold) return { score, decision: "add", neighborId };
  if (score <= noopThreshold) return { score, decision: "noop", neighborId };
  return { score, decision: "uncertain", neighborId };
}

export async function applyNoveltyGate(opts: {
  enabled: boolean;
  addThreshold: number;
  noopThreshold: number;
  lookup: () => Promise<{ embedding: number[]; neighborhood: NoveltyNeighbor[] }>;
}): Promise<NoveltyDecision> {
  if (!opts.enabled) {
    return { score: 0, decision: "uncertain" };
  }
  try {
    const { embedding, neighborhood } = await opts.lookup();
    return scoreNovelty(embedding, neighborhood, {
      addThreshold: opts.addThreshold,
      noopThreshold: opts.noopThreshold,
    });
  } catch {
    return { score: 0, decision: "uncertain" };
  }
}

/**
 * Judge-mediated merge-on-write decision (issue #2330, harmonic 2/5).
 *
 * A new candidate fact that is semantically close — but NOT near-duplicate
 * close — to an existing active memory is offered to an LLM merge judge.
 * On a "merge" verdict the caller updates the existing entry in place
 * instead of writing a new fragment. Every failure mode fails closed to
 * "create": the unsafe default is always the unchanged write path.
 *
 * The near-duplicate skip path (similarity >= the semantic dedup
 * threshold) is untouched — this module only sees the band
 * `[minSimilarity, dedupThreshold)`.
 */

import { coerceBool, coerceNumber } from "../connectors/coerce.js";
import { MEMORY_CATEGORIES } from "../correction/correction-contract.js";
import type { SemanticMergeConfig } from "../types.js";
import { isActiveMemoryStatus } from "../memory-lifecycle-ledger-utils.js";
import { semanticDedupThresholdFrom } from "./novelty-gate.js";
import { parseMinMergeScore } from "./merge-min-score.js";
import { REFUSED_MERGE_CATEGORIES } from "./merge-on-write.js";
import { checkMergedContent } from "./merge-content.js";
import type { SemanticDedupHit, SemanticDedupLookup } from "./semantic.js";
import { normalizeConnectorScope } from "./connector-scope.js";

// ── Public types ──────────────────────────────────────────────────────────────

/** An existing memory considered as a merge target. */
export interface MergeCandidate {
  memoryId: string;
  content: string;
  category: string;
  similarity: number;
  /** Frontmatter status; only `active` (or absent) memories are eligible. */
  status: string;
}

/**
 * Raw (parsed but UNVALIDATED) judge verdict. `decideSemanticMerge`
 * hard-validates before trusting any field — an LLM-fabricated targetId
 * must never survive (issue #2330 step 2).
 */
export interface MergeJudgeRawVerdict {
  decision: "merge" | "create" | "contradicts";
  targetId?: string | null;
  mergedContent?: string | null;
  reason?: string | null;
}

/** The judge call injected by the caller (LLM-backed in production). */
export type MergeJudge = (input: {
  content: string;
  category: string;
  candidates: readonly MergeCandidate[];
}) => Promise<MergeJudgeRawVerdict>;

/** Resolves candidate metadata for a lookup hit id; null = unknown memory. */
export type MergeCandidateResolver = (
  memoryId: string,
) => Promise<{ content: string; category: string; status: string } | null>;

/** Why a candidate fell through to the unchanged create path. */
export type MergeCreateReason =
  | "disabled"
  | "no_candidates"
  | "judge_create"
  | "judge_contradicts"
  | "judge_invalid"
  | "judge_error"
  | "backend_unavailable";

export type MergeDecision =
  | { action: "create"; reason: MergeCreateReason }
  | {
      action: "merge";
      targetId: string;
      mergedContent: string;
      /**
       * The target body the judge actually merged. The persist side must
       * compare it against the target it is about to write and fall back to
       * create when it differs: in a multi-writer deployment another
       * extraction can update the target between this decision and the write,
       * and `mergedContent` was computed from the older body.
       */
      targetContent: string;
      reason: "judge_merge";
    };

export interface DecideSemanticMergeOptions {
  content: string;
  category: string;
  lookup: SemanticDedupLookup;
  judge: MergeJudge;
  config: SemanticMergeConfig;
  /** Upper bound of the merge band: the semantic-dedup threshold. */
  dedupThreshold: number;
  resolveCandidate: MergeCandidateResolver;
  /**
   * Provenance connector of the INCOMING fact. Merge selection is stricter
   * than the novelty and semantic-dedup gates (`connector-scope.ts`): a merge
   * may only pair an unscoped fact with an unscoped target, or a
   * provenance-bearing fact with a neighbor from the same connector. A merge
   * rewrites the target's body, so any other pairing would relabel one side's
   * claims under the other's `sourceConnector` frontmatter (finding B).
   */
  sourceConnector?: string;
}

// ── Decision function ─────────────────────────────────────────────────────────

/** Total order: similarity desc, then memoryId asc (checklist #12). */
function compareMergeCandidates(a: MergeCandidate, b: MergeCandidate): number {
  if (a.similarity !== b.similarity) return b.similarity - a.similarity;
  return a.memoryId < b.memoryId ? -1 : a.memoryId > b.memoryId ? 1 : 0;
}

export async function decideSemanticMerge(
  options: DecideSemanticMergeOptions,
): Promise<MergeDecision> {
  const { config } = options;
  if (config.enabled !== true) return { action: "create", reason: "disabled" };
  // 0 disables merging entirely — short-circuit BEFORE the lookup so no
  // embedding backend call is made (config is runtime API; never coerce 0).
  if (!(config.maxCandidates > 0)) return { action: "create", reason: "disabled" };
  if (!(config.categories as readonly string[]).includes(options.category)) {
    return { action: "create", reason: "disabled" };
  }
  const trimmed = typeof options.content === "string" ? options.content.trim() : "";
  if (!trimmed) return { action: "create", reason: "no_candidates" };

  // Lookup throws = backend down (distinct from an empty index, #22).
  // Round N+17 (A): the fetch deliberately OVERSHOOTS maxCandidates. The
  // eligibility predicates below (band, connector scope, category, active
  // status) run after the lookup, so fetching exactly maxCandidates let
  // ineligible hits — a foreign connector or category, an inactive row —
  // occupy the whole fetch window and crowd out a valid target ranked
  // immediately beneath them; the write then created another fragment.
  // maxCandidates still bounds what reaches the JUDGE (the slice below is
  // the only truncation point).
  let hits: SemanticDedupHit[];
  try {
    hits = await options.lookup(trimmed, config.maxCandidates * CANDIDATE_OVERFETCH_FACTOR);
  } catch {
    return { action: "create", reason: "backend_unavailable" };
  }
  if (!Array.isArray(hits) || hits.length === 0) {
    return { action: "create", reason: "no_candidates" };
  }

  // Connector scope (finding B): a merge REWRITES the neighbor's body, so it
  // is stricter than the shared dedup helper — both sides must be unscoped or
  // carry the identical connector. An unscoped merge into a connector-owned
  // target would rewrite A's memory while A's `sourceConnector` frontmatter
  // still identifies A, so recall and connector-aware dedup would label the
  // unscoped claims as A's.
  const scope = normalizeConnectorScope(options.sourceConnector);
  const candidates: MergeCandidate[] = [];
  for (const hit of hits) {
    if (
      !hit ||
      typeof hit.id !== "string" ||
      hit.id.trim().length === 0 ||
      typeof hit.score !== "number" ||
      !Number.isFinite(hit.score)
    ) {
      continue;
    }
    // Band: [minSimilarity, dedupThreshold). The upper edge is owned by the
    // near-duplicate skip path and must stay excluded.
    if (!(hit.score >= config.minSimilarity && hit.score < options.dedupThreshold)) {
      continue;
    }
    if (normalizeConnectorScope(hit.sourceConnector) !== scope) continue;
    const meta = await options.resolveCandidate(hit.id);
    if (!meta) continue;
    if (meta.category !== options.category) continue;
    if (!isActiveMemoryStatus(meta.status)) continue;
    candidates.push({
      memoryId: hit.id,
      content: meta.content,
      category: meta.category,
      similarity: hit.score,
      status: meta.status,
    });
  }
  if (candidates.length === 0) return { action: "create", reason: "no_candidates" };

  candidates.sort(compareMergeCandidates);
  // Eligible-first truncation (round N+17 A): the judge sees up to
  // maxCandidates ELIGIBLE neighbors — never the raw top-of-index hits.
  const limited = candidates.slice(0, config.maxCandidates);

  let verdict: MergeJudgeRawVerdict;
  try {
    verdict = await options.judge({
      content: trimmed,
      category: options.category,
      candidates: limited,
    });
  } catch {
    return { action: "create", reason: "judge_error" };
  }
  if (!verdict || typeof verdict !== "object") {
    return { action: "create", reason: "judge_invalid" };
  }
  if (verdict.decision === "create") return { action: "create", reason: "judge_create" };
  if (verdict.decision === "contradicts") return { action: "create", reason: "judge_contradicts" };

  // Hard post-validation: never trust the model to echo ids.
  const target =
    typeof verdict.targetId === "string"
      ? limited.find((c) => c.memoryId === verdict.targetId)
      : undefined;
  if (!target) return { action: "create", reason: "judge_invalid" };
  const content = checkMergedContent({
    mergedContent: verdict.mergedContent,
    incomingContent: trimmed,
    targetContent: target.content,
  });
  if (!content.ok) return { action: "create", reason: "judge_invalid" };
  return {
    action: "merge",
    targetId: target.memoryId,
    mergedContent: content.content,
    targetContent: target.content,
    reason: "judge_merge",
  };
}

// ── Config parsing ────────────────────────────────────────────────────────────

export const DEFAULT_SEMANTIC_MERGE_CATEGORIES = [
  "fact",
  "preference",
  "decision",
  "relationship",
  "skill",
] as const;

/**
 * The categories `semanticMerge.categories` may name: every known memory
 * category except the episodic/immutable ones `REFUSED_MERGE_CATEGORIES`
 * excludes at runtime — listing a refused category configures a gate that
 * can never fire, and an unknown string (a typo like "facts") silently
 * disables merging for every category, so both are rejected at parse time.
 */
export const MERGEABLE_MEMORY_CATEGORIES: readonly string[] = MEMORY_CATEGORIES.filter(
  (category) => !(REFUSED_MERGE_CATEGORIES as readonly string[]).includes(category),
);

export const DEFAULT_SEMANTIC_MERGE_MIN = 0.8;
export const DEFAULT_SEMANTIC_MERGE_CANDIDATES = 3;

/**
 * Round N+17 (A): the neighbor fetch overshoots `maxCandidates` by this
 * factor so eligibility filtering happens BEFORE truncation. Bounded
 * ceiling: a corpus holding more than this many consecutive ineligible
 * neighbors above the valid target still crowds it out; raise only with
 * evidence of that corpus shape.
 */
const CANDIDATE_OVERFETCH_FACTOR = 4;

function describeValue(value: unknown): string {
  try {
    const serialized = JSON.stringify(value);
    return serialized === undefined ? String(value) : serialized;
  } catch {
    return String(value);
  }
}

/**
 * Parse the `semanticMerge` block (issue #2330). Follows the `procedural.*`
 * worked example: strict booleans that reject unrecognized values, CLI
 * string coercion for numbers ("0" is zero, never coerced upward), and
 * parse-time rejection of an empty merge band (`minSimilarity` must be
 * strictly below the semantic-dedup threshold that owns the band's top).
 * Invalid input is rejected, never silently defaulted or reinterpreted: a
 * present block that is not an object, a present-but-`undefined` or
 * unparseable field (`enabled`, `shadowMode`, `minSimilarity`,
 * `maxCandidates` "abc"/an object/NaN/infinity, or a malformed `categories`
 * array) each throw. Presence is OWN-property presence (checklist #46): a
 * key inherited through the prototype chain never applies, and only a key
 * absent from `Object.getOwnPropertyNames` means "use the defaults".
 *
 * The band check applies only when it can describe a real misconfiguration:
 * merging is enabled, or `minSimilarity` was set explicitly. A deployment
 * that predates this block and lowered `semanticDedupThreshold` to <= the
 * default merge minimum must keep starting — the disabled feature performs
 * no band lookup at all, so rejecting that config would be a gratuitous
 * backward-compatibility break.
 */
export function parseSemanticMergeConfig(
  cfg: Record<string, unknown>,
): { semanticMerge: SemanticMergeConfig } {
  // Own-property presence (checklist #46): a bracket read follows the
  // prototype chain, and `=== undefined` folds present-but-invalid into
  // absent. Gate every presence question on Object.hasOwn.
  const blockPresent = Object.hasOwn(cfg, "semanticMerge");
  const block = blockPresent ? cfg.semanticMerge : undefined;
  if (
    block !== undefined &&
    (typeof block !== "object" || block === null || Array.isArray(block))
  ) {
    throw new Error(
      `semanticMerge must be an object when present (got ${describeValue(block)}). Remove the block to fall back to the defaults.`,
    );
  }
  if (blockPresent && block === undefined) {
    throw new Error(
      `semanticMerge must be an object when present (got ${describeValue(block)}). Remove the key to fall back to the defaults.`,
    );
  }
  const raw = (block ?? {}) as Record<string, unknown>;
  const parseGate = (key: string, fallback: boolean): boolean => {
    if (!Object.hasOwn(raw, key)) return fallback;
    const value = raw[key];
    const coerced = coerceBool(value, `semanticMerge.${key}`);
    if (coerced === undefined) {
      throw new Error(
        `semanticMerge.${key} must be a boolean or one of "true"/"false"/"1"/"0"/"yes"/"no"/"on"/"off" (got ${describeValue(value)}).`,
      );
    }
    return coerced;
  };
  const minSimilarityPresent = Object.hasOwn(raw, "minSimilarity");
  const minSimilarity = minSimilarityPresent
    ? parseMinMergeScore(raw.minSimilarity)
    : DEFAULT_SEMANTIC_MERGE_MIN;
  // Round N+2 (D) — distinguish an ABSENT key from a present-but-unparseable
  // value (#1/#39/#45): coerceNumber returns undefined for "abc", objects,
  // NaN, and ±Infinity, and an undefined result here must never fall back to
  // the default — that would silently enable judge lookups under an invalid
  // config. Only a key absent from the own-property set means "use the
  // default"; present-but-`undefined` is invalid like any other bad value.
  const maxCandidates = (() => {
    if (!Object.hasOwn(raw, "maxCandidates")) return DEFAULT_SEMANTIC_MERGE_CANDIDATES;
    const rawCandidatesValue = raw.maxCandidates;
    const rawCandidates = coerceNumber(rawCandidatesValue, "semanticMerge.maxCandidates");
    if (rawCandidates === undefined || !Number.isInteger(rawCandidates) || rawCandidates < 0) {
      throw new Error(
        `semanticMerge.maxCandidates must be an integer >= 0 (got ${describeValue(rawCandidatesValue)}). Remove the key to use the default (${DEFAULT_SEMANTIC_MERGE_CANDIDATES}) or set 0 to disable merging entirely.`,
      );
    }
    return rawCandidates;
  })();
  const categories = (() => {
    if (!Object.hasOwn(raw, "categories")) return [...DEFAULT_SEMANTIC_MERGE_CATEGORIES];
    const rawCategories = raw.categories;
    if (
      !Array.isArray(rawCategories) ||
      !rawCategories.every((c) => typeof c === "string" && c.length > 0)
    ) {
      throw new Error(
        `semanticMerge.categories must be an array of non-empty category names (got ${describeValue(rawCategories)}).`,
      );
    }
    const invalidCategory = rawCategories.find(
      (c) => !MERGEABLE_MEMORY_CATEGORIES.includes(c),
    );
    if (invalidCategory !== undefined) {
      throw new Error(
        `semanticMerge.categories contains an unknown or never-mergeable category: ${describeValue(invalidCategory)}. Valid categories: ${MERGEABLE_MEMORY_CATEGORIES.join(", ")}. The episodic and immutable categories (${REFUSED_MERGE_CATEGORIES.join(", ")}) never merge and cannot be listed.`,
      );
    }
    return [...rawCategories];
  })();
  const enabled = parseGate("enabled", false);
  const dedupThreshold = semanticDedupThresholdFrom(cfg);
  if ((enabled || minSimilarityPresent) && minSimilarity >= dedupThreshold) {
    throw new Error(
      `semanticMerge.minSimilarity (${minSimilarity}) must be strictly below semanticDedupThreshold (${dedupThreshold}) — the near-duplicate skip path owns similarities at or above it.`,
    );
  }
  return {
    semanticMerge: {
      enabled,
      minSimilarity,
      maxCandidates,
      categories,
      shadowMode: parseGate("shadowMode", false),
    },
  };
}

import { coerceNumber } from "./connectors/coerce.js";

export function parseQmdSupportedVersion(value: unknown): string {
  if (value === undefined || value === null) return "2.8.3";
  if (typeof value !== "string") {
    throw new Error(`qmdSupportedVersion must be a semantic version string; got ${JSON.stringify(value)}`);
  }
  const normalized = value.trim();
  if (!/^\d+\.\d+\.\d+$/.test(normalized)) {
    throw new Error(
      `qmdSupportedVersion must be a semantic version string like "2.8.3"; got ${JSON.stringify(value)}`,
    );
  }
  return normalized;
}

export function parseQmdGpuBackend(value: unknown): "auto" | "metal" | "cuda" | "vulkan" | "false" | undefined {
  if (value === undefined || value === null) return undefined;
  if (value === false) return "false";
  if (typeof value !== "string") {
    throw new Error(`qmdGpuBackend must be one of "auto", "metal", "cuda", "vulkan", or false; got ${JSON.stringify(value)}`);
  }
  const normalized = value.trim().toLowerCase();
  if (
    normalized === "auto" ||
    normalized === "metal" ||
    normalized === "cuda" ||
    normalized === "vulkan" ||
    normalized === "false"
  ) {
    return normalized;
  }
  throw new Error(`qmdGpuBackend must be one of "auto", "metal", "cuda", "vulkan", or false; got ${JSON.stringify(value)}`);
}

export function parseQmdChunkStrategy(value: unknown): "auto" | "regex" {
  if (value === undefined || value === null) return "auto";
  if (typeof value !== "string") {
    throw new Error(`qmdChunkStrategy must be "auto" or "regex"; got ${JSON.stringify(value)}`);
  }
  const normalized = value.trim().toLowerCase();
  if (normalized === "auto" || normalized === "regex") return normalized;
  throw new Error(`qmdChunkStrategy must be "auto" or "regex"; got ${JSON.stringify(value)}`);
}

// Issue #1335. Default "hybrid" preserves the historical lex+vec+hyde daemon plan.
export function parseQmdSearchStrategy(value: unknown): "hybrid" | "lex-vec" | "lex" {
  if (value === undefined || value === null) return "hybrid";
  if (typeof value !== "string") {
    throw new Error(
      `qmdSearchStrategy must be one of "hybrid", "lex-vec", or "lex"; got ${JSON.stringify(value)}`,
    );
  }
  const normalized = value.trim().toLowerCase();
  if (normalized === "hybrid" || normalized === "lex-vec" || normalized === "lex") {
    return normalized;
  }
  throw new Error(
    `qmdSearchStrategy must be one of "hybrid", "lex-vec", or "lex"; got ${JSON.stringify(value)}`,
  );
}

// Issue #1335. Reject non-numeric / non-integer timeouts rather than silently
// coercing them (gotcha #51), then clamp valid integers to the documented bounds.
export function parseQmdDaemonTimeoutMs(value: unknown): number {
  if (value === undefined || value === null) return 60_000;
  const coerced = coerceNumber(value);
  if (coerced === undefined || !Number.isInteger(coerced)) {
    throw new Error(
      `qmdDaemonTimeoutMs must be an integer number of milliseconds between 1000 and 120000; got ${JSON.stringify(value)}`,
    );
  }
  return Math.min(120_000, Math.max(1_000, coerced));
}

// Issue #1335. Default "query" keeps `qmd query` (LLM expansion + rerank) per gotcha #7.
export function parseQmdSubprocessStrategy(value: unknown): "query" | "search" {
  if (value === undefined || value === null) return "query";
  if (typeof value !== "string") {
    throw new Error(
      `qmdSubprocessStrategy must be one of "query" or "search"; got ${JSON.stringify(value)}`,
    );
  }
  const normalized = value.trim().toLowerCase();
  if (normalized === "query" || normalized === "search") return normalized;
  throw new Error(
    `qmdSubprocessStrategy must be one of "query" or "search"; got ${JSON.stringify(value)}`,
  );
}

import { coerceBool } from "./connectors/coerce.js";
import { readEnvVar } from "./runtime/env.js";
import {
  DEFAULT_UNTRUSTED_ORIGINS,
  HARDENED_UNTRUSTED_ORIGINS,
} from "./security/origin-authority.js";
import type { MemoryInjectionDefenseMode } from "./security/types.js";
import type { InjectionScreenProfile } from "./security/injection-screen.js";

// Memory-poisoning hardening (#1955): preserve explicit config, but let env
// values replace schema-materialized defaults from the host config loader.
function resolveSecurityBooleanConfig(
  value: unknown,
  rawOperatorConfig: Record<string, unknown> | null | undefined,
  flagName: string,
  envName: string,
  defaultValue: boolean,
): boolean {
  const rawAuthored =
    rawOperatorConfig !== undefined &&
    rawOperatorConfig !== null &&
    Object.prototype.hasOwnProperty.call(rawOperatorConfig, flagName) &&
    rawOperatorConfig[flagName] !== undefined &&
    rawOperatorConfig[flagName] !== null;
  const schemaDefaultMaterialized =
    rawOperatorConfig !== undefined &&
    !rawAuthored &&
    value === defaultValue;
  if (!schemaDefaultMaterialized && value !== undefined && value !== null) {
    return resolveBooleanConfig(value, defaultValue, flagName);
  }
  if (rawAuthored) {
    return resolveBooleanConfig(value ?? rawOperatorConfig?.[flagName], defaultValue, flagName);
  }
  const envValue = readEnvVar(envName);
  return envValue === undefined
    ? defaultValue
    : resolveBooleanConfig(envValue, defaultValue, flagName);
}

function resolveBooleanConfig(
  value: unknown,
  defaultValue: boolean,
  keyName: string,
): boolean {
  if (value === undefined || value === null) return defaultValue;
  const coerced = coerceBool(value);
  if (coerced === undefined) {
    throw new Error(
      `${keyName} must be a boolean-like value (true/false/1/0/yes/no/on/off); got ${JSON.stringify(value)}`,
    );
  }
  return coerced;
}

// Memory-poisoning hardening (#1955): keep origin allow-list parsing in the
// parser module so config-contract extraction covers this delegated surface.
function resolveUntrustedOrigins(
  value: unknown,
  rawOperatorConfig: Record<string, unknown> | null | undefined,
): string[] {
  const rawAuthored =
    rawOperatorConfig !== undefined &&
    rawOperatorConfig !== null &&
    Object.prototype.hasOwnProperty.call(rawOperatorConfig, "untrustedOrigins") &&
    rawOperatorConfig.untrustedOrigins !== undefined &&
    rawOperatorConfig.untrustedOrigins !== null;
  const schemaDefaultMaterialized =
    rawOperatorConfig !== undefined &&
    !rawAuthored &&
    Array.isArray(value) &&
    value.length === DEFAULT_UNTRUSTED_ORIGINS.length &&
    value.every((entry, index) => entry === DEFAULT_UNTRUSTED_ORIGINS[index]);
  const configValue = schemaDefaultMaterialized ? undefined : value;
  const fromEnv = configValue === undefined || configValue === null;
  const envValue = fromEnv ? readEnvVar("REMNIC_UNTRUSTED_ORIGINS") : undefined;
  const source = fromEnv ? envValue : configValue;
  if (source === undefined || source === null) return [...DEFAULT_UNTRUSTED_ORIGINS];

  let entries: unknown[];
  if (Array.isArray(source)) {
    entries = source;
  } else if (fromEnv && typeof source === "string" && source.trim().length > 0) {
    const trimmed = source.trim();
    if (trimmed.startsWith("[")) {
      try {
        const parsed: unknown = JSON.parse(trimmed);
        if (!Array.isArray(parsed)) throw new Error("not an array");
        entries = parsed;
      } catch {
        throw new Error("untrustedOrigins must be an array of strings");
      }
    } else {
      entries = trimmed.split(",");
    }
  } else {
    throw new Error("untrustedOrigins must be an array of strings");
  }

  const normalized: string[] = [];
  for (const entry of entries) {
    if (typeof entry !== "string") {
      throw new Error("untrustedOrigins must be an array of strings");
    }
    const trimmed = entry.trim();
    if (trimmed.length > 0) normalized.push(trimmed);
  }
  return normalized.length > 0 ? normalized : [...DEFAULT_UNTRUSTED_ORIGINS];
}

function validateDefenseMode(value: unknown): MemoryInjectionDefenseMode {
  if (
    value === "custom"
    || value === "off"
    || value === "fencing"
    || value === "quarantine"
    || value === "layered"
  ) {
    return value;
  }
  throw new Error(
    `memoryInjectionDefenseMode must be custom|off|fencing|quarantine|layered; got ${JSON.stringify(value)}`,
  );
}

function isOperatorAuthored(
  rawOperatorConfig: Record<string, unknown> | null | undefined,
  key: string,
): boolean {
  return rawOperatorConfig !== undefined
    && rawOperatorConfig !== null
    && Object.prototype.hasOwnProperty.call(rawOperatorConfig, key)
    && (rawOperatorConfig as Record<string, unknown>)[key] !== undefined
    && (rawOperatorConfig as Record<string, unknown>)[key] !== null;
}

function resolveMemoryInjectionDefenseMode(
  value: unknown,
  rawOperatorConfig: Record<string, unknown> | null | undefined,
): MemoryInjectionDefenseMode {
  // Precedence: operator-authored config, then the environment, then a
  // host-materialized schema default. A host that fills in the manifest
  // default must not shadow an operator's environment override.
  if (isOperatorAuthored(rawOperatorConfig, "memoryInjectionDefenseMode")) {
    return validateDefenseMode(
      (rawOperatorConfig as Record<string, unknown>).memoryInjectionDefenseMode,
    );
  }
  const envValue = readEnvVar("REMNIC_MEMORY_INJECTION_DEFENSE_MODE");
  if (envValue !== undefined && rawOperatorConfig !== undefined) return validateDefenseMode(envValue);
  if (value !== undefined && value !== null) return validateDefenseMode(value);
  if (envValue !== undefined) return validateDefenseMode(envValue);
  return "custom";
}

function hasExplicitUntrustedOrigins(
  cfg: Record<string, unknown>,
  rawOperatorConfig: Record<string, unknown> | null | undefined,
): boolean {
  const configAuthored = rawOperatorConfig === undefined
    ? Object.prototype.hasOwnProperty.call(cfg, "untrustedOrigins")
    : rawOperatorConfig !== null
      && Object.prototype.hasOwnProperty.call(rawOperatorConfig, "untrustedOrigins");
  return configAuthored || readEnvVar("REMNIC_UNTRUSTED_ORIGINS") !== undefined;
}

export function parseSecurityConfig(
  cfg: Record<string, unknown>,
  rawOperatorConfig: Record<string, unknown> | null | undefined,
): {
  memoryInjectionDefenseMode: MemoryInjectionDefenseMode;
  originAuthorityEnabled: boolean;
  injectionScreenEnabled: boolean;
  injectionScreenProfile: InjectionScreenProfile;
  untrustedOrigins: string[];
} {
  const memoryInjectionDefenseMode = resolveMemoryInjectionDefenseMode(
    cfg.memoryInjectionDefenseMode,
    rawOperatorConfig,
  );
  const customOriginAuthority = resolveSecurityBooleanConfig(
    cfg.originAuthorityEnabled,
    rawOperatorConfig,
    "originAuthorityEnabled",
    "REMNIC_ORIGIN_AUTHORITY_ENABLED",
    false,
  );
  const customInjectionScreen = resolveSecurityBooleanConfig(
    cfg.injectionScreenEnabled,
    rawOperatorConfig,
    "injectionScreenEnabled",
    "REMNIC_INJECTION_SCREEN_ENABLED",
    true,
  );
  const flags = {
    custom: [customOriginAuthority, customInjectionScreen],
    off: [false, false],
    fencing: [true, false],
    quarantine: [false, true],
    layered: [true, true],
  } satisfies Record<MemoryInjectionDefenseMode, readonly [boolean, boolean]>;
  const [originAuthorityEnabled, injectionScreenEnabled] = flags[memoryInjectionDefenseMode];
  const injectionScreenProfile: InjectionScreenProfile =
    memoryInjectionDefenseMode === "custom" ? "default" : "hardened";
  const configuredOrigins = resolveUntrustedOrigins(cfg.untrustedOrigins, rawOperatorConfig);
  const untrustedOrigins =
    memoryInjectionDefenseMode !== "custom"
      && !hasExplicitUntrustedOrigins(cfg, rawOperatorConfig)
      ? [...HARDENED_UNTRUSTED_ORIGINS]
      : configuredOrigins;
  return {
    memoryInjectionDefenseMode,
    originAuthorityEnabled,
    injectionScreenEnabled,
    injectionScreenProfile,
    untrustedOrigins,
  };
}

/**
 * emit-legacy-tools — resolution cluster for the `emitLegacyTools` and
 * `namespaceCatalogEnabled` config gates (issues #1427, #1499, #1550).
 *
 * Extracted from packages/remnic-core/src/config.ts (PR #1593, round 6)
 * so the raw-vs-effective split, runtime-override precedence, and
 * fileConfig-null normalization logic specific to these two gates
 * stays out of the god-file `config.ts`. The export surface is exactly
 * the two resolvers plus the `coerceBooleanLikeOrThrow` helper that
 * wraps the local `coerceBooleanLike` — every other config gate in
 * `parseConfig` keeps using its own inline coercion or the
 * `coerceBooleanLike` already exported from
 * `packages/remnic-core/src/connectors/coerce.ts`.
 *
 * Precedence (PR #1593 rounds 1-4, plus the null/loader hardening from
 * rounds 3-5):
 *
 *   1. `configValue` (the first arg) is the MERGED config
 *      (runtime-over-file via the
 *      `{...fileConfig, ...api.pluginConfig}` spread in src/index.ts).
 *      If it's a real boolean, it represents what the operator wants,
 *      so honor it. We only fall through when it's the schema-default
 *      materialization with no operator authoring in raw.
 *   2. `rawOperatorConfig` (the second arg) is the operator-supplied
 *      config block BEFORE the OpenClaw manifest layer applies schema
 *      defaults — i.e. the file-backed `loadPluginConfigFromFile` output.
 *      When raw has the key with a non-null/undefined value, the file
 *      layer authored it. The merged `configValue` reflects the full
 *      operator intent (file + runtime), so `configValue` is still
 *      authoritative. raw presence is used only as the "operator
 *      authored this key" signal — if raw is missing AND configValue
 *      equals the schema default, only the schema layer materialized the
 *      key (no operator intent anywhere) and we fall through to env /
 *      sticky-legacy.
 *   3. Legacy callers (raw undefined): trust configValue as before to
 *      preserve the 121+ existing call sites that pass only one arg.
 *
 * Defensive normalization (PR #1593 round 3): JSON null on disk for the
 * operator config block surfaces as `null` in rawOperatorConfig. Both
 * resolvers normalize `null` to `{}` so the `"key" in rawOperatorConfig`
 * check never throws. The file loader
 * (`loadPluginConfigFromFile`) also normalizes null to undefined
 * before reaching here.
 */

import { readEnvVar } from "./runtime/env.js";
import { hasLegacyConnectorEntries } from "./connectors/paths.js";

/**
 * Coerce common string/number representations of a boolean to a real
 * boolean. Returns `undefined` when the value cannot be interpreted, so
 * callers can fail fast via `coerceBooleanLikeOrThrow`. Guards against
 * the "string `false` is truthy" footgun (CLAUDE.md gotcha #36) when
 * config values arrive from CLI/env/JSON sources where booleans are
 * sometimes string-typed.
 *
 * Local copy — the canonical implementation lives in
 * `packages/remnic-core/src/connectors/coerce.ts` but is private to that
 * module's `coerceBool` export; duplicating here keeps the god-file
 * contract clean (no cross-module pull) for the two gates that need
 * fail-fast rejection.
 */
function coerceBooleanLike(value: unknown): boolean | undefined {
  if (typeof value === "boolean") return value;
  if (typeof value === "number") {
    if (value === 1) return true;
    if (value === 0) return false;
    return undefined;
  }
  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    if (
      normalized === "true" ||
      normalized === "1" ||
      normalized === "yes" ||
      normalized === "on"
    ) {
      return true;
    }
    if (
      normalized === "false" ||
      normalized === "0" ||
      normalized === "no" ||
      normalized === "off"
    ) {
      return false;
    }
  }
  return undefined;
}

/**
 * Coerce a present boolean-like gate value or fail fast. A PRESENT but
 * unrecognized value ("fales", 2) is REJECTED rather than silently
 * defaulting (CLAUDE.md rule #51) — shared by both resolvers below so
 * the rejection behavior cannot drift between them.
 */
function coerceBooleanLikeOrThrow(label: string, value: unknown): boolean {
  const coerced = coerceBooleanLike(value);
  if (coerced === undefined) {
    throw new Error(
      `${label} must be a boolean-like value (true/false/1/0/yes/no/on/off); got ${JSON.stringify(value)}`,
    );
  }
  return coerced;
}

/**
 * Resolve the `emitLegacyTools` opt-out (issue #1427, defaults revised in
 * #1550). Precedence: operator-set raw config, then merged (post-defaults)
 * config, then the REMNIC_/ENGRAM_ env var, then a sticky-legacy default —
 * `true` only when existing legacy connector entries are present on disk
 * (`hasLegacyConnectorEntries`), `false` for fresh installs.
 */
export function resolveEmitLegacyTools(
  configValue: unknown,
  rawOperatorConfig: Record<string, unknown> | undefined | null,
  runtimeSet?: ReadonlySet<string>,
): boolean {
  // Defensive null normalization — see file header for the rationale.
  if (rawOperatorConfig === null) rawOperatorConfig = {};
  // Schema default for `emitLegacyTools` is `false` (issue #1550).
  const SCHEMA_DEFAULT = false;
  // Round 8: `runtimeAuthored` is now informational only — the resolver
  // does not consult it (see the comment on the check below). Kept as a
  // local so the signature-bound `runtimeSet` parameter remains useful
  // for future refactors and tests can read this state if needed.
  const runtimeAuthored = runtimeSet?.has("emitLegacyTools") ?? false;
  if (rawOperatorConfig !== undefined) {
    if (configValue !== undefined && configValue !== null) {
      const rawValue = (rawOperatorConfig as Record<string, unknown>).emitLegacyTools;
      const rawAuthored =
        "emitLegacyTools" in rawOperatorConfig &&
        rawValue !== null &&
        rawValue !== undefined;
      // Round 8 (PR #1593): revert the runtimeAuthored gate. OpenClaw's
      // `applyDefaults: true` materialization means api.pluginConfig keys
      // can't reliably signal operator authorship; the schema-default
      // comparison alone is the right signal (chatgpt-codex-connector P1
      // on src/index.ts:1348, round 8).
      if (rawAuthored || configValue !== SCHEMA_DEFAULT) {
        return coerceBooleanLikeOrThrow("emitLegacyTools", configValue);
      }
    } else if ("emitLegacyTools" in rawOperatorConfig) {
      const rawValue = (rawOperatorConfig as Record<string, unknown>).emitLegacyTools;
      if (rawValue !== null && rawValue !== undefined) {
        return coerceBooleanLikeOrThrow("emitLegacyTools", rawValue);
      }
    }
  } else if (configValue !== undefined && configValue !== null) {
    // Legacy caller (no rawOperatorConfig) — trust the merged value.
    return coerceBooleanLikeOrThrow("emitLegacyTools", configValue);
  }
  const envRaw =
    readEnvVar("REMNIC_EMIT_LEGACY_TOOLS") ?? readEnvVar("ENGRAM_EMIT_LEGACY_TOOLS");
  if (envRaw !== undefined) {
    return coerceBooleanLikeOrThrow("REMNIC_EMIT_LEGACY_TOOLS", envRaw);
  }
  return hasLegacyConnectorEntries();
}

/**
 * Resolve the `namespaceCatalogEnabled` opt-out (issue #1499). Same
 * raw-vs-effective split as `resolveEmitLegacyTools` — schema-default
 * hardening at the helper level so adding a `false` default later cannot
 * silently flip behavior on upgraded installs (#1550 class hardening).
 */
export function resolveNamespaceCatalogEnabled(
  configValue: unknown,
  rawOperatorConfig: Record<string, unknown> | undefined | null,
  runtimeSet?: ReadonlySet<string>,
): boolean {
  // Defensive null normalization — see file header for the rationale.
  if (rawOperatorConfig === null) rawOperatorConfig = {};
  // Schema default is `true` (the catalog is opt-out).
  const SCHEMA_DEFAULT = true;
  // Round 8: same as the emit variant — `runtimeAuthored` is
  // informational only, the resolver does not consult it.
  const runtimeAuthored = runtimeSet?.has("namespaceCatalogEnabled") ?? false;
  if (rawOperatorConfig !== undefined) {
    if (configValue !== undefined && configValue !== null) {
      const rawValue = (rawOperatorConfig as Record<string, unknown>)
        .namespaceCatalogEnabled;
      const rawAuthored =
        "namespaceCatalogEnabled" in rawOperatorConfig &&
        rawValue !== null &&
        rawValue !== undefined;
      // Round 8: same rollback as resolveEmitLegacyTools.
      if (rawAuthored || configValue !== SCHEMA_DEFAULT) {
        return coerceBooleanLikeOrThrow("namespaceCatalogEnabled", configValue);
      }
    } else if ("namespaceCatalogEnabled" in rawOperatorConfig) {
      const rawValue = (rawOperatorConfig as Record<string, unknown>)
        .namespaceCatalogEnabled;
      if (rawValue !== null && rawValue !== undefined) {
        return coerceBooleanLikeOrThrow("namespaceCatalogEnabled", rawValue);
      }
    }
  } else if (configValue !== undefined && configValue !== null) {
    // Legacy caller (no rawOperatorConfig) — trust the merged value.
    return coerceBooleanLikeOrThrow("namespaceCatalogEnabled", configValue);
  }
  return SCHEMA_DEFAULT;
}

/**
 * Wearables config parsing — strict, loud, and default-safe.
 *
 * Mirrors the `procedural` block conventions in config.ts: shape
 * violations and unparseable values throw with actionable messages
 * (CLAUDE.md rule 51); boolean-ish strings coerce via the shared
 * helpers (rule 36); every numeric knob is bounds-checked; the
 * memory-creation default is the least-privileged mode (rule 48).
 */

import { coerceBool, coerceNumber } from "../connectors/coerce.js";
import type { ImportanceLevel } from "../types.js";
import { compileCorrectionRules } from "./corrections.js";
import { compileRedactionPatterns } from "./redaction.js";
import type {
  OffTheRecordMarkerSettings,
  WearableCleanupSettings,
  WearableCorrectionRule,
  WearableMemoryMode,
  WearableFusionConfig,
  WearableSourceSettings,
  WearablesConfig,
} from "./types.js";

export const KNOWN_WEARABLE_SOURCE_IDS = ["limitless", "bee", "omi"] as const;

const MEMORY_MODES: WearableMemoryMode[] = ["off", "review", "auto", "smart"];
const IMPORTANCE_LEVELS: ImportanceLevel[] = [
  "trivial",
  "low",
  "normal",
  "high",
  "critical",
];
const NATIVE_IMPORT_MODES = ["off", "review", "smart"] as const;

const DEFAULT_MIN_CONFIDENCE = 0.6;
const DEFAULT_MIN_IMPORTANCE: ImportanceLevel = "low";
// Uncapped by default — wearables capture full days and the smart trust
// pipeline is the quality gate; a count cap would drop real memories on
// busy days. Operators who want a ceiling set any positive integer.
const DEFAULT_MAX_MEMORIES_PER_DAY = 0;
const DEFAULT_AUTO_SYNC_ENABLED = true;
const DEFAULT_AUTO_SYNC_INTERVAL_MINUTES = 15;
const MAX_AUTO_SYNC_INTERVAL_MINUTES = 1440;
const DEFAULT_AUTO_SYNC_DAYS = 2;
const DEFAULT_AUTO_SYNC_DEEP_DAYS = 7;
const MAX_AUTO_SYNC_WINDOW_DAYS = 90;
const DEFAULT_SOURCE_TRUST = 0.8;
const DEFAULT_AUTO_APPROVE_TRUST = 0.7;
const DEFAULT_REVIEW_TRUST = 0.45;
// Cross-source fusion (#1810) — disabled by default; enabling is the
// only behavior change fusion introduces.
const DEFAULT_FUSION_ENABLED = false;
const DEFAULT_FUSION_PROXIMITY_GAP_MS = 300_000;
const DEFAULT_FUSION_WINDOW_TOLERANCE_MS = 30_000;

// Sources whose provider emits per-utterance text but unreliable
// speaker labels (Bee falls back to a generic "unknown" label when
// diarization is unavailable). For those, the cleanup default keeps
// utterance-level boundaries so a whole conversation does not collapse
// into one mega-segment (issue #1811). Other sources keep the legacy
// merge-everything default unless explicitly configured.
const BOUNDARY_PRESERVING_SOURCE_IDS = new Set<string>(["bee"]);

/**
 * Default cleanup settings. `sourceId` (the connector id this block
 * belongs to) only adjusts the `preserveUtteranceBoundaries` default —
 * every other toggle is identical across sources.
 */
export function defaultWearableCleanupSettings(
  sourceId?: string,
): WearableCleanupSettings {
  return {
    mergeSameSpeaker: true,
    stripFillers: true,
    collapseRepeats: true,
    dropLowQuality: true,
    preserveUtteranceBoundaries:
      sourceId !== undefined && BOUNDARY_PRESERVING_SOURCE_IDS.has(sourceId),
  };
}

export function defaultWearableSourceSettings(
  sourceId?: string,
): WearableSourceSettings {
  return {
    enabled: false,
    memoryMode: "smart",
    sourceTrust: DEFAULT_SOURCE_TRUST,
    autoApproveTrust: DEFAULT_AUTO_APPROVE_TRUST,
    reviewTrust: DEFAULT_REVIEW_TRUST,
    minConfidence: DEFAULT_MIN_CONFIDENCE,
    minImportance: DEFAULT_MIN_IMPORTANCE,
    maxMemoriesPerDay: DEFAULT_MAX_MEMORIES_PER_DAY,
    importNativeMemories: "smart",
    cleanup: defaultWearableCleanupSettings(sourceId),
  };
}

export function defaultWearableFusionConfig(): WearableFusionConfig {
  return {
    enabled: DEFAULT_FUSION_ENABLED,
    proximityGapMs: DEFAULT_FUSION_PROXIMITY_GAP_MS,
    windowToleranceMs: DEFAULT_FUSION_WINDOW_TOLERANCE_MS,
  };
}

export function defaultWearablesConfig(): WearablesConfig {
  return {
    enabled: false,
    redactionEnabled: true,
    redactionPatterns: [],
    offTheRecordEnabled: true,
    offTheRecordMarkers: { start: [], end: [], useBuiltIns: true },
    fillerTokens: [],
    digestEnabled: true,
    autoSyncEnabled: DEFAULT_AUTO_SYNC_ENABLED,
    autoSyncIntervalMinutes: DEFAULT_AUTO_SYNC_INTERVAL_MINUTES,
    autoSyncDays: DEFAULT_AUTO_SYNC_DAYS,
    autoSyncDeepDays: DEFAULT_AUTO_SYNC_DEEP_DAYS,
    corrections: [],
    sources: {},
    fusion: defaultWearableFusionConfig(),
  };
}

function requireObject(
  value: unknown,
  keyPath: string,
): Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(
      `${keyPath} must be an object (got ${JSON.stringify(value)})`,
    );
  }
  return value as Record<string, unknown>;
}

/** Longest accepted off-the-record marker phrase. */
const MAX_MARKER_PHRASE_LENGTH = 128;
/** Longest accepted filler token. */
const MAX_FILLER_TOKEN_LENGTH = 64;

/**
 * Parse an optional array of non-empty phrases. Rejects a non-array, a
 * non-string entry, a blank entry, and an over-long entry — an operator
 * privacy phrase that is silently discarded is the failure this parser
 * exists to prevent (issue #2196).
 */
function parsePhraseList(
  value: unknown,
  keyPath: string,
  maxLength: number,
): string[] {
  if (value === undefined) return [];
  if (!Array.isArray(value)) {
    throw new Error(`${keyPath} must be an array of strings`);
  }
  return value.map((entry, index) => {
    if (typeof entry !== "string" || entry.trim().length === 0) {
      throw new Error(`${keyPath}[${index}] must be a non-empty string`);
    }
    if (entry.length > maxLength) {
      throw new Error(`${keyPath}[${index}] exceeds ${maxLength} characters`);
    }
    return entry.trim();
  });
}

function parseBool(
  value: unknown,
  keyPath: string,
  fallback: boolean,
): boolean {
  if (value === undefined) return fallback;
  const coerced = coerceBool(value);
  if (coerced === undefined) {
    throw new Error(
      `${keyPath} must be a boolean or one of "true"/"false"/"1"/"0"/"yes"/"no"/"on"/"off" (got ${JSON.stringify(value)})`,
    );
  }
  return coerced;
}

function parseEnum<T extends string>(
  value: unknown,
  keyPath: string,
  allowed: readonly T[],
  fallback: T,
): T {
  if (value === undefined) return fallback;
  if (typeof value === "string" && (allowed as readonly string[]).includes(value)) {
    return value as T;
  }
  throw new Error(
    `${keyPath} must be one of ${allowed.map((entry) => `"${entry}"`).join(", ")} (got ${JSON.stringify(value)})`,
  );
}

function parseOptionalString(
  value: unknown,
  keyPath: string,
): string | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new Error(`${keyPath} must be a non-empty string when set`);
  }
  return value.trim();
}

function parseCorrectionRules(
  value: unknown,
  keyPath: string,
): WearableCorrectionRule[] {
  if (value === undefined) return [];
  if (!Array.isArray(value)) {
    throw new Error(`${keyPath} must be an array of correction rules`);
  }
  const rules = value.map((entry, index) => {
    const raw = requireObject(entry, `${keyPath}[${index}]`);
    const rule: WearableCorrectionRule = {
      match: typeof raw.match === "string" ? raw.match : "",
      replace: typeof raw.replace === "string" ? raw.replace : "",
    };
    if (raw.regex !== undefined) {
      rule.regex = parseBool(raw.regex, `${keyPath}[${index}].regex`, false);
    }
    if (raw.caseInsensitive !== undefined) {
      rule.caseInsensitive = parseBool(
        raw.caseInsensitive,
        `${keyPath}[${index}].caseInsensitive`,
        true,
      );
    }
    if (raw.sources !== undefined) {
      if (
        !Array.isArray(raw.sources) ||
        raw.sources.some((source) => typeof source !== "string")
      ) {
        throw new Error(`${keyPath}[${index}].sources must be an array of strings`);
      }
      rule.sources = raw.sources as string[];
    }
    return rule;
  });
  // Compile now so bad rules fail at config load, not mid-sync.
  compileCorrectionRules(rules, keyPath);
  return rules;
}

function parseSourceSettings(
  value: unknown,
  keyPath: string,
  sourceId: string,
): WearableSourceSettings {
  const raw = requireObject(value, keyPath);
  const defaults = defaultWearableSourceSettings(sourceId);

  const minConfidenceRaw = coerceNumber(raw.minConfidence);
  // Out-of-range values reject loudly instead of clamping — silently
  // turning minConfidence 7 into 1 would change the memory gate in a
  // way the operator never asked for (Codex P2 on PR #1458, round 3).
  if (
    raw.minConfidence !== undefined &&
    (minConfidenceRaw === undefined || minConfidenceRaw < 0 || minConfidenceRaw > 1)
  ) {
    throw new Error(
      `${keyPath}.minConfidence must be a number between 0 and 1 (got ${JSON.stringify(raw.minConfidence)})`,
    );
  }
  const minConfidence = minConfidenceRaw ?? defaults.minConfidence;

  const maxPerDayRaw = coerceNumber(raw.maxMemoriesPerDay);
  // Reject non-integers instead of flooring them: 0.5 would floor to 0,
  // and 0 is the documented "disable the cap" value — a fractional typo
  // must not silently remove the cap (Codex P2 on PR #1458).
  if (
    raw.maxMemoriesPerDay !== undefined &&
    (maxPerDayRaw === undefined ||
      !Number.isInteger(maxPerDayRaw) ||
      maxPerDayRaw < 0)
  ) {
    throw new Error(
      `${keyPath}.maxMemoriesPerDay must be a non-negative integer (0, the default, disables the cap); got ${JSON.stringify(raw.maxMemoriesPerDay)}`,
    );
  }
  // 0 is the documented "disable the cap" value — honored here AND in
  // the schema minimum (CLAUDE.md rule 45).
  const maxMemoriesPerDay = maxPerDayRaw ?? defaults.maxMemoriesPerDay;

  const parseUnitInterval = (value: unknown, name: string, fallback: number): number => {
    if (value === undefined) return fallback;
    const coerced = coerceNumber(value);
    if (coerced === undefined || coerced < 0 || coerced > 1) {
      throw new Error(
        `${keyPath}.${name} must be a number between 0 and 1 (got ${JSON.stringify(value)})`,
      );
    }
    return coerced;
  };
  const sourceTrust = parseUnitInterval(raw.sourceTrust, "sourceTrust", defaults.sourceTrust);
  const autoApproveTrust = parseUnitInterval(
    raw.autoApproveTrust,
    "autoApproveTrust",
    defaults.autoApproveTrust,
  );
  const reviewTrust = parseUnitInterval(raw.reviewTrust, "reviewTrust", defaults.reviewTrust);
  if (reviewTrust >= autoApproveTrust) {
    throw new Error(
      `${keyPath}.reviewTrust (${reviewTrust}) must be below autoApproveTrust (${autoApproveTrust})`,
    );
  }

  const rawCleanup =
    raw.cleanup === undefined ? {} : requireObject(raw.cleanup, `${keyPath}.cleanup`);
  const cleanup: WearableCleanupSettings = {
    mergeSameSpeaker: parseBool(
      rawCleanup.mergeSameSpeaker,
      `${keyPath}.cleanup.mergeSameSpeaker`,
      defaults.cleanup.mergeSameSpeaker,
    ),
    stripFillers: parseBool(
      rawCleanup.stripFillers,
      `${keyPath}.cleanup.stripFillers`,
      defaults.cleanup.stripFillers,
    ),
    collapseRepeats: parseBool(
      rawCleanup.collapseRepeats,
      `${keyPath}.cleanup.collapseRepeats`,
      defaults.cleanup.collapseRepeats,
    ),
    dropLowQuality: parseBool(
      rawCleanup.dropLowQuality,
      `${keyPath}.cleanup.dropLowQuality`,
      defaults.cleanup.dropLowQuality,
    ),
    preserveUtteranceBoundaries: parseBool(
      rawCleanup.preserveUtteranceBoundaries,
      `${keyPath}.cleanup.preserveUtteranceBoundaries`,
      // Optional on the type; the per-source default is always concrete.
      defaults.cleanup.preserveUtteranceBoundaries ?? false,
    ),
  };

  return {
    enabled: parseBool(raw.enabled, `${keyPath}.enabled`, false),
    apiKey: parseOptionalString(raw.apiKey, `${keyPath}.apiKey`),
    baseUrl: parseOptionalString(raw.baseUrl, `${keyPath}.baseUrl`),
    appId: parseOptionalString(raw.appId, `${keyPath}.appId`),
    userId: parseOptionalString(raw.userId, `${keyPath}.userId`),
    memoryMode: parseEnum(
      raw.memoryMode,
      `${keyPath}.memoryMode`,
      MEMORY_MODES,
      defaults.memoryMode,
    ),
    sourceTrust,
    autoApproveTrust,
    reviewTrust,
    minConfidence,
    minImportance: parseEnum(
      raw.minImportance,
      `${keyPath}.minImportance`,
      IMPORTANCE_LEVELS,
      defaults.minImportance,
    ),
    maxMemoriesPerDay,
    importNativeMemories: parseEnum(
      raw.importNativeMemories,
      `${keyPath}.importNativeMemories`,
      NATIVE_IMPORT_MODES,
      defaults.importNativeMemories,
    ),
    cleanup,
  };
}

/**
 * Parse the `wearables` config block. `undefined` yields the disabled
 * default config; any present-but-malformed value throws.
 */
function parseFusionSettings(
  value: unknown,
  keyPath: string,
): WearableFusionConfig {
  if (value === undefined) return defaultWearableFusionConfig();
  const raw = requireObject(value, keyPath);
  const defaults = defaultWearableFusionConfig();
  const parsePositiveInt = (
    value: unknown,
    name: string,
    fallback: number,
  ): number => {
    if (value === undefined) return fallback;
    const coerced = coerceNumber(value);
    if (coerced === undefined || !Number.isInteger(coerced) || coerced <= 0) {
      throw new Error(
        `${keyPath}.${name} must be a positive integer (got ${JSON.stringify(value)})`,
      );
    }
    return coerced;
  };
  return {
    enabled: parseBool(raw.enabled, `${keyPath}.enabled`, defaults.enabled),
    proximityGapMs: parsePositiveInt(
      raw.proximityGapMs,
      "proximityGapMs",
      defaults.proximityGapMs,
    ),
    windowToleranceMs: parsePositiveInt(
      raw.windowToleranceMs,
      "windowToleranceMs",
      defaults.windowToleranceMs,
    ),
  };
}

export function parseWearablesConfig(value: unknown): WearablesConfig {
  if (value === undefined) return defaultWearablesConfig();
  const raw = requireObject(value, "wearables");
  const defaults = defaultWearablesConfig();

  const timezone = parseOptionalString(raw.timezone, "wearables.timezone");
  if (timezone !== undefined) {
    try {
      new Intl.DateTimeFormat("en-US", { timeZone: timezone });
    } catch {
      throw new Error(
        `wearables.timezone must be a valid IANA timezone identifier (got ${JSON.stringify(timezone)})`,
      );
    }
  }

  let redactionPatterns: string[] = defaults.redactionPatterns;
  if (raw.redactionPatterns !== undefined) {
    if (
      !Array.isArray(raw.redactionPatterns) ||
      raw.redactionPatterns.some((pattern) => typeof pattern !== "string")
    ) {
      throw new Error("wearables.redactionPatterns must be an array of strings");
    }
    redactionPatterns = raw.redactionPatterns as string[];
    // Compile now so invalid regexes fail at config load.
    compileRedactionPatterns(redactionPatterns);
  }

  const offTheRecordEnabled = parseBool(
    raw.offTheRecordEnabled,
    "wearables.offTheRecordEnabled",
    defaults.offTheRecordEnabled,
  );
  const rawMarkers =
    raw.offTheRecordMarkers === undefined
      ? {}
      : requireObject(raw.offTheRecordMarkers, "wearables.offTheRecordMarkers");
  // A typo such as `starts:` would otherwise be dropped without a word,
  // and the operator would believe a private span is protected. Core and
  // standalone callers never see OpenClaw's JSON schema, so the check
  // belongs here. Keys are compared literally so the config-contract
  // extractor can still enumerate this parser's surface.
  const {
    start: rawMarkerStart,
    end: rawMarkerEnd,
    useBuiltIns: rawMarkerUseBuiltIns,
    ...unknownMarkerKeys
  } = rawMarkers;
  const unknownMarkerNames = Object.keys(unknownMarkerKeys);
  if (unknownMarkerNames.length > 0) {
    throw new Error(
      `wearables.offTheRecordMarkers has unknown key(s) ${unknownMarkerNames.sort().join(", ")} — valid keys are start, end, useBuiltIns`,
    );
  }
  const offTheRecordMarkers: OffTheRecordMarkerSettings = {
    start: parsePhraseList(
      rawMarkerStart,
      "wearables.offTheRecordMarkers.start",
      MAX_MARKER_PHRASE_LENGTH,
    ),
    end: parsePhraseList(
      rawMarkerEnd,
      "wearables.offTheRecordMarkers.end",
      MAX_MARKER_PHRASE_LENGTH,
    ),
    useBuiltIns: parseBool(
      rawMarkerUseBuiltIns,
      "wearables.offTheRecordMarkers.useBuiltIns",
      defaults.offTheRecordMarkers.useBuiltIns,
    ),
  };
  // A silent no-op is the exact failure this feature exists to remove
  // (issue #2196): turning the built-ins off without supplying a start
  // phrase would leave the gate on and matching nothing.
  if (
    offTheRecordEnabled &&
    !offTheRecordMarkers.useBuiltIns &&
    offTheRecordMarkers.start.length === 0
  ) {
    throw new Error(
      "wearables.offTheRecordMarkers.useBuiltIns is false but no start phrase is configured — add wearables.offTheRecordMarkers.start, or set wearables.offTheRecordEnabled to false",
    );
  }

  const fillerTokens = parsePhraseList(
    raw.fillerTokens,
    "wearables.fillerTokens",
    MAX_FILLER_TOKEN_LENGTH,
  );

  const parseBoundedInt = (
    value: unknown,
    name: string,
    fallback: number,
    min: number,
    max: number,
  ): number => {
    if (value === undefined) return fallback;
    const coerced = coerceNumber(value);
    if (
      coerced === undefined ||
      !Number.isInteger(coerced) ||
      coerced < min ||
      coerced > max
    ) {
      throw new Error(
        `${name} must be an integer between ${min} and ${max}; got ${JSON.stringify(value)}`,
      );
    }
    return coerced;
  };
  const autoSyncIntervalMinutes = parseBoundedInt(
    raw.autoSyncIntervalMinutes,
    "wearables.autoSyncIntervalMinutes",
    defaults.autoSyncIntervalMinutes,
    1,
    MAX_AUTO_SYNC_INTERVAL_MINUTES,
  );
  const autoSyncDays = parseBoundedInt(
    raw.autoSyncDays,
    "wearables.autoSyncDays",
    defaults.autoSyncDays,
    1,
    MAX_AUTO_SYNC_WINDOW_DAYS,
  );
  const autoSyncDeepDays = parseBoundedInt(
    raw.autoSyncDeepDays,
    "wearables.autoSyncDeepDays",
    defaults.autoSyncDeepDays,
    0,
    MAX_AUTO_SYNC_WINDOW_DAYS,
  );
  // A deep window narrower than the every-tick window would make the
  // "deep" pass fetch LESS than a normal tick — reject the confusion
  // instead of silently honoring it (0 disables the deep pass).
  if (autoSyncDeepDays !== 0 && autoSyncDeepDays < autoSyncDays) {
    throw new Error(
      `wearables.autoSyncDeepDays must be 0 (disabled) or >= wearables.autoSyncDays (${autoSyncDays}); got ${autoSyncDeepDays}`,
    );
  }

  const sources: Record<string, WearableSourceSettings> = {};
  if (raw.sources !== undefined) {
    const rawSources = requireObject(raw.sources, "wearables.sources");
    for (const [sourceId, sourceValue] of Object.entries(rawSources)) {
      if (!/^[a-z][a-z0-9-]{0,63}$/.test(sourceId)) {
        throw new Error(
          `wearables.sources keys must be lowercase source ids (letters, digits, dashes); got ${JSON.stringify(sourceId)}`,
        );
      }
      sources[sourceId] = parseSourceSettings(
        sourceValue,
        `wearables.sources.${sourceId}`,
        sourceId,
      );
    }
  }

  return {
    enabled: parseBool(raw.enabled, "wearables.enabled", defaults.enabled),
    ...(timezone !== undefined ? { timezone } : {}),
    redactionEnabled: parseBool(
      raw.redactionEnabled,
      "wearables.redactionEnabled",
      defaults.redactionEnabled,
    ),
    redactionPatterns,
    offTheRecordEnabled,
    offTheRecordMarkers,
    fillerTokens,
    digestEnabled: parseBool(
      raw.digestEnabled,
      "wearables.digestEnabled",
      defaults.digestEnabled,
    ),
    autoSyncEnabled: parseBool(
      raw.autoSyncEnabled,
      "wearables.autoSyncEnabled",
      defaults.autoSyncEnabled,
    ),
    autoSyncIntervalMinutes,
    autoSyncDays,
    autoSyncDeepDays,
    fusion: parseFusionSettings(raw.fusion, "wearables.fusion"),
    corrections: parseCorrectionRules(raw.corrections, "wearables.corrections"),
    sources,
  };
}

import { parseActivityConfig } from "../activity/config.js";
import { parseMeetingsConfig } from "../meetings/config.js";
import { parseProvenanceConfig } from "../provenance.js";

/** Parse capture-adjacent config blocks without location (#2044). */
export function parseCaptureCompanionConfigs(cfg: Record<string, unknown>) {
  return {
    activity: parseActivityConfig(cfg.activity),
    meetings: parseMeetingsConfig(cfg.meetings),
    provenance: parseProvenanceConfig(cfg.provenance),
  };
}

import { coerceBooleanLike, coerceNumber } from "../connectors/coerce.js";
import { assertValidTimezone } from "../activity/digest.js";
import type { LocationConfig, LocationSourceConfig, LocationTaggingConfig } from "./types.js";

const PROVIDER_ID_PATTERN = /^[a-z0-9][a-z0-9-]*$/;

/** The inert default: disabled, UTC days, one day per run, no sources, no coordinates. */
export function defaultLocationConfig(): LocationConfig {
  return {
    enabled: false,
    timezone: "UTC",
    syncDays: 1,
    retainCoordinates: false,
    minimumOverlapSeconds: 300,
    minimumConfidence: 0.7,
    tagging: { enabled: false, backfillEnabled: false },
    sources: [],
  };
}

function asRecord(value: unknown, name: string): Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new TypeError(`${name} must be an object`);
  }
  return value as Record<string, unknown>;
}

function optionalNonEmptyString(value: unknown, name: string): string | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "string" || value.length === 0) throw new TypeError(`${name} must be a non-empty string`);
  return value;
}

function parseLocationSource(value: unknown): LocationSourceConfig {
  const raw = asRecord(value, "location source");
  const id = optionalNonEmptyString(raw.id, "location source id");
  if (id === undefined) {
    throw new TypeError("location source requires id");
  }
  if (!PROVIDER_ID_PATTERN.test(id)) {
    throw new RangeError(
      `location source id must be a lowercase kebab string (a-z, 0-9, hyphens): got "${id}"`,
    );
  }
  const enabledValue = coerceBooleanLike(raw.enabled, "location source enabled");
  if (raw.enabled !== undefined && enabledValue === undefined) {
    throw new TypeError(`location source '${id}' enabled must be a boolean`);
  }
  return { id, enabled: enabledValue ?? true };
}

/**
 * Parse the unified `location.*` block. `enabled` gates everything and
 * requires at least one source; a source's own `enabled` gates that source
 * only. `retainCoordinates` defaults to `false` — coordinates are privacy
 * data and are dropped everywhere unless explicitly retained.
 */
export function parseLocationConfig(raw: unknown): LocationConfig {
  const defaults = defaultLocationConfig();
  if (raw === undefined || raw === null) {
    return { ...defaults };
  }
  const config = asRecord(raw, "location");
  const enabledValue = coerceBooleanLike(config.enabled, "location.enabled");
  if (config.enabled !== undefined && enabledValue === undefined) {
    throw new TypeError("location.enabled must be a boolean");
  }
  const enabled = enabledValue ?? false;

  const timezone = optionalNonEmptyString(config.timezone, "location.timezone") ?? "UTC";
  // Validate the IANA zone at parse so a typo fails at config load, not
  // mid-sync after some sources may already have advanced their state.
  assertValidTimezone(timezone);

  const syncDaysValue = coerceNumber(config.syncDays, "location.syncDays");
  if (config.syncDays !== undefined && syncDaysValue === undefined) {
    throw new TypeError("location.syncDays must be a finite number");
  }
  const syncDays = syncDaysValue ?? 1;
  if (!Number.isInteger(syncDays) || syncDays < 1 || syncDays > 90) {
    throw new RangeError("location.syncDays must be an integer from 1 to 90");
  }

  const retainCoordinatesValue = coerceBooleanLike(config.retainCoordinates, "location.retainCoordinates");
  if (config.retainCoordinates !== undefined && retainCoordinatesValue === undefined) {
    throw new TypeError("location.retainCoordinates must be a boolean");
  }
  const retainCoordinates = retainCoordinatesValue ?? false;

  if (config.sources !== undefined && !Array.isArray(config.sources)) {
    throw new TypeError("location.sources must be an array");
  }
  const sources = (config.sources ?? []).map(parseLocationSource);
  // Day payloads and sync state are keyed on source id; two sources sharing
  // an id would overwrite each other's state. Reject the collision at parse.
  const ids = new Set<string>();
  for (const source of sources) {
    if (ids.has(source.id)) {
      throw new RangeError(`location source id must be unique: ${source.id}`);
    }
    ids.add(source.id);
  }
  if (enabled && sources.length === 0) {
    throw new RangeError("location.enabled requires at least one source");
  }

  const overlapValue = coerceNumber(config.minimumOverlapSeconds, "location.minimumOverlapSeconds");
  if (config.minimumOverlapSeconds !== undefined && overlapValue === undefined) {
    throw new TypeError("location.minimumOverlapSeconds must be a finite number");
  }
  const minimumOverlapSeconds = overlapValue ?? 300;
  if (!Number.isInteger(minimumOverlapSeconds) || minimumOverlapSeconds < 0) {
    throw new RangeError("location.minimumOverlapSeconds must be an integer >= 0 (0 disables the floor)");
  }

  const confidenceValue = coerceNumber(config.minimumConfidence, "location.minimumConfidence");
  if (config.minimumConfidence !== undefined && confidenceValue === undefined) {
    throw new TypeError("location.minimumConfidence must be a finite number");
  }
  const minimumConfidence = confidenceValue ?? 0.7;
  if (minimumConfidence < 0 || minimumConfidence > 1) {
    throw new RangeError("location.minimumConfidence must be within [0, 1]");
  }

  const tagging = parseLocationTagging(config.tagging, enabled);

  return { enabled, timezone, syncDays, retainCoordinates, minimumOverlapSeconds, minimumConfidence, tagging, sources };
}

function parseLocationTagging(raw: unknown, masterEnabled: boolean): LocationTaggingConfig {
  if (raw === undefined || raw === null) return { enabled: false, backfillEnabled: false };
  const tagging = asRecord(raw, "location.tagging");
  const enabledValue = coerceBooleanLike(tagging.enabled, "location.tagging.enabled");
  if (tagging.enabled !== undefined && enabledValue === undefined) {
    throw new TypeError("location.tagging.enabled must be a boolean");
  }
  const backfillValue = coerceBooleanLike(tagging.backfillEnabled, "location.tagging.backfillEnabled");
  if (tagging.backfillEnabled !== undefined && backfillValue === undefined) {
    throw new TypeError("location.tagging.backfillEnabled must be a boolean");
  }
  const backfillEnabled = backfillValue ?? false;
  if (enabledValue === true && !masterEnabled) {
    throw new RangeError("location.tagging.enabled requires location.enabled");
  }
  if (backfillEnabled && !(enabledValue ?? false)) {
    throw new RangeError("location.tagging.backfillEnabled requires location.tagging.enabled");
  }
  return { enabled: enabledValue ?? false, backfillEnabled };
}

/**
 * OKF conformance config (issue #1946). Parsed off the raw `okf` config
 * block; mirrors the meetings/wearables parse-module seam so config.ts
 * stays a thin caller.
 */
import { coerceBooleanLike } from "../connectors/coerce.js";

export interface OkfConfig {
  /** Emit inert OKF `type` metadata on writes and gate the sweep (default true). */
  conformanceEnabled: boolean;
  /** Opt-in governance sweep that backfills `type` on legacy files (default false). */
  sweepEnabled: boolean;
  /** Generate OKF index.md files in the live store (default false). */
  indexFilesEnabled: boolean;
}

export const DEFAULT_OKF_CONFIG: OkfConfig = Object.freeze({
  conformanceEnabled: true,
  sweepEnabled: false,
  indexFilesEnabled: false,
});

export function parseOkfConfig(raw: unknown): OkfConfig {
  if (raw === undefined || raw === null) return { ...DEFAULT_OKF_CONFIG };
  if (typeof raw !== "object" || Array.isArray(raw)) {
    throw new Error(
      `okf must be an object (got ${JSON.stringify(raw)}). Use okf: { conformanceEnabled: false } to opt out; omit the key for defaults.`,
    );
  }
  const record = raw as Record<string, unknown>;
  const conformance = coerceBooleanLike(record.conformanceEnabled, "okf.conformanceEnabled");
  const sweep = coerceBooleanLike(record.sweepEnabled, "okf.sweepEnabled");
  const indexFiles = coerceBooleanLike(record.indexFilesEnabled, "okf.indexFilesEnabled");
  return {
    conformanceEnabled: conformance ?? DEFAULT_OKF_CONFIG.conformanceEnabled,
    sweepEnabled: sweep ?? DEFAULT_OKF_CONFIG.sweepEnabled,
    indexFilesEnabled: indexFiles ?? DEFAULT_OKF_CONFIG.indexFilesEnabled,
  };
}

/**
 * Bounded JSONL state configuration (issue #1910).
 *
 * Extracted from `config.ts`/`types.ts` so the god-file line-count ratchets
 * (issue #1995) do not grow: `PluginConfig` extends the interface below and
 * `parseConfig` spreads `parseBoundedJsonlStateConfig`. No behavior change —
 * the knobs, defaults, and coercion rules are identical to the inline forms.
 */

/** Knobs that bound the unbounded JSONL state files (issue #1910). */
export interface BoundedJsonlStateConfig {
  /**
   * Auto-compact `state/memory-lifecycle-ledger.jsonl` when it exceeds this many
   * bytes, triggered off the debounced maintenance path. `0` disables. Default
   * 64MB.
   */
  memoryLifecycleLedgerCompactBytes: number;
  /**
   * Minimum interval between auto-compactions of the lifecycle ledger, so a
   * heavy rebuild cannot run back-to-back. Floored at 60s. Default 6h.
   */
  memoryLifecycleLedgerCompactMinIntervalMs: number;
  /**
   * Rotate `state/recall_impressions.jsonl` to `.1..N` when it exceeds this many
   * bytes. `0` disables. Default 32MB.
   */
  recallImpressionsRotateBytes: number;
  /**
   * Number of rotated recall-impression archives to keep (`.1 .. .N`). Floored
   * at 1 when rotation is enabled. Default 5.
   */
  recallImpressionsRotateKeep: number;
}

/** Integer coercion contract shared with `config.ts` (`parseIntegerAtLeast`). */
type IntegerParser = (value: unknown, fallback: number, min: number, keyName: string) => number;

/**
 * Upper bound for `recallImpressionsRotateKeep`. Each retained slot costs one
 * rename under the held cross-process impressions lock on every rotation, so an
 * accidentally huge value (a `1000000` typo) would stall recall recording and
 * block other writers. 1000 archives is already far past any real retention
 * need; a larger request is REJECTED before it reaches the rotation loop (#2033).
 */
export const RECALL_IMPRESSIONS_ROTATE_KEEP_MAX = 1000;

/**
 * Parse the bounded-state knobs. Numeric knobs accept CLI/overlay string forms
 * (Gotcha #28) via `coerceNumber`, then require an integer >= min. A
 * present-but-malformed or fractional value is REJECTED (throws) rather than
 * silently taking the default; only an absent value falls back. `0` survives
 * when `min` is 0, so the documented disable stays effective on every surface
 * (byte thresholds floor at 0, the min-interval at 60s, and the keep count at 1
 * so rotation always retains at least one archive).
 */
export function parseBoundedJsonlStateConfig(
  cfg: Record<string, unknown>,
  parseIntegerAtLeast: IntegerParser,
): BoundedJsonlStateConfig {
  const recallImpressionsRotateKeep = parseIntegerAtLeast(
    cfg.recallImpressionsRotateKeep,
    5,
    1,
    "recallImpressionsRotateKeep",
  );
  if (recallImpressionsRotateKeep > RECALL_IMPRESSIONS_ROTATE_KEEP_MAX) {
    throw new Error(
      `recallImpressionsRotateKeep must be an integer between 1 and `
      + `${RECALL_IMPRESSIONS_ROTATE_KEEP_MAX}; got ${JSON.stringify(cfg.recallImpressionsRotateKeep)}`,
    );
  }
  return {
    memoryLifecycleLedgerCompactBytes: parseIntegerAtLeast(
      cfg.memoryLifecycleLedgerCompactBytes,
      64 * 1024 * 1024,
      0,
      "memoryLifecycleLedgerCompactBytes",
    ),
    memoryLifecycleLedgerCompactMinIntervalMs: parseIntegerAtLeast(
      cfg.memoryLifecycleLedgerCompactMinIntervalMs,
      6 * 60 * 60 * 1000,
      60_000,
      "memoryLifecycleLedgerCompactMinIntervalMs",
    ),
    recallImpressionsRotateBytes: parseIntegerAtLeast(
      cfg.recallImpressionsRotateBytes,
      32 * 1024 * 1024,
      0,
      "recallImpressionsRotateBytes",
    ),
    recallImpressionsRotateKeep,
  };
}

/**
 * Scheduled projection-rebuild knobs (issue #2119, heap guard).
 *
 * Extracted from `config.ts` / `types.ts` so those god-file ceilings do not
 * grow. `PluginConfig` extends the interface and `parseConfig` spreads
 * {@link parseProjectionRebuildScheduleConfig}.
 */

import { coerceBooleanLike, coerceNumber } from "./connectors/coerce.js";

/** Knobs for the maintenance-scheduled memory-projection rebuild. */
export interface ProjectionRebuildScheduleConfig {
  /**
   * Enable the maintenance-scheduled rebuild of `state/memory-projection.sqlite`.
   * The projection is otherwise rebuild-only (manual CLI / tests), so it rots as
   * the lifecycle ledger grows and timeline/browse consumers silently regress to
   * full-corpus fallback scans. Default true — mirrors lifecycle-ledger
   * auto-compaction, which is likewise enabled-by-default to keep a state file
   * healthy. Set false to disable (operators can still cron the CLI rebuild).
   */
  projectionRebuildEnabled: boolean;
  /**
   * Minimum interval between scheduled projection rebuilds. A rebuild is skipped
   * when the projection's `rebuiltAt` meta is younger than this, so a burst of
   * maintenance requests cannot fan into back-to-back rebuilds. Floored at 60s.
   * Default 6h (matches memoryLifecycleLedgerCompactMinIntervalMs).
   */
  projectionRebuildIntervalMs: number;
  /**
   * Postpone a scheduled full-corpus projection rebuild when
   * `v8.getHeapStatistics().used_heap_size / heap_size_limit` exceeds this
   * ratio. Finite number in `(0, 1]`. Default `0.6`. `1` disables the guard
   * (usage cannot exceed the limit). A postponed rebuild uses the failure
   * backoff and does not start the multi-GB allocation.
   */
  projectionRebuildHeapUsageLimit: number;
}

/** Integer coercion contract shared with `config.ts` (`parseIntegerAtLeast`). */
type IntegerParser = (value: unknown, fallback: number, min: number, keyName: string) => number;

/** Default heap-usage ratio above which a scheduled full-corpus rebuild waits. */
export const DEFAULT_PROJECTION_REBUILD_HEAP_USAGE_LIMIT = 0.6;

/**
 * Parse `projectionRebuildHeapUsageLimit`. Absent values take the default.
 * A present value must be a finite number in `(0, 1]` (numeric strings
 * coerced). `0` is rejected: it would postpone every rebuild.
 */
export function parseProjectionRebuildHeapUsageLimit(value: unknown): number {
  if (value === undefined || value === null) return DEFAULT_PROJECTION_REBUILD_HEAP_USAGE_LIMIT;
  const coerced = coerceNumber(value);
  if (coerced === undefined || !Number.isFinite(coerced) || coerced <= 0 || coerced > 1) {
    throw new Error(
      `projectionRebuildHeapUsageLimit must be a finite number in (0, 1]; got ${JSON.stringify(value)}`,
    );
  }
  return coerced;
}

/**
 * Parse the scheduled projection-rebuild knobs. Boolean coercion follows
 * gotcha #36 (`"false"` is false). The interval uses the shared integer
 * parser (strings coerced, non-integers and sub-60s values rejected).
 */
export function parseProjectionRebuildScheduleConfig(
  cfg: Record<string, unknown>,
  parseIntegerAtLeast: IntegerParser,
): ProjectionRebuildScheduleConfig {
  return {
    projectionRebuildEnabled: coerceBooleanLike(cfg.projectionRebuildEnabled) ?? true,
    projectionRebuildIntervalMs: parseIntegerAtLeast(
      cfg.projectionRebuildIntervalMs,
      6 * 60 * 60 * 1000,
      60_000,
      "projectionRebuildIntervalMs",
    ),
    projectionRebuildHeapUsageLimit: parseProjectionRebuildHeapUsageLimit(
      cfg.projectionRebuildHeapUsageLimit,
    ),
  };
}

/**
 * Track A (issue #1548 PR 1) — parse the `codingKnowledge` config block.
 *
 * Lives in `coding/` (not in `config.ts`) so adding a feature config block
 * does not grow the watchlisted `config.ts` past its ratchet baseline. The
 * function is a pure helper: it reads from the raw `cfg.codingKnowledge`
 * sub-object, applies defaults from `CODING_KNOWLEDGE_DEFAULTS`, validates
 * the structural-provider enum, and returns the populated
 * `CodingKnowledgeConfig`.
 *
 * Parse rules (CLAUDE.md gotcha 36, rule 30, rule 48):
 *  - booleans are coerced at the parse boundary so CLI strings like
 *    `--config codingKnowledge.enabled=false` arrive as `false`, not truthy.
 *  - unknown structural-provider values are rejected listing the valid
 *    options (rule 51 — silent defaulting is a contract lie).
 *  - `structuralProvider` defaults to `"none"` (rule 48 — least-privileged:
 *    spawning subprocesses is an explicit operator choice).
 *
 * Env overrides follow the REMNIC_* + ENGRAM_* fallback already used elsewhere
 * in `config.ts` (#1427 family). Each individual switch is `codingKnowledge.*` —
 * the existing `ENGRAM_*` env vars from earlier releases do not pair them up.
 */

import type { CodingContext, CodingGraphLspConfig, CodingKnowledgeConfig } from "../types.js";
import { TIER_1_LANGUAGES } from "./coding-graph-types.js";
import { coerceBool } from "../connectors/coerce.js";

export const CODING_KNOWLEDGE_DEFAULTS = Object.freeze({
  enabled: false,
  decisionRecords: true,
  architectureCard: true,
  sessionDelta: true,
  architectureCardLlmSummary: false,
  structuralProvider: "none",
  structuralProviderCommand: "",
  codegraphTools: false,
  codegraphDbDir: "",
  // `lsp` is excluded: it is an optional structured sub-config (issue #1917)
  // with no flat boolean/string default; the parser returns `undefined` when
  // absent (LSP off — rule 48 explicit opt-in).
} satisfies Record<Exclude<keyof CodingKnowledgeConfig, "lsp">, boolean | string>);

const VALID_STRUCTURAL_PROVIDERS = ["none", "subprocess", "native"] as const;
type StructuralProvider = CodingKnowledgeConfig["structuralProvider"];

/**
 * Parse the `codingKnowledge` sub-object into a fully-populated
 * `CodingKnowledgeConfig`. Returns the documented defaults when the
 * sub-object is missing, null, not an object, or has unknown shape.
 *
 * Throws when an explicit `structuralProvider` value is not one of the
 * declared enum values (rule 51 — listing valid options in the error).
 */
export function parseCodingKnowledgeConfig(raw: unknown): CodingKnowledgeConfig {
  const record =
    raw && typeof raw === "object" && !Array.isArray(raw)
      ? (raw as Record<string, unknown>)
      : {};

  const structuralProvider = readStructuralProvider(record.structuralProvider);
  return {
    enabled: readStrictBool(record.enabled, "enabled", /* default */ false),
    decisionRecords: readStrictBool(record.decisionRecords, "decisionRecords", /* default */ true),
    architectureCard: readStrictBool(record.architectureCard, "architectureCard", /* default */ true),
    sessionDelta: readStrictBool(record.sessionDelta, "sessionDelta", /* default */ true),
    architectureCardLlmSummary: readStrictBool(record.architectureCardLlmSummary, "architectureCardLlmSummary", /* default */ false),
    structuralProvider,
    structuralProviderCommand:
      typeof record.structuralProviderCommand === "string"
        ? record.structuralProviderCommand.trim()
        : "",
    codegraphTools: readStrictBool(record.codegraphTools, "codegraphTools", /* default */ false),
    codegraphDbDir:
      typeof record.codegraphDbDir === "string"
        ? record.codegraphDbDir.trim()
        : "",
    // `lsp` is spread conditionally so an absent key stays ABSENT — an own
    // `lsp: undefined` property would change the pinned defaults shape
    // (config.test.ts) and leak a new key into serialized configs.
    ...readLspField(record.lsp),
  };
}

// ──────────────────────────────────────────────────────────────────────────
// Shared surface gates (rule 39: ONE predicate pair, identical on every
// surface — issue #2478 dedupe). Each Track A surface used to carry its own
// copy of this logic; they all resolve here now. The booleans are already
// strict-coerced by parseCodingKnowledgeConfig, so `=== true` is safe here.
// ──────────────────────────────────────────────────────────────────────────

/** Boolean feature switches governed by the master `codingKnowledge.enabled` gate. */
export type CodingKnowledgeFeatureFlag = "decisionRecords" | "architectureCard" | "sessionDelta";

/**
 * Config-only visibility gate — used by the MCP constructor to decide
 * whether a coding tool is advertised in `tools/list`. True only when the
 * master gate AND the feature switch are both on.
 */
export function isCodingKnowledgeFeatureVisible(
  config: CodingKnowledgeConfig,
  feature: CodingKnowledgeFeatureFlag,
): boolean {
  return config.enabled === true && config[feature] === true;
}

/**
 * Full call-time gate: visibility PLUS an attached coding context
 * (project/branch-scoped session). Handlers check this before dispatch.
 */
export function isCodingKnowledgeFeatureEnabled(
  config: CodingKnowledgeConfig,
  feature: CodingKnowledgeFeatureFlag,
  codingContext: CodingContext | null | undefined,
): boolean {
  return isCodingKnowledgeFeatureVisible(config, feature) && codingContext != null;
}

/**
 * Read the optional `codingKnowledge.lsp` sub-object. Absent → empty
 * spread (no own key). Present-but-malformed (string/number/array) is
 * REJECTED, consistent with `readStrictBool`'s posture — a typo like
 * `"lsp": true` must alert the operator, not silently disable Phase B.
 */
function readLspField(raw: unknown): { lsp?: CodingGraphLspConfig } {
  if (raw === undefined || raw === null) return {};
  if (typeof raw !== "object" || Array.isArray(raw)) {
    throw new Error(
      `codingKnowledge.lsp must be an object ({ enabled, servers?, timeoutMs?, maxRequestsPerRun? }); got ${JSON.stringify(raw)}`,
    );
  }
  return { lsp: parseLspConfig(raw as Record<string, unknown>) };
}

const STRICT_BOOL_ACCEPTED = "true/false/1/0/yes/no/on/off";

/**
 * Strict boolean parse for feature-gate config values.
 *  - `undefined` falls back to `defaultValue` (the key was simply not
 *    supplied).
 *  - `true`/`false` (native) and the boolean-like strings listed in
 *    `STRICT_BOOL_ACCEPTED` are honored (rule 36 — CLI string parity).
 *  - Any other shape, including misspelled strings like `"flase"`,
 *    numbers outside `{0, 1}`, objects, arrays — is REJECTED with an
 *    error listing the valid inputs (rule 51). Silent defaulting on
 *    malformed operator input is a contract lie.
 */
export function readStrictBool(
  value: unknown,
  keyName: string,
  defaultValue: boolean,
): boolean {
  if (value === undefined) return defaultValue;
  const coerced = coerceBool(value);
  if (coerced === undefined) {
    throw new Error(
      `codingKnowledge.${keyName} must be a boolean or one of ${STRICT_BOOL_ACCEPTED}; ` +
        `got ${JSON.stringify(value)}.`,
    );
  }
  return coerced;
}

function readStructuralProvider(raw: unknown): StructuralProvider {
  if (raw === undefined) return "none";
  if (typeof raw !== "string") {
    throw new Error(
      `codingKnowledge.structuralProvider must be a string (` +
        `${VALID_STRUCTURAL_PROVIDERS.join(", ")}); got ${JSON.stringify(raw)}.`,
    );
  }
  if (raw === "none" || raw === "subprocess" || raw === "native") return raw;
  throw new Error(
    `codingKnowledge.structuralProvider must be one of ` +
      `${VALID_STRUCTURAL_PROVIDERS.join(", ")}; got ${JSON.stringify(raw)}.`,
  );
}

/**
 * Parse the `codingKnowledge.lsp` sub-object (issue #1917). Returns
 * `{ enabled: false }` when absent or malformed — LSP is opt-in.
 */
function parseLspConfig(raw: Record<string, unknown>): CodingGraphLspConfig {
  const enabled = readStrictBool(raw.enabled, "lsp.enabled", false);
  if (!enabled) return { enabled: false };

  // Server overrides are validated STRICTLY (rule 51): a malformed entry
  // or a misspelled language key must not silently fall through to the
  // built-in default server — the operator configured an override for a
  // reason. Keys validate against TIER_1_LANGUAGES (core owns the tier-1
  // list in coding-graph-types.ts, so there is no drift risk).
  const servers: CodingGraphLspConfig["servers"] = {};
  if (raw.servers !== undefined && raw.servers !== null) {
    if (typeof raw.servers !== "object" || Array.isArray(raw.servers)) {
      throw new Error(
        `codingKnowledge.lsp.servers must be an object mapping language ids to { command, args? }; got ${JSON.stringify(raw.servers)}.`,
      );
    }
    for (const [lang, def] of Object.entries(raw.servers as Record<string, unknown>)) {
      if (!(TIER_1_LANGUAGES as readonly string[]).includes(lang)) {
        throw new Error(
          `codingKnowledge.lsp.servers has unknown language key ${JSON.stringify(lang)}; valid keys: ${TIER_1_LANGUAGES.join(", ")}.`,
        );
      }
      if (!def || typeof def !== "object" || Array.isArray(def)) {
        throw new Error(
          `codingKnowledge.lsp.servers.${lang} must be an object ({ command, args? }); got ${JSON.stringify(def)}.`,
        );
      }
      const d = def as Record<string, unknown>;
      if (typeof d.command !== "string" || d.command.trim().length === 0) {
        throw new Error(
          `codingKnowledge.lsp.servers.${lang}.command must be a non-empty string; got ${JSON.stringify(d.command)}.`,
        );
      }
      if (d.args !== undefined && (!Array.isArray(d.args) || !d.args.every((a) => typeof a === "string"))) {
        throw new Error(
          `codingKnowledge.lsp.servers.${lang}.args must be an array of strings; got ${JSON.stringify(d.args)}.`,
        );
      }
      servers[lang] = {
        command: d.command.trim(),
        ...(Array.isArray(d.args) ? { args: d.args as string[] } : {}),
      };
    }
  }

  const timeoutMs = readPositiveInt(raw.timeoutMs, "lsp.timeoutMs", 3_000, 30_000);
  const maxRequestsPerRun = readPositiveInt(raw.maxRequestsPerRun, "lsp.maxRequestsPerRun", 500, 5_000);

  return { enabled: true, ...(Object.keys(servers).length > 0 ? { servers } : {}), timeoutMs, maxRequestsPerRun };
}

/**
 * Strict positive-integer parse for LSP numeric knobs (rule 51 + CLI
 * string parity, pattern 17). `undefined` falls back to the default;
 * strings coerce via Number() (CLI values arrive as strings); anything
 * non-integer, < 1 (0 is NOT a disable value here — set lsp.enabled:false
 * to disable), or > max is REJECTED instead of silently replaced.
 */
function readPositiveInt(value: unknown, keyName: string, defaultValue: number, max: number): number {
  if (value === undefined) return defaultValue;
  const coerced = typeof value === "string" && value.trim().length > 0 ? Number(value) : value;
  if (typeof coerced !== "number" || !Number.isFinite(coerced) || !Number.isInteger(coerced) || coerced < 1 || coerced > max) {
    throw new Error(
      `codingKnowledge.${keyName} must be an integer in [1, ${max}]; got ${JSON.stringify(value)}. ` +
        `To disable LSP resolution set codingKnowledge.lsp.enabled to false.`,
    );
  }
  return coerced;
}

/**
 * Action-site failure gate (issue #2382, slice 1 — core contract).
 *
 * The H6 study (#1963) measured that a failure memory delivered in the prompt
 * preamble barely changes behaviour, while the same memory delivered at the
 * moment the agent proposes the matched action removes the repeated failure.
 * This module productionises that delivery point: `ActionGateService` wraps the
 * experimental `PreActionFailureGate` primitive, adds failure-class memory
 * candidates, a per-turn budget, cross-channel suppression, and telemetry.
 *
 * Scope, per the study's honest limit: the gate removes a known failure mode.
 * It does not improve task completion. It is advisory only — it never blocks an
 * action, never outruns its deadline, and fails open on every error path.
 */
import type { ActionIntent, ActionStrategyId } from "../causal-trajectory.js";
import { coerceBool, coerceNumber } from "../connectors/coerce.js";
import type { CodingContext, MemoryFile } from "../types.js";
import {
  PRE_ACTION_GATE_DEFAULT_TIMEOUT_MS,
  type PreActionFailureGate,
  normalizeActionIntent,
  sanitizePayloadString,
} from "./pre-action-gate.js";

export const ACTION_GATE_DEFAULT_MAX_ADVISORIES_PER_TURN = 3;
/** Bound on a single advisory payload, above the primitive's citation bound. */
const MAX_ADVISORY_CHARS = 400;
/** Bounded lexical matching: terms considered from one proposed action. */
const MAX_ACTION_TERMS = 24;
const MIN_TERM_CHARS = 3;
/** Fraction of action terms a failure memory must mention to be a candidate. */
const MIN_TERM_OVERLAP_RATIO = 0.6;
/** Sessions tracked for suppression before the oldest is evicted. */
const MAX_TRACKED_SESSIONS = 200;
/** Memory ids remembered per session for cross-channel suppression. */
const MAX_TRACKED_IDS_PER_SESSION = 200;

export interface ActionGateConfig {
  /**
   * Master gate. Default `false`: when disabled no lookup, no matching, and no
   * suppression bookkeeping runs on any path.
   */
  enabled: boolean;
  /** Hard latency cap for a whole gate evaluation. Overrun fails open. */
  timeoutMs: number;
  /** Advisories injected per turn. `0` disables injection and all lookups. */
  maxAdvisoriesPerTurn: number;
}

export const ACTION_GATE_DEFAULTS: ActionGateConfig = {
  enabled: false,
  timeoutMs: PRE_ACTION_GATE_DEFAULT_TIMEOUT_MS,
  maxAdvisoriesPerTurn: ACTION_GATE_DEFAULT_MAX_ADVISORIES_PER_TURN,
};

export function parseActionGateConfig(raw: unknown): ActionGateConfig {
  if (raw !== undefined && (raw === null || typeof raw !== "object" || Array.isArray(raw))) {
    throw new Error(
      `actionGate must be an object (got ${JSON.stringify(raw)}). Use actionGate: { enabled: true } to opt in.`
    );
  }
  const block = (raw ?? {}) as Record<string, unknown>;
  const rawEnabled = block.enabled;
  let enabled = ACTION_GATE_DEFAULTS.enabled;
  if (rawEnabled !== undefined) {
    const coerced = coerceBool(rawEnabled);
    if (coerced === undefined) {
      throw new Error(
        `actionGate.enabled must be a boolean or one of "true"/"false"/"1"/"0"/"yes"/"no"/"on"/"off" (got ${JSON.stringify(rawEnabled)}).`
      );
    }
    enabled = coerced;
  }
  const rawTimeout = coerceNumber(block.timeoutMs);
  const timeoutMs =
    rawTimeout !== undefined && Number.isFinite(rawTimeout)
      ? Math.min(5000, Math.max(1, Math.floor(rawTimeout)))
      : ACTION_GATE_DEFAULTS.timeoutMs;
  const rawMax = coerceNumber(block.maxAdvisoriesPerTurn);
  // Zero-limit semantics are a compatibility contract: `0` stays `0`.
  const maxAdvisoriesPerTurn =
    rawMax !== undefined && Number.isFinite(rawMax)
      ? Math.min(20, Math.max(0, Math.floor(rawMax)))
      : ACTION_GATE_DEFAULTS.maxAdvisoriesPerTurn;
  return { enabled, timeoutMs, maxAdvisoriesPerTurn };
}

export type ActionGateStatus = "DISABLED" | "NO_MATCH" | "MATCH_WARN" | "ERROR_FAIL_OPEN";

export interface ActionGateRequest {
  sessionKey: string;
  /** Turn identity: the per-turn budget and dedupe reset when this changes. */
  turnId: string;
  strategyId: ActionStrategyId;
  intent: ActionIntent;
  codingContext: CodingContext;
  /** Memory directory ALREADY resolved for the caller's readable namespace. */
  memoryDir: string;
  /** Resolved readable namespace, passed verbatim to candidate sources. */
  namespace?: string;
  causalTrajectoryStoreDir?: string;
  signal?: AbortSignal;
}

export interface ActionGateAdvisory {
  /** Trajectory id or memory id — the unit of dedupe and suppression. */
  memoryId: string;
  sourceId: string;
  text: string;
}

export interface ActionGateDecision {
  status: ActionGateStatus;
  advisories: ActionGateAdvisory[];
  /** Candidates withheld: already delivered this turn/session, or over budget. */
  suppressedIds: string[];
  /** Source failures, kept distinct from "no candidates" (rule 22). */
  degradations: string[];
  fingerprint?: string;
  reason?: string;
  latencyMs: number;
}

export interface ActionGateCandidate {
  memoryId: string;
  advisoryText: string;
  /** Deterministic ranking key; higher wins, ties break on `memoryId`. */
  score?: number;
}

export interface ActionGateCandidateQuery {
  sessionKey: string;
  fingerprint: string;
  /** Normalized, deduplicated lexical terms describing the proposed action. */
  actionTerms: string[];
  strategyId: ActionStrategyId;
  intent: ActionIntent;
  codingContext: CodingContext;
  memoryDir: string;
  namespace?: string;
  causalTrajectoryStoreDir?: string;
  signal?: AbortSignal;
}

export type ActionGateSourceResult = { ok: true; candidates: ActionGateCandidate[] } | { ok: false; reason: string };

export interface ActionGateCandidateSource {
  readonly id: string;
  find(query: ActionGateCandidateQuery): Promise<ActionGateSourceResult>;
}

export interface ActionGateAuditRecord {
  ts: string;
  sessionKey: string;
  turnId: string;
  status: ActionGateStatus;
  latencyMs: number;
  fingerprint?: string;
  deliveredIds: string[];
  suppressedIds: string[];
  degradations: string[];
  reason?: string;
}

export type ActionGateAuditSink = (record: ActionGateAuditRecord) => void | Promise<void>;

export interface ActionGateServiceDependencies {
  sources?: ActionGateCandidateSource[];
  audit?: ActionGateAuditSink;
  clock?: () => number;
  now?: () => Date;
}

/**
 * Deterministic, local term extraction from a proposed action. No LLM and no
 * I/O: this runs in the hot path ahead of the tool call.
 */
export function actionTermsFor(intent: ActionIntent): string[] {
  const raw =
    intent.kind === "command"
      ? [intent.command, ...(intent.args ?? [])]
      : [intent.filePath, intent.editKind, intent.symbol ?? "", intent.range ?? ""];
  const terms: string[] = [];
  const seen = new Set<string>();
  for (const piece of raw) {
    for (const token of sanitizePayloadString(piece ?? "")
      .toLowerCase()
      .split(/[^a-z0-9._-]+/)) {
      const term = token.replace(/^[._-]+|[._-]+$/g, "");
      if (term.length < MIN_TERM_CHARS || seen.has(term)) continue;
      seen.add(term);
      terms.push(term);
      if (terms.length >= MAX_ACTION_TERMS) return terms;
    }
  }
  return terms;
}

/**
 * Failure-class markers on stored memories, read from frontmatter only so the
 * decision stays deterministic: explicit corrections, procedures flagged for
 * repair by library maintenance, and memories whose recorded outcomes are
 * failure-dominant.
 */
export function isFailureClassMemory(memory: MemoryFile): boolean {
  const fm = memory.frontmatter;
  if (fm.status !== undefined && fm.status !== "active") return false;
  if (fm.category === "correction") return true;
  if (fm.structuredAttributes?.needsRepair === "true") return true;
  const failures = typeof fm.mw_fail === "number" ? fm.mw_fail : 0;
  const successes = typeof fm.mw_success === "number" ? fm.mw_success : 0;
  return failures > 0 && failures > successes;
}

export interface FailureMemorySourceDependencies {
  /**
   * Namespace-scoped listing of candidate memories. Callers wire this to a
   * storage read for the SAME namespace the gate request resolved, so a
   * principal can never receive another principal's advisories.
   */
  listMemories: (options: {
    namespace?: string;
    memoryDir: string;
    signal?: AbortSignal;
  }) => Promise<MemoryFile[]>;
}

/**
 * Failure-class memory candidates, matched by bounded lexical overlap against
 * the proposed action's terms. Deterministic and local by construction.
 */
export function createFailureMemoryCandidateSource(deps: FailureMemorySourceDependencies): ActionGateCandidateSource {
  return {
    id: "failure-memory",
    async find(query) {
      if (query.actionTerms.length === 0) return { ok: true, candidates: [] };
      let memories: MemoryFile[];
      try {
        memories = await deps.listMemories({
          namespace: query.namespace,
          memoryDir: query.memoryDir,
          signal: query.signal,
        });
      } catch (error) {
        return { ok: false, reason: error instanceof Error ? error.message : String(error) };
      }
      const required = Math.max(1, Math.ceil(query.actionTerms.length * MIN_TERM_OVERLAP_RATIO));
      const candidates: ActionGateCandidate[] = [];
      for (const memory of memories) {
        if (!isFailureClassMemory(memory)) continue;
        const haystack = `${memory.content} ${(memory.frontmatter.tags ?? []).join(" ")}`.toLowerCase();
        let hits = 0;
        for (const term of query.actionTerms) if (haystack.includes(term)) hits += 1;
        if (hits < required) continue;
        candidates.push({
          memoryId: memory.frontmatter.id,
          score: hits,
          advisoryText: `[ActionGate] A stored failure memory matches this action: "${memory.content}".`,
        });
      }
      candidates.sort((left, right) => {
        const byScore = (right.score ?? 0) - (left.score ?? 0);
        return byScore !== 0 ? byScore : left.memoryId.localeCompare(right.memoryId);
      });
      return { ok: true, candidates };
    },
  };
}

/**
 * Candidate source over recorded causal-trajectory failures, delegating the
 * fingerprint match to the existing `PreActionFailureGate` primitive.
 */
export function createTrajectoryCandidateSource(gate: PreActionFailureGate): ActionGateCandidateSource {
  return {
    id: "causal-trajectory",
    async find(query) {
      const result = await gate.evaluate({
        sessionKey: query.sessionKey,
        strategyId: query.strategyId,
        intent: query.intent,
        codingContext: query.codingContext,
        memoryDir: query.memoryDir,
        causalTrajectoryStoreDir: query.causalTrajectoryStoreDir,
        signal: query.signal,
      });
      if (result.status === "ERROR_FAIL_OPEN") {
        return { ok: false, reason: result.reason ?? "pre-action gate failed open" };
      }
      if (result.status !== "MATCH_WARN" || !result.matchedTrajectoryId || !result.advisoryText) {
        return { ok: true, candidates: [] };
      }
      return {
        ok: true,
        candidates: [
          {
            memoryId: result.matchedTrajectoryId,
            // Trajectory matches are exact fingerprint hits: rank above lexical ones.
            score: Number.MAX_SAFE_INTEGER,
            advisoryText: result.advisoryText,
          },
        ],
      };
    },
  };
}

interface SessionSuppression {
  turnId: string;
  /** Ids the gate delivered during `turnId`. */
  deliveredThisTurn: Set<string>;
  /** Ids the gate delivered anywhere in the session; turn-start must skip them. */
  deliveredByGate: Set<string>;
  /** Ids turn-start injection already delivered; the gate must skip them. */
  deliveredByTurnStart: Set<string>;
}

/**
 * Advisory gate evaluated immediately before an agent action.
 *
 * Delivery is bounded three ways: a hard deadline, `maxAdvisoriesPerTurn`, and
 * dedupe per memory per turn. Cross-channel suppression keeps one memory from
 * arriving twice in a session — once here and once from turn-start recall.
 */
export class ActionGateService {
  private readonly config: ActionGateConfig;
  private readonly sources: ActionGateCandidateSource[];
  private readonly audit?: ActionGateAuditSink;
  private readonly clock: () => number;
  private readonly now: () => Date;
  private readonly sessions = new Map<string, SessionSuppression>();

  constructor(config: ActionGateConfig, deps: ActionGateServiceDependencies = {}) {
    this.config = config;
    this.sources = deps.sources ?? [];
    this.audit = deps.audit;
    this.clock = deps.clock ?? Date.now;
    this.now = deps.now ?? (() => new Date());
  }

  /**
   * Memory ids the gate already delivered in this session. Turn-start recall
   * filters these out before its own cap, honouring the filter-then-cap order.
   */
  public suppressedForTurnStart(sessionKey: string): string[] {
    if (!this.config.enabled) return [];
    return [...(this.sessions.get(sessionKey)?.deliveredByGate ?? [])];
  }

  /** Record ids turn-start recall injected, so the gate will not repeat them. */
  public noteTurnStartDelivery(sessionKey: string, memoryIds: readonly string[]): void {
    if (!this.config.enabled || memoryIds.length === 0) return;
    const state = this.sessionState(sessionKey, undefined);
    for (const id of memoryIds) this.addTracked(state.deliveredByTurnStart, id);
  }

  public resetSession(sessionKey: string): void {
    this.sessions.delete(sessionKey);
  }

  async evaluate(request: ActionGateRequest): Promise<ActionGateDecision> {
    const startedAt = this.clock();
    if (!this.config.enabled) {
      return {
        status: "DISABLED",
        advisories: [],
        suppressedIds: [],
        degradations: [],
        reason: "actionGate.enabled is false",
        latencyMs: 0,
      };
    }
    if (this.config.maxAdvisoriesPerTurn === 0) {
      return this.finish(request, startedAt, {
        status: "DISABLED",
        advisories: [],
        suppressedIds: [],
        degradations: [],
        reason: "actionGate.maxAdvisoriesPerTurn is 0",
      });
    }

    let fingerprint: string;
    try {
      fingerprint = normalizeActionIntent(request.intent, request.strategyId, request.codingContext).fingerprint;
    } catch (error) {
      return this.finish(request, startedAt, {
        status: "ERROR_FAIL_OPEN",
        advisories: [],
        suppressedIds: [],
        degradations: [],
        reason: error instanceof Error ? error.message : String(error),
      });
    }

    const deadline = startedAt + this.config.timeoutMs;
    const collected = await this.collect(request, fingerprint, deadline);
    const state = this.sessionState(request.sessionKey, request.turnId);
    const advisories: ActionGateAdvisory[] = [];
    const suppressedIds: string[] = [];
    for (const { sourceId, candidate } of collected.candidates) {
      if (state.deliveredThisTurn.has(candidate.memoryId) || state.deliveredByTurnStart.has(candidate.memoryId)) {
        suppressedIds.push(candidate.memoryId);
        continue;
      }
      if (advisories.length >= this.config.maxAdvisoriesPerTurn) {
        suppressedIds.push(candidate.memoryId);
        continue;
      }
      advisories.push({
        memoryId: candidate.memoryId,
        sourceId,
        text: sanitizePayloadString(candidate.advisoryText).replace(/\s+/g, " ").slice(0, MAX_ADVISORY_CHARS),
      });
      this.addTracked(state.deliveredThisTurn, candidate.memoryId);
      this.addTracked(state.deliveredByGate, candidate.memoryId);
    }

    const status: ActionGateStatus =
      advisories.length > 0 ? "MATCH_WARN" : collected.degradations.length > 0 ? "ERROR_FAIL_OPEN" : "NO_MATCH";
    return this.finish(request, startedAt, {
      status,
      advisories,
      suppressedIds,
      degradations: collected.degradations,
      fingerprint,
      reason: status === "ERROR_FAIL_OPEN" ? collected.degradations[0] : undefined,
    });
  }

  private async collect(
    request: ActionGateRequest,
    fingerprint: string,
    deadline: number
  ): Promise<{
    candidates: Array<{ sourceId: string; candidate: ActionGateCandidate }>;
    degradations: string[];
  }> {
    if (this.sources.length === 0) return { candidates: [], degradations: [] };
    const timeoutAbort = new AbortController();
    const signal = request.signal
      ? AbortSignal.any([request.signal, timeoutAbort.signal])
      : timeoutAbort.signal;
    const query: ActionGateCandidateQuery = {
      sessionKey: request.sessionKey,
      fingerprint,
      actionTerms: actionTermsFor(request.intent),
      strategyId: request.strategyId,
      intent: request.intent,
      codingContext: request.codingContext,
      memoryDir: request.memoryDir,
      namespace: request.namespace,
      causalTrajectoryStoreDir: request.causalTrajectoryStoreDir,
      signal,
    };
    const remaining = Math.max(1, deadline - this.clock());
    let onTimeout!: (value: ActionGateSourceResult) => void;
    const timeoutResult = new Promise<ActionGateSourceResult>((resolve) => {
      onTimeout = resolve;
    });
    const timer = setTimeout(() => {
      timeoutAbort.abort();
      onTimeout({ ok: false, reason: `action gate timed out after ${this.config.timeoutMs}ms` });
    }, remaining);
    try {
      const settled = await Promise.all(
        this.sources.map(async (source) => {
          let result: ActionGateSourceResult;
          try {
            result = await Promise.race([source.find(query), timeoutResult]);
          } catch (error) {
            result = { ok: false, reason: error instanceof Error ? error.message : String(error) };
          }
          return { source, result };
        })
      );
      const candidates: Array<{ sourceId: string; candidate: ActionGateCandidate }> = [];
      const degradations: string[] = [];
      for (const { source, result } of settled) {
        if (!result.ok) {
          degradations.push(`${source.id}: ${result.reason}`);
          continue;
        }
        for (const candidate of result.candidates) candidates.push({ sourceId: source.id, candidate });
      }
      candidates.sort((left, right) => {
        const byScore = (right.candidate.score ?? 0) - (left.candidate.score ?? 0);
        if (byScore !== 0) return byScore;
        const bySource = left.sourceId.localeCompare(right.sourceId);
        return bySource !== 0 ? bySource : left.candidate.memoryId.localeCompare(right.candidate.memoryId);
      });
      return { candidates, degradations };
    } finally {
      clearTimeout(timer);
    }
  }

  private finish(
    request: ActionGateRequest,
    startedAt: number,
    decision: Omit<ActionGateDecision, "latencyMs">
  ): ActionGateDecision {
    const latencyMs = Math.max(0, this.clock() - startedAt);
    const result: ActionGateDecision = { ...decision, latencyMs };
    if (this.audit) {
      const record: ActionGateAuditRecord = {
        ts: this.now().toISOString(),
        sessionKey: request.sessionKey,
        turnId: request.turnId,
        status: result.status,
        latencyMs,
        fingerprint: result.fingerprint,
        deliveredIds: result.advisories.map((advisory) => advisory.memoryId),
        suppressedIds: result.suppressedIds,
        degradations: result.degradations,
        reason: result.reason,
      };
      // Telemetry must never break the action it observes.
      void Promise.resolve()
        .then(() => this.audit?.(record))
        .catch(() => undefined);
    }
    return result;
  }

  private sessionState(sessionKey: string, turnId: string | undefined): SessionSuppression {
    let state = this.sessions.get(sessionKey);
    if (!state) {
      if (this.sessions.size >= MAX_TRACKED_SESSIONS) {
        const oldest = this.sessions.keys().next().value;
        if (oldest !== undefined) this.sessions.delete(oldest);
      }
      state = {
        turnId: turnId ?? "",
        deliveredThisTurn: new Set(),
        deliveredByGate: new Set(),
        deliveredByTurnStart: new Set(),
      };
      this.sessions.set(sessionKey, state);
    }
    if (turnId !== undefined && state.turnId !== turnId) {
      state.turnId = turnId;
      state.deliveredThisTurn.clear();
    }
    return state;
  }

  private addTracked(set: Set<string>, value: string): void {
    if (set.has(value)) return;
    if (set.size >= MAX_TRACKED_IDS_PER_SESSION) {
      const oldest = set.values().next().value;
      if (oldest !== undefined) set.delete(oldest);
    }
    set.add(value);
  }
}

/**
 * Config parsing for the chat feature (issue #1583).
 *
 * Kept in a dedicated module so config.ts gains only an import + one call
 * site — the god-file ratchet (#1520) tracks config.ts LOC.
 */

import type { ChatConfig } from "../types.js";
import { coerceNumber } from "../connectors/coerce.js";

export const DEFAULT_CHAT_CONFIG: ChatConfig = {
  enabled: false,
  model: "",
  maxToolCallsPerTurn: 8,
  sessionTtlHours: 72,
};

/**
 * Coerce a positive-integer config value, accepting numeric strings written
 * via CLI `key=value` paths (rule 28 — coerce at the boundary). Falls back to
 * the default for missing/unparseable values, matching the existing
 * silent-default semantics of this parser.
 */
function positiveInt(value: unknown, fallback: number): number {
  const n = coerceNumber(value);
  return typeof n === "number" && Number.isInteger(n) && n > 0 ? n : fallback;
}

/**
 * Parse the `chat` config section from the raw config object.
 *
 * ```
 * "chat": {
 *   "enabled": true,
 *   "model": "ollama/llama3",
 *   "maxToolCallsPerTurn": 8,
 *   "sessionTtlHours": 72
 * }
 * ```
 *
 * Missing fields default to {@link DEFAULT_CHAT_CONFIG} (rule 48 — explicit
 * opt-in; `enabled` defaults to `false`).
 */
export function parseChatConfig(
  raw: unknown,
): ChatConfig {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    return { ...DEFAULT_CHAT_CONFIG };
  }
  const obj = raw as Record<string, unknown>;
  return {
    enabled: obj.enabled === true || obj.enabled === "true" || obj.enabled === "1",
    model: typeof obj.model === "string" ? obj.model : "",
    maxToolCallsPerTurn: positiveInt(obj.maxToolCallsPerTurn, DEFAULT_CHAT_CONFIG.maxToolCallsPerTurn),
    sessionTtlHours: positiveInt(obj.sessionTtlHours, DEFAULT_CHAT_CONFIG.sessionTtlHours),
  };
}

import { isIP } from "node:net";

import { z } from "zod";

import { coerceBool } from "../connectors/coerce.js";
import type { SupportPassportConfig } from "../types.js";

export const DEFAULT_SUPPORT_PASSPORT_CONFIG: SupportPassportConfig = {
  enabled: false,
  trustedProxyAddresses: [],
};

export function parseSupportPassportConfig(raw: unknown): SupportPassportConfig {
  if (raw === undefined) {
    return {
      ...DEFAULT_SUPPORT_PASSPORT_CONFIG,
      trustedProxyAddresses: [...DEFAULT_SUPPORT_PASSPORT_CONFIG.trustedProxyAddresses],
    };
  }
  const schema = z
    .object({
      enabled: z
        .preprocess((value) => {
          if (value === undefined) return false;
          return coerceBool(value) ?? value;
        }, z.boolean())
        .default(false),
      trustedProxyAddresses: z
        .array(z.string().trim().refine((value) => isIP(value) !== 0, "must contain IP addresses"))
        .max(32)
        .default([]),
    })
    .strict();
  const parsed = schema.safeParse(raw);
  if (!parsed.success) {
    throw new Error(
      "supportPassport must contain only enabled and up to 32 trustedProxyAddresses IP addresses"
    );
  }
  return parsed.data;
}

/**
 * Faithfulness-gate + correction-intent config parsing (issue #1576 / #1585).
 *
 * Extracted verbatim from `config.ts` (a watchlisted god file) so the gate
 * config block can grow — the model-lab pointer keys
 * `extractionFaithfulnessBaseUrl` (#1585) and the correction-intent pointers
 * (`correctionIntentModel` / `correctionIntentBaseUrl`) — without growing the
 * god file. This is a behavior-preserving extraction (#1526-style): the
 * validation, defaults, and error messages are byte-identical to the inline
 * block it replaces, which the existing extraction-faithfulness + config
 * tests pin.
 *
 * Why a dedicated module (and not inline): the ratchet
 * (`scripts/check-ratchets.mjs`) forbids `config.ts` from growing, and the
 * model-lab integration needs three new optional keys. Centralizing the whole
 * gate+intent parsing here keeps it unit-testable in isolation and lets
 * `config.ts` spread the result in one line.
 */

import { coerceBool, coerceNumber } from "./connectors/coerce.js";

/**
 * Parse a value as a strict integer >= `min`, throwing on anything else.
 *
 * Mirrors `parseIntegerAtLeast` in `config.ts` byte-for-byte (issue #1634:
 * reject non-numeric, <=0, non-integer, NaN, Infinity, booleans, objects —
 * gotcha #51). Reimplemented locally rather than exported from `config.ts`
 * so this module has no dependency on the god file (and vice versa).
 */
function parseIntegerAtLeast(
  value: unknown,
  fallback: number,
  min: number,
  keyName: string,
): number {
  if (value === undefined || value === null) return fallback;
  const coerced = coerceNumber(value);
  if (
    coerced === undefined ||
    !Number.isFinite(coerced) ||
    !Number.isInteger(coerced) ||
    coerced < min
  ) {
    throw new Error(
      `${keyName} must be an integer greater than or equal to ${min}; got ${JSON.stringify(value)}`,
    );
  }
  return coerced;
}

/**
 * Parse the extraction faithfulness gate config block.
 *
 * Returns exactly the `PluginConfig` fields this block owns. Defaults preserve
 * the byte-identical pre-feature pipeline (rule 39): gate "off", empty model
 * + base URL, context 400 chars, timeout 8000 ms. Invalid `gate` values reject
 * listing valid options (rule 51); invalid integers throw (issue #1634).
 *
 * `extractionFaithfulnessBaseUrl` (issue #1585) is the model-lab pointer: when
 * set together with `extractionFaithfulnessModel`, the gate routes to that
 * local openai-compatible endpoint before the configured chain; empty string
 * (default) preserves the existing routing exactly.
 */
export function parseFaithfulnessGateConfig(cfg: Record<string, unknown>): {
  extractionFaithfulnessGate: "off" | "shadow" | "enforce";
  extractionFaithfulnessModel: string;
  extractionFaithfulnessBaseUrl: string;
  extractionFaithfulnessContextChars: number;
  extractionFaithfulnessTimeoutMs: number;
  extractionFaithfulnessLocalParseFallback: boolean;
} {
  const gateValue = cfg.extractionFaithfulnessGate;
  let extractionFaithfulnessGate: "off" | "shadow" | "enforce";
  if (gateValue === undefined || gateValue === null) {
    extractionFaithfulnessGate = "off";
  } else {
    // Present-but-invalid (true/1/{}) must reject, not silently disable the gate (Ob4RQ).
    const raw = typeof gateValue === "string" ? gateValue.trim().toLowerCase() : gateValue;
    if (raw === "off" || raw === "shadow" || raw === "enforce") {
      extractionFaithfulnessGate = raw;
    } else {
      throw new Error(
        `extractionFaithfulnessGate must be one of "off" | "shadow" | "enforce" (got ${JSON.stringify(gateValue)})`,
      );
    }
  }

  const extractionFaithfulnessModel =
    typeof cfg.extractionFaithfulnessModel === "string" ? cfg.extractionFaithfulnessModel : "";

  // Issue #1585: model-lab pointer. Empty default → gate uses its existing
  // routing chain (byte-identical). Non-empty + a model name → gate prefers
  // the local served endpoint, falling back to the chain on failure.
  const extractionFaithfulnessBaseUrl =
    typeof cfg.extractionFaithfulnessBaseUrl === "string"
      ? cfg.extractionFaithfulnessBaseUrl
      : "";

  const extractionFaithfulnessContextChars = Math.min(
    parseIntegerAtLeast(cfg.extractionFaithfulnessContextChars, 400, 1, "extractionFaithfulnessContextChars"),
    4000,
  );

  const extractionFaithfulnessTimeoutMs = Math.min(
    parseIntegerAtLeast(cfg.extractionFaithfulnessTimeoutMs, 8000, 1, "extractionFaithfulnessTimeoutMs"),
    60_000,
  );

  // Issue #1700 nit #6: resilient-fallback toggle for the local model-lab
  // endpoint. Default false preserves the loud-signal behavior (a 200-with-
  // garbage local response surfaces malformed_output so a misconfigured
  // endpoint is visible); true falls back to the configured chain on local
  // parse failure. Byte-identical pre-feature when unset (rule 39).
  // coerceBool for CLI-string parity: a CLI override like
  // --config extractionFaithfulnessLocalParseFallback=true reaches here as the
  // string "true"; === true would silently leave the flag disabled. Matches
  // every other CLI-settable boolean in config.ts (gotcha 36, codex P2
  // PRRT_kwDORJXyws6O6gDQ / cursor BUGBOT e273b22c).
  const extractionFaithfulnessLocalParseFallback =
    coerceBool(cfg.extractionFaithfulnessLocalParseFallback) === true;

  return {
    extractionFaithfulnessGate,
    extractionFaithfulnessModel,
    extractionFaithfulnessBaseUrl,
    extractionFaithfulnessContextChars,
    extractionFaithfulnessTimeoutMs,
    extractionFaithfulnessLocalParseFallback,
  };
}

/**
 * Parse the correction-intent config block (issue #1581 / #1585).
 *
 * The model-lab pointer for passive-correction detection: when both
 * `correctionIntentModel` and `correctionIntentBaseUrl` are set, the detection
 * path can route to that local fine-tuned classifier; empty defaults (the
 * common case) keep the rule-based `detectPassiveCorrections` heuristic as the
 * sole detector — byte-identical to the pre-feature path. Consumption by the
 * detector is the consuming child's job (#1581's detector is a pure function;
 * wiring a model call into it is out of scope for this config-pointer PR).
 */
export function parseCorrectionIntentConfig(cfg: Record<string, unknown>): {
  correctionIntentModel: string;
  correctionIntentBaseUrl: string;
} {
  return {
    correctionIntentModel:
      typeof cfg.correctionIntentModel === "string" ? cfg.correctionIntentModel : "",
    correctionIntentBaseUrl:
      typeof cfg.correctionIntentBaseUrl === "string" ? cfg.correctionIntentBaseUrl : "",
  };
}

