  });
}

export function summarizeOfflineSyncPendingFiles(options: {
  baseFiles?: readonly OfflineSyncFileState[];
  currentFiles: readonly OfflineSyncFileState[];
  includeTranscripts?: boolean;
  userExcludeRegexps?: readonly RegExp[];
  /**
   * When false, enumeration uses only the legacy structural excludes —
   * the apply/pull-side view of local files. Push-side callers keep the
   * default (true): built-in node-local state excludes + user excludes.
   * (Cursor review on PR #1793: apply-side local enumeration must see
   * files like state/lcm.sqlite or merges misclassify them.)
   */
  excludeNodeLocalState?: boolean;
}): OfflineSyncChangesetSummary {
  const includeTranscripts = options.includeTranscripts !== false;
  const base = byPath(filterBaseFilesForMode(
    normalizeFileStates(options.baseFiles),
    includeTranscripts,
  ));
  const currentMap = byPath(filterBaseFilesForMode(
    normalizeFileStates(options.currentFiles),
    includeTranscripts,
  ));
  let upserts = 0;
  let deletes = 0;
  for (const relPath of unionPaths(base, currentMap)) {
    if (shouldPreferIncomingOfflineRuntimeFile(relPath)) continue;
    if (shouldExcludePushRelPath(relPath, includeTranscripts, options.userExcludeRegexps)) continue;
    const baseEntry = base.get(relPath);
    const currentEntry = currentMap.get(relPath);
    if (currentEntry && currentEntry.sha256 !== baseEntry?.sha256) {
      upserts += 1;
      continue;
    }
    if (!currentEntry && baseEntry) {
      deletes += 1;
    }
  }

  return {
    upserts,
    deletes,
    total: upserts + deletes,
  };
}

export async function applyOfflineSyncSnapshot(options: {
  root: string;
  snapshot: unknown;
  baseFiles?: readonly OfflineSyncFileState[];
  currentFiles?: readonly OfflineSyncFileState[];
  deferredPaths?: readonly string[];
  allowMissingConflictContent?: boolean;
  /**
   * Explicit INCOMING content source for snapshot records without inline
   * `contentBase64` (oversized generation members the client fetched
   * chunk-wise into a private staging root). Consulted only for such
   * records; return null to keep the metadata-only behavior (the local
   * file must hash-match the record). Returned buffers are digest-verified
   * against the incoming record before anything is published.
   */
  readIncomingFile?: (target: { path: string; sha256: string; bytes: number }) => Promise<Buffer | null>;
  writeConflictCopies?: boolean;
  readFile?: (target: OfflineSyncFileTarget) => Promise<Buffer>;
  readFileDigest?: (target: OfflineSyncFileTarget) => Promise<OfflineSyncFileDigest>;
  writeFile?: (target: OfflineSyncFileWriteTarget) => Promise<void>;
  writeStagingFile?: (target: OfflineSyncFileStagingWriteTarget) => Promise<void>;
  readStagingFile?: (target: OfflineSyncFileStagingReadTarget) => Promise<Buffer>;
  deleteFile?: (target: OfflineSyncFileDeleteTarget) => Promise<void>;
  recordDeletionRevision?: OfflineSyncRecordDeletionRevision;
}): Promise<OfflineSyncApplySnapshotResult> {
  const snapshot = normalizeOfflineSyncSnapshot(options.snapshot);
  const baseMap = byPath(filterBaseFilesForMode(
    normalizeFileStates(options.baseFiles),
    snapshot.includeTranscripts,
  ));
  const incomingMap = byPath(snapshot.files);
  const deletionMtimeByPath = snapshot.deletions === undefined
    ? undefined
    : new Map(snapshot.deletions.map((deletion) => [deletion.path, deletion.mtimeMs] as const));
  const incomingBuffers = await verifyRecordContents(snapshot.files, "offline sync snapshot", {
    requireContent: false,
    readIncomingFile: options.readIncomingFile,
  });
  const root = await ensureSyncRoot(options.root, "applyOfflineSyncSnapshot");
  const currentFiles = options.currentFiles
    ? filterBaseFilesForMode(normalizeFileStates(options.currentFiles), snapshot.includeTranscripts).sort(compareByPath)
    : (await buildOfflineSyncSnapshot({
        root: root.abs,
        sourceId: "local",
        includeContent: false,
        includeTranscripts: snapshot.includeTranscripts,
        readFile: options.readFile,
        readFileDigest: options.readFileDigest,
        excludeNodeLocalState: false,
      })).files;
  const currentMap = byPath(currentFiles);
  const deferredPaths = new Set([...(options.deferredPaths ?? []),
    ...divergedEmbeddingGenerationDeferrals({
      incomingFiles: snapshot.files, baseFiles: [...baseMap.values()], currentFiles,
    }),
  ]);
  const omittedGenerationDirs = new Set(snapshot.omittedEmbeddingGenerationDirs ?? []);
  if (deletionMtimeByPath && options.recordDeletionRevision) {
    for (const [relPath, mtimeMs] of deletionMtimeByPath) {
      if (
        currentMap.has(relPath) ||
        deferredPaths.has(relPath) ||
        (omittedGenerationDirs.size > 0 &&
          isPathInOmittedEmbeddingGeneration(relPath, omittedGenerationDirs)) ||
        matchesOfflineSyncDefaultExclude(relPath)
      ) {
        continue;
      }
      await options.recordDeletionRevision({
        root: root.abs,
        path: relPath,
        filePath: await resolveSafeArchiveTarget(root, relPath),
        mtimeMs,
      });
    }
  }
  const nextBase = new Map(baseMap);
  const conflicts: OfflineSyncConflict[] = [];
  let upserted = 0;
  let deleted = 0;
  let skipped = 0;
  let pendingLocal = 0;
  const conflictIncomingBuffer = (relPath: string): Buffer | undefined => {
    if (options.writeConflictCopies === false) return undefined;
    const buffer = incomingBuffers.get(relPath);
    if (buffer || options.allowMissingConflictContent === true) return buffer;
    return requiredBuffer(incomingBuffers, relPath);
  };

  // Embedding generations travel and replace as ONE unit (issue #3148):
  // atomic replacement, cross-layout marker conversion, whole-generation
  // removal on tombstones — all extracted to the generation module (issue
  // #3150) so the changeset path can share it without growing this file.
  const { transactionResults, deferredGenerationDirs } = await applyIncomingEmbeddingGenerations({
    root,
    incomingMap,
    incomingBuffers,
    baseMap,
    currentMap,
    deferredPaths,
    omittedGenerationDirs,
    deletionMtimeByPath,
    io: {
      readFile: options.readFile,
      writeStagingFile: options.writeStagingFile,
      readStagingFile: options.readStagingFile,
      deleteFile: options.deleteFile,
    },
    customIoPresent: Boolean(options.writeFile || options.readFile || options.readFileDigest || options.deleteFile),
    now: Date.now(),
  });

  const transactionHandled = new Set<string>();
  let generationUpserted = 0;
  let generationDeleted = 0;
  for (const result of transactionResults) {
    if (result.deferredLocalDivergence) {
      for (const relPath of result.handledPaths) deferredPaths.add(relPath);
      deferredGenerationDirs.add(result.shardDirRel);
      continue;
    }
    generationUpserted += result.upserted;
    generationDeleted += result.deleted;
    for (const relPath of result.handledPaths) transactionHandled.add(relPath);
    // Record converted shard paths directly; they may not be in any input map.
    for (const [relPath, state] of result.writtenStates) {
      nextBase.set(relPath, state);
      transactionHandled.add(relPath);
    }
    for (const relPath of result.removedPaths) {
      nextBase.delete(relPath);
      transactionHandled.add(relPath);
    }
  }

  for (const relPath of unionPaths(baseMap, incomingMap, currentMap)) {
    const base = baseMap.get(relPath);
    const incoming = incomingMap.get(relPath);
    const currentEntry = currentMap.get(relPath);

    if (deferredPaths.has(relPath)) {
      if (base) nextBase.set(relPath, base);
      else nextBase.delete(relPath);
      skipped += 1;
      continue;
    }

    // The generation transaction already published or removed this path and
    // applied its nextBase bookkeeping above; nothing left to do.
    if (transactionHandled.has(relPath)) continue;

    // A deferral anywhere in a generation defers the WHOLE generation: no
    // partial replacement in either direction, local files and base entries
    // stay exactly as they are.
    const membership = embeddingGenerationMembership(relPath);
    if (membership && deferredGenerationDirs.has(membership.shardDir)) {
      if (base) nextBase.set(relPath, base);
      else nextBase.delete(relPath);
      skipped += 1;
      continue;
    }

    if (incoming) {
      // The generation marker (PR #3176) is node-local on BOTH sides: an
      // incoming copy — old or hostile — never overwrites the local file
      // and never enters the base set. Other default excludes stay
      // apply-accepted (#1786: first-sync LCM sqlite bootstrapping).
      if (isEmbeddingGenerationMarkerPath(relPath)) {
        nextBase.delete(relPath);
        skipped += 1;
        continue;
      }
      if (currentEntry?.sha256 === incoming.sha256) {
        if (await setSafeFileMtime(root, relPath, incoming.mtimeMs)) {
          nextBase.set(relPath, toFileState(incoming));
        } else {
          if (base) nextBase.set(relPath, base);
          else nextBase.delete(relPath);
          pendingLocal += 1;
        }
        skipped += 1;
        continue;
      }
      // Remote unchanged from the shared base while the local file drifted:
      // keep the local copy (no content is needed to make that decision).
      // Members of a replaced generation never reach this branch — the
      // generation transaction or the deferral guard handled them above.
      if (
        shouldPreferIncomingOfflineRuntimeFile(relPath) &&
        currentEntry && base && incoming.sha256 === base.sha256
      ) {
        nextBase.set(relPath, base);
        skipped += 1;
        continue;
      }
      if (shouldPreferIncomingOfflineRuntimeFile(relPath)) {
        await writeSafeFile(root, relPath, requiredBuffer(incomingBuffers, relPath), options.writeFile, incoming.mtimeMs);
        nextBase.set(relPath, toFileState(incoming));
        upserted += 1;
        continue;
      }
      if (!currentEntry && base && incoming.sha256 === base.sha256) {
        nextBase.set(relPath, base);
        pendingLocal += 1;
        skipped += 1;
        continue;
      }
      if (!currentEntry && base && incoming.sha256 !== base.sha256) {
        conflicts.push(await recordConflict({
          root,
          relPath,
          reason: "local_deleted_remote_modified",
          baseSha256: base.sha256,
          incomingSha256: incoming.sha256,
          incomingBuffer: conflictIncomingBuffer(relPath),
          writeConflictCopies: options.writeConflictCopies !== false,
          sourceId: snapshot.sourceId,
          writeFile: options.writeFile,
        }));
        nextBase.set(relPath, base);
        continue;
      }
      if (!currentEntry && !base) {
        // Census miss with on-disk file: uncertain local presence, do not overwrite.
        if (await offlineSyncRegularFilePresent(root, relPath)) {
          pendingLocal += 1;
          skipped += 1;
          continue;
        }
        await writeSafeFile(root, relPath, requiredBuffer(incomingBuffers, relPath), options.writeFile, incoming.mtimeMs);
        nextBase.set(relPath, toFileState(incoming));
        upserted += 1;
        continue;
      }
      if (base && currentEntry && currentEntry.sha256 === base.sha256) {
        await writeSafeFile(root, relPath, requiredBuffer(incomingBuffers, relPath), options.writeFile, incoming.mtimeMs);
        nextBase.set(relPath, toFileState(incoming));
        upserted += 1;
        continue;
      }
      if (base && incoming.sha256 === base.sha256) {
        nextBase.set(relPath, base);
        pendingLocal += 1;
        skipped += 1;
        continue;
      }
      conflicts.push(await recordConflict({
        root,
        relPath,
        reason: base ? "both_modified" : "remote_exists_for_local_create",
        baseSha256: base?.sha256,
        localSha256: currentEntry?.sha256,
        incomingSha256: incoming.sha256,
        incomingBuffer: conflictIncomingBuffer(relPath),
        writeConflictCopies: options.writeConflictCopies !== false,
        sourceId: snapshot.sourceId,
        writeFile: options.writeFile,
      }));
      if (base) nextBase.set(relPath, base);
      continue;
    }

    // Node-local runtime state (#1786): a push-filtered remote snapshot
    // never carries these paths, so their absence is NOT a delete
    // instruction. Drop any stale base entry (pre-#1786 state files still
    // carry them) and leave the local file untouched — deleting a live
    // sqlite WAL/SHM here would corrupt the local LCM store.
    if (matchesOfflineSyncDefaultExclude(relPath)) {
      nextBase.delete(relPath);
      skipped += 1;
      continue;
    }
    if (!currentEntry) {
      nextBase.delete(relPath);
      skipped += 1;
      continue;
    }
    if (
      shouldPreferIncomingOfflineRuntimeFile(relPath) &&
      membership !== null && omittedGenerationDirs.has(membership.shardDir)
    ) {
      // The push omitted this whole generation because a filter excluded at
      // least one member (snapshot.omittedEmbeddingGenerationDirs): absence
      // is NOT a deletion — keep the local generation and its base entries
      // until it is pushed unfiltered or deleted with deletion metadata.
      pendingLocal += 1;
      skipped += 1;
      continue;
    }
    if (
      shouldPreferIncomingOfflineRuntimeFile(relPath) &&
      (base || shouldDeleteAbsentIncomingOfflineRuntimeFile(relPath))
    ) {
      await deleteSafeFile(
        root,
        relPath,
        options.deleteFile,
        deletionMtimeByPath?.get(relPath),
      );
      nextBase.delete(relPath);
      deleted += 1;
      continue;
    }
    if (shouldPreferIncomingOfflineRuntimeFile(relPath)) {
      pendingLocal += 1;
      skipped += 1;
      continue;
    }
    if (base && currentEntry.sha256 === base.sha256) {
      await deleteSafeFile(
        root,
        relPath,
        options.deleteFile,
        deletionMtimeByPath?.get(relPath),
      );
      nextBase.delete(relPath);
      deleted += 1;
      continue;
    }
    if (base) {
      conflicts.push({
        path: relPath,
        reason: "local_modified_remote_deleted",
        baseSha256: base.sha256,
        localSha256: currentEntry.sha256,
      });
      nextBase.set(relPath, base);
      continue;
    }
    pendingLocal += 1;
    skipped += 1;
  }

  return {
    upserted: upserted + generationUpserted,
    deleted: deleted + generationDeleted,
    skipped,
    pendingLocal,
    conflicts,
    nextBaseFiles: [...nextBase.values()].sort(compareByPath),
  };
}

export async function applyOfflineSyncChangeset(options: {
  root: string;
  changeset: unknown;
  currentFiles?: readonly OfflineSyncFileState[];
  returnCurrentFiles?: boolean;
  writeConflictCopies?: boolean;
  readFile?: (target: OfflineSyncFileTarget) => Promise<Buffer>;
  readFileDigest?: (target: OfflineSyncFileTarget) => Promise<OfflineSyncFileDigest>;
  writeFile?: (target: OfflineSyncFileWriteTarget) => Promise<void>;
  writeStagingFile?: (target: OfflineSyncFileStagingWriteTarget) => Promise<void>;
  readStagingFile?: (target: OfflineSyncFileStagingReadTarget) => Promise<Buffer>;
  deleteFile?: (target: OfflineSyncFileDeleteTarget) => Promise<void>;
  recordDeletionRevision?: OfflineSyncRecordDeletionRevision;
}): Promise<OfflineSyncApplyChangesetResult> {
  let changeset: OfflineSyncChangeset;
  try {
    changeset = normalizeOfflineSyncChangeset(options.changeset);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(
      message.startsWith("offline sync")
        ? message
        : `offline sync changeset invalid: ${message}`,
    );
  }
  const root = await ensureSyncRoot(options.root, "applyOfflineSyncChangeset");
  const records = changeset.changes
    .filter((change): change is Extract<OfflineSyncChange, { type: "upsert" }> => change.type === "upsert")
    .map((change) => change.file);
  const incomingBuffers = await verifyRecordContents(records, "offline sync changeset");
  const currentFiles = options.currentFiles
    ? filterBaseFilesForMode(normalizeFileStates(options.currentFiles), changeset.includeTranscripts).sort(compareByPath)
    : (await buildOfflineSyncSnapshotForPaths({
        root: root.abs,
        sourceId: "local",
        paths: changeset.changes.map((change) => change.path),
        includeContent: false,
        includeTranscripts: changeset.includeTranscripts,
        readFile: options.readFile,
        readFileDigest: options.readFileDigest,
        excludeNodeLocalState: false,
      })).files;
  const currentMap = byPath(currentFiles);
  const conflicts: OfflineSyncConflict[] = [];
  let appliedUpserts = 0;
  let appliedDeletes = 0;
  let skipped = 0;

  // Embedding generations apply as ONE unit through the shared locked
  // transaction (issue #3150). Deferred generations surface as conflicts so
  // the push side never checkpoints them as applied.
  const generationRouting = await applyChangesetEmbeddingGenerations({
    root,
    changeset,
    incomingBuffers,
    currentMap,
    io: {
      readFile: options.readFile,
      writeStagingFile: options.writeStagingFile,
      readStagingFile: options.readStagingFile,
      deleteFile: options.deleteFile,
    },
    customIoPresent: Boolean(options.writeFile || options.readFile || options.readFileDigest || options.deleteFile),
    now: Date.now(),
  });
  appliedUpserts += generationRouting.appliedUpserts;
  appliedDeletes += generationRouting.appliedDeletes;
  conflicts.push(...generationRouting.conflicts);

  for (const change of changeset.changes) {
    if (generationRouting.conflictedPaths.has(change.path)) continue;
    if (generationRouting.transactionHandled.has(change.path)) continue;
    if (isEmbeddingGenerationMarkerPath(change.path)) {
      skipped += 1;
      continue;
    }
    const currentEntry = currentMap.get(change.path);
    if (change.type === "upsert") {
      if (currentEntry?.sha256 === change.file.sha256) {
        if (await setSafeFileMtime(root, change.path, change.file.mtimeMs)) {
          skipped += 1;
        } else {
          await writeSafeFile(root, change.path, requiredBuffer(incomingBuffers, change.path), options.writeFile, change.file.mtimeMs);
          currentMap.set(change.path, toFileState(change.file));
          appliedUpserts += 1;
        }
        continue;
      }
      if (!change.baseSha256) {
        if (!currentEntry) {
          await writeSafeFile(root, change.path, requiredBuffer(incomingBuffers, change.path), options.writeFile, change.file.mtimeMs);
          currentMap.set(change.path, toFileState(change.file));
          appliedUpserts += 1;
          continue;
        }
        conflicts.push(await recordConflict({
          root,
          relPath: change.path,
          reason: "remote_exists_for_local_create",
          localSha256: currentEntry.sha256,
          incomingSha256: change.file.sha256,
          incomingBuffer: incomingBuffers.get(change.path),
          writeConflictCopies: options.writeConflictCopies !== false,
          sourceId: changeset.sourceId,
          writeFile: options.writeFile,
        }));
        continue;
      }
      if (currentEntry?.sha256 === change.baseSha256) {
        await writeSafeFile(root, change.path, requiredBuffer(incomingBuffers, change.path), options.writeFile, change.file.mtimeMs);
        currentMap.set(change.path, toFileState(change.file));
        appliedUpserts += 1;
        continue;
      }
      conflicts.push(await recordConflict({
        root,
        relPath: change.path,
        reason: currentEntry ? "remote_changed_for_local_update" : "remote_deleted_for_local_update",
        baseSha256: change.baseSha256,
        localSha256: currentEntry?.sha256,
        incomingSha256: change.file.sha256,
        incomingBuffer: incomingBuffers.get(change.path),
        writeConflictCopies: options.writeConflictCopies !== false,
        sourceId: changeset.sourceId,
        writeFile: options.writeFile,
      }));
      continue;
    }

    if (!currentEntry) {
      if (change.mtimeMs !== undefined && options.recordDeletionRevision) {
        await options.recordDeletionRevision({
          root: root.abs,
          path: change.path,
          filePath: await resolveSafeArchiveTarget(root, change.path),
          mtimeMs: change.mtimeMs,
        });
      }
      skipped += 1;
      continue;
    }
    if (currentEntry.sha256 === change.baseSha256) {
      await deleteSafeFile(root, change.path, options.deleteFile, change.mtimeMs);
      currentMap.delete(change.path);
      appliedDeletes += 1;
      continue;
    }
    conflicts.push({
      path: change.path,
      reason: "remote_changed_for_local_delete",
      baseSha256: change.baseSha256,
      localSha256: currentEntry.sha256,
    });
  }

  // Generation transactions bypassed the per-file loop; fold their published
  // and removed members into the partial result map (returnCurrentFiles ===
  // false consumers) so it reflects the post-apply generation exactly.
  for (const [relPath, state] of generationRouting.writtenStates) currentMap.set(relPath, state);
  for (const relPath of generationRouting.removedPaths) currentMap.delete(relPath);

  return {
    appliedUpserts,
    appliedDeletes,
    skipped,
    conflicts,
    currentFiles: options.returnCurrentFiles === false
      ? [...currentMap.values()].sort(compareByPath)
      : (await buildOfflineSyncSnapshot({
          root: root.abs,
          sourceId: "local",
          includeContent: false,
          includeTranscripts: changeset.includeTranscripts,
          readFile: options.readFile,
          readFileDigest: options.readFileDigest,
          excludeNodeLocalState: false,
        })).files,
    ...(options.returnCurrentFiles === false ? { currentFilesComplete: false } : {}),
  };
}

async function verifyRecordContents(
  records: readonly OfflineSyncFileRecord[],
  context: string,
  options: {
    requireContent?: boolean;
    readIncomingFile?: (target: { path: string; sha256: string; bytes: number }) => Promise<Buffer | null>;
  } = {},
): Promise<Map<string, Buffer>> {
  const buffers = new Map<string, Buffer>();
  for (const record of records) {
    if (typeof record.contentBase64 !== "string") {
      if (options.readIncomingFile) {
        // Explicit INCOMING content source for records whose bytes travel
        // out-of-band (chunked fetch into the client's private staging
        // root). Never the local current-state file: the buffer is
        // digest-verified against the incoming record before anything is
        // published. null keeps the metadata-only behavior below.
        const incoming = await options.readIncomingFile({
          path: record.path,
          sha256: record.sha256,
          bytes: record.bytes,
        });
        if (incoming) {
          const digest = sha256Buffer(incoming);
          if (digest.sha256 !== record.sha256 || digest.bytes !== record.bytes) {
            throw new Error(`${context}: incoming content checksum mismatch for ${record.path}`);
          }
          buffers.set(record.path, incoming);
          continue;
        }
      }
      if (options.requireContent === false) continue;
      throw new Error(`${context}: contentBase64 is required for ${record.path}`);
    }
    const buffer = Buffer.from(record.contentBase64, "base64");
    const digest = sha256Buffer(buffer);
    if (digest.sha256 !== record.sha256 || digest.bytes !== record.bytes) {
      throw new Error(
        `${context}: content checksum mismatch for ${record.path}`,
      );
    }
    buffers.set(record.path, buffer);
  }
  return buffers;
}

function requiredBuffer(buffers: Map<string, Buffer>, relPath: string): Buffer {
  const buffer = buffers.get(relPath);
  if (!buffer) {
    throw new Error(`missing decoded content for ${relPath}`);
  }
  return buffer;
}

async function ensureSyncRoot(rootPath: string, errorPrefix: string): Promise<SafeArchiveRoot> {
  const rootAbs = path.resolve(rootPath);
  await mkdir(rootAbs, { recursive: true });
  return prepareSafeArchiveRoot(rootAbs, errorPrefix, "root");
}

function byPath<T extends OfflineSyncFileState>(files: readonly T[]): Map<string, T> {
  const out = new Map<string, T>();
  for (const file of files) {
    out.set(validateArchiveRelativePath(file.path, "offlineSync"), file);
  }
  return out;
}

function unionPaths(...maps: Array<Map<string, unknown>>): string[] {
  const paths = new Set<string>();
  for (const map of maps) {
    for (const key of map.keys()) paths.add(key);
  }
  return [...paths].sort();
}

function toFileState(file: OfflineSyncFileState): OfflineSyncFileState {
  return {
    path: file.path,
    sha256: file.sha256,
    bytes: file.bytes,
    mtimeMs: file.mtimeMs,
  };
}

async function writeSafeFile(
  root: SafeArchiveRoot,
  relPath: string,
  content: Buffer,
  writeFileHook?: (target: OfflineSyncFileWriteTarget) => Promise<void>,
  mtimeMs?: number,
): Promise<void> {
  const target = await resolveSafeArchiveTarget(root, relPath);
  if (writeFileHook) {
    await writeFileHook({ root: root.abs, path: relPath, filePath: target, content });
    await setSafeFileMtime(root, relPath, mtimeMs);
    return;
  }
  await mkdir(path.dirname(target), { recursive: true });
  const tmp = path.join(
    path.dirname(target),
    `.remnic-sync.${process.pid}.${randomUUID()}.tmp`,
  );
  await writeFile(tmp, content);
  try {
    const targetStat = await lstat(target).catch((error: unknown) => {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw error;
    });
    if (targetStat?.isSymbolicLink()) {
      throw new Error(`offline sync target is a symlink: ${relPath}`);
    }
    await rename(tmp, target);
    await setSafeFileMtime(root, relPath, mtimeMs);
  } catch (error) {
    await unlink(tmp).catch(() => {});
    throw error;
  }
}


/**
 * Read the local file digest for a single relative path without applying
 * push-side exclude rules. Used by apply-side helpers that need to check
 * the current local state of a path that the push-side exclude would
 * reject (e.g. `state/lcm.sqlite`). Returns `null` if the file does not
 * exist, is not a regular file, or is a symlink.
 */
async function readLocalFileState(options: {
  rootAbs: string;
  relPath: string;
  readFile?: (target: OfflineSyncFileTarget) => Promise<Buffer>;
  readFileDigest?: (target: OfflineSyncFileTarget) => Promise<OfflineSyncFileDigest>;
  signal?: AbortSignal;
}): Promise<OfflineSyncFileState | null> {
  const filePath = await resolveSafeArchiveTarget(
    await prepareSafeArchiveRoot(options.rootAbs, "readLocalFileState", "rootAbs"),
    options.relPath,
  );
  const st = await lstat(filePath).catch((error: unknown) => {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  });
  if (!st || st.isSymbolicLink() || !st.isFile()) return null;
  throwIfOfflineSyncAborted(options.signal);
  let digest: OfflineSyncFileDigest;
  if (options.readFileDigest) {
    digest = await options.readFileDigest({ root: options.rootAbs, path: options.relPath, filePath });
  } else if (options.readFile) {
    const content = await options.readFile({ root: options.rootAbs, path: options.relPath, filePath });
    digest = sha256Buffer(content);
  } else {
    digest = await sha256OfflineSyncFile(filePath, options.signal);
  }
  throwIfOfflineSyncAborted(options.signal);
  return {
    path: options.relPath,
    sha256: digest.sha256,
    bytes: digest.bytes,
    mtimeMs: st.mtimeMs,
  };
}

export async function applyOfflineSyncFileContentChunk(options: {
  root: string;
  sourceId: string;
  path: string;
  sha256: string;
  bytes: number;
  mtimeMs: number;
  offset?: number;
  content: Buffer;
  baseSha256?: string;
  includeTranscripts?: boolean;
  readFile?: (target: OfflineSyncFileTarget) => Promise<Buffer>;
  readFileDigest?: (target: OfflineSyncFileTarget) => Promise<OfflineSyncFileDigest>;
  writeFile?: (target: OfflineSyncFileWriteTarget) => Promise<void>;
  writeStagingFile?: (target: OfflineSyncFileStagingWriteTarget) => Promise<void>;
  writeFileChunks?: (target: OfflineSyncFileWriteChunksTarget) => Promise<void>;
}): Promise<OfflineSyncApplyFileContentChunkResult> {
  const root = await ensureSyncRoot(options.root, "applyOfflineSyncFileContentChunk");
  const sourceId = normalizeSourceId(options.sourceId, "sourceId");
  const relPath = normalizeRelativePath(options.path, "path");
  const includeTranscripts = options.includeTranscripts !== false;
  if (shouldExcludeRelPath(relPath, includeTranscripts)) {
    throw new Error(`offline sync file content path is excluded: ${relPath}`);
  }
  if (isEmbeddingGenerationMarkerPath(relPath)) {
    throw new Error(`offline sync file content path is node-local: ${relPath}`);
  }
  const sha256 = assertSha256(options.sha256, "sha256");
  const bytes = assertNonNegativeInteger(options.bytes, "bytes");
  const mtimeMs = assertOfflineSyncMtimeMs(options.mtimeMs, "mtimeMs");
  const offset = options.offset === undefined
    ? 0
    : assertNonNegativeInteger(options.offset, "offset");
  const baseSha256 = options.baseSha256 === undefined
    ? undefined
    : assertSha256(options.baseSha256, "baseSha256");
  const preferIncomingRuntimeFile = shouldPreferIncomingOfflineRuntimeFile(relPath);
  if (!Buffer.isBuffer(options.content)) {
    throw new Error("content must be a Buffer");
  }
  if (options.content.length > OFFLINE_SYNC_FILE_CONTENT_MAX_CHUNK_BYTES) {
    throw new Error(
      `content chunk must be ${OFFLINE_SYNC_FILE_CONTENT_MAX_CHUNK_BYTES} bytes or fewer`,
    );
  }
  if (bytes > 0 && options.content.length === 0) {
    throw new Error("content chunk must be non-empty before EOF");
  }
  if (offset > bytes || offset + options.content.length > bytes) {
    throw new Error(`content chunk range exceeds declared file size for ${relPath}`);
  }
  if (options.writeFile && !options.writeFileChunks) {
    throw new Error("offline sync upload storage hooks require writeFileChunks");
  }
  if (options.writeFile && !options.writeStagingFile) {
    throw new Error("offline sync upload storage hooks require writeStagingFile");
  }
  const baseResult = {
    path: relPath,
    sha256,
    bytes,
    mtimeMs,
    offset,
    chunkBytes: options.content.length,
    done: offset + options.content.length === bytes,
  };
  const currentFileConflict = async (
    currentFile: OfflineSyncFileState | undefined,
  ): Promise<{ conflict: OfflineSyncConflict; currentFile?: OfflineSyncFileState } | null> => {
    if (!baseSha256 && currentFile && !preferIncomingRuntimeFile) {
      const conflict = await recordConflict({
        root,
        relPath,
        reason: "remote_exists_for_local_create",
        localSha256: currentFile.sha256,
        incomingSha256: sha256,
        writeConflictCopies: false,
        sourceId,
        writeFile: options.writeFile,
      });
      return {
        conflict,
        currentFile,
      };
    }
    if (baseSha256 && currentFile?.sha256 !== baseSha256 && !preferIncomingRuntimeFile) {
      const conflict = await recordConflict({
        root,
        relPath,
        reason: currentFile ? "remote_changed_for_local_update" : "remote_deleted_for_local_update",
        baseSha256,
        localSha256: currentFile?.sha256,
        incomingSha256: sha256,
        writeConflictCopies: false,
        sourceId,
        writeFile: options.writeFile,
      });
      return {
        conflict,
        ...(currentFile ? { currentFile } : {}),
      };
    }
    return null;
  };
  if (offset === 0) {
    await pruneOfflineUploadStaging(root);
    const currentFile = await readLocalFileState({
      rootAbs: root.abs,
      relPath,
      readFile: options.readFile,
      readFileDigest: options.readFileDigest,
    });
    if (currentFile && currentFile.sha256 === sha256) {
      await setSafeFileMtime(root, relPath, mtimeMs);
      return {
        ...baseResult,
        done: true,
        chunkBytes: 0,
        applied: false,
        skipped: true,
        currentFile: toFileState(currentFile),
      };
    }
    const conflictResult = await currentFileConflict(currentFile ? toFileState(currentFile) : undefined);
    if (conflictResult) {
      return {
        ...baseResult,
        done: true,
        chunkBytes: 0,
        applied: false,
        skipped: false,
        ...conflictResult,
      };
    }
  }

  const upload = await writeOfflineUploadChunk({
    root,
    sourceId,
    relPath,
    sha256,
    bytes,
    offset,
    content: options.content,
    readFile: options.readFile,
    writeFile: options.writeFile,
    writeStagingFile: options.writeStagingFile,
  });
  const done = baseResult.done;
  if (!done) {
    return {
      ...baseResult,
      applied: false,
      skipped: false,
    };
  }

  const digest = await digestOfflineUploadStagingContent({
    root,
    upload,
    readFile: options.readFile,
  });
  if (digest.sha256 !== sha256 || digest.bytes !== bytes) {
    await cleanupOfflineUpload(upload).catch(() => {});
    throw new Error(`offline sync upload checksum mismatch for ${relPath}`);
  }

  const currentFile = await readLocalFileState({
    rootAbs: root.abs,
    relPath,
    readFile: options.readFile,
    readFileDigest: options.readFileDigest,
  });
  const uploadedState: OfflineSyncFileState = {
    path: relPath,
    sha256,
    bytes,
    mtimeMs,
  };

  try {
    if (currentFile && currentFile.sha256 === sha256) {
      await setSafeFileMtime(root, relPath, mtimeMs);
      return {
        ...baseResult,
        applied: false,
        skipped: true,
        currentFile: uploadedState,
      };
    }

    const conflictResult = await currentFileConflict(currentFile ? toFileState(currentFile) : undefined);
    if (conflictResult) {
      return {
        ...baseResult,
        applied: false,
        skipped: false,
        ...conflictResult,
      };
    }

    await advanceEmbeddingGenerationMarker(root.abs, embeddingGenerationMembership(relPath), () =>
      writeSafeFileFromUpload(root, relPath, upload, options.readFile, options.writeFileChunks, mtimeMs),
    );
    return {
      ...baseResult,
      applied: true,
      skipped: false,
      currentFile: uploadedState,
    };
  } finally {
    await cleanupOfflineUpload(upload).catch(() => {});
  }
}


async function deleteSafeFile(
  root: SafeArchiveRoot,
  relPath: string,
  deleteFile?: (target: OfflineSyncFileDeleteTarget) => Promise<void>,
  mtimeMs?: number,
): Promise<void> {
  const target = await resolveSafeArchiveTarget(root, relPath);
  if (deleteFile) {
    await deleteFile({
      root: root.abs,
      path: relPath,
      filePath: target,
      ...(mtimeMs === undefined ? {} : { mtimeMs }),
    });
    return;
  }
  await unlink(target).catch((error: unknown) => {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return;
    throw error;
  });
}

async function recordConflict(options: {
  root: SafeArchiveRoot;
  relPath: string;
  reason: OfflineSyncConflict["reason"];
  baseSha256?: string;
  localSha256?: string;
  incomingSha256?: string;
  incomingBuffer?: Buffer;
  writeConflictCopies: boolean;
  sourceId: string;
  writeFile?: (target: OfflineSyncFileWriteTarget) => Promise<void>;
}): Promise<OfflineSyncConflict> {
  let conflictPath: string | undefined;
  if (options.writeConflictCopies && options.incomingBuffer) {
    const sourceHash = hashText(options.sourceId).slice(0, 12);
    const stamp = new Date().toISOString().replace(/[:.]/g, "-");
    conflictPath = `${SYNC_INTERNAL_DIR}/conflicts/${stamp}-${sourceHash}/${options.relPath}`;
    await writeSafeFile(options.root, conflictPath, options.incomingBuffer, options.writeFile);
  }
  return {
    path: options.relPath,
    reason: options.reason,
    baseSha256: options.baseSha256,
    localSha256: options.localSha256,
    incomingSha256: options.incomingSha256,
    ...(conflictPath ? { conflictPath } : {}),
  };
}

export function defaultOfflineSyncStatePath(
  memoryDir: string,
  remoteId: string,
  namespace?: string,
): string {
  const key = hashText(`${remoteId}\0${namespace ?? ""}`).slice(0, 16);
  return path.join(path.resolve(memoryDir), SYNC_INTERNAL_DIR, "state", `${key}.json`);
}

export async function readOfflineSyncState(
  statePath: string,
): Promise<OfflineSyncState | null> {
  let raw: string;
  try {
    raw = await readFile(path.resolve(statePath), "utf-8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  }
  const parsed = JSON.parse(raw) as unknown;
  return normalizeOfflineSyncState(parsed);
}

export async function writeOfflineSyncState(
  statePath: string,
  state: OfflineSyncState,
): Promise<void> {
  const normalized = normalizeOfflineSyncState(state);
  const target = path.resolve(statePath);
  await mkdir(path.dirname(target), { recursive: true });
  const tmp = path.join(
    path.dirname(target),
    `.remnic-sync-state.${process.pid}.${randomUUID()}.tmp`,
  );
  await writeFile(tmp, JSON.stringify(normalized, null, 2) + "\n", "utf-8");
  try {
    await rename(tmp, target);
  } catch (error) {
    await unlink(tmp).catch(() => {});
    throw error;
  }
}

export function offlineSyncStateFromSnapshot(options: {
  remoteId: string;
  namespace?: string;
  snapshot: OfflineSyncSnapshot;
  baseFiles?: readonly OfflineSyncFileState[];
}): OfflineSyncState {
  const snapshot = normalizeOfflineSyncSnapshot(options.snapshot);
  return normalizeOfflineSyncState({
    version: OFFLINE_SYNC_STATE_VERSION,
    remoteId: options.remoteId,
    namespace: options.namespace,
    includeTranscripts: snapshot.includeTranscripts,
    lastSyncedAt: new Date().toISOString(),
    baseFiles: options.baseFiles ?? snapshot.files.map(toFileState),
  });
}

export function normalizeOfflineSyncState(input: unknown): OfflineSyncState {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    throw new Error("offline sync state must be an object");
  }
  const obj = input as Record<string, unknown>;
  if (obj.version !== OFFLINE_SYNC_STATE_VERSION) {
    throw new Error(`offline sync state version must be ${OFFLINE_SYNC_STATE_VERSION}`);
  }
  const namespace =
    typeof obj.namespace === "string" && obj.namespace.trim().length > 0
      ? obj.namespace.trim()
      : undefined;
  const baseFiles = normalizeFileStates(obj.baseFiles as readonly unknown[] | undefined)
    .sort(compareByPath);
  assertUniquePaths(baseFiles, "offline sync state");
  return {
    version: OFFLINE_SYNC_STATE_VERSION,
    remoteId: normalizeSourceId(obj.remoteId, "remoteId"),
    ...(namespace ? { namespace } : {}),
    includeTranscripts: assertBoolean(obj.includeTranscripts, "includeTranscripts"),
    lastSyncedAt: normalizeIsoString(obj.lastSyncedAt, "lastSyncedAt"),
    baseFiles,
  };
}

export function fileStatesFromSnapshot(snapshot: OfflineSyncSnapshot): OfflineSyncFileState[] {
  return normalizeOfflineSyncSnapshot(snapshot).files.map(toFileState).sort(compareByPath);
}

import path from "node:path";
import { assertExternalWikiRootOutsideMemoryDir } from "./external-wiki-guard.js";
import { expandTildePath } from "./utils/path.js";

export interface ExternalWikiRoot {
  id: string;
  rootDir: string;
  enabled: boolean;
  label?: string;
  pagesDir: string;
  indexFile: string;
  indexInQmd: boolean;
  includeInDefaultRecall: false;
}

const EXTERNAL_WIKI_ID_PATTERN = /^[a-z0-9][a-z0-9_-]{0,63}$/;

function requireObject(value: unknown, keyName: string): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`${keyName} must be an object`);
  }
  return value as Record<string, unknown>;
}

function requireString(value: unknown, keyName: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new Error(`${keyName} must be a non-empty string`);
  }
  return value.trim();
}

function parseBoolean(value: unknown, fallback: boolean, keyName: string): boolean {
  if (value === undefined) return fallback;
  if (typeof value !== "boolean") throw new Error(`${keyName} must be a boolean`);
  return value;
}

function parseRootDir(value: unknown, keyName: string): string {
  const raw = requireString(value, keyName);
  if (!path.isAbsolute(raw) && !raw.startsWith("~/")) {
    throw new Error(`${keyName} must be an absolute path or start with ~/`);
  }
  return path.resolve(expandTildePath(raw));
}

function parseRootRelativePath(value: unknown, fallback: string, keyName: string): string {
  const candidate = value === undefined ? fallback : requireString(value, keyName);
  if (candidate.includes("\\")) {
    throw new Error(`${keyName} must use POSIX separators`);
  }
  const normalized = path.normalize(candidate);
  if (
    path.isAbsolute(candidate) ||
    normalized === ".." ||
    normalized.startsWith(`..${path.sep}`) ||
    normalized === "."
  ) {
    throw new Error(`${keyName} must be a relative path within rootDir`);
  }
  return normalized;
}

export function parseExternalWikiRoots(value: unknown, memoryDir?: string): ExternalWikiRoot[] {
  if (value === undefined) return [];
  if (!Array.isArray(value)) throw new Error("externalWikis must be an array");

  const seenIds = new Set<string>();
  return value.map((entry, index) => {
    const keyName = `externalWikis[${index}]`;
    const raw = requireObject(entry, keyName);
    const id = requireString(raw.id, `${keyName}.id`);
    if (!EXTERNAL_WIKI_ID_PATTERN.test(id)) {
      throw new Error(`${keyName}.id must match ${EXTERNAL_WIKI_ID_PATTERN}`);
    }
    if (seenIds.has(id)) throw new Error(`externalWikis contains duplicate id "${id}"`);
    seenIds.add(id);

    const includeInDefaultRecall = parseBoolean(raw.includeInDefaultRecall, false, `${keyName}.includeInDefaultRecall`);
    if (includeInDefaultRecall) {
      throw new Error(`${keyName}.includeInDefaultRecall=true is not supported yet`);
    }

    const rootDir = parseRootDir(raw.rootDir, `${keyName}.rootDir`);
    if (memoryDir !== undefined) {
      assertExternalWikiRootOutsideMemoryDir(memoryDir, rootDir);
    }

    const label = raw.label === undefined ? undefined : requireString(raw.label, `${keyName}.label`);
    return {
      id,
      rootDir,
      enabled: parseBoolean(raw.enabled, true, `${keyName}.enabled`),
      ...(label === undefined ? {} : { label }),
      pagesDir: parseRootRelativePath(raw.pagesDir, "wiki", `${keyName}.pagesDir`),
      indexFile: parseRootRelativePath(raw.indexFile, "INDEX.md", `${keyName}.indexFile`),
      indexInQmd: parseBoolean(raw.indexInQmd, false, `${keyName}.indexInQmd`),
      includeInDefaultRecall: false,
    };
  });
}

import { coerceBool } from "../connectors/coerce.js";
import type {
  ScopeProfileConfig,
  ScopeProfileLayerId,
  ScopeProfilePromotionTarget,
  ScopeTeamConfig,
} from "../types.js";

const SCOPE_PROFILE_LAYER_IDS = [
  "userProject",
  "teamProject",
  "userGlobal",
  "serverShared",
] as const satisfies readonly ScopeProfileLayerId[];
const SCOPE_PROFILE_PROMOTION_TARGETS = [
  ...SCOPE_PROFILE_LAYER_IDS,
] as const satisfies readonly ScopeProfilePromotionTarget[];
const SCOPE_PROFILE_AUTO_PROMOTE_CATEGORIES = [
  "fact",
  "correction",
  "decision",
  "preference",
  "rule",
  "procedure",
] as const;
const CONFIDENCE_TIERS = ["explicit", "implied", "inferred", "speculative"] as const;

type ConfidenceTier = (typeof CONFIDENCE_TIERS)[number];
type AutoPromoteCategory = (typeof SCOPE_PROFILE_AUTO_PROMOTE_CATEGORIES)[number];

function isConfidenceTier(value: unknown): value is ConfidenceTier {
  return typeof value === "string" && (CONFIDENCE_TIERS as readonly string[]).includes(value);
}

function isAutoPromoteCategory(value: unknown): value is AutoPromoteCategory {
  return typeof value === "string" && (SCOPE_PROFILE_AUTO_PROMOTE_CATEGORIES as readonly string[]).includes(value);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseStringList(value: unknown, keyName: string): string[] {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) {
    throw new Error(`${keyName} must be an array`);
  }
  const out: string[] = [];
  for (const entry of value) {
    if (typeof entry !== "string" || entry.length === 0) {
      throw new Error(`${keyName} must contain only non-empty strings`);
    }
    out.push(entry);
  }
  return out;
}

function parseScopeProfileLayerList(
  value: unknown,
  keyName: string,
  fallback: ScopeProfileLayerId[]
): ScopeProfileLayerId[] {
  if (value === undefined || value === null) return [...fallback];
  if (!Array.isArray(value)) {
    throw new Error(`${keyName} must be an array`);
  }
  const out: ScopeProfileLayerId[] = [];
  for (const entry of value) {
    if (!SCOPE_PROFILE_LAYER_IDS.includes(entry as ScopeProfileLayerId)) {
      throw new Error(`${keyName} contains unsupported layer: ${String(entry)}`);
    }
    if (!out.includes(entry as ScopeProfileLayerId)) {
      out.push(entry as ScopeProfileLayerId);
    }
  }
  return out;
}

function parseScopeProfilePromotionTargets(value: unknown, keyName: string): ScopeProfilePromotionTarget[] {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) {
    throw new Error(`${keyName} must be an array`);
  }
  const out: ScopeProfilePromotionTarget[] = [];
  for (const entry of value) {
    if (!SCOPE_PROFILE_PROMOTION_TARGETS.includes(entry as ScopeProfilePromotionTarget)) {
      throw new Error(`${keyName} contains unsupported target: ${String(entry)}`);
    }
    if (!out.includes(entry as ScopeProfilePromotionTarget)) {
      out.push(entry as ScopeProfilePromotionTarget);
    }
  }
  return out;
}

export function parseScopeProfiles(value: unknown): Record<string, ScopeProfileConfig> {
  if (value === undefined || value === null) return {};
  if (!isRecord(value)) {
    throw new Error("scopeProfiles must be an object");
  }
  const profiles: Record<string, ScopeProfileConfig> = {};
  for (const [profileId, rawProfile] of Object.entries(value)) {
    if (profileId.trim().length === 0) {
      throw new Error("scopeProfiles keys must not be empty");
    }
    if (!isRecord(rawProfile)) {
      throw new Error(`scopeProfiles.${profileId} must be an object`);
    }
    const readOrder = parseScopeProfileLayerList(rawProfile.readOrder, `scopeProfiles.${profileId}.readOrder`, [
      "userProject",
      "userGlobal",
      "serverShared",
    ]);
    const writeDefault =
      rawProfile.writeDefault === undefined || rawProfile.writeDefault === null
        ? "userProject"
        : rawProfile.writeDefault;
    if (!SCOPE_PROFILE_LAYER_IDS.includes(writeDefault as ScopeProfileLayerId)) {
      throw new Error(`scopeProfiles.${profileId}.writeDefault contains unsupported layer: ${String(writeDefault)}`);
    }
    if (rawProfile.teamProject !== undefined && rawProfile.teamProject !== null && !isRecord(rawProfile.teamProject)) {
      throw new Error(`scopeProfiles.${profileId}.teamProject must be an object`);
    }
    const teamProject = (() => {
      if (!isRecord(rawProfile.teamProject)) return undefined;
      const out: NonNullable<ScopeProfileConfig["teamProject"]> = {};
      if (rawProfile.teamProject.namespaceTemplate !== undefined) {
        if (
          typeof rawProfile.teamProject.namespaceTemplate !== "string" ||
          rawProfile.teamProject.namespaceTemplate.length === 0
        ) {
          throw new Error(`scopeProfiles.${profileId}.teamProject.namespaceTemplate must be a non-empty string`);
        }
        out.namespaceTemplate = rawProfile.teamProject.namespaceTemplate;
      }
      if (rawProfile.teamProject.teamId !== undefined) {
        if (typeof rawProfile.teamProject.teamId !== "string" || rawProfile.teamProject.teamId.length === 0) {
          throw new Error(`scopeProfiles.${profileId}.teamProject.teamId must be a non-empty string`);
        }
        out.teamId = rawProfile.teamProject.teamId;
      }
      return out;
    })();
    if (rawProfile.autoPromote !== undefined && rawProfile.autoPromote !== null && !isRecord(rawProfile.autoPromote)) {
      throw new Error(`scopeProfiles.${profileId}.autoPromote must be an object`);
    }
    const rawAutoPromote = isRecord(rawProfile.autoPromote) ? rawProfile.autoPromote : {};
    const hasAutoPromoteEnabled = Object.prototype.hasOwnProperty.call(rawAutoPromote, "enabled");
    const autoPromoteEnabled = coerceBool(rawAutoPromote.enabled);
    if (hasAutoPromoteEnabled && autoPromoteEnabled === undefined) {
      throw new Error(`scopeProfiles.${profileId}.autoPromote.enabled must be a boolean or boolean-like string`);
    }
    const minConfidenceTier = (() => {
      const rawTier = rawAutoPromote.minConfidenceTier;
      if (rawTier === undefined || rawTier === null) return "explicit";
      if (!isConfidenceTier(rawTier)) {
        throw new Error(
          `scopeProfiles.${profileId}.autoPromote.minConfidenceTier must be one of: ${CONFIDENCE_TIERS.join(", ")}`
        );
      }
      return rawTier;
    })();
    const autoPromoteCategories: AutoPromoteCategory[] = (() => {
      if (rawAutoPromote.categories === undefined || rawAutoPromote.categories === null) {
        return ["fact", "correction", "decision", "preference"];
      }
      if (!Array.isArray(rawAutoPromote.categories)) {
        throw new Error(`scopeProfiles.${profileId}.autoPromote.categories must be an array`);
      }
      const categories: AutoPromoteCategory[] = [];
      for (const entry of rawAutoPromote.categories) {
        if (!isAutoPromoteCategory(entry)) {
          throw new Error(
            `scopeProfiles.${profileId}.autoPromote.categories must contain only: ${SCOPE_PROFILE_AUTO_PROMOTE_CATEGORIES.join(", ")}`
          );
        }
        categories.push(entry);
      }
      return categories;
    })();
    profiles[profileId] = {
      readOrder,
      writeDefault: writeDefault as ScopeProfileLayerId,
      promotionTargets: parseScopeProfilePromotionTargets(
        rawProfile.promotionTargets,
        `scopeProfiles.${profileId}.promotionTargets`
      ),
      ...(teamProject && Object.keys(teamProject).length > 0 ? { teamProject } : {}),
      autoPromote: {
        enabled: autoPromoteEnabled === true,
        targets: parseScopeProfilePromotionTargets(
          rawAutoPromote.targets,
          `scopeProfiles.${profileId}.autoPromote.targets`
        ),
        categories: autoPromoteCategories,
        minConfidenceTier,
      },
    };
  }
  return profiles;
}

export function parseScopeTeams(value: unknown): Record<string, ScopeTeamConfig> {
  if (value === undefined || value === null) return {};
  if (!isRecord(value)) {
    throw new Error("teams must be an object");
  }
  const teams: Record<string, ScopeTeamConfig> = {};
  for (const [teamId, rawTeam] of Object.entries(value)) {
    if (teamId.trim().length === 0) {
      throw new Error("teams keys must not be empty");
    }
    if (!isRecord(rawTeam)) {
      throw new Error(`teams.${teamId} must be an object`);
    }
    const projectNamespaceTemplate = rawTeam.projectNamespaceTemplate;
    if (projectNamespaceTemplate !== undefined) {
      if (typeof projectNamespaceTemplate !== "string" || projectNamespaceTemplate.length === 0) {
        throw new Error(`teams.${teamId}.projectNamespaceTemplate must be a non-empty string`);
      }
    }
    teams[teamId] = {
      principals: parseStringList(rawTeam.principals, `teams.${teamId}.principals`),
      ...(projectNamespaceTemplate !== undefined ? { projectNamespaceTemplate } : {}),
      read: parseStringList(rawTeam.read, `teams.${teamId}.read`),
      write: parseStringList(rawTeam.write, `teams.${teamId}.write`),
      promote: parseStringList(rawTeam.promote, `teams.${teamId}.promote`),
    };
  }
  return teams;
}

export function validateScopeProfileTeamReferences(
  profiles: Record<string, ScopeProfileConfig>,
  teams: Record<string, ScopeTeamConfig>
): void {
  for (const [profileId, profile] of Object.entries(profiles)) {
    const teamId = profile.teamProject?.teamId;
    if (teamId && !Object.prototype.hasOwnProperty.call(teams, teamId)) {
      throw new Error(`scopeProfiles.${profileId}.teamProject.teamId references unknown team: ${teamId}`);
    }
  }
}

/**
 * Projection maintenance support (issue #2119) — helpers shared by the
 * scheduled projection rebuild, the CLI rebuild, and the ledger rebuild.
 * Lives beside the rebuild ops so the at-ceiling store/rebuild modules stay
 * within their structural ratchets.
 */

import path from "node:path";
import {
  openProjectionReadonly,
  readProjectedEntityMentions,
  readProjectedGovernanceRecord,
  readProjectedNativeKnowledgeChunks,
  type MemoryProjectionGovernanceAppliedActionRow,
  type MemoryProjectionGovernanceReviewQueueRow,
  type ProjectedEntityMentionRow,
  type ProjectedNativeKnowledgeChunkRow,
} from "../memory-projection-store.js";
import {
  isFrontmatterDerivedLifecycleEventType,
  memoryLifecycleEventProjectionIdentity,
} from "../memory-lifecycle-ledger-utils.js";
import type { MemoryLifecycleEvent } from "../types.js";
import type { BetterSqlite3Database } from "../runtime/better-sqlite.js";

/** Read the projection meta rebuiltAt timestamp; null when absent/unopenable. */
export function readProjectionRebuiltAt(memoryDir: string): string | null {
  const db = openProjectionReadonly(memoryDir);
  if (!db) return null;
  try {
    const row = db.prepare("SELECT value FROM meta WHERE key = 'rebuiltAt'").get() as
      | { value?: unknown }
      | undefined;
    return typeof row?.value === "string" && row.value.length > 0 ? row.value : null;
  } catch {
    return null;
  } finally {
    db.close();
  }
}

/** Format projection age description string for fallback warning telemetry. */
export function formatProjectionAge(rebuiltAt: string | null): string {
  if (!rebuiltAt) return "projection never rebuilt";
  const ageMs = Date.now() - Date.parse(rebuiltAt);
  if (!Number.isFinite(ageMs)) return `projection rebuiltAt=${rebuiltAt}`;
  const ageMin = Math.max(0, Math.round(ageMs / 60_000));
  const age = ageMin >= 120 ? `${Math.round(ageMin / 60)}h` : `${ageMin}m`;
  return `projection ${age} stale, last rebuilt ${rebuiltAt}`;
}

export interface ProjectionLifecycleLedgerHighWater {
  eventCount: number;
  sourceEventCount: number;
}

function readProjectionHighWaterFromDb(
  db: BetterSqlite3Database,
): ProjectionLifecycleLedgerHighWater | null {
  const sourceRow = db.prepare(
    "SELECT value FROM meta WHERE key = 'sourceLifecycleLedgerEventCount'",
  ).get() as { value?: unknown } | undefined;
  const projectedRow = db.prepare(
    "SELECT value FROM meta WHERE key = 'projectedLifecycleLedgerEventCount'",
  ).get() as { value?: unknown } | undefined;
  if (
    typeof sourceRow?.value !== "string"
    || !/^\d+$/.test(sourceRow.value)
    || typeof projectedRow?.value !== "string"
    || !/^\d+$/.test(projectedRow.value)
  ) return null;
  const sourceEventCount = Number(sourceRow.value);
  const eventCount = Number(projectedRow.value);
  if (!Number.isSafeInteger(sourceEventCount) || !Number.isSafeInteger(eventCount)) return null;
  return { eventCount, sourceEventCount };
}

export function readProjectionLifecycleLedgerHighWater(
  memoryDir: string,
): ProjectionLifecycleLedgerHighWater | null {
  const db = openProjectionReadonly(memoryDir);
  if (!db) return null;
  try {
    return readProjectionHighWaterFromDb(db);
  } catch {
    return null;
  } finally {
    db.close();
  }
}

export interface ProjectionLifecycleLedgerLagTracker {
  highWater: ProjectionLifecycleLedgerHighWater;
  record(event: MemoryLifecycleEvent): { unique: boolean; projected: boolean };
  close(): void;
}

export function openProjectionLifecycleLedgerLagTracker(
  memoryDir: string,
): ProjectionLifecycleLedgerLagTracker | null {
  const db = openProjectionReadonly(memoryDir);
  if (!db) return null;
  try {
    const highWater = readProjectionHighWaterFromDb(db);
    if (!highWater) {
      db.close();
      return null;
    }
    db.pragma("temp_store = FILE");
    db.exec(`
      CREATE TEMP TABLE projection_lag_current_identity (
        identity TEXT PRIMARY KEY
      ) WITHOUT ROWID;
    `);
    db.pragma("temp.cache_size = -1024");
    const insertCurrent = db.prepare(
      "INSERT OR IGNORE INTO projection_lag_current_identity(identity) VALUES (?)",
    );
    const findProjectedEvent = db.prepare(
      "SELECT 1 FROM memory_timeline WHERE event_id = ? LIMIT 1",
    );
    const findProjectedFrontmatterEvent = db.prepare(`
      SELECT 1
      FROM memory_timeline
      WHERE memory_id = ? AND event_type = ? AND timestamp = ?
      LIMIT 1
    `);
    return {
      highWater,
      record(event) {
        if (!event.memoryId.trim()) return { unique: false, projected: false };
        const identity = memoryLifecycleEventProjectionIdentity(event);
        const inserted = insertCurrent.run(identity);
        if (inserted.changes === 0) return { unique: false, projected: false };
        const projected = isFrontmatterDerivedLifecycleEventType(event.eventType)
          ? findProjectedFrontmatterEvent.get(event.memoryId, event.eventType, event.timestamp)
          : findProjectedEvent.get(event.eventId);
        return { unique: true, projected: projected !== undefined };
      },
      close: () => db.close(),
    };
  } catch {
    db.close();
    return null;
  }
}
/** Write the high-water ledger marker counts to projection meta store. */
export function writeProjectionMetaHighWater(
  insertMeta: { run: (key: string, value: string) => void },
  sourceLifecycleLedgerEventCount: number,
  timelineRows: MemoryLifecycleEvent[],
): void {
  insertMeta.run("sourceLifecycleLedgerEventCount", String(sourceLifecycleLedgerEventCount));
  insertMeta.run(
    "projectedLifecycleLedgerEventCount",
    String(new Set(timelineRows.map(memoryLifecycleEventProjectionIdentity)).size),
  );
}

export function readProjectedEntityMentionRows(
  memoryDir: string,
): { projectionExists: boolean; rows: ProjectedEntityMentionRow[] } {
  const rows = readProjectedEntityMentions(memoryDir);
  if (rows === null) return { projectionExists: false, rows: [] };
  return { projectionExists: true, rows };
}

export function readProjectedNativeKnowledgeRows(
  memoryDir: string,
): { projectionExists: boolean; rows: ProjectedNativeKnowledgeChunkRow[] } {
  const rows = readProjectedNativeKnowledgeChunks(memoryDir);
  if (rows === null) return { projectionExists: false, rows: [] };
  return { projectionExists: true, rows };
}

export function readProjectedGovernanceRows(memoryDir: string): {
  projectionExists: boolean;
  runId: string | null;
  summary: unknown;
  metrics: unknown;
  reviewQueueRows: MemoryProjectionGovernanceReviewQueueRow[];
  appliedActionRows: MemoryProjectionGovernanceAppliedActionRow[];
  report: string;
} {
  const record = readProjectedGovernanceRecord(memoryDir);
  if (record === null) {
    return {
      projectionExists: false,
      runId: null,
      summary: undefined,
      metrics: undefined,
      reviewQueueRows: [],
      appliedActionRows: [],
      report: "",
    };
  }
  return {
    projectionExists: true,
    runId: record.runId,
    summary: record.summary,
    metrics: record.metrics,
    reviewQueueRows: record.reviewQueueRows,
    appliedActionRows: record.appliedActionRows,
    report: record.report,
  };
}

/**
 * Assert an optionally injected storage (e.g. the daemon's live unlocked
 * secure-store instance) is rooted at `memoryDir`, and hand it back. Shared
 * by the projection and lifecycle-ledger rebuilds so the containment guard
 * cannot drift between them; callers construct their own StorageManager when
 * nothing was injected (keeps this module off the direct-storage-import
 * ratchet, issue #1533).
 */
export function assertInjectedStorageRooted<T extends { dir: string }>(
  label: string,
  memoryDir: string,
  injected: T | undefined,
): T | undefined {
  if (injected && path.resolve(injected.dir) !== path.resolve(memoryDir)) {
    throw new Error(
      `${label}: storage.dir (${injected.dir}) must match memoryDir (${memoryDir})`,
    );
  }
  return injected;
}

export interface SkippedDuplicateMemory {
  memoryId: string;
  keptPath: string;
  skippedPath: string;
}

export interface SkippedBlankIdMemory {
  path: string;
}
export interface SkippedDuplicateTimelineEvent {
  eventId: string;
  keptPath: string;
  skippedPath: string;
}

export interface SkippedBlankIdTimelineEvent {
  eventId: string;
  path: string;
}

/**
 * content-hash.ts — standalone content normalization + SHA-256 hashing.
 *
 * Extracted from `ContentHashIndex` (storage.ts) so correction modules and
 * other consumers can hash content WITHOUT importing the storage god file
 * (issue #1533 directStorageImports ratchet). The static methods on
 * `ContentHashIndex` delegate here to guarantee identical results.
 */

import { createHash } from "node:crypto";

/** Normalize content: preserve Unicode letters, marks, and numbers. */
export function normalizeContent(content: string): string {
  return content
    .normalize("NFC")
    .toLowerCase()
    .replace(/[^\p{L}\p{M}\p{N}\s]/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/** Normalize content with the pre-Unicode ASCII-only normalizer. */
export function normalizeLegacyContent(content: string): string {
  return content
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/** Compute the SHA-256 hash used by pre-Unicode content indexes. */
export function computeLegacyContentHash(content: string): string {
  return createHash("sha256").update(normalizeLegacyContent(content)).digest("hex");
}

/**
 * Return true only when a persisted legacy hash can be proved to identify the
 * same body under the current normalizer. Empty or changed legacy forms are
 * ambiguous and must not be promoted to a current identity.
 */
export function isUnambiguousLegacyContentHash(
  content: string,
  contentHash: string,
  currentNormalizedText: string = normalizeContent(content),
): boolean {
  const legacyNormalizedText = normalizeLegacyContent(content);
  return (
    legacyNormalizedText.length > 0 &&
    legacyNormalizedText === currentNormalizedText &&
    createHash("sha256").update(legacyNormalizedText).digest("hex") === contentHash
  );
}

/** Normalize content and compute SHA-256 hash. */
export function computeContentHash(content: string): string {
  return createHash("sha256").update(normalizeContent(content)).digest("hex");
}

/**
 * Shared preference-drift type surfaces (issue #2371).
 *
 * These live in the preferences module rather than in `types.ts` so the
 * cross-cutting fields drift detection introduces are declared next to the
 * subsystem that owns them, and `types.ts` composes them through `extends`
 * instead of growing another inline block.
 */

import type { DriftDetectionConfig } from "./drift-config.js";

/**
 * Drift verdict persisted on `preference` memories. `corroborated` is
 * deliberately NOT a member: a corroborated preference clears `driftState` and
 * stamps `lastCorroborated`, so the stored enum only carries a negative
 * verdict.
 */
export type MemoryDriftState = "stale" | "drifted";

/**
 * Derived drift provenance stamped by the scan AFTER a memory exists — never
 * supplied at compose time, which is why these fields stay outside the sealed
 * write envelope for exactly the reason `mw_success` / `mw_fail` do.
 *
 * Mixed into `MemoryFrontmatter`.
 */
export interface MemoryDriftProvenance {
  /**
   * `stale` means the lookback window held no corroborating evidence either
   * way; `drifted` means recent evidence pointed away from the preference and
   * a review item was opened. Absent means "not classified".
   */
  driftState?: MemoryDriftState;
  /** ISO 8601 timestamp of the last run that found corroborating evidence. */
  lastCorroborated?: string;
}

/**
 * Per-recall render hint, mixed into `QmdSearchResult`. Set by the
 * preference-drift recall stage when `driftDetection.annotateAfterDays` is on
 * and absent otherwise. Never persisted — this annotates one injection, it is
 * not memory state.
 */
export interface RecallDriftAnnotation {
  driftNote?: string;
}

/** Mixed into `PluginConfig`. */
export interface DriftDetectionSettings {
  driftDetection: DriftDetectionConfig;
}

/**
 * Frontmatter codec for the drift stamps. Lives here, beside the interface it
 * serializes, so `storage.ts` stays a caller rather than growing another
 * field-specific block.
 */
export function serializeDriftProvenance(fm: MemoryDriftProvenance): string[] {
  const lines: string[] = [];
  if (fm.driftState !== undefined) {
    // An unrecognized verdict on write is a caller bug that must surface, not
    // something to persist silently.
    if (fm.driftState !== "stale" && fm.driftState !== "drifted") {
      throw new Error(
        `serializeFrontmatter: invalid driftState ${JSON.stringify(fm.driftState)} — expected "stale" | "drifted"`,
      );
    }
    lines.push(`driftState: ${fm.driftState}`);
  }
  if (fm.lastCorroborated) lines.push(`lastCorroborated: ${fm.lastCorroborated}`);
  return lines;
}

/**
 * Read the drift stamps back. A hand-edited or unrecognized stored verdict
 * round-trips to `undefined` rather than poisoning recall damping — the same
 * policy the Memory Worth counters use for corrupt values.
 */
export function parseDriftProvenance(
  fm: Record<string, string | undefined>,
): MemoryDriftProvenance {
  return {
    driftState:
      fm.driftState === "stale" || fm.driftState === "drifted" ? fm.driftState : undefined,
    lastCorroborated: fm.lastCorroborated || undefined,
  };
}

import { AsyncLocalStorage } from "node:async_hooks";
import type { CaptureWriteLockBackoffLimits, CaptureWriteLockLimitSource } from "./capture-write-lock-backoff.js";
import type { StorageManager } from "./storage.js";

type CaptureLockOwner = Pick<StorageManager, "dir">;

const captureScope = new AsyncLocalStorage<{ storage: CaptureLockOwner; limits: CaptureWriteLockLimitSource }>();

export function withCaptureWriteLockBackoff<T>(
  storage: CaptureLockOwner,
  limits: CaptureWriteLockBackoffLimits,
  run: () => Promise<T>
): Promise<T> {
  return captureScope.run(
    {
      storage,
      limits: {
        captureWriteLockInitialDelayMs: limits.initialDelayMs,
        captureWriteLockMaxDelayMs: limits.maxDelayMs,
        captureWriteLockDeadlineMs: limits.deadlineMs,
      },
    },
    run
  );
}

export function scopedCaptureWriteLockLimits(storage: CaptureLockOwner): CaptureWriteLockLimitSource | undefined {
  const scope = captureScope.getStore();
  return scope?.storage === storage ? scope.limits : undefined;
}

/**
 * Verbatim-artifact keyword scan — extracted from `storage.ts` so the scan can
 * be made interruptible without growing that file (issue #2291).
 *
 * The scan re-tokenizes every stored artifact, and `fetchActiveArtifactsForNamespace`
 * repeats it with a growing fetch limit. On a large artifact tier that is long
 * enough to starve the event loop, which would stop a recall section deadline
 * from ever firing — so the loop yields periodically and observes cancellation.
 */

import { throwIfAborted } from "./abort-error.js";
import { yieldToEventLoop } from "./recall-qos.js";
import type { MemoryFile } from "./types.js";

const ARTIFACT_SEARCH_STOPWORDS = new Set([
  "a",
  "an",
  "and",
  "are",
  "as",
  "at",
  "be",
  "but",
  "by",
  "for",
  "from",
  "has",
  "have",
  "i",
  "in",
  "is",
  "it",
  "of",
  "on",
  "or",
  "that",
  "the",
  "this",
  "to",
  "was",
  "were",
  "with",
]);

/**
 * Artifacts scored between two yields. Small enough that a deadline observes a
 * sub-millisecond delay on a normal tier, large enough that the yields cost
 * nothing measurable relative to tokenizing that many documents.
 */
const ARTIFACT_SCAN_YIELD_INTERVAL = 256;

export function tokenizeArtifactSearchText(input: string): string[] {
  return input
    .toLowerCase()
    .split(/[^a-z0-9]+/i)
    .map((t) => t.trim())
    .filter((t) => t.length >= 2)
    .filter((t) => !ARTIFACT_SEARCH_STOPWORDS.has(t));
}

export interface ArtifactSearchOptions {
  abortSignal?: AbortSignal;
}

/**
 * Rank the artifact tier by how many query tokens each document contains, best
 * first.
 *
 * `loadArtifacts` is a thunk rather than a value so the two cheap early exits —
 * an already-cancelled caller, and a query with no searchable tokens — happen
 * BEFORE the tier is read. Reading it can mean a full recursive filesystem scan
 * on a cold cache, which a stopword-only query must never pay for.
 *
 * Yields to the event loop every `ARTIFACT_SCAN_YIELD_INTERVAL` documents and
 * checks the caller's signal there, so a pending recall section deadline can fire
 * mid-scan and an abandoned recall stops scanning instead of running to the end.
 */
export async function selectArtifactMatches(
  loadArtifacts: () => Promise<MemoryFile[]>,
  query: string,
  maxResults: number,
  options: ArtifactSearchOptions = {},
): Promise<MemoryFile[]> {
  throwIfAborted(options.abortSignal, "artifact search aborted");
  const tokens = tokenizeArtifactSearchText(query);
  if (tokens.length === 0) return [];

  const artifacts = await loadArtifacts();
  // The scan below never awaits real I/O, so this is the last chance to observe a
  // signal that fired while the tier was being read.
  throwIfAborted(options.abortSignal, "artifact search aborted");
  const hits: Array<{ score: number; memory: MemoryFile }> = [];
  let scanned = 0;
  for (const memory of artifacts) {
    scanned += 1;
    if (scanned % ARTIFACT_SCAN_YIELD_INTERVAL === 0) {
      await yieldToEventLoop();
      throwIfAborted(options.abortSignal, "artifact search aborted");
    }
    const indexedTokens = new Set(
      tokenizeArtifactSearchText(`${memory.content} ${(memory.frontmatter.tags ?? []).join(" ")}`),
    );
    let score = 0;
    for (const token of tokens) {
      if (indexedTokens.has(token)) score += 1;
    }
    if (score > 0) {
      hits.push({ score, memory });
    }
  }
  // Ties keep corpus order: the comparator returns 0 for equal scores rather
  // than an arbitrary sign, so repeated scans produce the same top-N.
  hits.sort((a, b) => b.score - a.score);
  return hits.slice(0, maxResults).map((h) => h.memory);
}

import { createHash } from "node:crypto";
import { lstat, realpath } from "node:fs/promises";
import path from "node:path";

export function encodeStoragePathSegment(value: string, fallback = "unknown"): string {
  const raw = value.length > 0 ? value : fallback;
  try {
    return encodeURIComponent(raw).replaceAll(".", "%2E");
  } catch {
    return `encoded-${storagePathHash(raw)}`;
  }
}

export function storagePathHash(value: string): string {
  return createHash("sha256").update(value).digest("hex").slice(0, 16);
}

export function encodeStoragePathSegmentWithHash(value: string, fallback = "unknown"): string {
  const raw = value.length > 0 ? value : fallback;
  return `${encodeStoragePathSegment(value, fallback)}--${storagePathHash(raw)}`;
}

export function isSafeLegacyPathSegment(value: string): boolean {
  return (
    value.length > 0 &&
    value !== "." &&
    value !== ".." &&
    !value.includes("/") &&
    !value.includes("\\")
  );
}

const DAILY_FILE_DATE = /^(\d{4}-\d{2}-\d{2})\.jsonl$/;

/**
 * True when `relativePath` is a daily partition, `<type>/<channel>/YYYY-MM-DD.jsonl`,
 * named for a UTC date before `minDate`. Daily transcript files are named for the
 * date they were written on, and an entry is written at or after its own
 * timestamp, so such a file cannot hold an entry stamped on or after `minDate`.
 * Only that three-component layout is a daily partition: a legacy
 * `<type>/<channelId>.jsonl` or a root-level file can have a date-shaped name
 * (a date-shaped channel id) without being one, so it is never reported as older
 * and callers always read it.
 */
export function isDailyFileDatedBefore(relativePath: string, minDate: string | undefined): boolean {
  const parts = relativePath.split(path.sep);
  const fileDate = parts.length === 3 ? DAILY_FILE_DATE.exec(parts[2])?.[1] : undefined;
  return minDate !== undefined && fileDate !== undefined && fileDate < minDate;
}

export function isPathInsideStorageRoot(rootAbs: string, targetAbs: string): boolean {
  const rel = path.relative(rootAbs, targetAbs);
  if (rel === "") return true;
  if (rel === "..") return false;
  if (rel.startsWith(`..${path.sep}`)) return false;
  if (path.isAbsolute(rel)) return false;
  return true;
}

export function resolvePathInsideStorageRoot(
  root: string,
  ...parts: string[]
): string {
  const rootAbs = path.resolve(root);
  const targetAbs = path.resolve(rootAbs, ...parts);
  if (!isPathInsideStorageRoot(rootAbs, targetAbs)) {
    throw new Error(`resolved storage path escapes root: ${targetAbs}`);
  }
  return targetAbs;
}

async function assertNoSymlinkInExistingPath(
  rootAbs: string,
  targetAbs: string,
): Promise<void> {
  let current = rootAbs;
  while (current !== path.dirname(current)) {
    const stat = await lstat(current).catch(() => null);
    if (stat !== null) {
      if (stat.isSymbolicLink()) {
        throw new Error(`storage path must not pass through a symlink: ${current}`);
      }
      break;
    }
    current = path.dirname(current);
  }

  const relative = path.relative(rootAbs, targetAbs);
  if (relative === "") return;

  current = rootAbs;
  for (const segment of relative.split(path.sep)) {
    current = path.join(current, segment);
    const stat = await lstat(current).catch(() => null);
    if (stat === null) return;
    if (stat.isSymbolicLink()) {
      throw new Error(`storage path must not pass through a symlink: ${current}`);
    }
  }
}

async function assertRealPathInsideStorageRoot(
  rootAbs: string,
  targetAbs: string,
): Promise<void> {
  const rootReal = await resolvePossiblyMissingRealPath(rootAbs);
  const targetReal = await resolvePossiblyMissingRealPath(targetAbs);
  if (!isPathInsideStorageRoot(rootReal, targetReal)) {
    throw new Error(`resolved storage path escapes root: ${targetAbs}`);
  }
}

async function resolvePossiblyMissingRealPath(absPath: string): Promise<string> {
  let existing = absPath;
  const suffix: string[] = [];
  while (existing !== path.dirname(existing)) {
    const stat = await lstat(existing).catch(() => null);
    if (stat !== null) break;
    suffix.unshift(path.basename(existing));
    existing = path.dirname(existing);
  }
  const existingReal = await realpath(existing).catch(() => existing);
  return suffix.length > 0 ? path.join(existingReal, ...suffix) : existingReal;
}

export async function resolveSafeStoragePath(
  root: string,
  ...parts: string[]
): Promise<string> {
  const rootAbs = path.resolve(root);
  const targetAbs = resolvePathInsideStorageRoot(rootAbs, ...parts);
  await assertNoSymlinkInExistingPath(rootAbs, targetAbs);
  await assertRealPathInsideStorageRoot(rootAbs, targetAbs);
  return targetAbs;
}

import type { MemoryFile } from "./types.js";

function sortSnapshotObject(_key: string, candidate: unknown): unknown {
  if (candidate === null || typeof candidate !== "object" || Array.isArray(candidate)) return candidate;
  return Object.keys(candidate)
    .sort()
    .reduce<Record<string, unknown>>((sorted, key) => {
      sorted[key] = (candidate as Record<string, unknown>)[key];
      return sorted;
    }, {});
}

export function createMemorySnapshot(memory: MemoryFile): string {
  return JSON.stringify([memory.frontmatter, memory.content], sortSnapshotObject);
}

import { log } from "./logger.js";

const PROJECTION_FALLBACK_WARN_INTERVAL_MS = 5 * 60_000;
export const PROJECTION_LEDGER_LAG_WARN_THRESHOLD_EVENTS = 100;
const projectionFallbackWarnedAt = new Map<string, number>();

export function assertMemoryFrontmatterId(
  fm: { id: string; category?: string; created?: string; entityRef?: string },
): void {
  if (typeof fm.id !== "string" || fm.id.trim().length === 0) {
    const context = [
      fm.category ? `category=${fm.category}` : null,
      fm.created ? `created=${fm.created}` : null,
      fm.entityRef ? `entityRef=${fm.entityRef}` : null,
    ].filter(Boolean).join(" ");
    throw new Error(
      `memory frontmatter id must not be blank${context ? ` (${context})` : ""}`,
    );
  }
}

export interface ProjectionLedgerLagTelemetry {
  projectedEvents: number;
  currentLedgerEvents: number;
  deltaEvents: number;
  warnThresholdEvents?: number;
}

export function warnProjectionFallback(
  memoryDir: string,
  consumer: string,
  detail?: () => string | undefined,
  ledgerLag?: ProjectionLedgerLagTelemetry,
): null {
  const fallback = `storage.${consumer}: memory projection absent or empty; falling back to full corpus`;
  const thresholdEvents = Math.max(
    0,
    Math.floor(ledgerLag?.warnThresholdEvents ?? PROJECTION_LEDGER_LAG_WARN_THRESHOLD_EVENTS),
  );
  const lag = ledgerLag
    ? `projected_events=${ledgerLag.projectedEvents} current_ledger_events=${ledgerLag.currentLedgerEvents} `
      + `delta_events=${ledgerLag.deltaEvents} threshold_events=${thresholdEvents} `
      + "fallback_action=full-ledger-scan"
    : undefined;

  if (ledgerLag && ledgerLag.deltaEvents <= thresholdEvents) {
    const suffix = [detail?.(), lag].filter(Boolean).join("; ");
    log.debug(`${fallback}${suffix ? ` (${suffix})` : ""}`);
    return null;
  }

  const key = `${memoryDir}\0${consumer}`;
  const now = Date.now();
  const warnedAt = projectionFallbackWarnedAt.get(key) ?? 0;
  if (now - warnedAt >= PROJECTION_FALLBACK_WARN_INTERVAL_MS) {
    projectionFallbackWarnedAt.set(key, now);
    const suffix = [detail?.(), lag].filter(Boolean).join("; ");
    log.warn(`${fallback}${suffix ? ` (${suffix})` : ""}`);
  }
  return null;
}

/** @internal Test seam (#2119): clear the fallback-warn rate-limit dedup map so
 *  a focused test can prove the once-per-interval spam suppression from a clean
 *  slate regardless of prior tests in the same process. */
export function __resetProjectionFallbackWarnSuppressionForTest(): void {
  projectionFallbackWarnedAt.clear();
}

import { statSync } from "node:fs";
import path from "node:path";
import type { TombstoneStoreOptions } from "../lifecycle/tombstones.js";
import type { MemoryFile } from "../types.js";

/**
 * Deps injected by `StorageManager.buildTombstoneStore` so this module owns no
 * storage-god-file imports (issue #1533 ratchet).
 */
export interface TombstoneMigrationSourceDeps {
  /** On-disk tombstone ledger path; its mtime scopes both caches below. */
  tombstonesPath: () => string;
  collectTombstoneMigrationPaths: () => Promise<string[]>;
  readParsedMemoriesFromPaths: (filePaths: string[], batchSize?: number) => Promise<MemoryFile[]>;
  storedContentIdentityCandidates: (content: string) => string[];
}

/**
 * Build the `sourceContentsForMemoryIds` callback `TombstoneStore` uses to
 * verify pre-Unicode rows against their retired source memories. The corpus
 * path snapshot and the resolved source-content map are memoized for one
 * ledger revision only (issue #2367): a peer process can create and retire a
 * legacy-format memory after this snapshot, and the staleness reload must
 * resolve the new row against a FRESH path list — otherwise the row stays
 * unverified (withheld from the lookup tiers) until restart.
 */
export function createTombstoneMigrationSourceContents(
  deps: TombstoneMigrationSourceDeps,
): NonNullable<TombstoneStoreOptions["sourceContentsForMemoryIds"]> {
  let sourcePathsPromise: Promise<string[]> | undefined;
  let sourceContentsByIdPromise: Promise<Map<string, readonly string[]>> | undefined;
  let ledgerMtimeMs: number | null = null;
  const dropCachesIfLedgerChanged = (): void => {
    let mtimeMs: number | null;
    try {
      mtimeMs = Math.floor(statSync(deps.tombstonesPath()).mtimeMs);
    } catch {
      return; // ENOENT / stat failure — keep whatever is cached.
    }
    if (mtimeMs === ledgerMtimeMs) return;
    ledgerMtimeMs = mtimeMs;
    sourcePathsPromise = undefined;
    sourceContentsByIdPromise = undefined;
  };
  return async (sourceMemoryIds) => {
    for (;;) {
      dropCachesIfLedgerChanged();
      // In-flight fills are bound to the ledger revision they started
      // against: if the ledger advances while a fill awaits, restart
      // against the fresh revision instead of publishing a cache built
      // from a stale path snapshot (issue #2367 review round 2).
      const revision = ledgerMtimeMs;
      const requested = new Set(sourceMemoryIds);
      const sourcePaths = await (sourcePathsPromise ??= deps.collectTombstoneMigrationPaths());
      if (ledgerMtimeMs !== revision) continue;
      const directPaths = sourcePaths.filter((filePath) =>
        requested.has(path.basename(filePath, ".md"))
      );
      const contents = new Map<string, readonly string[]>();
      for (const memory of await deps.readParsedMemoriesFromPaths(directPaths, 50)) {
        const id = memory.frontmatter.id;
        if (requested.has(id) && !contents.has(id)) {
          contents.set(id, deps.storedContentIdentityCandidates(memory.content));
        }
      }
      // Re-check after the direct-path read too: a concurrent drop during
      // that await must not let this call publish a fill built from the
      // stale snapshot into the freshly cleared slot (issue #2367 round 3).
      if (ledgerMtimeMs !== revision) continue;
      if (contents.size === requested.size) return contents;
      const fill = (sourceContentsByIdPromise ??= (async () => {
        const allContents = new Map<string, readonly string[]>();
        for (const memory of await deps.readParsedMemoriesFromPaths(sourcePaths, 50)) {
          const id = memory.frontmatter.id;
          if (!allContents.has(id)) {
            allContents.set(id, deps.storedContentIdentityCandidates(memory.content));
          }
        }
        return allContents;
      })());
      const allContents = await fill;
      if (ledgerMtimeMs !== revision) continue;
      for (const id of requested) {
        const content = allContents.get(id);
        if (content !== undefined) contents.set(id, content);
      }
      return contents;
    }
  };
}

