    const labelBoundaryLine =
      /^ {0,3}(?=\S)/.test(labelLine) ? labelLine.trimStart() : labelLine;
    return MARKDOWN_LINK_REFERENCE_LABEL.test(labelBoundaryLine);
  }
  if (!MARKDOWN_LINK_REFERENCE_DESTINATION_CONTINUATION.test(line)) return false;
  const previousLine = lines[index - 1]?.content ?? "";
  const previousBoundaryLine =
    /^ {0,3}(?=\S)/.test(previousLine) ? previousLine.trimStart() : previousLine;
  return MARKDOWN_LINK_REFERENCE_LABEL.test(previousBoundaryLine);
}

function isProfileTitleLine(lines: ProfileLine[], index: number, line: string): boolean {
  const titleLine = index === 0 && line.startsWith(UTF8_BOM) ? line.slice(1) : line;
  if (!PROFILE_TITLE.test(titleLine)) return false;
  const indentation = titleLine.length - titleLine.trimStart().length;
  if (indentation === 0 || index === 0) return true;
  const previousLine = lines[index - 1]?.content.trim() ?? "";
  return previousLine === ""
    ? !isNestedListContent(lines, index, indentation)
    : previousLine === "---" || previousLine === "...";
}

function findProfileTitleIndex(lines: ProfileLine[]): number {
  let titleIndex = -1;
  visitProfileMetadataLines(lines, (line, index) => {
    if (titleIndex >= 0) return;
    if (isProfileTitleLine(lines, index, line)) titleIndex = index;
  });
  return titleIndex;
}

function isSetextHeadingText(line: string): boolean {
  const withoutBom = line.startsWith(UTF8_BOM) ? line.slice(1) : line;
  const boundaryLine = withoutBom.trim();
  return (
    boundaryLine !== "" &&
    !MARKDOWN_HEADING.test(boundaryLine) &&
    !MARKDOWN_LIST_ITEM.test(boundaryLine) &&
    !MARKDOWN_BLOCK_QUOTE.test(boundaryLine) &&
    !MARKDOWN_THEMATIC_BREAK.test(boundaryLine) &&
    !isMarkdownLinkReferenceDefinition(boundaryLine) &&
    getFenceMarker(withoutBom) === null
  );
}

function isMetadataBoundary(
  line: string,
  htmlTerminator = false,
  allowSetext = true,
  allowParagraphListInterrupt = false,
  setextPreviousLine = "",
): boolean {
  const listPattern = allowParagraphListInterrupt
    ? MARKDOWN_LIST_ITEM_CAN_INTERRUPT
    : MARKDOWN_LIST_ITEM;
  const boundaryLine = /^ {0,3}(?=\S)/.test(line) ? line.trimStart() : line;
  const isSetextUnderline =
    !allowSetext &&
    MARKDOWN_SETEXT_UNDERLINE.test(boundaryLine) &&
    isSetextHeadingText(setextPreviousLine);
  return (
    line.trim() === "" ||
    MARKDOWN_HEADING.test(boundaryLine) ||
    listPattern.test(boundaryLine) ||
    (allowSetext && MARKDOWN_SETEXT_UNDERLINE.test(boundaryLine)) ||
    (MARKDOWN_THEMATIC_BREAK.test(boundaryLine) && !isSetextUnderline) ||
    MARKDOWN_BLOCK_QUOTE.test(boundaryLine) ||
    isMarkdownLinkReferenceDefinition(boundaryLine) ||
    isLastUpdatedHeader(line) ||
    getFenceMarker(line) !== null ||
    htmlTerminator
  );
}

function isStandaloneMetadataLine(
  lines: ProfileLine[],
  index: number,
  frontmatterEnd: number,
  htmlTerminatorIndexes: ReadonlySet<number>,
  fenceTerminatorIndexes: ReadonlySet<number>,
  standaloneHeaderIndexes: ReadonlySet<number>,
): boolean {
  const currentLine = lines[index]?.content ?? "";
  const currentWithoutBom = currentLine.startsWith(UTF8_BOM)
    ? currentLine.slice(1)
    : currentLine;
  const indentation = currentWithoutBom.length - currentWithoutBom.trimStart().length;
  const previousLine = lines[index - 1]?.content.trimEnd() ?? "";
  const nextLine = lines[index + 1]?.content.trimEnd() ?? "";
  const previousWithoutBom = previousLine.startsWith(UTF8_BOM)
    ? previousLine.slice(1)
    : previousLine;
  const nextWithoutBom = nextLine.startsWith(UTF8_BOM) ? nextLine.slice(1) : nextLine;
  const previousLinkReferenceBoundary = isMarkdownLinkReferenceDefinitionEnd(lines, index - 1);
  const previousMetadataBoundary =
    isCompletedIndentedCodeBlock(lines, index) ||
    previousLinkReferenceBoundary ||
    fenceTerminatorIndexes.has(index - 1) ||
    (isMetadataBoundary(
      previousWithoutBom,
      htmlTerminatorIndexes.has(index - 1),
    ) &&
      (!isLastUpdatedHeader(previousWithoutBom) || standaloneHeaderIndexes.has(index - 1)));
  const nextHtmlBlockBoundary = isHtmlBlockBoundary(
    lines,
    index + 1,
    htmlTerminatorIndexes,
  );
  const nextMetadataBoundary =
    nextHtmlBlockBoundary ||
    isMetadataBoundary(
      nextWithoutBom,
      htmlTerminatorIndexes.has(index + 1),
      false,
      true,
      currentWithoutBom,
    );
  const previousContainerMarker =
    !MARKDOWN_THEMATIC_BREAK.test(previousWithoutBom) &&
    (MARKDOWN_LIST_ITEM.test(previousWithoutBom) || MARKDOWN_BLOCK_QUOTE.test(previousWithoutBom));
  const nestedListContent =
    indentation > 0 && isNestedListContent(lines, index, indentation);
  const startsBlock =
    (index === 0 || index === frontmatterEnd + 1 || previousMetadataBoundary) &&
    !previousContainerMarker &&
    !nestedListContent;
  const endsBlock = index === lines.length - 1 || nextMetadataBoundary;
  const compactHeaderAfterTitle = isProfileTitleLine(lines, index - 1, previousWithoutBom);
  const compactHeaderAfterHeader =
    isLastUpdatedHeader(previousWithoutBom) && standaloneHeaderIndexes.has(index - 1);
  return startsBlock && (endsBlock || compactHeaderAfterTitle || compactHeaderAfterHeader);
}

function findProfileHeaderIndexes(lines: ProfileLine[]): number[] {
  const indexes: number[] = [];
  const frontmatterEnd = findFrontmatterEnd(lines);
  const htmlTerminatorIndexes = new Set<number>();
  const fenceTerminatorIndexes = new Set<number>();
  const standaloneHeaderIndexes = new Set<number>();
  visitProfileMetadataLines(
    lines,
    (line, index) => {
      if (
        isLastUpdatedHeader(line) &&
        isStandaloneMetadataLine(
          lines,
          index,
          frontmatterEnd,
          htmlTerminatorIndexes,
          fenceTerminatorIndexes,
          standaloneHeaderIndexes,
        )
      ) {
        indexes.push(index);
        standaloneHeaderIndexes.add(index);
      }
    },
    (index) => htmlTerminatorIndexes.add(index),
    (index) => fenceTerminatorIndexes.add(index),
  );
  return indexes;
}

function insertHeaderAfter(lines: ProfileLine[], index: number, header: string): void {
  const insertAt = index + 1;
  const ending = lines[index]?.ending || lines[insertAt]?.ending || "\n";
  if (lines[insertAt]?.content.trim() === "") {
    lines.splice(
      insertAt + 1,
      0,
      { content: header, ending },
      { content: "", ending },
    );
  } else {
    lines.splice(
      insertAt,
      0,
      { content: "", ending },
      { content: header, ending },
      { content: "", ending },
    );
  }
}

function prependHeader(lines: ProfileLine[], header: string): string {
  const frontmatterEnd = findFrontmatterEnd(lines);
  if (frontmatterEnd >= 0) {
    insertHeaderAfter(lines, frontmatterEnd, header);
    return renderProfileLines(lines);
  }
  const ending = lines[0]?.ending || "\n";
  if (lines[0]?.content.startsWith(UTF8_BOM)) {
    lines[0].content = lines[0].content.slice(1);
    lines.unshift(
      { content: `${UTF8_BOM}${header}`, ending },
      { content: "", ending },
    );
    return renderProfileLines(lines);
  }
  lines.unshift(
    { content: header, ending },
    { content: "", ending },
  );
  return renderProfileLines(lines);
}

export function renderProfileWithLastUpdated(content: string, updatedAt: string): string {
  const lines = parseProfileLines(content);
  const header = `*Last updated: ${updatedAt}*`;
  const titleIndex = findProfileTitleIndex(lines);
  const headerIndexes = findProfileHeaderIndexes(lines);

  if (headerIndexes.length > 0) {
    const firstHeaderIndex = headerIndexes[0];
    if (firstHeaderIndex === undefined) return renderProfileLines(lines);
    const canonicalIndex =
      titleIndex >= 0
        ? headerIndexes.find((index) => index > titleIndex) ?? firstHeaderIndex
        : firstHeaderIndex;
    const preserveBomAtFileStart = headerIndexes.some((index) =>
      lines[index].content.startsWith(UTF8_BOM),
    );
    const bomPrefix =
      canonicalIndex === 0 && lines[canonicalIndex].content.startsWith(UTF8_BOM)
        ? UTF8_BOM
        : "";
    lines[canonicalIndex].content = `${bomPrefix}${header}`;
    for (let index = headerIndexes.length - 1; index >= 0; index -= 1) {
      const headerIndex = headerIndexes[index];
      if (headerIndex === undefined || headerIndex === canonicalIndex) continue;
      lines.splice(headerIndex, 1);
    }
    if (preserveBomAtFileStart && !lines[0].content.startsWith(UTF8_BOM)) {
      lines[0].content = `${UTF8_BOM}${lines[0].content}`;
    }
    return renderProfileLines(lines);
  }

  if (titleIndex < 0) return prependHeader(lines, header);

  insertHeaderAfter(lines, titleIndex, header);
  return renderProfileLines(lines);
}

/**
 * OKF v0.1 profile frontmatter (issue #1946). `profile.md` gains a leading
 * frontmatter block so the memory directory is a conformant OKF knowledge
 * bundle; every reader strips it so the bytes injected into prompts are
 * unchanged. Line-scan based (no regex) per the regex-safety rule.
 */

/** Prepend the OKF block when enabled and not already present. No-op otherwise. */
export function withOkfProfileFrontmatter(content: string, timestamp: string, enabled: boolean): string {
  if (!enabled || stripOkfProfileFrontmatter(content) !== content) return content;
  return `---\ntype: Profile\ntitle: User Profile\ntimestamp: ${timestamp}\n---\n${content}`;
}

/**
 * Strip the OKF profile block from the start of `profile.md` content.
 * Only a leading block whose keys include `type: Profile` is removed, so
 * hand-written content without the marker round-trips byte-identically.
 */
export function stripOkfProfileFrontmatter(content: string): string {
  if (!content.startsWith("---\n") && !content.startsWith("---\r\n")) return content;
  const lines = content.split("\n");
  for (let index = 1; index < lines.length; index += 1) {
    const line = lines[index]!;
    if (line === "---" || line === "---\r") {
      return lines.slice(1, index).some((l) => l.startsWith("type: Profile"))
        ? lines.slice(index + 1).join("\n")
        : content;
    }
    if (line === "" || line === "\r" || line === "...") return content;
  }
  return content;
}

import path from "node:path";
import { serializeMutations, withHeldFileLock } from "../utils/serialize-mutations.js";

/**
 * Ports over the StorageManager surface the profile mutation domain needs.
 * Kept as ports so this module stays out of the storage.ts god-file (issue
 * #1533/#1995) while sharing ONE serialization domain per baseDir: the
 * `profile:<baseDir>` key is the in-process FIFO and `profile.md.lock` is the
 * cross-process gate, matching updateMetaSerialized's meta.json.lock shape
 * (bounded, fail-closed BEFORE any read/write, no LLM inside).
 */
export interface ProfileMutationPorts {
  readonly baseDir: string;
  readProfile(): Promise<string>;
  writeProfile(content: string): Promise<void>;
}

export type ProfileCommitOutcome = "committed" | "conflict";

function normalizeForDedup(s: string): string {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/**
 * Check if a new bullet is a fuzzy duplicate of any existing bullet.
 * Returns true if the new bullet should be skipped.
 */
function isFuzzyDuplicate(newNorm: string, existingNorms: string[]): boolean {
  for (const existing of existingNorms) {
    // Exact normalized match
    if (newNorm === existing) return true;

    // Containment check: shorter must be >60% length of longer
    const shorter = newNorm.length <= existing.length ? newNorm : existing;
    const longer = newNorm.length > existing.length ? newNorm : existing;
    if (shorter.length > 20 && shorter.length / longer.length > 0.6 && longer.includes(shorter)) {
      return true;
    }
  }
  return false;
}

async function appendToProfileUnlocked(ports: ProfileMutationPorts, updates: string[]): Promise<void> {
  // Filter out empty entries the LLM may return (persist screens strings already).
  updates = updates.filter((u) => u.trim().length > 0);
  if (updates.length === 0) return;
  const existing = await ports.readProfile();

  const existingNorms = (existing ? existing.split("\n") : [])
    .filter((l) => l.startsWith("- "))
    .map((l) => normalizeForDedup(l.slice(2).trim()));
  const newBullets = updates.filter((u) => {
    const norm = normalizeForDedup(u);
    return !isFuzzyDuplicate(norm, existingNorms);
  });
  if (newBullets.length === 0) return;

  await ports.writeProfile(
    existing
      ? existing.trimEnd() + "\n" + newBullets.map((b) => `- ${b}`).join("\n") + "\n"
      : ["# Behavioral Profile", "", ...newBullets.map((b) => `- ${b}`), ""].join("\n"),
  );
}

/**
 * Cross-process profile mutation domain: fail-closed `profile.md.lock` for the
 * brief mutation window only. Lock contention throws (`profile update skipped:
 * profile.md.lock not acquired`) — never a silent unlocked RMW; callers treat
 * it like a meta lock skip (retain and retry).
 */
async function withProfileMutationLock<T>(ports: ProfileMutationPorts, task: () => Promise<T>): Promise<T> {
  return withHeldFileLock(
    path.join(ports.baseDir, "profile.md.lock"),
    // Bounded: a profile RMW is a short read-merge-write, never a scan.
    { staleMs: 5_000, maxWaitMs: 2_000, pollMs: 50 },
    async (acquired) => {
      if (!acquired) {
        throw new Error(`profile update skipped: profile.md.lock not acquired (${ports.baseDir})`);
      }
      return task();
    },
  );
}

export async function appendToProfileSerialized(ports: ProfileMutationPorts, updates: string[]): Promise<void> {
  // Per-dir in-process chain, then the cross-process lock around the whole
  // RMW: serialized, the second append re-reads after the first's write.
  // Errors propagate: the extraction retry path retains the accepted turns.
  await serializeMutations(`profile:${ports.baseDir}`, () =>
    withProfileMutationLock(ports, () => appendToProfileUnlocked(ports, updates)),
  );
}

/**
 * Commit an LLM profile consolidation only if the profile is unchanged since
 * `baseline` was read; when a concurrent append landed during the LLM call,
 * return "conflict" and leave the file untouched (the append survives and the
 * line cap re-triggers consolidation on fresh data next pass). The LLM call
 * itself stays OUTSIDE this serialization domain; only this short
 * read-compare-write is serialized + locked.
 */
export async function commitConsolidatedProfileSerialized(
  ports: ProfileMutationPorts,
  baseline: string,
  consolidated: string,
): Promise<ProfileCommitOutcome> {
  return serializeMutations(`profile:${ports.baseDir}`, () =>
    withProfileMutationLock(ports, async () => {
      const current = await ports.readProfile();
      if (current !== baseline) return "conflict";
      await ports.writeProfile(consolidated);
      return "committed";
    }),
  );
}

/**
 * Question file format (issue #1946 extraction from storage.ts so the
 * surface file stays under its structural ceiling). Pure text parsing —
 * no filesystem, no caches; StorageManager delegates through so the
 * selfDeps consumers (MemoryReadStore) keep their seam unchanged.
 */
import path from "node:path";

export interface ParsedQuestionFile {
  id: string;
  question: string;
  context: string;
  priority: number;
  resolved: boolean;
  created: string;
  filePath: string;
}

export function parseQuestionFile(raw: string, filePath: string): ParsedQuestionFile | null {
  if (!raw.startsWith("---\n")) return null;
  const close = raw.indexOf("\n---\n\n", 4);
  if (close === -1) return null;
  const frontmatterStr = raw.slice(4, close);
  const body = raw.slice(close + 6).trim();

  const id = extractFrontmatterValue(frontmatterStr, "id") ?? path.basename(filePath, ".md");
  const created = extractFrontmatterValue(frontmatterStr, "created") ?? "";
  const priority = parseFloat(extractFrontmatterValue(frontmatterStr, "priority") ?? "0.5");
  const resolved = extractFrontmatterValue(frontmatterStr, "resolved") === "true";

  const contextMarker = "**Context:**";
  const contextAt = body.indexOf(contextMarker);
  const question = contextAt === -1 ? body : body.slice(0, contextAt).trim();
  const context = contextAt === -1 ? "" : body.slice(contextAt + contextMarker.length).trim();

  return { id, question, context, priority, resolved, created, filePath };
}

function extractFrontmatterValue(frontmatter: string, key: string): string | null {
  const prefix = `${key}:`;
  for (const line of frontmatter.split("\n")) {
    if (!line.startsWith(prefix)) continue;
    let value = line.slice(prefix.length).trim();
    if (value.startsWith('"') && value.endsWith('"') && value.length >= 2) {
      value = value.slice(1, -1);
    }
    return value;
  }
  return null;
}

/**
 * OKF v0.1 `type` mapping (issue #1946) — the single source of truth for
 * the inert `type` metadata emitted alongside Remnic's canonical fields.
 *
 * `category` remains the canonical internal field; `type` is
 * presentation/interop metadata for OKF consumers and NEVER overrides
 * `category` on parse (the parser reads `type` into its own field only).
 */
import path from "node:path";

/** OKF `type` values derived from Remnic memory categories. */
export const OKF_TYPE_BY_CATEGORY: Readonly<Record<string, string>> = Object.freeze({
  fact: "Memory Fact",
  decision: "Decision",
  preference: "Preference",
  commitment: "Commitment",
  relationship: "Relationship",
  principle: "Principle",
  moment: "Moment",
  skill: "Skill",
  correction: "Correction",
  rule: "Rule",
});

/** Fallback for categories not listed above (unknown/future categories). */
export const OKF_TYPE_FALLBACK = "Memory";

/** Stable domain seam over the category table (single mapping source, AGENTS.md pattern 9). */
export function okfTypeForCategory(category: string): string {
  return OKF_TYPE_BY_CATEGORY[category] ?? OKF_TYPE_FALLBACK;
}

/** Artifact memories report `Artifact` regardless of their storage category. */
export function okfTypeForMemory(fm: { category: string; artifactType?: string }): string {
  return fm.artifactType ? "Artifact" : okfTypeForCategory(fm.category);
}

/** OKF types for entity files, derived from the entity kind. */
export const OKF_TYPE_BY_ENTITY_KIND: Readonly<Record<string, string>> = Object.freeze({
  person: "Person",
  company: "Company",
  organization: "Organization",
  project: "Project",
  topic: "Topic",
  technology: "Technology",
  place: "Place",
  event: "Event",
});

/** Stable domain seam over the entity-kind table (single mapping source). */
export function okfTypeForEntityKind(kind: string | undefined): string {
  const normalized = kind?.trim().toLowerCase();
  return (normalized !== undefined && OKF_TYPE_BY_ENTITY_KIND[normalized]) || "Entity";
}

/** Fixed OKF types for non-memory bundle files. */
export const OKF_PROFILE_TYPE = "Profile";
export const OKF_QUESTION_TYPE = "Question";
export const OKF_DECISION_RECORD_TYPE = "Decision Record";
export const OKF_ARCHITECTURE_CARD_TYPE = "Architecture Card";
export const OKF_CODE_MODULE_TYPE = "Code Module";

/**
 * OKF §6/§7 reserve `index.md` and `log.md` for bundle-level files with a
 * different contract. Remnic never writes them (separate issue), and writes
 * targeting those basenames are rejected outright so a stray ID can never
 * shadow a reserved bundle file.
 */
export const OKF_RESERVED_BASENAMES: Readonly<Record<string, true>> = Object.freeze({
  "index.md": true,
  "log.md": true,
});

export function assertNotOkfReservedBasename(filePath: string): void {
  const basename = path.basename(filePath);
  if (OKF_RESERVED_BASENAMES[basename] === true) {
    throw new Error(
      `OKF reserved basename '${basename}' is not a valid memory file target (${filePath}); OKF §6/§7 reserves it for bundle-level files.`,
    );
  }
}

import type { ContextTransformTelemetryRecord } from "../active-context-transform.js";
import { readContextTransformRecordRowsFromLines, readMaybeEncryptedLines } from "./secure-line-reader.js";

export interface ContextTransformLedgerHost {
  memoryActionsPath: string;
  ensureDirectories(): Promise<void>;
  appendStorageSecureFile(path: string, payload: string): Promise<void>;
  readStorageSecureFile(path: string): Promise<string>;
}

export async function appendContextTransformRecords(
  host: ContextTransformLedgerHost,
  records: ContextTransformTelemetryRecord[],
): Promise<number> {
  if (records.length === 0) return 0;
  await host.ensureDirectories();
  await host.appendStorageSecureFile(
    host.memoryActionsPath,
    records.map((record) => `${JSON.stringify(record)}\n`).join(""),
  );
  return records.length;
}

export async function readContextTransformRecords(
  host: ContextTransformLedgerHost,
  limit = 200,
): Promise<ContextTransformTelemetryRecord[]> {
  const cappedLimit = Math.max(0, Math.floor(limit));
  if (cappedLimit === 0 || Number.isNaN(cappedLimit)) return [];
  try {
    const rows = await readContextTransformRecordRowsFromLines(
      readMaybeEncryptedLines(host.memoryActionsPath, () => host.readStorageSecureFile(host.memoryActionsPath)),
      cappedLimit,
    );
    return rows.map((row) => row.record);
  } catch {
    return [];
  }
}

import { createReadStream } from "node:fs";
import { lstat, open } from "node:fs/promises";
import { createInterface } from "node:readline";

import { isEncryptedFile, MAGIC_HEADER_SIZE } from "../secure-store/secure-fs.js";
import type { ContextTransformTelemetryRecord } from "../active-context-transform.js";
import type { MemoryActionEvent, MemoryLifecycleEvent } from "../types.js";

/**
 * Whole-file decrypt ceiling for encrypted state files. V8's max string length
 * is ~512MB; a decrypted body that approaches it throws an opaque
 * `Invalid string length` on every read (the 691MB lifecycle-ledger incident).
 * We refuse at a size comfortably under the cap and point the operator at the
 * compaction remedy instead of letting the runtime crash. Plaintext streaming
 * is unaffected at any size.
 */
export const STATE_FILE_MAX_DECRYPT_BYTES = 400 * 1024 * 1024;

/**
 * Stream plaintext files by line while preserving authenticated whole-file
 * reads for encrypted files. `maxDecryptBytes` bounds the whole-file decrypt:
 * when set, an encrypted file at/over it is refused before decryption with an
 * actionable error. The ceiling is OPT-IN so it applies ONLY to callers with a
 * compaction-backed remedy (the lifecycle ledger). Callers with no bounded
 * maintenance path — e.g. the memory-actions ledger — omit it and keep the
 * prior unbounded read (issue #1910).
 */
export async function* readMaybeEncryptedLines(
  filePath: string,
  readEncryptedFile: () => Promise<string>,
  maxDecryptBytes?: number,
): AsyncGenerator<string> {
  // Reject a symlink/FIFO/device BEFORE opening, matching the maintenance ledger
  // probe (probeEncryptedRegularFileHeader, #2033): opening a FIFO blocks until a
  // writer appears and a symlink would redirect the read outside our tree. An
  // ENOENT from the missing regular file propagates so callers keep their
  // absent-file → [] behavior (they catch ENOENT), exactly as a missing open did.
  const entryStat = await lstat(filePath);
  if (!entryStat.isFile()) {
    throw new Error(
      `refusing to read non-regular state file ${filePath} `
      + `(symlink/FIFO/device); opening it could block or escape containment (#2033)`,
    );
  }
  const file = await open(filePath, "r");
  const header = Buffer.alloc(MAGIC_HEADER_SIZE);
  try {
    const { bytesRead } = await file.read(header, 0, header.length, 0);
    if (isEncryptedFile(header.subarray(0, bytesRead))) {
      if (maxDecryptBytes !== undefined) {
        const { size } = await file.stat();
        if (size >= maxDecryptBytes) {
          throw new Error(
            `encrypted state file ${filePath} is ${size} bytes, at or over the ${maxDecryptBytes}-byte `
            + `whole-file decrypt limit. Run 'remnic rebuild-memory-lifecycle-ledger --write' (add `
            + `'--namespace <ns>' when the path is under namespaces/<ns>/state) or 'remnic doctor' to compact it.`,
          );
        }
      }
      yield* (await readEncryptedFile()).split("\n");
      return;
    }

    const input = createReadStream(filePath, {
      autoClose: false,
      encoding: "utf8",
      fd: file.fd,
      start: 0,
    });
    const lines = createInterface({ input, crlfDelay: Infinity });
    try {
      for await (const line of lines) yield line;
    } finally {
      lines.close();
    }
  } finally {
    await file.close();
  }
}

export async function readMemoryActionEventRowsFromLines(
  lines: AsyncIterable<string>,
  limit: number,
): Promise<Array<{ line: number; event: MemoryActionEvent }>> {
  const out: Array<{ line: number; event: MemoryActionEvent }> = [];
  let writeIndex = 0;
  let lineNumber = 0;
  for await (const row of lines) {
    lineNumber += 1;
    const line = row.trim();
    if (!line) continue;
    try {
      const parsed = JSON.parse(line) as Partial<MemoryActionEvent> & { recordKind?: unknown };
      // Ledger discriminated union (#2347): any row carrying a `recordKind`
      // belongs to another record family (e.g. context_transform) and must
      // be ignored here — the legacy parser stays strict for its own kind.
      if (parsed.recordKind !== undefined) continue;
      const outcome = parsed.outcome === "applied" || parsed.outcome === "skipped" || parsed.outcome === "failed"
        ? parsed.outcome
        : null;
      if (
        typeof parsed.timestamp === "string" &&
        typeof parsed.action === "string" &&
        outcome !== null
      ) {
        const entry = {
          line: lineNumber,
          event: { ...parsed, outcome } as MemoryActionEvent,
        };
        if (out.length < limit) {
          out.push(entry);
        } else {
          out[writeIndex] = entry;
          writeIndex = (writeIndex + 1) % limit;
        }
      }
    } catch {
      // Ignore malformed rows (fail-open).
    }
  }
  return writeIndex === 0 ? out : [...out.slice(writeIndex), ...out.slice(0, writeIndex)];
}

/**
 * Tail read for context-transform telemetry rows (#2347). Selects ONLY
 * records discriminated by `recordKind: "context_transform"` — the sibling
 * of `readMemoryActionEventRowsFromLines`, with the same O(limit) ring
 * buffer and line-number semantics. Malformed rows are skipped fail-open;
 * legacy action rows are never returned here.
 */
export async function readContextTransformRecordRowsFromLines(
  lines: AsyncIterable<string>,
  limit: number,
): Promise<Array<{ line: number; record: ContextTransformTelemetryRecord }>> {
  const out: Array<{ line: number; record: ContextTransformTelemetryRecord }> = [];
  let writeIndex = 0;
  let lineNumber = 0;
  for await (const row of lines) {
    lineNumber += 1;
    const line = row.trim();
    if (!line) continue;
    try {
      const parsed = JSON.parse(line) as Partial<ContextTransformTelemetryRecord>;
      if (
        parsed.recordKind === "context_transform" &&
        typeof parsed.timestamp === "string" &&
        typeof parsed.actionId === "string" &&
        typeof parsed.planHash === "string"
      ) {
        const entry = {
          line: lineNumber,
          record: parsed as ContextTransformTelemetryRecord,
        };
        if (out.length < limit) {
          out.push(entry);
        } else {
          out[writeIndex] = entry;
          writeIndex = (writeIndex + 1) % limit;
        }
      }
    } catch {
      // Ignore malformed rows (fail-open).
    }
  }
  return writeIndex === 0 ? out : [...out.slice(writeIndex), ...out.slice(0, writeIndex)];
}

/**
 * Validate that a parsed row carries every required lifecycle-event field.
 * Shared by the tail reader and the per-memory reader so both apply the EXACT
 * same fail-open guard as `readAllLifecycleEventsFromLedger` (`eventType` is any
 * string). Governance reads via `readMemoryLifecycleEvents(MAX_SAFE_INTEGER)`
 * must be byte-for-byte identical to `readAllMemoryLifecycleEvents`, so this
 * MUST NOT restrict `eventType` to a handled allow-list — an unknown type is
 * still admitted here and sorted deterministically by `lifecycleEventSortRank`
 * (issue #1910).
 */
function isValidLifecycleEventRow(
  parsed: Partial<MemoryLifecycleEvent>,
): parsed is MemoryLifecycleEvent {
  return (
    typeof parsed.eventId === "string" &&
    typeof parsed.memoryId === "string" &&
    typeof parsed.eventType === "string" &&
    typeof parsed.timestamp === "string" &&
    typeof parsed.actor === "string" &&
    typeof parsed.ruleVersion === "string"
  );
}

/**
 * Bounded min-heap that retains the `limit` rows that rank highest under
 * `compare`, breaking ties by append order (later rows win). Heap use is
 * O(limit); each row costs O(log limit). Used for the per-memory timeline
 * fallback, which must keep the last `limit` events in canonical
 * timestamp/event order — not merely the last `limit` appended rows.
 */
class BoundedLifecycleTopN {
  private readonly heap: Array<{ event: MemoryLifecycleEvent; seq: number }> = [];

  constructor(
    private readonly limit: number,
    private readonly compare: (a: MemoryLifecycleEvent, b: MemoryLifecycleEvent) => number,
  ) {}

  private less(
    a: { event: MemoryLifecycleEvent; seq: number },
    b: { event: MemoryLifecycleEvent; seq: number },
  ): boolean {
    const c = this.compare(a.event, b.event);
    return c !== 0 ? c < 0 : a.seq < b.seq;
  }

  add(event: MemoryLifecycleEvent, seq: number): void {
    const item = { event, seq };
    if (this.heap.length < this.limit) {
      this.heap.push(item);
      this.siftUp(this.heap.length - 1);
    } else if (this.heap.length > 0 && this.less(this.heap[0], item)) {
      this.heap[0] = item;
      this.siftDown(0);
    }
  }

  /** Kept rows in ascending canonical order (append order breaks ties). */
  drainSorted(): MemoryLifecycleEvent[] {
    return this.heap
      .slice()
      .sort((a, b) => (this.less(a, b) ? -1 : this.less(b, a) ? 1 : 0))
      .map((item) => item.event);
  }

  private siftUp(index: number): void {
    let i = index;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (!this.less(this.heap[i], this.heap[parent])) break;
      [this.heap[i], this.heap[parent]] = [this.heap[parent], this.heap[i]];
      i = parent;
    }
  }

  private siftDown(index: number): void {
    let i = index;
    const n = this.heap.length;
    for (;;) {
      const left = 2 * i + 1;
      const right = 2 * i + 2;
      let smallest = i;
      if (left < n && this.less(this.heap[left], this.heap[smallest])) smallest = left;
      if (right < n && this.less(this.heap[right], this.heap[smallest])) smallest = right;
      if (smallest === i) break;
      [this.heap[i], this.heap[smallest]] = [this.heap[smallest], this.heap[i]];
      i = smallest;
    }
  }
}

/**
 * Bounded tail read for lifecycle-event rows, mirroring
 * `readMemoryActionEventRowsFromLines`: heap use is O(limit) rather than
 * O(rows), no matter how large the ledger is. When `memoryId` is supplied,
 * only rows for that memory are considered, so the per-memory timeline
 * fallback never materializes the whole ledger either.
 *
 * Without `compare`, the retained rows are the last `limit` *appended* rows
 * (returned oldest→newest of that tail); callers apply
 * `sortMemoryLifecycleEvents` for canonical ordering. With `compare`, the
 * retained rows are the `limit` rows that rank highest under `compare` (ties
 * broken by append order), returned in ascending `compare` order — preserving
 * the prior "filter → canonical sort → last N" semantics without loading the
 * whole file.
 */
export async function readMemoryLifecycleEventsFromLines(
  lines: AsyncIterable<string>,
  limit: number,
  memoryId?: string,
  compare?: (a: MemoryLifecycleEvent, b: MemoryLifecycleEvent) => number,
  onEvent?: (event: MemoryLifecycleEvent) => void,
): Promise<MemoryLifecycleEvent[]> {
  if (limit <= 0) return [];
  const top = compare ? new BoundedLifecycleTopN(limit, compare) : null;
  const ring: MemoryLifecycleEvent[] = [];
  let writeIndex = 0;
  let seq = 0;
  for await (const row of lines) {
    const line = row.trim();
    if (!line) continue;
    try {
      const parsed = JSON.parse(line) as Partial<MemoryLifecycleEvent>;
      if (!isValidLifecycleEventRow(parsed)) continue;
      onEvent?.(parsed);
      if (memoryId !== undefined && parsed.memoryId !== memoryId) continue;
      if (top) {
        top.add(parsed, seq++);
      } else if (ring.length < limit) {
        ring.push(parsed);
      } else {
        ring[writeIndex] = parsed;
        writeIndex = (writeIndex + 1) % limit;
      }
    } catch {
      // Ignore malformed rows (fail-open).
    }
  }
  if (top) return top.drainSorted();
  return writeIndex === 0 ? ring : [...ring.slice(writeIndex), ...ring.slice(0, writeIndex)];
}

import path from "node:path";

export type OfflineSyncDigestCacheEntry = {
  statBytes: number;
  mtimeMs: number;
  ctimeMs: number;
  encrypted: boolean;
  sha256: string;
  bytes: number;
};

export function parseOfflineSyncDigestCache(raw: string): Map<string, OfflineSyncDigestCacheEntry> {
  const cache = new Map<string, OfflineSyncDigestCacheEntry>();
  const parsed = JSON.parse(raw) as unknown;
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return cache;
  const entries = (parsed as { entries?: unknown }).entries;
  if (!Array.isArray(entries)) return cache;
  for (const entry of entries) {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) continue;
    const record = entry as Record<string, unknown>;
    const cachePath = typeof record.path === "string" ? record.path : "";
    const statBytes = typeof record.statBytes === "number" ? record.statBytes : Number.NaN;
    const mtimeMs = typeof record.mtimeMs === "number" ? record.mtimeMs : Number.NaN;
    const ctimeMs = typeof record.ctimeMs === "number" ? record.ctimeMs : Number.NaN;
    const bytes = typeof record.bytes === "number" ? record.bytes : Number.NaN;
    const sha256 = typeof record.sha256 === "string" ? record.sha256 : "";
    const encrypted = record.encrypted === true;
    if (
      cachePath.length === 0 ||
      cachePath === ".." ||
      cachePath.startsWith("../") ||
      path.isAbsolute(cachePath) ||
      !Number.isFinite(statBytes) ||
      !Number.isFinite(mtimeMs) ||
      !Number.isFinite(ctimeMs) ||
      !Number.isFinite(bytes) ||
      !/^[a-f0-9]{64}$/i.test(sha256)
    ) {
      continue;
    }
    cache.set(cachePath, { statBytes, mtimeMs, ctimeMs, encrypted, sha256, bytes });
  }
  return cache;
}

// ---------------------------------------------------------------------------
// Shared serialized-mutation utilities for TOCTOU hotspots (issue #1524).
//
// Two complementary primitives that the namespace catalog (`queueCritical` +
// `withHeldCatalogLock`), the storage router's resolve-hook serialization, and
// the summary-snapshot writer each re-implement today:
//
//   1. `serializeMutations(key, task)` — keyed IN-PROCESS async serialization
//      that recovers after a rejection (CLAUDE.md rule #40). One failed task
//      never poisons the tasks queued behind it; the failed task's error is
//      still surfaced to ITS caller.
//
//   2. `withHeldFileLock(lockPath, opts, task)` — a held CROSS-PROCESS file
//      lock with replacement-safe stale breaking (the NG7Bg invariant from
//      #1506 round 28) and ownership-checked release.
//
// This is the UTILITY module only. Per-issue PR split: one PR for the utility
// + tests (this file), then one PR per adoption hotspot (catalog, router
// provenance, summary snapshot). No adoptions live here.
// ---------------------------------------------------------------------------

import { randomUUID } from "node:crypto";
import { link, mkdir, open, readFile, rename, stat, unlink, utimes } from "node:fs/promises";
import path from "node:path";
import { sleep } from "./sleep.js";

// ─────────────────────────────────────────────────────────────────────────────
// 1. serializeMutations — keyed async serialization with rejection recovery
// ─────────────────────────────────────────────────────────────────────────────

/**
 * One entry in the per-key serialization map. `tail` is the recovered promise
 * the next queued task chains off of; it never rejects (both settle handlers
 * swallow), so a prior task's failure can never break subsequent ones.
 */
interface MutationChainEntry {
  tail: Promise<void>;
}

/**
 * Instance-scoped keyed serializer. Holds the per-key chain map so that all
 * tasks queued under the same key on the SAME serializer run strictly in order.
 *
 * The map is instance-scoped (not module-level) so tests can construct a fresh
 * serializer per case and avoid cross-test contamination, and so adopters that
 * want isolation (e.g. one serializer per storage root) can have it. The free
 * {@link serializeMutations} export delegates to a single shared default
 * instance for callers that want process-wide serialization.
 */
export class MutationSerializer {
  private readonly chains = new Map<string, MutationChainEntry>();

  /**
   * Run `task` strictly after every other task already queued under `key` on
   * this serializer has settled.
   *
   * Rejection recovery (rule #40, mirroring the catalog's `queueCritical`):
   * if a prior task rejects, later tasks STILL RUN, while the rejecting task's
   * error is surfaced to ITS OWN caller. Concretely, the recovered tail is
   * `run.then(noop, noop)` — never a bare `.then(fn)`, which would let one
   * failure kill every queued task behind it.
   *
   * No unbounded growth: when a chain's last task settles and no newer task
   * chained onto it, its entry is deleted (the storage router's
   * `inFlightResolved` marker-then-clear discipline).
   */
  serialize<T>(key: string, task: () => Promise<T>): Promise<T> {
    if (typeof key !== "string" || key.length === 0) {
      throw new TypeError("MutationSerializer.serialize: key must be a non-empty string");
    }
    if (typeof task !== "function") {
      throw new TypeError("MutationSerializer.serialize: task must be a function returning a promise");
    }

    let entry = this.chains.get(key);
    if (!entry) {
      entry = { tail: Promise.resolve() };
      this.chains.set(key, entry);
    }

    // Chain this task off the prior tail. `tail.then(task)` runs task only once
    // the previous task has settled, preserving read-modify-write ordering.
    const run = entry.tail.then(task);

    // Recover the tail after a rejection so a failed task never poisons later
    // ones. Both handlers swallow; `run` still carries the original resolution
    // (or rejection) to THIS caller. This is the line a naive `.then(fn)`
    // implementation omits — see the "naive poison chain" prove-fail test.
    const recovered = run.then(settleNoop, settleNoop);
    entry.tail = recovered;

    // Self-cleaning: once our recovered tail settles, if no newer task chained
    // onto us the entry still points at `recovered` and is safe to delete. A
    // concurrent `serialize()` call enqueues synchronously and would have
    // replaced `entry.tail` BEFORE this microtask runs, so the identity check
    // is race-free (no newer task's entry can be wrongly removed).
    //
    // `recovered` cannot reject in correct operation (both handlers above
    // swallow) and the cleanup body cannot throw — but we attach a rejection
    // handler anyway so that IF the recovery invariant is ever broken, the
    // failure surfaces as a behavioral assertion (skipped tasks) rather than an
    // unhandled-rejection storm that masks which task failed. The handler is a
    // no-op: cleanup only runs on fulfillment.
    void recovered.then(
      () => {
        if (entry && entry.tail === recovered) {
          this.chains.delete(key);
        }
      },
      () => undefined,
    );

    return run;
  }

  /**
   * Test-only: the number of keys with a not-yet-cleaned chain. Used to assert
   * the no-unbounded-growth invariant. Not part of the public contract.
   */
  pendingKeysForTest(): number {
    return this.chains.size;
  }
}

/**
 * Recovery handler shared by both settle arms. Named (not inline
 * `() => undefined`) so the chain assignment stays self-documenting in stack
 * traces and the review-patterns poison-chain check can see the chain is
 * recovered, not bare `.then(fn)`.
 */
function settleNoop(): void {
  /* swallow — the original resolution/rejection is carried by `run` */
}

/**
 * Process-wide default serializer backing the free {@link serializeMutations}
 * export. Lazy so it is only created when first used (tests that construct
 * their own `MutationSerializer` pay nothing).
 */
let defaultSerializer: MutationSerializer | undefined;

/**
 * Free-function entry point (issue #1524 signature). Serializes `task` against
 * every other task queued under `key` across the whole process, via a shared
 * default {@link MutationSerializer}. For isolated/testable serialization,
 * construct a `MutationSerializer` directly.
 */
export function serializeMutations<T>(key: string, task: () => Promise<T>): Promise<T> {
  if (!defaultSerializer) defaultSerializer = new MutationSerializer();
  return defaultSerializer.serialize(key, task);
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. withHeldFileLock — cross-process held file lock with stale breaking
// ─────────────────────────────────────────────────────────────────────────────

/** Options for {@link withHeldFileLock}. */
export interface HeldFileLockOptions {
  /**
   * A lock whose mtime is older than this (in ms) is treated as a crashed
   * holder and broken. Required — there is no safe default, since the right
   * value depends on how long the guarded critical section can legitimately
   * run.
   */
  readonly staleMs: number;
  /**
   * Bounded acquisition: give up trying to acquire a busy lock after this long
   * (ms) and invoke `task(false)` best-effort WITHOUT holding the lock, rather
   * than blocking forever or crashing the primary op. Default 5000ms (matches
   * the namespace catalog's `REBUILD_LOCK_MAX_WAIT_MS`).
   */
  readonly maxWaitMs?: number;
  /**
   * Poll interval (ms) while waiting for a busy lock to clear. Default 50ms.
   */
  readonly pollMs?: number;
  /**
   * While WE hold the lock, refresh its mtime on this cadence (ms) so a
   * legitimately long task is not mistaken for a crashed holder and broken out
   * from under. Default `floor(staleMs / 3)` (at least 100ms), mirroring the
   * catalog heartbeat ratio. Must be comfortably below `staleMs`.
   */
  readonly heartbeatMs?: number;
  /**
   * Test seam (NG7Bg, #1506 round 28): fires AFTER a lock is judged stale and
   * BEFORE the re-verify + unlink, simulating a replacement lock being created
   * in the race window. No-op in production.
   */
  readonly onBeforeBreakStaleUnlinkForTest?: () => Promise<void> | void;
  /**
   * Test seam (codex P2): fires AFTER the release rename moves the lock to a
   * trash path and BEFORE the ownership re-verify/restore — simulating a third
   * contender acquiring the (now-empty) lockPath in the race window. No-op in
   * production. Used to prove the pre-check prevents the rename entirely.
   */
  readonly onAfterReleaseRenameForTest?: () => Promise<void> | void;
  /**
   * Test seam (#2033): fires inside {@link HeldFileLockController.refresh} AFTER
   * the ownership pre-check passes and BEFORE the `utimes` mtime bump —
   * simulating a peer that deletes the lock (making the bump throw) or replaces
   * it (a different owner the post-bump re-check must catch). No-op in
   * production; proves refresh reports LOST rather than clobbering a peer.
   */
  readonly onBeforeRefreshUtimesForTest?: () => Promise<void> | void;
  /**
   * Best-effort hook for non-fatal lock warnings (heartbeat refresh failure,
   * release-time ownership check failure). Never throws into the caller. If
   * omitted, warnings are swallowed (the lock is advisory; release/heartbeat
   * failures must never crash the guarded op).
   */
  readonly onLockWarning?: (message: string, err: unknown) => void;
}

/**
 * Control surface handed to a held-lock task so a long, CPU-bound critical
 * section can re-assert ownership immediately before its destructive write.
 */
export interface HeldFileLockController {
  /**
   * Re-verify THIS acquirer still owns the lock and, when it does, refresh the
   * lock's mtime. Returns `true` only while we still hold it.
   *
   * The timer heartbeat cannot fire while a synchronous, CPU-bound section
   * (a large parse/merge/sort/serialize) blocks the event loop, so a peer can
   * judge the lock stale, break it, and start its own write within the stale
   * window. A caller about to perform a destructive rewrite MUST call this
   * first: `false` means the lock was stale-broken/replaced and the caller MUST
   * abort rather than clobber the peer that now holds it; `true` also re-stamps
   * the mtime so the bounded write that immediately follows cannot itself be
   * judged stale mid-write. On the best-effort unlocked path (`acquired` was
   * `false`) this always resolves `false` — there is no lock to hold.
   */
  refresh(): Promise<boolean>;
  /**
   * Why the lock was not acquired. `timeout` means a busy peer consumed the
   * bounded wait; `error` means acquisition failed due to filesystem setup or
   * I/O and must not be retried as contention.
   */
  readonly failure?: "timeout" | "error";
}

/** Default bounded acquisition wait, mirroring the catalog. */
const DEFAULT_MAX_WAIT_MS = 5_000;
/** Default busy-lock poll interval, mirroring the catalog. */
const DEFAULT_POLL_MS = 50;
/** Floor for the derived heartbeat cadence. */
const MIN_HEARTBEAT_MS = 100;
/** Node's setTimeout/setInterval 32-bit signed-int ceiling (2^31 − 1 ms ≈ 24.8
 * days). Delays above this are silently clamped to 1ms by the Node timer, so
 * timer-backed options (pollMs, heartbeatMs) must be rejected at this boundary
 * (chatgpt-codex-connector P2). */
const MAX_TIMER_DELAY_MS = 2_147_483_647;

/** Internal handle for a lock we successfully acquired. */
interface HeldLock {
  readonly path: string;
  readonly ownerId: string;
}
type LockAcquisitionFailure = { readonly failure: "timeout" | "error" };

/**
 * Run `task` under an exclusive on-disk lock at `lockPath`.
 *
 * Cross-process mutex via `open(lockPath, "wx")` (atomic exclusive create).
 * While held, a heartbeat timer refreshes the lock's mtime so a legitimately
 * long task is not mistaken for a crashed holder and broken out from under. A
 * lock older than `opts.staleMs` is treated as stale and broken — but
 * REPLACEMENT-SAFE (NG7Bg): we capture the stale lock's identity (full content
 * line: `<pid> <owner-uuid> <iso>`) when judging it stale, then RE-READ and
 * RE-STAT immediately before `unlink`, deleting only if byte-identical AND
 * still stale. A replacement lock created in the window has a different owner
 * id / timestamp, so its content differs and is left untouched.
 *
 * `task` receives `acquired: boolean` — `true` when we hold the lock, `false`
 * when acquisition is unavailable. The controller's `failure` field
 * distinguishes a bounded busy-lock timeout from a permanent filesystem
 * acquisition error.
 * This explicit callback keeps the lock utility as the single lock home while
 * allowing callers to choose their timeout and failure policy.
 *
 * Release is ownership-checked: we only `unlink` a lock whose content still
 * identifies THIS acquirer (same owner id), so a replacement created after we
 * stopped heartbeating is never destroyed — mirroring the catalog's
 * `rebuildLockHeldBySelf`.
 *
 * ADOPTION NOTE: lock only the brief final read-merge-write window, never a
 * long scan — a scan-length lock makes concurrent writers time out and
 * silently drop work (catalog round 5, codex/cursor P2).
 */
export async function withHeldFileLock<T>(
  lockPath: string,
  opts: HeldFileLockOptions,
  task: (acquired: boolean, lock: HeldFileLockController) => Promise<T>,
): Promise<T> {
  if (typeof lockPath !== "string" || lockPath.length === 0) {
    throw new TypeError("withHeldFileLock: lockPath must be a non-empty string");
  }
  if (typeof opts?.staleMs !== "number" || !Number.isFinite(opts.staleMs) || opts.staleMs <= 0) {
    throw new TypeError(
      `withHeldFileLock: opts.staleMs must be a positive finite number ` +
        `(valid range: > 0 ms, finite; got ${formatInvalidNumber(opts?.staleMs)}).`,
    );
  }

  // Validate optional timings: a NaN/Infinity here is a real hazard (e.g.
  // `Date.now() + NaN` === NaN, so `Date.now() >= deadline` is always false and
  // the bounded acquire loop would wait forever instead of falling back to
  // best-effort). Reject invalid input rather than silently defaulting it
  // (codex P2 review). Omitting an option still picks its default.
  const maxWaitMs = optionalPositiveMs(opts.maxWaitMs, "maxWaitMs", DEFAULT_MAX_WAIT_MS, MAX_TIMER_DELAY_MS);
  const pollMs = optionalPositiveMs(opts.pollMs, "pollMs", DEFAULT_POLL_MS, MAX_TIMER_DELAY_MS);
  const heartbeatMs = optionalPositiveMs(
    opts.heartbeatMs,
    "heartbeatMs",
    Math.max(MIN_HEARTBEAT_MS, Math.floor(opts.staleMs / 3)),
    MAX_TIMER_DELAY_MS,
  );
  if (heartbeatMs >= opts.staleMs) {
    throw new TypeError(
      `withHeldFileLock: heartbeatMs (${heartbeatMs}) must be below staleMs (${opts.staleMs}) ` +
        `(valid range: > 0 and < staleMs ms) so at least one heartbeat lands per stale window.`,
    );
  }
  if (heartbeatMs > MAX_TIMER_DELAY_MS) {
    throw new TypeError(
      `withHeldFileLock: derived heartbeatMs (${heartbeatMs} = floor(staleMs/3)) exceeds ` +
        `Node's setTimeout ceiling (${MAX_TIMER_DELAY_MS} ms). Use an explicit opts.heartbeatMs ` +
        `at or below ${MAX_TIMER_DELAY_MS} ms.`,
    );
  }
  // Wrap the consumer's warning hook so a throwing callback never turns a
  // non-fatal advisory lock warning into an unhandled rejection (heartbeat
  // catch handler) or overrides the task's result (release path). The option
  // is documented as never throwing into the caller; enforce that here
  // (codex P2 review).
  const rawWarn = opts.onLockWarning;
  const warn = (message: string, err: unknown): void => {
    if (!rawWarn) return;
    try {
      rawWarn(message, err);
    } catch {
      /* swallow — a throwing advisory hook must not crash the guarded op */
    }
  };

  // Per-call owner identity. Two withHeldFileLock calls in the SAME process
  // get different ids, so neither mistakes the other's lock for its own
  // (stronger than the catalog's per-instance id, which is what we want for a
  // stateless utility).
  const ownerId = randomUUID();
  const lockDir = path.dirname(lockPath);

  const acquisition = await acquireLock(lockPath, lockDir, ownerId, opts, maxWaitMs, pollMs);
  if ("failure" in acquisition) {
    return task(false, { refresh: async () => false, failure: acquisition.failure });
  }
  const held = acquisition;

  // Heartbeat: while WE hold the lock, refresh its mtime so age-based stale
  // detection sees an active holder and does not break us out from under
  // (catalog round 5). Failures are swallowed (advisory lock); the timer is
  // always cleared in the finally.
  //
  // OWNERSHIP CHECK (codex P2): if our event loop was paused long enough that
  // another process judged us stale, broke our lock, and created a replacement,
  // we must NOT refresh the replacement's mtime — that would keep a (possibly
  // crashed) replacement looking fresh. Verify lockHeldBySelf before each
  // utimes; if ownership is lost, stop heartbeating (our lock is gone).
  const heartbeat = setInterval(() => {
    lockHeldBySelf(held)
      .then((ours) => {
        if (!ours) return; // broken/replaced — stop refreshing
        return utimes(held.path, new Date(), new Date());
      })
      .catch((err: unknown) => {
        warn("withHeldFileLock heartbeat refresh failed", err);
      });
  }, heartbeatMs);
  // Don't keep the event loop alive solely for the heartbeat.
  heartbeat.unref?.();
  const controller: HeldFileLockController = {
    refresh: () => refreshHeldLock(held, warn, opts.onBeforeRefreshUtimesForTest),
  };
  try {
    return await task(true, controller);
  } finally {
    clearInterval(heartbeat);
    await releaseLock(held, warn, opts.onAfterReleaseRenameForTest);
  }
}

/**
 * Resolve an optional millisecond timing option, REJECTING invalid values
 * (NaN, Infinity, non-positive, or above `maxMs`) rather than silently defaulting
 * them. A NaN or Infinity maxWaitMs would make the bounded acquire loop wait
 * forever (`Date.now() + NaN` is NaN); a non-positive poll/heartbeat makes no
 * sense. Timer-backed options (pollMs, heartbeatMs) are bounded to Node's
 * setTimeout ceiling (`MAX_TIMER_DELAY_MS`): a value above 2^31−1 is silently
 * clamped to 1ms by the timer, turning a typo into tight polling (codex P2).
 * Omitting the option (`undefined`) picks `fallback`. Non-number types are also
 * rejected (defensive against config/env coercion).
 */
function optionalPositiveMs(
  value: number | undefined,
  name: "maxWaitMs" | "pollMs" | "heartbeatMs",
  fallback: number,
  maxMs: number,
): number {
  if (value === undefined) return fallback;
  if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) {
    throw new TypeError(
      `withHeldFileLock: opts.${name} must be a positive finite number ` +
        `(valid range: > 0 ms, finite; got ${formatInvalidNumber(value)}). ` +
        `Omit the option to use the default of ${fallback} ms.`,
    );
  }
  if (value > maxMs) {
    throw new TypeError(
      `withHeldFileLock: opts.${name} (${value} ms) exceeds the ${maxMs} ms ` +
        `ceiling (Node's setTimeout clamps larger delays to 1ms, turning a ` +
        `typo into tight polling). Omit the option to use the default of ${fallback} ms.`,
    );
  }
  return value;
}

/**
 * Human-readable label for a rejected numeric input. Makes the error message
 * immediately actionable for NaN/Infinity (which print as "NaN"/"Infinity" via
 * String() but are easier to triage with an explicit sign), and surfaces the
 * actual type for non-number values (defensive against config/env coercion).
 */
function formatInvalidNumber(value: unknown): string {
  if (typeof value === "number") {
    if (Number.isNaN(value)) return "NaN";
    if (value === Infinity) return "+Infinity";
    if (value === -Infinity) return "-Infinity";
    return String(value);
  }
  return `${typeof value} ${JSON.stringify(value)}`;
}

/**
 * Atomically create the lock file, looping until acquired or the bounded
 * deadline. Reports `timeout` for a busy lock and `error` for permanent
 * filesystem setup/I/O failures so callers can choose the safe policy.
 */
async function acquireLock(
  lockPath: string,
  lockDir: string,
  ownerId: string,
  opts: HeldFileLockOptions,
  maxWaitMs: number,
  pollMs: number,
): Promise<HeldLock | LockAcquisitionFailure> {
  try {
    await mkdir(lockDir, { recursive: true });
  } catch {
    // Lock-directory setup failure is a permanent acquisition error.
    return { failure: "error" };
  }
  const deadline = Date.now() + maxWaitMs;
  for (;;) {
    try {
      const handle = await open(lockPath, "wx");
      let wroteMeta = true;
      try {
        await handle.writeFile(`${process.pid} ${ownerId} ${new Date().toISOString()}\n`, "utf8");
      } catch {
        // The metadata write failed; the lock file may be empty or partial.
        // Our ownership check on release would NOT find this ownerId, leaving
        // a malformed lock that lingers until stale and blocks other callers
        // out of the mutex (codex P2). Undo our exclusive create and report
        // acquisition failure so the caller runs best-effort instead.
        wroteMeta = false;
      } finally {
        try {
          await handle.close();
        } catch {
          // close() can report a deferred I/O error (e.g. write that appeared
          // to succeed but failed on flush). The lock file may be malformed —
          // treat it as a metadata-write failure so the cleanup path unlinks
          // the orphaned lock (codex P2 review).
          wroteMeta = false;
        }
      }
      if (!wroteMeta) {
        await unlink(lockPath).catch(() => undefined);
        return { failure: "error" };
      }
      return { path: lockPath, ownerId };
    } catch (err) {
      if ((err as NodeJS.ErrnoException | undefined)?.code !== "EEXIST") {
        // Unexpected filesystem errors are permanent acquisition failures.
        return { failure: "error" };
      }
      // Lock exists: break it if stale, then poll. breakStaleLock is
      // replacement-safe (NG7Bg) and never throws.
      await breakStaleLock(lockPath, opts.staleMs, opts.onBeforeBreakStaleUnlinkForTest);
      if (Date.now() >= deadline) return { failure: "timeout" };
      // Cap the sleep to the remaining budget so a large pollMs cannot block
      // acquisition far past maxWaitMs (e.g. maxWaitMs=1000, pollMs=60000
      // would otherwise block ~60s instead of 1s — codex P2).
      await sleep(Math.min(pollMs, deadline - Date.now()));
    }
  }
}

/**
 * Replacement-safe stale-lock breaking (NG7Bg, #1506 round 28). Capture the
 * lock's identity when judging it stale, then ATOMICALLY rename it to a unique
 * trash path and verify the moved content matches. A replacement lock created
 * in the race window is either left untouched (different identity at
 * lockPath, so the rename moves the stale lock — not the replacement) or
 * restored (if the rename accidentally moves a replacement, the verify
 * detects the mismatch and renames it back).
 *
 * ATOMICITY (codex P2): `rename` is atomic on POSIX — only ONE contender can
 * successfully rename a given file. This eliminates the TOCTOU between the
 * identity/stat checks and the deletion that a bare `unlink` leaves open:
 * without rename, contender A could verify identity X, pause, then unlink
 * contender B's freshly acquired replacement Y. With rename, A moves whatever
 * is at lockPath, then checks: if it is X, A broke the stale lock; if it is
 * not X (a replacement appeared between A's last check and the rename), A
 * restores it.
 */
async function breakStaleLock(
  lockPath: string,
  staleMs: number,
  onBeforeBreakStaleUnlinkForTest: (() => Promise<void> | void) | undefined,
): Promise<void> {
  let staleIdentity: string;
  try {
    const info = await stat(lockPath);
    if (Date.now() - info.mtimeMs <= staleMs) {
      // Not stale (a live holder's heartbeat keeps it fresh) — leave it.
      return;
    }
    staleIdentity = await readFile(lockPath, "utf8");
  } catch {
    // Lock vanished (released by holder) or stat/read failed — nothing to do.
    return;
  }
  // Test seam: simulate a replacement lock being created in the race window
  // between the staleness judgment and the atomic break. No-op in production.
  if (onBeforeBreakStaleUnlinkForTest) {
    await onBeforeBreakStaleUnlinkForTest();
  }
  try {
    // Re-validate immediately before breaking: the lock must still carry the
    // SAME identity AND still be stale.
    const current = await readFile(lockPath, "utf8");
    if (current !== staleIdentity) return; // replaced — leave the fresh lock
    const recheck = await stat(lockPath);
    if (Date.now() - recheck.mtimeMs <= staleMs) return; // heartbeat refreshed it

    // ATOMIC BREAK: rename is atomic on POSIX. Only one contender succeeds;
    // others get ENOENT (the file is already gone). After the rename, verify
    // the moved content: if it matches staleIdentity we broke the right lock;
    // if it does not, a replacement appeared in the window and we restore it.
    const trashPath = `${lockPath}.breaking.${process.pid}.${Date.now()}`;
    await rename(lockPath, trashPath);
    try {
      const moved = await readFile(trashPath, "utf8");
      if (moved !== staleIdentity) {
        // We accidentally moved a replacement lock (created between our last
        // check and the rename). Restore it so the replacement holder's lock
        // survives. Use link (not rename) to AVOID overwriting a fresh lock
        // that a third contender may have acquired at lockPath while the file
        // was in trash: link fails with EEXIST if lockPath exists, leaving
        // the third contender's lock intact (codex P2 review).
        try {
          await link(trashPath, lockPath);
          // link succeeded — remove the redundant trash hard link. The lock
          // now lives only at lockPath.
          await unlink(trashPath).catch(() => undefined);
        } catch {
          // lockPath already exists (a third contender acquired it). Do NOT
          // unlink the moved file — it may be a LIVE lock whose holder is
          // still in its critical section. Destroying it would leave the
          // holder running with no visible lock, breaking mutual exclusion
          // (codex P2). Leave it in trash as a breadcrumb; it is not at
          // lockPath so it does not block other contenders.
        }
      } else {
        // Content matches — but verify the moved file is STILL stale. The
        // original holder may have resumed and heartbeated between our
        // pre-rename stat() and the rename, refreshing the mtime. If so, the
        // holder is live: restore the lock instead of deleting it (codex P2).
        const movedStat = await stat(trashPath);
        if (Date.now() - movedStat.mtimeMs <= staleMs) {
          // Mtime was refreshed — the holder resumed. Restore the lock.
          try {
            await link(trashPath, lockPath);
            await unlink(trashPath).catch(() => undefined);
          } catch {
            // lockPath already exists — another contender acquired it. Do NOT
            // unlink the moved file (it may be a live lock). Leave it in trash.
          }
        } else {
          // Still stale — we broke the right lock. Clean up the trash.
          await unlink(trashPath).catch(() => undefined);
        }
      }
    } catch {
      // Could not read the trash file — clean it up best-effort.
      await unlink(trashPath).catch(() => undefined);
    }
  } catch {
    // The lock changed/vanished between checks — another process handled it.
  }
}

/**
 * Release the lock ONLY if its content still identifies THIS acquirer (same
 * owner id). Two-stage ownership check:
 *
 *   1. PRE-CHECK (chatgpt-codex-connector P2): read lockPath BEFORE renaming.
 *      If the lock is already a replacement (a contender broke our stale lock),
 *      return WITHOUT renaming — renaming a replacement out of lockPath leaves
 *      it empty, letting a third contender acquire while the replacement holder
 *      is still active. The replacement is safe at lockPath; leave it alone.
 *
 *   2. ATOMIC CLAIM: if the pre-check saw our ownerId, rename lockPath→trash
 *      (POSIX-atomic) and re-verify on the moved file. A replacement could
 *      appear between the pre-check and the rename; if the moved file is no
 *      longer ours, restore it via link (non-overwriting). This ties the
 *      ownership check to the deletion so a bare readFile-then-unlink TOCTOU
 *      cannot delete a fresh replacement (codex P2).
 */
async function releaseLock(
  held: HeldLock,
  warn: (message: string, err: unknown) => void,
  onAfterReleaseRenameForTest: (() => Promise<void> | void) | undefined,
): Promise<void> {
  try {
    // PRE-CHECK (chatgpt-codex-connector P2): read lockPath before renaming. If
    // the lock is no longer ours, a contender broke our stale lock and created a
    // replacement. Return WITHOUT renaming — renaming the replacement out of
    // lockPath leaves it empty, so a third contender could acquire while the
    // replacement holder is still active. The replacement is safe at lockPath.
    let precheck: string;
    try {
      precheck = await readFile(held.path, "utf8");
    } catch {
      return; // lock vanished — nothing to release.
    }
    if (!precheck.includes(held.ownerId)) {
      return; // replacement lock — leave it untouched for its holder.
    }
    // It was ours when we read it. Atomically claim via rename, then re-verify
    // on the moved file: a replacement could appear between the pre-check read
    // above and this rename.
    const trashPath = `${held.path}.releasing.${process.pid}.${Date.now()}`;
    await rename(held.path, trashPath);
    // Test seam: simulate a third contender acquiring the now-empty lockPath
    // in the rename-to-restore window. No-op in production.
    if (onAfterReleaseRenameForTest) {
      await onAfterReleaseRenameForTest();
    }
    try {
      const moved = await readFile(trashPath, "utf8");
      if (moved.includes(held.ownerId)) {
        // Still our lock — safe to delete.
        await unlink(trashPath).catch(() => undefined);
      } else {
        // Not ours: a replacement appeared between the pre-check and the rename.
        // Restore it via link (non-overwriting — if lockPath already has a newer
        // lock, leave it).
        try {
          await link(trashPath, held.path);
        } catch {
          // lockPath already exists — a newer holder is active. Leave the
          // moved file in trash rather than destroying a live lock (codex P2).
          return;
        }
        await unlink(trashPath).catch(() => undefined);
      }
    } catch {
      // Could not read the moved file — clean it up best-effort.
      await unlink(trashPath).catch(() => undefined);
    }
  } catch (err) {
    // Best-effort release; a stale lock will be broken on the next acquire.
    warn("withHeldFileLock release failed", err);
  }
}

/**
 * Whether the lock file at `held.path` was written by THIS acquirer (same owner
 * id). Reads the content and matches the `<pid> <owner-uuid>` prefix; the iso
 * timestamp varies so it is not part of the identity check.
 */
async function lockHeldBySelf(held: HeldLock): Promise<boolean> {
  try {
    const body = await readFile(held.path, "utf8");
    const parts = body.trim().split(/\s+/);
    const fileOwner = parts[1];
    return typeof fileOwner === "string" && fileOwner === held.ownerId;
  } catch {
    return false;
  }
}

/**
 * Re-assert ownership and refresh the lock mtime for {@link HeldFileLockController.refresh}.
 * Returns `true` only while THIS acquirer still owns the lock. When ownership
 * was lost (a peer stale-broke and replaced the lock while a CPU-bound section
 * blocked the event loop), returns `false` WITHOUT touching the replacement's
 * mtime — mirroring the heartbeat's ownership guard.
 *
 * FAIL-CLOSED on the mtime bump (#2033): a `utimes` failure means we cannot
 * prove the lock is still ours AND fresh — the file may have been stale-broken,
 * deleted, or replaced between the ownership check and the bump — so we report
 * lost ownership rather than let the caller rewrite the ledger on an unrefreshed
 * (soon-stale) or already-replaced lock. After a successful bump we RE-CHECK
 * ownership: a peer could have broken and replaced the lock in the window, in
 * which case `utimes` just refreshed the replacement's mtime and we must not
 * report held.
 */
async function refreshHeldLock(
  held: HeldLock,
  warn: (message: string, err: unknown) => void,
  onBeforeRefreshUtimesForTest?: () => Promise<void> | void,
): Promise<boolean> {
  if (!(await lockHeldBySelf(held))) return false;
  if (onBeforeRefreshUtimesForTest) await onBeforeRefreshUtimesForTest();
  try {
    await utimes(held.path, new Date(), new Date());
  } catch (err) {
    warn("withHeldFileLock manual refresh failed", err);
    return false;
  }
  return lockHeldBySelf(held);
}

/**
 * Process-wide chains serializing meta updates per state dir inside one
 * process. The cross-process advisory lock below only orders DIFFERENT
 * processes; without the chain, two same-process updates would contend on the
 * lock file and one could time out to failure.
 */
const metaUpdateChains = new Map<string, Promise<unknown>>();

/**
 * Serialized meta read-modify-write for one state dir (`<stateDir>/meta.json`).
 * Parallel extraction workers (the daemon's bounded queue and out-of-process
 * buffer-drain workers) each load meta, mutate counters, fingerprints or retry
 * state, and save; unlocked, a slow writer's save silently reverts a fast
 * writer's update. The chain orders same-process callers and the advisory lock
 * file (`meta.json.lock`) orders different processes; a worker that cannot
 * take the lock inside the budget FAILS the update instead of writing
 * unlocked — callers are fail-open, so the outcome is a logged miss retried by
 * the next extraction, never a silent lost update. The mutator may return
 * `false` to skip the save (nothing changed).
 */
export async function updateMetaSerialized<M>(
  dir: string,
  loadMeta: () => Promise<M>,
  saveMeta: (meta: M) => Promise<void>,
  mutate: (meta: M) => boolean | void | Promise<boolean | void>,
): Promise<void> {
  const previous = metaUpdateChains.get(dir) ?? Promise.resolve();
  const run = previous.then(() =>
    withHeldFileLock(
      path.join(dir, "meta.json.lock"),
      // Bounded: a meta update is a short read-merge-write, never a scan.
      { staleMs: 5_000, maxWaitMs: 2_000, pollMs: 50 },
      async (acquired) => {
        // A lock we could not take (busy peer past the wait budget, or a
        // filesystem error) must NOT fall back to an unlocked
        // read-modify-write: that silently reintroduces the lost-update race
        // this function exists to close. Fail instead — every caller treats
        // meta updates as fail-open, so the outcome is a logged miss that
        // the next extraction retries, never a silent clobber.
        if (!acquired) {
          throw new Error(`meta update skipped: meta.json.lock not acquired (${dir})`);
        }
        const meta = await loadMeta();
        if ((await mutate(meta)) === false) return;
        await saveMeta(meta);
      },
    ),
  );
  // Every waiter keeps its own result/error; the chain only carries completion.
  metaUpdateChains.set(dir, run.then(() => undefined, () => undefined));
  await run;
}

