/**
 * Meeting record composition, serialization, and the on-disk store (#1900).
 *
 * One markdown file per meeting under `<memoryDir>/meetings/<YYYY-MM-DD>/<id>.md`
 * with YAML frontmatter. Placement mirrors the wearables day-store rationale:
 *
 *   - OUTSIDE the memory scan roots (facts/, procedures/, …) so meeting
 *     transcripts never surface as memories in recall or governance passes;
 *   - INSIDE the QMD collection root (the memory dir) so records are full-text
 *     searchable after the next index update — but never auto-recalled raw.
 *
 * Records rebuild idempotently on `contentHash`: an unchanged meeting re-writes
 * nothing. The transcript body reuses the wearables day-store line grammar
 * (`**Name** [HH:MM]: text`, escape-aware) so existing parsers apply. File IO is
 * injected (like the fusion artifact store) so encrypted-at-rest + atomic-write
 * semantics are inherited without this module touching the secure-store key.
 */

import { createHash } from "node:crypto";
import * as path from "node:path";

import { pathIsInside } from "../utils/path-containment.js";
import { escapeSegmentText, escapeSpeakerLabel, isValidTranscriptDate } from "../wearables/day-store.js";
import type { FusedSegment } from "../wearables/fusion/types.js";
import type { FusedMeeting, MeetingDetectionSource, MeetingRecord } from "./types.js";

export const MEETINGS_DIR_NAME = "meetings";
export const MEETING_KIND = "meeting" as const;
export const MEETING_FORMAT_VERSION = 1;

/** `mtg-YYYY-MM-DD-<8 hex>` — the id shape derived by `meetingId`. */
const MEETING_ID_PATTERN = /^mtg-(\d{4}-\d{2}-\d{2})-[0-9a-f]{8}$/;

/** The detection-source label from a meeting id would be ambiguous, so validate
 *  an id AND confirm its embedded date matches the directory it lives under. */
export function meetingIdDate(id: string): string | null {
  const match = MEETING_ID_PATTERN.exec(id);
  return match === null ? null : match[1]!;
}

/** Base fields (identity + detection) a fused meeting is composed with. */
export interface MeetingRecordBase {
  id: string;
  date: string;
  startUtc: string;
  endUtc: string;
  app?: string;
  detectionSource: MeetingDetectionSource;
  title?: string;
}

/** Canonical semantic content hashed for idempotency (excludes contentHash). */
function canonicalContent(base: MeetingRecordBase, fused: FusedMeeting): string {
  return JSON.stringify({
    formatVersion: MEETING_FORMAT_VERSION,
    id: base.id,
    date: base.date,
    startUtc: base.startUtc,
    endUtc: base.endUtc,
    app: base.app ?? null,
    detectionSource: base.detectionSource,
    title: base.title ?? null,
    attendees: fused.attendees,
    sources: fused.sources,
    corroboratedBy: fused.corroboratedBy,
    screenContext: fused.screenContext,
    contextExcerpts: fused.contextExcerpts,
    transcript: fused.transcript,
    speakers: fused.speakers,
    snapshotCount: fused.snapshotCount,
  });
}

/** Compose a full meeting record (with contentHash) from its base + fused view. */
export function composeMeetingRecord(base: MeetingRecordBase, fused: FusedMeeting): MeetingRecord {
  const contentHash = createHash("sha256").update(canonicalContent(base, fused), "utf-8").digest("hex");
  return {
    ...base,
    ...fused,
    contentHash,
    formatVersion: MEETING_FORMAT_VERSION,
  };
}

function formatClockUtc(iso: string): string {
  const ms = Date.parse(iso);
  if (Number.isNaN(ms)) return "--:--";
  return new Date(ms).toISOString().slice(11, 16);
}

function renderTranscriptLine(segment: FusedSegment): string {
  const clock = formatClockUtc(segment.startIso ?? "");
  return `**${escapeSpeakerLabel(segment.speaker)}** [${clock}]: ${escapeSegmentText(segment.text)}`;
}

function frontmatterList(key: string, values: readonly string[]): string[] {
  if (values.length === 0) return [`${key}: []`];
  const lines = [`${key}:`];
  for (const value of values) lines.push(`  - ${JSON.stringify(value)}`);
  return lines;
}

/** Serialize a meeting record into its persisted markdown form. */
export function serializeMeetingRecord(record: MeetingRecord): string {
  const lines: string[] = ["---"];
  lines.push(`kind: ${MEETING_KIND}`);
  lines.push(`formatVersion: ${record.formatVersion}`);
  lines.push(`id: ${JSON.stringify(record.id)}`);
  lines.push(`date: ${JSON.stringify(record.date)}`);
  lines.push(`startUtc: ${JSON.stringify(record.startUtc)}`);
  lines.push(`endUtc: ${JSON.stringify(record.endUtc)}`);
  if (record.app !== undefined) lines.push(`app: ${JSON.stringify(record.app)}`);
  lines.push(`detectionSource: ${JSON.stringify(record.detectionSource)}`);
  if (record.title !== undefined) lines.push(`title: ${JSON.stringify(record.title)}`);
  lines.push(...frontmatterList("attendees", record.attendees));
  lines.push(...frontmatterList("sources", record.sources));
  lines.push(...frontmatterList("corroboratedBy", record.corroboratedBy));
  lines.push(`snapshotCount: ${record.snapshotCount}`);
  lines.push(`contentHash: ${JSON.stringify(record.contentHash)}`);
  lines.push("---");
  lines.push("");

  const heading = record.title !== undefined && record.title.length > 0 ? ` · ${record.title}` : "";
  lines.push(`# Meeting ${record.id}${heading}`);
  lines.push("");

  lines.push("## Attendees");
  lines.push("");
  if (record.attendees.length === 0) {
    lines.push("_None resolved._");
  } else {
    for (const attendee of record.attendees) lines.push(`- ${attendee}`);
  }
  lines.push("");

  if (record.screenContext.length > 0 || record.contextExcerpts.length > 0) {
    lines.push("## Screen context");
    lines.push("");
    for (const event of record.screenContext) {
      lines.push(`- [${event.clock}] ${event.label}`);
    }
    if (record.contextExcerpts.length > 0) {
      if (record.screenContext.length > 0) lines.push("");
      lines.push("Notable excerpts:");
      lines.push("");
      for (const excerpt of record.contextExcerpts) lines.push(`> ${excerpt.replace(/\n/g, " ")}`);
    }
    lines.push("");
  }

  lines.push("## Transcript");
  lines.push("");
  if (record.transcript.length === 0) {
    lines.push("_No transcript segments in this window._");
  } else {
    for (const segment of record.transcript) lines.push(renderTranscriptLine(segment));
  }
  lines.push("");

  return `${lines.join("\n")}`;
}

/** A meeting record's frontmatter, parsed for listing + idempotency checks. */
export interface MeetingRecordSummary {
  id: string;
  date: string;
  startUtc: string;
  endUtc: string;
  app?: string;
  detectionSource: string;
  title?: string;
  attendees: string[];
  sources: string[];
  corroboratedBy: string[];
  snapshotCount: number;
  contentHash: string;
}

function parseScalar(value: string): string {
  const trimmed = value.trim();
  if (trimmed.startsWith('"')) {
    try {
      return JSON.parse(trimmed) as string;
    } catch {
      return trimmed;
    }
  }
  return trimmed;
}

/** Parse a meeting record's frontmatter. Returns null when the content is not a
 *  meeting record (wrong kind, missing frontmatter) so callers distinguish a
 *  non-record from a corrupt one. */
export function parseMeetingRecordSummary(raw: string): MeetingRecordSummary | null {
  if (!raw.startsWith("---\n")) return null;
  const closeIndex = raw.indexOf("\n---\n", 4);
  if (closeIndex === -1) return null;
  const frontmatter = raw.slice(4, closeIndex).split("\n");

  const scalars: Record<string, string> = {};
  const lists: Record<string, string[]> = {};
  let currentList: string | null = null;
  for (const line of frontmatter) {
    const listItem = /^ {2}- (.*)$/.exec(line);
    if (listItem !== null && currentList !== null) {
      lists[currentList]!.push(parseScalar(listItem[1]!));
      continue;
    }
    const kv = /^([A-Za-z][A-Za-z0-9]*):\s*(.*)$/.exec(line);
    if (kv === null) continue;
    const key = kv[1]!;
    const value = kv[2]!;
    if (value === "") {
      currentList = key;
      lists[key] = [];
    } else if (value === "[]") {
      currentList = null;
      lists[key] = [];
    } else {
      currentList = null;
      scalars[key] = value;
    }
  }

  if (scalars.kind !== undefined && parseScalar(scalars.kind) !== MEETING_KIND) return null;
  const id = scalars.id !== undefined ? parseScalar(scalars.id) : undefined;
  const contentHash = scalars.contentHash !== undefined ? parseScalar(scalars.contentHash) : undefined;
  if (id === undefined || contentHash === undefined) return null;

  return {
    id,
    date: scalars.date !== undefined ? parseScalar(scalars.date) : "",
    startUtc: scalars.startUtc !== undefined ? parseScalar(scalars.startUtc) : "",
    endUtc: scalars.endUtc !== undefined ? parseScalar(scalars.endUtc) : "",
    ...(scalars.app !== undefined ? { app: parseScalar(scalars.app) } : {}),
    detectionSource: scalars.detectionSource !== undefined ? parseScalar(scalars.detectionSource) : "",
    ...(scalars.title !== undefined ? { title: parseScalar(scalars.title) } : {}),
    attendees: lists.attendees ?? [],
    sources: lists.sources ?? [],
    corroboratedBy: lists.corroboratedBy ?? [],
    snapshotCount: scalars.snapshotCount !== undefined ? Number(scalars.snapshotCount) || 0 : 0,
    contentHash,
  };
}

/**
 * Encrypted-at-rest + atomic file IO the meeting record store needs. Satisfied
 * by StorageManager (which owns the secure-store key + atomic write path) and
 * injected so this module performs NO direct fs — records inherit the same
 * encrypted-at-rest + atomic-write semantics as memories. Same shape as the
 * fusion artifact store's IO port (kept per-module, not shared, so each store's
 * boundary stays explicit).
 */
export interface MeetingRecordFileIo {
  writeFile(filePath: string, content: string): Promise<void>;
  readFile(filePath: string): Promise<string>;
  readDir(dirPath: string): Promise<string[]>;
  deleteFile(filePath: string): Promise<void>;
  realpath(filePath: string): Promise<string>;
  lstat(filePath: string): Promise<{ isSymbolicLink: boolean }>;
}

/** Result of an idempotent record save. */
export interface MeetingSaveResult {
  path: string;
  /** False when the on-disk contentHash already matched (nothing rewritten). */
  written: boolean;
  contentHash: string;
}

/**
 * Owns the meeting record files under `<memoryDir>/meetings/<date>/<id>.md`.
 * Path construction, date/id validation, and symlink containment live here; the
 * bytes flow through the injected secure IO. Containment is anchored to the real
 * memory-dir root and mirrors the fusion artifact store (AGENTS.md pattern #3).
 */
export class MeetingRecordStore {
  private readonly meetingsDir: string;

  constructor(
    private readonly memoryDir: string,
    private readonly io: MeetingRecordFileIo,
  ) {
    this.meetingsDir = path.join(memoryDir, MEETINGS_DIR_NAME);
  }

  recordPath(date: string, id: string): string {
    if (!isValidTranscriptDate(date)) {
      throw new Error(`invalid meeting date '${String(date)}' — expected YYYY-MM-DD`);
    }
    const idDate = meetingIdDate(id);
    if (idDate === null) {
      throw new Error(`invalid meeting id '${String(id)}' — expected mtg-YYYY-MM-DD-<hash>`);
    }
    if (idDate !== date) {
      throw new Error(`meeting id '${id}' does not belong to date '${date}'`);
    }
    return path.join(this.meetingsDir, date, `${id}.md`);
  }

  /** Idempotently persist a record: skip the write when contentHash is unchanged. */
  async saveMeetingRecord(record: MeetingRecord): Promise<MeetingSaveResult> {
    const filePath = this.recordPath(record.date, record.id);
    await this.assertPathContained(filePath);
    const existing = await this.readRaw(filePath);
    if (existing !== null) {
      const summary = parseMeetingRecordSummary(existing);
      if (summary !== null && summary.contentHash === record.contentHash) {
        return { path: filePath, written: false, contentHash: record.contentHash };
      }
    }
    await this.io.writeFile(filePath, serializeMeetingRecord(record));
    return { path: filePath, written: true, contentHash: record.contentHash };
  }

  /** Read a stored record's raw markdown; null when absent. */
  async readMeetingRecord(date: string, id: string): Promise<string | null> {
    const filePath = this.recordPath(date, id);
    await this.assertPathContained(filePath);
    return this.readRaw(filePath);
  }

  /**
   * Read + parse every stored record for a day exactly ONCE, sorted by start
   * time (ascending, id tiebreak). The single day-read path both `listMeetingIds`
   * and `listMeetingSummaries` derive from — no record is read twice.
   */
  private async readDaySummaries(date: string): Promise<MeetingRecordSummary[]> {
    if (!isValidTranscriptDate(date)) {
      throw new Error(`invalid meeting date '${String(date)}' — expected YYYY-MM-DD`);
    }
    const dayDir = path.join(this.meetingsDir, date);
    await this.assertPathContained(dayDir);
    let entries: string[];
    try {
      entries = await this.io.readDir(dayDir);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
      throw err;
    }
    const summaries: MeetingRecordSummary[] = [];
    for (const entry of entries) {
      if (!entry.endsWith(".md")) continue;
      const id = entry.slice(0, -3);
      if (meetingIdDate(id) !== date) continue;
      const raw = await this.readMeetingRecord(date, id);
      if (raw === null) continue;
      const summary = parseMeetingRecordSummary(raw);
      if (summary !== null) summaries.push(summary);
    }
    summaries.sort((a, b) => (a.startUtc < b.startUtc ? -1 : a.startUtc > b.startUtc ? 1 : SORT_STR(a.id, b.id)));
    return summaries;
  }

  /** List meeting ids stored for a day, sorted by start time (ascending). */
  async listMeetingIds(date: string): Promise<string[]> {
    return (await this.readDaySummaries(date)).map((summary) => summary.id);
  }

  /** Read parsed summaries for a day, sorted by start time. */
  async listMeetingSummaries(date: string): Promise<MeetingRecordSummary[]> {
    return this.readDaySummaries(date);
  }

  /** List dates that have at least one stored meeting record, newest first. */
  async listMeetingDates(): Promise<string[]> {
    await this.assertPathContained(this.meetingsDir);
    let entries: string[];
    try {
      entries = await this.io.readDir(this.meetingsDir);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
      throw err;
    }
    const dates = entries.filter((entry) => isValidTranscriptDate(entry));
    dates.sort((a, b) => (a > b ? -1 : a < b ? 1 : 0));
    return dates;
  }

  /** Remove a stored record. Idempotent: a no-op when already absent. */
  async deleteMeetingRecord(date: string, id: string): Promise<void> {
    const filePath = this.recordPath(date, id);
    await this.assertPathContained(filePath);
    try {
      await this.io.deleteFile(filePath);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return;
      throw err;
    }
  }

  private async readRaw(filePath: string): Promise<string | null> {
    try {
      return await this.io.readFile(filePath);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw err;
    }
  }

  private async assertPathContained(targetPath: string): Promise<void> {
    let rootReal: string;
    try {
      rootReal = await this.io.realpath(this.memoryDir);
    } catch {
      rootReal = path.resolve(this.memoryDir);
    }
    await this.assertNoEscape(rootReal, this.meetingsDir);
    await this.assertNoEscape(rootReal, path.dirname(targetPath));
    await this.assertNoEscape(rootReal, targetPath);
    // Reject a symlinked meetings root OR a symlinked intermediate day directory
    // outright — even when the link resolves inside the memory dir (aliasing /
    // tampering) — before any read/write (AGENTS.md pattern #3).
    await this.assertNotSymlink(this.meetingsDir, "directory");
    const dayDir = this.dayDirWithin(targetPath);
    if (dayDir !== null) await this.assertNotSymlink(dayDir, "directory");
    // Reject a symlinked LEAF record file too: lstat'ing only the root + day dir
    // let a pre-existing `<id>.md` symlink (e.g. into facts/) pass realpath
    // containment, so the read/write would FOLLOW the link and leak raw
    // transcript into the recall corpus. Refuse the link before any IO.
    if (targetPath.endsWith(".md")) await this.assertNotSymlink(targetPath, "record file");
  }

  /** The `<meetings>/<date>` directory on the path to `targetPath`, or null when
   *  `targetPath` is the meetings root itself. */
  private dayDirWithin(targetPath: string): string | null {
    const rel = path.relative(this.meetingsDir, targetPath);
    if (rel === "" || rel.startsWith("..") || path.isAbsolute(rel)) return null;
    const first = rel.split(path.sep)[0];
    if (first === undefined || first.length === 0) return null;
    return path.join(this.meetingsDir, first);
  }

  private async assertNotSymlink(target: string, kind: "directory" | "record file"): Promise<void> {
    let stat: { isSymbolicLink: boolean };
    try {
      stat = await this.io.lstat(target);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return;
      throw err;
    }
    if (stat.isSymbolicLink) {
      const label = path.relative(this.memoryDir, target) || MEETINGS_DIR_NAME;
      throw new Error(
        `meetings ${kind} '${label}' is a symbolic link — refusing to follow it even when it resolves inside the memory dir (AGENTS.md pattern #3)`,
      );
    }
  }

  private async assertNoEscape(rootReal: string, candidate: string): Promise<void> {
    let candidateReal: string;
    try {
      candidateReal = await this.io.realpath(candidate);
    } catch {
      return;
    }
    if (!pathIsInside(rootReal, candidateReal)) {
      throw new Error(
        "meeting record path resolves outside the memory dir — refusing to follow a symlink/traversal (AGENTS.md pattern #3)",
      );
    }
  }
}

const SORT_STR = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);

/**
 * Transparent file-level encryption for the secure-store module.
 *
 * Issue #690 (PR 3/4) — storage.ts integration layer.
 *
 * This module sits between the raw filesystem and StorageManager.
 * Every memory file is either:
 *   - a plain UTF-8 text file (legacy, back-compat), or
 *   - a REMNIC-ENC sealed file (AES-256-GCM, see format below).
 *
 * On-disk format
 * --------------
 * Encrypted files begin with a 9-byte magic header:
 *
 *   REMNIC-ENC  (7 ASCII bytes)
 *   VER         (1 byte, currently 0x01)
 *   FLAGS       (1 byte, reserved, must be 0x00)
 *
 * Followed immediately by a `seal()` envelope from `cipher.ts`:
 *
 *   [VERSION:1][SALT:16][IV:12][AUTHTAG:16][CIPHERTEXT:...]
 *
 * The magic header makes encrypted files sniffable without attempting
 * a full `open()` call and gives operators a clear signal that the
 * file cannot be read by opening it in an editor.
 *
 * AAD
 * ---
 * The file path relative to the memory root is bound as Associated
 * Authenticated Data (AAD) on both encrypt and decrypt. This means
 * moving or renaming an encrypted file without re-encrypting it will
 * cause auth-tag failure on the next read — the file is tied to its
 * path. Callers that move files must re-encrypt them.
 *
 * Back-compat
 * -----------
 * `readMaybeEncryptedFile` transparently handles both formats: if the
 * file does NOT start with the magic bytes, it is returned as-is (plain
 * text). This lets an operator migrate incrementally: newly-written
 * files are encrypted while existing files continue to be read in plain
 * form until `migrateMemoryDirToEncrypted` is run.
 *
 * Naming: `secure-fs.ts` (not `vault-fs.ts`) — see `kdf.ts` naming note.
 */

import { createCipheriv, createDecipheriv, randomBytes, randomUUID } from "node:crypto";
import { lstat, mkdir, open as openFile, readFile, readdir, rename, unlink, writeFile } from "node:fs/promises";
import path from "node:path";

import {
  AUTH_TAG_LENGTH,
  ENVELOPE_HEADER_SIZE,
  ENVELOPE_LAYOUT,
  ENVELOPE_SALT_LENGTH,
  ENVELOPE_VERSION,
  IV_LENGTH,
  generateSalt,
  open as openEnvelope,
  parseEnvelope,
  seal,
} from "./cipher.js";
import { RECALL_FALLBACK_DIRS } from "../utils/category-dir.js";
import { isErrnoCode } from "../utils/errno.js";
import { readStoreFileBufferTolerant as readStoreFileBuffer } from "./entity-file-read.js";

// ---------------------------------------------------------------------------
// Error classes
// ---------------------------------------------------------------------------

/**
 * Thrown when a read is attempted but the keyring entry for this
 * store is absent (i.e. `secure-store unlock` has not been run
 * since the last daemon start).
 */
export class SecureStoreLockedError extends Error {
  constructor(message = "secure-store is locked — run `remnic secure-store unlock` to decrypt") {
    super(message);
    this.name = "SecureStoreLockedError";
  }
}

/**
 * Thrown when `open()` fails because the auth tag does not validate.
 * This covers both wrong-key and tampered-ciphertext scenarios —
 * intentionally indistinguishable from the caller's perspective.
 */
export class SecureStoreDecryptError extends Error {
  constructor(message = "secure-store decryption failed — wrong key or tampered ciphertext") {
    super(message);
    this.name = "SecureStoreDecryptError";
  }
}

// ---------------------------------------------------------------------------
// Magic header
// ---------------------------------------------------------------------------

/** Magic bytes: the ASCII string "REMNIC-ENC" (10 bytes). */
export const MAGIC_BYTES = Buffer.from("REMNIC-ENC", "ascii");

/** Current on-disk version byte. */
export const FILE_FORMAT_VERSION = 0x01;

/** Reserved flags byte — must be 0x00. */
export const FILE_FORMAT_FLAGS = 0x00;

/** Total size of the magic header prefix (magic + version + flags). */
export const MAGIC_HEADER_SIZE = MAGIC_BYTES.length + 2; // 12 bytes

/**
 * Exact, deterministic bytes `writeMaybeEncryptedFile` adds to an encrypted
 * file beyond its plaintext body: the magic header prefix plus the fixed
 * envelope header (version + salt + IV + auth tag). AES-256-GCM ciphertext
 * matches the plaintext length and the state-file write path applies no
 * compression, so an encrypted state file is exactly `plaintext +
 * SECURE_STORE_ENVELOPE_OVERHEAD_BYTES` on disk. Compaction reserves this so an
 * encrypted ledger lands strictly below the reader's whole-file decrypt cap
 * (issue #2033).
 */
export const SECURE_STORE_ENVELOPE_OVERHEAD_BYTES = MAGIC_HEADER_SIZE + ENVELOPE_HEADER_SIZE;

// ---------------------------------------------------------------------------
// Detection
// ---------------------------------------------------------------------------

/**
 * Return true iff `buf` begins with the REMNIC-ENC magic header.
 * Does not validate the envelope; just identifies the format.
 */
export function isEncryptedFile(buf: Uint8Array): boolean {
  if (buf.length < MAGIC_HEADER_SIZE) return false;
  const b = Buffer.isBuffer(buf) ? buf : Buffer.from(buf);
  return b.subarray(0, MAGIC_BYTES.length).equals(MAGIC_BYTES);
}

type PositionedFileReader = {
  read: (buffer: Buffer, offset: number, length: number, position: number) => Promise<{ bytesRead: number }>;
};

async function readPositionedPrefix(handle: PositionedFileReader, buffer: Buffer): Promise<number> {
  let bytesRead = 0;
  while (bytesRead < buffer.length) {
    const result = await handle.read(buffer, bytesRead, buffer.length - bytesRead, bytesRead);
    if (result.bytesRead === 0) break;
    bytesRead += result.bytesRead;
  }
  return bytesRead;
}

/**
 * True when the REGULAR file at `probePath` is encrypted at rest (its first
 * bytes are the REMNIC-ENC magic header). ENOENT resolves to false — an absent
 * file has nothing to probe. A symlink, FIFO, device, or any other non-regular
 * path is REFUSED with a throw rather than opened: opening a FIFO blocks until a
 * writer appears and a symlink would redirect the probe outside our tree. The
 * ledgers and per-event spills we manage are always regular files, so a
 * non-regular path is an anomaly the caller must treat as unsafe, never follow
 * (#2033). Shared by the CLI ledger recovery probe and the auto-compaction probe
 * so both enforce identical open safety.
 */
export async function probeEncryptedRegularFileHeader(probePath: string): Promise<boolean> {
  let entryStat;
  try {
    entryStat = await lstat(probePath);
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return false;
    throw err;
  }
  if (!entryStat.isFile()) {
    throw new Error(
      `refusing to probe non-regular state path ${probePath} ` +
        `(symlink/FIFO/device); opening it could block or escape containment (#2033)`
    );
  }
  const handle = await openFile(probePath, "r");
  try {
    const header = Buffer.alloc(MAGIC_HEADER_SIZE);
    const bytesRead = await readPositionedPrefix(handle, header);
    return isEncryptedFile(header.subarray(0, bytesRead));
  } finally {
    await handle.close();
  }
}

// ---------------------------------------------------------------------------
// Encrypt / decrypt file body
// ---------------------------------------------------------------------------

/**
 * Encrypt `plain` (UTF-8 content of a memory file) and return a
 * Buffer ready to write to disk.
 *
 * @param plain  Plain-text file content (UTF-8 string or Buffer).
 * @param key    32-byte AES-256 key from the keyring.
 * @param aad    Optional associated data — defaults to empty if omitted.
 *               Callers should pass the file path relative to memoryDir
 *               so the ciphertext is bound to its location.
 */
export function encryptFileBody(plain: string | Buffer, key: Buffer, aad?: Buffer): Buffer {
  const plainBuf = typeof plain === "string" ? Buffer.from(plain, "utf8") : plain;
  const salt = generateSalt();
  const envelope = seal(key, salt, plainBuf, aad ? { aad } : {});

  const header = Buffer.alloc(MAGIC_HEADER_SIZE);
  MAGIC_BYTES.copy(header, 0);
  header.writeUInt8(FILE_FORMAT_VERSION, MAGIC_BYTES.length);
  header.writeUInt8(FILE_FORMAT_FLAGS, MAGIC_BYTES.length + 1);

  return Buffer.concat([header, envelope]);
}

/**
 * Decrypt a buffer produced by `encryptFileBody` and return the
 * original UTF-8 content.
 *
 * Throws `SecureStoreDecryptError` on auth failure (wrong key or
 * tampered ciphertext). Throws a plain `Error` for structural problems
 * (truncated buffer, wrong magic, unsupported version).
 */
export function decryptFileBody(buf: Buffer, key: Buffer, aad?: Buffer): Buffer {
  if (!isEncryptedFile(buf)) {
    throw new Error("decryptFileBody: buffer does not start with REMNIC-ENC magic header");
  }
  const version = buf.readUInt8(MAGIC_BYTES.length);
  if (version !== FILE_FORMAT_VERSION) {
    throw new Error(
      `decryptFileBody: unsupported file format version ${version} (this build supports ${FILE_FORMAT_VERSION})`
    );
  }
  const flags = buf.readUInt8(MAGIC_BYTES.length + 1);
  if (flags !== FILE_FORMAT_FLAGS) {
    throw new Error(`decryptFileBody: unknown flags byte 0x${flags.toString(16).padStart(2, "0")}`);
  }
  const envelope = buf.subarray(MAGIC_HEADER_SIZE);
  parseEnvelope(envelope);
  try {
    return openEnvelope(key, envelope, aad ? { aad } : {});
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    throw new SecureStoreDecryptError(`secure-store decryption failed: ${msg}`);
  }
}

function buildHeaderAad(salt: Uint8Array): Buffer {
  const out = Buffer.alloc(1 + ENVELOPE_SALT_LENGTH);
  out.writeUInt8(ENVELOPE_VERSION, 0);
  Buffer.from(salt).copy(out, 1);
  return out;
}

// ---------------------------------------------------------------------------
// Path → AAD helper
// ---------------------------------------------------------------------------

/**
 * Build the AAD buffer for a file at `filePath` relative to
 * `memoryDir`. The AAD binds the ciphertext to its path so a
 * file cannot be silently relocated without re-encryption.
 *
 * When `memoryDir` is supplied and `filePath` is absolute, the
 * relative sub-path is used. Otherwise `filePath` is used verbatim.
 */
export function filePathAad(filePath: string, memoryDir?: string): Buffer {
  let rel = filePath;
  if (memoryDir && path.isAbsolute(filePath)) {
    rel = path.relative(memoryDir, filePath);
  }
  return Buffer.from(rel, "utf8");
}

// ---------------------------------------------------------------------------
// High-level read / write helpers
// ---------------------------------------------------------------------------

/**
 * Read a file from `filePath`.
 *
 * - If the file is plaintext (no magic header), return its content
 *   as-is — back-compat with unencrypted stores.
 * - If the file is encrypted AND `key` is provided, decrypt and return
 *   the plaintext content.
 * - If the file is encrypted AND `key` is null, throw
 *   `SecureStoreLockedError`.
 *
 * @param filePath  Absolute path to the file.
 * @param key       32-byte AES-256 key, or null when the store is locked.
 * @param memoryDir Memory root for path-bound AAD.  Should be absolute.
 */
export async function readMaybeEncryptedFileBuffer(
  filePath: string,
  key: Buffer | null,
  memoryDir?: string,
  opts?: { aadFilePath?: string }
): Promise<Buffer> {
  const buf = memoryDir ? await readStoreFileBuffer(filePath, memoryDir) : await readFile(filePath);
  if (!isEncryptedFile(buf)) {
    // Plain file — legacy or unencrypted store.
    return buf;
  }
  // Encrypted — key required.
  if (key === null) {
    throw new SecureStoreLockedError(
      `secure-store is locked — cannot read encrypted file at ${filePath}. Run \`remnic secure-store unlock\` to decrypt.`
    );
  }
  return decryptFileBodyForPath(buf, key, filePath, memoryDir, opts?.aadFilePath);
}

export async function readMaybeEncryptedFile(
  filePath: string,
  key: Buffer | null,
  memoryDir?: string
): Promise<string> {
  return (await readMaybeEncryptedFileBuffer(filePath, key, memoryDir)).toString("utf8");
}

export interface WriteMaybeEncryptedFileOptions {
  /**
   * File mode bits. Default 0o600 (owner read/write only).
   * Applied only on create; existing files inherit their existing mode.
   */
  mode?: number;
  /**
   * If true, write atomically via a temp file + rename (CLAUDE.md gotcha #54).
   * Default true.
   */
  atomic?: boolean;
  /**
   * ABSOLUTE final path whose canonical AAD (via {@link filePathAad})
   * replaces the physical `filePath`'s. Used by the offline-sync generation
   * transaction: staged ciphertext physically lives under a staging
   * directory but must decrypt at its FINAL published path after the
   * staging directory is swapped into place by rename. Deriving the AAD
   * from the absolute final path through the SAME filePathAad logic as
   * ordinary reads keeps write and read derivations identical on every
   * platform (POSIX and Windows separators alike). (issue #3148, round 4/5)
   */
  aadFilePath?: string;
}

/**
 * Write `content` to `filePath`.
 *
 * - If `key` is provided and non-null, encrypt the content first.
 * - If `key` is null, write the content as plain UTF-8 (unencrypted store).
 *
 * Writes atomically: content is written to a unique temp file
 * first, then renamed into place (CLAUDE.md gotcha #54 — never delete
 * before write).
 */
export async function writeMaybeEncryptedFile(
  filePath: string,
  content: string | Buffer,
  key: Buffer | null,
  options: WriteMaybeEncryptedFileOptions = {},
  memoryDir?: string
): Promise<void> {
  const { mode = 0o600, atomic = true, aadFilePath } = options;
  await mkdir(path.dirname(filePath), { recursive: true });

  let data: Buffer | string;
  if (key !== null) {
    const aad = aadFilePath !== undefined ? filePathAad(aadFilePath, memoryDir) : filePathAad(filePath, memoryDir);
    data = encryptFileBody(content, key, aad);
  } else {
    data = content;
  }

  if (atomic) {
    const tempPath = uniqueAtomicTempPath(filePath, "tmp");
    try {
      await writeFile(tempPath, data, { mode });
      await rename(tempPath, filePath);
    } catch (err) {
      // Best-effort cleanup of the temp file.
      try {
        await unlink(tempPath);
      } catch {
        // ignore
      }
      throw err;
    }
  } else {
    await writeFile(filePath, data, { mode });
  }
}

export async function writeMaybeEncryptedFileFromChunks(
  filePath: string,
  chunks: AsyncIterable<Buffer>,
  key: Buffer | null,
  options: WriteMaybeEncryptedFileOptions = {},
  memoryDir?: string
): Promise<void> {
  const { mode = 0o600, atomic = true } = options;
  await mkdir(path.dirname(filePath), { recursive: true });
  const writePath = atomic ? `${filePath}.tmp-${process.pid}-${Date.now()}` : filePath;
  let completed = false;
  try {
    const handle = await openFile(writePath, "w", mode);
    try {
      if (key !== null) {
        const salt = generateSalt();
        const iv = randomBytes(IV_LENGTH);
        const header = Buffer.alloc(MAGIC_HEADER_SIZE + ENVELOPE_HEADER_SIZE);
        MAGIC_BYTES.copy(header, 0);
        header.writeUInt8(FILE_FORMAT_VERSION, MAGIC_BYTES.length);
        header.writeUInt8(FILE_FORMAT_FLAGS, MAGIC_BYTES.length + 1);
        const envelopeOffset = MAGIC_HEADER_SIZE;
        header.writeUInt8(ENVELOPE_VERSION, envelopeOffset + ENVELOPE_LAYOUT.version);
        salt.copy(header, envelopeOffset + ENVELOPE_LAYOUT.salt);
        iv.copy(header, envelopeOffset + ENVELOPE_LAYOUT.iv);
        await handle.write(header);

        const cipher = createCipheriv("aes-256-gcm", key, iv, { authTagLength: AUTH_TAG_LENGTH });
        const aad = filePathAad(filePath, memoryDir);
        cipher.setAAD(Buffer.concat([buildHeaderAad(salt), aad]));
        for await (const chunk of chunks) {
          if (chunk.length === 0) continue;
          const encrypted = cipher.update(chunk);
          if (encrypted.length > 0) await handle.write(encrypted);
        }
        const final = cipher.final();
        if (final.length > 0) await handle.write(final);
        const authTag = cipher.getAuthTag();
        await handle.write(authTag, 0, authTag.length, MAGIC_HEADER_SIZE + ENVELOPE_LAYOUT.authTag);
      } else {
        for await (const chunk of chunks) {
          if (chunk.length > 0) await handle.write(chunk);
        }
      }
    } finally {
      await handle.close();
    }
    if (atomic) {
      await rename(writePath, filePath);
    }
    completed = true;
  } finally {
    if (!completed && atomic) {
      await unlink(writePath).catch(() => {});
    }
  }
}

/**
 * Stream a file through the secure-store reader without buffering the whole
 * payload. Plaintext files are passed through unchanged; encrypted files are
 * authenticated and decrypted incrementally.
 */
export async function* readMaybeEncryptedFileFromChunks(
  filePath: string,
  key: Buffer | null,
  memoryDir?: string,
  chunkSize = 64 * 1024
): AsyncIterable<Buffer> {
  const handle = await openFile(filePath, "r");
  const headerSize = MAGIC_HEADER_SIZE + ENVELOPE_HEADER_SIZE;
  try {
    const prefix = Buffer.alloc(headerSize);
    const prefixBytes = await readPositionedPrefix(handle, prefix);
    const prefixView = prefix.subarray(0, prefixBytes);
    if (!isEncryptedFile(prefixView)) {
      if (prefixBytes > 0) yield Buffer.from(prefixView);
      let position = prefixBytes;
      const buffer = Buffer.alloc(chunkSize);
      for (;;) {
        const { bytesRead } = await handle.read(buffer, 0, buffer.length, position);
        if (bytesRead === 0) break;
        position += bytesRead;
        yield Buffer.from(buffer.subarray(0, bytesRead));
      }
      return;
    }
    if (prefixBytes < headerSize) {
      throw new Error(`encrypted file header is truncated: ${filePath}`);
    }
    if (key === null) {
      throw new SecureStoreLockedError(
        `secure-store is locked — cannot read encrypted file at ${filePath}. ` +
          "Run `remnic secure-store unlock` to decrypt."
      );
    }
    const envelope = prefix.subarray(MAGIC_HEADER_SIZE);
    const version = envelope.readUInt8(ENVELOPE_LAYOUT.version);
    if (version !== ENVELOPE_VERSION) {
      throw new Error(`secure-store: unsupported envelope version ${version}`);
    }
    const salt = envelope.subarray(ENVELOPE_LAYOUT.salt, ENVELOPE_LAYOUT.salt + ENVELOPE_SALT_LENGTH);
    const iv = envelope.subarray(ENVELOPE_LAYOUT.iv, ENVELOPE_LAYOUT.iv + IV_LENGTH);
    const authTag = envelope.subarray(ENVELOPE_LAYOUT.authTag, ENVELOPE_LAYOUT.authTag + AUTH_TAG_LENGTH);
    const decipher = createDecipheriv("aes-256-gcm", key, iv, { authTagLength: AUTH_TAG_LENGTH });
    decipher.setAAD(Buffer.concat([buildHeaderAad(salt), filePathAad(filePath, memoryDir)]));
    decipher.setAuthTag(authTag);
    let position = headerSize;
    const buffer = Buffer.alloc(chunkSize);
    try {
      for (;;) {
        const { bytesRead } = await handle.read(buffer, 0, buffer.length, position);
        if (bytesRead === 0) break;
        position += bytesRead;
        const plain = decipher.update(buffer.subarray(0, bytesRead));
        if (plain.length > 0) yield plain;
      }
      const final = decipher.final();
      if (final.length > 0) yield final;
    } catch (err) {
      if (err instanceof SecureStoreDecryptError) throw err;
      const message = err instanceof Error ? err.message : String(err);
      throw new SecureStoreDecryptError(`secure-store decryption failed: ${message}`);
    }
  } finally {
    await handle.close();
  }
}

// ---------------------------------------------------------------------------
// Migration
// ---------------------------------------------------------------------------

export interface MigrateResult {
  /** Number of files successfully encrypted. */
  encrypted: number;
  /** Number of files already encrypted (skipped). */
  skipped: number;
  /** Files that failed to encrypt (path → error message). */
  errors: Array<{ filePath: string; error: string }>;
}

export interface DecryptResult {
  /** Number of files successfully decrypted back to plaintext. */
  decrypted: number;
  /** Number of files already plaintext (skipped). */
  skipped: number;
  /** Files that failed to decrypt (path → error message). */
  errors: Array<{ filePath: string; error: string }>;
}

/**
 * Walk `dir` recursively, find encryptable storage-managed files that are not
 * yet encrypted, and re-write them as encrypted files under `key`.
 *
 * Safety rules per CLAUDE.md gotchas #54 and #25:
 *   1. A page-version snapshot is taken (via `createVersion`) BEFORE
 *      each overwrite so the plaintext version is preserved in history.
 *      Since this module has no direct access to `page-versioning.ts`
 *      internals, callers who have page-versioning configured should
 *      pass `onBeforeEncrypt` to take the snapshot.
 *   2. The new encrypted content is written to a temp file first,
 *      then renamed atomically — never deleted before written.
 *   3. If encryption of any file fails, the error is recorded and the
 *      original file is left intact (partial migration is safe).
 *
 * @param dir              Absolute path to the memory directory.
 * @param key              32-byte AES-256 key.
 * @param onBeforeEncrypt  Optional callback invoked before encrypting
 *                         each file. Can be used to take page-version
 *                         snapshots. Errors here are non-fatal.
 */
export async function migrateMemoryDirToEncrypted(
  dir: string,
  key: Buffer,
  onBeforeEncrypt?: (filePath: string) => Promise<void>
): Promise<MigrateResult> {
  const result: MigrateResult = { encrypted: 0, skipped: 0, errors: [] };

  const files = await collectEncryptableStorageFiles(dir);
  for (const filePath of files) {
    try {
      const buf = await readFile(filePath);
      if (isEncryptedFile(buf)) {
        result.skipped++;
        continue;
      }
      // Call optional pre-encryption hook (e.g. page-version snapshot).
      if (onBeforeEncrypt) {
        try {
          await onBeforeEncrypt(filePath);
        } catch {
          // Non-fatal — continue with encryption even if snapshot fails.
        }
      }
      const content = buf.toString("utf8");
      const aad = filePathAad(filePath, dir);
      const encrypted = encryptFileBody(content, key, aad);

      // Atomic write: temp → rename (gotcha #54).
      const tempPath = uniqueAtomicTempPath(filePath, "enc-tmp");
      try {
        await writeFile(tempPath, encrypted, { mode: 0o600 });
        await rename(tempPath, filePath);
        result.encrypted++;
      } catch (writeErr) {
        // Clean up temp file, leave original intact.
        try {
          const { unlink } = await import("node:fs/promises");
          await unlink(tempPath);
        } catch {
          // ignore
        }
        throw writeErr;
      }
    } catch (err) {
      result.errors.push({
        filePath,
        error: err instanceof Error ? err.message : String(err),
      });
    }
  }

  return result;
}

/**
 * Walk `dir` recursively, find storage-managed encrypted files, and
 * re-write them as plaintext under the same paths.
 *
 * This is the reversible counterpart to {@link migrateMemoryDirToEncrypted}.
 * It only touches files under the same storage-managed roots, skips
 * plaintext files, skips symlinks, excludes `.secure-store/`, and writes
 * each plaintext replacement via temp-file + rename so a per-file failure
 * leaves the ciphertext intact.
 */
export async function decryptMemoryDirToPlaintext(dir: string, key: Buffer): Promise<DecryptResult> {
  const result: DecryptResult = { decrypted: 0, skipped: 0, errors: [] };

  const files = await collectStorageManagedFiles(dir, isDecryptableStoragePath);
  for (const filePath of files) {
    try {
      const buf = await readFile(filePath);
      if (!isEncryptedFile(buf)) {
        result.skipped++;
        continue;
      }

      const plaintext = decryptFileBodyForPath(buf, key, filePath, dir);
      const tempPath = uniqueAtomicTempPath(filePath, "dec-tmp");
      try {
        await writeFile(tempPath, plaintext, { mode: 0o600 });
        await rename(tempPath, filePath);
        result.decrypted++;
      } catch (writeErr) {
        try {
          await unlink(tempPath);
        } catch {
          // ignore cleanup errors; original ciphertext is still intact.
        }
        throw writeErr;
      }
    } catch (err) {
      result.errors.push({
        filePath,
        error: err instanceof Error ? err.message : String(err),
      });
    }
  }

  return result;
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

function uniqueAtomicTempPath(filePath: string, label: string): string {
  return `${filePath}.${label}-${process.pid}-${Date.now()}-${randomUUID()}`;
}

function decryptFileBodyForPath(
  buf: Buffer,
  key: Buffer,
  filePath: string,
  memoryDir?: string,
  aadFilePath?: string
): Buffer {
  // A canonical-AAD stage read (offline-sync generation transaction) binds
  // the FINAL published path, not the physical staging path.
  const aad = aadFilePath !== undefined ? filePathAad(aadFilePath, memoryDir) : filePathAad(filePath, memoryDir);
  try {
    return decryptFileBody(buf, key, aad);
  } catch (err) {
    if (!(err instanceof SecureStoreDecryptError)) {
      throw err;
    }
    const legacyRoot = legacyNamespaceAadRootForFile(filePath, memoryDir);
    if (legacyRoot) {
      try {
        return decryptFileBody(buf, key, filePathAad(filePath, legacyRoot));
      } catch {
        // Fall through to the namespace-reader fallback below.
      }
    }

    const topLevelRoot = topLevelAadRootForNamespaceReader(filePath, memoryDir);
    if (topLevelRoot) {
      try {
        return decryptFileBody(buf, key, filePathAad(filePath, topLevelRoot));
      } catch {
        // Preserve the caller-facing error from the canonical decrypt attempt.
      }
    }

    throw err;
  }
}

function topLevelAadRootForNamespaceReader(filePath: string, memoryDir?: string): string | null {
  if (!memoryDir || !path.isAbsolute(filePath)) return null;
  const resolvedMemoryDir = path.resolve(memoryDir);
  const rel = path.relative(resolvedMemoryDir, filePath);
  if (rel === "" || rel.startsWith("..") || path.isAbsolute(rel)) return null;
  const parts = resolvedMemoryDir.split(path.sep);
  if (parts.length < 3 || parts.at(-2) !== "namespaces" || !parts.at(-1)) return null;
  const topLevelRoot = parts.slice(0, -2).join(path.sep) || path.sep;
  const topRel = path.relative(topLevelRoot, filePath);
  if (topRel === "" || topRel.startsWith("..") || path.isAbsolute(topRel)) {
    return null;
  }
  const topParts = topRel.split(path.sep);
  if (topParts[0] !== "namespaces" || topParts[1] !== parts.at(-1)) {
    return null;
  }
  return topLevelRoot;
}

function legacyNamespaceAadRootForFile(filePath: string, memoryDir?: string): string | null {
  if (!memoryDir || !path.isAbsolute(filePath)) return null;
  const rel = path.relative(memoryDir, filePath);
  if (rel === "" || rel.startsWith("..") || path.isAbsolute(rel)) return null;
  const parts = rel.split(path.sep);
  if (parts[0] === "namespaces" && parts.length >= 3 && parts[1]) {
    return path.join(memoryDir, "namespaces", parts[1]);
  }
  return null;
}

/**
 * Recursively collect files under `dir` that are read through the
 * storage-layer secure-store helpers, excluding symlinked entries and
 * `.secure-store/` metadata.
 */
async function collectEncryptableStorageFiles(dir: string, rootDir = dir): Promise<string[]> {
  return collectStorageManagedFiles(dir, isEncryptableStoragePath, rootDir);
}

/**
 * Recursively collect regular files under storage-managed roots, excluding
 * symlinked entries and `.secure-store/` metadata. This broader collector is
 * used by the decrypt/disable path so future encrypted sidecars can be
 * restored without requiring extension-specific logic.
 */
async function collectStorageManagedFiles(
  dir: string,
  includeFile: (filePath: string, rootDir: string) => boolean,
  rootDir = dir
): Promise<string[]> {
  const results: string[] = [];
  let scanDir = dir;
  let scanRootDir = rootDir;
  if (path.resolve(dir) === path.resolve(rootDir)) {
    const normalizedRoot = await resolveStorageManagedRootForScan(dir);
    if (!normalizedRoot) return results;
    scanDir = normalizedRoot;
    scanRootDir = normalizedRoot;
  }
  let names: string[];
  try {
    names = await readdir(scanDir, { encoding: "utf8" });
  } catch {
    return results;
  }
  for (const name of names) {
    if (name.startsWith(".secure-store")) continue;
    const full = path.join(scanDir, name);
    let isDir = false;
    let isFile = false;
    try {
      const s = await lstat(full);
      if (s.isSymbolicLink()) continue;
      isDir = s.isDirectory();
      isFile = s.isFile();
    } catch {
      continue;
    }
    if (isDir) {
      const sub = await collectStorageManagedFiles(full, includeFile, scanRootDir);
      results.push(...sub);
    } else if (isFile && includeFile(full, scanRootDir)) {
      results.push(full);
    }
  }
  return results;
}

async function resolveStorageManagedRootForScan(dir: string): Promise<string | null> {
  const lstatPath = normalizePathForLstat(dir);
  let stat: Awaited<ReturnType<typeof lstat>>;
  try {
    stat = await lstat(lstatPath);
  } catch (error) {
    if (isFsErrorWithCode(error, "ENOENT")) return null;
    throw error;
  }
  if (stat.isSymbolicLink()) {
    throw new Error(`secure-store migration root must not be a symlink: ${dir}`);
  }
  if (!stat.isDirectory()) {
    throw new Error(`secure-store migration root must be a directory: ${dir}`);
  }
  return lstatPath;
}

function normalizePathForLstat(filePath: string): string {
  return stripTrailingPathSeparators(path.normalize(filePath));
}

function isFsErrorWithCode(error: unknown, code: string): boolean {
  return typeof error === "object" && error !== null && (error as { code?: unknown }).code === code;
}

function stripTrailingPathSeparators(filePath: string): string {
  const root = path.parse(filePath).root;
  let end = filePath.length;
  while (
    end > root.length &&
    (filePath[end - 1] === path.sep || filePath[end - 1] === path.posix.sep || filePath[end - 1] === path.win32.sep)
  ) {
    end -= 1;
  }
  return end === filePath.length ? filePath : filePath.slice(0, end);
}

function isEncryptableStoragePath(filePath: string, rootDir: string): boolean {
  const rel = path.relative(rootDir, filePath);
  if (rel === "" || rel.startsWith("..") || path.isAbsolute(rel)) return false;
  const normalized = normalizeStorageRelativePath(rel);
  if (normalized === "profile.md") return true;
  if (isEncryptableStateSidecar(normalized)) return true;
  if (isEncryptableBufferSessionFile(normalized)) return true;
  if (isEncryptableSummarySidecar(normalized)) return true;
  const firstSegment = normalized.split("/", 1)[0];
  return ENCRYPTABLE_MARKDOWN_STORAGE_ROOTS.has(firstSegment) && normalized.endsWith(".md");
}

function isDecryptableStoragePath(filePath: string, rootDir: string): boolean {
  if (isEncryptableStoragePath(filePath, rootDir)) return true;
  const rel = path.relative(rootDir, filePath);
  if (rel === "" || rel.startsWith("..") || path.isAbsolute(rel)) return false;
  const normalized = normalizeStorageRelativePath(rel);
  const firstSegment = normalized.split("/", 1)[0];
  return DECRYPTABLE_SIDECAR_ROOTS.has(firstSegment);
}

function normalizeStorageRelativePath(rel: string): string {
  const normalized = rel.split(path.sep).join("/");
  const parts = normalized.split("/");
  if (parts[0] === "namespaces" && parts.length >= 3) {
    return parts.slice(2).join("/");
  }
  return normalized;
}

// Every recall MEMORY category directory (facts/ + the CATEGORY_DIR_MAP memory
// dirs) must be encryptable at rest — #1546 routes decision/preference/moment/...
// memories into their own dirs, so hardcoding only facts/corrections/procedures/
// reasoning-traces would silently write those categories in plaintext on
// encrypted stores. RECALL_FALLBACK_DIRS is the single source of truth for that
// set; the extra non-category markdown roots (artifacts/archive/entities/
// identity) are appended.
//
// questions/ is deliberately EXCLUDED (RECALL_FALLBACK_DIRS omits the non-memory
// queue dirs): the question queue is written/resolved through plain readFile/
// writeFile (StorageManager.writeQuestion/resolveQuestion), NOT the secure-file
// helpers. Encrypting questions/ here would make migration seal those files,
// after which resolveQuestion() would read ciphertext as UTF-8, fail to update
// the frontmatter, and overwrite/corrupt the file while returning success
// (codex #1563 review). Keeping questions/ plaintext preserves the queue's
// existing behavior; #1546 does not change question encryption.
const ENCRYPTABLE_MARKDOWN_STORAGE_ROOTS = new Set<string>([
  ...RECALL_FALLBACK_DIRS,
  "artifacts",
  "archive",
  "entities",
  "identity",
]);

const ENCRYPTABLE_STATE_SIDECARS = new Set([
  "state/behavior-signals.jsonl",
  "state/buffer-surprise-ledger.jsonl",
  "state/buffer.json",
  "state/compression-guideline-draft-state.json",
  "state/compression-guideline-state.json",
  "state/compression-guidelines.draft.md",
  "state/compression-guidelines.md",
  "state/entity-synthesis-queue.json",
  "state/fact-hashes.txt",
  "state/memory-actions.jsonl",
  "state/memory-lifecycle-ledger.jsonl",
  "state/meta.json",
  "state/reextract-jobs.jsonl",
  "state/topics.json",
]);

function isEncryptableStateSidecar(normalized: string): boolean {
  // state/dropped/ holds copies of extraction-buffer turns dropped after
  // repeated extraction failures — same content sensitivity as buffer.json.
  return ENCRYPTABLE_STATE_SIDECARS.has(normalized) || normalized.startsWith("state/dropped/");
}

/**
 * Per-session buffer state files (`state/buffer/<session>.json`) hold the same
 * buffered turns the legacy `state/buffer.json` held, so they are encryptable
 * state sidecars too — otherwise enabling the secure store would leave the
 * daemon's buffered turns in plaintext on disk.
 */
function isEncryptableBufferSessionFile(normalized: string): boolean {
  return normalized.startsWith("state/buffer/") && normalized.endsWith(".json");
}

function isEncryptableSummarySidecar(normalized: string): boolean {
  return normalized.startsWith("summaries/") && normalized.endsWith(".json");
}

const DECRYPTABLE_SIDECAR_ROOTS = new Set(["state", "indexes", "index", "provenance"]);

/**
 * consolidation-operator.ts — Standalone operator vocabulary + validators
 * for the consolidation subsystem (issue #561, All-Mem paper
 * arxiv:2603.19595).
 *
 * This module is intentionally dependency-free so storage, the `remnic
 * doctor` check (PR 4), and the undo CLI (PR 5) can import the validators
 * without dragging in the full consolidation engine — which in turn pulls
 * in the Codex materialize runner and creates a `storage → consolidation
 * → codex-materialize-runner → storage` import cycle.
 *
 * The `semantic-consolidation.ts` module re-exports these symbols so
 * existing import paths continue to work.
 */

/**
 * Operator algebra for non-destructive consolidation.
 *
 * - `split`  — one source memory is rewritten as multiple smaller memories.
 * - `merge`  — multiple source memories are collapsed into one canonical
 *   memory.
 * - `update` — a newer value supersedes an older value within the same
 *   logical fact.
 * - `pattern-reinforcement` (issue #687 PR 2/4) — emitted by the
 *   pattern-reinforcement maintenance job when it clusters duplicate
 *   non-procedural memories and promotes the most recent member to
 *   canonical.  Unlike the other operators, the job does not produce
 *   page-versioning snapshots — it just stamps reinforcement metadata
 *   on the canonical and points superseded duplicates at it.  See
 *   `maintenance/pattern-reinforcement.ts`.
 */
export type ConsolidationOperator =
  | "split"
  | "merge"
  | "update"
  | "pattern-reinforcement";

/**
 * Allowed values for the `derived_via` frontmatter field.  Used by storage
 * validation to reject unknown operator values on write.
 */
export const CONSOLIDATION_OPERATORS: readonly ConsolidationOperator[] = [
  "split",
  "merge",
  "update",
  "pattern-reinforcement",
] as const;

/**
 * Regular expression for validating a single `derived_from` entry.
 *
 * Format: `<non-empty memory path>:<integer version >= 0>`.  Matches the
 * `path:versionNumber` convention used by `page-versioning.ts` snapshots
 * (e.g. `"facts/preferences.md:3"`).  The path portion is greedy-last so
 * paths that themselves contain a colon remain parseable — only the final
 * `:<digits>` is consumed as the version.
 */
const DERIVED_FROM_ENTRY_RE = /^(.+):(\d+)$/;

/**
 * Regular expression for validating a memory-id `derived_from` entry
 * (issue #687 PR 2/4).  Pattern reinforcement records source memory IDs
 * directly rather than page-versioning snapshots, so we also need to
 * accept that shape.
 *
 * Memory IDs are alphanumeric with hyphens, underscores, or COLONS —
 * the namespace-prefixed form (e.g. `global:fact-abc-123`,
 * `entity:person-alice`) is a legitimate ID format already used
 * throughout the graph-retrieval code path (`stripDerivedFromVersion`).
 * The disambiguation against `<path>:<version>` is *not* "no colons
 * allowed" — it's "the segment after the last colon must NOT be a
 * non-negative integer" (PR #730 review feedback, Codex P1).
 *
 * Slashes and dots remain forbidden so paths cannot accidentally pass
 * as memory IDs.
 *
 * Exported so the consolidation-provenance integrity scanner (PR
 * #730 review feedback) can recognize bare memory IDs instead of
 * flagging them as malformed snapshot references.
 */
export const DERIVED_FROM_MEMORY_ID_RE = /^[A-Za-z0-9][A-Za-z0-9_:-]*$/;

/**
 * Disambiguator: an entry is a `<path>:<version>` snapshot reference
 * iff it ends with `:<digits>` AND the left side contains a `/` or
 * `.` (path-shape).  Without the path-shape requirement a legitimate
 * namespace-prefixed memory id like `global:42` would be silently
 * misinterpreted as a snapshot reference.
 *
 * This mirrors the precedence used by `stripDerivedFromVersion` in
 * `graph-retrieval.ts`: only strip the trailing `:<digits>` when the
 * left side actually looks like a stored path.
 */
function looksLikeSnapshotEntry(entry: string): boolean {
  const match = entry.match(DERIVED_FROM_ENTRY_RE);
  if (!match) return false;
  const pathPart = match[1];
  // A real snapshot path always contains a directory separator or a
  // file extension dot.  Memory IDs use neither.
  return pathPart.includes("/") || pathPart.includes(".");
}

/**
 * Validate a `derived_from` entry string.  Returns `true` for either
 * - the snapshot format `<non-empty path>:<integer >= 0>` (issue #561), or
 * - a memory-id of the form `[A-Za-z0-9][A-Za-z0-9_:-]*` (issue #687
 *   PR 2/4 — used by pattern-reinforcement provenance).  Memory IDs
 *   may include `:` for namespace-prefixed forms like
 *   `global:fact-abc-123` (PR #730 review feedback, Codex P1).
 *
 * Disambiguation rule: only treat the entry as `<path>:<version>` when
 * the trailing segment after the last `:` is a non-negative integer
 * AND the left side looks like a path (contains `/` or `.`).
 * Otherwise treat the entire string as a memory ID.  This is the same
 * heuristic the graph retrieval path uses when splitting derived_from
 * references back into a memory id.
 *
 * Kept pure so storage and future CLI/doctor paths can share the same
 * validator.
 */
export function isValidDerivedFromEntry(entry: unknown): entry is string {
  if (typeof entry !== "string") return false;
  if (entry.length === 0) return false;
  // Snapshot format takes precedence ONLY when the left side looks
  // like a real path.  This avoids misclassifying memory IDs whose
  // tail happens to be numeric (e.g. `global:42`).
  if (looksLikeSnapshotEntry(entry)) {
    const match = entry.match(DERIVED_FROM_ENTRY_RE);
    if (!match) return false;
    const pathPart = match[1];
    if (pathPart.length === 0 || pathPart.trim().length === 0) return false;
    const versionNum = Number(match[2]);
    return Number.isInteger(versionNum) && versionNum >= 0;
  }
  // Otherwise treat as a memory ID.  Empty or `:`-only entries are
  // already excluded by the leading-alphanumeric requirement of the
  // regex.
  return DERIVED_FROM_MEMORY_ID_RE.test(entry);
}

/**
 * Type guard for `ConsolidationOperator`.
 */
export function isConsolidationOperator(value: unknown): value is ConsolidationOperator {
  return (
    typeof value === "string" &&
    (CONSOLIDATION_OPERATORS as readonly string[]).includes(value)
  );
}

/**
 * Narrow operator vocabulary for the LLM-driven semantic-consolidation
 * pass (issue #561 PR 3).  This explicitly excludes
 * `"pattern-reinforcement"` (issue #687 PR 2/4), which is reserved for
 * the maintenance job and must NEVER be emitted by the consolidation
 * LLM.  Without this narrow gate, a hallucinated
 * `{"operator":"pattern-reinforcement"}` response from the LLM would
 * write misleading provenance on a semantic-consolidation memory
 * (Cursor Bugbot review, PR #730 head `aa1c2a8`).
 */
export type SemanticConsolidationLlmOperator = "split" | "merge" | "update";

const SEMANTIC_CONSOLIDATION_LLM_OPERATORS: readonly SemanticConsolidationLlmOperator[] = [
  "split",
  "merge",
  "update",
] as const;

/**
 * Type guard restricted to the operator subset the
 * semantic-consolidation LLM is allowed to emit.  Use this in any
 * code path that validates LLM output — `isConsolidationOperator` is
 * for validating values that came from disk / internal callers.
 */
export function isSemanticConsolidationLlmOperator(
  value: unknown,
): value is SemanticConsolidationLlmOperator {
  return (
    typeof value === "string" &&
    (SEMANTIC_CONSOLIDATION_LLM_OPERATORS as readonly string[]).includes(value)
  );
}

/**
 * Inline Source Attribution Protocol (issue #369)
 *
 * Extracted facts carry provenance inline inside the fact body, so the
 * citation survives hostile memory text, copy/paste, and LLM quoting. This
 * complements — never replaces — the YAML frontmatter provenance stored on
 * disk.
 *
 * Default format (matches issue #369 proposal):
 *
 *   The foo service uses Redis for rate limiting. [Source: agent=planner, session=abc123, ts=2026-04-10T14:25:07Z]
 *
 * Key properties:
 *   - Inline (part of the body, not metadata).
 *   - Compact (typically <80 chars of overhead per fact).
 *   - Machine-parseable by a single regex.
 *   - Opt-in via `inlineSourceAttributionEnabled` config flag (default off
 *     for backwards compatibility with existing downstream consumers).
 *   - Legacy facts without a citation remain fully readable.
 *
 * The format template is configurable via `inlineSourceAttributionFormat`
 * with supported placeholders:
 *
 *   {agent}     — principal / agent identifier
 *   {session}   — full session key (colon-delimited)
 *   {sessionId} — short stable session id (trailing component)
 *   {ts}        — extraction timestamp (ISO 8601)
 *   {date}      — extraction date (YYYY-MM-DD)
 *
 * Any privacy-sensitive identifiers should be normalized before being passed
 * to `formatCitation` — the helper treats them as opaque strings.
 */

/** Default citation format template (matches issue #369). */
export const DEFAULT_CITATION_FORMAT =
  "[Source: agent={agent}, session={sessionId}, ts={ts}]";

/** Sentinel value used when a provenance field is missing. */
export const CITATION_UNKNOWN = "unknown";

export interface CitationContext {
  /** Principal / agent identifier (e.g. resolved via resolvePrincipal). */
  agent?: string;
  /** Full session key (e.g. "agent:planner:main"). */
  session?: string;
  /**
   * Opaque short session id. Derived from the trailing component of the
   * session key when not provided explicitly. Use this for compact formats
   * that do not need the full colon-delimited session key.
   */
  sessionId?: string;
  /** Extraction timestamp as an ISO 8601 string. */
  ts?: string;
}

export interface ParsedCitation {
  /** Agent identifier parsed from the citation (never crashes on malformed input). */
  agent?: string;
  /** Session identifier parsed from the citation. */
  session?: string;
  /** Extraction timestamp parsed from the citation. */
  ts?: string;
  /** The full matched citation substring. */
  raw: string;
}

/**
 * Regex that matches the default `[Source: agent=X, session=Y, ts=Z]` shape
 * as well as human-edited variants (extra whitespace, reordered fields,
 * subset of fields). Matches non-greedily so it can be anchored anywhere in
 * the text. Kept as a getter factory so callers do not share regex state.
 */
function defaultCitationMatcher(): RegExp {
  // Bounded repetition {1,1024} instead of + so the match cannot backtrack
  // polynomially over hostile memory text (CodeQL js/polynomial-redos). A real
  // citation is far shorter than 1024 chars, so this is behavior-preserving for
  // any genuine [Source: …] block; only pathological/oversized input is excluded.
  return /\[Source:([^\]\n]{1,1024})\]/gi;
}

// Linear trailing-whitespace trim. Replaces text.replace(/\s+$/u, ""), whose
// anchored quantifier backtracks polynomially on long inputs (CodeQL
// js/polynomial-redos). Matches the exact \s (with u flag) semantics one char
// at a time, so the trailing-content preservation logic in attachCitation is
// unaffected.
function trimTrailingWhitespace(text: string): string {
  let end = text.length;
  while (end > 0 && /\s/u.test(text[end - 1]!)) end--;
  return text.slice(0, end);
}

/**
 * Derive a short session id from a full session key.
 * Falls back to the raw session string if no colon is present.
 */
export function deriveSessionId(session: string | undefined): string | undefined {
  if (!session) return undefined;
  const trimmed = session.trim();
  if (trimmed.length === 0) return undefined;
  const parts = trimmed.split(":").filter((p) => p.length > 0);
  if (parts.length === 0) return trimmed;
  return parts[parts.length - 1];
}

/**
 * Format an inline citation tag using the provided template.
 *
 * Missing context fields fall back to {@link CITATION_UNKNOWN} — the caller
 * should always get a non-empty, parseable tag.
 *
 * Uses a single-pass substitution so that values which themselves contain
 * placeholder syntax (e.g. an agent literally named `"{ts}"`) cannot be
 * re-interpreted by subsequent replacement steps. Each placeholder slot
 * receives exactly one lookup and the substituted value is treated as
 * terminal text, not template source.
 */
export function formatCitation(
  ctx: CitationContext,
  template: string = DEFAULT_CITATION_FORMAT,
): string {
  const session = ctx.session ?? "";
  const sessionId = ctx.sessionId ?? deriveSessionId(session) ?? CITATION_UNKNOWN;
  const ts = ctx.ts ?? CITATION_UNKNOWN;
  const agent = ctx.agent && ctx.agent.trim().length > 0 ? ctx.agent : CITATION_UNKNOWN;
  const date = ts && ts !== CITATION_UNKNOWN ? ts.slice(0, 10) : CITATION_UNKNOWN;
  const sessionForTemplate = session.trim().length > 0 ? session : CITATION_UNKNOWN;

  // Map from recognised placeholder names to their resolved value. Unknown
  // placeholder names are left intact (returning the original `{name}`).
  const values: Record<string, string> = {
    agent,
    session: sessionForTemplate,
    sessionId,
    ts,
    date,
  };

  // Single-pass scan: replace every recognised `{name}` in one sweep so that
  // substituted values cannot themselves be treated as template source on a
  // subsequent pass. The replacer-function form also guarantees that `$` /
  // `$&` / `$1` sequences inside values are emitted literally.
  return template.replace(/\{([a-zA-Z_][\w]*)\}/g, (match, name: string) => {
    return Object.prototype.hasOwnProperty.call(values, name)
      ? values[name]!
      : match;
  });
}

/**
 * Returns true if the text already carries at least one citation marker.
 * Safe to call on any string — never throws.
 */
export function hasCitation(text: string): boolean {
  if (typeof text !== "string" || text.length === 0) return false;
  return defaultCitationMatcher().test(text);
}

/**
 * Escape a string for use as a regex literal.
 */
function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Escape a single character for use INSIDE a character class `[...]`.
 * Special chars inside character classes: `]`, `\`, `^`, `-`.
 */
function escapeRegExpCharClass(ch: string): string {
  if (ch === "]") return "\\]";
  if (ch === "\\") return "\\\\";
  if (ch === "^") return "\\^";
  if (ch === "-") return "\\-";
  // Other regex meta chars are NOT special inside [...] but escaping them is safe.
  return escapeRegExp(ch);
}

/**
 * Build a per-placeholder token pattern that excludes newlines, whitespace,
 * and any punctuation characters used as inner separators in the template.
 *
 * This prevents a placeholder span from consuming separator bytes and
 * matching strings that cross separator boundaries in user-supplied content.
 *
 * @param nonWordSepChars - Set of non-word (non-alphanumeric, non-`_`) chars
 *   extracted from the inner separator literals of the template.
 */
function buildTokenPattern(nonWordSepChars: Set<string>): string {
  // Always exclude newlines and whitespace.
  const base = "\\n\\s";
  if (nonWordSepChars.size === 0) {
    // No inner separator punctuation — the placeholder spans the full space
    // between prefix and suffix. Fall back to a generous no-newline match.
    return `[^\\n]+?`;
  }
  const escaped = [...nonWordSepChars].map(escapeRegExpCharClass).join("");
  return `[^${base}${escaped}]+?`;
}

/** Regex that matches a `{placeholder}` token inside a template string. */
const PLACEHOLDER_REGEX = /\{[a-zA-Z_][\w]*\}/g;

/**
 * Build a regex that matches a citation produced by the given template.
 *
 * The approach depends on the shape of the template:
 *
 *  - **Normal case (non-empty literal prefix or suffix).** Anchor the match
 *    on the outer literal frame and reconstruct the interior as
 *    `interToken + sep + interToken + sep + ... + sep + lastToken`.
 *    All **intermediate** per-placeholder tokens exclude the combined set of
 *    non-word separator characters used between any two adjacent placeholders,
 *    preventing a value from consuming a separator and crossing placeholder
 *    boundaries.  The **last** token is only required to avoid newlines because
 *    it is terminated by the literal suffix anchor — this lets placeholder
 *    values that legitimately contain a separator character be recognised (e.g.
 *    an ISO-8601 timestamp `2026-04-10T14:25:07Z` in `[src:{agent}:{ts}]`
 *    where `:` is the inter-placeholder separator).  A template like
 *    `[src:{agent}/{sessionId}@{date}]` emits
 *    `\[src:[^\n\s/@]+?\/[^\n\s/@]+?@[^\n]+?\]` so that `[src:foo/bar]`
 *    is NOT matched (wrong separator count), `[src:foo/bar/extra@2026]`
 *    is NOT matched (intermediate token crosses a `/` boundary), and
 *    `[src:planner/main@2026-04-10]` IS matched correctly.
 *
 *  - **Placeholder-bounded with whitespace separator.** Both prefix and
 *    suffix are empty and the separator literal(s) between placeholders
 *    contain at least one whitespace character (e.g. `{source}: {content}`,
 *    `{agent} {sessionId}`). A whitespace-containing separator produces
 *    output that is visually indistinguishable from ordinary prose, so the
 *    safe strategy is to require a **hard bracket/paren/angle delimiter** on
 *    both sides of the reconstructed match. Prose almost never places
 *    `[...]` / `(...)` / `<...>` around a phrase, so this yields clean
 *    false-positive rejection.
 *
 *  - **Placeholder-bounded with compact (non-whitespace) separator.** Both
 *    prefix and suffix are empty and the separator literal(s) contain NO
 *    whitespace (e.g. `{agent}:{sessionId}`, `{agent}/{sessionId}`).
 *    `formatCitation` emits a compact token like `planner:main` with no
 *    surrounding delimiters, so the bracket strategy cannot detect it.
 *    Instead, the pattern requires that the entire token is bordered by
 *    whitespace or a bracket/paren/angle on each side:
 *
 *      `(?:(?<=[\[\(\<])|(?<!\S))[\w.-]+<sep>[\w.-]+(?:(?=[\]\)\>])|(?!\S))`
 *
 *    This accepts `planner:main` when it appears standalone or inside a
 *    bracket-wrapped token, and rejects `host:80` embedded inside a URL like
 *    `http://host:80` because `host` is immediately preceded by `/`
 *    (non-whitespace, non-bracket).
 *
 *  - **All-placeholder case (no literals between placeholders either).** No
 *    reliable regex can be built — a template like `{agent}{sessionId}`
 *    contains no anchor characters. Returns `null`; {@link
 *    hasCitationForTemplate} treats this as "cannot detect" and returns
 *    false, falling back on explicit sentinel/format detection only for the
 *    default `[Source: ...]` shape.
 *
 * Returns `null` when the template has no placeholders (fully-literal
 * citation, handled by the string-equality fast path in {@link
 * hasCitationForTemplate}) **or** when the template is entirely placeholder-
 * only with no literal content whatsoever.
 */
function templateMatcher(template: string): RegExp | null {
  // Split around all {placeholder} tokens.
  const parts = template.split(PLACEHOLDER_REGEX);
  if (parts.length <= 1) return null;

  const prefix = parts[0] ?? "";
  const suffix = parts[parts.length - 1] ?? "";

  // Normal case: at least one literal frame on the outside.
  // Tighten the per-placeholder token so it cannot consume separator
  // characters and match strings that cross separator boundaries
  // (Finding 3 — Uru3).
  if (prefix.length > 0 || suffix.length > 0) {
    const escapedPrefix = escapeRegExp(prefix);
    const escapedSuffix = escapeRegExp(suffix);

    // Inner parts: literal separators that sit between adjacent placeholders.
    // For `[src:{agent}/{sessionId}@{date}]`, parts = ["[src:", "/", "@", "]"]
    // so innerParts = ["/", "@"].
    const innerParts = parts.slice(1, -1);

    // Collect only the non-word (punctuation/symbol) characters from each
    // inner separator so alphabetic separator text (unlikely but valid) does
    // not exclude letters from the per-placeholder token pattern.
    const nonWordSepChars = new Set<string>();
    for (const sep of innerParts) {
      for (const ch of sep) {
        if (!/\w/.test(ch)) {
          nonWordSepChars.add(ch);
        }
      }
    }

    // All intermediate tokens (every placeholder except the last) use the
    // combined exclusion so they cannot cross placeholder boundaries.
    //
    // The LAST token is different: it is terminated by the literal suffix anchor
    // (e.g. `\]`), so it does not need to exclude inner-separator characters.
    // Dropping that restriction lets placeholder values that legitimately contain
    // a separator character (e.g. an ISO-8601 timestamp `2026-04-10T14:25:07Z`
    // in template `[src:{agent}:{ts}]`) be recognised correctly instead of
    // producing false-negative misses that trigger duplicate citation injection.
    //
    // Only the LAST token is relaxed.  Intermediate tokens keep the combined
    // exclusion so that cross-boundary false positives are still rejected
    // (e.g. `[src:foo/bar/extra@2026-04-11]` for `[src:{a}/{b}@{c}]`).
    const interToken = buildTokenPattern(nonWordSepChars);
    // Last token: terminated by suffix anchor — exclude only newlines.
    const lastToken = buildTokenPattern(new Set<string>());

    // Reconstruct the interior: interToken sep interToken sep ... sep lastToken
    // (or just lastToken when there are no inner separators at all).
    const middle =
      innerParts.length === 0
        ? lastToken
        : interToken +
          innerParts
            .slice(0, -1)
            .map((sep) => escapeRegExp(sep) + interToken)
            .join("") +
          escapeRegExp(innerParts[innerParts.length - 1]!) +
          lastToken;

    const pattern = escapedPrefix + middle + escapedSuffix;
    return new RegExp(pattern, "i");
  }

  // Placeholder-bounded case: prefix and suffix are both empty.
  const middleLiterals = parts.slice(1, -1);
  const hasNonEmptyMiddle = middleLiterals.some((p) => p.length > 0);
  if (!hasNonEmptyMiddle) {
    // All-placeholder template with no literal content. Impossible to anchor
    // reliably without sentinel markers; signal the caller.
    return null;
  }

  // Identifier token: one or more word chars, dots, dashes, or colons.
  // Colons are included to allow timestamp values like "10:30" or session
  // keys like "agent:planner:main" inside compact placeholder-bounded
  // templates.  URL-like fragments (`http://host:80`) are still rejected
  // because the lead anchor requires whitespace or a bracket immediately
  // before the first id-token group (`http` is preceded by `/`).
  const idToken = "[\\w.:-]+";
  const body =
    idToken +
    middleLiterals.map((lit) => escapeRegExp(lit) + idToken).join("");

  const separatorText = middleLiterals.join("");
  if (/\s/.test(separatorText)) {
    // Separator contains whitespace: the emitted citation looks like ordinary
    // prose (e.g. `planner main`). Require a hard bracket/paren/angle
    // delimiter on both sides to prevent false matches on English text.
    const opener = "[\\[\\(\\<]";
    const closer = "[\\]\\)\\>]";
    return new RegExp(opener + body + closer, "i");
  }

  // Separator is compact (no whitespace): `formatCitation` emits a token like
  // `planner:main` without surrounding delimiters. The challenge is that the
  // same token shape also matches ordinary hyphenated or slashed prose words
  // (e.g. `long-term`, `docs/setup`), causing `hasCitationForTemplate` to
  // return true on uncited fact bodies and silently suppress citation injection
  // from `attachCitation`.
  //
  // Fix (Finding 1): tighten the trail anchor so a bare compact token is only
  // accepted when it sits at the very end of the string (possibly followed by
  // optional trailing whitespace or a newline). Since `attachCitation` always
  // appends the citation at the trimmed end of the fact body, a real citation
  // token will always appear at the tail. Prose like `"long-term solution"`
  // has `long-term` in the middle of the string (followed by ` solution`), so
  // the end-of-string anchor rejects it — no false positive, no silent drop.
  //
  // The lead anchor still accepts either a bracket opener or a whitespace
  // boundary (or start of string), so `"Fact. planner:main"` and standalone
  // `"planner:main"` are both detected after the first attachment pass.
  //
  // Bracket-wrapped form (e.g. `[planner:main]`) is also accepted via the
  // opener/closer pair — bracket still takes precedence over end-of-string.
  //
  // Example — why `http://host:80` does NOT match:
  //   Trying to match `host:80`: the char before `h` is `/` (non-whitespace,
  //   non-bracket), so `(?<=[\[\(\<])` and `(?<!\S)` both fail ⟹ no match.
  //   Trying to match `http:...`: after `http:` the next chars are `//` which
  //   are not `[\w.-]+`, so the second id-token group fails ⟹ no match.
  const leadAnchor = "(?:(?<=[\\[\\(\\<])|(?<!\\S))";
  // Trail: either a bracket closer (for `[token]` shape) or end-of-string
  // optionally preceded by whitespace. The `(?!\S)` is deliberately removed
  // so that a compact token in the MIDDLE of a sentence does not match.
  const trailAnchor = "(?:(?=[\\]\\)\\>])|(?=\\s*$))";
  return new RegExp(leadAnchor + body + trailAnchor, "i");
}

/**
 * Returns true if `text` already carries a citation produced by `template`
 * **or** by the default `[Source: ...]` format (for facts that were tagged
 * before a config change).
 *
 * Use this instead of {@link hasCitation} whenever the caller has access to
 * the configured `inlineSourceAttributionFormat`.
 *
 * All-placeholder templates such as `{agent}{sessionId}` have no literal
 * content to anchor on and therefore cannot be reliably detected without
 * dedicated sentinel markers. In that case the function returns `false` —
 * callers that need idempotent dedup for such templates should either adopt
 * a template with literal delimiters (recommended) or rely on the default
 * `[Source: ...]` marker detection which is always available via
 * {@link hasCitation}.
 */
export function hasCitationForTemplate(text: string, template: string): boolean {
  if (typeof text !== "string" || text.length === 0) return false;
  // Always accept the default format as a fallback so facts tagged before a
  // configuration change are not double-tagged on reprocessing.
  if (hasCitation(text)) return true;
  // If the configured template matches the default, we're done.
  //
  // Known limitation (Thread 2 — Codex P2): this fast path exits without
  // checking whether the content carries a citation from a DIFFERENT custom
  // template that was active before the config was changed back to the default.
  // Such a fact would be detected by `hasCitation` above only if the prior
  // custom template happened to match the default `[Source: ...]` pattern.
  // In practice, template changes mid-stream are rare, and the false-negative
  // (missing an old custom citation) produces a benign duplicate citation rather
  // than data loss. A full fix would require storing the citation template used
  // at write time in the frontmatter and checking that here.
  if (template === DEFAULT_CITATION_FORMAT) return false;

  // Fully-literal template (no placeholders): exact inclusion check.
  if (!PLACEHOLDER_REGEX.test(template)) {
    // Reset lastIndex because PLACEHOLDER_REGEX is declared with /g.
    PLACEHOLDER_REGEX.lastIndex = 0;
    return text.includes(template);
  }
  // Reset lastIndex after the .test() probe above.
  PLACEHOLDER_REGEX.lastIndex = 0;

  const matcher = templateMatcher(template);
  if (!matcher) {
    // All-placeholder template: cannot build a reliable matcher. See the
    // docstring — callers should not rely on dedup for this shape.
    return false;
  }
  return matcher.test(text);
}

/**
 * Return the LAST citation marker in `text` for the given template (or the
 * default `[Source: ...]` shape). `attachCitation` always appends at the
 * trimmed end, so the last occurrence is the most recently attached marker —
 * callers use this to lift a just-attached citation off a cited body and
 * re-attach it to a derived body (the merged-target commit path). Returns
 * null when the text carries no marker of this template (including
 * all-placeholder templates that cannot be matched reliably).
 */
export function lastCitationMarkerForTemplate(
  text: string,
  template: string = DEFAULT_CITATION_FORMAT,
): string | null {
  if (typeof text !== "string" || text.length === 0) return null;
  let matcher: RegExp | null;
  if (template === DEFAULT_CITATION_FORMAT) {
    matcher = defaultCitationMatcher();
  } else if (!PLACEHOLDER_REGEX.test(template)) {
    // Fully-literal template: presence is exact inclusion (no placeholders
    // to widen the match).
    PLACEHOLDER_REGEX.lastIndex = 0;
    return text.includes(template) ? template : null;
  } else {
    PLACEHOLDER_REGEX.lastIndex = 0;
    matcher = templateMatcher(template);
  }
  if (!matcher) return null;
  const global = new RegExp(
    matcher.source,
    matcher.flags.includes("g") ? matcher.flags : matcher.flags + "g",
  );
  let last: string | null = null;
  for (let match = global.exec(text); match !== null; match = global.exec(text)) {
    last = match[0];
    if (match[0].length === 0) global.lastIndex++;
  }
  return last;
}

/**
 * True when a template can be matched and stripped later. All-placeholder
 * templates such as `{agent}{sessionId}` have no literal anchors.
 */
export function citationTemplateIsDetectable(template: string): boolean {
  if (typeof template !== "string" || template.length === 0) return false;
  if (template === DEFAULT_CITATION_FORMAT) return true;
  PLACEHOLDER_REGEX.lastIndex = 0;
  if (!PLACEHOLDER_REGEX.test(template)) {
    PLACEHOLDER_REGEX.lastIndex = 0;
    return true;
  }
  PLACEHOLDER_REGEX.lastIndex = 0;
  return templateMatcher(template) !== null;
}

/**
 * Templates the merge path may lift, preserve, or strip. Longest
 * templates first so an overlapping custom marker beats an inner default
 * match; the current template wins equal-length ties. Undetectable
 * shapes are dropped so we never hash or attach a marker we cannot re-match.
 */
export function citationTemplatesToRecognize(
  primary: string | undefined,
  extra: readonly string[] = [],
): string[] {
  const out: string[] = [];
  const add = (template: string | undefined): void => {
    if (typeof template !== "string" || template.length === 0) return;
    if (!citationTemplateIsDetectable(template)) return;
    if (!out.includes(template)) out.push(template);
  };
  add(primary);
  for (const template of extra) add(template);
  add(DEFAULT_CITATION_FORMAT);
  out.sort((a, b) => {
    if (b.length !== a.length) return b.length - a.length;
    if (a === primary && b !== primary) return -1;
    if (b === primary && a !== primary) return 1;
    return 0;
  });
  return out;
}

/**
 * Prior formats the caller still holds, if any. Absent or malformed
 * history is ignored — fail safe, do not invent templates.
 */
export function citationTemplatesForMerge(config: {
  inlineSourceAttributionFormat?: string;
  inlineSourceAttributionFormatHistory?: unknown;
}): string[] {
  const raw = config.inlineSourceAttributionFormatHistory;
  const extra = Array.isArray(raw)
    ? raw.filter((value): value is string => typeof value === "string" && value.length > 0)
    : [];
  return citationTemplatesToRecognize(config.inlineSourceAttributionFormat, extra);
}

export function lastRecognizedCitationMarker(
  text: string,
  templates: readonly string[],
): string | null {
  for (const template of templates) {
    const marker = lastCitationMarkerForTemplate(text, template);
    if (marker) return marker;
  }
  return null;
}

export function stripRecognizedCitations(text: string, templates: readonly string[]): string {
  let out = text;
  for (const template of templates) {
    out = stripCitationForTemplate(out, template);
  }
  return out;
}

/**
 * Attach an inline citation to fact text.
 *
 * If the text already has a citation — either the default `[Source: ...]`
 * marker or one produced by the configured template — it is returned unchanged.
 * Existing provenance is respected and never overwritten. Otherwise the
 * citation is appended to the trimmed text with a single space separator,
 * which keeps the marker visually adjacent to the fact body.
 */
export function attachCitation(
  text: string,
  ctx: CitationContext,
  template: string = DEFAULT_CITATION_FORMAT,
): string {
  if (typeof text !== "string") return text as unknown as string;
  if (hasCitationForTemplate(text, template)) return text;
  const trimmedEnd = trimTrailingWhitespace(text);
  if (trimmedEnd.length === 0) return text;
  const citation = formatCitation(ctx, template);
  // Preserve any trailing newline that callers rely on for markdown rendering.
  const trailing = text.slice(trimmedEnd.length);
  return `${trimmedEnd} ${citation}${trailing}`;
}

/**
 * Parse a single inline citation from a piece of text. Returns the first
 * citation encountered or `null` when none is present. Malformed citations
 * do not throw — fields that cannot be parsed simply remain `undefined`.
 */
export function parseCitation(text: string): ParsedCitation | null {
  if (typeof text !== "string" || text.length === 0) return null;
  const matcher = defaultCitationMatcher();
  const match = matcher.exec(text);
  if (!match) return null;

  const body = match[1] ?? "";
  const raw = match[0] ?? "";
  const parsed: ParsedCitation = { raw };

  const fields = body
    .split(",")
    .map((segment) => segment.trim())
    .filter((segment) => segment.length > 0);

  for (const field of fields) {
    const eqIdx = field.indexOf("=");
    if (eqIdx <= 0) continue;
    const key = field.slice(0, eqIdx).trim().toLowerCase();
    const value = field.slice(eqIdx + 1).trim();
    if (value.length === 0) continue;
    switch (key) {
      case "agent":
        parsed.agent = value;
        break;
      case "session":
      case "sessionid":
        parsed.session = value;
        break;
      case "ts":
      case "timestamp":
        parsed.ts = value;
        break;
      default:
        // Unknown fields are ignored defensively so human edits never crash.
        break;
    }
  }

  return parsed;
}

/**
 * Parse every citation embedded in the text. Always returns an array; empty
 * when none are present.
 */
export function parseAllCitations(text: string): ParsedCitation[] {
  if (typeof text !== "string" || text.length === 0) return [];
  const matcher = defaultCitationMatcher();
  const results: ParsedCitation[] = [];
  let match: RegExpExecArray | null;
  while ((match = matcher.exec(text)) !== null) {
    const parsed = parseCitation(match[0]);
    if (parsed) results.push(parsed);
  }
  return results;
}

/**
 * Remove all inline citations from a piece of text.
 *
 * Callers that want the raw fact body (for dedup hashing, display, or
 * comparison) should use this helper instead of hand-rolled regexes so the
 * whole codebase agrees on the citation syntax.
 *
 * Finding 2 fix: when the input contains no citation marker, the input is
 * returned byte-for-byte unchanged. When a citation IS removed, whitespace
 * normalization is applied only at each join seam (the single space between
 * the preceding text and where the citation was), rather than across the
 * entire string. This preserves markdown hard-break spacing, aligned text,
 * and code-like snippets in fact bodies that happen to carry a citation.
 *
 * Implementation: each citation match is replaced by its "seam fix" — the
 * content before the match has its trailing whitespace trimmed and then a
 * single space is appended if any text remains, collapsing only the gap
 * left by the removed marker. Whitespace elsewhere in the body is untouched.
 */
export function stripCitation(text: string): string {
  if (typeof text !== "string" || text.length === 0) return text;
  // Early exit: no citation marker present — return the input unchanged so
  // that callers never lose formatting fidelity on uncited strings.
  if (!hasCitation(text)) return text;

  // Walk through all citations and slice them out one by one so that we can
  // normalise ONLY the whitespace at each seam rather than the entire string.
  const matcher = defaultCitationMatcher();
  let result = "";
  let lastIndex = 0;

  let match: RegExpExecArray | null;
  while ((match = matcher.exec(text)) !== null) {
    // Text before this citation. Trim trailing spaces/tabs at the seam only.
    const before = text.slice(lastIndex, match.index).replace(/[ \t]+$/, "");
    result += before;
    lastIndex = match.index + match[0].length;
  }

  // Append any trailing text after the last citation. Trim leading
  // spaces/tabs and trailing whitespace at the join seam.
  const after = text.slice(lastIndex).replace(/^[ \t]+/, "");
  if (after.length > 0) {
    if (result.length > 0) result += " ";
    result += after;
  }

  return result.trimEnd();
}

/**
 * Strip an inline citation from text using a specific template regex.
 *
 * This is the template-aware counterpart to {@link stripCitation}. When the
 * caller holds the configured `inlineSourceAttributionFormat`, use this
 * function to strip citations produced by that template — including custom
 * templates that differ from the default `[Source: ...]` pattern.
 *
 * Behaviour:
 *  - If the text has a **default-format** citation, strips it first
 *    (always safe).
 *  - Then, if the result has a **custom-template** citation detected by
 *    `hasCitationForTemplate`, builds the template regex and removes every
 *    occurrence. BOTH passes run when a body carries both forms — a target
 *    written under the default format can carry the default marker plus a
 *    custom marker appended after a config change; returning after the
 *    default pass alone left the custom marker inside hash inputs (#2330).
 *  - Fully-literal templates (no placeholders) are stripped by exact match
 *    of the template text, the same inclusion check `hasCitationForTemplate`
 *    uses.
 *  - All-placeholder templates (no literal prefix/suffix/separator) cannot
 *    produce a reliable matcher. `hasCitationForTemplate` already returns
 *    `false` for such templates, so this function never attempts to strip an
 *    undetectable citation. The text is returned unchanged when no citation
 *    is detected.
 *  - If no citation is detected for the given template, returns the text
 *    unchanged.
 *
 * @returns The stripped text (or the original text when no citation is found).
 */
export function stripCitationForTemplate(
  text: string,
  template: string,
): string {
  if (typeof text !== "string" || text.length === 0) return text;

  // First pass: the default-format marker, if any. A second pass below still
  // runs — a body can carry the default marker AND the custom template's
  // marker, and canonicalization must remove every recognized form.
  const afterDefault = hasCitation(text) ? stripCitation(text) : text;

  if (!hasCitationForTemplate(afterDefault, template)) return afterDefault;

  PLACEHOLDER_REGEX.lastIndex = 0;
  if (!PLACEHOLDER_REGEX.test(template)) {
    PLACEHOLDER_REGEX.lastIndex = 0;
    return stripExactLiteralCitation(afterDefault, template);
  }
  PLACEHOLDER_REGEX.lastIndex = 0;

  // Build the template matcher. hasCitationForTemplate already returned true,
  // which means templateMatcher produced a non-null result. The null branch
  // here is a defensive fallback only — the default pass already ran.
  const matcher = templateMatcher(template);
  if (!matcher) return afterDefault;

  // The matcher regex was built without the global flag; add it for exec loop.
  const globalMatcher = new RegExp(
    matcher.source,
    matcher.flags.includes("g") ? matcher.flags : matcher.flags + "g",
  );
  let result = "";
  let lastIndex = 0;
  let match: RegExpExecArray | null;

  while ((match = globalMatcher.exec(afterDefault)) !== null) {
    const matchEnd = match.index + match[0].length;
    const enclosure = enclosingDelimiterRange(afterDefault, match.index, matchEnd);
    const removalStart = enclosure?.start ?? match.index;
    const removalEnd = enclosure?.end ?? matchEnd;
    const before = afterDefault.slice(lastIndex, removalStart).replace(/[ \t]+$/, "");
    result += before;
    lastIndex = removalEnd;
    // Guard against zero-width matches causing an infinite loop.
    if (match[0].length === 0) {
      globalMatcher.lastIndex++;
    }
  }

  const after = afterDefault.slice(lastIndex).replace(/^[ \t]+/, "");
  if (after.length > 0) {
    if (result.length > 0) result += " ";
    result += after;
  }

  return result.trimEnd();
}

function stripExactLiteralCitation(text: string, marker: string): string {
  if (marker.length === 0) return text;
  let result = "";
  let lastIndex = 0;
  let idx = text.indexOf(marker);
  if (idx === -1) return text;
  while (idx !== -1) {
    const before = text.slice(lastIndex, idx).replace(/[ \t]+$/, "");
    result += before;
    lastIndex = idx + marker.length;
    idx = text.indexOf(marker, lastIndex);
  }
  const after = text.slice(lastIndex).replace(/^[ \t]+/, "");
  if (after.length > 0) {
    if (result.length > 0) result += " ";
    result += after;
  }
  return result.trimEnd();
}

function enclosingDelimiterRange(
  text: string,
  start: number,
  end: number,
): { start: number; end: number } | undefined {
  if (start <= 0 || end >= text.length) return undefined;
  const opener = text[start - 1];
  const closer = text[end];
  if (
    (opener === "[" && closer === "]") ||
    (opener === "(" && closer === ")") ||
    (opener === "<" && closer === ">")
  ) {
    return { start: start - 1, end: end + 1 };
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// lifecycle/tombstones.ts — Tombstone store + non-resurrection invariant
// (issue #1579)
//
// A "tombstone" records that a fact has been retired (corrected, superseded,
// or retracted) so that the SAME fact cannot silently come back to life through
// any of the five resurrection paths:
//
//   1. Re-extraction (session replay, re-observation)
//   2. Importers (capsule / import-* payloads)
//   3. Consolidation merges
//   4. Dreams (REM re-derivation)
//   5. Pattern reinforcement (duplicate promotion)
//
// The invariant is enforced at the SINGLE storage persist path
// (`StorageManager.writeMemory` — the same chokepoint that records catalog
// writes, issue #1522). Every write path funnels through it, so paths (a)–(e)
// are blocked WITHOUT per-path code.
//
// File-first / rebuildable (the repo's storage philosophy): the JSONL at
// `<stateDir>/tombstones.jsonl` is a cache of truth. The authoritative sources
// are the memory files themselves (status: superseded/retracted) and the
// `corrections/` records. `rebuildTombstonesFromStorage` reconstructs the
// JSONL from those sources.
//
// Design rules honored (issue #1579 design section):
//   - Hash `rawContent` exactly as the dedup index does — one helper
//     (`ContentHashIndex.computeHash` / `normalizeContent`), never a second
//     (checklist §13; rule 23).
//   - Append-only log — never rewrite history; a later `kind: "revocation"`
//     entry re-allows (rule 25).
//   - Instance-scoped, never module-level (rule 11).
//   - Namespace-scoped — a tombstone in namespace A never blocks namespace B
//     (rule 42).
//   - Serialized appends with rejection recovery (rule 40).
//   - Never silent drop — a blocked write lands as pending_review + blockedBy
//     (rule 34).
//   - Do NOT register a blocked fact as an active dedup/index entry (rule 44).
//   - Off = pre-feature behavior for rollback safety (rule 30).
//   - Semantic tier (4) ships dark, off by default (rule 48).
// ---------------------------------------------------------------------------

import { serializeMutations, withHeldFileLock } from "../utils/serialize-mutations.js";
import {
  computeLegacyContentHash,
  isUnambiguousLegacyContentHash,
  normalizeLegacyContent,
} from "../content-hash.js";

/** Why a tombstone was emitted. */
export type TombstoneReason =
  | "correction"
  | "supersession"
  | "retraction"
  | "contradiction_resolution";

/** Who emitted the tombstone. */
export type TombstoneCreatedBy =
  | "user_correction"
  | "contradiction_resolution"
  | "supersession"
  | "chat";

/** Tier that matched on lookup. */
export type TombstoneMatchTier = "exact" | "normalized" | "keyed" | "semantic";

/**
 * A single append-only tombstone log entry.
 *
 * `kind: "tombstone"` blocks; `kind: "revocation"` re-allows. The log is
 * never rewritten — the NEWEST matching entry wins at lookup (rule 25).
 */
export interface TombstoneEntry {
  /** Stable tombstone id (`tomb-<ts>-<rand>`). */
  id: string;
  kind: "tombstone" | "revocation";
  reason: TombstoneReason;
  /** The memory that was retired. */
  sourceMemoryId: string;
  /** sha256 of the retired identity; explicit contentHashSource may define it. */
  contentHash: string;
  /** Current body hash retained alongside an ambiguous or explicit primary hash. */
  currentContentHashAlias?: string;
  /** Current normalized body used by the normalized lookup tier. */
  normalizedText: string;
  /** Version of the current body identity fields. */
  normalizerVersion?: number;
  entityRef?: string;
  /** Structured-attribute supersession key when one existed. */
  supersessionKey?: string;
  /** Stable operation identity for crash-recovery replay. */
  operationKey?: string;
  /** Namespace scope (rule 42). */
  namespace: string;
  createdAt: string;
  createdBy: TombstoneCreatedBy;
  /** For `kind: "revocation"`: the tombstone id being revoked. */
  revokes?: string;
}

/** A positive block decision returned by `TombstoneStore.lookup`. */
export interface TombstoneMatch {
  tombstoneId: string;
  matchedTier: TombstoneMatchTier;
  reason: TombstoneReason;
}

/** Inputs to a lookup. At least one discriminator must be present.
 *
 * Issue #1579 thread Ociag/Oci-W: `supersessionKeys` (plural) lets the write
 * chokepoint check EVERY derived key, not just the first. Emitters register
 * one tombstone per matched key (temporal-supersession, rebuild), so a block
 * can live on any later key; querying only `supersessionKeys[0]` missed it
 * and the retired fact resurrected as active. `supersessionKey` (singular)
 * remains for direct/unit callers; `lookup` checks the union of both. */
export interface TombstoneLookupQuery {
  contentHash?: string;
  normalizedText?: string;
  entityRef?: string;
  /** Single supersession key (direct/unit callers). */
  supersessionKey?: string;
  /** All derived supersession keys (write chokepoint). The keyed tier is
   * checked for each; the first active match wins. */
  supersessionKeys?: string[];
  namespace: string;
}

/** Configuration for a tombstone store instance. */
export interface TombstoneStoreOptions {
  enabled: boolean;
  semanticMatch: boolean;
  semanticThreshold: number;
  /** sha256 of raw content — wired to `ContentHashIndex.computeHash`. */
  hashContent: (raw: string) => string;
  /** Normalize raw content — wired to `ContentHashIndex.normalizeContent`. */
  normalizeText: (raw: string) => string;
  /**
   * Optional cosine similarity in [0, 1] for the semantic tier. When
   * undefined or when `semanticMatch` is false, the semantic tier is
   * skipped entirely.
   */
  semanticSimilarity?: (a: string, b: string) => number;
  /**
   * Resolve source identity candidates for bounded legacy sourceMemoryIds.
   * StorageManager reads the corpus before the tombstone write lock.
   */
  readonly sourceContentsForMemoryIds?: (
    sourceMemoryIds: readonly string[],
  ) => Promise<ReadonlyMap<string, string | readonly string[]>>;
  /** Maximum number of legacy entries considered during one load. */
  readonly legacyMigrationLimit?: number;
  /**
   * Cross-process write-lock timings for the tombstone JSONL mutation lock
   * (issue #1639). The secure-store append is a read-merge-write (read
   * encrypted → decrypt → concat → re-encrypt → atomic rename), so two
   * Remnic processes appending concurrently can each read the same contents
   * and the last writer drops the other's entry — breaking the
   * non-resurrection invariant. The lock serializes the mutation across
   * processes. When omitted, defaults that fit the short tombstone critical
   * section (mirroring the summary-snapshot lock): staleMs 30s, maxWaitMs 5s,
   * heartbeatMs floor(staleMs/3).
   */
  readonly lockStaleMs?: number;
  readonly lockMaxWaitMs?: number;
  readonly lockHeartbeatMs?: number;
}

/** Injected file I/O — the StorageManager wires its secure-store-aware
 * implementations so tombstones are encrypted at rest alongside other state.
 * `stat` is optional; when provided the store tracks the file mtime itself and
 * runs a cross-process staleness probe on each access (#1579). */
export interface TombstoneFileIo {
  read: (filePath: string) => Promise<string>;
  append: (filePath: string, content: string) => Promise<void>;
  write: (filePath: string, content: string) => Promise<void>;
  stat?: (filePath: string) => { mtimeMs: number };
}

/** Aggregate stats for `remnic doctor`. */
export interface TombstoneStats {
  count: number;
  revoked: number;
  lastAppendAt: string | null;
  corruptedLines: number;
  /** Whether the in-memory index matches the on-disk file (rebuild check). */
  loaded: boolean;
}

const TOMBSTONE_NORMALIZER_VERSION = 2;
const DEFAULT_LEGACY_MIGRATION_LIMIT = 10_000;

const TOMBSTONE_PREFIX = "tomb";

function newTombstoneId(): string {
  return `${TOMBSTONE_PREFIX}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

/** Deterministic key for the keyed tier (namespace + entityRef + supersessionKey).
 *
 * The namespace is part of the discriminator so two namespace-scoped stores
 * that share the same backing `tombstones.jsonl` (namespaces disabled, or the
 * same directory used with different namespace configs) cannot overwrite each
 * other's index entries — a later tombstone for namespace B with the same
 * entity/key no longer evicts namespace A's entry (issue #1579 thread Ocs-O). */
function keyedTierKey(namespace: string, entityRef: string, supersessionKey: string): string {
  return `${namespace}\0${entityRef}\0${supersessionKey}`;
}

/**
 * Parse one JSONL line into a TombstoneEntry, validating the discriminated
 * union. Returns `null` for malformed lines (rule 34 — skip with a counter,
 * never crash).
 */
export function parseTombstoneLine(line: string): TombstoneEntry | null {
  const trimmed = line.trim();
  if (trimmed.length === 0) return null;
  let parsed: unknown;
  try {
    parsed = JSON.parse(trimmed);
  } catch {
    return null;
  }
  if (!parsed || typeof parsed !== "object") return null;
  const e = parsed as Record<string, unknown>;
  if (typeof e.id !== "string" || e.id.length === 0) return null;
  if (e.kind !== "tombstone" && e.kind !== "revocation") return null;
  if (
    e.reason !== "correction" &&
    e.reason !== "supersession" &&
    e.reason !== "retraction" &&
    e.reason !== "contradiction_resolution"
  ) {
    return null;
  }
  if (typeof e.sourceMemoryId !== "string") return null;
  if (typeof e.contentHash !== "string") return null;
  if (typeof e.normalizedText !== "string") return null;
  if (typeof e.namespace !== "string") return null;
  if (typeof e.createdAt !== "string") return null;
  if (
    e.createdBy !== "user_correction" &&
    e.createdBy !== "contradiction_resolution" &&
    e.createdBy !== "supersession" &&
    e.createdBy !== "chat"
  ) {
    return null;
  }
  const out: TombstoneEntry = {
    id: e.id,
    kind: e.kind,
    reason: e.reason,
    sourceMemoryId: e.sourceMemoryId,
    contentHash: e.contentHash,
    normalizedText: e.normalizedText,
    namespace: e.namespace,
    createdAt: e.createdAt,
    createdBy: e.createdBy,
  };
  if (typeof e.currentContentHashAlias === "string") {
    out.currentContentHashAlias = e.currentContentHashAlias;
  }
  if (typeof e.normalizerVersion === "number" && Number.isInteger(e.normalizerVersion)) {
    out.normalizerVersion = e.normalizerVersion;
  }
  if (typeof e.operationKey === "string") out.operationKey = e.operationKey;
  if (typeof e.entityRef === "string") out.entityRef = e.entityRef;
  if (typeof e.supersessionKey === "string") out.supersessionKey = e.supersessionKey;
  if (typeof e.revokes === "string") out.revokes = e.revokes;
  return out;
}

/**
 * The instance-scoped tombstone store. One per StorageManager (rule 11),
 * namespace-scoped via `namespace` + the on-disk path (rule 42).
 *
 * The in-memory index is built lazily on first access and invalidated on
 * append + by the StorageManager's cache-invalidation chokepoint (rule 25).
 */
export class TombstoneStore {
  private entries: TombstoneEntry[] = [];
  /** contentHash → tombstone id (newest) — exact tier. */
  private readonly byHash = new Map<string, string>();
  /** normalizedText → tombstone id (newest) — normalized tier. */
  private readonly byNormalized = new Map<string, string>();
  /** entityRef\0supersessionKey → tombstone id (newest) — keyed tier. */
  private readonly byKey = new Map<string, string>();
  /** Tombstone ids that have a later revocation entry. */
  private readonly revokedIds = new Set<string>();
  /** id → entry index (newest only, for revocation lookups). */
  private readonly byId = new Map<string, TombstoneEntry>();
  private loaded = false;
  private loadPromise: Promise<void> | null = null;
  private corruptedLines = 0;
  private lastAppendAt: string | null = null;
  /**
   * Last-seen mtime of the JSONL file (cross-process staleness probe, #1579).
   * Tracked inside the store so the StorageManager wiring stays thin. When the
   * file's mtime advances past this value between accesses, the in-memory index
   * is stale (a peer process appended) and is reloaded before the next lookup.
   */
  private fileMtimeMs = 0;

  constructor(
    private readonly filePath: string,
    private readonly namespace: string,
    private readonly options: TombstoneStoreOptions,
    private readonly io: TombstoneFileIo,
  ) {
    const limit = this.options.legacyMigrationLimit;
    if (limit !== undefined && (!Number.isFinite(limit) || !Number.isInteger(limit) || limit < 0)) {
      throw new Error("legacyMigrationLimit must be a finite non-negative integer");
    }
    this.lockStaleMs = this.options.lockStaleMs ?? 30_000;
    this.lockMaxWaitMs = this.options.lockMaxWaitMs ?? 5_000;
    this.lockHeartbeatMs =
      this.options.lockHeartbeatMs ?? Math.max(100, Math.floor(this.lockStaleMs / 3));
  }

  /**
   * Resolved cross-process write-lock timings (issue #1639). Defaults mirror
   * the summary-snapshot lock: a tombstone append critical section is
   * sub-second, so a stale lock older than 30s is a crashed holder; bounded
   * acquisition gives up after 5s and strict-fails rather than clobbering a
   * concurrent writer (which would reintroduce the lost-write race this lock
   * closes).
   */
  private readonly lockStaleMs: number;
  private readonly lockMaxWaitMs: number;
  private readonly lockHeartbeatMs: number;

  /**
   * Sibling advisory lockfile: `<tombstones>.jsonl` → `<tombstones>.lock`.
   * Shared by append, revoke, and rebuild so every JSONL mutation serializes
   * against the others across processes (issue #1639: "shared with rebuilds").
   */
  private get lockPath(): string {
    return this.filePath.replace(/\.jsonl$/i, "") + ".lock";
  }

  /** Lazy load + build the in-memory index. Idempotent. */
  async load(): Promise<void> {
    if (this.loaded) return;
    if (this.loadPromise) return this.loadPromise;
    this.loadPromise = this.loadInternal();
    try {
      await this.loadPromise;
    } finally {
      this.loadPromise = null;
    }
  }

  private async loadInternal(migrateLegacy = true): Promise<void> {
    // Record the file mtime before reading so an ENOENT still records 0 and
    // a successful load does not immediately trigger a staleness reload.
    this.recordFileMtime();
    let raw: string;
    try {
      raw = await this.io.read(this.filePath);
    } catch (err) {
      const code = (err as NodeJS.ErrnoException)?.code;
      if (code !== "ENOENT") throw err;
      this.loaded = true;
      return;
    }
    const initial = this.parseEntries(raw);
    const migrated = migrateLegacy
      ? await this.migrateLegacyEntries(initial)
      : initial;
    this.resetIndex();
    for (const entry of migrated.entries) this.indexEntry(entry);
    this.corruptedLines = migrated.corruptedLines;
    this.loaded = true;
  }

  private parseEntries(raw: string): {
    entries: TombstoneEntry[];
    corruptedLines: number;
  } {
    const entries: TombstoneEntry[] = [];
    let corruptedLines = 0;
    for (const line of raw.split("\n")) {
      const entry = parseTombstoneLine(line);
      if (!entry) {
        if (line.trim().length > 0) corruptedLines += 1;
        continue;
      }
      entries.push(entry);
    }
    return { entries, corruptedLines };
  }

  /**
   * Re-index pre-Unicode records from retired source content.
   * Source reads stay bounded, but every batch finishes before the store
   * publishes its in-memory index. Missing sources remain eligible on restart.
   */
  private async migrateLegacyEntries(initial: {
    entries: TombstoneEntry[];
    corruptedLines: number;
  }): Promise<{ entries: TombstoneEntry[]; corruptedLines: number }> {
    const limit = this.options.legacyMigrationLimit ?? DEFAULT_LEGACY_MIGRATION_LIMIT;
    if (limit === 0 || !this.options.sourceContentsForMemoryIds) return initial;
    const sourceMemoryIds: string[] = [];
    const requested = new Set<string>();
    for (const entry of initial.entries) {
      if (
        entry.kind !== "tombstone" ||
        entry.normalizerVersion === TOMBSTONE_NORMALIZER_VERSION
      ) {
        continue;
      }
      if (requested.has(entry.sourceMemoryId)) continue;
      requested.add(entry.sourceMemoryId);
      sourceMemoryIds.push(entry.sourceMemoryId);
    }
    if (sourceMemoryIds.length === 0) return initial;
    const sourceContents = new Map<string, string | readonly string[]>();
    for (let offset = 0; offset < sourceMemoryIds.length; offset += limit) {
      const batch = sourceMemoryIds.slice(offset, offset + limit);
      const fetched = await this.options.sourceContentsForMemoryIds(batch);
      for (const [sourceMemoryId, content] of fetched) sourceContents.set(sourceMemoryId, content);
    }
    return await serializeMutations(`tombstone:${this.filePath}`, () =>
      this.withWriteLock(async () => {
        const latestRaw = await this.io.read(this.filePath);
        const latest = this.parseEntries(latestRaw);
        let changed = false;
        const migrateEntry = (entry: TombstoneEntry): TombstoneEntry => {
          if (
            entry.kind !== "tombstone" ||
            entry.normalizerVersion === TOMBSTONE_NORMALIZER_VERSION ||
            !requested.has(entry.sourceMemoryId)
          ) {
            return entry;
          }
          const resolved = sourceContents.get(entry.sourceMemoryId);
          if (resolved === undefined) return entry;
          const candidates = typeof resolved === "string" ? [resolved] : resolved;
          const matches = candidates.filter((source) =>
            entry.contentHash === this.options.hashContent(source) ||
            entry.contentHash === computeLegacyContentHash(source)
          );
          const explicitPrimary =
            matches.length === 0 &&
            entry.contentHash !== this.options.hashContent(entry.normalizedText);
          const source = matches[0] ?? (explicitPrimary ? candidates[0] : undefined);
          if (source === undefined) return entry;
          const currentHash = this.options.hashContent(source);
          const alias = explicitPrimary
            ? currentHash
            : matches
              .map((candidate) => this.options.hashContent(candidate))
              .find((hash) => hash !== currentHash);
          changed = true;
          return {
            ...entry,
            contentHash: explicitPrimary ? entry.contentHash : currentHash,
            ...(alias ? { currentContentHashAlias: alias } : {}),
            normalizedText: this.options.normalizeText(source),
            normalizerVersion: TOMBSTONE_NORMALIZER_VERSION,
          };
        };
        const serialized = latestRaw
          .split("\n")
          .map((line) => {
            const entry = parseTombstoneLine(line);
            if (!entry) return line;
            const migrated = migrateEntry(entry);
            return migrated === entry ? line : JSON.stringify(migrated);
          })
          .join("\n");
        if (!changed) return latest;
        await this.io.write(this.filePath, serialized);
        this.markWritten();
        return this.parseEntries(serialized);
      }),
    );
  }

  private resetIndex(): void {
    this.entries = [];
    this.byHash.clear();
    this.byNormalized.clear();
    this.byKey.clear();
    this.revokedIds.clear();
    this.byId.clear();
  }

  /**
   * Index an entry. Later entries (higher array index = newer createdAt)
   * OVERRIDE earlier ones at each tier key — the newest matching entry wins
   * (rule 25). Revocation entries mark their target as revoked.
   */
  private indexEntry(entry: TombstoneEntry): void {
    this.entries.push(entry);
    this.byId.set(entry.id, entry);
    if (entry.createdAt > (this.lastAppendAt ?? "")) {
      this.lastAppendAt = entry.createdAt;
    }
    if (entry.kind === "revocation") {
      if (entry.revokes) this.revokedIds.add(entry.revokes);
      return;
    }
    // Tombstone entries populate the lookup maps. The namespace is part of
    // every discriminator key (issue #1579 thread Ocs-O): when two
    // namespace-scoped stores share the same backing file, a later tombstone
    // for namespace B with identical content must NOT evict namespace A's map
    // entry — otherwise A's lookup finds B's id, rejects it on namespace
    // mismatch, and misses its own still-active tombstone (resurrection).
    const ns = entry.namespace;
    if (entry.normalizerVersion === TOMBSTONE_NORMALIZER_VERSION) {
      if (entry.contentHash) this.byHash.set(`${ns}\0${entry.contentHash}`, entry.id);
      if (entry.currentContentHashAlias) {
        this.byHash.set(`${ns}\0${entry.currentContentHashAlias}`, entry.id);
      }
      if (entry.normalizedText) this.byNormalized.set(`${ns}\0${entry.normalizedText}`, entry.id);
    }
    if (entry.entityRef && entry.supersessionKey) {
      this.byKey.set(keyedTierKey(ns, entry.entityRef, entry.supersessionKey), entry.id);
    }
  }

  /** Invalidate the in-memory cache (rule 25). The next access reloads. */
  invalidate(): void {
    this.loaded = false;
    this.loadPromise = null;
    this.resetIndex();
  }

  /**
   * Cross-process staleness probe (#1579). If the file's mtime advanced since
   * the last load/own-write, a peer process appended and our in-memory index
   * is stale — invalidate and reload before the next access. Mutation callers
   * pass `migrate: false` to avoid nested serializer/lock acquisition.
   */
  async ensureFreshAgainstDisk(options: { migrate?: boolean } = {}): Promise<void> {
    if (!this.io.stat) return;
    let mtimeMs: number;
    try {
      mtimeMs = Math.floor(this.io.stat(this.filePath).mtimeMs);
    } catch {
      return; // ENOENT / permission — keep the loaded index (fail-open).
    }
    if (mtimeMs === this.fileMtimeMs && this.loaded) return;
    this.fileMtimeMs = mtimeMs;
    this.invalidate();
    if (options.migrate === false) {
      await this.loadInternal(false);
    } else {
      await this.load();
    }
  }

  /**
   * Record the file mtime after THIS process writes (append / revoke / rebuild)
   * so `ensureFreshAgainstDisk` does not treat our own write as a peer append
   * and throw away the just-updated in-memory index (#1579 — avoids a needless
   * invalidate+reload in the hot write path).
   */
  private markWritten(): void {
    this.recordFileMtime();
  }

  private recordFileMtime(): void {
    if (!this.io.stat) return;
    try {
      this.fileMtimeMs = Math.floor(this.io.stat(this.filePath).mtimeMs);
    } catch {
      // ENOENT — fresh store with no file yet; mtime stays at its current value.
    }
  }

  /**
   * Append a tombstone entry. Serialized via `serializeMutations` keyed by
   * file path so concurrent appends do not interleave, with rejection recovery
   * (rule 40 — a single failed append never poisons the chain). The in-memory
   * index is updated AFTER the durable append succeeds.
   *
   * Returns the new tombstone id.
   */
  async appendTombstone(input: {
    reason: TombstoneReason;
    createdBy: TombstoneCreatedBy;
    sourceMemoryId: string;
    rawContent: string;
    entityRef?: string;
    supersessionKey?: string;
    operationKey?: string;
    createdAt?: string;
    /**
     * Pre-computed canonical contentHash from the retired memory's frontmatter.
     * When provided, used directly so the tombstone's exact tier matches the
     * hash writeMemory computes on re-extraction (issue #1579 review: cited
     * facts must not slip past the chokepoint because the emitter hashed the
     * citation-annotated body instead of the canonical source).
     */
    contentHash?: string;
  }): Promise<string> {
    await this.load();
    const createdAt = input.createdAt ?? new Date().toISOString();
    const id = newTombstoneId();
    const currentHash = this.options.hashContent(input.rawContent);
    const currentNormalizedText = this.options.normalizeText(input.rawContent);
    const entry: TombstoneEntry = {
      id,
      ...(input.contentHash && input.contentHash !== currentHash
        ? { currentContentHashAlias: currentHash }
        : {}),
      kind: "tombstone",
      reason: input.reason,
      sourceMemoryId: input.sourceMemoryId,
      contentHash: input.contentHash ?? currentHash,
      normalizedText: currentNormalizedText,
      normalizerVersion: TOMBSTONE_NORMALIZER_VERSION,
      ...(input.entityRef ? { entityRef: input.entityRef } : {}),
      ...(input.supersessionKey ? { supersessionKey: input.supersessionKey } : {}),
      ...(input.operationKey ? { operationKey: input.operationKey } : {}),
      namespace: this.namespace,
      createdAt,
      createdBy: input.createdBy,
    };
    await this.serializeAppend(entry);
    this.indexEntry(entry);
    this.markWritten();
    await this.migrateLoadedLegacyEntries();
    return id;
  }

  /**
   * Append a revocation entry referencing `tombstoneId`. The log is
   * append-only; lookup treats a revoked tombstone as re-allowed (rule 25).
   */
  async revoke(tombstoneId: string, createdBy: TombstoneCreatedBy): Promise<string> {
    await this.load();
    const createdAt = new Date().toISOString();
    const id = newTombstoneId();
    const entry: TombstoneEntry = {
      id,
      kind: "revocation",
      reason: "correction",
      sourceMemoryId: "",
      contentHash: "",
      normalizedText: "",
      namespace: this.namespace,
      createdAt,
      createdBy,
      revokes: tombstoneId,
    };
    await this.serializeAppend(entry);
    this.indexEntry(entry);
    this.markWritten();
    await this.migrateLoadedLegacyEntries();
    return id;
  }

  private serializeAppend(entry: TombstoneEntry): Promise<void> {
    const line = JSON.stringify(entry) + "\n";
    // serializeMutations (in-process, rule 40 rejection recovery) wraps the
    // cross-process lock: within one process appends are queued, and across
    // processes the advisory lockfile serializes the read-merge-write so two
    // Remnic processes appending concurrently cannot drop each other's entry
    // (issue #1639). Under the lock we re-sync the in-memory index against
    // disk first, so indexEntry builds on the peer's just-appended entries.
    return serializeMutations(`tombstone:${this.filePath}`, () =>
      this.withWriteLock(async () => {
        await this.ensureFreshAgainstDisk({ migrate: false });
        await this.io.append(this.filePath, line);
      }),
    );
  }

  private async migrateLoadedLegacyEntries(): Promise<void> {
    const initial = {
      entries: [...this.entries],
      corruptedLines: this.corruptedLines,
    };
    if (!initial.entries.some(
      (entry) => entry.kind === "tombstone" && entry.normalizerVersion !== TOMBSTONE_NORMALIZER_VERSION,
    )) {
      return;
    }
    try {
      const migrated = await this.migrateLegacyEntries(initial);
      this.resetIndex();
      for (const entry of migrated.entries) this.indexEntry(entry);
      this.corruptedLines = migrated.corruptedLines;
      this.loaded = true;
    } catch {
      // The durable mutation already succeeded; defer migration to next load.
    }
  }

  /**
   * Acquire the cross-process tombstone write lock and run `task` under it
   * (issue #1639). Strict-fail on acquisition timeout: the secure-store append
   * is a read-merge-write, so a best-effort unlocked run would clobber a
   * concurrent writer — reintroducing the lost-write race this lock closes.
   * The thrown error surfaces to the caller (rule 34: never silently drop);
   * rebuild recovers the tombstone on the next maintenance cycle.
   *
   * In-process callers are already serialized by serializeMutations (one key
   * for append/revoke/rebuild), so this lock only contends across processes —
   * the single-process daemon (default deployment) acquires it immediately.
   */
  private withWriteLock<T>(task: () => Promise<T>): Promise<T> {
    return withHeldFileLock(
      this.lockPath,
      {
        staleMs: this.lockStaleMs,
        maxWaitMs: this.lockMaxWaitMs,
        heartbeatMs: this.lockHeartbeatMs,
      },
      async (acquired) => {
        if (!acquired) {
          throw new Error(
            "could not acquire tombstone write lock (contention timeout or filesystem error)",
          );
        }
        return task();
      },
    );
  }

  /**
   * Look up whether `query` is blocked by an active (non-revoked) tombstone.
   * Tiers are checked in order: exact (contentHash) → normalized → keyed →
   * semantic (off by default). Returns the first active match, or `null`.
   *
   * Namespace isolation (rule 42): only entries with `namespace === query.namespace`
   * match. The store is per-namespace, so this is belt-and-suspenders.
   */
  lookup(query: TombstoneLookupQuery): TombstoneMatch | null {
    // We intentionally do NOT await load() here — lookup is called from the
    // hot write path. Callers MUST ensure the store is loaded before lookup
    // (StorageManager does this in ensureTombstoneStoreLoaded). If not loaded,
    // lookup returns null (fail-open: a missing tombstone check is preferable
    // to crashing every write — see rule 34 / the "degrade gracefully" note).
    if (!this.options.enabled) return null;
    if (!this.loaded) return null;

    // Tier 1: exact contentHash. Namespace is part of the map key (thread
    // Ocs-O), so the lookup finds only this namespace's tombstone even when
    // the backing file is shared. The namespace equality check below is kept
    // as defense-in-depth.
    const ns = query.namespace;
    if (query.contentHash) {
      const id = this.byHash.get(`${ns}\0${query.contentHash}`);
      if (id && !this.revokedIds.has(id)) {
        const entry = this.byId.get(id);
        if (entry && entry.namespace === ns) {
          return { tombstoneId: id, matchedTier: "exact", reason: entry.reason };
        }
      }
    }
    // Tier 2: normalized text.
    if (query.normalizedText) {
      const id = this.byNormalized.get(`${ns}\0${query.normalizedText}`);
      if (id && !this.revokedIds.has(id)) {
        const entry = this.byId.get(id);
        if (entry && entry.namespace === ns) {
          return { tombstoneId: id, matchedTier: "normalized", reason: entry.reason };
        }
      }
    }
    // Tier 3: keyed (entityRef + supersessionKey). Issue #1579 thread
    // Ociag/Oci-W: check EVERY supplied key, not just the first — emitters
    // append one tombstone per matched supersession key, so the active block
    // can live on any later key. The union of `supersessionKey` (singular,
    // direct callers) and `supersessionKeys` (array, write chokepoint) is
    // checked; the first active match wins (tiers are equality-based, so
    // ordering across keys does not affect correctness).
    if (query.entityRef) {
      const keysToCheck: string[] = [];
      if (query.supersessionKey) keysToCheck.push(query.supersessionKey);
      if (query.supersessionKeys) {
        for (const k of query.supersessionKeys) {
          if (!keysToCheck.includes(k)) keysToCheck.push(k);
        }
      }
      for (const key of keysToCheck) {
        const id = this.byKey.get(keyedTierKey(ns, query.entityRef, key));
        if (id && !this.revokedIds.has(id)) {
          const entry = this.byId.get(id);
          if (entry && entry.namespace === ns) {
            return { tombstoneId: id, matchedTier: "keyed", reason: entry.reason };
          }
        }
      }
    }
    // Tier 4: semantic (off by default, rule 48).
    if (this.options.semanticMatch && this.options.semanticSimilarity && query.normalizedText) {
      const threshold = this.options.semanticThreshold;
      let best: { id: string; reason: TombstoneReason; score: number } | null = null;
      for (const entry of this.entries) {
        if (entry.kind !== "tombstone") continue;
        if (entry.normalizerVersion !== TOMBSTONE_NORMALIZER_VERSION) continue;
        if (entry.namespace !== query.namespace) continue;
        if (this.revokedIds.has(entry.id)) continue;
        if (!entry.normalizedText) continue;
        const score = this.options.semanticSimilarity(query.normalizedText, entry.normalizedText);
        if (score >= threshold && (!best || score > best.score)) {
          best = { id: entry.id, reason: entry.reason, score };
        }
      }
      if (best) {
        return { tombstoneId: best.id, matchedTier: "semantic", reason: best.reason };
      }
    }
    return null;
  }
  async hasExactEntry(input: {
    sourceMemoryId: string;
    contentHash?: string;
    entityRef?: string;
    supersessionKey?: string;
    createdAt?: string;
    operationKey?: string;
  }): Promise<boolean> {
    if (!this.options.enabled) return false;
    await this.ensureFreshAgainstDisk();
    await this.load();
    return this.entries.some(
      (entry) =>
        entry.kind === "tombstone" &&
        !this.revokedIds.has(entry.id) &&
        entry.namespace === this.namespace &&
        entry.sourceMemoryId === input.sourceMemoryId &&
        (input.contentHash === undefined || entry.contentHash === input.contentHash) &&
        (input.entityRef === undefined || entry.entityRef === input.entityRef) &&
        (input.supersessionKey === undefined || entry.supersessionKey === input.supersessionKey) &&
        (input.createdAt === undefined || entry.createdAt === input.createdAt) &&
        (input.operationKey === undefined || entry.operationKey === input.operationKey),
    );
  }


  /** Aggregate stats for the doctor / x-ray surfaces. */
  stats(): TombstoneStats {
    let active = 0;
    for (const entry of this.entries) {
      if (entry.kind === "tombstone" && !this.revokedIds.has(entry.id)) active += 1;
    }
    return {
      count: active,
      revoked: this.revokedIds.size,
      lastAppendAt: this.lastAppendAt,
      corruptedLines: this.corruptedLines,
      loaded: this.loaded,
    };
  }

  /** Read-only snapshot of all entries (for rebuild + tests). */
  snapshot(): readonly TombstoneEntry[] {
    return this.entries;
  }

  /**
   * Rebuild the in-memory index + JSONL from the supplied retired-memory
   * records + existing entries (preserving revocations). Byte-stable: entries
   * are sorted by (createdAt, id) before write (rule 38).
   *
   * Returns the count of tombstone entries written.
   */
  async rebuild(retiredMemories: ReadonlyArray<RetiredMemoryRecord>): Promise<number> {
    // The full read-merge-write runs UNDER the cross-process lock (issue #1639,
    // cursor/codex review): we ensureFreshAgainstDisk() first so the in-memory
    // index reflects any peer append/revoke that landed while we waited for the
    // lock, THEN compute the payload. Rebuild rewrites the entire JSONL, so a
    // payload built from a stale this.entries would overwrite a peer's just-
    // written entry and resurrect a retired fact — the exact invariant this
    // store exists to enforce. serializeMutations (in-process) wraps the
    // cross-process lock; the key is unified with append/revoke so they cannot
    // interleave in-process either.
    const rebuiltCount = await serializeMutations(`tombstone:${this.filePath}`, () =>
      this.withWriteLock(async () => {
        await this.ensureFreshAgainstDisk({ migrate: false });
        // Preserve existing revocations (all namespaces — ids are globally
        // unique) so a rebuild does not silently un-revoke.
        const existingRevocations = this.entries.filter((e) => e.kind === "revocation");
        // Preserve tombstone entries from OTHER namespaces when the backing
        // file is shared (issue #1579 thread Oc2MJ). rebuild rewrites the
        // entire file; without preserving foreign entries, rebuilding
        // namespace A would silently delete namespace B's tombstones, allowing
        // resurrection in B.
        const foreignTombstones = this.entries.filter(
          (e) => e.kind === "tombstone" && e.namespace !== this.namespace,
        );
        // Reuse existing tombstone ids for source-equivalent entries so a prior
        // revocation (which references the tombstone id) survives rebuild —
        // minting fresh ids would orphan the revocation and silently un-revoke.
        // Issue #1579 thread Oci-T: key the reuse map by (sourceMemoryId,
        // supersessionKey). See the append path above for the full rationale.
        const existingBySource = new Map<string, string>();
        for (const e of this.entries) {
          if (e.kind === "tombstone") {
            existingBySource.set(`${e.sourceMemoryId}\u{0000}${e.supersessionKey ?? ""}`, e.id);
          }
        }
        const rebuilt: TombstoneEntry[] = retiredMemories.map((m) => {
          const currentHash = this.options.hashContent(m.rawContent);
          const currentNormalizedText = this.options.normalizeText(m.rawContent);
          const persistedHash = m.contentHash;
          // A persisted hash equal to the body's LEGACY hash only proves the
          // record predates the Unicode normalizer when that legacy hash is
          // unambiguous. When the legacy normalizer is lossy for this body
          // (any body whose ASCII skeleton collides with a distinct
          // contentHashSource), the equality cannot distinguish "old body
          // hash" from "explicit source identity" — replacing the persisted
          // hash would displace a live identity (issue #2367). Preserving
          // keeps BOTH keys: contentHash stays the persisted identity and
          // currentContentHashAlias still blocks the body.

          // Repair only when the persisted hash provably identifies THIS
          // body's stale legacy hash: either the unambiguous case (legacy and
          // current normalizations agree), or the empty-skeleton case — every
          // non-ASCII-only body normalizes to the empty legacy skeleton, so a
          // persisted hash equal to hash("") is the shared non-identifying
          // legacy body hash and publishing it on the exact tier would
          // collide unrelated tombstones. Any OTHER persisted hash on an
          // empty-skeleton body is a distinct explicit identity (e.g.
          // contentHashSource) and must be preserved.
          const legacyBodyHash = computeLegacyContentHash(m.rawContent);
          const repairEmptySkeleton =
            normalizeLegacyContent(m.rawContent).length === 0 && persistedHash === legacyBodyHash;
          const preserveOverride =
            persistedHash !== undefined &&
            persistedHash !== currentHash &&
            !repairEmptySkeleton &&
            !isUnambiguousLegacyContentHash(m.rawContent, persistedHash, currentNormalizedText);
          return {
            id:
              existingBySource.get(`${m.memoryId}\u{0000}${m.supersessionKey ?? ""}`) ??
              newTombstoneId(),
            ...(preserveOverride ? { currentContentHashAlias: currentHash } : {}),
            kind: "tombstone" as const,
            reason: m.reason,
            sourceMemoryId: m.memoryId,
            contentHash: preserveOverride ? persistedHash : currentHash,
            normalizedText: currentNormalizedText,
            normalizerVersion: TOMBSTONE_NORMALIZER_VERSION,
            ...(m.entityRef ? { entityRef: m.entityRef } : {}),
            ...(m.supersessionKey ? { supersessionKey: m.supersessionKey } : {}),
            namespace: this.namespace,
            createdAt: m.createdAt,
            createdBy: m.createdBy,
          };
        });
        // Sort deterministically (rule 38): createdAt, then id for stability.
        rebuilt.sort((a, b) =>
          a.createdAt === b.createdAt
            ? a.id < b.id ? -1 : a.id > b.id ? 1 : 0
            : a.createdAt < b.createdAt ? -1 : 1,
        );
        const all = [...rebuilt, ...existingRevocations, ...foreignTombstones].sort((a, b) =>
          a.createdAt === b.createdAt
            ? a.id < b.id ? -1 : a.id > b.id ? 1 : 0
            : a.createdAt < b.createdAt ? -1 : 1,
        );
        const serialized =
          all.map((e) => JSON.stringify(e)).join("\n") + (all.length > 0 ? "\n" : "");
        await this.io.write(this.filePath, serialized);
        // Update the in-memory index under the same lock so it stays consistent
        // with the file we just wrote (no window for a lookup to see a stale
        // index that misses a just-rebuilt entry).
        this.resetIndex();
        for (const entry of all) this.indexEntry(entry);
        this.corruptedLines = 0;
        this.loaded = true;
        this.markWritten();
        return rebuilt.length;
      }),
    );
    await this.migrateLoadedLegacyEntries();
    return rebuiltCount;
  }
}

/** A retired memory projected into the shape `TombstoneStore.rebuild` consumes. */
export interface RetiredMemoryRecord {
  memoryId: string;
  rawContent: string;
  entityRef?: string;
  supersessionKey?: string;
  reason: TombstoneReason;
  createdBy: TombstoneCreatedBy;
  createdAt: string;
  /** Canonical contentHash from the retired memory's frontmatter (#1579). */
  contentHash?: string;
}

/**
 * Project a corpus of memories into the retired-memory records `rebuild`
 * consumes. Pure (no I/O) so the StorageManager wiring stays thin (#1579,
 * #1520 god-file ratchet). Only superseded / forgotten / rejected FACTS
 * participate — entities, questions, and artifacts have their own lifecycle
 * (issue pitfall). The supersession key is derived from structured attributes
 * via the injected helper so there is one keyed-tier definition (rule 23).
 */
export function collectRetiredMemoriesForRebuild(
  memories: ReadonlyArray<{
    frontmatter: {
      id: string;
      status?: string;
      category?: string;
      contentHash?: string;
      entityRef?: string;
      structuredAttributes?: Record<string, string>;
      updated?: string;
      created?: string;
    };
    content: string;
  }>,
  deps: {
    /** Strip citation annotations from the body before hashing/normalizing. */
    stripCitation: (text: string) => string;
    /** Derive the keyed-tier supersession key (one helper, rule 23). */
    supersessionKeysForFact: (spec: {
      entityRef?: string;
      structuredAttributes?: Record<string, string>;
    }) => string[];
  },
): RetiredMemoryRecord[] {
  const retired: RetiredMemoryRecord[] = [];
  for (const m of memories) {
    const status = m.frontmatter.status;
    if (status !== "superseded" && status !== "rejected" && status !== "forgotten") continue;
    if (m.frontmatter.category !== "fact") continue;
    const reason: TombstoneReason =
      status === "superseded" ? "supersession" : status === "forgotten" ? "retraction" : "correction";
    const createdBy: TombstoneCreatedBy =
      reason === "supersession" ? "supersession" : "user_correction";
    const entityRef = m.frontmatter.entityRef;
    const keys =
      entityRef && m.frontmatter.structuredAttributes
        ? deps.supersessionKeysForFact({
            entityRef,
            structuredAttributes: m.frontmatter.structuredAttributes,
          })
        : [];
    // Issue #1579 thread Ocgjz: emit one record per matched supersession key
    // (not just keys[0]) so rebuild reproduces the same keyed tombstones as
    // live temporal-supersession (which now appends one per key — thread ObteS).
    // Without this, a rebuild would under-rebuild the JSONL and keyed-tier
    // blocks would disappear until rediscovered.
    const keysToEmit = keys.length > 0 ? keys : [undefined];
    for (const key of keysToEmit) {
      retired.push({
        memoryId: m.frontmatter.id,
        rawContent: deps.stripCitation(m.content),
        contentHash: m.frontmatter.contentHash,
        ...(entityRef ? { entityRef } : {}),
        ...(key ? { supersessionKey: key } : {}),
        reason,
        createdBy,
        createdAt: m.frontmatter.updated || m.frontmatter.created || new Date().toISOString(),
      });
    }
  }
  return retired;
}

/**
 * One-shot write-time resurrection gate (issue #1579 / #2213). Looks up the
 * fact's identity in the tombstone store and, on a match, downgrades the
 * frontmatter to `pending_review` + `blockedBy` IN PLACE. ADD-ONLY: an
 * already-blocked or terminal-status record is left untouched. Pure over its
 * inputs (no I/O beyond the injected store) so both `writeMemory`'s gate and
 * the chunk-repair re-gate share one lookup + apply.
 */
export function applyTombstoneResurrectionGate(
  store: Pick<TombstoneStore, "lookup">,
  fm: {
    id: string;
    status?: string;
    blockedBy?: string;
    tombstoneBlockTier?: TombstoneMatchTier;
    entityRef?: string;
    contentHash?: string;
  },
  query: {
    normalizedText: string;
    supersessionKeys: string[];
    namespace: string;
  },
): TombstoneMatch | null {
  if (fm.status === "pending_review" && fm.blockedBy) return null;
  if (!(fm.status === undefined || fm.status === "active" || fm.status === "pending_review")) return null;
  const match = store.lookup({
    contentHash: fm.contentHash,
    normalizedText: query.normalizedText,
    ...(fm.entityRef ? { entityRef: fm.entityRef } : {}),
    ...(query.supersessionKeys.length > 0 ? { supersessionKeys: query.supersessionKeys } : {}),
    namespace: query.namespace,
  });
  if (!match) return null;
  fm.status = "pending_review";
  fm.blockedBy = match.tombstoneId;
  fm.tombstoneBlockTier = match.matchedTier;
  return match;
}

/**
 * Build the live-emission tombstone inputs for a single retired FACT — one
 * input per derived supersession key (or a single keyless record when no
 * structured attributes are present). Pure (no I/O) so the emitters in
 * `StorageManager.supersedeMemory` (contradiction) and `forgetMemory`
 * (retraction) stay thin (#1579, #1520 god-file ratchet). Mirrors the
 * temporal-supersession emitter and `collectRetiredMemoriesForRebuild` so
 * every retire path emits the same keyed-tombstone shape (issue #1579
 * threads Oci-Y / OchiF: without per-key tombstones, a paraphrased
 * re-observation missed the keyed tier and the fact resurrected active).
 */
export function buildRetiredFactTombstoneInputs(
  memory: {
    id: string;
    content: string;
    contentHash?: string;
    entityRef?: string;
    structuredAttributes?: Record<string, string>;
  },
  opts: {
    reason: TombstoneReason;
    createdBy: TombstoneCreatedBy;
    createdAt: string;
    supersessionKeysForFact: (spec: {
      entityRef?: string;
      structuredAttributes?: Record<string, string>;
    }) => string[];
  },
): Array<{
  reason: TombstoneReason;
  createdBy: TombstoneCreatedBy;
  sourceMemoryId: string;
  rawContent: string;
  contentHash?: string;
  entityRef?: string;
  supersessionKey?: string;
  createdAt: string;
}> {
  const keys =
    memory.entityRef && memory.structuredAttributes
      ? opts.supersessionKeysForFact({
          entityRef: memory.entityRef,
          structuredAttributes: memory.structuredAttributes,
        })
      : [];
  const keysToEmit = keys.length > 0 ? keys : [undefined];
  return keysToEmit.map((key) => ({
    reason: opts.reason,
    createdBy: opts.createdBy,
    sourceMemoryId: memory.id,
    rawContent: memory.content,
    ...(memory.contentHash ? { contentHash: memory.contentHash } : {}),
    ...(memory.entityRef ? { entityRef: memory.entityRef } : {}),
    ...(key ? { supersessionKey: key } : {}),
    createdAt: opts.createdAt,
  }));
}

/**
 * Temporal Supersession (issue #375)
 *
 * When a new fact lands with `structuredAttributes` keyed on a known
 * `entityRef`, any prior fact whose supersession key collides with the new
 * fact's key is marked `status: "superseded"` and linked via
 * `supersededBy` / `supersededAt`.  Recall filters those superseded memories
 * by default so agents see only the "current" value per entity attribute.
 *
 * The algorithm is intentionally O(N) over the memory corpus per write, but
 * skips cheaply when the new fact has no structuredAttributes.  It reuses the
 * cached `readAllMemories()` path so cost is amortized with the rest of the
 * write pipeline.
 */
import type { MemoryFile, MemoryFrontmatter, MemoryLifecycleEvent } from "./types.js";

import { createHash } from "node:crypto";
import { log } from "./logger.js";
import { effectiveValidAt } from "./temporal-validity.js";
import type {
  DependencyPropagationDeliveryPort,
  DependencyPropagationPreparationToken,
} from "./orchestration/dependency-propagation-delivery.js";
import type { PropagationEvent } from "./orchestration/dependency-propagation.js";
export interface TemporalSupersessionStorage {
  readAllMemories(): Promise<MemoryFile[]>;
  readAllColdMemories(): Promise<MemoryFile[]>;
  readMemoryByPath(memoryPath: string): Promise<MemoryFile | null>;
  writeMemoryFrontmatterIfUnchanged?: (
    memory: MemoryFile,
    patch: Partial<MemoryFrontmatter>,
    lifecycle?: {
      actor?: string;
      reasonCode?: string;
      relatedMemoryIds?: string[];
      correlationId?: string;
    },
  ) => Promise<boolean>;
  appendTombstone(input: {
    reason: "supersession";
    createdBy: "supersession";
    sourceMemoryId: string;
    rawContent: string;
    entityRef?: string;
    supersessionKey?: string;
    createdAt?: string;
    contentHash?: string;
    operationKey?: string;
  }): Promise<string | null>;
  hasExactTombstone?: (input: {
    sourceMemoryId: string;
    contentHash?: string;
    entityRef?: string;
    supersessionKey?: string;
    createdAt?: string;
    operationKey?: string;
  }) => Promise<boolean>;
  getMemoryTimeline: (memoryId: string, limit?: number) => Promise<MemoryLifecycleEvent[]>;
  isTombstonesEnabled?: () => boolean;
}

/**
 * Shared normalization for supersession key components.
 *
 * Trims surrounding whitespace, lowercases, then collapses any run of
 * whitespace OR hyphens to a single hyphen, and strips any leading/trailing
 * hyphens that result.  Both `computeSupersessionKey` and
 * `lookupAttributeByNormalizedKey` must use this so that keys produced at
 * write time and keys used at lookup time are identical regardless of how
 * the LLM encoded whitespace, hyphens, or casing (Finding B fix).
 *
 * Symmetry guarantee: `"foo bar"`, `"foo-bar"`, `"foo - bar"`, and
 * `"foo  bar"` all canonicalize to `"foo-bar"`.
 *
 * Exported so external tests can verify the canonical form.
 */
export function normalizeSupersessionKey(raw: string): string {
  return raw
    .trim()
    .toLowerCase()
    .replace(/[\s\-]+/g, "-")
    // The previous line already collapsed runs to single hyphens, so ^-|-$ is
    // equivalent to ^-+|-+$ here and drops the anchored quantifier flagged by
    // CodeQL js/polynomial-redos.
    .replace(/^-|-$/g, "");
}

/**
 * Stable supersession key for an (entityRef, attributeName) pair.
 *
 * The algorithm is:
 *  - normalize the entityRef (trim, lower-case, collapse whitespace)
 *  - normalize the attributeName the same way
 *  - join with `::`
 *
 * Exported so tests and tools can recompute it without depending on storage.
 */
export function computeSupersessionKey(
  entityRef: string | undefined,
  attributeName: string,
): string | null {
  if (!entityRef || typeof entityRef !== "string") return null;
  if (!attributeName || typeof attributeName !== "string") return null;
  const entity = normalizeSupersessionKey(entityRef);
  const attr = normalizeSupersessionKey(attributeName);
  if (entity.length === 0 || attr.length === 0) return null;
  return `${entity}::${attr}`;
}

/**
 * Compute the full set of supersession keys for a fact with structured
 * attributes.  Returns an empty array if no keys can be derived.
 */
export function supersessionKeysForFact(spec: {
  entityRef?: string;
  structuredAttributes?: Record<string, string>;
}): string[] {
  if (!spec.entityRef) return [];
  if (!spec.structuredAttributes) return [];
  const keys: string[] = [];
  for (const attrName of Object.keys(spec.structuredAttributes)) {
    const key = computeSupersessionKey(spec.entityRef, attrName);
    if (key) keys.push(key);
  }
  return keys;
}

/**
 * Look up a structured-attribute value by a raw key, normalizing both sides
 * with `normalizeSupersessionKey` before comparing.  This ensures that keys
 * written by the LLM with mixed case, surrounding whitespace, or internal
 * whitespace (e.g. `"City"`, `" city "`, `"job   title"`, `"job-title"`)
 * are all matched against normalized keys produced by `computeSupersessionKey`
 * (Finding B fix — uses the same helper so both sides are identical).
 *
 * The storage format is NOT changed — we only normalize at lookup time.
 */
export function lookupAttributeByNormalizedKey(
  attributes: Record<string, unknown>,
  rawKey: string,
): unknown {
  const normalizedTarget = normalizeSupersessionKey(rawKey);
  for (const [k, v] of Object.entries(attributes)) {
    if (normalizeSupersessionKey(k) === normalizedTarget) return v;
  }
  return undefined;
}

/**
 * Decide whether an existing memory should be superseded by a newly-written
 * memory that carries the supplied supersession key set.
 *
 * Only memories that:
 *  - are currently `active`
 *  - share an `entityRef` with the new fact
 *  - share at least one supersession key with the new fact
 *  - are older than the new fact
 *  - have a conflicting value (different string) for the overlapping key
 * are eligible.  This keeps supersession local to the attribute that actually
 * changed — if fact A sets `{city: Austin, tool: vim}` and fact B sets
 * `{city: NYC}`, only the city attribute is superseded, not the tool.
 */
export function shouldSupersedeExisting(args: {
  candidate: MemoryFrontmatter;
  newEntityRef: string;
  newAttributes: Record<string, string>;
  newCreatedAt: string;
  newMemoryId: string;
}): { matchedKeys: string[] } | null {
  const { candidate, newEntityRef, newAttributes, newCreatedAt, newMemoryId } = args;

  if (candidate.id === newMemoryId) return null;
  if (candidate.status && candidate.status !== "active") return null;
  if (!candidate.entityRef) return null;
  if (!candidate.structuredAttributes) return null;

  // Reuse the shared `normalizeSupersessionKey` helper so this comparison
  // cannot drift from the canonical form used to build supersession keys
  // elsewhere in this file.
  const candidateEntityNorm = normalizeSupersessionKey(candidate.entityRef);
  const newEntityNorm = normalizeSupersessionKey(newEntityRef);
  if (candidateEntityNorm !== newEntityNorm) return null;

  // Must be older than the new fact's effective validity start — equal
  // timestamps are ignored to avoid races within the same millisecond. When
  // replay/import supplies source time, valid_at must drive ordering instead
  // of wall-clock persistence time.
  const candidateCreated = Date.parse(effectiveValidAt(candidate));
  const newCreated = Date.parse(newCreatedAt);
  if (!Number.isFinite(candidateCreated) || !Number.isFinite(newCreated)) return null;
  if (candidateCreated >= newCreated) return null;

  const matchedKeys: string[] = [];
  for (const [attrName, newValue] of Object.entries(newAttributes)) {
    // Use normalized key lookup so mixed-case or whitespace-padded keys
    // stored by the LLM are matched correctly (Finding 2 fix).
    const candidateValue = lookupAttributeByNormalizedKey(
      candidate.structuredAttributes,
      attrName,
    );
    if (candidateValue === undefined) continue;
    // Only supersede on conflicting values — identical values are a no-op.
    if (normalizeValue(String(candidateValue)) === normalizeValue(newValue)) continue;
    const key = computeSupersessionKey(newEntityRef, attrName);
    if (key) matchedKeys.push(key);
  }

  return matchedKeys.length > 0 ? { matchedKeys } : null;
}

function normalizeValue(v: string): string {
  return v.trim().toLowerCase();
}
function temporalSupersessionOperationKey(
  sourceMemoryId: string,
  replacementId: string,
  mutation: TemporalSupersessionMutation,
): string {
  return createHash("sha256")
    .update(
      JSON.stringify({
        sourceMemoryId,
        replacementId,
        cause: "temporal_supersession",
        supersededAt: mutation.supersededAt,
        invalidAt: mutation.invalidAt ?? null,
        matchedKeys: [...mutation.matchedKeys].sort(compareByteStable),
      }),
    )
    .digest("hex");
}
type TemporalMemorySnapshot = Pick<MemoryFile, "content" | "frontmatter">;
function compareByteStable(left: string, right: string): number {
  return Buffer.from(left, "utf8").compare(Buffer.from(right, "utf8"));
}

function canonicalTemporalValue(value: unknown): unknown {
  if (Array.isArray(value)) return value.map((entry) => canonicalTemporalValue(entry));
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>)
        .sort(([left], [right]) => compareByteStable(left, right))
        .map(([key, entry]) => [key, canonicalTemporalValue(entry)]),
    );
  }
  return value;
}

function temporalSnapshotKey(memory: TemporalMemorySnapshot): string {
  return JSON.stringify(
    canonicalTemporalValue({
      content: memory.content,
      frontmatter: memory.frontmatter,
    }),
  );
}

function temporalMutationPatch(
  replacementId: string,
  mutation: TemporalSupersessionMutation,
): Partial<MemoryFrontmatter> {
  return {
    status: "superseded",
    supersededBy: replacementId,
    supersededAt: mutation.supersededAt,
    updated: mutation.supersededAt,
    ...(mutation.invalidAt ? { invalid_at: mutation.invalidAt } : {}),
  };
}

type TemporalPrimaryCommitState = "committed" | "not-committed" | "unknown";

async function classifyTemporalPrimaryMutation(args: {
  storage: TemporalSupersessionStorage;
  path: string;
  before: TemporalMemorySnapshot;
  patch: Partial<MemoryFrontmatter>;
}): Promise<TemporalPrimaryCommitState> {
  let current: MemoryFile | null;
  try {
    current = await args.storage.readMemoryByPath(args.path);
  } catch {
    return "unknown";
  }
  if (!current) return "unknown";
  const beforeKey = temporalSnapshotKey(args.before);
  const committedKey = temporalSnapshotKey({
    content: args.before.content,
    frontmatter: { ...args.before.frontmatter, ...args.patch },
  });
  const currentKey = temporalSnapshotKey(current);
  if (currentKey === committedKey) return "committed";
  if (currentKey === beforeKey) return "not-committed";
  return "unknown";
}
type PreparedTemporalPropagation = {
  delivery: DependencyPropagationDeliveryPort;
  event: PropagationEvent;
  token: DependencyPropagationPreparationToken | null;
};

async function settleTemporalPropagationAfterPrimaryFailure(
  pending: PreparedTemporalPropagation,
  commitState: TemporalPrimaryCommitState,
  memoryId: string,
): Promise<void> {
  let token = pending.token;
  if (commitState === "not-committed") {
    if (token !== null) {
      try {
        await pending.delivery.cancel(token);
      } catch (error) {
        log.warn(
          `temporal-supersession: dependency propagation cancellation failed for ${memoryId}: ${error}`,
        );
      }
    }
    return;
  }
  if (token === null && (commitState === "committed" || commitState === "unknown")) {
    try {
      token = await pending.delivery.prepare(pending.event);
    } catch (error) {
      log.warn(
        `temporal-supersession: dependency propagation recovery preparation failed for ${memoryId}: ${error}`,
      );
    }
  }
  if (token !== null) {
    try {
      await pending.delivery.deferPrepared(token);
    } catch (error) {
      log.warn(`temporal-supersession: dependency propagation defer failed for ${memoryId}: ${error}`);
    }
    return;
  }
  if (commitState === "committed") {
    try {
      await pending.delivery.afterMutation(null, pending.event);
    } catch (error) {
      log.warn(`temporal-supersession: dependency propagation fallback failed for ${memoryId}: ${error}`);
    }
  }
}


async function hasTemporalLifecycleEffect(args: {
  storage: TemporalSupersessionStorage;
  memoryId: string;
  timestamp: string;
  operationKey: string;
  reasonCode: string;
  relatedMemoryIds: string[];
}): Promise<boolean> {
  const events = await args.storage.getMemoryTimeline(args.memoryId, 200);
  return events.some((event) => {
    if (
      event.memoryId !== args.memoryId ||
      (event.eventType !== "superseded" && event.eventType !== "updated") ||
      event.timestamp !== args.timestamp ||
      event.after?.status !== "superseded"
    ) {
      return false;
    }
    if (event.correlationId !== undefined) return event.correlationId === args.operationKey;
    // Rows written before correlation IDs existed can be replayed only with
    // their complete legacy identity. New rows always take the exact branch.
    return (
      event.reasonCode === args.reasonCode &&
      Array.isArray(event.relatedMemoryIds) &&
      event.relatedMemoryIds.length === args.relatedMemoryIds.length &&
      event.relatedMemoryIds.every((memoryId, index) => memoryId === args.relatedMemoryIds[index])
    );
  });
}

async function hasTemporalTombstoneEffect(args: {
  storage: TemporalSupersessionStorage;
  oldMemory: MemoryFile;
  supersessionKey?: string;
  operationKey: string;
  createdAt: string;
}): Promise<boolean> {
  if (!args.storage.hasExactTombstone) return false;
  return args.storage.hasExactTombstone({
    sourceMemoryId: args.oldMemory.frontmatter.id,
    ...(args.oldMemory.frontmatter.contentHash
      ? { contentHash: args.oldMemory.frontmatter.contentHash }
      : {}),
    ...(args.oldMemory.frontmatter.entityRef
      ? { entityRef: args.oldMemory.frontmatter.entityRef }
      : {}),
    ...(args.supersessionKey ? { supersessionKey: args.supersessionKey } : {}),
    createdAt: args.createdAt,
    operationKey: args.operationKey,
  });
}


async function ensureTemporalLifecycleEffect(args: {
  storage: TemporalSupersessionStorage;
  memory: MemoryFile;
  replacementId: string;
  mutation: TemporalSupersessionMutation;
  operationKey: string;
  child?: boolean;
}): Promise<boolean> {
  const reasonCode = args.child
    ? "structured-attribute-update-child-chunk"
    : "structured-attribute-update";
  const relatedMemoryIds = args.child
    ? [args.replacementId, args.memory.frontmatter.parentId ?? ""].filter(Boolean)
    : [args.replacementId];
  const lifecycleEffect = await hasTemporalLifecycleEffect({
    storage: args.storage,
    memoryId: args.memory.frontmatter.id,
    timestamp: args.mutation.supersededAt,
    operationKey: args.operationKey,
    reasonCode,
    relatedMemoryIds,
  });
  if (lifecycleEffect === undefined) return false;
  if (lifecycleEffect === true) return true;
  if (lifecycleEffect === false || args.memory.frontmatter.status !== "superseded") {
    if (!args.storage.writeMemoryFrontmatterIfUnchanged) return false;
    const wrote = await args.storage.writeMemoryFrontmatterIfUnchanged(
      args.memory,
      {
        status: "superseded",
        supersededBy: args.replacementId,
        supersededAt: args.mutation.supersededAt,
        updated: args.mutation.supersededAt,
        ...(args.mutation.invalidAt && !args.memory.frontmatter.invalid_at
          ? { invalid_at: args.mutation.invalidAt }
          : {}),
      },
      {
        actor: "temporal-supersession",
        reasonCode: args.child
          ? "structured-attribute-update-child-chunk"
          : "structured-attribute-update",
        relatedMemoryIds: args.child
          ? [args.replacementId, args.memory.frontmatter.parentId ?? ""].filter(Boolean)
          : [args.replacementId],
        correlationId: args.operationKey,
      },
    );
    return wrote;
  }
  return true;
}

async function expireChildChunksForSupersededParent(args: {
  storage: TemporalSupersessionStorage;
  allCandidates: MemoryFile[];
  parentId: string;
  newMemoryId: string;
  supersededAt: string;
  invalidAt?: string;
  operationKey: string;
}): Promise<boolean> {
  const processedChunkIds = new Set<string>();
  const chunks = args.allCandidates.filter(
    (candidate) => candidate.frontmatter.parentId === args.parentId,
  );

  for (const chunk of chunks) {
    const chunkKey = chunk.frontmatter.id ?? chunk.path;
    if (processedChunkIds.has(chunkKey)) continue;

    try {
      const freshChunk = await args.storage.readMemoryByPath(chunk.path);
      if (!freshChunk) continue;
      processedChunkIds.add(chunkKey);
      const freshStatus = freshChunk.frontmatter.status ?? "active";
      if (
        freshStatus !== "active" &&
        !(
          freshStatus === "superseded" &&
          freshChunk.frontmatter.supersededBy === args.newMemoryId
        )
      ) {
        continue;
      }
      const completed = await ensureTemporalLifecycleEffect({
        storage: args.storage,
        memory: freshChunk,
        replacementId: args.newMemoryId,
        mutation: {
          supersededAt: args.supersededAt,
          ...(args.invalidAt ? { invalidAt: args.invalidAt } : {}),
          matchedKeys: [],
        },
        operationKey: `${args.operationKey}:child:${freshChunk.frontmatter.id}`,
        child: true,
      });
      if (!completed) return false;
    } catch (err) {
      log.warn(
        `temporal-supersession: failed to expire child chunk ${chunk.frontmatter.id} for parent ${args.parentId}: ${err}`,
      );
      return false;
    }
  }
  return true;
}

export interface TemporalSupersessionMutation {
  supersededAt: string;
  invalidAt?: string;
  matchedKeys: string[];
}

export async function applyTemporalSupersessionPrimaryMutation(args: {
  storage: TemporalSupersessionStorage;
  oldMemory: MemoryFile;
  replacementId: string;
  mutation: TemporalSupersessionMutation;
  allCandidates?: MemoryFile[];
}): Promise<boolean> {
  const { storage, oldMemory, replacementId, mutation } = args;
  if (typeof storage.getMemoryTimeline !== "function") {
    log.warn("temporal-supersession: required memory timeline adapter is missing");
    return false;
  }
  const operationKey = temporalSupersessionOperationKey(
    oldMemory.frontmatter.id,
    replacementId,
    mutation,
  );
  const alreadyApplied =
    oldMemory.frontmatter.status === "superseded" &&
    oldMemory.frontmatter.supersededBy === replacementId &&
    oldMemory.frontmatter.supersededAt === mutation.supersededAt &&
    (mutation.invalidAt === undefined || oldMemory.frontmatter.invalid_at === mutation.invalidAt);
  const lifecycleEffect = alreadyApplied
    ? await hasTemporalLifecycleEffect({
        storage,
        memoryId: oldMemory.frontmatter.id,
        timestamp: mutation.supersededAt,
        operationKey,
        reasonCode: "structured-attribute-update",
        relatedMemoryIds: [replacementId],
      })
    : undefined;
  if (alreadyApplied && lifecycleEffect === undefined) return false;
  if (!alreadyApplied || lifecycleEffect === false) {
    if (!storage.writeMemoryFrontmatterIfUnchanged) return false;
    const wrote = await storage.writeMemoryFrontmatterIfUnchanged(
      oldMemory,
      temporalMutationPatch(replacementId, mutation),
      {
        actor: "temporal-supersession",
        reasonCode: "structured-attribute-update",
        relatedMemoryIds: [replacementId],
        correlationId: operationKey,
      },
    );
    if (!wrote) return false;
  }

  let allCandidates = args.allCandidates;
  if (!allCandidates) {
    let hotMemories: MemoryFile[];
    let coldMemories: MemoryFile[];
    try {
      hotMemories = await storage.readAllMemories();
    } catch (error) {
      log.warn(`temporal-supersession: recovery hot-memory scan failed: ${error}`);
      return false;
    }
    try {
      coldMemories = await storage.readAllColdMemories();
    } catch (error) {
      log.warn(`temporal-supersession: recovery cold-memory scan failed: ${error}`);
      return false;
    }
    allCandidates = [...hotMemories, ...coldMemories];
  }
  const childrenCompleted = await expireChildChunksForSupersededParent({
    storage,
    allCandidates,
    parentId: oldMemory.frontmatter.id,
    newMemoryId: replacementId,
    supersededAt: mutation.supersededAt,
    invalidAt: mutation.invalidAt ?? oldMemory.frontmatter.invalid_at,
    operationKey,
  });
  if (!childrenCompleted) return false;

  const keysToTombstone =
    mutation.matchedKeys.length > 0 ? mutation.matchedKeys : [undefined];
  for (const key of keysToTombstone) {
    const tombstoneOperationKey = `${operationKey}:tombstone:${key ?? "content"}`;
    if (
      await hasTemporalTombstoneEffect({
        storage,
        oldMemory,
        supersessionKey: key,
        operationKey: tombstoneOperationKey,
        createdAt: mutation.supersededAt,
      })
    ) {
      continue;
    }
    try {
      const tombstoneId = await storage.appendTombstone({
        reason: "supersession",
        createdBy: "supersession",
        sourceMemoryId: oldMemory.frontmatter.id,
        ...(oldMemory.frontmatter.contentHash
          ? { contentHash: oldMemory.frontmatter.contentHash }
          : {}),
        rawContent: oldMemory.content,
        ...(oldMemory.frontmatter.entityRef ? { entityRef: oldMemory.frontmatter.entityRef } : {}),
        ...(key ? { supersessionKey: key } : {}),
        createdAt: mutation.supersededAt,
        operationKey: tombstoneOperationKey,
      });
      if (tombstoneId === null && storage.isTombstonesEnabled?.() !== false) {
        return false;
      }
    } catch (error) {
      log.warn(
        `temporal-supersession: tombstone emit failed for ${oldMemory.frontmatter.id}${key ? ` (key=${key})` : ""} : ${error}`,
      );
      return false;
    }
  }
  return true;
}

export interface TemporalSupersessionResult {
  supersededIds: string[];
  matchedKeys: string[];
}

/**
 * Scan existing memories and mark any that are superseded by the
 * just-written memory.  Fails open on I/O errors — the new memory is already
 * on disk, and supersession is a best-effort hygiene step.
 */
export async function applyTemporalSupersession(args: {
  storage: TemporalSupersessionStorage;
  newMemoryId: string;
  entityRef?: string;
  structuredAttributes?: Record<string, string>;
  createdAt: string;
  enabled: boolean;
  /**
   * When true, skip the persisted `frontmatter.created` lookup and use
   * `args.createdAt` directly as the ordering anchor.  Set this on the
   * hash-dedup short-circuit path where `newMemoryId` points to an existing
   * OLD fact (no new file is written) and its persisted timestamp would be
   * stale relative to the incoming promotion event (PR #402 Finding Uyui).
   */
  useCallerTimestamp?: boolean;
  /** Namespace used by the dependency propagation worker. */
  namespaceScope?: string;
  /** Optional durable delivery for one-hop propagation. */
  dependencyPropagationDelivery?: DependencyPropagationDeliveryPort;
}): Promise<TemporalSupersessionResult> {
  const empty: TemporalSupersessionResult = { supersededIds: [], matchedKeys: [] };
  const createdAtMs = typeof args.createdAt === "string" ? Date.parse(args.createdAt) : Number.NaN;
  if (!Number.isFinite(createdAtMs)) {
    log.warn(`temporal-supersession: refusing mutation with invalid createdAt: ${String(args.createdAt)}`);
    return empty;
  }
  // Validate the caller's ordering anchor before any corpus scan or durable
  // side-effect preparation.  A malformed timestamp must be a true no-op:
  // otherwise a later monotonic clamp could manufacture a 1970 mutation and
  // leave a prepared propagation job without a replayable temporal identity.
  if (!args.enabled) return empty;
  if (!args.entityRef) return empty;
  if (!args.structuredAttributes) return empty;
  if (Object.keys(args.structuredAttributes).length === 0) return empty;
  if (typeof args.storage.getMemoryTimeline !== "function") {
    log.warn("temporal-supersession: required memory timeline adapter is missing");
    return empty;
  }

  const newKeys = supersessionKeysForFact({
    entityRef: args.entityRef,
    structuredAttributes: args.structuredAttributes,
  });
  if (newKeys.length === 0) return empty;

  let hotMemories: MemoryFile[];
  try {
    hotMemories = await args.storage.readAllMemories();
  } catch (err) {
    log.warn(`temporal-supersession: readAllMemories failed: ${err}`);
    return empty;
  }

  // Finding 1 fix: use the on-disk effective validity start of the
  // newly-written memory rather than a wall-clock timestamp sampled after
  // `writeMemory` returns.  In concurrent writers the two can differ by enough
  // to cause wrong-direction supersession.  If source replay/import provided
  // valid_at, it must drive ordering; otherwise created remains the legacy
  // fallback.  If the memory is not yet visible in the cache (edge case during
  // fast concurrent writes) fall back to args.createdAt.
  //
  // PR #402 round-12 (Finding Uyui): on the hash-dedup early-return path the
  // caller supplies the OLD matching fact's id as `newMemoryId` (no new file is
  // written).  That makes `newMemoryFile.frontmatter.created` an arbitrarily
  // old timestamp.  When `args.useCallerTimestamp` is set the caller explicitly
  // opts out of the persisted-timestamp lookup so `args.createdAt` (the
  // incoming event time: source valid_at when present, otherwise wall-clock) is
  // used directly, keeping ordering correct regardless of how old the matching
  // fact is.
  const newMemoryFile = hotMemories.find((m) => m.frontmatter.id === args.newMemoryId);
  const persistedCreatedAt = args.useCallerTimestamp
    ? args.createdAt
    : (newMemoryFile ? effectiveValidAt(newMemoryFile.frontmatter) : args.createdAt);

  const supersededIds: string[] = [];
  const matchedKeys = new Set<string>();

  // Process hot then cold.  Hot-then-cold ordering is safer because hot
  // writes are more frequent and the CAS re-read guards against double-writes.
  // A Set<string> of already-processed ids ensures that a memory visible in
  // both tiers (same logical memory with different filesystem paths during a
  // migration race) is processed at most once.  Keying on `frontmatter.id`
  // is correct because the same logical memory has the same id regardless of
  // which tier's directory it currently lives in (PR #402 Finding 1 fix).
  // Fall back to path-based keying when id is absent (defensive).
  const processedIds = new Set<string>();

  // Finding UOGi fix (round-6): readAllColdMemories() performs a full uncached
  // recursive directory scan of cold/.  After Finding UTsP broadened the scan
  // to cover the entire cold root (not just facts/+corrections/), the per-call
  // cost grows with the cold tree size.
  //
  // The fix is a TTL-based in-memory cache inside StorageManager
  // (readAllColdMemories caches its result for COLD_SCAN_CACHE_TTL_MS) that is
  // shared across consecutive supersession calls within the same write burst.
  // The cache is invalidated automatically on any hot→cold demotion (which
  // calls invalidateAllMemoriesCache, which also clears the cold cache) and
  // expires after the TTL as a safety net.
  //
  // This means back-to-back structured-attribute writes in the same burst
  // (e.g. batch extraction) pay the cold I/O cost at most once, not N times.
  // Correctness is preserved because the cache TTL ensures eventual consistency
  // and the invalidation hook covers the hot→cold path.

  let coldMemories: MemoryFile[];
  try {
    coldMemories = await args.storage.readAllColdMemories();
  } catch (err) {
    log.warn(`temporal-supersession: readAllColdMemories failed: ${err}`);
    coldMemories = [];
  }

  // Combine hot and cold memories into a single scan.  New memory itself is
  // excluded inline.  We do NOT skip cold scan when hot produced zero
  // supersessions — the P1 finding is precisely that stale cold facts leak
  // when hot has no hits.
  const allCandidates: MemoryFile[] = [...hotMemories, ...coldMemories];
  // Resolve the replacement from the combined hot and cold snapshot. A
  // hash-dedup promotion can point at a cold-only memory, and replay needs its
  // captured content rather than a null replacement payload.
  const replacementMemory =
    allCandidates.find((memory) => memory.frontmatter.id === args.newMemoryId) ?? newMemoryFile;

  for (const memory of allCandidates) {
    if (memory.frontmatter.id === args.newMemoryId) continue;
    const dedupeKey = memory.frontmatter.id ?? memory.path;
    if (processedIds.has(dedupeKey)) continue;
    const snapshotStatus = memory.frontmatter.status ?? "active";
    if (snapshotStatus !== "active") {
      // A stale non-active snapshot entry must not suppress an active copy of
      // the same logical memory that appears later in another tier.  This can
      // happen during hot/cold migration races where the hot snapshot is already
      // superseded but the cold copy is still active and should be evaluated.
      continue;
    }
    // NOTE: do NOT call processedIds.add(dedupeKey) here.  We defer marking
    // the id as processed until AFTER the CAS re-read succeeds.  If we mark
    // it here and the re-read fails (e.g. the hot entry has already been
    // migrated to cold storage), the same logical id that appears later in
    // the cold tier scan would be silently skipped, leaving a stale cold
    // fact unsuperseded.  Deferring ensures that a failed primary-tier read
    // grants the alternate tier a chance to process the same id (PR #402
    // round-6 Finding 1 fix).

    const decision = shouldSupersedeExisting({
      candidate: memory.frontmatter,
      newEntityRef: args.entityRef,
      newAttributes: args.structuredAttributes,
      newCreatedAt: persistedCreatedAt,
      newMemoryId: args.newMemoryId,
    });
    if (!decision) {
      // No supersession decision — safe to mark as processed now so the
      // alternate tier doesn't re-evaluate an identical non-matching entry.
      processedIds.add(dedupeKey);
      continue;
    }

    let preparedPropagation: {
      delivery: DependencyPropagationDeliveryPort;
      event: PropagationEvent;
      token: DependencyPropagationPreparationToken | null;
    } | null = null;
    let primaryPath: string | null = null;
    let primaryBefore: TemporalMemorySnapshot | null = null;
    let primaryPatch: Partial<MemoryFrontmatter> | null = null;
    try {
      // CAS-style re-read immediately before the write.  `readAllMemories()`
      // is a snapshot — with concurrent writers, another run may have already
      // superseded this candidate since we loaded it.  If we blindly trust the
      // snapshot we can clobber a newer `supersededBy` link with a stale one.
      //
      // File storage offers no true locking, so the best we can do is:
      //   1. re-read the exact file we're about to mutate
      //   2. verify status is still "active" and no `supersededBy` is set
      //   3. only then issue the write
      // If the re-read shows a newer concurrent writer beat us to it, skip.
      // This CAS pattern applies equally to hot and cold tier candidates.
      // Mark as processed AFTER confirming the candidate is readable so that
      // a migration-race read failure on the hot entry does not silently
      // prevent the cold entry from being evaluated (Finding 1, round 6).
      const fresh = await args.storage.readMemoryByPath(memory.path);
      if (!fresh) {
        log.debug(
          `[engram] temporal supersession skipped candidate ${memory.frontmatter.id}: no longer readable at ${memory.path} — leaving id available for alternate tier`,
        );
        // Do NOT add to processedIds — allow the cold-tier copy to be
        // evaluated in the next iteration of the same scan.
        continue;
      }
      // Candidate is readable — mark the id as processed now to prevent the
      // alternate tier from double-writing.
      processedIds.add(dedupeKey);
      const freshStatus = fresh.frontmatter.status ?? "active";
      if (freshStatus !== "active" || fresh.frontmatter.supersededBy) {
        log.debug(
          `[engram] temporal supersession skipped candidate ${memory.frontmatter.id}: already superseded by concurrent writer`,
        );
        continue;
      }
      primaryPath = fresh.path;
      primaryBefore = {
        content: fresh.content,
        frontmatter: { ...fresh.frontmatter },
      };

      // Finding 2 fix: the `supersededAt` / `updated` timestamps written to the
      // old fact must never run backwards relative to its own persisted
      // `created` timestamp.  If the caller-supplied `args.createdAt` (which
      // represents "when the new replacing fact was authored") is earlier than
      // either the new fact's persisted `created` (T_new) or the old fact's
      // persisted `created` (T_old), we'd be writing a nonsensical
      // `supersededAt` that precedes the old memory's own creation.  Clamp to
      // the monotonic maximum so time only moves forward.
      // This monotonic clamp is applied for both hot and cold tier writes.
      const oldCreatedMs = new Date(fresh.frontmatter.created).getTime();
      const newCreatedMs = new Date(persistedCreatedAt).getTime();
      const argCreatedMs = new Date(args.createdAt).getTime();
      const maxMs = Math.max(
        Number.isFinite(oldCreatedMs) ? oldCreatedMs : 0,
        Number.isFinite(newCreatedMs) ? newCreatedMs : 0,
        Number.isFinite(argCreatedMs) ? argCreatedMs : 0,
      );
      const supersededAt = new Date(maxMs).toISOString();

      // Issue #680 — explicit fact lifecycle.  When the new fact
      // supersedes this one, set the predecessor's `invalid_at` to the
      // successor's effective valid_at.  Skip when the predecessor
      // already carries an `invalid_at` so manual / earlier values
      // are preserved (idempotent).
      //
      // Codex P1 on PR #713: in the hash-dedup early-return path
      // (`useCallerTimestamp: true`), `newMemoryFile` is actually the
      // OLD matching fact — no new file was written — so its
      // `valid_at` is the predecessor's own old timestamp, not the
      // successor's effective time. Use `persistedCreatedAt`
      // directly in that path so the predecessor's invalid_at lines
      // up with the caller's wall-clock, not the matching fact's old
      // valid_at. The non-dedup path keeps the previous behavior
      // (prefer the new file's explicit valid_at, fall back to its
      // persisted created).
      let invalidAtPatch: string | undefined;
      if (!fresh.frontmatter.invalid_at) {
        if (args.useCallerTimestamp) {
          invalidAtPatch = persistedCreatedAt;
        } else {
          const newValidAt = replacementMemory?.frontmatter.valid_at?.trim();
          invalidAtPatch =
            newValidAt && newValidAt.length > 0 ? newValidAt : persistedCreatedAt;
        }
      }
      const mutation: TemporalSupersessionMutation = {
        supersededAt,
        ...(invalidAtPatch ? { invalidAt: invalidAtPatch } : {}),
        matchedKeys: decision.matchedKeys,
      };
      primaryPatch = temporalMutationPatch(args.newMemoryId, mutation);
      const propagationEvent: PropagationEvent | null =
        args.dependencyPropagationDelivery && args.namespaceScope
          ? {
              oldMemory: {
                content: fresh.content,
                frontmatter: {
                  ...fresh.frontmatter,
                  ...(fresh.frontmatter.links
                    ? { links: fresh.frontmatter.links.map((link) => ({ ...link })) }
                    : {}),
                },
              },
              replacementId: args.newMemoryId,
              replacementContent: replacementMemory?.content ?? null,
              cause: "temporal_supersession",
              namespaceScope: args.namespaceScope,
              temporalMutation: mutation,
            }
          : null;
      if (propagationEvent && args.dependencyPropagationDelivery) {
        preparedPropagation = {
          delivery: args.dependencyPropagationDelivery,
          event: propagationEvent,
          token: null,
        };
        try {
          preparedPropagation.token =
            await args.dependencyPropagationDelivery.prepare(propagationEvent);
        } catch (prepareErr) {
          log.warn(
            `temporal-supersession: dependency propagation preparation failed for ${fresh.frontmatter.id}: ${prepareErr}`,
          );
        }
      }
      const wrote = await applyTemporalSupersessionPrimaryMutation({
        storage: args.storage,
        oldMemory: fresh,
        replacementId: args.newMemoryId,
        mutation,
        allCandidates,
      });
      if (!wrote) {
        const commitState = await classifyTemporalPrimaryMutation({
          storage: args.storage,
          path: fresh.path,
          before: primaryBefore,
          patch: primaryPatch,
        });
        if (preparedPropagation) {
          await settleTemporalPropagationAfterPrimaryFailure(
            preparedPropagation,
            commitState,
            fresh.frontmatter.id,
          );
          if (commitState !== "not-committed") {
            log.warn(
              `temporal-supersession: retaining dependency propagation recovery for ${fresh.frontmatter.id} after ${commitState} primary mutation`,
            );
          }
        }
        preparedPropagation = null;
        continue;
      }
      if (preparedPropagation) {
        const completedPropagation = preparedPropagation;
        preparedPropagation = null;
        try {
          await completedPropagation.delivery.afterMutation(
            completedPropagation.token,
            completedPropagation.event,
          );
        } catch (afterMutationErr) {
          log.warn(
            `temporal-supersession: dependency propagation delivery failed for ${memory.frontmatter.id}: ${afterMutationErr}`,
          );
        }
      }
      supersededIds.push(memory.frontmatter.id);
      for (const key of decision.matchedKeys) matchedKeys.add(key);
    } catch (err) {
      let commitState: TemporalPrimaryCommitState = "unknown";
      if (primaryPath && primaryBefore && primaryPatch) {
        commitState = await classifyTemporalPrimaryMutation({
          storage: args.storage,
          path: primaryPath,
          before: primaryBefore,
          patch: primaryPatch,
        });
      }
      if (preparedPropagation) {
        await settleTemporalPropagationAfterPrimaryFailure(
          preparedPropagation,
          commitState,
          memory.frontmatter.id,
        );
        if (commitState !== "not-committed") {
          log.warn(
            `temporal-supersession: retaining dependency propagation recovery for ${memory.frontmatter.id} after ${commitState} primary mutation`,
          );
        }
      }
      preparedPropagation = null;
      log.warn(
        `temporal-supersession: failed to mark ${memory.frontmatter.id} superseded: ${err}`,
      );
    }
  }

  if (supersededIds.length > 0) {
    log.debug(
      `temporal-supersession: marked ${supersededIds.length} memories superseded by ${args.newMemoryId} (keys=${Array.from(matchedKeys).join(",")})`,
    );
  }

  return { supersededIds, matchedKeys: Array.from(matchedKeys) };
}

/**
 * Recall-side filter: returns true when the candidate should be excluded
 * from recall because it has been temporally superseded.  When
 * `includeInRecall` is true, this always returns false (the fact is kept),
 * matching the audit/history opt-in described in the config.
 */
export function shouldFilterSupersededFromRecall(
  frontmatter: MemoryFrontmatter,
  options: { enabled: boolean; includeInRecall: boolean },
): boolean {
  if (!options.enabled) return false;
  if (options.includeInRecall) return false;
  return frontmatter.status === "superseded";
}

import { BufferDrainClaims, type BufferSessionSaveOutcome } from "./buffer-drain-claims.js";
import { createHash } from "node:crypto";
import type { Stats } from "node:fs";
import { lstat, readdir, unlink } from "node:fs/promises";
import path from "node:path";
import { subtractBufferTurns } from "../buffer-turn-helpers.js";
import { log } from "../logger.js";
import { SecureStoreDecryptError, SecureStoreLockedError } from "../secure-store/secure-fs.js";
import type { BufferEntryState, BufferState, BufferTurn } from "../types.js";

/** The secure-store file I/O the owning StorageManager already provides. */
export interface BufferFileIo {
  read(filePath: string): Promise<string>;
  write(filePath: string, content: string): Promise<void>;
}

type FsError = NodeJS.ErrnoException;

function isMissing(err: FsError | null): boolean {
  return err?.code === "ENOENT";
}

function asFsError(err: Error): FsError {
  return err;
}

/**
 * Case-independent, collision-free file name for a buffer key: the lowercase
 * hex SHA-256 of the key under a fixed prefix. Hex has no case and no path
 * characters, so `Session-A` and `session-a` get different names even on
 * case-insensitive filesystems, every key (short or long) lives in the same
 * naming domain, and the key itself is stored inside the file (loading never
 * inverts the hash).
 */
export function bufferSessionFileName(key: string): string {
  return `s-${createHash("sha256").update(key).digest("hex")}.json`;
}

/** Flatten a legacy BufferState into per-session entries (top-level fields
 * are the legacy mirror of the "default" entry). */
export function legacyStateToEntries(state: BufferState): Map<string, BufferEntryState> {
  const entries = new Map<string, BufferEntryState>();
  for (const [key, value] of Object.entries(state.entries ?? {})) {
    if (value && Array.isArray(value.turns)) entries.set(key, value);
  }
  if (!entries.has("default")) {
    entries.set("default", {
      turns: Array.isArray(state.turns) ? state.turns : [],
      lastExtractionAt: state.lastExtractionAt ?? null,
      extractionCount: Number.isFinite(state.extractionCount) ? state.extractionCount : 0,
    });
  }
  return entries;
}

/** What a per-session file contains once parsed (written only by this module). */
interface SessionFileBody {
  key?: string;
  turns?: BufferTurn[];
  retainedTurns?: BufferTurn[];
  lastExtractionAt?: string | null;
  extractionCount?: number;
}

function entryFromBody(body: SessionFileBody): { key: string; entry: BufferEntryState } | null {
  if (!body || !Array.isArray(body.turns) || (body.key?.length ?? 0) === 0) return null;
  const entry: BufferEntryState = {
    turns: body.turns,
    lastExtractionAt: body.lastExtractionAt ?? null,
    extractionCount: Number.isFinite(body.extractionCount) ? Number(body.extractionCount) : 0,
  };
  if (Array.isArray(body.retainedTurns)) entry.retainedTurns = body.retainedTurns;
  return { key: String(body.key), entry };
}

/**
 * One file per buffer session under `<stateDir>/buffer/`, so the observe hot
 * path persists only the session that changed. All writes happen under
 * SmartBuffer's serialized mutation chain (one writer per process).
 *
 * Sessions claimed by `remnic buffer drain` (see buffer-drain-claims.ts) are
 * owned by the drain: `save` hands the in-memory entry INTO the claim
 * (identity-deduped merge) instead of writing a session file, so a live
 * buffer owner can never resurrect claimed turns.
 */
export class BufferSessionFiles {
  private dirVerified = false;
  private readonly claimsStore: BufferDrainClaims;

  constructor(
    private readonly stateDir: string,
    private readonly io: BufferFileIo,
  ) {
    this.claimsStore = new BufferDrainClaims(stateDir, io);
  }

  /** The drain-claim store for this state dir (CLI scan + claim ops). */
  get claims(): BufferDrainClaims {
    return this.claimsStore;
  }

  /** Sync gate check: is this session claimed by a buffer drain? */
  isClaimed(key: string): boolean {
    return this.claimsStore.isClaimed(key);
  }

  private get dir(): string {
    return path.join(this.stateDir, "buffer");
  }

  private fileFor(key: string): string {
    return path.join(this.dir, bufferSessionFileName(key));
  }

  /**
   * Refuse a symlinked buffer directory: following it would send buffered
   * conversation data (and deletions) outside the memory root. One lstat of
   * one directory, cached after it passes, so the observe path pays nothing
   * per write; the cache is dropped on any failure.
   */
  private async assertDirSafe(): Promise<void> {
    if (this.dirVerified) return;
    let stat: Stats | null = null;
    try {
      stat = await lstat(this.dir);
    } catch (err) {
      if (!(err instanceof Error) || !isMissing(asFsError(err))) throw err;
    }
    if (stat && (stat.isSymbolicLink() || !stat.isDirectory())) {
      throw new Error(`buffer session directory must be a real directory, not a symlink or file: ${this.dir}`);
    }
    this.dirVerified = stat !== null;
  }

  /** Persist ONE session atomically. Compact JSON: machine-read state, and
   * pretty-printing a large buffer costs CPU and bytes on every observe.
   * A drain-claimed session is handed over instead (see class doc). */
  async save(key: string, entry: BufferEntryState): Promise<BufferSessionSaveOutcome> {
    if (this.isClaimed(key)) {
      // Consume the tombstone ONLY when the drain finished (acked: extracted
      // turns recorded, nothing pending, no lease). Partial `drained` just
      // means chunks completed — the drainer may still be running, and
      // releasing here would unlink its claim and turn its later writes into
      // no-ops.
      if (await this.claimsStore.isDrained(key)) {
        const drained = await this.claimsStore.drainedTurns(key);
        // The drain finished this session: the claim is a tombstone. Write
        // the owner's fresh remainder back as a session file (the drained
        // turns are subtracted here too, so a caller that did not subtract
        // them cannot resurrect them) and release the tombstone.
        const fresh: BufferEntryState = { ...entry, turns: subtractBufferTurns(entry.turns, drained) };
        if (entry.retainedTurns && entry.retainedTurns.length > 0) {
          fresh.retainedTurns = subtractBufferTurns(entry.retainedTurns, drained);
          if (fresh.retainedTurns.length === 0) delete fresh.retainedTurns;
        }
        await this.assertDirSafe();
        await this.io.write(this.fileFor(key), JSON.stringify({ key, ...fresh }));
        await this.claimsStore.release(key);
        return { status: "saved", drainedTurns: drained };
      }
      await this.claimsStore.mergeIntoClaim(key, entry);
      return { status: "handed_over" };
    }
    await this.assertDirSafe();
    await this.io.write(this.fileFor(key), JSON.stringify({ key, ...entry }));
    return { status: "saved" };
  }

  /** Remove one session's file. Idempotent: an absent file is fine. */
  async remove(key: string): Promise<void> {
    await this.assertDirSafe();
    try {
      await unlink(this.fileFor(key));
    } catch (err) {
      if (!(err instanceof Error) || !isMissing(asFsError(err))) throw err;
    }
  }

  private async listFiles(): Promise<string[]> {
    await this.assertDirSafe();
    try {
      const dirents = await readdir(this.dir, { withFileTypes: true });
      // Regular files only: a symlink inside the directory is never followed.
      return dirents.filter((d) => d.isFile() && d.name.endsWith(".json")).map((d) => d.name);
    } catch (err) {
      if (err instanceof Error && isMissing(asFsError(err))) return [];
      throw err;
    }
  }

  /** Read every per-session file. Corrupt files are skipped (and logged) so
   * one bad file cannot nuke the other sessions' buffered turns. */
  private async readAll(): Promise<{ entries: Map<string, BufferEntryState>; fileCount: number }> {
    const names = await this.listFiles();
    const entries = new Map<string, BufferEntryState>();
    for (const name of names) {
      try {
        const body: SessionFileBody = JSON.parse(await this.io.read(path.join(this.dir, name)));
        const parsed = entryFromBody(body);
        if (!parsed) throw new Error("invalid buffer session file shape");
        if (entries.has(parsed.key)) {
          log.warn(`buffer: duplicate session file for key ${parsed.key} (${name}); keeping the first`);
          continue;
        }
        entries.set(parsed.key, parsed.entry);
      } catch (err) {
        // A locked store or a wrong key is not a corrupt file: reading it as empty would let
        // later saves replace the real encrypted session.
        if (err instanceof SecureStoreLockedError || err instanceof SecureStoreDecryptError) throw err;
        log.warn(`buffer: skipping unreadable per-session buffer file ${name}: ${err instanceof Error ? err.message : String(err)}`);
      }
    }
    return { entries, fileCount: names.length };
  }

  /**
   * Read the legacy single-file buffer.json for migration. Null when absent,
   * or unreadable while session files exist (they are authoritative; a
   * corrupt leftover must not block startup). With no session files a corrupt
   * legacy file THROWS, preserving the old contract so callers can reset it.
   */
  private async readLegacy(hasSessionFiles: boolean): Promise<BufferState | null> {
    let raw: string;
    try {
      raw = await this.io.read(path.join(this.stateDir, "buffer.json"));
    } catch (err) {
      if (err instanceof SecureStoreLockedError) throw err;
      if (err instanceof Error && isMissing(asFsError(err))) return null;
      throw err;
    }
    try {
      const legacy: BufferState = JSON.parse(raw);
      return legacy;
    } catch (err) {
      if (!hasSessionFiles) throw err;
      log.warn(
        `buffer: legacy buffer.json is unreadable but per-session buffer files exist; ` +
          `ignoring the legacy file (${err instanceof Error ? err.message : String(err)})`,
      );
      return null;
    }
  }

  /**
   * Load the whole buffer, migrating a legacy buffer.json once. A per-session
   * file that parsed wins over the legacy snapshot (a crash mid-migration
   * leaves exactly that pair); legacy entries without a usable file are
   * written out, then the legacy file is retired. Both steps are idempotent.
   */
  async load(): Promise<BufferState> {
    const { entries, fileCount } = await this.readAll();
    const legacy = await this.readLegacy(fileCount > 0);
    if (legacy !== null) {
      for (const [key, entry] of legacyStateToEntries(legacy)) {
        if (entries.has(key)) continue;
        entries.set(key, entry);
        await this.save(key, entry);
      }
      try {
        await unlink(path.join(this.stateDir, "buffer.json"));
      } catch (err) {
        if (!(err instanceof Error) || !isMissing(asFsError(err))) throw err;
      }
    }
    const out: NonNullable<BufferState["entries"]> = Object.create(null);
    for (const [key, entry] of entries) out[key] = entry;
    const def = entries.get("default");
    return {
      turns: def?.turns ?? [],
      lastExtractionAt: def?.lastExtractionAt ?? null,
      extractionCount: def?.extractionCount ?? 0,
      entries: out,
    };
  }

  /**
   * Reconcile the files with a WHOLE buffer state: write every entry, then
   * delete files for keys no longer present. Writes first, deletes last: a
   * crash leaves stale extra files (removed by the next reconcile) but never
   * loses sessions the state says exist. Not on the observe hot path.
   */
  async reconcile(state: BufferState): Promise<void> {
    const entries = legacyStateToEntries(state);
    const existing = await this.listFiles();
    for (const [key, entry] of entries) await this.save(key, entry);
    const live = new Set([...entries.keys()].map((key) => bufferSessionFileName(key)));
    for (const name of existing) {
      if (live.has(name)) continue;
      try {
        await unlink(path.join(this.dir, name));
      } catch (err) {
        if (!(err instanceof Error) || !isMissing(asFsError(err))) throw err;
      }
    }
  }
}

import {
  buildRetiredFactTombstoneInputs,
  type TombstoneCreatedBy,
  type TombstoneReason,
} from "../lifecycle/tombstones.js";
import { log } from "../logger.js";
import { stripCitationForTemplate } from "../source-attribution.js";
import { supersessionKeysForFact } from "../temporal-supersession.js";
import type { MemoryFile, MemoryFrontmatter } from "../types.js";
import { composeMemoryEnvelope, type SealedMemoryEnvelope } from "../write-envelope.js";
import { hasSupersessionAudit } from "./supersession-audit.js";

type TombstoneInput = {
  reason: TombstoneReason;
  createdBy: TombstoneCreatedBy;
  sourceMemoryId: string;
  rawContent: string;
  entityRef?: string;
  supersessionKey?: string;
  operationKey?: string;
  createdAt?: string;
  contentHash?: string;
};

export interface SupersessionSideEffectOptions {
  oldMemoryId: string;
  newMemoryId: string;
  reason: string;
  now: string;
  operationId: string;
  exactReplay: boolean;
  currentBefore: MemoryFile;
  updatedFm: MemoryFrontmatter;
  actor?: string;
  audit?: SupersessionAuditOptions;
  citationTemplate: string;
  correctionsDir: string;
  readMemoryByPath: (filePath: string) => Promise<MemoryFile | null>;
  isColdOrArchiveTierPath: (memoryPath: string) => boolean;
  invalidateColdMemoriesCache: () => void;
  invalidateAllMemoriesCache: () => void;
  bumpMemoryCorpusVersion: () => void;
  appendLifecycleEvent: () => Promise<void>;
  bumpMemoryStatusVersion: () => void;
  hasExactTombstone: (input: TombstoneInput) => Promise<boolean>;
  appendTombstone: (input: TombstoneInput) => Promise<string | null>;
  writeSealedMemory: (
    envelope: SealedMemoryEnvelope,
    extras: { actor?: string; lineage: [string, string]; sourceMemoryId: string }
  ) => Promise<unknown>;
}

export interface SupersessionAuditOptions {
  content: string;
  tags?: string[];
  structuredAttributes?: Record<string, string>;
  source?: string;
}

export async function runSupersessionSideEffects(options: SupersessionSideEffectOptions): Promise<boolean> {
  const {
    oldMemoryId,
    newMemoryId,
    reason,
    now,
    operationId,
    exactReplay,
    currentBefore,
    updatedFm,
    citationTemplate,
  } = options;
  try {
    if (options.isColdOrArchiveTierPath(currentBefore.path)) options.invalidateColdMemoriesCache();
    if (exactReplay) options.invalidateAllMemoriesCache();
    else options.bumpMemoryCorpusVersion();
    await options.appendLifecycleEvent();
    options.bumpMemoryStatusVersion();
    log.debug(`superseded memory ${oldMemoryId} by ${newMemoryId}: ${reason}`);

    if (currentBefore.frontmatter.category === "fact") {
      for (const input of buildRetiredFactTombstoneInputs(
        {
          id: oldMemoryId,
          content: stripCitationForTemplate(currentBefore.content, citationTemplate),
          contentHash: currentBefore.frontmatter.contentHash,
          entityRef: updatedFm.entityRef,
          structuredAttributes: currentBefore.frontmatter.structuredAttributes,
        },
        {
          reason: "contradiction_resolution",
          createdBy: "contradiction_resolution",
          createdAt: now,
          supersessionKeysForFact,
        }
      )) {
        const exactInput = { ...input, operationKey: operationId };
        const exists = (await options.hasExactTombstone(exactInput)) || (await options.hasExactTombstone(input));
        if (!exists) await options.appendTombstone(exactInput);
      }
    }

    const auditBody = `Superseded: ${options.audit?.content ?? currentBefore.content}\n\nReason: ${reason}`;
    const auditExists = await hasSupersessionAudit(
      {
        correctionsDir: options.correctionsDir,
        readMemoryByPath: options.readMemoryByPath,
      },
      oldMemoryId,
      newMemoryId,
      auditBody,
      options.audit?.structuredAttributes
    );
    if (!auditExists) {
      const auditEnvelope = composeMemoryEnvelope(
        {
          content: auditBody,
          category: "correction",
          confidence: 1,
          tags: options.audit?.tags ?? ["supersession", "auto-resolved"],
          structuredAttributes: options.audit?.structuredAttributes,
        },
        { source: options.audit?.source ?? "contradiction-detection" }
      );
      await options.writeSealedMemory(auditEnvelope, {
        actor: options.actor,
        lineage: [oldMemoryId, newMemoryId],
        sourceMemoryId: oldMemoryId,
      });
    }
    options.invalidateAllMemoriesCache();
    return true;
  } catch (err) {
    log.error(`supersession side effects failed for ${oldMemoryId}:`, err);
    return false;
  }
}

import { randomUUID } from "node:crypto";
import { mkdir } from "node:fs/promises";
import path from "node:path";
import type { BufferTurn } from "../types.js";

/**
 * Persist a copy of extraction-buffer turns that are being DROPPED after repeated extraction failures (trigger-drain drop
 * path), so a destructive drop never loses content silently. Written under `<stateDir>/dropped/` through the store's secure
 * writer, so encrypted stores keep it encrypted (secure-fs encrypts the whole `state/dropped/` prefix). Returns the path.
 */
export async function saveDroppedExtractionChunk(
  stateDir: string,
  writeSecureFile: (filePath: string, content: string) => Promise<void>,
  bufferKey: string,
  reason: string,
  turns: readonly BufferTurn[],
): Promise<string> {
  const droppedDir = path.join(stateDir, "dropped");
  await mkdir(droppedDir, { recursive: true });
  const safeKey = bufferKey.replace(/[^a-zA-Z0-9._-]/g, "-").slice(0, 80) || "default";
  // The random suffix keeps copies written in the same millisecond (or for keys that truncate to the same name) from
  // overwriting each other.
  const filePath = path.join(droppedDir, `${Date.now()}-${randomUUID().slice(0, 8)}-${safeKey}.json`);
  const payload = { bufferKey, reason, droppedAt: new Date().toISOString(), turns };
  await writeSecureFile(filePath, JSON.stringify(payload, null, 2));
  return filePath;
}

