  ownerId?: string;
  createdAt?: number;
  processStartedAtMs?: number;
  malformed?: boolean;
};

export type TombstoneBlockedCaptureIndexOptions = {
  readonly stateDir: string;
  readonly memoryDir: string;
  readonly secureStoreKeyProvider: () => Buffer | null;
  readonly secureStoreWriteKeyProvider: () => Buffer | null;
  readonly lockOptions: () => ContentHashIndexLockOptions;
  /** Capture-write-lock limit source; undefined until converge installs limits. */
  readonly captureLockLimitSource?: () => CaptureWriteLockLimitSource | undefined;
  readonly readAllMemories: () => Promise<MemoryFile[]>;
  readonly readAllColdMemories: () => Promise<MemoryFile[]>;
  readonly parseMemory?: OfflineSyncMemoryParser;
  readonly withHeldFileLock?: typeof withHeldFileLock;
};

/**
 * Durable targeted deduplication for tombstone-blocked explicit captures.
 *
 * The active fact-hash index intentionally excludes blocked rows. This small
 * companion index keeps the blocked identity visible without making every
 * authoritative active-index miss scan the full corpus.
 */
export class TombstoneBlockedCaptureIndex {
  private readonly options: TombstoneBlockedCaptureIndexOptions;
  private index: ContentHashIndex | null = null;
  private loadPromise: Promise<ContentHashIndex> | null = null;
  private refreshPromise: Promise<ContentHashIndex> | null = null;
  private authoritative = false;
  private readonly captureWriteLock: TombstoneBlockedCaptureWriteLock;

  constructor(options: TombstoneBlockedCaptureIndexOptions) {
    this.options = options;
    this.captureWriteLock = new TombstoneBlockedCaptureWriteLock({
      stateDir: options.stateDir,
      withHeldFileLock: options.withHeldFileLock,
      lockOptions: options.captureLockLimitSource,
    });
  }

  private createIndex(): ContentHashIndex {
    return new ContentHashIndex(
      path.join(this.options.stateDir, "tombstone-blocked-capture"),
      this.options.secureStoreKeyProvider,
      this.options.secureStoreWriteKeyProvider,
      this.options.memoryDir,
      this.options.lockOptions()
    );
  }

  private indexPath(): string {
    return path.join(this.options.stateDir, "tombstone-blocked-capture", "fact-hashes.txt");
  }

  private rebuildMarkerPath(): string {
    return path.join(this.options.stateDir, "tombstone-blocked-capture", "rebuild-required");
  }

  private async readRebuildMarkers(): Promise<RebuildMarker[]> {
    try {
      const entries = (await readdir(this.rebuildMarkerPath())).filter((entry) => !entry.startsWith("."));
      return (
        await Promise.all(
          entries.map(async (entry) => {
            const markerPath = path.join(this.rebuildMarkerPath(), entry);
            try {
              const raw = (await readFile(markerPath, "utf8")).trim();
              if (raw === "committed") return { path: markerPath, committed: true };
              let value: Record<string, unknown>;
              let malformed = false;
              try {
                const parsed = JSON.parse(raw) as unknown;
                if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
                  malformed = true;
                  value = {};
                } else {
                  value = parsed as Record<string, unknown>;
                }
              } catch {
                malformed = true;
                value = {};
              }
              const state = value.state;
              if (state !== "pending" && state !== "committed") malformed = true;
              const markerStat = await stat(markerPath).catch(() => null);
              // A torn payload can lose its JSON metadata, but the atomic
              // marker filename and filesystem mtime still identify its owner
              // and age. Preserve both so stale malformed markers can be
              // reaped without treating a fresh pre-commit gap as abandoned.
              const createdAt =
                typeof value.createdAt === "number" && Number.isFinite(value.createdAt)
                  ? value.createdAt
                  : markerStat?.mtimeMs;
              if (typeof value.pid !== "number" || !Number.isInteger(value.pid)) malformed = true;
              const ownerId =
                typeof value.ownerId === "string" && value.ownerId.length > 0
                  ? value.ownerId
                  : path.basename(markerPath);
              if (typeof value.ownerId !== "string" || value.ownerId.length === 0) malformed = true;
              const processStartedAtMs =
                typeof value.processStartedAtMs === "number" &&
                Number.isFinite(value.processStartedAtMs) &&
                value.processStartedAtMs > 0
                  ? value.processStartedAtMs
                  : undefined;
              return {
                path: markerPath,
                committed: state === "committed",
                ...(typeof value.pid === "number" && Number.isInteger(value.pid) ? { pid: value.pid } : {}),
                ...(ownerId.length > 0 ? { ownerId } : {}),
                ...(typeof createdAt === "number" && Number.isFinite(createdAt) ? { createdAt } : {}),
                ...(processStartedAtMs === undefined ? {} : { processStartedAtMs }),
                ...(malformed ? { malformed: true } : {}),
              };
            } catch (err) {
              if (isErrnoCode(err, "ENOENT")) return null;
              throw err;
            }
          })
        )
      ).filter((marker): marker is RebuildMarker => marker !== null);
    } catch (err) {
      if (isErrnoCode(err, "ENOENT")) return [];
      throw err;
    }
  }
  private async isAbandonedMarker(marker: RebuildMarker): Promise<boolean> {
    if (marker.committed || marker.createdAt === undefined) return false;
    if (Date.now() - marker.createdAt < ABANDONED_MARKER_MIN_AGE_MS) return false;
    if (marker.malformed) return true;
    return marker.pid !== undefined && !(await this.isProcessAlive(marker.pid, marker.processStartedAtMs));
  }

  private async isProcessAlive(pid: number, processStartedAtMs?: number): Promise<boolean> {
    try {
      process.kill(pid, 0);
    } catch (err) {
      return !isErrnoCode(err, "ESRCH");
    }
    if (processStartedAtMs === undefined) return true;
    const runningStartedAtMs = await this.readProcessStartedAtMs(pid);
    if (runningStartedAtMs === null) return true;
    return runningStartedAtMs <= processStartedAtMs + MARKER_PROCESS_START_TOLERANCE_MS;
  }
  private async readProcessStartedAtMs(pid: number): Promise<number | null> {
    try {
      if (process.platform === "win32") {
        const { stdout } = await execFileAsync(
          "powershell.exe",
          [
            "-NoLogo",
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            `(Get-Process -Id ${pid} -ErrorAction Stop).StartTime.ToUniversalTime().Ticks`,
          ],
          { encoding: "utf8", timeout: 1_000 }
        );
        const ticks = Number(stdout.trim());
        return Number.isFinite(ticks) ? (ticks - DOTNET_UNIX_EPOCH_TICKS) / 10_000 : null;
      }
      const { stdout } = await execFileAsync("ps", ["-p", String(pid), "-o", "lstart="], {
        encoding: "utf8",
        timeout: 1_000,
      });
      const output = stdout.trim();
      if (!output) return null;
      const startedAtMs = Date.parse(output);
      return Number.isFinite(startedAtMs) ? startedAtMs : null;
    } catch {
      return null;
    }
  }

  private async getClearableRebuildMarkerPaths(markers: readonly RebuildMarker[]): Promise<string[]> {
    const paths = await Promise.all(
      markers.map(async (marker) => (marker.committed || (await this.isAbandonedMarker(marker)) ? marker.path : null))
    );
    return paths.filter((markerPath): markerPath is string => markerPath !== null);
  }

  private async getRebuildMarkers(): Promise<RebuildMarker[]> {
    return await this.readRebuildMarkers();
  }

  // A pending marker protects the pre-commit gap; only committed markers are safe for another writer to clear.
  private async writeMarkerAtomically(markerPath: string, payload: string): Promise<void> {
    const temporaryPath = `${markerPath}.tmp-${process.pid}-${randomUUID()}`;
    try {
      await writeFile(temporaryPath, payload, "utf8");
      await rename(temporaryPath, markerPath);
    } finally {
      await unlink(temporaryPath).catch((err: unknown) => {
        if (!isErrnoCode(err, "ENOENT")) throw err;
      });
    }
  }

  private async markRebuildRequired(committed = false): Promise<string> {
    const markerDir = this.rebuildMarkerPath();
    await mkdir(markerDir, { recursive: true });
    const ownerId = randomUUID();
    const markerPath = path.join(markerDir, ownerId);
    await this.writeMarkerAtomically(
      markerPath,
      `${JSON.stringify({
        state: committed ? "committed" : "pending",
        pid: process.pid,
        ownerId,
        createdAt: Date.now(),
        processStartedAtMs: MARKER_PROCESS_STARTED_AT_MS,
      })}\n`
    );
    return markerPath;
  }

  private async markRebuildCommitted(markerPath: string): Promise<void> {
    await this.writeMarkerAtomically(
      markerPath,
      `${JSON.stringify({
        state: "committed",
        pid: process.pid,
        ownerId: path.basename(markerPath),
        createdAt: Date.now(),
        processStartedAtMs: MARKER_PROCESS_STARTED_AT_MS,
      })}\n`
    );
  }

  private async clearRebuildRequired(markerPaths: readonly string[]): Promise<void> {
    await Promise.all(
      markerPaths.map(async (markerPath) => {
        try {
          await unlink(markerPath);
        } catch (err) {
          if (!isErrnoCode(err, "ENOENT")) throw err;
        }
      })
    );
  }

  private async hasRebuildRequired(excludedMarkers: readonly string[] = []): Promise<boolean> {
    const excluded = new Set(excludedMarkers);
    return (await this.getRebuildMarkers()).some((marker) => !excluded.has(marker.path));
  }

  private async setAuthoritative(rebuilt: boolean): Promise<void> {
    this.authoritative = rebuilt && !(await this.getRebuildMarkers()).some((marker) => !marker.committed);
  }
  private isBlocked(memory: MemoryFile): boolean {
    return memory.frontmatter.status === "pending_review" && Boolean(memory.frontmatter.blockedBy);
  }

  private async rebuild(index: ContentHashIndex): Promise<boolean> {
    return await index.rebuildUnderLock(async () => {
      index.clear();
      const existing = [...(await this.options.readAllMemories()), ...(await this.options.readAllColdMemories())];
      for (const memory of existing) {
        if (!this.isBlocked(memory)) continue;
        index.add(
          buildExplicitCaptureDedupKey(memory.content, memory.frontmatter.category, memory.frontmatter.sourceConnector)
        );
      }
    });
  }

  private async hasPersistedIndexOrMarkers(): Promise<boolean> {
    try {
      await stat(this.indexPath());
      return true;
    } catch (err) {
      if (!isErrnoCode(err, "ENOENT")) throw err;
      return (await this.readRebuildMarkers()).length > 0;
    }
  }

  private async getIndex(): Promise<ContentHashIndex> {
    if (this.index) return this.index;
    if (!this.loadPromise) {
      const index = this.createIndex();
      this.loadPromise = (async () => {
        await index.load();
        const rebuildMarkers = await this.getRebuildMarkers();
        const clearableRebuildMarkers = await this.getClearableRebuildMarkerPaths(rebuildMarkers);
        let persisted = !index.requiresFormatMigration;
        try {
          await stat(this.indexPath());
          if (rebuildMarkers.length > 0) persisted = false;
        } catch (err) {
          if (isErrnoCode(err, "ENOENT")) persisted = false;
          else throw err;
        }
        if (!persisted) {
          const lockOptions = this.options.lockOptions();
          const maxAttempts = lockOptions.retryMaxAttempts ?? REBUILD_MAX_ATTEMPTS;
          const baseMs = lockOptions.retryBaseMs ?? REBUILD_RETRY_BASE_MS;
          let rebuilt = false;
          for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
            rebuilt = await this.rebuild(index);
            if (rebuilt || attempt === maxAttempts - 1) break;
            const wait = Math.min(baseMs * 2 ** attempt, CONTENT_HASH_INDEX_RETRY_MAX_DELAY_MS);
            const delayState = Promise.withResolvers<void>();
            setTimeout(delayState.resolve, wait);
            await delayState.promise;
          }
          if (!rebuilt) {
            throw new Error("tombstone-blocked capture index rebuild lock unavailable");
          }
          await this.clearRebuildRequired(clearableRebuildMarkers);
        }
        await this.setAuthoritative(true);
        this.index = index;
        return index;
      })().catch((err) => {
        this.loadPromise = null;
        throw err;
      });
    }
    return this.loadPromise;
  }

  async withCaptureWriteLock<T>(task: () => Promise<T>, identity?: string | readonly string[]): Promise<T> {
    return await this.captureWriteLock.withCaptureWriteLock(task, identity);
  }

  async withCaptureWriteLockHashes<T>(task: () => Promise<T>, identityHashes: readonly string[]): Promise<T> {
    return await this.captureWriteLock.withCaptureWriteLockHashes(task, identityHashes);
  }
  async withCaptureWriteLockAndHashes<T>(
    task: () => Promise<T>,
    identity: string | readonly string[] | undefined,
    identityHashes: readonly string[]
  ): Promise<T> {
    return await this.captureWriteLock.withCaptureWriteLockAndHashes(task, identity, identityHashes);
  }

  private async reload(): Promise<ContentHashIndex> {
    if (!this.refreshPromise) {
      this.refreshPromise = (async () => {
        this.index = null;
        this.loadPromise = null;
        return await this.getIndex();
      })().finally(() => {
        this.refreshPromise = null;
      });
    }
    return this.refreshPromise;
  }

  /** Return blocked-row membership and authority from one index snapshot. */
  async check(
    content: string,
    category: string,
    sourceConnector?: string
  ): Promise<{ has: boolean; authoritative: boolean }> {
    const key = buildExplicitCaptureDedupKey(content, category, sourceConnector);
    let index = await this.getIndex();
    if ((await this.hasRebuildRequired()) || !(await index.isDiskFingerprintCurrent())) {
      index = await this.reload();
    }
    return { has: index.has(key), authoritative: this.authoritative };
  }

  /** Return whether a blocked row matches this explicit-capture identity. */
  async has(content: string, category: string, sourceConnector?: string): Promise<boolean> {
    return (await this.check(content, category, sourceConnector)).has;
  }

  /** Return whether the in-memory index is safe to answer an authoritative miss. */
  async isAuthoritative(): Promise<boolean> {
    const index = await this.getIndex();
    if ((await this.hasRebuildRequired()) || !(await index.isDiskFingerprintCurrent())) {
      await this.reload();
    }
    return this.authoritative;
  }

  /** Reserve durable rebuild intent before a blocked memory file is committed. */
  async prepareWrite(): Promise<string> {
    return this.markRebuildRequired();
  }

  /** Mark a prepared write committed once its memory file is durable. */
  async commitWrite(rebuildMarker: string): Promise<void> {
    await this.markRebuildCommitted(rebuildMarker);
  }

  /** Drop a pending marker when the protected memory write never commits. */
  async discardWrite(rebuildMarker: string): Promise<void> {
    await this.clearRebuildRequired([rebuildMarker]);
  }

  /** Add a newly persisted blocked row to the durable targeted index. */
  async add(memory: MemoryFile, rebuildMarker?: string): Promise<void> {
    if (!this.isBlocked(memory)) return;
    let index = await this.getIndex();
    if (
      (await this.hasRebuildRequired(rebuildMarker ? [rebuildMarker] : [])) ||
      !(await index.isDiskFingerprintCurrent())
    ) {
      index = await this.reload();
    }
    index.add(
      buildExplicitCaptureDedupKey(memory.content, memory.frontmatter.category, memory.frontmatter.sourceConnector)
    );
    const marker = rebuildMarker ?? (await this.markRebuildRequired(true));
    if (rebuildMarker) await this.markRebuildCommitted(rebuildMarker);
    await index.saveMergingWithDisk();
    await index.flushReconcileRetry();
    if (index.hasPendingChanges) {
      this.markUntrusted();
      return;
    }
    await this.clearRebuildRequired([marker]);
    await this.setAuthoritative(true);
  }

  /** Rebuild the index after a blocked row changes or is removed. */
  async rebuildIfLoaded(ownedMarker?: string): Promise<void> {
    const index = this.index ?? ((await this.hasPersistedIndexOrMarkers()) ? this.getIndex() : null);
    if (!index) return;
    const rebuildMarkers = await this.getRebuildMarkers();
    const rebuildMarker = await this.markRebuildRequired(true);
    const clearableRebuildMarkers = await this.getClearableRebuildMarkerPaths(rebuildMarkers);
    const rebuilt = await this.rebuild(await index);
    if (rebuilt) {
      await this.clearRebuildRequired([
        ...clearableRebuildMarkers,
        ...(ownedMarker === undefined || clearableRebuildMarkers.includes(ownedMarker) ? [] : [ownedMarker]),
        rebuildMarker,
      ]);
    }
    await this.setAuthoritative(rebuilt);
  }

  /** Rebuild when either side of a write is blocked and its identity changed. */
  async sync(before: MemoryFile, after: MemoryFile, rebuildMarker?: string): Promise<void> {
    const beforeBlocked = this.isBlocked(before);
    const afterBlocked = this.isBlocked(after);
    if (!beforeBlocked && !afterBlocked) return;
    const beforeKey = buildExplicitCaptureDedupKey(
      before.content,
      before.frontmatter.category,
      before.frontmatter.sourceConnector
    );
    const afterKey = buildExplicitCaptureDedupKey(
      after.content,
      after.frontmatter.category,
      after.frontmatter.sourceConnector
    );
    if (beforeBlocked && afterBlocked && beforeKey === afterKey) {
      if (rebuildMarker) {
        await this.markRebuildCommitted(rebuildMarker);
        await this.clearRebuildRequired([rebuildMarker]);
      }
      return;
    }
    const existingMarkers = await this.getRebuildMarkers();
    const marker = rebuildMarker ?? (await this.markRebuildRequired(true));
    const clearableExistingMarkers = await this.getClearableRebuildMarkerPaths(existingMarkers);
    if (rebuildMarker) await this.markRebuildCommitted(rebuildMarker);
    const rebuilt = await this.rebuild(await this.getIndex());
    if (rebuilt) {
      await this.clearRebuildRequired([...clearableExistingMarkers, marker]);
    }
    await this.setAuthoritative(rebuilt);
  }
  markUntrusted(): void {
    this.authoritative = false;
  }

  private async failOpen(operation: string, action: () => Promise<void>): Promise<void> {
    try {
      await action();
    } catch (err) {
      this.markUntrusted();
      log.warn(`storage.${operation} completed but failed to update tombstone-blocked capture index: ${err}`);
    }
  }

  async addWrittenMemory(
    pathname: string,
    frontmatter: MemoryFrontmatter,
    content: string,
    rebuildMarker?: string
  ): Promise<void> {
    await this.failOpen("writeMemory", () => this.add({ path: pathname, frontmatter, content }, rebuildMarker));
  }

  async rebuildAfterInvalidation(ownedMarker?: string): Promise<void> {
    await this.failOpen("invalidateMemory", () => this.rebuildIfLoaded(ownedMarker));
  }

  /**
   * Drop an already-committed write marker without re-reading the corpus. The
   * offline-sync mutation path commits its marker around the file write, then
   * must clear it even when the write cannot have changed the blocked key set
   * (neither side tombstone-blocked) — otherwise the marker lingers until some
   * later rebuild clears it. Mirrors the tail of `add`/`sync`.
   */
  async clearCommittedWriteMarker(rebuildMarker: string): Promise<void> {
    await this.clearRebuildRequired([rebuildMarker]);
    // getIndex() may have rebuilt while this marker was still pending and
    // left authoritative=false. After the marker is gone, restore authority
    // if no other uncommitted marker remains.
    await this.setAuthoritative(true);
  }

  async syncUpdatedMemory(
    before: MemoryFile,
    frontmatter: MemoryFrontmatter,
    content: string,
    rebuildMarker?: string
  ): Promise<void> {
    await this.failOpen("updateMemory", () => this.sync(before, { ...before, frontmatter, content }, rebuildMarker));
  }

  async syncUpdatedFrontmatter(
    before: MemoryFile,
    frontmatter: MemoryFrontmatter,
    rebuildMarker?: string
  ): Promise<void> {
    await this.failOpen("writeMemoryFrontmatter", () => this.sync(before, { ...before, frontmatter }, rebuildMarker));
  }
  shouldRebuildAfterInvalidationForPath(filePath: string): boolean {
    const relative = path.relative(path.resolve(this.options.memoryDir), path.resolve(filePath));
    const category = relative.split(path.sep)[0];
    return category === "cold" || RECALL_FALLBACK_DIRS.includes(category);
  }
}

import { AsyncLocalStorage } from "node:async_hooks";
import { createHash } from "node:crypto";
import { mkdir } from "node:fs/promises";
import path from "node:path";
import { raceAbort, throwIfAborted } from "../abort-error.js";
import {
  CAPTURE_WRITE_LOCK_BUSY_MESSAGE,
  type CaptureWriteLockLimitSource,
  captureWriteLockDelayMs,
  resolveCaptureWriteLockBackoffLimits,
} from "../capture-write-lock-backoff.js";
import { log } from "../logger.js";
import type { MemoryFile, MemoryFrontmatter } from "../types.js";
import { withHeldFileLock } from "../utils/serialize-mutations.js";
import { sleepAbortable } from "../utils/sleep.js";
import type { CasRevisionTransaction } from "./cas-revision-store.js";

export { isTombstoneBlockedCaptureWriteLockBusy } from "../capture-write-lock-backoff.js";

const TOMBSTONE_CAPTURE_WRITE_LOCK_STALE_MS = 60_000;
/**
 * One exclusive-create probe. The bounded wait lives in the outer backoff,
 * which runs only after every lock from this attempt has been released.
 * A multi-second poll here would hold an already-acquired sibling lock.
 */
const CAPTURE_WRITE_LOCK_PROBE_MS = 1;
const CAPTURE_WRITE_LOCK_RETRY = Symbol("capture-write-lock-retry");
const CAPTURE_WRITE_LOCK_PERMANENT = Symbol("capture-write-lock-permanent-failure");

export function normalizeExplicitCaptureContent(value: string): string {
  return value.toLowerCase().replace(/\s+/g, " ").trim();
}

export function buildExplicitCaptureDedupKey(
  content: string,
  category: string,
  sourceConnector: string | undefined
): string {
  const encode = (label: string, value: string): string => `${label} ${value.length} ${value}`;
  return [
    encode("category", category),
    encode("connector", sourceConnector?.trim() ?? ""),
    encode("content", normalizeExplicitCaptureContent(content)),
  ].join(" ");
}

export function buildCapturePathLockIdentity(pathname: string): string {
  return `path ${pathname.length} ${pathname}`;
}

export function captureIdentityHash(memory: MemoryFile): string {
  return createHash("sha256")
    .update(
      buildExplicitCaptureDedupKey(memory.content, memory.frontmatter.category, memory.frontmatter.sourceConnector)
    )
    .digest("hex");
}

export type TombstoneBlockedCaptureWriteLockOptions = {
  readonly stateDir: string;
  readonly withHeldFileLock?: typeof withHeldFileLock;
  /** Read when an acquire starts, after the caller has installed converge config. */
  readonly lockOptions?: () => CaptureWriteLockLimitSource | undefined;
  readonly now?: () => number;
  readonly random?: () => number;
  readonly sleep?: (ms: number, signal?: AbortSignal) => Promise<void>;
  readonly logDebug?: (message: string) => void;
  readonly logWarn?: (message: string) => void;
  /** Direct seam. Converge passes the same signal through `lockOptions` instead. */
  readonly signal?: AbortSignal;
};

export class TombstoneBlockedCaptureWriteLock {
  private readonly context = new AsyncLocalStorage<ReadonlySet<string>>();

  constructor(private readonly options: TombstoneBlockedCaptureWriteLockOptions) {}

  private captureWriteLockPathForHash(identityHash: string): string {
    const filename =
      identityHash.length === 0 ? "explicit-capture-write.lock" : `explicit-capture-write-${identityHash}.lock`;
    return path.join(this.options.stateDir, "tombstone-blocked-capture", filename);
  }

  private now(): number {
    return this.options.now?.() ?? Date.now();
  }

  private debug(message: string): void {
    if (this.options.logDebug) {
      this.options.logDebug(message);
      return;
    }
    log.debug(message);
  }

  private warn(message: string): void {
    if (this.options.logWarn) {
      this.options.logWarn(message);
      return;
    }
    log.warn(message);
  }

  /** Prefer the constructor seam; converge installs the signal on lock options at acquire time. */
  private captureAbortSignal(): AbortSignal | undefined {
    return this.options.signal ?? this.options.lockOptions?.()?.captureWriteLockSignal;
  }

  /**
   * One probe of a single lock file. Returns the retry symbol when the lock
   * is busy and the permanent symbol on a filesystem error. Does not sleep:
   * the caller backs off only after the whole chain has unwound.
   */
  private async withSingleCaptureWriteLockOnce<T>(
    lockPath: string,
    task: () => Promise<T | typeof CAPTURE_WRITE_LOCK_RETRY>
  ): Promise<T | typeof CAPTURE_WRITE_LOCK_RETRY | typeof CAPTURE_WRITE_LOCK_PERMANENT> {
    await mkdir(path.dirname(lockPath), { recursive: true });
    const runWithHeldFileLock = this.options.withHeldFileLock ?? withHeldFileLock;
    return await runWithHeldFileLock(
      lockPath,
      {
        staleMs: TOMBSTONE_CAPTURE_WRITE_LOCK_STALE_MS,
        maxWaitMs: CAPTURE_WRITE_LOCK_PROBE_MS,
        pollMs: CAPTURE_WRITE_LOCK_PROBE_MS,
      },
      async (acquired, controller) => {
        if (acquired) return await task();
        return controller.failure === "error" ? CAPTURE_WRITE_LOCK_PERMANENT : CAPTURE_WRITE_LOCK_RETRY;
      }
    );
  }

  private async withPhysicalCaptureWriteLocks<T>(
    task: () => Promise<T>,
    identityHashes: readonly string[]
  ): Promise<T> {
    const signal = this.captureAbortSignal();
    const lockPaths = [...new Set(identityHashes.map((hash) => this.captureWriteLockPathForHash(hash)))];
    const limits = resolveCaptureWriteLockBackoffLimits(this.options.lockOptions?.());
    const deadline = this.now() + limits.deadlineMs;
    const giveUp = (): never => {
      throwIfAborted(signal);
      this.warn(
        `tombstone-blocked capture write lock remained busy after ${limits.deadlineMs}ms; failing this write so the rest of the cycle can continue`
      );
      throw new Error(CAPTURE_WRITE_LOCK_BUSY_MESSAGE);
    };
    const acquire = async (
      index: number
    ): Promise<T | typeof CAPTURE_WRITE_LOCK_RETRY | typeof CAPTURE_WRITE_LOCK_PERMANENT> => {
      throwIfAborted(signal);
      // The deadline gates each probe: a chain that started before the
      // deadline must not keep probing locks (or run the write) after it.
      const runTask = async (): Promise<T> => {
        if (this.now() >= deadline) giveUp();
        return await task();
      };
      if (index === lockPaths.length) return await runTask();
      const lockPath = lockPaths[index];
      if (lockPath === undefined) return await runTask();
      if (this.now() >= deadline) giveUp();
      return await this.withSingleCaptureWriteLockOnce(lockPath, () => acquire(index + 1));
    };
    for (let attempt = 0; ; attempt += 1) {
      throwIfAborted(signal);
      const outcome = await acquire(0);
      if (outcome === CAPTURE_WRITE_LOCK_PERMANENT) {
        throw new Error("tombstone-blocked capture write lock acquisition failed");
      }
      if (outcome !== CAPTURE_WRITE_LOCK_RETRY) return outcome;
      throwIfAborted(signal);
      const now = this.now();
      if (now >= deadline) giveUp();
      const delay = Math.min(
        captureWriteLockDelayMs(attempt, limits, this.options.random ?? Math.random),
        deadline - now
      );
      if (delay <= 0) giveUp();
      this.debug(`tombstone-blocked capture write lock busy; backing off ${delay}ms before retry ${attempt + 1}`);
      // raceAbort covers seam sleeps that ignore the signal; the default
      // sleepAbortable also clears its timer so abort holds no Timeout.
      await raceAbort((this.options.sleep ?? sleepAbortable)(delay, signal), signal);
    }
  }

  async withCaptureWriteLock<T>(task: () => Promise<T>, identity?: string | readonly string[]): Promise<T> {
    const identities =
      Array.isArray(identity) && identity.length > 0 ? identity : [typeof identity === "string" ? identity : ""];
    return await this.withCaptureWriteLocks(task, identities, []);
  }

  async withCaptureWriteLockHashes<T>(task: () => Promise<T>, identityHashes: readonly string[]): Promise<T> {
    return await this.withCaptureWriteLocks(task, [], identityHashes);
  }

  async withCaptureWriteLockAndHashes<T>(
    task: () => Promise<T>,
    identity: string | readonly string[] | undefined,
    identityHashes: readonly string[]
  ): Promise<T> {
    const identities =
      Array.isArray(identity) && identity.length > 0 ? identity : [typeof identity === "string" ? identity : ""];
    return await this.withCaptureWriteLocks(task, identities, identityHashes);
  }

  private async withCaptureWriteLocks<T>(
    task: () => Promise<T>,
    identities: readonly string[],
    identityHashes: readonly string[]
  ): Promise<T> {
    throwIfAborted(this.captureAbortSignal());
    const current = this.context.getStore();
    const hashToken = (key: string): string =>
      `\u0000${key.length === 0 ? "" : createHash("sha256").update(key).digest("hex")}`;
    const identityHash = (key: string): string =>
      key.length === 0 ? "" : createHash("sha256").update(key).digest("hex");
    const identityKeys = [...new Set(identities)];
    const hashes = [...new Set(identityHashes)];
    const requested = [
      ...identityKeys
        .filter((key) => !current || (!current.has(key) && !current.has(hashToken(key))))
        .map((key) => ({ hash: identityHash(key), pathLock: key.startsWith("path ") })),
      ...hashes.filter((hash) => !current || !current.has(`\u0000${hash}`)).map((hash) => ({ hash, pathLock: false })),
    ]
      .filter((entry, index, entries) => entries.findIndex((candidate) => candidate.hash === entry.hash) === index)
      .sort(
        (left, right) =>
          Number(left.pathLock) - Number(right.pathLock) ||
          this.captureWriteLockPathForHash(left.hash).localeCompare(this.captureWriteLockPathForHash(right.hash))
      );
    const physicalMissing = requested.map((entry) => entry.hash);
    if (current && requested.length > 0) {
      const held = [...current]
        .filter((token) => token.startsWith("\u0000"))
        .map((token) => {
          const hash = token.slice(1);
          const pathLock = [...current].some(
            (key) => !key.startsWith("\u0000") && key.startsWith("path ") && hashToken(key) === token
          );
          return { hash, pathLock };
        });
      const requestedFirst = requested[0];
      const heldLast = held
        .sort(
          (left, right) =>
            Number(left.pathLock) - Number(right.pathLock) ||
            this.captureWriteLockPathForHash(left.hash).localeCompare(this.captureWriteLockPathForHash(right.hash))
        )
        .at(-1);
      if (
        heldLast &&
        requestedFirst &&
        (Number(requestedFirst.pathLock) < Number(heldLast.pathLock) ||
          (requestedFirst.pathLock === heldLast.pathLock &&
            this.captureWriteLockPathForHash(requestedFirst.hash) < this.captureWriteLockPathForHash(heldLast.hash)))
      ) {
        throw new Error(CAPTURE_WRITE_LOCK_BUSY_MESSAGE);
      }
    }
    const next = new Set(current);
    for (const key of identityKeys) {
      next.add(key);
      next.add(hashToken(key));
    }
    for (const hash of hashes) next.add(`\u0000${hash}`);
    const run = () => {
      throwIfAborted(this.captureAbortSignal());
      return this.context.run(next, task);
    };
    if (physicalMissing.length === 0) return await run();
    return await this.withPhysicalCaptureWriteLocks(run, physicalMissing);
  }
}

export type TombstoneBlockedMutationHost = {
  readCurrent: () => Promise<MemoryFile | null>;
  isBlocked: (memory: MemoryFile | null) => boolean;
  isQueuedReview: (memory: MemoryFile | null) => boolean;
  memoryIdentity: (memory: MemoryFile) => string;
  prepareWrite: () => Promise<string>;
  commitWrite: (marker: string) => Promise<void>;
  discardWrite: (marker: string) => Promise<void>;
  markUntrusted: () => void;
  writeStorageSecureFile: (pathname: string, fileContent: string) => Promise<void>;
  withCaptureWriteLock: (task: () => Promise<void>, identity: string | readonly string[]) => Promise<void>;
  logWarning: (message: string) => void;
  beginDurableMemoryRevision?: (
    pathname: string,
    expectedContent?: string | Buffer | null
  ) => Promise<CasRevisionTransaction | undefined>;
};

export type TombstoneBlockedMutation = {
  blocked: boolean;
  pathname: string;
  fileContent: string;
  identity: string | readonly string[];
  updateIndex: (rebuildMarker?: string, current?: MemoryFile | null) => Promise<void>;
  beforeIndexUpdate?: () => Promise<void>;
  coordinate?: boolean;
  shouldMintRevision?: (current: MemoryFile | null) => boolean;
};

export async function runTombstoneBlockedMutation(
  host: TombstoneBlockedMutationHost,
  mutation: TombstoneBlockedMutation
): Promise<string | undefined> {
  let lockIdentity: string | readonly string[] = mutation.identity;
  for (;;) {
    let retryIdentity: string | undefined;
    let mintedRevision: string | undefined;
    const mutate = async (): Promise<void> => {
      const current = await host.readCurrent();
      const currentBlocked = host.isBlocked(current);
      const currentQueuedReview = host.isQueuedReview(current);
      if (current !== null && (mutation.coordinate === true || currentBlocked || currentQueuedReview)) {
        const currentIdentity = host.memoryIdentity(current);
        const heldIdentities = Array.isArray(lockIdentity) ? lockIdentity : [lockIdentity];
        if (!heldIdentities.includes(currentIdentity)) {
          retryIdentity = currentIdentity;
          return;
        }
      }
      const rebuildMarker = mutation.blocked || currentBlocked ? await host.prepareWrite() : undefined;
      const discardRebuildMarker = async (): Promise<void> => {
        if (!rebuildMarker) return;
        try {
          await host.discardWrite(rebuildMarker);
        } catch (cleanupError) {
          host.markUntrusted();
          host.logWarning(`storage.tombstoneBlocked failed to clear write marker: ${cleanupError}`);
        }
      };
      let transaction: CasRevisionTransaction | undefined;
      try {
        // #2813 (P1 C): a two-phase receipt transaction under this same
        // path lock. The PENDING reservation is minted BEFORE the durable
        // file publish, so a failed reservation leaves the memory file
        // untouched — never a mutated record without a receipt. The
        // COMMITTED receipt publishes only AFTER the write lands, so a
        // failed write can never leave the reservation posing as
        // ownership.
        transaction = mutation.shouldMintRevision?.(current)
          ? await host.beginDurableMemoryRevision?.(mutation.pathname, mutation.fileContent)
          : undefined;
        await host.writeStorageSecureFile(mutation.pathname, mutation.fileContent);
      } catch (err) {
        // The memory write failed (or never ran): abort the reservation so
        // no pending marker survives a write that did not land. A failed
        // abort keeps the marker — ambiguity, recovered later.
        if (transaction) {
          try {
            await transaction.abort();
          } catch (abortError) {
            host.logWarning(
              `storage.tombstoneBlocked failed to abort the reserved receipt (pending marker preserved): ${abortError}`
            );
          }
        }
        await discardRebuildMarker();
        throw err;
      }
      if (transaction) {
        // #2807: record the post-write fingerprint in the PENDING marker
        // BEFORE publishing, so a crash between the durable write and the
        // COMMITTED receipt is decisively recoverable. The evidence only
        // guards that crash window — a recording failure must not fail the
        // landed write, so commit still runs and publishes truthfully.
        try {
          await transaction.writeLanded();
        } catch (evidenceError) {
          host.logWarning(
            `storage.tombstoneBlocked failed to record receipt crash evidence (pending marker preserved): ${evidenceError}`
          );
        }
        try {
          await transaction.commit();
        } catch (err) {
          // #2813 (P1 C): the memory file LANDED but the COMMITTED receipt
          // never published. The PENDING marker stays: readers must see
          // unavailable/recovery-needed — never ownership, never absence —
          // and promotion/rollback refuse until recovery reconciles. The
          // reservation must NOT be aborted: the write is on disk.
          host.logWarning(
            `storage.tombstoneBlocked receipt publication failed after the memory write (pending marker preserved for recovery): ${err}`
          );
          await discardRebuildMarker();
          throw err;
        }
      }
      mintedRevision = transaction?.pendingRevision;
      if (rebuildMarker) {
        try {
          await host.commitWrite(rebuildMarker);
        } catch (err) {
          host.markUntrusted();
          host.logWarning(`storage.tombstoneBlocked committed write marker failed: ${err}`);
        }
      }
      if (rebuildMarker) await mutation.beforeIndexUpdate?.();
      await mutation.updateIndex(rebuildMarker, currentBlocked && current !== null ? current : undefined);
    };

    await host.withCaptureWriteLock(mutate, lockIdentity);
    if (retryIdentity === undefined) return mintedRevision;
    const identities = Array.isArray(lockIdentity) ? [...lockIdentity, retryIdentity] : [lockIdentity, retryIdentity];
    lockIdentity = [...new Set(identities)];
  }
}

export function tombstoneBlocked(frontmatter: MemoryFrontmatter): boolean {
  return frontmatter.status === "pending_review" && Boolean(frontmatter.blockedBy);
}

export function isQueuedReviewFrontmatter(frontmatter: MemoryFrontmatter): boolean {
  return frontmatter.status === "pending_review" && (frontmatter.tags ?? []).includes("queued-review");
}

export function isQueuedReviewMemory(memory: MemoryFile | null): memory is MemoryFile {
  return memory !== null && isQueuedReviewFrontmatter(memory.frontmatter);
}

