export function normalizeIanaTimeZone(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const trimmed = value.trim();
  if (!trimmed) return undefined;
  try {
    Intl.DateTimeFormat(undefined, { timeZone: trimmed });
    return trimmed;
  } catch {
    return undefined;
  }
}

export function formatDateInTimeZone(date: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(date);
  const get = (type: string): string => parts.find((part) => part.type === type)?.value ?? "";
  return `${get("year")}-${get("month")}-${get("day")}`;
}

export function utcDateKey(date: Date): string {
  return date.toISOString().slice(0, 10);
}

export function utcDateKeysAround(date: Date): string[] {
  const dayMs = 86_400_000;
  const keys = [
    utcDateKey(new Date(date.getTime() - dayMs)),
    utcDateKey(date),
    utcDateKey(new Date(date.getTime() + dayMs)),
  ];
  return keys.filter((value, index, array) => array.indexOf(value) === index);
}

export function utcDateKeysForLocalDay(date: Date, timeZone: string): string[] {
  const targetLocalDate = formatDateInTimeZone(date, timeZone);
  const keys = new Set<string>();
  const hourMs = 3_600_000;
  const scanStart = date.getTime() - 48 * hourMs;
  const scanEnd = date.getTime() + 48 * hourMs;
  for (let ms = scanStart; ms <= scanEnd; ms += hourMs) {
    const candidate = new Date(ms);
    if (formatDateInTimeZone(candidate, timeZone) === targetLocalDate) {
      keys.add(utcDateKey(candidate));
    }
  }
  return keys.size > 0 ? [...keys].sort() : utcDateKeysAround(date);
}

export function parseFiniteDate(value: unknown): Date | null {
  if (typeof value !== "string" || value.trim().length === 0) return null;
  const parsed = new Date(value);
  return Number.isFinite(parsed.getTime()) ? parsed : null;
}

export function filterHourlySummaryMarkdownForLocalDay(
  raw: string,
  utcDate: string,
  timeZone: string,
  targetLocalDate: string,
): string | null {
  const hourHeaderPattern = /^## ([01]\d|2[0-3]):00[ \t]*$/gm;
  const matches = Array.from(raw.matchAll(hourHeaderPattern));
  if (matches.length === 0) return null;

  const firstSectionStart = matches[0]?.index ?? 0;
  const preamble = raw.slice(0, firstSectionStart).trim();
  const sections: string[] = [];
  for (let index = 0; index < matches.length; index += 1) {
    const match = matches[index];
    const hour = match[1];
    if (!hour) continue;
    const sectionTimestamp = parseFiniteDate(`${utcDate}T${hour}:00:00.000Z`);
    if (
      !sectionTimestamp ||
      formatDateInTimeZone(sectionTimestamp, timeZone) !== targetLocalDate
    ) {
      continue;
    }
    const sectionStart = match.index ?? 0;
    const sectionEnd = matches[index + 1]?.index ?? raw.length;
    const section = raw.slice(sectionStart, sectionEnd).trim();
    if (section.length > 0) sections.push(section);
  }

  if (sections.length === 0) return null;
  return [preamble, ...sections]
    .filter((section) => section.length > 0)
    .join("\n\n");
}

export type SearchCollectionState = "present" | "missing" | "unknown" | "skipped";

export function qmdStartupCollectionCheckTimeoutMs(): number {
  const raw =
    process.env.REMNIC_QMD_STARTUP_COLLECTION_CHECK_TIMEOUT_MS ??
    process.env.ENGRAM_QMD_STARTUP_COLLECTION_CHECK_TIMEOUT_MS;
  if (raw === undefined) return DEFAULT_QMD_STARTUP_COLLECTION_CHECK_TIMEOUT_MS;
  const parsed = Number(raw);
  return Number.isFinite(parsed) && parsed >= 1_000
    ? Math.floor(parsed)
    : DEFAULT_QMD_STARTUP_COLLECTION_CHECK_TIMEOUT_MS;
}

export async function qmdStartupCollectionCheckWithTimeout(
  promise: Promise<SearchCollectionState>,
  controller: AbortController,
  label: string,
): Promise<SearchCollectionState> {
  const timeoutMs = qmdStartupCollectionCheckTimeoutMs();
  let timer: NodeJS.Timeout | undefined;
  let settled = false;

  const timeoutPromise = new Promise<SearchCollectionState>((resolve) => {
    timer = setTimeout(() => {
      if (settled) return;
      controller.abort();
      log.warn(
        `QMD startup collection check for ${label} timed out after ${timeoutMs}ms; keeping search enabled fail-open`,
      );
      resolve("unknown");
    }, timeoutMs);
    timer.unref?.();
  });

  const checkedPromise = promise
    .catch((err): SearchCollectionState => {
      log.warn(
        `QMD startup collection check for ${label} failed; keeping search enabled fail-open: ${err}`,
      );
      return "unknown";
    })
    .finally(() => {
      settled = true;
      if (timer) clearTimeout(timer);
    });

  return await Promise.race([checkedPromise, timeoutPromise]);
}

/** Default workspace directory when no per-agent or config workspace is available. */
export function defaultWorkspaceDir(): string {
  return path.join(os.homedir(), ".openclaw", "workspace");
}

/**
 * Produce a collision-resistant, filesystem-safe identifier from a session key.
 *
 * Session keys follow colon-delimited forms (e.g., `agent:gpucodebot:main`).
 * A naive replace (`:` → `_`) is lossy: different keys like `agent:alpha` and
 * `agent/alpha` would collide. Instead we append a short SHA-256 hash of the
 * original key to the human-readable sanitized prefix, guaranteeing uniqueness
 * while keeping filenames debuggable.
 *
 * Format: `<sanitized>-<12-char-hex-hash>`
 * Example: `agent:gpucodebot:main` → `agent_gpucodebot_main-a1b2c3d4e5f6`
 */
export function sanitizeSessionKeyForFilename(sessionKey: string): string {
  const readable = sessionKey.replace(/[^a-zA-Z0-9._-]/g, "_");
  const hash = createHash("sha256")
    .update(sessionKey)
    .digest("hex")
    .slice(0, 12);
  return `${readable}-${hash}`;
}

export function sourceValidAtMs(turn: BufferTurn): number | null {
  if (typeof turn.sourceValidAt !== "string") return null;
  return parseFlexibleIsoTimestamp(turn.sourceValidAt.trim());
}

export const SOURCE_VALID_AT_CONTEXT_TURNS = 2;

export function sourceValidAtSliceKey(turn: BufferTurn, index: number): string {
  const validAtMs = sourceValidAtMs(turn);
  return validAtMs === null ? `unknown:${index}` : String(validAtMs);
}

export function asExtractionContextTurn(turn: BufferTurn): BufferTurn {
  return { ...turn, extractionContextOnly: true };
}

export function asExtractionTargetTurn(turn: BufferTurn): BufferTurn {
  const { extractionContextOnly: _contextOnly, ...targetTurn } = turn;
  return targetTurn;
}

export function sourceValidAtContextTurns(
  turns: readonly BufferTurn[],
  targetStart: number,
  targetEnd: number,
  targetValidAtMs: number | null,
): BufferTurn[] {
  if (targetValidAtMs === null) return [];
  return turns
    .flatMap((turn, index) => {
      if (index >= targetStart && index < targetEnd) return [];
      const contextValidAtMs = sourceValidAtMs(turn);
      if (contextValidAtMs === null || contextValidAtMs > targetValidAtMs) {
        return [];
      }
      return [{ turn, index, validAtMs: contextValidAtMs }];
    })
    .sort((a, b) => {
      if (a.validAtMs < b.validAtMs) return -1;
      if (a.validAtMs > b.validAtMs) return 1;
      if (a.index === b.index) return 0;
      return a.index < b.index ? -1 : 1;
    })
    .slice(-SOURCE_VALID_AT_CONTEXT_TURNS)
    .map(({ turn }) => asExtractionContextTurn(turn));
}

export function targetSourceValidAtSortMs(turns: readonly BufferTurn[]): number {
  let latestMs: number | null = null;
  for (const turn of turns) {
    if (turn.extractionContextOnly === true) continue;
    const validAtMs = sourceValidAtMs(turn);
    if (validAtMs === null) continue;
    if (latestMs === null || validAtMs > latestMs) {
      latestMs = validAtMs;
    }
  }
  return latestMs ?? Number.POSITIVE_INFINITY;
}

export function sortSourceValidAtSlicesChronologically(
  slices: BufferTurn[][],
): BufferTurn[][] {
  return slices
    .map((turns, order) => ({
      turns,
      order,
      targetValidAtMs: targetSourceValidAtSortMs(turns),
    }))
    .sort((a, b) => {
      if (a.targetValidAtMs < b.targetValidAtMs) return -1;
      if (a.targetValidAtMs > b.targetValidAtMs) return 1;
      if (a.order === b.order) return 0;
      return a.order < b.order ? -1 : 1;
    })
    .map((slice) => slice.turns);
}

export function splitTurnsBySourceValidAt(
  turns: readonly BufferTurn[],
  options: { includeContext?: boolean } = {},
): BufferTurn[][] {
  if (turns.length === 0) return [];
  if (!turns.some((turn) => sourceValidAtMs(turn) !== null)) {
    return [[...turns]];
  }

  const slices: BufferTurn[][] = [];
  let start = 0;
  while (start < turns.length) {
    const targetValidAtMs = sourceValidAtMs(turns[start]);
    const activeKey = sourceValidAtSliceKey(turns[start], start);
    let end = start + 1;
    while (
      end < turns.length &&
      sourceValidAtSliceKey(turns[end], end) === activeKey
    ) {
      end += 1;
    }

    const contextTurns =
      options.includeContext === false
        ? []
        : sourceValidAtContextTurns(turns, start, end, targetValidAtMs);
    slices.push([
      ...contextTurns,
      ...turns.slice(start, end).map(asExtractionTargetTurn),
    ]);
    start = end;
  }
  return sortSourceValidAtSlicesChronologically(slices);
}

export function isArtifactMemoryPath(filePath: string): boolean {
  return /(?:^|[\\/])artifacts(?:[\\/]|$)/i.test(filePath);
}

/**
 * Meeting records (issue #1900) live at
 * `<root>/meetings/<YYYY-MM-DD>/mtg-<YYYY-MM-DD>-<hash>.md` — inside the QMD
 * collection root (full-text searchable) but NEVER surfaced through generic
 * recall, exactly like `artifacts/`. The predicate matches the FULL record
 * shape (anchored at the filename) rather than any `meetings` path segment, so
 * a namespaced deployment whose non-default namespace is literally named
 * `meetings` (`.../namespaces/meetings/facts/…`) keeps its ordinary memories in
 * recall — only true meeting records are excluded.
 */
export function isMeetingRecordPath(filePath: string): boolean {
  return /(?:^|[\\/])meetings[\\/]\d{4}-\d{2}-\d{2}[\\/]mtg-\d{4}-\d{2}-\d{2}-[0-9a-f]{8}\.md$/i.test(filePath);
}

/** Exactly `activity/<YYYY-MM-DD>.md`, at the top level of a memory root. */
const ACTIVITY_DIGEST_TOPLEVEL = /^activity[\\/]\d{4}-\d{2}-\d{2}\.md$/i;
/** The digest FILE shape anywhere in a path (root-unaware best-effort). */
const ACTIVITY_DIGEST_ANYWHERE = /(?:^|[\\/])activity[\\/]\d{4}-\d{2}-\d{2}\.md$/i;

/**
 * Activity day-digests live at `<memoryRoot>/activity/<YYYY-MM-DD>.md` — a
 * dedicated searchable surface (explicit activity search), never generic recall.
 * Captured screen text must not auto-inject into ordinary prompts (issue #1899).
 * Keyed on the path (parseFrontmatter drops the digest's `kind` marker).
 *
 * Root-aware: when `memoryRoot` is given, the path is resolved relative to it and
 * must be the TOP-LEVEL `activity/<date>.md`, so an ordinary memory nested under
 * a category (e.g. `facts/proj/activity/<date>.md`) stays recallable. Without a
 * root, falls back to the digest file shape anywhere (best-effort).
 */
export function isActivityDigestPath(filePath: string, memoryRoot?: string): boolean {
  if (memoryRoot !== undefined && memoryRoot.length > 0) {
    const relative = path.relative(memoryRoot, path.resolve(memoryRoot, filePath));
    return ACTIVITY_DIGEST_TOPLEVEL.test(relative);
  }
  return ACTIVITY_DIGEST_ANYWHERE.test(filePath);
}

/** Exactly `locations/<YYYY-MM-DD>.md`, at the top level of a memory root. */
const LOCATION_DAY_TOPLEVEL = /^locations[\\/]\d{4}-\d{2}-\d{2}\.md$/i;
/** The day-file shape anywhere in a path (root-unaware best-effort). */
const LOCATION_DAY_ANYWHERE = /(?:^|[\\/])locations[\\/]\d{4}-\d{2}-\d{2}\.md$/i;

/**
 * Location day documents (issue #2044) live at
 * `<memoryRoot>/locations/<YYYY-MM-DD>.md` — a dedicated searchable surface,
 * never generic recall (place history must not auto-inject into ordinary
 * prompts). Root-aware exactly like `isActivityDigestPath`: with a root, only
 * the top-level `locations/<date>.md` matches, so an ordinary memory nested
 * under a category (e.g. `facts/locations-note.md`) stays recallable; without
 * a root, falls back to the day-file shape anywhere (best-effort).
 */
export function isLocationDayPath(filePath: string, memoryRoot?: string): boolean {
  if (memoryRoot !== undefined && memoryRoot.length > 0) {
    const relative = path.relative(memoryRoot, path.resolve(memoryRoot, filePath));
    return LOCATION_DAY_TOPLEVEL.test(relative);
  }
  return LOCATION_DAY_ANYWHERE.test(filePath);
}

export function buildCompressionGuidelinesMarkdown(
  events: MemoryActionEvent[],
  generatedAtIso: string = new Date().toISOString(),
): string {
  return buildCompressionGuidelinesMarkdownV2(events, generatedAtIso);
}

export function applyQueryAwareCandidateFilter(
  candidates: QmdSearchResult[],
  candidatePaths: Set<string> | null,
): QmdSearchResult[] {
  if (!candidatePaths) return candidates;
  if (candidatePaths.size === 0) return [];
  const filtered = candidates.filter((candidate) =>
    candidatePaths.has(candidate.path),
  );
  return filtered.length > 0 ? filtered : candidates;
}

export function tokenizeRecallQuery(prompt: string): string[] {
  return prompt
    .toLowerCase()
    .split(/[^a-z0-9]+/i)
    .map((t) => t.trim())
    .filter((t) => t.length >= 3);
}

export function hasLifecycleMetadata(frontmatter: MemoryFrontmatter): boolean {
  return (
    frontmatter.lifecycleState !== undefined ||
    frontmatter.verificationState !== undefined ||
    frontmatter.policyClass !== undefined ||
    frontmatter.lastValidatedAt !== undefined ||
    frontmatter.decayScore !== undefined ||
    frontmatter.heatScore !== undefined
  );
}

export function shouldFilterLifecycleRecallCandidate(
  frontmatter: MemoryFrontmatter,
  options: {
    lifecyclePolicyEnabled: boolean;
    lifecycleFilterStaleEnabled: boolean;
  },
): boolean {
  if (!options.lifecyclePolicyEnabled || !options.lifecycleFilterStaleEnabled)
    return false;
  if (!hasLifecycleMetadata(frontmatter)) return false;
  const lifecycleState = resolveLifecycleState(frontmatter);
  return lifecycleState === "stale" || lifecycleState === "archived";
}

export function lifecycleRecallScoreAdjustment(
  frontmatter: MemoryFrontmatter,
  options: {
    lifecyclePolicyEnabled: boolean;
  },
): number {
  if (!options.lifecyclePolicyEnabled) return 0;
  if (!hasLifecycleMetadata(frontmatter)) return 0;

  let delta = 0;
  const lifecycleState = resolveLifecycleState(frontmatter);
  switch (lifecycleState) {
    case "active":
      delta += 0.05;
      break;
    case "validated":
      delta += 0.03;
      break;
    case "candidate":
      delta -= 0.01;
      break;
    case "stale":
      delta -= 0.06;
      break;
    case "archived":
      delta -= 0.08;
      break;
  }
  if (frontmatter.verificationState === "disputed") {
    delta -= 0.12;
  }
  return delta;
}

export function computeArtifactRecallLimit(
  recallMode: RecallPlanMode,
  recallResultLimit: number,
  verbatimArtifactsMaxRecall: number,
): number {
  if (recallMode === "no_recall") return 0;
  if (Math.max(0, recallResultLimit) === 0) return 0;
  const base = Math.max(0, verbatimArtifactsMaxRecall);
  if (recallMode === "minimal") {
    return Math.min(base, Math.max(0, recallResultLimit));
  }
  return base;
}

export function resolveEffectiveRecallMode(options: {
  plannerEnabled: boolean;
  graphRecallEnabled: boolean;
  multiGraphMemoryEnabled: boolean;
  graphExpandedIntentEnabled?: boolean;
  prompt: string;
}): RecallPlanMode {
  return resolveRecallModeDecision(options).effectiveMode;
}

export interface RecallModeGraphOptions {
  plannerEnabled: boolean;
  graphRecallEnabled: boolean;
  multiGraphMemoryEnabled: boolean;
  graphExpandedIntentEnabled?: boolean;
  prompt: string;
}

/**
 * Apply the graph-mode overlay + gating to a planner-produced mode.
 *
 * Shared by the heuristic ({@link resolveRecallModeDecision}) and LLM
 * ({@link resolveRecallModeDecisionAsync}) paths so graph promotion and the
 * "graph disabled → fall back to full" gating behave identically regardless of
 * which planner produced `plannedModeRaw` (gotcha #39).
 */
export function finalizeRecallModeDecision(
  plannedModeRaw: RecallPlanMode,
  options: RecallModeGraphOptions,
): RecallModeDecision {
  let plannedMode: RecallPlanMode = plannedModeRaw;
  const graphExpandedIntentDetected =
    options.plannerEnabled &&
    options.graphExpandedIntentEnabled === true &&
    hasBroadGraphIntent(options.prompt);
  if (plannedMode !== "graph_mode" && graphExpandedIntentDetected) {
    plannedMode = "graph_mode";
  }
  if (
    plannedMode === "graph_mode" &&
    (!options.graphRecallEnabled || !options.multiGraphMemoryEnabled)
  ) {
    return {
      plannedMode,
      effectiveMode: "full",
      graphExpandedIntentDetected,
      graphReason: !options.graphRecallEnabled
        ? "graph recall disabled by config"
        : "multi-graph memory disabled by config",
    };
  }
  return {
    plannedMode,
    effectiveMode: plannedMode,
    graphExpandedIntentDetected,
  };
}

export function resolveRecallModeDecision(options: RecallModeGraphOptions): RecallModeDecision {
  const plannedMode: RecallPlanMode = options.plannerEnabled
    ? planRecallMode(options.prompt)
    : "full";
  return finalizeRecallModeDecision(plannedMode, options);
}

/**
 * Async recall-mode decision with optional LLM-based planning (issue #1367 /
 * Option C). Falls back to the heuristic decision when the LLM planner is
 * disabled, in shadow mode, or unavailable/failed — so this is always safe to
 * await on the recall hot path. Provider-agnostic: the LLM call routes through
 * the gateway/fallback chain.
 *
 * `recallPlannerEnabled === false` keeps the legacy "always full" behavior and
 * skips the LLM entirely (the planner as a whole is off).
 */
export async function resolveRecallModeDecisionAsync(
  options: RecallModeGraphOptions & {
    config: PluginConfig;
    /**
     * Recall-operation capability gates (issue #1523). REQUIRED: the recall
     * orchestrator always passes a resolved set — the LLM planner gate reads
     * `caps.recallPlannerLlm`, never re-derives from config.
     */
    caps: CapabilitySet;
    hints?: string[];
    llm?: FallbackLlmClient;
    signal?: AbortSignal;
  },
): Promise<RecallModeDecision> {
  const heuristicDecision = resolveRecallModeDecision(options);

  // Planner globally off, or LLM planning not opted into → heuristic only.
  // Read the resolved capability (issue #1523) — never re-derive from config.
  const plannerLlmEnabled = options.caps.recallPlannerLlm;
  if (!options.plannerEnabled || !plannerLlmEnabled) {
    return heuristicDecision;
  }

  const { planRecallModeLLM } = await import("../recall-planner-llm.js");
  const planned = await planRecallModeLLM(
    options.prompt,
    options.hints,
    options.config,
    options.caps,
    options.llm,
    options.signal,
  );

  // Shadow mode: record what the LLM would have chosen but keep the heuristic
  // effective decision (safe rollout / comparison — gotcha #30).
  if (options.config.recallPlannerShadowMode) {
    return {
      ...heuristicDecision,
      plannerSource: planned.source,
      plannerReason: `shadow:${planned.reason}`,
      plannerLatencyMs: planned.latencyMs,
      plannerFallbackUsed: planned.fallbackUsed,
      plannerModelUsed: planned.modelUsed,
      plannerHeuristicMode: planned.heuristicMode,
      shadowLlmMode: planned.mode,
    };
  }

  const llmDecision = finalizeRecallModeDecision(planned.mode, options);
  return {
    ...llmDecision,
    plannerSource: planned.source,
    plannerReason: planned.reason,
    plannerLatencyMs: planned.latencyMs,
    plannerFallbackUsed: planned.fallbackUsed,
    plannerModelUsed: planned.modelUsed,
    plannerHeuristicMode: planned.heuristicMode,
  };
}

export function computeArtifactCandidateFetchLimit(
  targetCount: number,
): number {
  const cappedTarget = Math.max(0, targetCount);
  if (cappedTarget === 0) return 0;
  const headroom = Math.max(8, cappedTarget * 4);
  return Math.min(200, cappedTarget + headroom);
}

export function computeQmdHybridFetchLimit(
  recallFetchLimit: number,
  artifactsEnabled: boolean,
  maxArtifactRecall: number,
): number {
  const cappedRecallLimit = Math.max(0, recallFetchLimit);
  if (cappedRecallLimit === 0) return 0;
  if (!artifactsEnabled) return cappedRecallLimit;
  // Overscan when artifacts are enabled, then filter artifact paths before
  // re-applying the recall cap to avoid artifact-dominated top-N starvation.
  const artifactHeadroom = Math.max(20, Math.max(0, maxArtifactRecall) * 8);
  return Math.min(400, cappedRecallLimit + artifactHeadroom);
}

export function summarizeGraphShadowComparison(
  baseline: QmdSearchResult[],
  merged: QmdSearchResult[],
  topN: number,
): {
  baselineCount: number;
  graphCount: number;
  overlapCount: number;
  overlapRatio: number;
  averageOverlapDelta: number;
} {
  const limit = Math.max(0, Math.floor(topN));
  const baselineTop = limit > 0 ? baseline.slice(0, limit) : [];
  const graphTop = limit > 0 ? merged.slice(0, limit) : [];
  const baselineByPath = new Map(
    baselineTop.map((item) => [item.path, item.score]),
  );
  const graphByPath = new Map(graphTop.map((item) => [item.path, item.score]));

  let overlapCount = 0;
  let overlapDeltaSum = 0;
  for (const [p, baselineScore] of baselineByPath.entries()) {
    const graphScore = graphByPath.get(p);
    if (typeof graphScore !== "number") continue;
    overlapCount += 1;
    overlapDeltaSum += graphScore - baselineScore;
  }

  const baselineCount = baselineTop.length;
  return {
    baselineCount,
    graphCount: graphTop.length,
    overlapCount,
    overlapRatio: baselineCount > 0 ? overlapCount / baselineCount : 0,
    averageOverlapDelta: overlapCount > 0 ? overlapDeltaSum / overlapCount : 0,
  };
}

export function parseGraphRecallRankedResults(
  value: unknown,
): GraphRecallRankedResult[] {
  if (!Array.isArray(value)) return [];
  const parsed: GraphRecallRankedResult[] = [];
  for (const entry of value) {
    if (!entry || typeof entry !== "object") continue;
    const candidate = entry as Partial<GraphRecallRankedResult>;
    if (
      typeof candidate.path !== "string" ||
      typeof candidate.score !== "number"
    )
      continue;
    parsed.push({
      path: candidate.path,
      score: candidate.score,
      docid: typeof candidate.docid === "string" ? candidate.docid : undefined,
      sourceLabels: Array.isArray(candidate.sourceLabels)
        ? candidate.sourceLabels.filter(
            (item): item is string => typeof item === "string",
          )
        : [],
    });
  }
  return parsed.slice(0, 64);
}

export function parseMemoryIntentSnapshot(value: unknown): MemoryIntent {
  const candidate =
    value && typeof value === "object" ? (value as Partial<MemoryIntent>) : {};
  return {
    goal: typeof candidate.goal === "string" ? candidate.goal : "unknown",
    actionType:
      typeof candidate.actionType === "string"
        ? candidate.actionType
        : "unknown",
    entityTypes: Array.isArray(candidate.entityTypes)
      ? candidate.entityTypes.filter(
          (item): item is string => typeof item === "string",
        )
      : [],
    taskInitiation: candidate.taskInitiation === true,
  };
}

export function buildQmdIntentHint(intent: MemoryIntent): string | undefined {
  const parts: string[] = [];
  if (intent.goal !== "unknown") {
    parts.push(`goal:${intent.goal.replace(/_/g, " ")}`);
  }
  if (intent.actionType !== "unknown") {
    parts.push(`action:${intent.actionType.replace(/_/g, " ")}`);
  }
  if (intent.entityTypes.length > 0) {
    parts.push(`entities:${intent.entityTypes.join(",")}`);
  }
  if (intent.taskInitiation === true) {
    parts.push("task_initiation");
  }
  return parts.length > 0 ? parts.join(" ") : undefined;
}

export function parseQmdRecallResults(value: unknown): QmdSearchResult[] {
  if (!Array.isArray(value)) return [];
  const parsed: QmdSearchResult[] = [];
  for (const entry of value) {
    if (!entry || typeof entry !== "object") continue;
    const candidate = entry as Partial<QmdSearchResult>;
    if (
      typeof candidate.path !== "string" ||
      typeof candidate.score !== "number"
    )
      continue;
    parsed.push({
      docid: typeof candidate.docid === "string" ? candidate.docid : "",
      path: candidate.path,
      snippet: typeof candidate.snippet === "string" ? candidate.snippet : "",
      score: candidate.score,
      explain: parseQmdExplain(candidate.explain),
      transport:
        candidate.transport === "daemon" ||
        candidate.transport === "subprocess" ||
        candidate.transport === "hybrid" ||
        candidate.transport === "scoped_prefilter"
          ? candidate.transport
          : undefined,
    });
  }
  return parsed.slice(0, 32);
}

export function mergeArtifactRecallCandidates(
  candidatesByNamespace: MemoryFile[][],
  limit: number,
): MemoryFile[] {
  const cappedLimit = Math.max(0, limit);
  if (cappedLimit === 0) return [];

  const out: MemoryFile[] = [];
  const seen = new Set<string>();
  let offset = 0;
  while (out.length < cappedLimit) {
    let hasAnyCandidateAtOffset = false;
    for (const list of candidatesByNamespace) {
      if (offset >= list.length) continue;
      hasAnyCandidateAtOffset = true;
      const item = list[offset];
      const dedupeKey = `${item.frontmatter.id}:${item.frontmatter.sourceMemoryId ?? ""}:${item.content}`;
      if (seen.has(dedupeKey)) continue;
      seen.add(dedupeKey);
      out.push(item);
      if (out.length >= cappedLimit) break;
    }
    if (!hasAnyCandidateAtOffset) break;
    offset += 1;
  }
  return out;
}

export function resolveRecentThreadMemoryPaths(options: {
  threadEpisodeIds: string[];
  currentMemoryId: string;
  allMemsForGraph: MemoryFile[] | null | undefined;
  pathById?: Map<string, string>;
  storageDir: string;
  maxRecent: number;
}): string[] {
  const maxRecent = Math.max(0, options.maxRecent);
  if (options.threadEpisodeIds.length === 0 || maxRecent === 0) return [];
  const pathById =
    options.pathById ??
    buildMemoryPathById(options.allMemsForGraph, options.storageDir);
  if (pathById.size === 0) return [];

  // #1635 (defensive): skip pending_review ids from legacy episode sets.
  const pendingReviewIds = new Set<string>(
    (options.allMemsForGraph ?? [])
      .filter((m) => m.frontmatter.status === "pending_review" && m.frontmatter.id)
      .map((m) => m.frontmatter.id as string),
  );

  return options.threadEpisodeIds
    .filter((id) => id !== options.currentMemoryId)
    .filter((id) => !pendingReviewIds.has(id))
    .slice(-maxRecent)
    .map((id) => pathById.get(id))
    .filter((p): p is string => typeof p === "string" && p.length > 0);
}

export function buildMemoryPathById(
  allMemsForGraph: MemoryFile[] | null | undefined,
  storageDir: string,
): Map<string, string> {
  const pathById = new Map<string, string>();
  for (const mem of allMemsForGraph ?? []) {
    const id = mem.frontmatter.id;
    if (!id) continue;
    pathById.set(id, path.relative(storageDir, mem.path));
  }
  return pathById;
}

export function appendMemoryToGraphContext(options: {
  allMemsForGraph: MemoryFile[] | null | undefined;
  storageDir: string;
  memoryRelPath: string;
  memoryId: string;
  category: MemoryFile["frontmatter"]["category"];
  content: string;
  entityRef: string | undefined;
}): void {
  if (!Array.isArray(options.allMemsForGraph)) return;

  const nowIso = new Date().toISOString();
  options.allMemsForGraph.push({
    path: path.join(options.storageDir, options.memoryRelPath),
    content: options.content,
    frontmatter: {
      id: options.memoryId,
      category: options.category,
      created: nowIso,
      updated: nowIso,
      source: "extraction",
      confidence: 0.8,
      confidenceTier: "implied",
      tags: [],
      entityRef: options.entityRef,
      status: "active",
    },
  });
}

export function resolvePersistedMemoryRelativePath(options: {
  memoryId: string;
  pathById: Map<string, string>;
  category: string;
}): string {
  const persisted = options.pathById.get(options.memoryId);
  if (persisted) return persisted;
  if (options.category === "correction") {
    return path.join("corrections", `${options.memoryId}.md`);
  }
  // Pick the subtree that matches the StorageManager.writeMemory routing
  // so fallback paths (used before memoryPathById has seen the fresh
  // write) agree with where the file actually lives. Routing goes through
  // the shared categoryDirName() chokepoint (utils/category-dir.ts) so
  // every category — decisions/, preferences/, reasoning-traces/, ... —
  // resolves to the same dir the writer used; otherwise graph edges point
  // at the wrong subtree and graph expansion silently drops those nodes
  // when readMemoryByPath cannot resolve them (issue #564 PR 3 / #1546).
  const subtree = categoryDirName(options.category);
  const idParts = options.memoryId.split("-");
  const maybeTimestamp = Number(idParts[1]);
  if (Number.isFinite(maybeTimestamp) && maybeTimestamp > 0) {
    const day = new Date(maybeTimestamp).toISOString().slice(0, 10);
    return path.join(subtree, day, `${options.memoryId}.md`);
  }
  return path.join(subtree, `${options.memoryId}.md`);
}

import type { BufferTurn, ExtractionFailureClass, ExtractionResult, MetaState } from "../types.js";
import type { StorageManager } from "../index.js";
import { log } from "../logger.js";
import type { ExtractionRunResult } from "./extraction-run.js";

export function combineExtractionAbortSignals(
  primary: AbortSignal | undefined,
  deadlineController: AbortController | undefined,
): AbortSignal | undefined {
  if (!deadlineController) return primary;
  return primary ? AbortSignal.any([primary, deadlineController.signal]) : deadlineController.signal;
}


/** Result of a run whose extraction found nothing durable; `retained` marks a recorded failure that left the window in the buffer. */
export function emptyExtractionResult(retained: boolean, failureClass?: ExtractionFailureClass): ExtractionRunResult {
  const result: ExtractionRunResult = { status: "skipped", reason: "empty_extraction_result", persistedCount: 0, durableOutputCount: 0 };
  if (retained) Object.assign(result, { retainedBuffer: true, failureClass: failureClass ?? "provider_retryable" }); // same default as the retry bookkeeping
  return result;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

export function deriveTopicsFromExtraction(result: ExtractionResult): string[] {
  if (!isRecord(result)) return [];
  const topics = new Set<string>();
  const facts = Array.isArray(result.facts) ? result.facts : [];
  for (const rawFact of facts) {
    if (!isRecord(rawFact)) continue;
    const tags = Array.isArray(rawFact.tags) ? rawFact.tags : [];
    for (const tag of tags) {
      if (typeof tag === "string" && tag.length >= 2) topics.add(tag.toLowerCase());
    }
    if (typeof rawFact.entityRef === "string" && rawFact.entityRef.length >= 2) {
      topics.add(rawFact.entityRef.toLowerCase());
    }
    if (typeof rawFact.category === "string" && rawFact.category.length > 0) {
      topics.add(rawFact.category);
    }
  }
  const entities = Array.isArray(result.entities) ? result.entities : [];
  for (const rawEntity of entities) {
    if (!isRecord(rawEntity)) continue;
    if (typeof rawEntity.name === "string" && rawEntity.name.length >= 2) {
      topics.add(rawEntity.name.toLowerCase());
    }
  }
  return [...topics].slice(0, 16);
}

/** Bounded cap on persisted per-fingerprint retry-state entries (per namespace meta). */
export const EXTRACTION_RETRY_STATE_MAX_ENTRIES = 500;

export interface ExtractionRetryStateEntry {
  attempts: number;
  nextEligibleAtMs: number;
  firstFailedAtMs: number;
  lastFailureClass: ExtractionFailureClass;
}

export interface ExtractionResilienceStatus {
  breaker: {
    state: "closed" | "open" | "half_open";
    openUntilMs: number;
    consecutiveFailures: number;
    lastReason: string;
  };
  backoffFingerprintCount: number;
}

/**
 * Pure backoff scheduler. Returns the absolute ms timestamp at which a
 * fingerprint that has failed `attempts` times becomes eligible again:
 * exponential via the configured schedule, clamped to `maxBackoffMs`, with
 * ±`jitterRatio` multiplicative jitter. `rng` is injectable for deterministic
 * tests. Never returns a timestamp before `now`.
 */
export function computeExtractionRetryNextEligibleMs(
  attempts: number,
  scheduleMs: readonly number[],
  maxBackoffMs: number,
  jitterRatio: number,
  now: number,
  rng: () => number = Math.random,
): number {
  if (!Number.isFinite(attempts) || !Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError("attempts must be a finite integer >= 1");
  }
  if (!Number.isFinite(maxBackoffMs) || maxBackoffMs < 0) {
    throw new RangeError("maxBackoffMs must be a finite number >= 0");
  }
  if (!Number.isFinite(jitterRatio) || jitterRatio < 0 || jitterRatio > 1) {
    throw new RangeError("jitterRatio must be a finite number in [0, 1]");
  }
  const safeNow = Number.isFinite(now) ? now : 0;
  const cap = maxBackoffMs;
  if (!Array.isArray(scheduleMs) || scheduleMs.length === 0) {
    return safeNow + cap;
  }
  const idx = Math.min(attempts - 1, scheduleMs.length - 1);
  const step = scheduleMs[idx];
  const base = Math.min(typeof step === "number" && Number.isFinite(step) && step > 0 ? step : cap, cap);
  const randomValue = rng();
  if (!Number.isFinite(randomValue) || randomValue < 0 || randomValue > 1) {
    throw new RangeError("rng() must return a finite number in [0, 1]");
  }
  const jitter = 1 + (randomValue * 2 - 1) * jitterRatio;
  return safeNow + Math.max(0, Math.round(base * jitter));
}

/**
 * Cap the persisted retry-state array to the newest `maxEntries` by
 * firstFailedAt. Guards invalid caps so they cannot turn `slice(-maxEntries)`
 * into an unbounded copy (AGENTS.md rule 17).
 */
export function capExtractionRetryStateEntries<T extends { firstFailedAt: string }>(
  entries: readonly T[],
  maxEntries: number,
): T[] {
  if (!Number.isFinite(maxEntries) || !Number.isInteger(maxEntries) || maxEntries <= 0) return [];
  const sorted = [...entries].sort((a, b) => a.firstFailedAt.localeCompare(b.firstFailedAt));
  return sorted.slice(-maxEntries);
}

/**
 * Derive a single `sourceConnector` from a batch of turns.
 * Returns the connector ONLY when ALL turns carry the same connector.
 * Mixed tagged/untagged batches return undefined — extraction facts are
 * persisted at batch level, so attributing them to the single tagged
 * connector would falsely label facts from untagged turns.
 * Conflicting connectors (different values) also return undefined.
 */
export function deriveSourceConnector(turns: readonly BufferTurn[]): string | undefined {
  if (turns.length === 0) return undefined;
  const connectors = new Set<string>();
  let untaggedCount = 0;
  for (const turn of turns) {
    if (typeof turn.sourceConnector === "string" && turn.sourceConnector.length > 0) {
      connectors.add(turn.sourceConnector);
    } else {
      untaggedCount += 1;
    }
  }
  // All turns must agree on the same connector — no untagged turns mixed in.
  if (untaggedCount > 0) return undefined;
  return connectors.size === 1 ? [...connectors][0] : undefined;
}

export async function runExtractionPostPersistBestEffort(
  runDeadlineAware: (
    operation: () => Promise<unknown>,
    phase: string,
    clearTimerOnError?: boolean,
    options?: { ignoreAbort?: boolean; ignoreDeadline?: boolean },
  ) => Promise<unknown>,
  stage: string,
  operation: () => Promise<unknown>,
  options?: { ignoreAbort?: boolean; ignoreDeadline?: boolean; propagateErrors?: boolean },
): Promise<void> {
  try {
    await runDeadlineAware(operation, stage, false, {
      ignoreAbort: options?.ignoreAbort,
      ignoreDeadline: options?.ignoreDeadline,
    });
  } catch (error) {
    if (options?.propagateErrors) throw error;
    log.warn(`runExtraction: ${stage} failed after persistence (non-fatal)`, error);
  }
}

/**
 * Applies deferred-judge retention only to live, non-shadow extraction runs.
 * Replay/import paths must not synthesize live-buffer entries after persistence.
 */
export interface ExtractionDeferRetentionOptions {
  clearBufferAfterExtraction: boolean;
  extractionJudgeShadow: boolean;
  deferredCount: number;
  normalizedTurns: BufferTurn[];
  bufferKey: string;
  retainDeferredTurns: (bufferKey: string, turns: BufferTurn[], max: number) => Promise<void>;
}

export async function runExtractionDeferRetention(
  runPostPersistBestEffort: (
    stage: string,
    operation: () => Promise<unknown>,
    options?: { ignoreAbort?: boolean },
  ) => Promise<void>,
  options: ExtractionDeferRetentionOptions,
): Promise<void> {
  await runPostPersistBestEffort("during_defer_retention", async () => {
    if (options.clearBufferAfterExtraction && !options.extractionJudgeShadow) {
      const deferredCount = options.deferredCount;
      if (deferredCount > 0 && options.normalizedTurns.length > 0) {
        await options.retainDeferredTurns(options.bufferKey, options.normalizedTurns, 10);
      } else {
        await options.retainDeferredTurns(options.bufferKey, [], 0);
      }
    }
  });
}

export interface ExtractionPostPersistOptions {
  result: ExtractionResult;
  storage: StorageManager;
  extractionFingerprint?: string;
  shouldPersistProcessedFingerprint: boolean;
  recordProcessedExtractionFingerprint: (
    storage: StorageManager,
    fingerprint: string,
    meta: MetaState,
  ) => Promise<void>;
  runDeadlineAware: (
    operation: () => Promise<unknown>,
    phase: string,
    clearTimerOnError?: boolean,
    options?: { ignoreAbort?: boolean; ignoreDeadline?: boolean },
  ) => Promise<unknown>;
  isDeadlineError: (error: unknown) => boolean;
  createDeadlineError: (stage: string) => Error;
  deadlineMs?: number;
  clearBufferAfterExtraction: boolean;
  runPostPersistBestEffort: (
    stage: string,
    operation: () => Promise<unknown>,
    options?: { ignoreAbort?: boolean; ignoreDeadline?: boolean; propagateErrors?: boolean },
  ) => Promise<void>;
  extractionJudgeShadow: boolean;
  /** Facts this run's persist deferred to the judge — drives retention (#1523). */
  deferredCount: number;
  normalizedTurns: BufferTurn[];
  bufferKey: string;
  retainDeferredTurns: (bufferKey: string, turns: BufferTurn[], max: number) => Promise<void>;
  clearBuffer: (options?: { ignoreAbort?: boolean }) => Promise<void>;
  failOnExtractionFailure: boolean;
}

export interface ExtractionPostPersistResult {
  metadataFailed: boolean;
}

export async function runExtractionPostPersist(
  options: ExtractionPostPersistOptions,
): Promise<ExtractionPostPersistResult> {
  let metadataFailed = false;
  let deadlineError: Error | undefined;
  const recordFailure = (stage: string, error: unknown): void => {
    metadataFailed = true;
    if (options.isDeadlineError(error) && deadlineError === undefined) {
      deadlineError = error as Error;
    }
    log.warn(`runExtraction: ${stage} failed after durable persistence; continuing with buffer clear`, error);
  };
  // Applied under the storage's per-dir meta lock (storage.updateMeta): the
  // fingerprint record and the counters land on a FRESHLY loaded meta, so a
  // concurrent extraction's updates are not reverted by this save.
  const applyPostPersistMetadata = async (fresh: MetaState): Promise<void> => {
    if (options.extractionFingerprint && options.shouldPersistProcessedFingerprint) {
      try {
        await options.recordProcessedExtractionFingerprint(options.storage, options.extractionFingerprint, fresh);
      } catch (error) {
        metadataFailed = true;
        log.warn("runExtraction: processed fingerprint failed after durable persistence; continuing with buffer clear", error);
      }
    }
    fresh.extractionCount += 1;
    fresh.lastExtractionAt = new Date().toISOString();
    fresh.totalMemories += Array.isArray(options.result.facts) ? options.result.facts.length : 0;
    fresh.totalEntities += Array.isArray(options.result.entities) ? options.result.entities.length : 0;
  };
  try {
    await options.runDeadlineAware(
      () => options.storage.updateMeta(applyPostPersistMetadata),
      "during_post_persist_meta_save",
      false,
    );
  } catch (error) {
    recordFailure("metadata save", error);
  }
  const runBestEffort = options.runPostPersistBestEffort;
  await runExtractionDeferRetention(runBestEffort, {
    clearBufferAfterExtraction: options.clearBufferAfterExtraction,
    extractionJudgeShadow: options.extractionJudgeShadow,
    deferredCount: options.deferredCount,
    normalizedTurns: options.normalizedTurns,
    bufferKey: options.bufferKey,
    retainDeferredTurns: options.retainDeferredTurns,
  });
  await runBestEffort(
    "during_buffer_clear",
    () => options.clearBuffer({ ignoreAbort: true }),
    {
      ignoreAbort: true,
      ignoreDeadline: options.failOnExtractionFailure,
      propagateErrors: options.failOnExtractionFailure,
    },
  );
  if (options.failOnExtractionFailure && typeof options.deadlineMs === "number" && Date.now() >= options.deadlineMs) {
    throw options.createDeadlineError("during_buffer_clear");
  }
  if (deadlineError) throw deadlineError;
  return { metadataFailed };
}

/**
 * Record a processed fingerprint when applicable and advance the extraction
 * liveness watermark only for a provider-backed empty success. Fingerprinted
 * imports treat the metadata save as load-bearing dedupe state; normal live
 * runs treat the stamp as diagnostic and fail open. Deadline errors always
 * propagate.
 */
export async function commitEmptySuccessExtraction(args: {
  storage: StorageManager;
  extractionFingerprint: string | null;
  shouldPersistProcessedFingerprint: boolean;
  hasExtractionFailure: boolean;
  extractionSkippedReason: ExtractionResult["extractionSkippedReason"];
  recordProcessedExtractionFingerprint: (storage: StorageManager, fingerprint: string, meta: MetaState) => Promise<unknown>;
  runDeadlineAware: <T>(operation: () => Promise<T>, phase: string, clearTimerOnError?: boolean) => Promise<T>;
  isDeadlineError: (error: unknown) => boolean;
}): Promise<void> {
  const {
    storage,
    extractionFingerprint,
    shouldPersistProcessedFingerprint,
    hasExtractionFailure,
    extractionSkippedReason,
    recordProcessedExtractionFingerprint,
    runDeadlineAware,
    isDeadlineError,
  } = args;
  const shouldRecordFingerprint =
    extractionFingerprint !== null &&
    shouldPersistProcessedFingerprint &&
    !hasExtractionFailure;
  const shouldStampLiveness =
    !hasExtractionFailure && extractionSkippedReason === undefined;
  if (!shouldRecordFingerprint && !shouldStampLiveness) return;

  const metadataFailureIsFatal = shouldRecordFingerprint;
  try {
    await runDeadlineAware(
      () =>
        storage.updateMeta(async (meta) => {
          if (shouldRecordFingerprint) {
            await recordProcessedExtractionFingerprint(storage, extractionFingerprint!, meta);
          }
          if (shouldStampLiveness) {
            meta.extractionCount += 1;
            meta.lastExtractionAt = new Date().toISOString();
          }
        }),
      "during_empty_success_liveness_save",
      false,
    );
  } catch (err) {
    if (isDeadlineError(err)) throw err;
    if (metadataFailureIsFatal) throw err;
    log.warn("runExtraction: failed to stamp empty-success liveness watermark (non-fatal)", err);
  }
}

import { log } from "../logger.js";
import type { ExtractionFailureClass } from "../types.js";

export interface ProviderBreakerConfig {
  readonly failureThreshold: number;
  readonly cooldownMs: number;
  readonly authCooldownMs: number;
}

export interface ProbeOwnerToken {
  readonly __probeOwner: true;
}

export interface ProviderBreakerSnapshot {
  readonly state: "closed" | "open" | "half_open";
  readonly openUntilMs: number;
  readonly consecutiveFailures: number;
  readonly lastReason: string;
}

export interface ProbeAcquisition {
  /** True when the attempt is suppressed (breaker open, or the half-open
   *  probe is owned by another attempt). */
  readonly suppressed: boolean;
  /** True when THIS attempt owns the single half-open probe and must
   *  terminate it via {@link failure}/{@link success} (with its token), or
   *  release it via {@link releaseProbe} on any early exit (deadline, abort,
   *  throw). */
  readonly probe: boolean;
  /** Opaque ownership token; only the matching token settles or releases the
   *  probe, so attempts that bypass the gate (forced extractions) can never
   *  release another attempt's in-flight probe. */
  readonly token?: ProbeOwnerToken;
}

/**
 * Provider circuit breaker with single-flight half-open probe OWNERSHIP
 * (codex P2 on #3311): under extractionQueueConcurrency > 1 several sessions
 * can pass an expired `open` breaker in the same window, and a wall-clock
 * reservation either expires under a live long provider attempt (600s
 * timeouts) or pins the breaker when an attempt dies without settling. So the
 * probe is OWNED, not timed: exactly one attempt holds it from the
 * open→half_open flip until its terminal `failure()`/`success()`, and any
 * early exit releases it explicitly. A released-but-unfinished probe lets the
 * next attempt re-probe; a retry backoff still throttles that namespace.
 */
export class ProviderCircuitBreaker {
  private consecutiveFailures = 0;
  private openUntilMs = 0;
  private state: ProviderBreakerSnapshot["state"] = "closed";
  private lastReason = "";
  private probeHeld = false;
  private probeToken: ProbeOwnerToken | null = null;

  acquire(now: number): ProbeAcquisition {
    if (now < this.openUntilMs) return { suppressed: true, probe: false };
    if (this.state === "open") {
      this.state = "half_open";
      this.probeHeld = true;
      const token: ProbeOwnerToken = { __probeOwner: true };
      this.probeToken = token;
      this.logTransition();
      return { suppressed: false, probe: true, token }; // THIS attempt is the probe.
    }
    if (this.state === "half_open") {
      if (this.probeHeld) return { suppressed: true, probe: false };
      this.probeHeld = true; // previous owner released without settling; re-probe.
      const token: ProbeOwnerToken = { __probeOwner: true };
      this.probeToken = token;
      return { suppressed: false, probe: true, token };
    }
    return { suppressed: false, probe: false };
  }

  /** Release an owned probe on an attempt that exits without a terminal
   *  outcome (deadline, abort, throw). Only the matching owner releases;
   *  idempotent; state stays half_open so the next attempt re-probes. */
  releaseProbe(token?: ProbeOwnerToken): void {
    if (token === undefined || this.probeToken !== token) return;
    this.probeToken = null;
    this.probeHeld = false;
  }

  failure(cls: ExtractionFailureClass, now: number, config: ProviderBreakerConfig, probeToken?: ProbeOwnerToken): void {
    // Only the probe OWNER's failure settles the half-open probe: a failure
    // from an attempt that bypassed acquire (forced extraction) must not
    // release another attempt's in-flight probe or masquerade as its result.
    const owned = probeToken !== undefined && this.probeToken === probeToken;
    if (owned) {
      this.probeToken = null;
      this.probeHeld = false;
    }
    this.consecutiveFailures += 1;
    const trip =
      // An unowned auth_config failure (forced extraction) must not reopen
      // over a held half-open probe — same ownership rule as the threshold
      // term; the auth cooldown still applies once the probe settles.
      (cls === "auth_config" && (this.state !== "half_open" || owned)) ||
      // A failed half-open probe re-opens immediately (standard breaker
      // semantics). Without this, an auth_config-opened breaker (which trips
      // below the threshold) would get stuck half_open after a transient
      // probe failure and stop suppressing (cursor review).
      (owned && this.state === "half_open") ||
      // PRRT_kwDORJXyws6zxG6V: an unowned (forced-extraction) failure must
      // not cross the threshold while another attempt owns the half-open
      // probe — reopening here would strand the owner's token and let the
      // next cooldown mint a second concurrent probe. The failure count and
      // retry bookkeeping still accumulate for when the state leaves
      // half_open.
      (this.state !== "half_open" && this.consecutiveFailures >= config.failureThreshold);
    if (!trip) return;
    const cooldown = cls === "auth_config" ? config.authCooldownMs : config.cooldownMs;
    this.openUntilMs = now + Math.max(0, cooldown);
    this.lastReason = cls;
    if (this.state !== "open") {
      this.state = "open";
      this.logTransition();
    }
  }

  success(probeToken?: ProbeOwnerToken): void {
    const wasDisturbed =
      this.state !== "closed" || this.consecutiveFailures > 0 || this.openUntilMs > 0;
    if (!wasDisturbed) return;
    // PRRT_kwDORJXyws6zxG6u: while a half-open probe is held, only its OWNER
    // may settle it. An unowned (forced-extraction) success must not clear
    // another run's probe or close the breaker mid-probe — the next ordinary
    // acquisition could then start a second concurrent probe.
    if (this.probeHeld && !(probeToken !== undefined && this.probeToken === probeToken)) return;
    const wasOpen = this.state !== "closed";
    this.probeToken = null;
    this.probeHeld = false;
    this.consecutiveFailures = 0;
    this.openUntilMs = 0;
    this.lastReason = "";
    this.state = "closed";
    if (wasOpen) this.logTransition();
  }

  snapshot(): ProviderBreakerSnapshot {
    return {
      state: this.state,
      openUntilMs: this.openUntilMs,
      consecutiveFailures: this.consecutiveFailures,
      lastReason: this.lastReason,
    };
  }

  private logTransition(): void {
    // Once per state change (not per attempt) — AGENTS.md observability rule.
    log.warn("extraction: provider circuit breaker transition", {
      state: this.state,
      consecutiveFailures: this.consecutiveFailures,
      lastReason: this.lastReason,
      openUntilMs: this.openUntilMs,
    });
  }
}

import { isIP } from "node:net";

function normalizedIp(host: string): string {
  const value = host.trim().replace(/^\[/, "").replace(/\]\.?$/, "").replace(/\.$/, "");
  if (isIP(value) === 4) return value;
  if (isIP(value) !== 6) return "";
  return new URL(`http://[${value}]/`).hostname.slice(1, -1);
}

export function isLoopbackHost(host: string): boolean {
  const normalized = host.trim().replace(/^\[/, "").replace(/\]\.?$/, "").replace(/\.$/, "").toLowerCase();
  if (normalized === "localhost" || normalized.endsWith(".localhost")) return true;

  const ip = normalizedIp(normalized);
  if (ip === "::1") return true;
  if (isIP(ip) === 4) return ip.startsWith("127.");
  if (!ip.startsWith("::ffff:")) return false;

  const [high, low] = ip.slice("::ffff:".length).split(":");
  return Number.parseInt(high, 16) >>> 8 === 127 || (high === "0" && Number.parseInt(low, 16) >>> 8 === 127);
}

export function httpProtocolForHost(host: string, allowInsecureHttp = false): "http" | "https" {
  return isLoopbackHost(host) || allowInsecureHttp ? "http" : "https";
}

/**
 * Honest names for the gateway/task LLM chain (issue #2967).
 *
 * `FallbackLlmClient` is the primary configured path in gateway mode, not a
 * secondary recovery path. `taskLlmTimeoutMs` / `taskLlmFallback` are the
 * current keys. `localLlmTimeoutMs` / `localLlmFallback` remain documented
 * legacy aliases, read only when the corresponding new key is absent.
 */
import { coerceBool, coerceNumber } from "./connectors/coerce.js";
import { log } from "./logger.js";

const DEFAULT_TIMEOUT_MS = 180_000;
const MIN_TIMEOUT_MS = 1;
const MAX_TIMEOUT_MS = 86_400_000;

const warnedLegacy = new Set<string>();

export function resetTaskLlmLegacyWarningsForTest(): void {
  warnedLegacy.clear();
}

function warnLegacyOnce(legacyKey: string, currentKey: string, extra: string): void {
  if (warnedLegacy.has(legacyKey)) return;
  warnedLegacy.add(legacyKey);
  log.warn(
    `config: ${legacyKey} is a legacy alias for ${currentKey}; set ${currentKey} instead. ${legacyKey} still works when ${currentKey} is absent. ${extra}`,
  );
}

function parseBoundedIntegerMs(value: unknown, fallback: number): number {
  const coerced = coerceNumber(value);
  if (coerced === undefined) return fallback;
  return Math.min(MAX_TIMEOUT_MS, Math.max(MIN_TIMEOUT_MS, Math.floor(coerced)));
}

function hasOwnKey(raw: Record<string, unknown>, key: string): boolean {
  return Object.hasOwn(raw, key);
}

export interface ParsedTaskLlmConfig {
  timeoutMs: number;
  localTimeoutMs: number;
  fallback: boolean;
}

/**
 * Resolve task-LLM timeout and local→task fallback.
 *
 * New key wins when present (including present-with-`undefined`, which takes
 * the default rather than falling through to the legacy key). Legacy keys are
 * read only when the new key is absent, and warn once per process.
 */
export function parseTaskLlmConfig(cfg: Record<string, unknown>): ParsedTaskLlmConfig {
  const localTimeoutMs = hasOwnKey(cfg, "localLlmTimeoutMs")
    ? parseBoundedIntegerMs(cfg.localLlmTimeoutMs, DEFAULT_TIMEOUT_MS)
    : DEFAULT_TIMEOUT_MS;

  let timeoutMs: number;
  if (hasOwnKey(cfg, "taskLlmTimeoutMs")) {
    timeoutMs = parseBoundedIntegerMs(cfg.taskLlmTimeoutMs, DEFAULT_TIMEOUT_MS);
  } else if (hasOwnKey(cfg, "localLlmTimeoutMs")) {
    warnLegacyOnce(
      "localLlmTimeoutMs",
      "taskLlmTimeoutMs",
      "localLlmTimeoutMs remains the local-endpoint timeout; without taskLlmTimeoutMs it also sizes the gateway/task chain.",
    );
    timeoutMs = localTimeoutMs;
  } else {
    timeoutMs = DEFAULT_TIMEOUT_MS;
  }

  let fallback: boolean;
  if (hasOwnKey(cfg, "taskLlmFallback")) {
    const coerced = coerceBool(cfg.taskLlmFallback, "taskLlmFallback");
    fallback = coerced !== undefined ? coerced : true;
  } else if (hasOwnKey(cfg, "localLlmFallback")) {
    warnLegacyOnce(
      "localLlmFallback",
      "taskLlmFallback",
      "taskLlmFallback is the current name for using the gateway/task chain when the local path fails.",
    );
    fallback = cfg.localLlmFallback !== false;
  } else {
    fallback = true;
  }

  return { timeoutMs, localTimeoutMs, fallback };
}

/**
 * Backoff for the tombstone-blocked capture write lock (COS-392).
 *
 * A converge cycle used to give up after three probes about 25ms apart while
 * the daemon still held the lock for an ordinary write. Waiters now sleep
 * outside every lock: equal-jitter exponential backoff, capped per wait, with
 * one overall deadline. The numbers are the production defaults; converge
 * config and env can override them.
 */

export const CAPTURE_WRITE_LOCK_BUSY_MESSAGE = "tombstone-blocked capture write lock remained busy";

export function isTombstoneBlockedCaptureWriteLockBusy(error: unknown): boolean {
  return error instanceof Error && error.message === CAPTURE_WRITE_LOCK_BUSY_MESSAGE;
}

export const DEFAULT_CAPTURE_WRITE_LOCK_INITIAL_DELAY_MS = 50;
export const DEFAULT_CAPTURE_WRITE_LOCK_MAX_DELAY_MS = 2_000;
export const DEFAULT_CAPTURE_WRITE_LOCK_DEADLINE_MS = 60_000;
/** Same hour ceiling as the converge peer HTTP timeout. */
export const MAX_CAPTURE_WRITE_LOCK_WAIT_MS = 3_600_000;

const MAX_BACKOFF_EXPONENT = 16;

export type CaptureWriteLockBackoffLimits = {
  readonly initialDelayMs: number;
  readonly maxDelayMs: number;
  readonly deadlineMs: number;
};

export type CaptureWriteLockLimitSource = {
  readonly captureWriteLockInitialDelayMs?: number;
  readonly captureWriteLockMaxDelayMs?: number;
  readonly captureWriteLockDeadlineMs?: number;
  /**
   * Read when an acquire starts. Converge installs the apply abort signal
   * here so a SIGINT during backoff never reaches the guarded write.
   */
  readonly captureWriteLockSignal?: AbortSignal;
};

/**
 * One backoff wait. Attempt 0 is uniform in `[ceil(initial/2), initial]`
 * (25–50ms at the defaults). Each later attempt doubles that window until
 * `maxDelayMs`. `random` returns a finite number in `[0, 1]`.
 */
export function captureWriteLockDelayMs(
  attempt: number,
  limits: Pick<CaptureWriteLockBackoffLimits, "initialDelayMs" | "maxDelayMs">,
  random: () => number = Math.random
): number {
  if (!Number.isInteger(attempt) || attempt < 0) {
    throw new TypeError("capture write lock backoff attempt must be a non-negative integer");
  }
  if (!Number.isInteger(limits.initialDelayMs) || limits.initialDelayMs <= 0) {
    throw new TypeError("capture write lock initialDelayMs must be a positive integer");
  }
  if (!Number.isInteger(limits.maxDelayMs) || limits.maxDelayMs <= 0) {
    throw new TypeError("capture write lock maxDelayMs must be a positive integer");
  }
  if (limits.initialDelayMs > limits.maxDelayMs) {
    throw new TypeError("capture write lock initialDelayMs must be <= maxDelayMs");
  }
  const unit = random();
  if (typeof unit !== "number" || !Number.isFinite(unit) || unit < 0 || unit > 1) {
    throw new TypeError("capture write lock jitter source must return a finite number in [0, 1]");
  }
  const exponent = Math.min(attempt, MAX_BACKOFF_EXPONENT);
  const ceiling = Math.min(limits.maxDelayMs, limits.initialDelayMs * 2 ** exponent);
  const floor = Math.ceil(ceiling / 2);
  if (ceiling <= floor) return ceiling;
  const span = ceiling - floor;
  const offset = Math.min(span, Math.floor(unit * (span + 1)));
  return floor + offset;
}

export function normalizeCaptureWriteLockWaitMs(value: unknown, label: string): number {
  if (typeof value !== "number" || !Number.isInteger(value) || value <= 0) {
    throw new Error(`${label} must be a positive integer number of milliseconds; got ${JSON.stringify(value)}`);
  }
  return Math.min(value, MAX_CAPTURE_WRITE_LOCK_WAIT_MS);
}

function pickWaitMs(value: number | undefined, fallback: number, label: string): number {
  if (value === undefined) return fallback;
  return normalizeCaptureWriteLockWaitMs(value, label);
}

/**
 * Limits for a capture with no lock-options source — the plain daemon or an
 * inline capture. The deadline matches the pre-backoff tolerance of about 3s
 * (three probe waits of up to 1s each plus short retry sleeps), so ordinary
 * capture contention keeps that wait and still fails in bounded time.
 */
export const LEGACY_CAPTURE_WRITE_LOCK_INITIAL_DELAY_MS = 25;
export const LEGACY_CAPTURE_WRITE_LOCK_MAX_DELAY_MS = 50;
export const LEGACY_CAPTURE_WRITE_LOCK_DEADLINE_MS = 3_000;

/** Fill omitted knobs from the defaults and reject an inverted schedule. */
export function resolveCaptureWriteLockBackoffLimits(
  source: CaptureWriteLockLimitSource | undefined
): CaptureWriteLockBackoffLimits {
  // No source means a non-converge capture: keep the short legacy bounds.
  const defaults =
    source === undefined
      ? {
          initialDelayMs: LEGACY_CAPTURE_WRITE_LOCK_INITIAL_DELAY_MS,
          maxDelayMs: LEGACY_CAPTURE_WRITE_LOCK_MAX_DELAY_MS,
          deadlineMs: LEGACY_CAPTURE_WRITE_LOCK_DEADLINE_MS,
        }
      : {
          initialDelayMs: DEFAULT_CAPTURE_WRITE_LOCK_INITIAL_DELAY_MS,
          maxDelayMs: DEFAULT_CAPTURE_WRITE_LOCK_MAX_DELAY_MS,
          deadlineMs: DEFAULT_CAPTURE_WRITE_LOCK_DEADLINE_MS,
        };
  const initialDelayMs = pickWaitMs(
    source?.captureWriteLockInitialDelayMs,
    defaults.initialDelayMs,
    "captureWriteLockInitialDelayMs"
  );
  const maxDelayMs = pickWaitMs(
    source?.captureWriteLockMaxDelayMs,
    defaults.maxDelayMs,
    "captureWriteLockMaxDelayMs"
  );
  const deadlineMs = pickWaitMs(
    source?.captureWriteLockDeadlineMs,
    defaults.deadlineMs,
    "captureWriteLockDeadlineMs"
  );
  if (initialDelayMs > maxDelayMs) {
    throw new Error(
      `captureWriteLockInitialDelayMs (${initialDelayMs}) must be <= captureWriteLockMaxDelayMs (${maxDelayMs})`
    );
  }
  if (maxDelayMs > deadlineMs) {
    throw new Error(`captureWriteLockMaxDelayMs (${maxDelayMs}) must be <= captureWriteLockDeadlineMs (${deadlineMs})`);
  }
  return { initialDelayMs, maxDelayMs, deadlineMs };
}

/**
 * Memory subject: user-centric vs agent-centric classification (issue #2372).
 *
 * Scope says WHERE a memory lives; subject says WHOM it is about — and that
 * is what determines where it may safely go. `user` memories model one
 * person (preferences, relationships, biography, moments, commitments);
 * `agent` memories model how to operate (procedures, principles,
 * tool-usage lessons, debugging strategies, environment facts with no
 * personal content).
 *
 * This module owns, in one place:
 *  - the deterministic write-time classification (category defaults with an
 *    optional extractor override),
 *  - the promotion guard shared by EVERY promotion surface (spaces promote
 *    AND scope-profile promotion targets — AGENTS.md §27 uniform gating),
 *  - read-only promotion-candidate surfacing (reuse-signaled agent-subject
 *    memories with no equivalent in the target layer), and
 *  - the deterministic backfill pass (shadow/apply, no LLM).
 */

import { ContentHashIndex } from "./storage/content-hash-index.js";
import { sanitizeMemoryContent } from "./sanitize.js";
import type { McpTool } from "./access-mcp.js";
import type { MemoryCategory, MemoryFile, MemorySubject, SubjectGuardMode } from "./types.js";

export const SUBJECT_VALUES = ["user", "agent"] as const;
export const SUBJECT_GUARD_MODES = ["off", "warn", "enforce"] as const;

/** The CLI / per-call override that permits a user-subject promotion. */
export const SUBJECT_GUARD_OVERRIDE_FLAG = "--allow-user-subject";

export function isMemorySubject(value: unknown): value is MemorySubject {
  return value === "user" || value === "agent";
}

export function isSubjectGuardMode(value: unknown): value is SubjectGuardMode {
  return value === "off" || value === "warn" || value === "enforce";
}

// ---------------------------------------------------------------------------
// Write-time classification
// ---------------------------------------------------------------------------

/**
 * Deterministic category defaults (issue #2372 §1):
 *   user — preference, relationship, moment, commitment
 *   agent — procedure, principle, skill
 * Every other category has no default; the resolver falls back to `"user"`,
 * the most-restrictive value (Review Prevention Checklist §36 — an unsafe
 * enum default is never the convenient one).
 */
const SUBJECT_CATEGORY_DEFAULTS: Partial<Record<MemoryCategory, MemorySubject>> = {
  preference: "user",
  relationship: "user",
  moment: "user",
  commitment: "user",
  procedure: "agent",
  principle: "agent",
  skill: "agent",
};

export function subjectDefaultForCategory(category: MemoryCategory): MemorySubject {
  return SUBJECT_CATEGORY_DEFAULTS[category] ?? "user";
}

/**
 * Resolve the write-time subject: the extractor's single-token value when it
 * emitted a valid one, else the category default. Never reclassifies on read.
 */
export function resolveWriteSubject(
  category: MemoryCategory,
  extractorValue: unknown,
): MemorySubject {
  return isMemorySubject(extractorValue) ? extractorValue : subjectDefaultForCategory(category);
}

// ---------------------------------------------------------------------------
// Promotion guard (uniform across every promotion surface — §27)
// ---------------------------------------------------------------------------

/** Scope-profile promotion targets that are shared layers. */
export function isSharedPromotionTarget(target: string): boolean {
  return target === "teamProject" || target === "serverShared";
}

export interface SubjectGuardDecision {
  action: "allow" | "warn" | "reject";
  /** Effective subject — an absent subject resolves to "user" (fail closed, §36). */
  effectiveSubject: MemorySubject;
  /** Structured reason; empty string when action === "allow". */
  reason: string;
  /** The override that permits this promotion when action is reject/warn. */
  override: typeof SUBJECT_GUARD_OVERRIDE_FLAG;
}

/**
 * Evaluate one promotion against the subject guard. Shared by the spaces
 * promotion workflow and the scope-profile promotion targets so the two
 * surfaces cannot drift (issue #2372 acceptance 2, AGENTS.md §27).
 *
 *  - mode "off", non-shared targets, agent-subject memories, and explicit
 *    `allowUserSubject` overrides all allow.
 *  - a `user`-subject memory (or a memory with NO subject — fail closed)
 *    promoted to a shared layer warns under "warn" and rejects under
 *    "enforce", with the override named in the reason (§39: never a silent
 *    accept).
 */
export function evaluateSubjectGuard(params: {
  subject: MemorySubject | undefined;
  sharedTarget: boolean;
  mode: SubjectGuardMode;
  allowUserSubject?: boolean;
}): SubjectGuardDecision {
  const effectiveSubject = params.subject ?? "user";
  const base = { effectiveSubject, override: SUBJECT_GUARD_OVERRIDE_FLAG } as const;
  if (params.mode === "off" || !params.sharedTarget || effectiveSubject === "agent") {
    return { action: "allow", reason: "", ...base };
  }
  if (params.allowUserSubject === true) {
    return { action: "allow", reason: "user-subject promotion override accepted", ...base };
  }
  return {
    action: params.mode === "enforce" ? "reject" : "warn",
    reason:
      `subject=${effectiveSubject} memory targets a shared layer (team/server); ` +
      `user-subject memories model one person and must not be shared; ` +
      `override with ${SUBJECT_GUARD_OVERRIDE_FLAG} (allowUserSubject: true) if intended`,
    ...base,
  };
}

// ---------------------------------------------------------------------------
// Promotion candidates (read-only surfacing — no auto-promotion)
// ---------------------------------------------------------------------------

export type PromotionReuseSignal = "reinforcement" | "memory_worth" | "access_count";

export interface PromotionCandidate {
  id: string;
  path: string;
  category: MemoryCategory;
  content: string;
  accessCount: number;
  reinforcementCount: number;
  mwSuccess: number;
  mwFail: number;
  reuseSignal: PromotionReuseSignal;
}

/** Default reuse-signal threshold for `accessCount` (config `promotionCandidates.minAccessCount`). */
export const PROMOTION_CANDIDATES_DEFAULT_MIN_ACCESS = 3;

/** Canonical content form for target-equivalence checks (same normalize pipeline as dedup). */
export function promotionCandidateKey(content: string): string {
  return ContentHashIndex.normalizeContent(sanitizeMemoryContent(content).text);
}

/**
 * List `subject: "agent"` memories that (a) are active, (b) show a reuse
 * signal (`reinforcement_count > 0` OR `mw_success > mw_fail` OR
 * `accessCount >= minAccessCount`), and (c) have no equivalent already in
 * the promotion target layer (content-hash check via the dedup normalizer).
 * Pure over the two memory lists; callers resolve namespaces.
 */
export function computePromotionCandidates(options: {
  memories: MemoryFile[];
  targetMemories: MemoryFile[];
  minAccessCount: number;
  limit?: number;
}): PromotionCandidate[] {
  if (!Number.isFinite(options.minAccessCount) || options.minAccessCount < 0) {
    throw new Error(
      `computePromotionCandidates: minAccessCount must be a non-negative number (got ${String(options.minAccessCount)})`,
    );
  }
  const targetKeys = new Set(
    options.targetMemories.map((m) => promotionCandidateKey(m.content ?? "")),
  );
  const out: PromotionCandidate[] = [];
  for (const memory of options.memories) {
    const fm = memory.frontmatter;
    if (fm.subject !== "agent") continue;
    if ((fm.status ?? "active") !== "active") continue;
    const reinforcementCount = fm.reinforcement_count ?? 0;
    const mwSuccess = fm.mw_success ?? 0;
    const mwFail = fm.mw_fail ?? 0;
    const accessCount = fm.accessCount ?? 0;
    let reuseSignal: PromotionReuseSignal | undefined;
    if (reinforcementCount > 0) reuseSignal = "reinforcement";
    else if (mwSuccess > mwFail) reuseSignal = "memory_worth";
    else if (accessCount >= options.minAccessCount) reuseSignal = "access_count";
    if (reuseSignal === undefined) continue;
    if (targetKeys.has(promotionCandidateKey(memory.content ?? ""))) continue;
    out.push({
      id: fm.id,
      path: memory.path,
      category: fm.category,
      content: memory.content ?? "",

      accessCount,
      reinforcementCount,
      mwSuccess,
      mwFail,
      reuseSignal,
    });
    if (options.limit !== undefined && out.length >= options.limit) break;
  }
  return out;
}

export interface PromotionCandidatesResult {
  namespace: string;
  targetNamespace: string;
  minAccessCount: number;
  candidates: PromotionCandidate[];
}

export const PROMOTION_CANDIDATES_MCP_TOOLS: McpTool[] = [
  {
    // Registered as `engram.promotion_candidates`; `withToolAliases` emits
    // the canonical `remnic.promotion_candidates` alias (dual-naming).
    name: "engram.promotion_candidates",
    description:
      "List agent-subject memories in the caller's namespace that are active, show a reuse signal (reinforcement_count > 0, mw_success > mw_fail, or accessCount >= threshold), and have no equivalent in the promotion target layer (default: the shared namespace). Read-only report; promotion itself uses the existing promotion commands (issue #2372).",
    inputSchema: {
      type: "object",
      properties: {
        namespace: {
          type: "string",
          description:
            "Optional source namespace. Enforced against the caller's principal the same way recall is.",
        },
        targetNamespace: {
          type: "string",
          description: "Promotion target layer checked for existing equivalents. Default: the shared namespace.",
        },
        limit: {
          type: "integer",
          minimum: 1,
          maximum: 100,
          description: "Maximum candidates to return (default 20, max 100).",
