/**
 * Procedural memory types (issue #519).
 * Bodies use ordered "## Step N" sections; machine fields live in frontmatter / structuredAttributes.
 */

export interface ProcedureStep {
  order: number;
  intent: string;
  toolCall?: {
    kind: string;
    signature: string;
  };
  expectedOutcome?: string;
  optional?: boolean;
}

/** Normalize loose extraction JSON into ProcedureStep records. */
export function normalizeProcedureSteps(raw: unknown): ProcedureStep[] {
  if (!Array.isArray(raw)) return [];
  const out: ProcedureStep[] = [];
  for (let i = 0; i < raw.length; i++) {
    const s = raw[i];
    if (!s || typeof s !== "object") continue;
    const o = s as Record<string, unknown>;
    const intent = typeof o.intent === "string" ? o.intent.trim() : "";
    if (!intent) continue;
    const orderRaw = o.order;
    const order =
      typeof orderRaw === "number" && Number.isFinite(orderRaw)
        ? Math.max(1, Math.floor(orderRaw))
        : i + 1;
    let toolCall: ProcedureStep["toolCall"];
    const tc = o.toolCall;
    if (tc && typeof tc === "object" && !Array.isArray(tc)) {
      const t = tc as Record<string, unknown>;
      const kind = typeof t.kind === "string" ? t.kind.trim() : "";
      const signature = typeof t.signature === "string" ? t.signature.trim() : "";
      if (kind && signature) {
        toolCall = { kind, signature };
      }
    }
    const expectedOutcome =
      typeof o.expectedOutcome === "string" && o.expectedOutcome.trim()
        ? o.expectedOutcome.trim()
        : undefined;
    const optional = o.optional === true ? true : undefined;
    out.push({ order, intent, toolCall, expectedOutcome, optional });
  }
  return out;
}

/** Title line plus serialized steps for storage.writeMemory body. */
export function buildProcedurePersistBody(title: string, procedureSteps: unknown): string {
  const head = typeof title === "string" ? title.trim() : "";
  const steps = normalizeProcedureSteps(procedureSteps);
  if (steps.length === 0) return head;
  return `${head}\n\n${buildProcedureMarkdownBody(steps)}`.trimEnd() + "\n";
}

/** Serialize steps into markdown body (human-editable). */
export function buildProcedureMarkdownBody(steps: ProcedureStep[]): string {
  const sorted = [...steps].sort((a, b) => a.order - b.order);
  const lines: string[] = [];
  for (const step of sorted) {
    const n = Number.isFinite(step.order) ? Math.max(1, Math.floor(step.order)) : 1;
    lines.push(`## Step ${n}`);
    lines.push("");
    lines.push(step.intent.trim());
    if (step.toolCall?.kind && step.toolCall.signature) {
      lines.push("");
      lines.push(`- Tool: \`${step.toolCall.kind}\` — ${step.toolCall.signature}`);
    }
    if (step.expectedOutcome?.trim()) {
      lines.push("");
      lines.push(`- Expected: ${step.expectedOutcome.trim()}`);
    }
    if (step.optional === true) {
      lines.push("");
      lines.push("- Optional: true");
    }
    lines.push("");
  }
  return lines.join("\n").trimEnd() + "\n";
}

const STEP_HEADER_RE = /^##\s+Step\s+(\d+)\s*$/im;

/**
 * Best-effort parse of "## Step N" blocks into ProcedureStep records.
 * Returns null when no step headers are found.
 */
export function parseProcedureStepsFromBody(content: string): ProcedureStep[] | null {
  const text = content.replace(/\r\n/g, "\n").trim();
  if (!text) return null;
  const matches = [...text.matchAll(new RegExp(STEP_HEADER_RE.source, "gim"))];
  if (matches.length === 0) return null;

  const steps: ProcedureStep[] = [];
  for (let i = 0; i < matches.length; i++) {
    const m = matches[i];
    const order = Number.parseInt(m[1] ?? "1", 10);
    const start = (m.index ?? 0) + m[0].length;
    const end = i + 1 < matches.length ? (matches[i + 1].index ?? text.length) : text.length;
    const block = text.slice(start, end).trim();
    const lines = block.split("\n").map((l) => l.trim());
    const intentLines = lines.filter(
      (l) => l.length > 0 && !l.startsWith("- Tool:") && !l.startsWith("- Expected:") && !l.startsWith("- Optional:"),
    );
    const intent = intentLines.join(" ").trim() || "(unspecified)";
    let toolCall: ProcedureStep["toolCall"];
    const toolLine = lines.find((l) => l.startsWith("- Tool:"));
    if (toolLine) {
      const inner = toolLine.replace(/^- Tool:\s*/i, "").trim();
      const tick = inner.match(/^`([^`]+)`\s*[—-]\s*(.+)$/);
      if (tick) {
        toolCall = { kind: tick[1].trim(), signature: tick[2].trim() };
      }
    }
    const expectedLine = lines.find((l) => l.startsWith("- Expected:"));
    const expectedOutcome = expectedLine?.replace(/^- Expected:\s*/i, "").trim();
    const optional = /^- Optional:\s*true$/i.test(lines.find((l) => l.startsWith("- Optional:")) ?? "");

    steps.push({
      order: Number.isFinite(order) ? order : i + 1,
      intent,
      toolCall,
      expectedOutcome: expectedOutcome?.length ? expectedOutcome : undefined,
      optional: optional || undefined,
    });
  }
  return steps.length > 0 ? steps : null;
}

/**
 * Tool-surface error enrichment: nearest-tool suggestions and arg-shape hints.
 *
 * Each function is a pure message builder — it returns a better error string
 * without changing semantics, status codes, or rejection behavior.
 *
 * @module access-errors
 */

import type { ZodError } from "zod";

// ─── Existing error classes (restored from pre-#3042) ─────────────────────

/** Authenticated caller lacks the required authorization (HTTP 403). */
export class EngramAccessForbiddenError extends Error {}

/** Invalid caller input (HTTP 400). */
export class EngramAccessInputError extends Error {}

/**
 * A write rejected by the namespace write-ACL (issue #1888). Subclasses
 * EngramAccessInputError so every existing catch/HTTP-400 mapping still
 * applies, but carries the attempted namespace + principal so the observe/
 * write surfaces can dead-letter the payload before re-throwing (fail-closed
 * placement is unchanged; only the destroyed-payload behavior is fixed).
 */
export class NamespaceNotWritableError extends EngramAccessInputError {
  constructor(
    readonly attemptedNamespace: string,
    readonly principal: string | undefined,
    message?: string,
  ) {
    super(message ?? `namespace is not writable: ${attemptedNamespace}`);
    this.name = "NamespaceNotWritableError";
  }
}

// ─── Levenshtein distance ─────────────────────────────────────────────────

/**
 * Standard Levenshtein edit distance. O(n*m) over bounded inputs.
 * Exported so the test can verify it without importing private helpers.
 */
export function levenshtein(a: string, b: string): number {
  const an = a.length;
  const bn = b.length;
  // Fast paths for empty strings.
  if (an === 0) return bn;
  if (bn === 0) return an;

  // Use two rows to keep memory O(min(n,m)).
  let prev: number[] = [];
  let curr: number[] = [];

  // Align loops to the shorter string.
  const [shorter, longer, sn, ln] =
    an < bn ? [a, b, an, bn] : [b, a, bn, an];

  for (let i = 0; i <= sn; i++) prev[i] = i;

  for (let j = 1; j <= ln; j++) {
    curr[0] = j;
    for (let i = 1; i <= sn; i++) {
      const cost = shorter[i - 1] === longer[j - 1] ? 0 : 1;
      curr[i] = Math.min(
        prev[i] + 1,       // deletion
        curr[i - 1] + 1,   // insertion
        prev[i - 1] + cost, // substitution
      );
    }
    [prev, curr] = [curr, prev];
  }
  return prev[sn];
}

// ─── Similar-name helpers ─────────────────────────────────────────────────

const SUGGESTION_DISTANCE_CAP = 3;
/**
 * Upper bound on the requested tool name. Anything longer is rejected before
 * the O(n*m) Levenshtein pass (#3042 review, P2): a 128 KB request over ~30
 * tools would otherwise run hundreds of millions of comparisons and block
 * the server event loop. The repo documents 64 chars as the tool-name shape;
 * this matches the limit enforced by every published surface.
 */
export const SUGGESTION_REQUEST_MAX_LEN = 64;

export interface SuggestionCandidate {
  name: string;
  distance: number;
}

/**
 * Find the nearest registered tool names by Levenshtein distance.
 * Results are sorted by distance ascending then name ascending (deterministic).
 * Only names with distance <= {@link SUGGESTION_DISTANCE_CAP} are returned;
 * when no name is that close the caller falls back to listing the full set.
 */
export function nearestSuggestions(
  requested: string,
  registeredNames: readonly string[],
): SuggestionCandidate[] {
  // Defense in depth: the entry point already caps; this guards any direct
  // caller of the helper from an unbounded Levenshtein pass (issue #3042).
  if (requested.length > SUGGESTION_REQUEST_MAX_LEN) return [];
  const candidates: SuggestionCandidate[] = [];
  for (const name of registeredNames) {
    const distance = levenshtein(requested.toLowerCase(), name.toLowerCase());
    if (distance <= SUGGESTION_DISTANCE_CAP) {
      candidates.push({ name, distance });
    }
  }
  // Total comparator: distance asc, then name asc.
  candidates.sort((a, b) => {
    if (a.distance !== b.distance) return a.distance < b.distance ? -1 : 1;
    return a.name < b.name ? -1 : a.name > b.name ? 1 : 0;
  });
  return candidates;
}

/**
 * Build a human-readable "did you mean?" suggestion string.
 * When no close match is found, returns a fallback listing.
 */
function buildSuggestion(
  requested: string,
  registeredNames: readonly string[],
): string {
  const suggestions = nearestSuggestions(requested, registeredNames);
  if (suggestions.length === 0) {
    return `Registered tools: ${registeredNames.join(", ")}`;
  }
  return `Did you mean ${suggestions.map((s) => s.name).join(", ")}?`;
}

/**
 * Read a Zod type tag without asserting a shape.
 *
 * Zod keeps its discriminant at `_def.typeName`. Both hops are narrowed with
 * `in`/`typeof` rather than an inline cast, so a non-Zod object yields
 * `undefined` instead of a fabricated read.
 */
function zodTypeName(schema: unknown): string | undefined {
  // zod 4: schema internals live on `_zod.def.type` (v3 read `_def.typeName`).
  if (!(schema instanceof Object) || !("_zod" in schema)) return undefined;
  // SAFETY: the guard above established `_zod` exists; its `.def` carries the
  // discriminator string under `type`.
  const def = (schema as { _zod?: { def?: { type?: unknown } } })._zod?.def;
  // SAFETY: zod's `_zod.def.type` discriminator is always a string literal.
  const discriminator = def?.type;
  return discriminator === undefined ? undefined : String(discriminator);
}

/**
 * A zod schema node this module reflects over — any object the library
 * exposes as a schema (v4 marks them with `_zod`).
 */
/** Structural marker: every zod schema carries `_zod`. */
type ZodSchemaLike = { _zod?: unknown };

/**
 * A synthetic example value derived from a schema: a placeholder the SAME
 * schema accepts, so the error message can show a valid argument shape.
 */
type SchemaExample = string | number | boolean | null | readonly SchemaExample[] | { [key: string]: SchemaExample };

/**
 * Reverse-engineer ONE synthetic example value from a Zod schema type.
 * Returns a deterministic placeholder intended to round-trip through parse().
 */
function exampleFromSchema(schema: ZodSchemaLike): SchemaExample | undefined {
  switch (zodTypeName(schema)) {
    case "string":
      return "<string>";
    case "number":
      return 42;
    case "boolean":
      return true;
    case "nullable":
      return null;
    case "array":
      return [];
    case "optional":
      // Optional fields are omitted from the example rather than sent as null.
      return undefined;
    case "enum": {
      // v4 exposes accepted values as the public `.enum` record.
      if (!(schema instanceof Object) || !("enum" in schema)) return "<value>";
      // SAFETY: the guard established `.enum`; zod types it as a value record.
      const values = Object.values((schema as { enum: Record<string, string> }).enum);
      return values.length > 0 ? values[0] : "<value>";
    }
    case "object": {
      // v4 exposes `.shape` as a plain property on the object schema.
      if (!(schema instanceof Object) || !("shape" in schema)) return {};
      // SAFETY: object schemas expose their field schemas keyed by name.
      const fieldsByName = (schema as { shape: { [field: string]: ZodSchemaLike } }).shape;
      if (!(fieldsByName instanceof Object)) return {};
      const result: { [key: string]: SchemaExample } = {};
      for (const field of Object.getOwnPropertyNames(fieldsByName)) {
        if (!Object.hasOwn(fieldsByName, field)) continue;
        const schemaNode = fieldsByName[field];
        const value = exampleFromSchema(schemaNode);
        if (value !== undefined) result[field] = value;
      }
      return result;
    }
    default:
      return undefined;
  }
}
/**
 * Build an enriched "unknown tool" error message.
 *
 * @param requested - the tool name the caller used
 * @param registeredNames - ALL registered tool names (including aliases)
 */
export function unknownToolError(
  requested: string,
  registeredNames: readonly string[],
): string {
  // Cap the request before the suggestion pass: a 128 KB name would otherwise
  // pay O(n*m) per registered tool (issue #3042 review, P2). The cap matches
  // the documented tool-name shape; an over-long request is rejected with a
  // teaching message rather than a silent truncate.
  if (requested.length > SUGGESTION_REQUEST_MAX_LEN) {
    return `Unknown tool: name exceeds ${SUGGESTION_REQUEST_MAX_LEN} characters (got ${requested.length}).`;
  }
  const suggestion = buildSuggestion(requested, registeredNames);
  return `Unknown tool: ${requested}. ${suggestion}`;
}

/**
 * Build an enriched "invalid arguments" error message.
 *
 * The example is generated from the schema (never hand-written, so it cannot
 * drift) and is shown ONLY when it round-trips through that same schema. It
 * carries schema-derived fields only: injecting the tool name would add an
 * unrecognized property and fail a `.strict()` object (#3035 review finding).
 *
 * @param tool - the tool name that received the invalid args
 * @param zodError - the ZodError from parse()
 * @param schema - the original Zod schema, used to generate the example
 */
export function invalidArgsError(
  tool: string,
  zodError: ZodError,
  schema?: unknown,
): string {
  const issues = zodError.issues.map((issue) => {
    const path = issue.path.length > 0 ? issue.path.join(".") : "(root)";
    // `expected` exists only on the invalid_type / invalid_literal variants of
    // ZodIssue, so it is read through a presence check rather than assumed.
    const expected = "expected" in issue ? issue.expected : undefined;
    return expected === undefined
      ? `${path}: ${issue.message}`
      : `${path}: ${issue.message} (expected ${String(expected)})`;
  });
  let message = `Invalid arguments for "${tool}": ${issues.join("; ")}`;
  if (!schema) return message;

  const example = exampleFromSchema(schema);
  if (!example || typeof example !== "object" || Object.keys(example).length === 0) {
    return message;
  }

  // Withhold an example that cannot parse against its own schema: a
  // non-round-tripping example is misinformation, worse than none. Narrowed
  // with `in`/`typeof` rather than an inline cast so the shape is checked.
  let roundTrips = false;
  if (typeof schema === "object" && "safeParse" in schema) {
    const parser = schema.safeParse;
    if (typeof parser === "function") {
      try {
        const parsed: unknown = parser.call(schema, example);
        roundTrips =
          typeof parsed === "object"
          && parsed !== null
          && "success" in parsed
          && parsed.success === true;
      } catch {
        roundTrips = false;
      }
    }
  }

  return roundTrips ? `${message}. Example arguments: ${JSON.stringify(example)}` : message;
}

/**
 * @remnic/core — Dedup & Contradiction Detection
 *
 * Statement-level deduplication and contradiction detection
 * against existing memories. Can be used standalone or via curation.
 */

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { normalizeRecallTokenSet } from "../recall-tokenization.js";
import { ALL_CATEGORY_DIRS } from "../utils/category-dir.js";

// ── Types ────────────────────────────────────────────────────────────────────

export interface MemoryEntry {
  /** Memory ID */
  id: string;
  /** Content text */
  content: string;
  /** Category */
  category: string;
  /** File path (if known) */
  filePath?: string;
}

export interface DedupOptions {
  /** Memory root directory */
  memoryDir: string;
  /** Categories to scan (default: all) */
  categories?: string[];
  /** Similarity threshold for fuzzy matching (0-1, default: 0.85) */
  threshold?: number;
  /** Max memories to load (default: 10000) */
  maxLoad?: number;
}

export interface DedupResult {
  /** Total memories scanned */
  scanned: number;
  /** Duplicate pairs found */
  duplicates: DuplicatePair[];
  /** Duration in ms */
  durationMs: number;
}

export interface DuplicatePair {
  /** First memory */
  left: MemoryEntry;
  /** Second memory */
  right: MemoryEntry;
  /** Similarity score */
  similarity: number;
  /** Recommended action */
  action: "merge" | "keep_left" | "keep_right";
}

export interface ContradictionOptions {
  /** Memory root directory */
  memoryDir: string;
  /** Categories to scan (default: all) */
  categories?: string[];
  /** Max memories to load (default: 10000) */
  maxLoad?: number;
}

export interface ContradictionResult {
  /** Total memories scanned */
  scanned: number;
  /** Contradictions found */
  contradictions: ContradictionPair[];
  /** Duration in ms */
  durationMs: number;
}

export interface ContradictionPair {
  /** First statement */
  left: MemoryEntry;
  /** Contradicting statement */
  right: MemoryEntry;
  /** Severity */
  severity: "high" | "medium" | "low";
  /** Reason */
  reason: string;
}

// ── Main functions ───────────────────────────────────────────────────────────

const DEFAULT_DEDUP_THRESHOLD = 0.85;
const DEFAULT_MAX_LOAD = 10000;

function normalizeThreshold(value: number | undefined, defaultValue: number): number {
  return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= 1 ? value : defaultValue;
}

function normalizeMaxLoad(value: number | undefined, defaultValue: number): number {
  return typeof value === "number" && Number.isInteger(value) && value >= 0 ? value : defaultValue;
}

export function findDuplicates(options: DedupOptions): DedupResult {
  const startTime = Date.now();
  const { memoryDir } = options;
  const threshold = normalizeThreshold(options.threshold, DEFAULT_DEDUP_THRESHOLD);
  const maxLoad = normalizeMaxLoad(options.maxLoad, DEFAULT_MAX_LOAD);

  const memories = loadMemories(memoryDir, options.categories, maxLoad);
  const duplicates: DuplicatePair[] = [];

  // Compare all pairs (O(n^2) but bounded by maxLoad)
  for (let i = 0; i < memories.length; i++) {
    for (let j = i + 1; j < memories.length; j++) {
      const sim = computeSimilarity(memories[i].content, memories[j].content);
      if (sim >= threshold) {
        duplicates.push({
          left: memories[i],
          right: memories[j],
          similarity: sim,
          action: sim >= 0.98 ? "merge" : sim >= 0.9 ? "keep_right" : "keep_left",
        });
      }
    }
  }

  return {
    scanned: memories.length,
    duplicates,
    durationMs: Date.now() - startTime,
  };
}

export function findContradictions(options: ContradictionOptions): ContradictionResult {
  const startTime = Date.now();
  const { memoryDir } = options;
  const maxLoad = normalizeMaxLoad(options.maxLoad, DEFAULT_MAX_LOAD);

  const memories = loadMemories(memoryDir, options.categories, maxLoad);
  const contradictions: ContradictionPair[] = [];

  for (let i = 0; i < memories.length; i++) {
    for (let j = i + 1; j < memories.length; j++) {
      const contra = detectContradiction(memories[i], memories[j]);
      if (contra) {
        contradictions.push(contra);
      }
    }
  }

  return {
    scanned: memories.length,
    contradictions,
    durationMs: Date.now() - startTime,
  };
}

// ── Similarity computation ───────────────────────────────────────────────────

function computeSimilarity(a: string, b: string): number {
  const normA = normalize(a);
  const normB = normalize(b);
  const punctuationBoundariesA = embeddedPunctuationSignature(a);
  const punctuationBoundariesB = embeddedPunctuationSignature(b);

  // Compare punctuation and positions before normalization's exact/hash paths.
  if (punctuationBoundariesA !== punctuationBoundariesB) return 0;

  if (normA === normB) return 1;

  if (hashContent(normA) === hashContent(normB)) return 0.99;
  if (normA.length > 50 && normB.length > 50) {
    if (normA.includes(normB.slice(0, 40)) || normB.includes(normA.slice(0, 40))) {
      return 0.9;
    }
  }

  const wordsA = tokenizeForSimilarity(normA);
  const wordsB = tokenizeForSimilarity(normB);
  const intersection = new Set([...wordsA].filter((w) => wordsB.has(w)));
  const union = new Set([...wordsA, ...wordsB]);

  if (union.size === 0) return 0;
  return intersection.size / union.size;
}

function embeddedPunctuationSignature(text: string): string {
  const chars = [...text.normalize("NFC")];
  const significant = /[\p{L}\p{M}\p{N}]/u;
  const ignored = /[\s']/u;
  const boundaries: string[] = [];
  let position = 0;
  for (let index = 0; index < chars.length;) {
    const char = chars[index];
    if (char === undefined) break;
    if (significant.test(char)) {
      position++;
      index++;
      continue;
    }
    if (ignored.test(char)) {
      index++;
      continue;
    }
    const start = index;
    while (index < chars.length) {
      const next = chars[index];
      if (next === undefined || significant.test(next) || ignored.test(next)) break;
      index++;
    }
    const before = chars[start - 1];
    const after = chars[index];
    if (before && after && significant.test(before) && significant.test(after)) {
      boundaries.push(`${position}:${chars.slice(start, index).join("")}`);
    }
  }
  return boundaries.join("\u0000");
}

function normalize(text: string): string {
  return text
    .normalize("NFC")
    .toLowerCase()
    .replace(/[^\p{ASCII}\p{L}\p{M}\p{N}\s']/gu, " ")
    .replace(/[^\p{L}\p{M}\p{N}\s']/gu, "")
    .replace(/\s+/g, " ")
    .trim();
}

function tokenizeForSimilarity(text: string): Set<string> {
  if (/\p{Script=Hangul}/u.test(text)) {
    const tokens = normalizeRecallTokenSet(text);
    for (const segment of text.match(/\p{Script=Hangul}+/gu) ?? []) {
      const chars = [...segment];
      for (const size of [1, 2, 3, 4]) {
        for (let index = 0; index <= chars.length - size; index += 1) {
          tokens.add(chars.slice(index, index + size).join(""));
        }
      }
    }
    return tokens;
  }
  if (/[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}]/u.test(text)) {
    return normalizeRecallTokenSet(text);
  }
  return text.length === 0 ? new Set() : new Set(text.split(/\s+/));
}

// ── Contradiction detection ──────────────────────────────────────────────────

export const NEGATION_WORDS = new Set([
  "not",
  "don't",
  "doesn't",
  "isn't",
  "aren't",
  "won't",
  "can't",
  "cannot",
  "never",
  "no",
  "none",
  "neither",
  "nor",
  "nothing",
  "nowhere",
]);

function detectContradiction(a: MemoryEntry, b: MemoryEntry): ContradictionPair | null {
  const normA = normalize(a.content);
  const normB = normalize(b.content);

  // Check if one has negation and the other doesn't
  const aHasNegation = containsNegation(normA);
  const bHasNegation = containsNegation(normB);

  if (aHasNegation === bHasNegation) return null;

  // Strip negation and compare core content
  const strippedA = stripNegation(normA);
  const strippedB = stripNegation(normB);

  const sim = computeSimilarity(strippedA, strippedB);
  if (sim < 0.7) return null;

  // Check for opposite quantifiers
  const oppQuantifiers = [
    ["always", "never"],
    ["all", "none"],
    ["every", "no"],
    ["must", "must not"],
    ["should", "should not"],
    ["can", "cannot"],
  ];

  for (const [pos, neg] of oppQuantifiers) {
    if (
      (a.content.toLowerCase().includes(pos) && b.content.toLowerCase().includes(neg)) ||
      (a.content.toLowerCase().includes(neg) && b.content.toLowerCase().includes(pos))
    ) {
      return {
        left: a,
        right: b,
        severity: "high",
        reason: `Opposite quantifiers: "${pos}" vs "${neg}"`,
      };
    }
  }

  return {
    left: a,
    right: b,
    severity: sim >= 0.85 ? "high" : "medium",
    reason: "Negated version of similar content",
  };
}

function containsNegation(text: string): boolean {
  const words = text.split(/\s+/);
  return words.some((w) => NEGATION_WORDS.has(w));
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// Single vocabulary source: the strip pattern is derived from NEGATION_WORDS,
// never hand-maintained. Keyed on the alternation content so any vocabulary
// change (not just a size change) rebuilds the pattern.
let stripNegationPattern: RegExp | null = null;
let stripNegationPatternSource: string | null = null;

function stripNegationRegex(): RegExp {
  const alternation = [...NEGATION_WORDS]
    .sort((a, b) => b.length - a.length)
    .map(escapeRegExp)
    .join("|");
  if (stripNegationPattern === null || stripNegationPatternSource !== alternation) {
    stripNegationPattern = new RegExp(`\\b(?:${alternation})\\b`, "gi");
    stripNegationPatternSource = alternation;
  }
  return stripNegationPattern;
}

function stripNegation(text: string): string {
  return text
    .replace(stripNegationRegex(), "")
    .replace(/\s+/g, " ")
    .trim();
}

// ── Memory loading ───────────────────────────────────────────────────────────

function loadMemories(memoryDir: string, categories?: string[], maxLoad = 10000): MemoryEntry[] {
  const result: MemoryEntry[] = [];
  const allCategories = categories ?? ALL_CATEGORY_DIRS;
  if (!fs.existsSync(memoryDir)) return result;
  const memoryRootReal = fs.realpathSync(memoryDir);

  for (const category of allCategories) {
    if (result.length >= maxLoad) break;

    const dir = path.join(memoryDir, category);
    if (!fs.existsSync(dir)) continue;
    const categoryStat = fs.lstatSync(dir);
    if (categoryStat.isSymbolicLink()) {
      throw new Error(`Refusing to scan symlinked memory category directory: ${dir}`);
    }
    if (!categoryStat.isDirectory()) continue;
    const categoryRootReal = fs.realpathSync(dir);
    assertPathInsideRoot(memoryRootReal, categoryRootReal, dir);

    walkMdFiles(dir, memoryRootReal, categoryRootReal, (filePath) => {
      if (result.length >= maxLoad) return;

      const content = readFileSafe(filePath, memoryRootReal, categoryRootReal);
      if (!content) return;

      const fm = parseFrontmatter(content);
      const body = extractBody(content);
      if (!fm?.id || !body) return;

      result.push({
        id: fm.id as string,
        content: body,
        category: (fm.category as string) ?? category.slice(0, -1),
        filePath,
      });
    });
  }

  return result;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function hashContent(content: string): string {
  return crypto.createHash("sha256").update(content).digest("hex").slice(0, 16);
}

function readFileSafe(filePath: string, memoryRootReal: string, categoryRootReal: string): string | null {
  try {
    const fileStat = fs.lstatSync(filePath);
    if (fileStat.isSymbolicLink()) {
      throw new Error(`Refusing to read symlinked memory file: ${filePath}`);
    }
    const fileReal = fs.realpathSync(filePath);
    assertPathInsideRoot(memoryRootReal, fileReal, filePath);
    assertPathInsideRoot(categoryRootReal, fileReal, filePath);
    return fs.readFileSync(filePath, "utf8");
  } catch {
    return null;
  }
}

function parseFrontmatter(content: string): Record<string, unknown> | null {
  const match = content.match(/^---\n([\s\S]*?)\n---/);
  if (!match) return null;

  const fm: Record<string, unknown> = {};
  for (const line of match[1].split("\n")) {
    const colonIdx = line.indexOf(":");
    if (colonIdx === -1) continue;
    const key = line.slice(0, colonIdx).trim();
    const value = line.slice(colonIdx + 1).trim();
    fm[key] = value;
  }
  return fm;
}

function extractBody(content: string): string {
  const match = content.match(/^---\n[\s\S]*?\n---\n([\s\S]*)/);
  return match ? match[1].trim() : content.trim();
}

function assertPathInsideRoot(rootReal: string, targetReal: string, sourcePath: string): void {
  const rel = path.relative(rootReal, targetReal);
  if (rel === "" || (!rel.startsWith("..") && !path.isAbsolute(rel))) {
    return;
  }
  throw new Error(`Refusing to scan memory path outside root: ${sourcePath}`);
}

function walkMdFiles(
  dir: string,
  memoryRootReal: string,
  categoryRootReal: string,
  callback: (filePath: string) => void
): void {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name);
    const entryStat = fs.lstatSync(fullPath);
    if (entryStat.isSymbolicLink()) {
      throw new Error(`Refusing to scan symlinked memory path: ${fullPath}`);
    }
    const entryReal = fs.realpathSync(fullPath);
    assertPathInsideRoot(memoryRootReal, entryReal, fullPath);
    assertPathInsideRoot(categoryRootReal, entryReal, fullPath);
    if (entryStat.isDirectory()) {
      walkMdFiles(fullPath, memoryRootReal, categoryRootReal, callback);
    } else if (entry.name.endsWith(".md")) {
      callback(fullPath);
    }
  }
}

