/**
 * Gateway/task LLM client. In `modelSource: "gateway"` this is the primary
 * configured path (taskModelChain / agent persona), not a secondary recovery
 * client. The class name stays `FallbackLlmClient` because it is imported
 * widely; prefer the `TaskLlmClient` alias in new code. Issue #2967.
 */
export class FallbackLlmClient {
  private gatewayConfig: GatewayConfig | undefined;
  private runtimeContext: FallbackLlmRuntimeContext;

  constructor(
    gatewayConfig?: GatewayConfig,
    runtimeContext: FallbackLlmRuntimeContext = {},
  ) {
    this.gatewayConfig = gatewayConfig;
    this.runtimeContext = {
      ...runtimeContext,
      workspaceDir:
        normalizeRuntimePath(runtimeContext.workspaceDir) ??
        readGatewayWorkspaceDir(gatewayConfig) ??
        defaultOpenClawWorkspaceDir(),
    };
  }

  /**
   * Check if fallback is available (gateway config has at least one model).
   */
  isAvailable(agentIdOrOptions?: string | FallbackLlmAvailabilityOptions): boolean {
    const options = typeof agentIdOrOptions === "string"
      ? { agentId: agentIdOrOptions }
      : (agentIdOrOptions ?? {});
    const models = this.getModelChain(options.agentId, undefined, options.modelChain);
    return models.length > 0;
  }

  /**
   * Make a chat completion request using the gateway's default AI chain.
   * Tries primary first, then each fallback in order.
   * When agentId is provided, uses that agent persona's model chain instead of defaults.
   */
  async chatCompletion(
    messages: Array<{ role: "system" | "user" | "assistant"; content: string }>,
    options: FallbackLlmOptions = {},
  ): Promise<FallbackLlmResponse | null> {
    const outcome = await this.completeChat(messages, options);
    return outcome.ok ? outcome.response : null;
  }

  /**
   * Same transport walk as chatCompletion, but tagged so structured parse can
   * tell timeout / empty / HTTP error apart instead of collapsing them to null.
   */
  private async completeChat(
    messages: Array<{ role: "system" | "user" | "assistant"; content: string }>,
    options: FallbackLlmOptions = {},
  ): Promise<ChatCompletionOutcome> {
    const models = this.getModelChain(
      options.agentId,
      options.model,
      options.modelChain,
      options.includeDefaultModelFallback,
    );
    if (models.length === 0) {
      log.warn("task LLM: no models configured in gateway");
      return { ok: false, failure: { failureReason: "no_models", errorClass: "no_models" } };
    }
    options = withCodexRuntimeShutdown(options, this.runtimeContext.codexSubscriptionRunner);

    let lastFailure: Omit<StructuredParseFailure, "result"> = {
      failureReason: "http_error",
      errorClass: "network",
    };

    const recordFailure = (
      failure: Omit<StructuredParseFailure, "result">,
      attemptedModel?: string,
    ): void => {
      lastFailure = attemptedModel ? { ...failure, attemptedModel } : failure;
    };

    const throwIfCallerAborted = (signal: AbortSignal | undefined): void => {
      if (!signal?.aborted) return;
      const reason = abortReason(signal);
      if (isTimeoutError(reason) && !options.signal?.aborted) {
        recordFailure({ failureReason: "timeout", errorClass: "timeout" });
        return;
      }
      throw reason;
    };

    const runChain = async (
      initialOptions: FallbackLlmOptions,
    ): Promise<FallbackLlmResponse | null> => {
      let runOptions = initialOptions;
      let lastRejectedResponse: FallbackLlmResponse | null = null;
      let lastError: unknown;
      let terminalError: unknown;
      // Try each model in the chain
      for (let i = 0; i < models.length; i++) {
        if (runOptions.signal?.aborted) {
          throwIfCallerAborted(runOptions.signal);
          if (lastFailure.failureReason === "timeout") return null;
        }
        const model = models[i];
        const isFallback = i > 0;

        try {
          const result = await this.tryModel(model, messages, runOptions);
          if (result?.content) {
            const response = {
              content: result.content,
              modelUsed: model.modelString,
              usage: result.usage,
            };
            if (runOptions.acceptResponse && !runOptions.acceptResponse(response)) {
              lastRejectedResponse = response;
              log.debug(`task LLM: ${model.modelString} returned rejected output, trying next...`);
              continue;
            }
            if (isFallback) {
              log.debug(`task LLM: succeeded using ${model.modelString} (fallback ${i})`);
            }
            return response;
          }
          recordFailure({ failureReason: "empty", errorClass: "empty" }, model.modelString);
        } catch (err) {
          if (isTerminalCodexSubscriptionError(err) && runOptions.signal?.aborted) {
            throw err;
          }
          if (runOptions.signal?.aborted) {
            throwIfCallerAborted(runOptions.signal);
            if (lastFailure.failureReason === "timeout") return null;
          }
          lastError = err;
          if (
            (runOptions.jsonSchema || runOptions.responsesJsonSchema) &&
            isUnsupportedJsonSchemaError(err)
          ) {
            log.debug(`task LLM: ${model.modelString} rejected native JSON schema; retrying without it`);
            // Degrade to prompt-only for the REST of the chain too, so an
            // N-model chain where every provider rejects structured output
            // costs N+1 requests instead of 2N.
            runOptions = {
              ...runOptions,
              jsonSchema: undefined,
              responsesJsonSchema: undefined,
            };
            try {
              const result = await this.tryModel(model, messages, runOptions);
              if (result?.content) {
                const response = {
                  content: result.content,
                  modelUsed: model.modelString,
                  usage: result.usage,
                };
                if (!runOptions.acceptResponse || runOptions.acceptResponse(response)) {
                  return response;
                }
                lastRejectedResponse = response;
                log.debug(`task LLM: ${model.modelString} unstructured retry output rejected by acceptResponse, trying next model...`);
                continue;
              }
              recordFailure({ failureReason: "empty", errorClass: "empty" }, model.modelString);
            } catch (retryError) {
              if (isTerminalCodexSubscriptionError(retryError) && runOptions.signal?.aborted) {
                throw retryError;
              }
              if (runOptions.signal?.aborted) {
                throwIfCallerAborted(runOptions.signal);
                if (lastFailure.failureReason === "timeout") return null;
              }
              lastError = retryError;
              const retryClassified = classifyThrownProviderError(retryError);
              recordFailure(retryClassified, model.modelString);
              const retryErrorMsg = runOptions.redactProviderErrors
                ? "provider error details redacted"
                : retryError instanceof Error
                  ? retryError.message
                  : String(retryError);
              log.debug(
                `task LLM: ${model.modelString} unstructured retry failed (${retryErrorMsg})`,
              );
              if (isTerminalCodexSubscriptionError(retryError)) {
                terminalError = retryError;
              }
            }
            continue;
          }
          const classified = classifyThrownProviderError(err);
          recordFailure(classified, model.modelString);
          const errorMsg = runOptions.redactProviderErrors
            ? "provider error details redacted"
            : err instanceof Error
              ? err.message
              : String(err);
          log.debug(`task LLM: ${model.modelString} failed (${errorMsg}), trying next...`);
          if (isTerminalCodexSubscriptionError(err)) {
            terminalError = err;
          }
          // Continue to next model in chain
        }
      }

      log.warn(`task LLM: all ${models.length} models in chain failed`);
      if (options.failureDiag && lastError !== undefined && !lastRejectedResponse) {
        options.failureDiag.lastError = lastError;
      }
      // A terminal typed provider failure must reach the caller when the
      // chain is exhausted — the documented timeout/re-login guidance
      // depends on it (issue #2833).
      if (terminalError !== undefined) {
        throw terminalError;
      }
      return lastRejectedResponse;
    };

    const toOutcome = (response: FallbackLlmResponse | null): ChatCompletionOutcome => {
      if (response) return { ok: true, response };
      return { ok: false, failure: lastFailure };
    };

    if (typeof options.timeoutMs === "number") {
      if (options.timeoutMs <= 0) {
        log.warn("task LLM: timed out before request started");
        return { ok: false, failure: { failureReason: "timeout", errorClass: "timeout" } };
      }
      const controller = new AbortController();
      const onCallerAbort = (): void => {
        controller.abort(abortReason(options.signal));
      };
      options.signal?.addEventListener("abort", onCallerAbort, { once: true });
      if (options.signal?.aborted) onCallerAbort();
      const timedOptions = { ...options, signal: controller.signal };
      const chain = runChain(timedOptions);
      const guarded = chain.catch((err) => {
        if (isTerminalCodexSubscriptionError(err)) throw err;
        return null;
      });
      try {
        const timeoutError = Object.assign(
          new Error(`task LLM timed out after ${options.timeoutMs}ms`),
          { name: "TimeoutError" },
        );
        const outcome = await raceFallbackLlmDeadline(
          guarded,
          options.timeoutMs,
          () => {
            log.warn(`task LLM: timed out after ${options.timeoutMs}ms`);
            recordFailure({ failureReason: "timeout", errorClass: "timeout" });
            controller.abort(timeoutError);
            if (options.failureDiag) options.failureDiag.lastError = timeoutError;
          },
          models.some((m) => m.providerConfig.api === "codex-cli") ? codexDeadlineHeadroomMs(options.timeoutMs) : 0,
        );
        if (outcome.timedOut) {
          return { ok: false, failure: { failureReason: "timeout", errorClass: "timeout" } };
        }
        return toOutcome(outcome.value);
      } finally {
        options.signal?.removeEventListener("abort", onCallerAbort);
      }
    }

    return toOutcome(await runChain(options));
  }

  /**
   * Make a request with structured output (Zod schema).
   * Returns parsed JSON or null on failure.
   */
  async parseWithSchema<T>(
    messages: Array<{ role: "system" | "user" | "assistant"; content: string }>,
    schema: { parse: (data: unknown) => T },
    options: FallbackLlmOptions = {},
  ): Promise<T | null> {
    const detailed = await this.parseWithSchemaDetailed(messages, schema, options);
    return detailed?.result ?? null;
  }

  /**
   * Like parseWithSchema but also returns the model that was used,
   * so callers can emit accurate trace events.
   */
  async parseWithSchemaDetailed<T>(
    messages: Array<{ role: "system" | "user" | "assistant"; content: string }>,
    schema: { parse: (data: unknown) => T },
    options: FallbackLlmOptions = {},
  ): Promise<StructuredParseResult<T>> {
    let outcome: ChatCompletionOutcome;
    try {
      outcome = await this.completeChat(messages, options);
    } catch (err) {
      // Caller aborts must propagate (e.g. recall planner cancellation) — do
      // not swallow them as a provider failure, or abort-driven callers lose
      // cancellation and treat it as an extraction error (codex review).
      // Terminal codex-subscription failures propagate for the same reason:
      // their TimeoutError/auth guidance is the documented contract.
      if (options.signal?.aborted || isTerminalCodexSubscriptionError(err)) throw err;
      if (isTimeoutError(err)) {
        return { result: null, failureReason: "timeout", errorClass: "timeout" };
      }
      log.warn("task LLM: chatCompletion threw during structured parse:", err);
      return { result: null, ...classifyThrownProviderError(err) };
    }
    if (!outcome.ok) {
      return { result: null, ...outcome.failure };
    }
    const response = outcome.response;
    if (!response.content) {
      return {
        result: null,
        failureReason: "empty",
        attemptedModel: response.modelUsed,
        errorClass: "empty",
      };
    }

    try {
      const candidates = extractJsonCandidates(response.content);
      let sawJson = false;
      let sawSchemaReject = false;
      for (const c of candidates) {
        let parsed: unknown;
        try {
          parsed = JSON.parse(c);
          sawJson = true;
        } catch {
          continue;
        }
        try {
          return { result: schema.parse(parsed), modelUsed: response.modelUsed };
        } catch {
          sawSchemaReject = true;
        }
      }
      if (sawSchemaReject) {
        return {
          result: null,
          failureReason: "schema_rejection",
          attemptedModel: response.modelUsed,
          errorClass: "schema_rejection",
        };
      }
      return {
        result: null,
        failureReason: "empty",
        attemptedModel: response.modelUsed,
        errorClass: "empty",
      };
    } catch (err) {
      log.warn("task LLM: failed to parse structured output:", err);
      return {
        result: null,
        failureReason: "empty",
        attemptedModel: response.modelUsed,
        errorClass: "empty",
      };
    }
  }

  /**
   * Get the full model chain from gateway config.
   * Returns array of models in order: [primary, fallback1, fallback2, ...]
   *
   * When modelChainOverride is provided, uses it instead of any configured
   * agent/default chain. Otherwise, when agentId is provided, looks up the
   * matching entry in agents.list[] and uses that persona's model chain.
   * Falls back to agents.defaults.model if agentId is not found or not provided.
   */
  private getModelChain(
    agentId?: string,
    modelOverride?: string,
    modelChainOverride?: AgentPersonaModelConfig,
    includeDefaultModelFallback = true,
  ): ModelRef[] {
    const chain: ModelRef[] = [];
    const providers = this.gatewayConfig?.models?.providers ?? {};

    // Resolve the model config: explicit task chain, agent persona chain, or global defaults
    let modelConfig: AgentPersonaModelConfig | undefined;

    if (modelChainOverride?.primary) {
      modelConfig = modelChainOverride;
      log.debug("task LLM: using explicit model chain override");
    } else if (modelChainOverride) {
      log.warn("task LLM: ignoring explicit model chain override without primary model");
    }

    if (!modelConfig && agentId) {
      const persona = this.gatewayConfig?.agents?.list?.find(
        (a) => a.id === agentId,
      );
      if (persona?.model) {
        modelConfig = persona.model;
        log.debug(`task LLM: using agent persona "${agentId}" model chain`);
      } else {
        log.warn(
          `task LLM: agent persona "${agentId}" not found or has no model config, falling back to defaults`,
        );
      }
    }

    if (!modelConfig) {
      modelConfig = this.gatewayConfig?.agents?.defaults?.model;
    }

    // Build list of model strings: primary + fallbacks
    const modelStrings: string[] = [];

    const addModelString = (value: unknown): void => {
      if (typeof value !== "string") return;
      const trimmed = value.trim();
      if (trimmed.length > 0 && !modelStrings.includes(trimmed)) {
        modelStrings.push(trimmed);
      }
    };

    addModelString(modelOverride);
    addModelString(modelConfig?.primary);

    if (Array.isArray(modelConfig?.fallbacks)) {
      for (const fb of modelConfig.fallbacks) {
        addModelString(fb);
      }
    }

    // Parse each model string and look up provider config
    for (const modelString of modelStrings) {
      const modelRef = this.parseModelString(modelString, providers);
      if (modelRef) {
        chain.push(modelRef);
      }
    }

    // Implicit last-resort: when a task-specific modelChain override is active,
    // append the gateway default model so a stale or exhausted taskModelChain
    // never leaves the chain empty — Remnic should never be the reason a chat is
    // interrupted by a flush failure. Keyed on `modelChainOverride?.primary` —
    // the SAME activation condition chain resolution uses above — so a
    // primary-less override (e.g. {}) that falls through to a persona/default
    // chain does NOT get the default appended (gotcha #39). Issue #1365 / PR #1370.
    if (includeDefaultModelFallback && modelChainOverride?.primary && modelStrings.length > 0) {
      // Append the FULL gateway default chain (primary + fallbacks), not just
      // the primary — if the default primary is also unreachable, a listed
      // default fallback may still succeed (cursor review #1425).
      const defaults = this.gatewayConfig?.agents?.defaults?.model;
      const defaultStrings: string[] = [
        ...(typeof defaults?.primary === "string" ? [defaults.primary] : []),
        ...(Array.isArray(defaults?.fallbacks) ? defaults.fallbacks : []),
      ];
      for (const candidate of defaultStrings) {
        if (typeof candidate !== "string") continue;
        const trimmed = candidate.trim();
        if (trimmed.length === 0 || modelStrings.includes(trimmed)) continue;
        const defaultRef = this.parseModelString(trimmed, providers);
        if (defaultRef) {
          chain.push(defaultRef);
          modelStrings.push(trimmed); // keep dedupe correct for later default fallbacks
          log.debug(
            `task LLM: appended gateway default model "${trimmed}" as implicit last resort`,
          );
        }
      }
    }

    return chain;
  }

  /**
   * Parse a "provider/model" string and look up its config.
   */
  private parseModelString(
    modelString: string,
    providers: Record<string, ModelProviderConfig>,
  ): ModelRef | null {
    // Parse "provider/model" format (e.g., "openai/gpt-5.5", "anthropic/claude-opus-4-6")
    const parts = modelString.split("/");
    if (parts.length < 2) {
      log.warn(`task LLM: invalid model format: ${modelString}`);
      return null;
    }

    const requestedProviderId = parts[0];
    const modelId = parts.slice(1).join("/"); // Handle cases like "openai/gpt-5.5"

    // Respect the active gateway config first so profile-local overrides and
    // credentials win. Fall back to the materialized models.json only when
    // the provider is absent from the loaded config (for built-in providers
    // registered by the gateway at runtime).
    const resolvedProvider = this.resolveProviderConfig(requestedProviderId, providers);
    const providerConfig = resolvedProvider?.config;
    if (!providerConfig) {
      log.warn(
        `task LLM: provider not found: ${requestedProviderId} ` +
        `(tried: ${this.providerResolutionCandidates(requestedProviderId).join(", ")})`,
      );
      return null;
    }

    return {
      providerId: resolvedProvider.providerId,
      modelId,
      providerConfig,
      modelString,
    };
  }

  private resolveProviderConfig(
    providerId: string,
    providers: Record<string, ModelProviderConfig>,
  ): { providerId: string; config: ModelProviderConfig } | null {
    const candidates = this.providerResolutionCandidates(providerId);
    const aliasCandidates = candidates.filter((candidate) => candidate !== providerId);
    const fallbackCandidates = LEGACY_PROVIDER_IDS.has(providerId)
      ? [...aliasCandidates, providerId]
      : [providerId, ...aliasCandidates];
    for (const candidate of candidates) {
      const config = providers[candidate];
      if (config) {
        if (candidate !== providerId) {
          log.debug(`task LLM: provider "${providerId}" resolved via alias "${candidate}"`);
        }
        return { providerId: candidate, config };
      }
    }
    for (const candidate of fallbackCandidates) {
      const config = this.resolveFromModelsJson(candidate);
      if (config) {
        if (candidate !== providerId) {
          log.debug(`task LLM: provider "${providerId}" resolved via models.json alias "${candidate}"`);
        }
        return { providerId: candidate, config };
      }
      const builtInConfig = BUILT_IN_PROVIDER_FALLBACKS[candidate];
      if (builtInConfig) {
        if (candidate === providerId) {
          log.debug(`task LLM: provider "${providerId}" resolved from built-in defaults`);
          return { providerId, config: builtInConfig };
        }
        log.debug(`task LLM: provider "${providerId}" resolved via built-in alias "${candidate}"`);
        return { providerId: candidate, config: builtInConfig };
      }
    }
    return null;
  }

  private providerResolutionCandidates(providerId: string): string[] {
    const candidates = [providerId, ...(PROVIDER_ALIASES[providerId] ?? [])];
    return [...new Set(candidates)];
  }

  /**
   * Look up a provider from the gateway's materialized models.json, which
   * contains all providers including built-in ones (openai-codex, google-vertex,
   * etc.) that aren't in the user's openclaw.json but are registered by
   * gateway plugins. Returns null if the provider isn't found there either.
   */
  private resolveFromModelsJson(providerId: string): ModelProviderConfig | null {
    const allProviders = loadModelsJsonProviders();
    const config = allProviders[providerId];
    if (config) {
      log.debug(`task LLM: resolved provider "${providerId}" from models.json (api: ${config.api ?? "default"})`);
      return config;
    }
    return null;
  }

  /**
   * Try to call a single model.
   *
   * Uses the gateway's native getRuntimeAuthForModel when available — this
   * handles all provider-specific auth transforms (OAuth token exchange,
   * base URL overrides for codex/copilot/etc.) through the same codepath
   * the gateway itself uses. Falls back to resolveProviderApiKey for
   * simpler providers or when the runtime module isn't loaded.
   */
  private async tryModel(
    model: ModelRef,
    messages: Array<{ role: "system" | "user" | "assistant"; content: string }>,
    options: FallbackLlmOptions,
  ): Promise<{ content: string; usage?: FallbackLlmResponse["usage"] } | null> {
    const codexResult = await tryCodexSubscriptionProvider(
      model,
      messages,
      options,
      () => this.resolveFallbackApiKey(model),
      this.runtimeContext.codexSubscriptionRunner,
    );
    if (codexResult !== undefined) return codexResult;
    const runtimeAuth = await this.resolveRuntimeAuth(model);
    const effectiveBaseUrl = runtimeAuth?.baseUrl ?? model.providerConfig.baseUrl;
    const resolvedApiKey = runtimeAuth?.apiKey ?? await this.resolveFallbackApiKey(model);

    // If the raw key looks like an unresolved secret ref and resolution fails,
    // skip this provider entirely so the chain falls through to the next.
    const rawKey = model.providerConfig.apiKey;
    const needsResolution = rawKey === "secretref-managed" || (typeof rawKey === "object" && rawKey !== null);
    if (needsResolution && !resolvedApiKey) {
      throw new Error(`API key for provider "${model.providerId}" could not be resolved from secret ref`);
    }

    const effectiveConfig: ModelProviderConfig = {
      ...model.providerConfig,
      baseUrl: effectiveBaseUrl,
      ...(resolvedApiKey ? { apiKey: resolvedApiKey } : {}),
    };

    if (model.providerConfig.api === "anthropic-messages") {
      return await this.callAnthropic(effectiveConfig, model.modelId, messages, options);
    }

    if (model.providerConfig.api === "ollama-chat") {
      return await this.callOllamaChat(effectiveConfig, model.modelId, messages, options);
    }

    const wanted = Math.floor(options.reasoningHeadroomTokens ?? 0);
    const headroom = Number.isFinite(wanted) ? Math.max(0, wanted) : 0; // NaN and Infinity add nothing
    const capped = options.maxTokens === undefined ? options : { ...options, maxTokens: options.maxTokens + headroom };

    if (
      model.providerConfig.api === "openai-responses" ||
      model.providerConfig.api === "openai-codex-responses" ||
      model.providerConfig.api === "azure-openai-responses"
    ) {
      return await this.callOpenAIResponses(effectiveConfig, model.modelId, messages, capped);
    }

    // For OpenAI-compatible chat-completions APIs (openai-completions,
    // ollama, etc.) and unknown formats, use chat completions — the gateway's
    // runtime auth resolver returns request-ready base URL and credentials for
    // most providers.
    return await this.callOpenAI(
      effectiveConfig,
      model.modelId,
      messages,
      capped,
      shouldAssumeOpenAiChatCompletions(effectiveConfig.baseUrl),
    );
  }

  /**
   * Resolve request-ready auth through the gateway's native runtime, which
   * handles provider-specific transforms (OAuth token exchange for codex/copilot,
   * base URL rewrite, etc.). Returns null if the runtime isn't available.
   */
  private async resolveRuntimeAuth(
    model: ModelRef,
  ): Promise<{ apiKey?: string; baseUrl?: string } | null> {
    try {
      const getRuntimeAuth = await getGatewayRuntimeAuthForModel({
        getRuntimeAuthForModel: this.runtimeContext.getRuntimeAuthForModel,
      });
      if (!getRuntimeAuth) return null;

      const result = await getRuntimeAuth({
        model: {
          provider: model.providerId,
          id: model.modelId,
          api: model.providerConfig.api,
          baseUrl: model.providerConfig.baseUrl,
        },
        cfg: this.gatewayConfig,
        workspaceDir: this.runtimeContext.workspaceDir,
      });

      if (result?.apiKey || result?.baseUrl) {
        log.debug(
          `task LLM: resolved runtime auth for "${model.modelString}" (source: ${result.source ?? "unknown"}, mode: ${result.mode ?? "unknown"})`,
        );
        return { apiKey: result.apiKey, baseUrl: result.baseUrl };
      }
    } catch (err) {
      log.debug(
        `task LLM: gateway runtime auth failed for "${model.modelString}": ${err instanceof Error ? err.message : String(err)}`,
      );
    }
    return null;
  }

  /**
   * Resolve API key through the existing provider-level resolution (env vars,
   * secret refs, etc.). Used as fallback when gateway runtime auth isn't available.
   */
  private async resolveFallbackApiKey(model: ModelRef): Promise<string | undefined> {
    return resolveProviderApiKey(
      model.providerId,
      model.providerConfig.apiKey,
      this.gatewayConfig,
      this.runtimeContext.agentDir,
      {
        resolveApiKeyForProvider: this.runtimeContext.resolveApiKeyForProvider,
      },
    );
  }

  /**
   * Call OpenAI-compatible API.
   */
  private async callOpenAI(
    config: ModelProviderConfig,
    modelId: string,
    messages: Array<{ role: "system" | "user" | "assistant"; content: string }>,
    options: FallbackLlmOptions,
    assumeOpenAI: boolean,
  ): Promise<{ content: string; usage?: FallbackLlmResponse["usage"] } | null> {
    const base = config.baseUrl.replace(/\/$/, "");
    const url = base.endsWith("/v1")
      ? `${base}/chat/completions`
      : `${base}/v1/chat/completions`;

    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      ...config.headers,
    };

    // Handle auth — apiKey is already resolved to a string by tryModel()
    if (config.apiKey && typeof config.apiKey === "string") {
      if (config.authHeader !== false) {
        headers["Authorization"] = `Bearer ${config.apiKey}`;
      }
    }

    const body = {
      model: modelId,
      messages,
      ...buildChatCompletionTemperature(modelId, options.temperature ?? 0.3, {
        assumeOpenAI,
      }),
      ...buildChatCompletionTokenLimit(modelId, options.maxTokens ?? 4096, {
        assumeOpenAI,
      }),
      ...(options.jsonSchema
        ? {
            response_format: {
              type: "json_schema",
              json_schema: {
                name: options.jsonSchema.name,
                strict: options.jsonSchema.strict ?? false,
                schema: options.jsonSchema.schema,
              },
            },
          }
        : {}),
    };

    const response = await fetch(url, {
      method: "POST",
      headers,
      signal: options.signal,
      body: JSON.stringify(body),
    });

    if (!response.ok) {
      const error = await response.text();
      throw Object.assign(new Error(`OpenAI API error: ${response.status} ${error}`), { status: response.status });
    }

    const data = (await response.json()) as {
      choices: Array<{
        message: {
          content: string;
        };
      }>;
      usage?: {
        prompt_tokens?: number;
        completion_tokens?: number;
        total_tokens?: number;
      };
    };

    const content = data.choices?.[0]?.message?.content;
    if (!content) {
      throw new Error("Empty response from OpenAI API");
    }

    return {
      content,
      usage: data.usage
        ? {
            inputTokens: data.usage.prompt_tokens,
            outputTokens: data.usage.completion_tokens,
            totalTokens: data.usage.total_tokens,
          }
        : undefined,
    };
  }

  /**
   * Call Ollama's native /api/chat transport. This lets benchmark-isolated
   * gateway configs route Remnic's own internal LLM calls to Ollama Cloud
   * without requiring an OpenAI-compatible shim.
   */
  private async callOllamaChat(
    config: ModelProviderConfig,
    modelId: string,
    messages: Array<{ role: "system" | "user" | "assistant"; content: string }>,
    options: FallbackLlmOptions,
  ): Promise<{ content: string; usage?: FallbackLlmResponse["usage"] } | null> {
    const base = config.baseUrl.replace(/\/$/, "");
    const url = base.endsWith("/api") ? `${base}/chat` : `${base}/api/chat`;
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      ...config.headers,
    };
    if (config.apiKey && typeof config.apiKey === "string" && config.authHeader !== false) {
      headers.Authorization = `Bearer ${config.apiKey}`;
    }

    const response = await fetch(url, {
      method: "POST",
      headers,
      signal: options.signal,
      body: JSON.stringify({
        model: modelId,
        messages,
        stream: false,
        ...(config.disableThinking ? { think: false } : {}),
        options: {
          temperature: options.temperature ?? 0.3,
          num_predict: options.maxTokens ?? 4096,
        },
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      throw Object.assign(new Error(`Ollama API error: ${response.status} ${error}`), { status: response.status });
    }

    const data = (await response.json()) as {
      message?: { content?: string };
      response?: string;
      prompt_eval_count?: number;
      eval_count?: number;
    };
    const content = data.message?.content ?? data.response;
    if (!content) {
      throw new Error("Empty response from Ollama API");
    }

    const inputTokens = data.prompt_eval_count ?? 0;
    const outputTokens = data.eval_count ?? 0;
    return {
      content,
      usage: {
        inputTokens,
        outputTokens,
        totalTokens: inputTokens + outputTokens,
      },
    };
  }

  /**
   * Call an OpenAI-compatible Responses API.
   */
  private async callOpenAIResponses(
    config: ModelProviderConfig,
    modelId: string,
    messages: Array<{ role: "system" | "user" | "assistant"; content: string }>,
    options: FallbackLlmOptions,
  ): Promise<{ content: string; usage?: FallbackLlmResponse["usage"] } | null> {
    const base = config.baseUrl.replace(/\/$/, "");
    const url = base.endsWith("/v1")
      ? `${base}/responses`
      : `${base}/v1/responses`;

    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      ...config.headers,
    };

    if (config.apiKey && typeof config.apiKey === "string" && config.authHeader !== false) {
      headers["Authorization"] = `Bearer ${config.apiKey}`;
    }

    const instructions = messages
      .filter((message) => message.role === "system")
      .map((message) => message.content)
      .join("\n\n")
      .trim();
    const input = messages
      .filter((message) => message.role !== "system")
      .map((message) => ({
        role: message.role,
        content: [{
          type: message.role === "assistant" ? "output_text" : "input_text",
          text: message.content,
        }],
      }));

    const body: Record<string, unknown> = {
      model: modelId,
      input,
      max_output_tokens: Math.max(0, Math.floor(options.maxTokens ?? 4096)),
      ...buildChatCompletionTemperature(modelId, options.temperature ?? 0.3, {
        assumeOpenAI: shouldAssumeOpenAiChatCompletions(config.baseUrl),
      }),
      ...(options.store === undefined ? {} : { store: options.store }),
      ...(options.jsonSchema || options.responsesJsonSchema
        ? {
            text: {
              format: {
                type: "json_schema",
                name: (options.jsonSchema ?? options.responsesJsonSchema)!.name,
                strict: (options.jsonSchema?.strict ?? (options.responsesJsonSchema ? true : false)),
                schema: (options.jsonSchema ?? options.responsesJsonSchema)!.schema,
              },
            },
          }
        : {}),
    };
    if (instructions.length > 0) {
      body.instructions = instructions;
    }

    const response = await fetch(url, {
      method: "POST",
      headers,
      signal: options.signal,
      body: JSON.stringify(body),
    });

    if (!response.ok) {
      const error = await response.text();
      throw Object.assign(new Error(`OpenAI Responses API error: ${response.status} ${error}`), { status: response.status });
    }

    const data = (await response.json()) as {
      output_text?: string;
      output?: Array<{
        type?: string;
        text?: string;
        content?: Array<{
          type?: string;
          text?: string;
        }>;
      }>;
      usage?: {
        input_tokens?: number;
        output_tokens?: number;
        total_tokens?: number;
      };
    };

    const outputText = extractResponsesOutputText(data);
    if (!outputText) {
      throw new Error("Empty response from OpenAI Responses API");
    }

    return {
      content: outputText,
      usage: data.usage
        ? {
            inputTokens: data.usage.input_tokens,
            outputTokens: data.usage.output_tokens,
            totalTokens: data.usage.total_tokens,
          }
        : undefined,
    };
  }

  /**
   * Call Anthropic Messages API.
   */
  private async callAnthropic(
    config: ModelProviderConfig,
    modelId: string,
    messages: Array<{ role: "system" | "user" | "assistant"; content: string }>,
    options: FallbackLlmOptions,
  ): Promise<{ content: string; usage?: FallbackLlmResponse["usage"] } | null> {
    const base = config.baseUrl.replace(/\/$/, "");
    const url = base.endsWith("/v1")
      ? `${base}/messages`
      : `${base}/v1/messages`;

    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      "anthropic-version": "2023-06-01",
      ...config.headers,
    };

    // Handle auth - Anthropic uses x-api-key header (apiKey resolved by tryModel)
    if (config.apiKey && typeof config.apiKey === "string") {
      headers["x-api-key"] = config.apiKey;
    }

    // Extract system message (Anthropic handles it separately)
    const systemMessage = messages.find((m) => m.role === "system")?.content;
    const nonSystemMessages = messages.filter((m) => m.role !== "system");

    // Convert messages to Anthropic format
    const anthropicMessages = nonSystemMessages.map((m) => ({
      role: m.role,
      content: m.content,
    }));

    const body: Record<string, unknown> = {
      model: modelId,
      messages: anthropicMessages,
      max_tokens: options.maxTokens ?? 4096,
      temperature: options.temperature ?? 0.3,
    };

    if (systemMessage) {
      body.system = systemMessage;
    }

    const response = await fetch(url, {
      method: "POST",
      headers,
      signal: options.signal,
      body: JSON.stringify(body),
    });

    if (!response.ok) {
      const error = await response.text();
      throw Object.assign(new Error(`Anthropic API error: ${response.status} ${error}`), { status: response.status });
    }

    const data = (await response.json()) as {
      content: Array<{
        type: string;
        text: string;
      }>;
      usage?: {
        input_tokens?: number;
        output_tokens?: number;
      };
    };

    const content = data.content?.[0]?.text;
    if (!content) {
      throw new Error("Empty response from Anthropic API");
    }

    return {
      content,
      usage: data.usage
        ? {
            inputTokens: data.usage.input_tokens,
            outputTokens: data.usage.output_tokens,
            totalTokens: (data.usage.input_tokens ?? 0) + (data.usage.output_tokens ?? 0),
          }
        : undefined,
    };
  }
}

/**
 * Local fine-tuned model endpoint resolver + openai-compatible caller
 * (issue #1585 model-lab integration).
 *
 * Remnic's two classification workloads — the extraction faithfulness gate
 * (#1576) and passive-correction intent detection (#1581) — can run on small
 * fine-tuned models served locally (Ollama / vLLM) instead of prompted
 * frontier LLMs. The model-lab (`model-lab/`) produces those models; this
 * module is the config-side half: it resolves the optional local endpoint
 * pointer from config and, when set, makes a minimal openai-compatible
 * chat-completions call to it.
 *
 * Design:
 *   - **Pointers are optional.** Empty defaults preserve the existing routing
 *     chain exactly (rule 39 / byte-identical pre-feature). A resolver returns
 *     `null` when the pointer is unset, so callers short-circuit before any
 *     network.
 *   - **Graceful degradation.** A local-endpoint failure (network, non-2xx,
 *     malformed body, timeout) returns `null`; callers fall back to the
 *     configured chain (checklist §4 — never block writes on a classifier).
 *   - **No inline casts.** The fetch JSON is narrowed with `in` / `typeof`
 *     guards (project rule: never assert a shape to read one property).
 *   - **Injectable fetch.** `callOpenAiCompatibleChat` takes an optional
 *     `fetchImpl` so the caller is unit-testable without a live server.
 */

import type { PluginConfig } from "./types.js";

/** A resolved local endpoint: where to call + which model to name. */
export interface LocalModelEndpoint {
  /** Base URL, e.g. `http://localhost:11434/v1` (no trailing slash required). */
  baseUrl: string;
  /** Model name the server expects, e.g. `remnic-faithfulness-gate-v1`. */
  model: string;
}

/** A chat message in the openai-compatible shape this caller sends. */
export interface EndpointChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

/** Options for a single local-endpoint chat call. */
export interface EndpointChatOptions {
  /** Per-call timeout in ms. Bounds each attempt so one slow server can't
   *  starve the batch (matches the local-LLM precedent). */
  timeoutMs: number;
  /** Optional batch AbortSignal forwarded into the probe (issue #1700 nit #5).
   *  When the batch budget elapses (or the caller aborts), the in-flight probe
   *  aborts immediately instead of waiting for its own `timeoutMs` — a
   *  micro-optimization, not a correctness fix (the outer race already bounds
   *  the total). Undefined preserves the prior per-attempt-only behavior. */
  signal?: AbortSignal;
  /** Sampling temperature — classification wants low entropy (0.0–0.2). */
  temperature?: number;
  /** Max output tokens. */
  maxTokens?: number;
  /** Request JSON-object output (the gate emits a JSON verdict array). */
  responseFormatJson?: boolean;
}

/** Result of a local-endpoint chat call. */
export interface EndpointChatResult {
  content: string;
  /** The model the server reports it used (falls back to the requested name). */
  modelUsed: string;
}

/**
 * Resolve the faithfulness-gate local endpoint from config (issue #1585).
 *
 * Returns the endpoint only when BOTH a base URL and a model name are
 * configured; otherwise `null` (gate uses its existing routing chain). The
 * gate's verifier needs a model identity, so a base URL alone is intentionally
 * insufficient — silently calling whatever the server's default model is would
 * be an unreviewed behavioral change.
 */
export function resolveFaithfulnessGateEndpoint(
  config: Pick<PluginConfig, "extractionFaithfulnessModel" | "extractionFaithfulnessBaseUrl">,
): LocalModelEndpoint | null {
  const baseUrl = config.extractionFaithfulnessBaseUrl.trim();
  const model = config.extractionFaithfulnessModel.trim();
  if (!baseUrl || !model) return null;
  return { baseUrl, model };
}

/**
 * Resolve the correction-intent local endpoint from config (issue #1581/#1585).
 *
 * Same contract as the gate resolver. Consumption by the model-backed
 * detector is the consuming child's job — the rule-based
 * `detectPassiveCorrections` remains the default path; this pointer lets a
 * future model-backed detector route to a fine-tuned local classifier when an
 * operator configures one.
 */
export function resolveCorrectionIntentEndpoint(
  config: Pick<PluginConfig, "correctionIntentModel" | "correctionIntentBaseUrl">,
): LocalModelEndpoint | null {
  const baseUrl = config.correctionIntentBaseUrl.trim();
  const model = config.correctionIntentModel.trim();
  if (!baseUrl || !model) return null;
  return { baseUrl, model };
}

type FetchLike = typeof fetch;

/**
 * Make an openai-compatible chat-completions call to a local endpoint.
 *
 * POSTs to `${baseUrl}/chat/completions` with `{ model, messages, ... }` and
 * returns the first choice's content. Any failure (non-2xx, network error,
 * malformed body, timeout) returns `null` so callers fall back gracefully.
 *
 * The response is narrowed with runtime guards — never an unchecked cast — so
 * a surprising server response fails closed (`null`) rather than reading a
 * fabricated field.
 */
export async function callOpenAiCompatibleChat(
  endpoint: LocalModelEndpoint,
  messages: EndpointChatMessage[],
  options: EndpointChatOptions,
  fetchImpl: FetchLike = fetch,
): Promise<EndpointChatResult | null> {
  const url = joinBaseUrl(endpoint.baseUrl, "/chat/completions");
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), options.timeoutMs);
  // Forward the batch AbortSignal into the probe (issue #1700 nit #5): if the
  // batch budget already elapsed, abort the in-flight probe immediately rather
  // than waiting for the probe's own timeoutMs. AbortSignal.any is ES2024
  // (forbidden here); wire the listener manually + guard the already-aborted
  // case. The fetch still uses the probe's controller, so clearing the timer
  // below is the only cleanup needed.
  const batchSignal = options.signal;
  const onBatchAbort = () => controller.abort();
  if (batchSignal) {
    if (batchSignal.aborted) {
      controller.abort();
    } else {
      batchSignal.addEventListener("abort", onBatchAbort, { once: true });
    }
  }
  try {
    const body: Record<string, unknown> = {
      model: endpoint.model,
      messages,
      temperature: options.temperature ?? 0.1,
    };
    if (typeof options.maxTokens === "number") {
      body.max_tokens = options.maxTokens;
    }
    if (options.responseFormatJson) {
      body.response_format = { type: "json_object" };
    }
    let response: Response;
    try {
      response = await fetchImpl(url, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body),
        signal: controller.signal,
      });
    } catch {
      // Network error or abort — fail closed, let the caller fall back.
      return null;
    }
    if (!response.ok) return null;
    const parsed: unknown = await response.json().catch(() => null);
    const content = extractFirstChoiceContent(parsed);
    if (content === null) return null;
    return { content, modelUsed: extractModel(parsed) ?? endpoint.model };
  } finally {
    clearTimeout(timer);
    if (batchSignal) batchSignal.removeEventListener("abort", onBatchAbort);
  }
}

/** Join a base URL and a path, tolerating a trailing slash on the base. */
function joinBaseUrl(base: string, path: string): string {
  return base.endsWith("/") ? `${base.slice(0, -1)}${path}` : `${base}${path}`;
}

/**
 * Narrow the openai-compatible response and pull the first choice's content.
 *
 * `in` / `typeof` guards only — no `as` cast (project rule). Returns `null`
 * for any shape that isn't `{ choices: [{ message: { content: string } }, …] }`.
 */
function extractFirstChoiceContent(data: unknown): string | null {
  if (!data || typeof data !== "object") return null;
  // After `in`, TS narrows the property to `unknown` — read it directly, no cast.
  if (!("choices" in data) || !Array.isArray(data.choices)) return null;
  const choices: unknown[] = data.choices;
  for (const choice of choices) {
    if (!choice || typeof choice !== "object") continue;
    if (!("message" in choice)) continue;
    const message = choice.message;
    if (!message || typeof message !== "object") continue;
    if (!("content" in message)) continue;
    const content = message.content;
    if (typeof content === "string" && content.length > 0) return content;
  }
  return null;
}

/** Narrow the `model` field from the response (best-effort, may be absent). */
function extractModel(data: unknown): string | null {
  if (!data || typeof data !== "object" || !("model" in data)) return null;
  const model = data.model;
  return typeof model === "string" && model.length > 0 ? model : null;
}

/**
 * recall-handles.ts — injection-time memory handles (issue #1582).
 *
 * Every injected memory gets a stable short handle — `[m:4f2a]` — so a user
 * (or the agent) can react to ONE specific memory in-band ("[m:4f2a] is
 * stale", thumbs-down, "correct that") without a context switch to a CLI or
 * console. The handle is derived from the memory **id** (never the content),
 * so it is stable across edits/versioning.
 *
 * This module is PURE — no I/O, no side effects, no state. It owns:
 *   - {@link handleFor} — deterministic 4-hex handle from a memory id.
 *   - {@link renderHandle} / {@link renderHandlesForInjection} — render the
 *     `[m:xxxx]` token for one memory (or a whole injection set, extending to
 *     6 chars on intra-injection collision).
 *   - {@link parseHandles} — extract handle tokens from prose.
 *   - {@link normalizeHandle} / {@link isHandleToken} — classify a string.
 *   - {@link resolveHandle} — map a handle back to a memory id against the
 *     session's recent recall snapshots (hit / not-found / ambiguous).
 *
 * Design rules honored (issue #1582 design + pitfalls):
 *   - Handles are derived from the id only — never hashed with content, never
 *     persisted into memory files or rawContent (rule 23). Rendering happens
 *     at injection time only.
 *   - Resolution is per-session and snapshot-scoped — there is NEVER a global
 *     handle→id map (collision space too small globally, leaks across
 *     principals — rule 42). Misses are tagged, never guessed (rule 34/51).
 *   - The formatter is allocation-light: a string append at render time, no
 *     per-memory object churn, because it runs on every recall.
 */

import { createHash } from "node:crypto";

/**
 * Default handle width in hex characters (4 → 65 536-handle space).
 * Per-injection sets are ~10–40 memories, so in-context collisions are
 * vanishingly rare; {@link renderHandlesForInjection} widens the colliding
 * member to {@link HANDLE_EXTENDED_WIDTH} when two ids in ONE injection would
 * collide.
 */
export const HANDLE_DEFAULT_WIDTH = 4;

/**
 * Width used to disambiguate two ids that collide at the default width within
 * a single injection. 6 hex chars → ~16 M-handle space, which is comfortably
 * beyond per-injection set sizes.
 */
export const HANDLE_EXTENDED_WIDTH = 6;

/** Minimum/maximum accepted hex widths for a rendered/parsed handle. */
export const HANDLE_MIN_WIDTH = 4;
export const HANDLE_MAX_WIDTH = 8;

/**
 * Regex matching a rendered handle token anywhere in prose: `[m:` followed by
 * 4–8 lowercase hex chars and a closing `]`. Malformed tokens (`[m:xyz!]`,
 * `[m:abc]` with uppercase, missing bracket) are intentionally NOT matched.
 * Used by {@link parseHandles} and the sanitizer.
 */
export const HANDLE_REGEX = /\[m:[0-9a-f]{4,8}\]/g;

/**
 * Memory ids are `<category>-<timestamp>-<suffix>` (e.g. `fact-1770469224307-eelr`,
 * `artifact-...`, `reasoning_trace-...`, plus parent-`-chunk-N` variants). The
 * category segment allows underscores because `MemoryCategory` includes
 * `reasoning_trace` (codex review); bare names (`Widget`) still fail. Entity
 * reconstructions and other non-memory `.md` rows use bare names (`Widget`)
 * that must NOT receive a handle — citing one would resolve to a basename no
 * storage can load. This pattern gates handle rendering/recording to plausible
 * memory ids only (issue #1582, codex review).
 */
export const MEMORY_ID_PATTERN = /^[a-z][a-z0-9_]*-\d+-[a-z0-9-]+$/;

/**
 * Derive the deterministic handle hex for a memory id at a given width.
 *
 * `handleFor(id) === handleFor(id)` always, and `handleFor(id, w)` is a prefix
 * of `handleFor(id, w+1)` (both slice the same sha256 hex digest), so widening
 * for collision-disambiguation never changes the shorter prefix.
 *
 * @param memoryId  Stable memory id (e.g. `fact-1770469224307-eelr`).
 * @param width     Hex width. Defaults to {@link HANDLE_DEFAULT_WIDTH}.
 *                   Clamped to [4, 8]; the digest has 64 hex chars available.
 */
export function handleFor(memoryId: string, width: number = HANDLE_DEFAULT_WIDTH): string {
  const w = clampWidth(width);
  return createHash("sha256").update(memoryId).digest("hex").slice(0, w);
}

function clampWidth(width: number): number {
  if (!Number.isFinite(width)) return HANDLE_DEFAULT_WIDTH;
  return Math.min(HANDLE_MAX_WIDTH, Math.max(HANDLE_MIN_WIDTH, Math.floor(width)));
}

/**
 * Render the `[m:xxxx]` token for one memory id. Width override is for the
 * collision-extension path in {@link renderHandlesForInjection}; callers that
 * render a single handle in isolation should omit it.
 */
export function renderHandle(memoryId: string, widthOverride?: number): string {
  return `[m:${handleFor(memoryId, widthOverride ?? HANDLE_DEFAULT_WIDTH)}]`;
}

/**
 * Append a handle to a memory line, allocation-light. When `widthOverride` is
 * omitted the default-width handle is used; pass the widened width from
 * {@link renderHandlesForInjection} for a colliding member.
 *
 *   appendHandle("API rate limit is 1000 rpm.", "fact-1-abc")
 *   // → "API rate limit is 1000 rpm. [m:4f2a]"
 */
export function appendHandle(line: string, memoryId: string, widthOverride?: number): string {
  const handle = renderHandle(memoryId, widthOverride);
  // Single trailing space before the handle; collapse a double space if the
  // line already ended in whitespace so output stays clean.
  const trimmed = line.replace(/\s+$/, "");
  return `${trimmed} ${handle}`;
}

/**
 * Result of {@link renderHandlesForInjection}: for each memory id, the width
 * used (default 4, or 6 when widened to break an intra-injection collision)
 * and the rendered token. Ordered for stable iteration.
 */
export interface InjectionHandleEntry {
  memoryId: string;
  width: number;
  handle: string;
}

/**
 * Build handles for a whole injection set, widening to 6 chars when two ids
 * collide at the default width within THIS set (so each rendered token is
 * unique in context). Idempotent for the same input.
 *
 * The collision case is vanishingly rare (~10–40 memories per injection), but
 * widening guarantees a user can always point at exactly one memory in-band.
 */
export function renderHandlesForInjection(
  memoryIds: readonly string[],
): InjectionHandleEntry[] {
  // Group ids by their default-width handle so every member of a 4-char
  // collision group widens to 6 together — not just the later one. Widening
  // only the second id would leave the first rendering a 4-char token whose
  // resolution is ambiguous against the group (codex review).
  const idsByDefaultHandle = new Map<string, string[]>();
  for (const memoryId of memoryIds) {
    if (!memoryId) continue;
    const defaultHandle = handleFor(memoryId, HANDLE_DEFAULT_WIDTH);
    const group = idsByDefaultHandle.get(defaultHandle);
    if (group) group.push(memoryId);
    else idsByDefaultHandle.set(defaultHandle, [memoryId]);
  }
  const entries: InjectionHandleEntry[] = [];
  for (const memoryId of memoryIds) {
    if (!memoryId) continue;
    const defaultHandle = handleFor(memoryId, HANDLE_DEFAULT_WIDTH);
    const group = idsByDefaultHandle.get(defaultHandle) ?? [memoryId];
    const width = group.length > 1 ? HANDLE_EXTENDED_WIDTH : HANDLE_DEFAULT_WIDTH;
    entries.push({ memoryId, width, handle: `[m:${handleFor(memoryId, width)}]` });
  }
  // Reconciliation pass: if two DIFFERENT ids still produce the same rendered
  // token at their assigned width — the pathological case where they also
  // collide at the extended 6-char width — widen ALL members of the collision
  // group together, never just the later one. Leaving the first at 6 chars
  // while widening the second to 7 makes the first token resolve ambiguously
  // (both ids match at width 6). Iterate until no collision remains or every
  // member reaches HANDLE_MAX_WIDTH (codex review).
  let widened = true;
  while (widened) {
    widened = false;
    const tokenToIndices = new Map<string, number[]>();
    for (let i = 0; i < entries.length; i++) {
      const token = entries[i]!.handle;
      const arr = tokenToIndices.get(token);
      if (arr) arr.push(i);
      else tokenToIndices.set(token, [i]);
    }
    for (const indices of tokenToIndices.values()) {
      if (indices.length < 2) continue;
      const uniqueIds = new Set(indices.map((idx) => entries[idx]!.memoryId));
      if (uniqueIds.size < 2) continue; // same id listed twice — same handle is fine
      // Only continue widening if at least one entry has room to grow.
      // When every member has reached HANDLE_MAX_WIDTH the collision is
      // irreducible (two ids with identical sha256 8-char prefixes —
      // astronomically unlikely for real data); stop to avoid an infinite loop.
      let anyWidened = false;
      for (const idx of indices) {
        const entry = entries[idx]!;
        if (entry.width >= HANDLE_MAX_WIDTH) continue;
        entry.width += 1;
        entry.handle = `[m:${handleFor(entry.memoryId, entry.width)}]`;
        anyWidened = true;
      }
      if (anyWidened) widened = true;
    }
  }
  return entries;
}

/**
 * Build a `resultIndex → handle` map for a QMD result set. Returns an empty
 * map when handles are disabled or no result carries a handle-eligible memory
 * id. Extracted from the orchestrator's `formatQmdResults` so the rendering
 * logic lives in the pure handles module, not the god file (issue #1582,
 * rule 4).
 *
 * Only real memory ids (matching {@link MEMORY_ID_PATTERN}) are handle-eligible;
 * entity reconstructions and other non-memory `.md` rows get no handle.
 *
 * @param results  QMD search results (each has a `path` like `…/fact-x.md`).
 * @param enabled  Whether handle rendering is on. The caller gates on both the
 *                  config flag and session-key availability — handles rendered
 *                  without a session key can never be resolved, so they must
 *                  not be shown (cursor review of #1582).
 */
export function buildHandleIndexForResults(
  results: readonly { path: string }[],
  enabled: boolean,
): Map<number, string> {
  if (!enabled) return new Map();
  const ids: string[] = [];
  const idIndexByResult: Array<number | null> = results.map((r) => {
    const match = r.path.match(/([^/]+)\.md$/);
    if (!match) return null;
    const candidate = match[1] as string;
    if (!MEMORY_ID_PATTERN.test(candidate)) return null;
    ids.push(candidate);
    return ids.length - 1;
  });
  const entries = renderHandlesForInjection(ids);
  const handleByIndex = new Map<number, string>();
  results.forEach((_r, i) => {
    const idIndex = idIndexByResult[i];
    if (idIndex === null) return;
    const entry = entries[idIndex];
    if (entry) handleByIndex.set(i, entry.handle);
  });
  return handleByIndex;
}

/**
 * Extract every handle token from prose, in order of appearance. Returns the
 * full rendered tokens (e.g. `[m:4f2a]`) so callers can locate them in text.
 * Malformed tokens are ignored. Duplicates are preserved (a user may cite the
 * same memory twice).
 *
 *   parseHandles("see [m:4f2a] (also [m:1b9e]) — not [m:xyz!]")
 *   // → ["[m:4f2a]", "[m:1b9e]"]
 */
export function parseHandles(text: string): string[] {
  if (typeof text !== "string" || text.length === 0) return [];
  const out: string[] = [];
  // Reset lastIndex because HANDLE_REGEX is /g and may be reused.
  HANDLE_REGEX.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = HANDLE_REGEX.exec(text)) !== null) {
    out.push(match[0]);
  }
  return out;
}

/**
 * Strip every handle token from text, collapsing the spacing it introduced.
 * Used by the sanitizer so handles observed back into the pipeline never
 * become memory content (issue #1582 hygiene §2).
 *
 *   stripHandles("API limit 1000 rpm. [m:4f2a]") → "API limit 1000 rpm."
 */
export function stripHandles(text: string): string {
  if (typeof text !== "string" || text.length === 0) return text;
  // Remove the token and the single preceding space that {@link appendHandle}
  // added, then tidy any double space left behind.
  // \\s? (not \\s*): the renderer appends exactly one preceding space, and a
  // bounded quantifier avoids the polynomial-ReDoS flag on uncontrolled input.
  // A stray run of spaces is collapsed by the following line.
  return text
    .replace(/\s?\[m:[0-9a-f]{4,8}\]/g, "")
    .replace(/[ \t]{2,}/g, " ")
    .replace(/[ \t]+$/g, "");
}

/**
 * Normalize a handle token (or bare hex) to its lowercase hex core, or `null`
 * when the input is not a handle. Accepts both the rendered `[m:4f2a]` form
 * and the bare `m:4f2a` / `4f2a` form a user might type.
 *
 *   normalizeHandle("[m:4f2a]") → "4f2a"
 *   normalizeHandle("m:4f2a")   → "4f2a"
 *   normalizeHandle("4f2a")     → "4f2a"
 *   normalizeHandle("fact-1")   → null
 */
export function normalizeHandle(token: string): string | null {
  if (typeof token !== "string" || token.length === 0) return null;
  const trimmed = token.trim().toLowerCase();
  // [m:4f2a]
  const bracketed = /^\[m:([0-9a-f]{4,8})\]$/.exec(trimmed);
  if (bracketed) return bracketed[1] ?? null;
  // m:4f2a
  const prefixed = /^m:([0-9a-f]{4,8})$/.exec(trimmed);
  if (prefixed) return prefixed[1] ?? null;
  // bare 4f2a — only treat as a handle when it is pure hex in the width range,
  // so we don't mis-classify a real memory id that happens to be 4 hex chars.
  const bare = /^([0-9a-f]{4,8})$/.exec(trimmed);
  if (bare) return bare[1] ?? null;
  return null;
}

/**
 * Whether a string looks like a handle token (rendered or bare). Cheaper
 * boolean form of {@link normalizeHandle} for callers that only need to branch.
 */
export function isHandleToken(token: string): boolean {
  return normalizeHandle(token) !== null;
}

/**
 * A flattened id-or-handle reference: either a raw memory id or the hex core
 * of a handle. {@link resolveMemoryIdOrHandle} produces this so the snapshot
 * lookup only runs for actual handles.
 */
export interface ParsedIdOrHandle {
  /** The original reference as supplied by the caller. */
  raw: string;
  /** `true` when `raw` is a handle that still needs snapshot resolution. */
  isHandle: boolean;
  /** For a handle, its hex core; for a raw id, the id itself. */
  value: string;
}

/**
 * Classify a single caller reference as id-or-handle.
 */
export function parseIdOrHandle(ref: string): ParsedIdOrHandle {
  const hex = normalizeHandle(ref);
  if (hex !== null) {
    return { raw: ref, isHandle: true, value: hex };
  }
  return { raw: ref, isHandle: false, value: ref };
}

/**
 * A flattened view of the memory-id sets a session has recently recalled.
 * Each entry is one past recall's admitted memory ids (newest first).
 * Resolution never sees raw {@link LastRecallSnapshot}s — callers flatten to
 * this so the pure resolver has no dependency on the snapshot type.
 */
export interface RecallSnapshotIds {
  memoryIds: readonly string[];
}

/**
 * Result of resolving a handle against recent recall snapshots.
 * - `{ ok: true, memoryId }` — exactly one match within the lookback window.
 * - `{ ok: false, reason: "not_found" }` — no memory id produced this handle
 *   within the window (misses are acceptable and tagged, never guessed).
 * - `{ ok: false, reason: "ambiguous", candidates }` — two DIFFERENT memory
 *   ids in the window collide on the same handle; the caller must disambiguate
 *   (rule 34/51: never guess).
 */
export type ResolveHandleResult =
  | { ok: true; memoryId: string }
  | { ok: false; reason: "not_found" }
  | { ok: false; reason: "ambiguous"; candidates: string[] };

/**
 * Resolve a handle hex (or a rendered token / bare form) to its memory id
 * against the session's recent recall snapshots.
 *
 * @param handle     A handle token, bare hex, or `m:hex` form.
 * @param snapshots  Recent recall snapshots for the session, newest first.
 *                   Only the first `depth` entries are searched.
 * @param depth      How many snapshots (newest-first) to search. Defaults to
 *                   {@link DEFAULT_HANDLE_SNAPSHOT_DEPTH}.
 */
export function resolveHandle(
  handle: string,
  snapshots: readonly RecallSnapshotIds[],
  depth: number = DEFAULT_HANDLE_SNAPSHOT_DEPTH,
): ResolveHandleResult {
  const hex = normalizeHandle(handle);
  if (hex === null) {
    return { ok: false, reason: "not_found" };
  }
  // A handle resolves when a memory id's handle is a PREFIX of `hex` (handles
  // widened to 6 chars for collision still match their own 4-char core, and a
  // user citing the short form must still resolve the widened memory).
  const width = hex.length;
  const limit = Math.max(0, Math.min(depth, snapshots.length));
  const matches = new Set<string>();
  for (let i = 0; i < limit; i += 1) {
    const snap = snapshots[i];
    if (!snap) continue;
    for (const memoryId of snap.memoryIds) {
      if (!memoryId) continue;
      if (handleFor(memoryId, width) === hex) {
        matches.add(memoryId);
      }
    }
  }
  if (matches.size === 0) {
    return { ok: false, reason: "not_found" };
  }
  if (matches.size === 1) {
    return { ok: true, memoryId: matches.values().next().value as string };
  }
  return { ok: false, reason: "ambiguous", candidates: [...matches] };
}

/**
 * Default snapshot lookback depth for handle resolution (issue #1582 config
 * `recall.handleSnapshotDepth`). Older-than-N snapshots are not searched and a
 * miss is tagged rather than widening the window.
 */
export const DEFAULT_HANDLE_SNAPSHOT_DEPTH = 5;

/**
 * Utilities for extracting JSON payloads from LLM outputs.
 *
 * We see common failure modes:
 * - "Here's an example: {..}\nHere's the real answer: {..}" (multiple JSON blocks)
 * - fenced ```json blocks
 * - leading/trailing prose around JSON
 *
 * These helpers attempt multiple candidates and let callers validate with schemas.
 */

export function stripCodeFences(text: string): string {
  // Drop the leading \s* before the lazy body: it overlapped the body and caused
  // polynomial backtracking on unterminated fences (CodeQL js/polynomial-redos).
  // inner is trimmed, so captured content is identical.
  return text.replace(/```(?:json)?([\s\S]*?)```/gi, (_m, inner) => String(inner).trim());
}

export function extractJsonCandidates(text: string): string[] {
  const trimmed = text.trim();
  const cleaned = stripCodeFences(trimmed);
  const candidates: string[] = [];

  // Verbatim balanced blocks FIRST: stripCodeFences rewrites every ``` pair, so
  // a stripped candidate can parse while carrying altered content (e.g. a
  // patch value that embeds an inner code block). A string-aware balanced scan
  // of the unstripped text yields the payload unmodified; stripped candidates
  // remain as later fallbacks for shapes the raw scan cannot cut.
  candidates.push(...scanBalancedJsonBlocks(trimmed));
  if (cleaned.length > 0) candidates.push(cleaned);
  candidates.push(...scanBalancedJsonBlocks(cleaned));

  // Legacy regex fallback (single object)
  const objMatch = cleaned.match(/\{[\s\S]*\}/);
  if (objMatch) candidates.push(objMatch[0]);

  const seen = new Set<string>();
  return candidates
    .map((c) => c.trim())
    .filter((c) => c.length > 0)
    .filter((c) => {
      if (seen.has(c)) return false;
      seen.add(c);
      return true;
    });
}

function scanBalancedJsonBlocks(text: string): string[] {
  const out: string[] = [];
  const opens = new Set(["{", "["]);
  const closes: Record<string, string> = { "{": "}", "[": "]" };

  for (let i = 0; i < text.length; i++) {
    const start = text[i];
    if (!opens.has(start)) continue;

    const expectedClose = closes[start];
    let depth = 0;
    let inString = false;
    let escape = false;

    for (let j = i; j < text.length; j++) {
      const ch = text[j];

      if (inString) {
        if (escape) {
          escape = false;
        } else if (ch === "\\") {
          escape = true;
        } else if (ch === "\"") {
          inString = false;
        }
        continue;
      }

      if (ch === "\"") {
        inString = true;
        continue;
      }

      if (ch === start) depth++;
      if (ch === expectedClose) depth--;

      if (depth === 0) {
        out.push(text.slice(i, j + 1).trim());
        i = j;
        break;
      }
    }
  }

  return out;
}

/**
 * Wearable cross-source fusion — deterministic conversation clustering.
 *
 * Conversations from multiple sources recording the same real-world event
 * overlap or sit within a proximity gap. This module groups them into
 * clusters that are fully deterministic: the only inputs are start/end
 * times, source ids, and conversation ids (no randomness, no LLM).
 *
 * Cross-source time proximity BRIDGES the same real-world conversation
 * recorded by DIFFERENT sources. A single source's own distinct
 * conversations are never merged by time proximity alone — that would
 * collapse the source's conversation boundaries. Two same-source
 * conversations may end up in one cluster only when a different-source
 * conversation within the gap corroborates that they are part of the same
 * real-world event (a cross-source chain/bridge).
 */

import type { FusionConversationInput } from "./types.js";

/** Default max gap (ms) between two conversations to merge into one cluster. */
export const DEFAULT_PROXIMITY_GAP_MS = 5 * 60_000;

interface Interval {
  start: number;
  end: number;
}

/** The latest extent of a set of segments as an epoch-ms value + its ISO.
 * Each segment contributes its OWN extent — its `endIso` when known,
 * otherwise its `startIso` — and the result is the maximum. Reconstructed
 * `--:--` transcripts rebuild segments with only a start, so this reaches
 * the last segment start; segment ISOs are already cross-midnight-rolled by
 * the reconstruct layer, so the derived end is consistent with the segment
 * timeline. Returns undefined when no segment carries a parseable extent.
 *
 * This is the SINGLE shared primitive behind every end/interval derivation
 * in the fusion pipeline (cluster interval, fused conversation end): when a
 * conversation-level end is missing, the window falls back to the latest
 * segment extent instead of collapsing to a zero-length point at the start.
 */
export interface SegmentExtent {
  /** Epoch ms of the latest extent. */
  ms: number;
  /** ISO string that produced `ms` (a segment endIso, else its startIso). */
  iso: string;
}

export function maxSegmentExtent(
  segments: readonly { endIso?: string; startIso?: string }[],
): SegmentExtent | undefined {
  let best: SegmentExtent | undefined;
  for (const seg of segments) {
    const iso = seg.endIso ?? seg.startIso;
    if (iso === undefined) continue;
    const ms = Date.parse(iso);
    if (!Number.isFinite(ms)) continue;
    if (best === undefined || ms > best.ms) {
      best = { ms, iso };
    }
  }
  return best;
}

/**
 * Resolve a conversation's effective [start, end] window in epoch ms.
 *
 * When the conversation carries no explicit end (`endIso` undefined — the
 * reconstructed form of a stored transcript whose heading end renders as
 * `--:--`), the window is derived from the segments so it spans the actual
 * utterances instead of collapsing to a zero-length point at the start:
 *
 *   1. conversation `endIso`, when known;
 *   2. the latest segment END (`segment.endIso`);
 *   3. the latest segment START (`segment.startIso`) — reconstructed
 *      transcripts rebuild segments with only a start, so the window must
 *      reach the last segment start;
 *   4. the conversation start itself (no segments at all).
 *
 * Each segment contributes its own extent (end when known, otherwise its
 * start); the window end is the maximum extent. Segment ISOs are already
 * rolled for cross-midnight by the reconstruct layer, so the derived end is
 * consistent with the segment timeline. The end is clamped to `>= start` so
 * the window is always valid regardless of input anomalies.
 */
function effectiveInterval(conversation: FusionConversationInput): Interval {
  const start = Date.parse(conversation.startIso);
  const endRaw =
    conversation.endIso !== undefined ? Date.parse(conversation.endIso) : NaN;
  // No conversation-level end ("--:--"): derive the window from the latest
  // SEGMENT extent via the shared primitive, so every end/interval derivation
  // in the pipeline uses ONE coherent implementation. Falling back only to
  // `start` would produce a zero/negative-length window that drops or
  // mis-clusters the conversation (issue #1810).
  const end = Number.isFinite(endRaw)
    ? (endRaw as number)
    : (maxSegmentExtent(conversation.segments)?.ms ?? start);
  // Clamp universally so the window is always non-negative. An explicit
  // conversation end that precedes the start (malformed/cross-day input)
  // would otherwise yield a negative-length window that shrinks the merge
  // horizon and can split a within-gap cluster.
  return { start, end: Math.max(end, start) };
}

function compareConversation(
  a: FusionConversationInput,
  b: FusionConversationInput,
): number {
  if (a.source !== b.source) return a.source < b.source ? -1 : 1;
  if (a.conversationId !== b.conversationId) {
    return a.conversationId < b.conversationId ? -1 : 1;
  }
  return 0;
}

/**
 * Cluster conversations across sources for one day. Returns clusters in
 * chronological order; each cluster is sorted by (start, source, id).
 * Conversations whose start time is unparseable are emitted as
 * single-element clusters at the tail (sorted by source then id) so no
 * data is lost.
 *
 * ## Cross-source bridging rule (issue #1849)
 *
 * Time proximity is meant to bridge the SAME real-world conversation
 * recorded by DIFFERENT sources — not to merge one source's own distinct
 * conversations. Two conversations from the SAME source are therefore
 * never directly joined by time proximity alone; they may end up in the
 * same cluster only through a cross-source chain where a different-source
 * conversation within the gap corroborates the bridge. This preserves the
 * source's own conversation boundaries when no other source corroborates
 * a merge.
 *
 * Concretely, a union-find pass links every pair of conversations that
 * (a) come from DIFFERENT sources and (b) sit within the proximity gap
 * (the later start ≤ the earlier end + gap). The transitive closure then
 * groups same-source conversations that are bridged by at least one
 * intervening different-source conversation. A single source with two
 * near-back-to-back conversations and no other source recording the same
 * window stays in two separate clusters.
 */
export function clusterConversations(
  inputs: readonly FusionConversationInput[],
  proximityGapMs: number = DEFAULT_PROXIMITY_GAP_MS,
): FusionConversationInput[][] {
  const finite: Array<{ conv: FusionConversationInput; interval: Interval }> = [];
  const noStart: FusionConversationInput[] = [];
  for (const conv of inputs) {
    const interval = effectiveInterval(conv);
    if (Number.isFinite(interval.start)) {
      finite.push({ conv, interval });
    } else {
      noStart.push(conv);
    }
  }

  // Deterministic processing + output ordering: (start, source, id).
  finite.sort((a, b) => {
    if (a.interval.start !== b.interval.start) {
      return a.interval.start - b.interval.start;
    }
    return compareConversation(a.conv, b.conv);
  });

  const n = finite.length;

  // Union-find so that same-source pairs are never directly joined by time
  // proximity alone; they may share a cluster only through a cross-source
  // bridge (transitive closure over different-source proximity edges).
  const parent = new Array<number>(n);
  for (let i = 0; i < n; i++) parent[i] = i;

  const find = (x: number): number => {
    let root = x;
    while (parent[root] !== root) root = parent[root];
    // Path compression.
    let cur = x;
    while (parent[cur] !== root) {
      const next = parent[cur]!;
      parent[cur] = root;
      cur = next;
    }
    return root;
  };

  const union = (a: number, b: number): void => {
    const ra = find(a);
    const rb = find(b);
    if (ra !== rb) parent[ra] = rb;
  };

  // Link every cross-source pair within the proximity gap. `finite` is
  // sorted by start, so once j's start exceeds i's end + gap, every later
  // j is also out of reach — break early.
  for (let i = 0; i < n; i++) {
    const endGap = finite[i]!.interval.end + proximityGapMs;
    for (let j = i + 1; j < n; j++) {
      if (finite[j]!.interval.start > endGap) break;
      // Only DIFFERENT sources may be directly joined by proximity.
      if (finite[i]!.conv.source === finite[j]!.conv.source) continue;
      union(i, j);
    }
  }

  // Group conversations by union-find root. Because `finite` is sorted and
  // we iterate in index order, each group's conversations stay in (start,
  // source, id) order, and groups are discovered in chronological order
  // (the first root seen belongs to the earliest-starting conversation).
  const clusters: FusionConversationInput[][] = [];
  const rootToCluster = new Map<number, number>();
  for (let i = 0; i < n; i++) {
    const root = find(i);
    let idx = rootToCluster.get(root);
    if (idx === undefined) {
      idx = clusters.length;
      rootToCluster.set(root, idx);
      clusters.push([]);
    }
    clusters[idx]!.push(finite[i]!.conv);
  }

  // Conversations with no parseable start can't be ordered in time, so
  // each becomes its own cluster, appended after the time-ordered ones.
  // Sort for determinism (source, id).
  noStart.sort(compareConversation);
  for (const conv of noStart) {
    clusters.push([conv]);
  }

  return clusters;
}

import { appendFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { entityMentionEpoch } from "./entity-mention-epoch.js";
import { deleteInFlightReadsForDir } from "./in-flight-reads.js";
import { invalidateDerivedAndGlobalForDir } from "./memory-cache.js";

/**
 * Filename of the memory-corpus version sentinel (issue #1902). MUST stay in
 * sync with `StorageManager.versionFilePath("memory-corpus")` in storage.ts —
 * the byte size of this append-only file IS the corpus version, and the
 * version-keyed hot-memories result cache keys on it.
 */
export const MEMORY_CORPUS_VERSION_SENTINEL = ".memory-corpus-version.log";

/**
 * Out-of-band corpus-version bump (issue #1902) for code paths that write or
 * modify memory files WITHOUT going through a StorageManager mutation method
 * — review approval, governance restore, migration. Appends one byte to the
 * on-disk sentinel so any process's version-keyed hot-memories cache rescans
 * on its next read (StorageManager.readSharedVersion reads the file size, so
 * the growth is observed immediately). The same call moves the entity-mention
 * epoch, unless the caller passes `{ indexedText: false }` for a metadata
 * stamp that cannot change snippet text, entityRef, or origin. Fail-open: a
 * bump failure must never crash the caller — a stale-cache window self-heals
 * on the next real write.
 */
export function bumpMemoryCorpusVersionForDir(
  memoryDir: string,
  options?: { indexedText?: boolean },
): void {
  try {
    const stateDir = path.join(memoryDir, "state");
    mkdirSync(stateDir, { recursive: true });
    appendFileSync(path.join(stateDir, MEMORY_CORPUS_VERSION_SENTINEL), "x");
  } catch {
    /* fail-open: never let a cache-coherence bump crash the primary operation */
  }
  if (options?.indexedText !== false && !entityMentionEpoch.suppressed()) {
    entityMentionEpoch.bump(memoryDir);
  }
  // Drop any in-flight readAllMemories scan for this dir (Cursor Medium, #1902):
  // after the sentinel advances, a concurrent read that missed the version-keyed
  // hot entry must not attach to a scan that began BEFORE this out-of-band write
  // and receive a pre-write corpus. Clearing forces a fresh scan of disk truth.
  deleteInFlightReadsForDir(memoryDir);
  // Also evict the TTL-keyed derived (episode/rule) and global (QMD search/recall)
  // caches for this dir (issue #1902, Codex Medium). The sentinel bump self-heals
  // the version-keyed hot cache, but the QMD caches are TTL-keyed, NOT
  // corpus-version-keyed — without this, an out-of-band writer (capsule
  // import/merge, review, spaces, governance restore, page revert, binary
  // redirect) would leave a warm process serving pre-write recall/search results
  // for the remainder of the QMD cache TTL. Route the bump through the same
  // invalidation chokepoint the in-process mutation paths use.
  invalidateDerivedAndGlobalForDir(memoryDir);
}

/**
 * Wearable speaker registry — maps provider diarization labels to
 * human names, persistently, per source.
 *
 * Providers expose speakers differently (Limitless: names + a "user"
 * marker; Bee: opaque labels like "0"/"1"; Omi: "SPEAKER_00" + is_user
 * + optional person ids). The registry stores operator-confirmed
 * mappings keyed `<sourceId>:<speakerKey>` in
 * `state/wearables/speakers.json`, plus the wearer's display name.
 *
 * Resolution precedence (most-authoritative first):
 *   1. registry override for `<sourceId>:<speakerKey>`
 *   2. provider-identified wearer  -> selfName
 *   3. provider-supplied speaker name
 *   4. the raw speaker key, prefixed "Speaker" when it is bare digits
 */

import { promises as fsPromises } from "node:fs";
import * as path from "node:path";

export interface SpeakerOverride {
  name: string;
  /** Mark this speaker as the wearer (their words become "you"). */
  isSelf?: boolean;
  updatedAt: string;
}

export interface SpeakerRegistry {
  version: 1;
  /** Display name used for the wearer across all sources. */
  selfName: string;
  /** Overrides keyed `<sourceId>:<speakerKey>`. */
  speakers: Record<string, SpeakerOverride>;
}

export const DEFAULT_SELF_NAME = "Me";

/**
 * Reserved self marker appended to a wearer's display label so the
 * rendered transcript carries explicit, parseable self metadata. It is
 * RESERVED: a non-self display label can never carry it (see
 * `stripSelfMarker`), so when `reconstructFusionInputs` reads it back it
 * is authoritative self metadata — never a coincidental display-name
 * suffix that would misattribute another speaker as the wearer
 * (issue #1849).
 */
export const SELF_MARKER_SUFFIX = " (you)";
const SELF_MARKER = "(you)";

/**
 * Remove a reserved `(you)` self marker from a display name. Applied to
 * every base name before it becomes a label so the marker can only ever
 * appear as the renderer-appended self flag, never as part of a stored
 * non-self display name.
 *
 * Implemented with plain string ops instead of a regex so the leading
 * `\s*` (no anchor) cannot cause the O(n²) backtracking CodeQL flags
 * on whitespace-only input (js/polynomial-redos).
 */
export function stripSelfMarker(name: string): string {
  const trimmed = name.trimEnd();
  if (!trimmed.endsWith(SELF_MARKER)) return trimmed;
  return trimmed.slice(0, -SELF_MARKER.length).trimEnd();
}

/**
 * Whether a rendered label carries the reserved self marker. This is the
 * single authoritative self-status detector shared by the renderer and
 * the fusion reconstructor (issue #1849).
 */
export function hasSelfMarker(label: string): boolean {
  return label.trimEnd().endsWith(SELF_MARKER);
}

export function emptySpeakerRegistry(): SpeakerRegistry {
  return { version: 1, selfName: DEFAULT_SELF_NAME, speakers: {} };
}

export function speakersFilePath(memoryDir: string): string {
  return path.join(memoryDir, "state", "wearables", "speakers.json");
}

export async function loadSpeakerRegistry(
  memoryDir: string,
): Promise<SpeakerRegistry> {
  const filePath = speakersFilePath(memoryDir);
  let raw: string;
  try {
    raw = await fsPromises.readFile(filePath, "utf-8");
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") {
      return emptySpeakerRegistry();
    }
    throw err;
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new Error(
      `wearables speakers file is not valid JSON (state/wearables/speakers.json): ${
        err instanceof Error ? err.message : String(err)
      }`,
    );
  }
  if (
    typeof parsed !== "object" ||
    parsed === null ||
    Array.isArray(parsed) ||
    typeof (parsed as SpeakerRegistry).speakers !== "object" ||
    (parsed as SpeakerRegistry).speakers === null
  ) {
    throw new Error(
      'wearables speakers file has an unexpected shape (state/wearables/speakers.json); expected {"version":1,"selfName":"...","speakers":{}}',
    );
  }
  const registry = parsed as SpeakerRegistry;
  return {
    version: 1,
    selfName:
      typeof registry.selfName === "string" && registry.selfName.trim().length > 0
        ? registry.selfName.trim()
        : DEFAULT_SELF_NAME,
    speakers: registry.speakers,
  };
}

export async function saveSpeakerRegistry(
  memoryDir: string,
  registry: SpeakerRegistry,
): Promise<void> {
  const filePath = speakersFilePath(memoryDir);
  await fsPromises.mkdir(path.dirname(filePath), { recursive: true });
  const tmpPath = `${filePath}.tmp-${process.pid}-${Date.now().toString(36)}`;
  await fsPromises.writeFile(
    tmpPath,
    `${JSON.stringify(registry, null, 2)}\n`,
    "utf-8",
  );
  try {
    await fsPromises.rename(tmpPath, filePath);
  } catch (err) {
    await fsPromises.unlink(tmpPath).catch(() => undefined);
    throw err;
  }
}

export function speakerRegistryKey(
  sourceId: string,
  speakerKey: string,
): string {
  return `${sourceId}:${speakerKey}`;
}

export interface ResolvedSpeaker {
  /** Display label used in transcripts, e.g. "Jane" or "Me (you)". */
  label: string;
  /** Whether this speaker is the wearer. */
  isSelf: boolean;
}

export function resolveSpeaker(
  sourceId: string,
  segment: { speakerKey: string; speakerName?: string; isWearer?: boolean },
  registry: SpeakerRegistry,
): ResolvedSpeaker {
  const override = registry.speakers[speakerRegistryKey(sourceId, segment.speakerKey)];
  if (override) {
    const isSelf = override.isSelf === true;
    // Reserve the `(you)` marker: strip any pre-existing marker from the
    // base name so a NON-self label can never carry it. Without this, a
    // speaker override like "Pat (you)" set WITHOUT --self would render
    // as "Pat (you)" and the fusion reconstructor would read the suffix
    // as self metadata, attributing Pat's words to the wearer (issue
    // #1849).
    const base = stripSelfMarker(override.name);
    return {
      label: isSelf ? `${base}${SELF_MARKER_SUFFIX}` : base,
      isSelf,
    };
  }
  if (segment.isWearer === true) {
    return {
      label: `${stripSelfMarker(registry.selfName)}${SELF_MARKER_SUFFIX}`,
      isSelf: true,
    };
  }
  if (
    typeof segment.speakerName === "string" &&
    segment.speakerName.trim().length > 0
  ) {
    // Provider-supplied names are never self here; strip a stray marker
    // so a provider label cannot masquerade as the reserved self flag.
    return { label: stripSelfMarker(segment.speakerName.trim()), isSelf: false };
  }
  // Strip the reserved `(you)` marker from the raw key so a provider
  // speakerKey like "Pat (you)" can never leak the marker into a non-self
  // rendered label — the fusion reconstructor reads the suffix as
  // authoritative self metadata and would misattribute the speaker as the
  // wearer (issue #1849).
  const key = stripSelfMarker(segment.speakerKey.trim());
  // Bare diarization indexes read better with a prefix.
  if (/^\d+$/.test(key)) {
    return { label: `Speaker ${key}`, isSelf: false };
  }
  return { label: key.length > 0 ? key : "Unknown speaker", isSelf: false };
}

/**
 * Distinct speaker labels for a set of segments, in first-appearance
 * order — used for day-transcript frontmatter.
 */
export function distinctSpeakerLabels(
  sourceId: string,
  segments: Array<{ speakerKey: string; speakerName?: string; isWearer?: boolean }>,
  registry: SpeakerRegistry,
): string[] {
  const labels: string[] = [];
  const seen = new Set<string>();
  for (const segment of segments) {
    const { label } = resolveSpeaker(sourceId, segment, registry);
    if (!seen.has(label)) {
      seen.add(label);
      labels.push(label);
    }
  }
  return labels;
}

/**
 * Wearable cross-source fusion — deterministic reconciliation.
 *
 * Given one cluster (conversations from N sources that overlapped in
 * time), produce a single reconciled timeline where each utterance
 * carries the best source's text plus per-segment provenance, and
 * conflicts that could not be settled deterministically are recorded as
 * disagreements.
 *
 * Reconciliation rules (all deterministic, no LLM):
 *  - text: prefer higher source trust, then the more-complete (longer)
 *    transcript over a truncated one; otherwise a stable tie-break.
 *  - disagreement: when two sources offer genuinely different text for
 *    the same window/speaker (neither contains the other), record every
 *    candidate and keep a provisional winner marked uncertain — we never
 *    silently pick.
 *  - speaker: resolved labels unify the wearer across sources; generic
 *    labels that cannot be cross-matched keep a lowered confidence.
 *
 * Full segment-level alignment beyond time windows is a deferred
 * follow-up (see PR body). This pass aligns by (speaker, time window).
 */

import { resolveSpeaker, type SpeakerRegistry } from "../speakers.js";
import { maxSegmentExtent } from "./cluster.js";
import type { WearableConversation } from "../types.js";
import type {
  FusionConversationInput,
  FusionOptions,
  FusionSegmentInput,
  FusedDisagreement,
  FusedSegment,
  FusedSpeaker,
  SegmentPickReason,
} from "./types.js";

/** Default max drift (ms) for two segments to align across sources. */
export const DEFAULT_WINDOW_TOLERANCE_MS = 30_000;
/** Default trust weight for a source with no configured prior. */
export const DEFAULT_SOURCE_TRUST = 0.8;
/** Trust prior at which a source is considered "more trusted" than another. */
const TRUST_DECISION_EPSILON = 1e-9;
/** Labels that cannot be confidently cross-matched between sources.
 * Raw provider diarization keys (e.g. Omi `SPEAKER_00`) are generic too:
 * they carry no cross-source identity, so they get the same lowered
 * confidence as bare "Speaker N". */
const GENERIC_LABEL_PATTERN = /^(Speaker \d+|Unknown speaker|SPEAKER_\d+)$/i;

export interface FuseClusterResult {
  sources: string[];
  speakers: FusedSpeaker[];
  title?: string;
  summary?: string;
  startIso: string;
  endIso?: string;
  segments: FusedSegment[];
  disagreements: FusedDisagreement[];
}

interface TaggedSegment {
  source: string;
  conversationId: string;
  speakerLabel: string;
  isSelf: boolean;
  text: string;
  startMs: number;
  startIso?: string;
  endIso?: string;
  sourceTrust: number;
  /** Original position in the flattened input (sources in first-appearance
   * order, then segment order within each source). Carried through
   * alignment so equal-time segments keep their transcript sequence. */
  originalIndex: number;
}

interface AlignGroup {
  /** Match key: "self" for the wearer, else the resolved label. */
  key: string;
  speakerLabel: string;
  isSelf: boolean;
  members: TaggedSegment[];
  anchorMs: number;
  /** The anchor member's ORIGINAL start ISO — the canonical utterance
   * time the fused segment is emitted at (groups are sorted by anchorMs,
   * so the emitted startIso must come from here, not from the chosen
   * higher-trust source's later clock, or pre-sorted chronology breaks).
   * Undefined for untimestamped (missing-start) groups. */
  anchorStartIso?: string;
  /** The anchor member's ORIGINAL end ISO, when known. */
  anchorEndIso?: string;
  /** Earliest original sequence index among members — the secondary sort
   * key so equal-anchorMs groups keep transcript/source order. */
  originalIndex: number;
}

/** Match key that unifies the wearer across sources. */
function speakerKey(label: string, isSelf: boolean): string {
  return isSelf ? "self" : label;
}

function resolveTrust(
  source: string,
  trustMap: Record<string, number> | undefined,
): number {
  const value = trustMap?.[source];
  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.min(1, Math.max(0, value));
  }
  return DEFAULT_SOURCE_TRUST;
}

/** Lowercased, punctuation-stripped word sequence — order-sensitive. */
function normalizeWords(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, " ")
    .split(/\s+/)
    .filter((word) => word.length > 0);
}

function wordsEqual(a: string[], b: string[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

/** True when `short` is an exact leading prefix of `long` (truncation). */
function isWordPrefix(short: string[], long: string[]): boolean {
  if (short.length === 0 || short.length > long.length) return false;
  for (let i = 0; i < short.length; i++) {
    if (short[i] !== long[i]) return false;
  }
  return true;
}

/** Whether two normalized word sequences corroborate the SAME utterance.
 * Exact match always corroborates; a leading-word-prefix (truncation)
 * corroborates only when `allowPrefix` is set (timestamped alignment),
 * so the more-complete-wins override can reunite a clipped transcript
 * with its full wording. Untimed alignment passes `allowPrefix = false`
 * and demands an exact word match. */
function wordsCorroborate(
  a: string[],
  b: string[],
  allowPrefix: boolean,
): boolean {
  if (wordsEqual(a, b)) return true;
  if (!allowPrefix) return false;
  return isWordPrefix(a, b) || isWordPrefix(b, a);
}

function clamp01(value: number): number {
  if (!Number.isFinite(value)) return 0;
  return Math.min(1, Math.max(0, value));
}

/**
 * Build fusion inputs from raw provider conversations + the shared
 * speaker registry. This is the precise connector path: full ISO
 * timestamps and resolved speaker labels. (The on-demand service path
 * instead reconstructs inputs from stored transcripts — see
 * `reconstruct.ts`.)
 */
export function fusionInputsFromConversations(
  sourceId: string,
  conversations: readonly WearableConversation[],
  registry: SpeakerRegistry,
): FusionConversationInput[] {
  return conversations.map((conversation) => {
    const segments: FusionSegmentInput[] = conversation.segments.map((raw) => {
      const resolved = resolveSpeaker(sourceId, raw, registry);
      return {
        speaker: resolved.label,
        isSelf: resolved.isSelf,
        text: raw.text,
        ...(raw.startIso !== undefined ? { startIso: raw.startIso } : {}),
        ...(raw.endIso !== undefined ? { endIso: raw.endIso } : {}),
      };
    });
    return {
      source: sourceId,
      conversationId: conversation.id,
      startIso: conversation.startIso,
      ...(conversation.endIso !== undefined ? { endIso: conversation.endIso } : {}),
      ...(conversation.title !== undefined ? { title: conversation.title } : {}),
      ...(conversation.summary !== undefined ? { summary: conversation.summary } : {}),
      segments,
    };
  });
}

/**
 * Fuse one cluster into a reconciled conversation (without id/date).
 */
export function fuseCluster(
  cluster: readonly FusionConversationInput[],
  options: FusionOptions = {},
): FuseClusterResult {
  const trustMap = options.sourceTrust;
  const toleranceMs = options.windowToleranceMs ?? DEFAULT_WINDOW_TOLERANCE_MS;

  // Sources in first-appearance order.
  const sources: string[] = [];
  const sourcesSeen = new Set<string>();
  for (const conv of cluster) {
    if (!sourcesSeen.has(conv.source)) {
      sourcesSeen.add(conv.source);
      sources.push(conv.source);
    }
  }

  // Earliest start / latest end across the cluster. The fused END considers
  // BOTH every conversation's explicit endIso AND every segment's own extent
  // (endIso ?? startIso) across ALL members: a stored transcript whose
  // heading end renders as "--:--" rebuilds segments with only a start, so
  // its later segment starts must still extend the fused window — otherwise
  // a source with an explicit SHORT end would clip the fused conversation
  // before the missing-end source's last utterance (issue #1849). Segment
  // extents use the SAME `maxSegmentExtent` primitive as the cluster
  // interval, so there is one coherent end derivation in the pipeline.
  let startMs = Number.POSITIVE_INFINITY;
  let endMs = Number.NEGATIVE_INFINITY;
  let startIso: string | undefined;
  let endIso: string | undefined;
  for (const conv of cluster) {
    const ms = Date.parse(conv.startIso);
    if (Number.isFinite(ms) && ms < startMs) {
      startMs = ms;
      startIso = conv.startIso;
    }
    if (conv.endIso !== undefined) {
      const endM = Date.parse(conv.endIso);
      if (Number.isFinite(endM) && endM > endMs) {
        endMs = endM;
        endIso = conv.endIso;
      }
    }
  }
  // Fall back to / extend with the latest segment extent across ALL members
  // so a missing-end ("--:--") source's later segment starts are not lost.
  const segmentExtent = maxSegmentExtent(
    cluster.flatMap((conv) => conv.segments),
  );
  if (segmentExtent !== undefined && segmentExtent.ms > endMs) {
    endMs = segmentExtent.ms;
    endIso = segmentExtent.iso;
  }
  // Clamp the fused window end to >= start so it is always valid, mirroring
  // cluster.ts. A malformed explicit/derived end preceding the cluster start
  // would otherwise yield a negative-length window.
  if (endIso !== undefined && Number.isFinite(startMs) && endMs < startMs) {
    endIso = startIso;
    endMs = startMs;
  }
  if (startIso === undefined) {
    // No parseable start in the cluster — fall back to the first conv's
    // start string so the required field stays present downstream.
    startIso = cluster[0]?.startIso ?? new Date(0).toISOString();
  }

  // Title / summary: first non-empty in cluster order.
  let title: string | undefined;
  let summary: string | undefined;
  for (const conv of cluster) {
    if (title === undefined && conv.title !== undefined && conv.title.trim().length > 0) {
      title = conv.title.trim();
    }
    if (
      summary === undefined &&
      conv.summary !== undefined &&
      conv.summary.trim().length > 0
    ) {
      summary = conv.summary.trim();
    }
    if (title !== undefined && summary !== undefined) break;
  }

  // Flatten + tag every segment with its source provenance and trust.
  const tagged: TaggedSegment[] = [];
  for (const conv of cluster) {
    const sourceTrust = resolveTrust(conv.source, trustMap);
    for (const segment of conv.segments) {
      const startMsValue =
        segment.startIso !== undefined ? Date.parse(segment.startIso) : NaN;
      tagged.push({
        source: conv.source,
        conversationId: conv.conversationId,
        speakerLabel: segment.speaker,
        isSelf: segment.isSelf,
        text: segment.text,
        startMs: Number.isFinite(startMsValue)
          ? (startMsValue as number)
          : Number.POSITIVE_INFINITY,
        ...(segment.startIso !== undefined ? { startIso: segment.startIso } : {}),
        ...(segment.endIso !== undefined ? { endIso: segment.endIso } : {}),
        sourceTrust,
        originalIndex: tagged.length,
      });
    }
  }

  // Deterministic order: time first. Equal-time (and both-missing)
  // segments keep their ORIGINAL transcript/source sequence instead of
  // being scrambled by source or speaker label, so minute-precision and
  // untimestamped utterances are not reordered relative to their input.
  tagged.sort((a, b) => {
    const aFinite = Number.isFinite(a.startMs);
    const bFinite = Number.isFinite(b.startMs);
    if (aFinite && bFinite && a.startMs !== b.startMs) return a.startMs - b.startMs;
    if (aFinite !== bFinite) return aFinite ? -1 : 1;
    return a.originalIndex - b.originalIndex;
  });

  // Greedy cross-source alignment: a group holds at most one segment per
  // source (so two sequential same-source utterances never collapse). A
  // segment joins an existing group when their time windows match (or both
  // are untimestamped) AND the text corroborates the SAME utterance.
  // Speaker is matched in two tiers: first an exact same-speaker group;
  // only when none exists does a segment join a group whose utterance
  // corroborates but whose speaker label DISAGREES. That is a speaker
  // conflict on the same utterance — fused into one segment and recorded
  // as a disagreement (see reconcileGroup) rather than emitted as two
  // separate segments. This does NOT collapse distinct utterances: the
  // text must corroborate, so different-worded same-window segments
  // (the r2 separation) still stay apart.
  const groups: AlignGroup[] = [];
  for (const seg of tagged) {
    const key = speakerKey(seg.speakerLabel, seg.isSelf);
    const segMissing = !Number.isFinite(seg.startMs);
    const segWords = normalizeWords(seg.text);

    // True when `group` has room for `seg`'s source and corroborates the
    // same utterance (matching time window + corroborating text). Speaker
    // is intentionally NOT tested here — the caller decides whether a
    // same-speaker match or a speaker-conflict match is acceptable.
    const corroborates = (group: AlignGroup): boolean => {
      if (group.members.some((member) => member.source === seg.source)) {
        return false;
      }
      // Missing-start segments only align with other missing-start groups.
      const groupMissing = !Number.isFinite(group.anchorMs);
      if (groupMissing !== segMissing) return false;
      if (!groupMissing && Math.abs(seg.startMs - group.anchorMs) > toleranceMs) {
        return false;
      }
      // Cross-source corroboration gate: distinct utterances that merely
      // share a speaker and a time window (timestamped) — or a speaker key
      // alone (untimed) — must NOT collapse. Timestamped alignment accepts
      // an exact word match OR a leading-word prefix (truncation) so the
      // more-complete-wins override can reunite a clipped transcript with
      // its full wording; untimed alignment has no anchor, so exact only.
      return group.members.some((member) =>
        wordsCorroborate(normalizeWords(member.text), segWords, !groupMissing),
      );
    };

    // Choose the CLOSEST corroborating group instead of the first match
    // (issue #1849). Within windowToleranceMs several groups can corroborate
    // the same short utterance — e.g. a speaker repeating "yes" at 10:00 and
    // 10:20 with a 30s window — so a later source segment at 10:21
    // corroborates BOTH. First-match would attach it to the earliest (10:00)
    // group even though 10:20 is nearer, misattributing provenance and
    // potentially reordering the fused timeline. Scan every candidate and
    // keep the one whose anchor is nearest to this segment by
    // |anchorMs - startMs|; ties break on the smaller anchor, then on the
    // order the group was created (stable, never dependent on key order).
    // Single-occurrence behavior is unchanged: the lone corroborating group
    // is trivially the closest.
    const closestCorroborating = (
      wantSameSpeaker: boolean,
    ): AlignGroup | undefined => {
      let best: AlignGroup | undefined;
      let bestDelta = Infinity;
      for (const group of groups) {
        if (
          (group.key === key) !== wantSameSpeaker ||
          !corroborates(group)
        ) {
          continue;
        }
        const delta =
          !segMissing && Number.isFinite(group.anchorMs)
            ? Math.abs(seg.startMs - group.anchorMs)
            : 0;
        if (
          best === undefined ||
          delta < bestDelta ||
          (delta === bestDelta && group.anchorMs < best.anchorMs)
        ) {
          best = group;
          bestDelta = delta;
        }
      }
      return best;
    };

    // Prefer an exact same-speaker corroborating group.
    let chosen = closestCorroborating(true);
    if (chosen === undefined) {
      // Fall back: same utterance (time+text corroborate) but a different
      // speaker label -> speaker conflict, aligned into one segment.
      chosen = closestCorroborating(false);
    }

    if (chosen !== undefined) {
      chosen.members.push(seg);
      if (seg.originalIndex < chosen.originalIndex) {
        chosen.originalIndex = seg.originalIndex;
      }
    } else {
      groups.push({
        key,
        speakerLabel: seg.speakerLabel,
        isSelf: seg.isSelf,
        members: [seg],
        anchorMs: seg.startMs,
        // The creating segment is the EARLIEST member (tagged is
        // time-sorted), so its clock IS the group anchor that groups are
        // sorted by and that the fused segment must be emitted at.
        anchorStartIso: seg.startIso,
        anchorEndIso: seg.endIso,
        originalIndex: seg.originalIndex,
      });
    }
  }

  // Output groups in time order; missing-start groups last. Equal-anchorMs
  // (and all-missing) groups tie-break on original transcript/source
  // sequence — not source/speaker label — so equal-time utterances keep
  // the order they appeared in their input transcripts.
  groups.sort((a, b) => {
    const aMissing = !Number.isFinite(a.anchorMs);
    const bMissing = !Number.isFinite(b.anchorMs);
    if (aMissing !== bMissing) return aMissing ? 1 : -1;
    if (!aMissing && a.anchorMs !== b.anchorMs) return a.anchorMs - b.anchorMs;
    return a.originalIndex - b.originalIndex;
  });

  const segments: FusedSegment[] = [];
  const disagreements: FusedDisagreement[] = [];
  for (const group of groups) {
    const reconciled = reconcileGroup(group);
    segments.push(reconciled.segment);
    disagreements.push(...reconciled.disagreements);
  }
  // Belt-and-suspenders: segments are built from anchor-sorted groups with
  // each segment's startIso pinned to its group anchor, so the array is
  // already chronological. This explicit, STABLE re-sort guarantees that
  // invariant end to end — no trust-based text/content swap can ever
  // reorder the timeline, even if a future change alters how a fused
  // segment's timestamp is derived. Stability contract:
  //   - timestamped segments sort by startMs ascending;
  //   - missing/invalid timestamps keep their position (timestamped before
  //     missing, preserving original relative order among missing ones);
  //   - equal timestamps preserve prior order via a deterministic secondary
  //     key (the pre-sort index), never reordering by source/speaker — so
  //     cross-source clock skew does not scramble same-anchor utterances.
  const preSortOrder = new Map(segments.map((seg, i) => [seg, i]));
  segments.sort((a, b) => {
    const aMs = a.startIso !== undefined ? Date.parse(a.startIso) : Number.NaN;
    const bMs = b.startIso !== undefined ? Date.parse(b.startIso) : Number.NaN;
    const aFinite = Number.isFinite(aMs);
    const bFinite = Number.isFinite(bMs);
    if (aFinite && bFinite) {
      if (aMs !== bMs) return aMs - bMs;
    } else if (aFinite !== bFinite) {
      return aFinite ? -1 : 1;
    }
    // Equal timestamp (or both missing): preserve prior order — never let
    // a naive ts-only comparator scramble equal/missing-time entries.
    return (preSortOrder.get(a) ?? 0) - (preSortOrder.get(b) ?? 0);
  });
  // Cross-segment ASR disagreements: distinct utterances kept as separate
  // segments (never collapsed) yet sharing a speaker + time window and
  // disagreeing on wording. Neither side's content is lost — both remain
  // visible segments — but the unresolved conflict is still surfaced for
  // review and each involved segment's confidence is lowered, matching
  // how an in-group conflict is flagged.
  detectCrossSegmentDisagreements(segments, toleranceMs, disagreements);

  const result: FuseClusterResult = {
    sources,
    speakers: collectSpeakers(tagged),
    startIso,
    segments,
    disagreements,
  };
  if (endIso !== undefined) result.endIso = endIso;
  if (title !== undefined) result.title = title;
  if (summary !== undefined) result.summary = summary;
  return result;
}

interface ReconciledGroup {
  segment: FusedSegment;
  disagreements: FusedDisagreement[];
}

function reconcileGroup(group: AlignGroup): ReconciledGroup {
  const members = group.members;
  // Rank: higher trust, then more-complete (longer), then stable source
  // order, finally the original transcript index — a total order so the
  // comparator returns 0 only for an identical item (never nonzero on a
  // tie), keeping the sort stable and contract-compliant.
  const ranked = [...members].sort((a, b) => {
    if (Math.abs(b.sourceTrust - a.sourceTrust) > TRUST_DECISION_EPSILON) {
      return b.sourceTrust - a.sourceTrust;
    }
    if (b.text.length !== a.text.length) return b.text.length - a.text.length;
    if (a.source !== b.source) return a.source < b.source ? -1 : 1;
    if (a.conversationId !== b.conversationId) {
      return a.conversationId < b.conversationId ? -1 : 1;
    }
    return a.originalIndex - b.originalIndex;
  });
  const top = ranked[0];
  const topWords = normalizeWords(top.text);

  // Truncation override: the top-ranked (highest-trust) member may be a
  // CLIPPED version of a corroborating candidate — e.g. a summary source
  // clipped at "The deploy window opens at" while a verbatim source has
  // the full sentence. Trust dominates the rank, so without this the
  // truncated high-trust text would win despite the documented
  // "more-complete wins" rule. When the top's words are a strict prefix of
  // another member's words, adopt the LONGEST such more-complete member's
  // text + provenance.
  let chosen = top;
  if (topWords.length > 0) {
    let bestLen = -1;
    for (const candidate of ranked) {
      if (candidate === top) continue;
      const candidateWords = normalizeWords(candidate.text);
      if (
        isWordPrefix(topWords, candidateWords) &&
        candidateWords.length > topWords.length &&
        candidateWords.length > bestLen
      ) {
        chosen = candidate;
        bestLen = candidateWords.length;
      }
    }
  }
  const truncatedOverride = chosen !== top;
  const others = ranked.filter((member) => member !== chosen);

  const chosenWords = normalizeWords(chosen.text);

  const reason: SegmentPickReason =
    members.length === 1
      ? "only-source"
      : truncatedOverride
        ? "more-complete"
        : others.some(
            (r) => chosen.sourceTrust - r.sourceTrust > TRUST_DECISION_EPSILON,
          )
          ? "higher-trust"
          : others.some((r) => chosen.text.length - r.text.length > 0)
            ? "more-complete"
            : "tie-break";

  // Conflict detection: a candidate whose word sequence differs from the
  // chosen text AND is not a containment (one a prefix/truncation of the
  // other). Containment is "more-complete wins" with no disagreement.
  const disagree: Array<{ source: string; value: string }> = [];
  let conflict = false;
  for (const candidate of others) {
    const candidateWords = normalizeWords(candidate.text);
    if (chosenWords.length === 0 && candidateWords.length === 0) continue;
    if (wordsEqual(chosenWords, candidateWords)) continue;
    if (
      isWordPrefix(candidateWords, chosenWords) ||
      isWordPrefix(chosenWords, candidateWords)
    ) {
      continue;
    }
    conflict = true;
    disagree.push({ source: candidate.source, value: candidate.text });
  }

  // Speaker-attribution conflict: members of the same utterance disagree
  // on who spoke (same time window + corroborating text, different label).
  // Detected from member labels — not the group key — so a group that
  // absorbed a conflicting speaker is handled identically. The chosen
  // (top-ranked) member's attribution wins the segment provisionally;
  // every source's label is surfaced as a disagreement with full
  // provenance so no attribution is silently lost.
  const distinctSpeakerKeys = new Set(
    members.map((m) => speakerKey(m.speakerLabel, m.isSelf)),
  );
  const speakerConflict = distinctSpeakerKeys.size > 1;

  const alternatives = others.map((candidate) => ({
    source: candidate.source,
    text: candidate.text,
  }));

  // Confidence: single source -> its trust; corroboration boosts; a
  // recorded text OR speaker conflict lowers it.
  const confidence =
    conflict || speakerConflict
      ? clamp01(chosen.sourceTrust * 0.7)
      : members.length > 1
        ? clamp01(chosen.sourceTrust + 0.1 * (members.length - 1))
        : clamp01(chosen.sourceTrust);

  // TIMELINE POSITION (startIso/endIso) comes from the group/window ANCHOR
  // — the canonical utterance time the groups are sorted by — NOT from the
  // chosen (higher-trust) source's clock. The chosen source may be LATER
  // than the anchor (a low-trust utterance at 10:00 corroborated by a
  // high-trust source at 10:25 within tolerance); emitting chosen.startIso
  // would print the fused segment at 10:25 even though the group sits at
  // the 10:00 anchor, jumping it past an intervening 10:10 utterance and
  // corrupting the chronology. The chosen source still provides the TEXT;
  // only the timeline position is anchored. Its original clock is kept in
  // provenance so the source's recording time stays traceable.
  const segment: FusedSegment = {
    speaker: chosen.speakerLabel,
    isSelf: chosen.isSelf,
    text: chosen.text,
    confidence,
    provenance: {
      source: chosen.source,
      conversationId: chosen.conversationId,
      sourceTrust: chosen.sourceTrust,
      reason,
      alternatives,
      ...(chosen.startIso !== undefined
        ? { sourceStartIso: chosen.startIso }
        : {}),
      ...(chosen.endIso !== undefined ? { sourceEndIso: chosen.endIso } : {}),
    },
    ...(group.anchorStartIso !== undefined
      ? { startIso: group.anchorStartIso }
      : {}),
    ...(group.anchorEndIso !== undefined ? { endIso: group.anchorEndIso } : {}),
  };

  const disagreements: FusedDisagreement[] = [];
  // The disagreement subject is the EMITTED timeline position (the group
  // anchor), coherent with segment.startIso — not the chosen source's
  // possibly-later clock.
  const anchorIso =
    group.anchorStartIso ??
    (Number.isFinite(group.anchorMs)
      ? new Date(group.anchorMs).toISOString()
      : undefined);
  if (conflict) {
    disagreements.push({
      kind: "asr-text",
      subject: anchorIso ?? "(no timestamp)",
      candidates: [{ source: chosen.source, value: chosen.text }, ...disagree],
      provisional: { source: chosen.source, value: chosen.text },
    });
  }
  if (speakerConflict) {
    // One candidate per source (a group holds one member per source),
    // sorted by source for determinism; the chosen source is provisional.
    const speakerCandidates = members
      .map((m) => ({ source: m.source, value: m.speakerLabel }))
      .sort((a, b) =>
        a.source < b.source ? -1 : a.source > b.source ? 1 : 0,
      );
    disagreements.push({
      kind: "speaker",
      subject: anchorIso ?? "(no timestamp)",
      candidates: speakerCandidates,
      provisional: { source: chosen.source, value: chosen.speakerLabel },
    });
  }

  return { segment, disagreements };
}

/**
 * Detect ASR-text disagreements BETWEEN segments that were intentionally
 * kept separate (distinct utterances) yet share a speaker and a time
 * window and disagree on wording. Unlike an in-group conflict (same
 * utterance bridged by a truncation), these never merged — so neither
 * side's content is lost — but the unresolved disagreement is still
 * surfaced for review and each involved segment's confidence is lowered.
 *
 * Timestamped only: untimestamped segments have no window anchor to compare
 * against. Mutates `confidence` on involved segments and appends to `out`.
 */
function detectCrossSegmentDisagreements(
  segments: FusedSegment[],
  toleranceMs: number,
  out: FusedDisagreement[],
): void {
  const n = segments.length;
  if (n < 2) return;
  const claimed = new Array<boolean>(n).fill(false);
  for (let i = 0; i < n; i++) {
    if (claimed[i]) continue;
    const seed = segments[i]!;
    const seedMs =
      seed.startIso !== undefined ? Date.parse(seed.startIso) : NaN;
    if (!Number.isFinite(seedMs)) continue;
    const seedWords = normalizeWords(seed.text);
    const clusterIdx: number[] = [];
    for (let j = i + 1; j < n; j++) {
      if (claimed[j]) continue;
      const cand = segments[j]!;
      // Speaker identity is matched via speakerKey() — the SAME
      // normalization grouping uses (line 305) — not the raw display
      // label. The wearer is often labeled differently per source (e.g.
      // "Me (you)" vs an override "Alex (you)"); both normalize to
      // "self". Matching on the raw label would skip them, leaving a real
      // same-window ASR-text disagreement undetected and both confidences
      // wrongly high. (Issue #1849.)
      if (
        speakerKey(cand.speaker, cand.isSelf) !==
        speakerKey(seed.speaker, seed.isSelf)
      ) {
        continue;
      }
      if (cand.provenance.source === seed.provenance.source) continue;
      const candMs =
        cand.startIso !== undefined ? Date.parse(cand.startIso) : NaN;
      if (!Number.isFinite(candMs)) continue;
      if (Math.abs(candMs - seedMs) > toleranceMs) continue;
      if (wordsCorroborate(seedWords, normalizeWords(cand.text), true)) {
        continue;
      }
      clusterIdx.push(j);
    }
    if (clusterIdx.length === 0) continue;
    clusterIdx.unshift(i);
    for (const idx of clusterIdx) claimed[idx] = true;

    const involved = clusterIdx.map((idx) => segments[idx]!);
    // Stable secondary key: each involved segment's position in the
    // reconciled segment array (clusterIdx is ascending). Two cands can
    // share a source, so source alone is NOT a total order here; the
    // position tie-break makes the comparator return 0 only for an
    // identical item and keeps the ranking deterministic — mirroring
    // reconcileGroup's originalIndex tie-break.
    const involvedOrder = new Map(involved.map((seg, i) => [seg, i]));
    involved.sort((a, b) => {
      if (
        Math.abs(b.provenance.sourceTrust - a.provenance.sourceTrust) >
        TRUST_DECISION_EPSILON
      ) {
        return b.provenance.sourceTrust - a.provenance.sourceTrust;
      }
      if (b.text.length !== a.text.length) return b.text.length - a.text.length;
      if (a.provenance.source !== b.provenance.source) {
        return a.provenance.source < b.provenance.source ? -1 : 1;
      }
      return involvedOrder.get(a)! - involvedOrder.get(b)!;
    });
    const provisional = involved[0]!;
    const anchorIso = involved
      .map((s) => s.startIso)
      .filter((v): v is string => v !== undefined)
      .sort()[0];

    for (const seg of involved) {
      seg.confidence = clamp01(seg.provenance.sourceTrust * 0.7);
    }

    out.push({
      kind: "asr-text",
      subject: anchorIso ?? "(no timestamp)",
      candidates: involved.map((s) => ({
        source: s.provenance.source,
        value: s.text,
      })),
      provisional: {
        source: provisional.provenance.source,
        value: provisional.text,
      },
    });
  }
}

/**
 * Build the reconciled speaker list. The wearer unifies across all
 * sources; generic labels (bare "Speaker N" or a raw key) seen in only
 * one source get a lowered confidence since they could not be
 * confidently matched across sources.
 */
function collectSpeakers(tagged: readonly TaggedSegment[]): FusedSpeaker[] {
  interface Acc {
    label: string;
    isSelf: boolean;
    sources: Set<string>;
    generic: boolean;
  }
  const order: string[] = [];
  const acc = new Map<string, Acc>();
  for (const seg of tagged) {
    const key = speakerKey(seg.speakerLabel, seg.isSelf);
    let entry = acc.get(key);
    if (entry === undefined) {
      entry = {
        label: seg.speakerLabel,
        isSelf: seg.isSelf,
        sources: new Set<string>(),
        generic: GENERIC_LABEL_PATTERN.test(seg.speakerLabel),
      };
      acc.set(key, entry);
      order.push(key);
    }
    entry.sources.add(seg.source);
  }
  return order.map((key) => {
    const entry = acc.get(key);
    if (entry === undefined) throw new Error("fusion speaker accumulator miss");
    const sourceCount = entry.sources.size;
    const confidence = entry.isSelf
      ? sourceCount > 1
        ? 0.95
        : 0.85
      : entry.generic
        ? sourceCount > 1
          ? 0.7
          : 0.5
        : sourceCount > 1
          ? 0.9
          : 0.7;
    return {
      label: entry.label,
      isSelf: entry.isSelf,
      confidence,
      sources: [...entry.sources].sort(),
    };
  });
}

/**
 * Wearable cross-source fusion — day-level orchestrator.
 *
 * Takes every enabled source's normalized conversations for one day,
 * clusters them across sources, reconciles each cluster, and attaches a
 * stable content-hash id so re-running over unchanged inputs produces a
 * byte-identical artifact (idempotent — no duplicate files).
 *
 * Deterministic end to end: no timestamps from "now", no LLM, no
 * randomness. The only time-derived value is the `fusedAt` frontmatter
 * field added at storage time (excluded from the content hash).
 */

import { createHash } from "node:crypto";
import { clusterConversations } from "./cluster.js";
import {
  DEFAULT_SOURCE_TRUST,
  DEFAULT_WINDOW_TOLERANCE_MS,
  fuseCluster,
  type FuseClusterResult,
} from "./reconcile.js";
import { DEFAULT_PROXIMITY_GAP_MS } from "./cluster.js";
import type {
  FusionConversationInput,
  FusionDayResult,
  FusionOptions,
  FusedConversationProvenance,
  FusedWearableConversation,
} from "./types.js";

const FUSION_ID_PREFIX = "fusion";
/**
 * Fusion algorithm/schema version. Folded into the day content hash (the
 * idempotency key) so a change to the clustering, reconciliation, or
 * reconstruction algorithm invalidates cached artifacts even when the raw
 * inputs and fusion config are byte-identical — pre-existing `_fusion/`
 * files are regenerated rather than served stale. Bump this whenever the
 * fusion algorithm meaningfully changes (this PR changed it repeatedly).
 * The per-conversation id (`canonicalInputsKey`) is intentionally NOT
 * folded with the version, so a conversation keeps a stable identity.
 */
export const FUSION_ALGO_VERSION = "2026-07-12-1";

/**
 * Canonical, stable serialization of a set of fusion inputs — the base
 * for the per-conversation id. Input-only so a conversation keeps a
 * stable identity across re-runs regardless of input order. The day
 * content hash additionally folds the effective fusion config (see
 * `canonicalDayKey`) so a config change invalidates the cached artifact.
 */
function canonicalInputsKey(
  date: string,
  inputs: readonly FusionConversationInput[],
): string {
  const sorted = [...inputs].sort((a, b) => {
    if (a.source !== b.source) return a.source < b.source ? -1 : 1;
    if (a.conversationId !== b.conversationId) {
      return a.conversationId < b.conversationId ? -1 : 1;
    }
    return 0;
  });
  // Serialize the structured tuples UNAMBIGUOUSLY before hashing. The old
  // `|`/newline-delimited form could collide: a speaker label or segment
  // text containing `|` (or a newline plus a forged `seg|…`/`conv|…`
  // prefix) could make two DISTINCT inputs serialize to identical bytes,
  // hashing alike — so fuseDay wrongly took the idempotent-skip path and
  // kept serving a stale artifact. JSON string quoting makes every field
  // boundary unforgeable, and the positional array order is the
  // deterministic key order (no object keys to sort).
  const record = [
    date,
    sorted.map((conv) => [
      conv.source,
      conv.conversationId,
      conv.startIso,
      conv.endIso ?? "",
      conv.title ?? "",
      conv.summary ?? "",
      conv.segments.map((segment) => [
        segment.speaker,
        segment.isSelf ? "self" : "other",
        segment.startIso ?? "",
        segment.endIso ?? "",
        segment.text,
      ]),
    ]),
  ];
  return createHash("sha256").update(JSON.stringify(record), "utf-8").digest("hex");
}

/**
 * Effective-config fingerprint folded into the day content hash so a
 * change to any clustering/reconciliation knob (proximity gap, window
 * tolerance, or per-source trust) invalidates the cached artifact.
 * Defaults are resolved so an explicit default hashes identically to an
 * omission, keeping the skip-unchanged path deterministic. Only sources
 * that actually contribute to the day are included, so a trust change
 * for an absent source cannot spuriously trigger a rebuild.
 */
function configFingerprint(
  options: FusionOptions,
  sources: readonly string[],
): string {
  const proximityGapMs = options.proximityGapMs ?? DEFAULT_PROXIMITY_GAP_MS;
  const windowToleranceMs =
    options.windowToleranceMs ?? DEFAULT_WINDOW_TOLERANCE_MS;
  const trustMap = options.sourceTrust ?? {};
  // JSON form so a source id (or future field) containing `|` cannot forge
  // a trust-entry boundary and collide two distinct effective configs into
  // one day hash.
  const trustEntries = [...new Set(sources)]
    .sort()
    .map((source) => [source, trustMap[source] ?? DEFAULT_SOURCE_TRUST]);
  return JSON.stringify([proximityGapMs, windowToleranceMs, trustEntries]);
}

/**
 * Day idempotency key: the input-only hash combined with the effective
 * fusion-config fingerprint AND the fusion algorithm version. Same inputs +
 * same config + same version => same hash (no duplicate rewrite); a config
 * change OR an algorithm-version bump => new hash => rebuild. The version
 * is what forces regeneration when the ALGORITHM itself changes but the
 * inputs and config are byte-identical (issue #1849).
 */
export function canonicalDayKey(
  date: string,
  inputs: readonly FusionConversationInput[],
  options: FusionOptions,
  algoVersion: string = FUSION_ALGO_VERSION,
): string {
  const inputsKey = canonicalInputsKey(date, inputs);
  const fingerprint = configFingerprint(
    options,
    inputs.map((conv) => conv.source),
  );
  return createHash("sha256")
    .update(inputsKey)
    .update("\n")
    .update(fingerprint)
    .update("\n")
    .update(algoVersion)
    .digest("hex");
}

function buildProvenance(
  cluster: readonly FusionConversationInput[],
  proximityGapMs: number,
  windowToleranceMs: number,
): FusedConversationProvenance {
  return {
    contributions: cluster.map((conv) => ({
      source: conv.source,
      conversationId: conv.conversationId,
      startIso: conv.startIso,
      ...(conv.endIso !== undefined ? { endIso: conv.endIso } : {}),
      segmentCount: conv.segments.length,
    })),
    proximityGapMs,
    windowToleranceMs,
    method: "time-proximity",
  };
}

/**
 * Fuse every source's conversations for one day into a stable result.
 * Empty input yields an empty (but well-formed) result so callers can
 * treat "nothing to fuse" uniformly.
 */
export function fuseDay(
  date: string,
  inputs: readonly FusionConversationInput[],
  options: FusionOptions = {},
): FusionDayResult {
  const proximityGapMs = options.proximityGapMs ?? DEFAULT_PROXIMITY_GAP_MS;
  const windowToleranceMs =
    options.windowToleranceMs ?? DEFAULT_WINDOW_TOLERANCE_MS;

  const clusters = clusterConversations(inputs, proximityGapMs);
  const conversations: FusedWearableConversation[] = clusters.map((cluster) => {
    const fused: FuseClusterResult = fuseCluster(cluster, {
      ...options,
      windowToleranceMs,
    });
    const id = `${FUSION_ID_PREFIX}-${canonicalInputsKey(date, cluster).slice(0, 24)}`;
    const result: FusedWearableConversation = {
      id,
      date,
      startIso: fused.startIso,
      sources: fused.sources,
      speakers: fused.speakers,
      segments: fused.segments,
      disagreements: fused.disagreements,
      provenance: buildProvenance(cluster, proximityGapMs, windowToleranceMs),
    };
    if (fused.endIso !== undefined) result.endIso = fused.endIso;
    if (fused.title !== undefined) result.title = fused.title;
    if (fused.summary !== undefined) result.summary = fused.summary;
    return result;
  });

  const sourcesSeen = new Set<string>();
  const sources: string[] = [];
  for (const conv of conversations) {
    for (const source of conv.sources) {
      if (!sourcesSeen.has(source)) {
        sourcesSeen.add(source);
        sources.push(source);
      }
    }
  }

  return {
    date,
    conversations,
    sources,
    contentHash: canonicalDayKey(date, inputs, options),
  };
}

/**
 * Wearable cross-source fusion — derived-day file serialization.
 *
 * One derived file per fused day, stored ALONGSIDE raw source transcripts
 * (under the wearables tree) but never overwriting them. Format mirrors
 * the day-transcript convention: YAML frontmatter (`kind:
 * wearable-fusion`) + a JSON body carrying the structured
 * `FusedWearableConversation[]`. The frontmatter `contentHash` is the
 * idempotency key derived from inputs plus the effective fusion config,
 * so an unchanged re-run (same inputs AND config) produces a
 * byte-identical file.
 */

import { createHash } from "node:crypto";
import * as path from "node:path";
import { pathIsInside } from "../../utils/path-containment.js";
import { isValidTranscriptDate } from "../day-store.js";
import type {
  FusedDayFile,
  FusedDayMeta,
  FusedWearableConversation,
} from "./types.js";

export const FUSION_KIND = "wearable-fusion" as const;

/** Hash the canonical JSON body for idempotent skip-unchanged checks. */
export function hashFusionBody(
  conversations: readonly FusedWearableConversation[],
): string {
  return createHash("sha256")
    .update(JSON.stringify(conversations), "utf-8")
    .digest("hex");
}

export function composeFusionDayMeta(
  date: string,
  conversations: readonly FusedWearableConversation[],
  sources: readonly string[],
  contentHash: string,
  fusedAt: string,
): FusedDayMeta {
  return {
    kind: FUSION_KIND,
    date,
    sourceCount: sources.length,
    conversationCount: conversations.length,
    contentHash,
    bodyHash: hashFusionBody(conversations),
    fusedAt,
  };
}

/** Serialize meta + conversations into the persisted file format. */
export function serializeFusionDay(
  meta: FusedDayMeta,
  conversations: readonly FusedWearableConversation[],
): string {
  const lines: string[] = ["---"];
  lines.push(`kind: ${meta.kind}`);
  lines.push(`date: ${JSON.stringify(meta.date)}`);
  lines.push(`sourceCount: ${meta.sourceCount}`);
  lines.push(`conversationCount: ${meta.conversationCount}`);
  lines.push(`contentHash: ${JSON.stringify(meta.contentHash)}`);
  lines.push(`bodyHash: ${JSON.stringify(meta.bodyHash)}`);
  lines.push(`fusedAt: ${JSON.stringify(meta.fusedAt)}`);
  lines.push("---");
  lines.push("");
  return `${lines.join("\n")}\n${JSON.stringify(conversations, null, 2)}\n`;
}

function parseScalar(value: string): string {
  const trimmed = value.trim();
  if (trimmed.startsWith('"') && trimmed.endsWith('"') && trimmed.length >= 2) {
    try {
      const parsed = JSON.parse(trimmed);
      if (typeof parsed === "string") return parsed;
    } catch {
      // Fall through to the raw value below.
    }
  }
  return trimmed;
}

function parseNonNegativeInt(value: string | undefined): number {
  if (value === undefined) return 0;
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) return 0;
  return Math.floor(parsed);
}

const FUSED_SEGMENT_PICK_REASONS: Record<string, true> = {
  "only-source": true,
  "higher-trust": true,
  "more-complete": true,
  "tie-break": true,
};

const FUSED_DISAGREEMENT_KINDS: Record<string, true> = {
  "asr-text": true,
  speaker: true,
  timestamp: true,
};

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((item) => typeof item === "string");
}

/** Structural guard for a parsed segment-provenance record. */
function isFusedSegmentProvenance(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (typeof value.source !== "string") return false;
  if (typeof value.conversationId !== "string") return false;
  if (typeof value.sourceTrust !== "number") return false;
  if (typeof value.reason !== "string") return false;
  if (!(value.reason in FUSED_SEGMENT_PICK_REASONS)) return false;
  return (
    Array.isArray(value.alternatives) &&
    value.alternatives.every(
      (alt) =>
        isPlainObject(alt) && typeof alt.source === "string" && typeof alt.text === "string",
    )
  );
}

/** Structural guard for a parsed fused segment. */
function isFusedSegment(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (typeof value.speaker !== "string") return false;
  if (typeof value.isSelf !== "boolean") return false;
  if (typeof value.text !== "string") return false;
  if (typeof value.confidence !== "number") return false;
  return isFusedSegmentProvenance(value.provenance);
}

/** Structural guard for a parsed fused speaker. */
function isFusedSpeaker(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (typeof value.label !== "string") return false;
  if (typeof value.isSelf !== "boolean") return false;
  if (typeof value.confidence !== "number") return false;
  return isStringArray(value.sources);
}

/** Structural guard for a parsed fused disagreement. */
function isFusedDisagreement(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (typeof value.kind !== "string") return false;
  if (!(value.kind in FUSED_DISAGREEMENT_KINDS)) return false;
  if (typeof value.subject !== "string") return false;
  return (
    Array.isArray(value.candidates) &&
    value.candidates.every(
      (cand) =>
        isPlainObject(cand) && typeof cand.source === "string" && typeof cand.value === "string",
    )
  );
}

/** Structural guard for a parsed fused-conversation contribution record. */
function isFusedContribution(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (typeof value.source !== "string") return false;
  if (typeof value.conversationId !== "string") return false;
  if (typeof value.startIso !== "string") return false;
  return typeof value.segmentCount === "number";
}

/** Structural guard for a parsed fused-conversation provenance record. */
function isFusedConversationProvenance(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (!Array.isArray(value.contributions) || !value.contributions.every(isFusedContribution)) {
    return false;
  }
  if (typeof value.proximityGapMs !== "number") return false;
  if (typeof value.windowToleranceMs !== "number") return false;
  return value.method === "time-proximity";
}

/**
 * Structural guard for a parsed fused conversation. Every required field of
 * `FusedWearableConversation` (and its nested segments / speakers /
 * disagreements / provenance) must be present with the right shape, so a
 * null, wrong-typed, or partial element (`[{}]`, `[null]`, `[{id:1}]`) is
 * rejected and the caller treats the body as corrupt (parseOk:false →
 * self-repair rewrite) rather than trusting it.
 */
function isFusedWearableConversation(value: unknown): value is FusedWearableConversation {
  if (!isPlainObject(value)) return false;
  if (typeof value.id !== "string") return false;
  if (typeof value.date !== "string") return false;
  if (typeof value.startIso !== "string") return false;
  if (!isStringArray(value.sources)) return false;
  if (!Array.isArray(value.speakers) || !value.speakers.every(isFusedSpeaker)) return false;
  if (!Array.isArray(value.segments) || !value.segments.every(isFusedSegment)) return false;
  if (!Array.isArray(value.disagreements) || !value.disagreements.every(isFusedDisagreement)) {
    return false;
  }
  return isFusedConversationProvenance(value.provenance);
}

/**
 * Parse a persisted fused-day file. Returns null when the content does
 * not look like a fusion artifact (wrong kind / missing frontmatter) so
 * callers can distinguish "not fused" from a malformed file. A non-null
 * result carries `parseOk`: false when the JSON body failed to parse, was
 * not an array, or held a malformed element (conversations is empty in
 * that case), true for a well-formed (incl. legitimately-empty `[]`)
 * body — so the skip-unchanged path can force a self-repair rewrite
 * regardless of the recomputed conversation count or body hash.
 */
export function parseFusionDay(raw: string): FusedDayFile | null {
  if (!raw.startsWith("---\n")) return null;
  const closeIndex = raw.indexOf("\n---\n", 4);
  if (closeIndex === -1) return null;
  const header = raw.slice(4, closeIndex);
  const body = raw.slice(closeIndex + 5).replace(/^\n/, "");

  const scalars = new Map<string, string>();
  for (const line of header.split("\n")) {
    const match = line.match(/^([A-Za-z][A-Za-z0-9]*): (.*)$/);
    if (match) scalars.set(match[1], parseScalar(match[2]));
  }

  if (scalars.get("kind") !== FUSION_KIND) return null;
  const date = scalars.get("date");
  if (date === undefined) return null;

  let conversations: FusedWearableConversation[] = [];
  let parseOk = true;
  const bodyTrimmed = body.trim();
  if (bodyTrimmed.length === 0) {
    // An existing artifact whose body is blank or whitespace-only (no
    // JSON at all) is corrupt — it is NOT a valid empty `[]`. The
    // serializer always writes `JSON.stringify(conversations, null, 2)`
    // which produces `[]` for zero conversations, so a blank body means
    // the file was truncated, partially written, or manually emptied.
    // Flag parseOk:false so fusedConversations() surfaces the corruption
    // and fuseDay() repairs it (issue #1849).
    parseOk = false;
  } else {
    try {
      const parsed: unknown = JSON.parse(bodyTrimmed);
      if (Array.isArray(parsed) && parsed.every(isFusedWearableConversation)) {
        conversations = parsed;
      } else {
        // Valid JSON but not a well-formed FusedWearableConversation[]
        // (non-array, or an array carrying a null / wrong-typed /
        // missing-required-field element) — flag corrupt so callers
        // recompute fusion rather than trusting a partial read. A
        // legitimately-empty [] is accepted with parseOk left true.
        parseOk = false;
      }
    } catch {
      // A truncated/corrupt body fails to parse; flag parseOk:false so the
      // skip-unchanged path forces a self-repair rewrite (even when the
      // frontmatter hash matches and the recomputed count is also zero).
      parseOk = false;
    }
  }

  const meta: FusedDayMeta = {
    kind: FUSION_KIND,
    date,
    sourceCount: parseNonNegativeInt(scalars.get("sourceCount")),
    conversationCount: parseNonNegativeInt(scalars.get("conversationCount")),
    contentHash: scalars.get("contentHash") ?? "",
    bodyHash: scalars.get("bodyHash") ?? "",
    fusedAt: scalars.get("fusedAt") ?? "",
  };
  return { meta, conversations, parseOk };
}

/** Reserved underscore-prefixed subdir for derived fusion artifacts. */
export const FUSION_DIR_NAME = "_fusion";

/**
 * Encrypted-at-rest + atomic file IO the fusion artifact store needs.
 * Satisfied by StorageManager (which owns the secure-store key + atomic
 * write path) and injected so this module performs NO direct fs — the
 * derived files inherit the same encrypted-at-rest + atomic-write
 * semantics as raw day transcripts without this module knowing the key.
 */
export interface FusionFileIo {
  writeFile(filePath: string, content: string): Promise<void>;
  /** Read a file; rejects with ENOENT when it is absent. */
  readFile(filePath: string): Promise<string>;
  /** Directory entries; rejects with ENOENT when the directory is absent. */
  readDir(dirPath: string): Promise<string[]>;
  /** Remove a file; rejects with ENOENT when it is absent. */
  deleteFile(filePath: string): Promise<void>;
  /**
   * Resolve a path through symlinks (node:fs/promises realpath); rejects
   * with ENOENT when the path is absent. Used by the symlink-containment
   * guard so a symlinked `_fusion` dir (or a symlinked wearables root)
   * that resolves outside the memory dir is rejected before any
   * read/write/delete (AGENTS.md #3).
   */
  realpath(filePath: string): Promise<string>;
  /**
   * Stat a path WITHOUT following a trailing symlink
   * (node:fs/promises lstat); rejects with ENOENT when the path is
   * absent. Used to detect a pre-existing symlink at the fusion
   * artifact directory itself, which is rejected even when its
   * target resolves inside the memory dir (issue #1849).
   */
  lstat(filePath: string): Promise<{ isSymbolicLink: boolean }>;
}

/**
 * Owns the derived fused-day artifact files under
 * `<wearablesDir>/_fusion/<YYYY-MM-DD>.md`. Path construction, date
 * validation, and newest-first listing live here (relocated out of the
 * root storage module — issue #1810 ratchet); the bytes flow through the
 * injected secure IO.
 */
export class FusionArtifactStore {
  constructor(
    private readonly wearablesDir: string,
    private readonly memoryDir: string,
    private readonly io: FusionFileIo,
  ) {}

  fusedDayPath(date: string): string {
    if (!isValidTranscriptDate(date)) {
      throw new Error(
        `invalid wearable fusion date '${String(date)}' — expected YYYY-MM-DD`,
      );
    }
    return path.join(this.wearablesDir, FUSION_DIR_NAME, `${date}.md`);
  }

  async writeFusedDay(date: string, serialized: string): Promise<void> {
    const filePath = this.fusedDayPath(date);
    await this.assertPathContained(filePath);
    await this.io.writeFile(filePath, serialized);
  }

  /** Read a stored fused-day artifact; null when absent. */
  async readFusedDay(date: string): Promise<string | null> {
    const filePath = this.fusedDayPath(date);
    await this.assertPathContained(filePath);
    try {
      return await this.io.readFile(filePath);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw err;
    }
  }

  /**
   * Remove a stored fused-day artifact. Idempotent: a no-op when the
   * artifact is already absent. Used to clear a now-stale derived file
   * before a fusion run that deliberately refuses to fuse (e.g. a day
   * whose sources later conflict on timezone) so fusedConversations()
   * does not keep serving a stale view (issue #1849).
   */
  async deleteFusedDay(date: string): Promise<void> {
    const filePath = this.fusedDayPath(date);
    await this.assertPathContained(filePath);
    try {
      await this.io.deleteFile(filePath);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return;
      throw err;
    }
  }

  /** List dates with stored fused artifacts, newest first. */
  async listFusedDays(): Promise<string[]> {
    const fusionDir = path.join(this.wearablesDir, FUSION_DIR_NAME);
    await this.assertPathContained(fusionDir);
    let entries: string[];
    try {
      entries = await this.io.readDir(fusionDir);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
      throw err;
    }
    const days: string[] = [];
    for (const entry of entries) {
      if (!entry.endsWith(".md")) continue;
      const date = entry.slice(0, -3);
      if (!isValidTranscriptDate(date)) continue;
      days.push(date);
    }
    days.sort((a, b) => (a > b ? -1 : a < b ? 1 : 0));
    return days;
  }

  /**
   * Reject a symlinked/traversing fusion artifact path before any IO. The
   * fusion dir (`<wearablesDir>/_fusion`) and its parents are followed
   * directly by the secure IO; a symlink placed there (attacker-writable
   * or a malformed memory dir) would otherwise be followed and
   * read/write/delete outside the allowed root (AGENTS.md pattern #3).
   *
   * Containment is anchored to the real MEMORY-DIR root, not the
   * wearables dir, AND the wearables root is checked explicitly: if
   * `wearablesDir` itself is a symlink that resolves outside memoryDir, a
   * leaf candidate like `<wearablesDir>/_fusion/<date>.md` may not yet
   * exist (so its realpath ENOENT-skips) and the write would silently
   * create the file inside the symlinked escape target. Checking
   * `wearablesDir` itself — which resolves through the symlink when it
   * exists — closes that gap, while the per-leaf checks catch a nested
   * `_fusion` or per-file symlink. Absent paths are allowed (a fresh
   * write creates them lexically under the root; only a path that
   * resolves to an existing target can redirect IO). Mirrors
   * `assertPathInsideRoot` in the storage walkers.
   */
  private async assertPathContained(targetPath: string): Promise<void> {
    let rootReal: string;
    try {
      rootReal = await this.io.realpath(this.memoryDir);
    } catch {
      // Fresh memory dir not yet on disk — no symlink can resolve through
      // a missing root, so fall back to a lexical resolve.
      rootReal = path.resolve(this.memoryDir);
    }
    // The wearables root first (catches a symlinked wearables dir even
    // when the leaf artifact does not yet exist), then the fusion dir and
    // the target file itself.
    await this.assertNoEscape(rootReal, this.wearablesDir);
    await this.assertNoEscape(rootReal, path.dirname(targetPath));
    await this.assertNoEscape(rootReal, targetPath);
    // Reject a symlinked `_fusion` dir outright — even when its
    // target resolves INSIDE the memory dir. The managed fusion root
    // is always a real directory created by the secure write; a
    // pre-existing link there is tampering/aliasing and is refused
    // before a single byte is written or read (issue #1849).
    await this.assertFusionDirNotSymlinked();
  }

  /**
   * Refuse a pre-existing symbolic link at the `<wearablesDir>/_fusion`
   * directory. Unlike `assertNoEscape` (which follows the link and only
   * rejects when the target lands outside the memory dir), this catches a
   * fusion root that aliases an in-bounds path — e.g. a `_fusion` link
   * pointed at a raw source transcript — so fusion IO never writes
   * through it and overwrites the aliased file. Absent dirs are allowed
   * (a fresh write creates a real directory lexically under the root).
   */
  private async assertFusionDirNotSymlinked(): Promise<void> {
    const fusionDir = path.join(this.wearablesDir, FUSION_DIR_NAME);
    let stat: { isSymbolicLink: boolean };
    try {
      stat = await this.io.lstat(fusionDir);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return;
      throw err;
    }
    if (stat.isSymbolicLink) {
      throw new Error(
        "wearable fusion dir '_fusion' is a symbolic link — refusing to follow it even when it resolves inside the memory dir (AGENTS.md pattern #3)",
      );
    }
  }

  /**
   * Refuse a candidate whose realpath escapes the memory root. Absent
   * candidates are allowed: a missing path cannot yet redirect IO, and
   * the secure write creates it lexically under the root.
   */
  private async assertNoEscape(rootReal: string, candidate: string): Promise<void> {
    let candidateReal: string;
    try {
      candidateReal = await this.io.realpath(candidate);
    } catch {
      return; // absent — nothing to follow
    }
    if (!pathIsInside(rootReal, candidateReal)) {
      throw new Error(
        "wearable fusion artifact path resolves outside the memory dir — refusing to follow a symlink/traversal (AGENTS.md pattern #3)",
      );
    }
  }
}

/**
 * Wearable cross-source fusion — reconstruct inputs from stored transcripts.
 *
 * The on-demand service path fuses from already-synced day transcripts
 * (offline, no connector calls). Those files store a human-readable
 * markdown body, so this module parses it back into the normalized
 * `FusionConversationInput[]` shape the fusion engine consumes.
 *
 * Precision caveat (documented, accepted for this foundational PR):
 * the rendered body carries minute-precision clock times in the
 * configured timezone. We reconstruct them as `${date}T${HH}:${MM}:00Z`
 * — every source for a given day is rendered in the SAME timezone, so
 * relative within-day comparisons and time-window alignment stay
 * correct even though the absolute ISO is timezone-normalized. Full
 * segment-level alignment with sub-minute precision is a deferred
 * follow-up (see PR body).
 */

import {
  isValidTranscriptDate,
  parseTranscriptSegmentLine,
  unescapeSegmentText,
  unescapeSpeakerLabel,
} from "../day-store.js";
import { hasSelfMarker } from "../speakers.js";
import type {
  FusionConversationInput,
  FusionSegmentInput,
} from "./types.js";

const CONVERSATION_HEADING =
  /^## (.+?)\u2013(.+?)(?:\s\u00b7\s(.*))?\s\(conversation (.+)\)$/;
const LOCATION_LINE = /^\*Location: (.+)\*$/;
const CLOCK_PATTERN = /^(\d{2}):(\d{2})$/;

/** Minutes in a 24-hour day. */
const MINUTES_PER_DAY = 24 * 60;

/**
 * Upper bound on a plausible single-conversation duration, used to decide
 * whether an earlier heading end clock (or segment clock) is a genuine
 * midnight wrap (start -> midnight -> end/segment within this bound)
 * versus a malformed/ordinary earlier clock that should stay on the same
 * date and be clamped downstream. Generous enough that any legitimate
 * overnight wrap a wearable source would emit still rolls forward; tight
 * enough that a near-24h implied span (e.g. 14:00 -> 13:00) is treated as
 * the error it almost certainly is instead of producing a day-spanning
 * window that broadly clusters unrelated neighbors (#1849).
 */
const MAX_PLAUSIBLE_WRAP_MINUTES = 12 * 60;

/** Rendered clock ("HH:MM") -> timezone-normalized ISO; "--:--" -> undefined. */
function clockToIso(clock: string, date: string): string | undefined {
  const match = CLOCK_PATTERN.exec(clock.trim());
  if (match === null) return undefined;
  // en-US hour12:false renders the first wall-clock hour (00:xx) as 24:xx
  // on some ICU builds. CLOCK_PATTERN matches "24", which would build an
  // invalid ISO (24:01-24:59 => NaN) or a next-day instant (24:00 => start
  // of next day). Normalize to 00:xx on the SAME rendered date; cross-
  // midnight conversation windows are rolled forward by the caller.
  const hour = match[1] === "24" ? "00" : match[1];
  return `${date}T${hour}:${match[2]}:00.000Z`;
}

/**
 * Minutes-of-day for a rendered clock (24:xx normalized to 0), or
 * undefined when the clock is not parseable (e.g. "--:--"). Used to
 * detect conversations that wrap past midnight.
 */
function clockMinutesOfDay(clock: string): number | undefined {
  const match = CLOCK_PATTERN.exec(clock.trim());
  if (match === null) return undefined;
  const hour = match[1] === "24" ? 0 : Number.parseInt(match[1], 10);
  return hour * 60 + Number.parseInt(match[2], 10);
}

/** Increment a YYYY-MM-DD date string by one calendar day (UTC arithmetic). */
function nextCalendarDay(date: string): string {
  const [y, m, d] = date.split("-").map((part) => Number.parseInt(part, 10));
  const dt = new Date(Date.UTC(y, m - 1, d));
  dt.setUTCDate(dt.getUTCDate() + 1);
  const yy = dt.getUTCFullYear();
  const mm = String(dt.getUTCMonth() + 1).padStart(2, "0");
  const dd = String(dt.getUTCDate()).padStart(2, "0");
  return `${yy}-${mm}-${dd}`;
}

/**
 * Reconstruct fusion inputs for a day from one or more sources' stored
 * transcript bodies. Each body is the markdown produced by
 * `composeDayTranscriptBody` (frontmatter already stripped by the
 * caller via `parseDayTranscript`).
 */
export function reconstructFusionInputs(
  date: string,
  dayTranscripts: ReadonlyArray<{
    source: string;
    body: string;
    /**
     * Whether the body was written by the escape-aware serializer
     * (`bodyIsEscaped(meta)`). When falsy (legacy) the segment text and
     * speaker label are used verbatim — no escape decoding — so a legacy
     * transcript's literal two-character `\n`/`\r` is never altered
     * (issue #1849).
     */
    escaped?: boolean;
  }>,
): FusionConversationInput[] {
  if (!isValidTranscriptDate(date)) return [];
  const inputs: FusionConversationInput[] = [];

  for (const { source, body, escaped } of dayTranscripts) {
    let current: {
      conversationId: string;
      title?: string;
      startIso?: string;
      endIso?: string;
      segments: FusionSegmentInput[];
      /** True when the heading end clock precedes the start clock (the
       * conversation window wrapped past midnight); rolls `endIso` forward.
       * Post-midnight SEGMENTS roll independently via `wrapStartMin`. */
      wrapped: boolean;
      wrapStartMin?: number;
    } | null = null;

    const flushCurrent = () => {
      if (current === null) return;
      const startIso =
        current.startIso ??
        current.segments.find((segment) => segment.startIso !== undefined)?.startIso ??
        `${date}T00:00:00.000Z`;
      const input: FusionConversationInput = {
        source,
        conversationId: current.conversationId,
        startIso,
        segments: current.segments,
      };
      if (current.endIso !== undefined) input.endIso = current.endIso;
      if (current.title !== undefined) input.title = current.title;
      inputs.push(input);
      current = null;
    };

    for (const rawLine of body.split("\n")) {
      const line = rawLine.trimEnd();
      if (line.length === 0) continue;

      const heading = CONVERSATION_HEADING.exec(line);
      if (heading !== null) {
        flushCurrent();
        const [, startClock, endClock, title, id] = heading;
        const startMin = clockMinutesOfDay(startClock);
        const endMin = clockMinutesOfDay(endClock);
        // A conversation whose end clock reads EARLIER than its start
        // clock MAY have wrapped past midnight. Roll its end to the next
        // calendar day ONLY when the implied wrap duration (start ->
        // midnight -> end) is within a plausible single-conversation
        // bound; a near-24h implied span (e.g. start 14:00, end 13:00)
        // is almost certainly a malformed/ordinary earlier clock, not a
        // midnight crossing. Leaving that end on the SAME date keeps
        // endIso < startIso so the downstream cluster clamp collapses it
        // to the start instead of stretching the window across most of
        // the day and broadly clustering unrelated neighbors (#1849).
        // Post-midnight SEGMENTS roll independently below under the SAME
        // plausibility bound: a segment whose clock precedes the start
        // clock is rolled only when the implied wrap is plausible.
        const wrapped =
          startMin !== undefined && endMin !== undefined && endMin < startMin;
        const wrapDuration =
          startMin !== undefined && endMin !== undefined
            ? MINUTES_PER_DAY - startMin + endMin
            : undefined;
        const plausibleWrap =
          wrapped &&
          wrapDuration !== undefined &&
          wrapDuration <= MAX_PLAUSIBLE_WRAP_MINUTES;
        const startIso = clockToIso(startClock, date);
        const endIso = plausibleWrap
          ? clockToIso(endClock, nextCalendarDay(date))
          : clockToIso(endClock, date);
        current = {
          conversationId: id,
          segments: [],
          wrapped,
          ...(startMin !== undefined ? { wrapStartMin: startMin } : {}),
          ...(startIso !== undefined ? { startIso } : {}),
          ...(endIso !== undefined ? { endIso } : {}),
          ...(title !== undefined && title.length > 0 ? { title } : {}),
        };
        continue;
      }

      if (LOCATION_LINE.exec(line) !== null) continue;

      const segmentMatch = parseTranscriptSegmentLine(line);
      if (segmentMatch !== null) {
        if (current === null) continue; // segment outside any conversation
        const { label, clock, text: rawText } = segmentMatch;
        const text = escaped ? unescapeSegmentText(rawText) : rawText;
        const segMin = clockMinutesOfDay(clock);
        // A segment clock EARLIER than the conversation start clock MAY
        // have crossed midnight. Roll it to the next calendar day ONLY
        // when the implied wrap duration (start -> midnight -> segment)
        // is within the SAME plausible single-conversation bound as the
        // heading end; a near-24h implied span (e.g. start 14:00,
        // segment 13:00) is almost certainly a malformed/provider-skew
        // earlier clock, not a midnight crossing. Leaving it on the SAME
        // date keeps segIso < startIso so the downstream cluster clamp
        // collapses it instead of stretching the interval across most of
        // the day and broadly clustering unrelated neighbors (#1849).
        // Driven by the segment-vs-start comparison directly — NOT gated
        // on `wrapped` — so a heading whose end is missing/unparseable
        // (e.g. `## 23:55–--:--`) still rolls a plausible `[00:05]`
        // segment forward.
        const segWrapDuration =
          current.wrapStartMin !== undefined && segMin !== undefined
            ? MINUTES_PER_DAY - current.wrapStartMin + segMin
            : undefined;
        const plausibleSegWrap =
          current.wrapStartMin !== undefined &&
          segMin !== undefined &&
          segMin < current.wrapStartMin &&
          segWrapDuration !== undefined &&
          segWrapDuration <= MAX_PLAUSIBLE_WRAP_MINUTES;
        const segDate = plausibleSegWrap ? nextCalendarDay(date) : date;
        const startIso = clockToIso(clock, segDate);
        // Decode the safely-serialized speaker label back to its original
        // form ONLY when the body is escape-aware; legacy raw labels are
        // used verbatim so their literal characters are never altered
        // (#1849).
        const speaker = escaped
          ? unescapeSpeakerLabel(label.trim())
          : label.trim();
        const segment: FusionSegmentInput = {
          speaker,
          // Self status is read from the RESERVED `(you)` marker, which the
          // renderer guarantees can only appear on the wearer's label -
          // never on a non-self display name (issue #1849).
          isSelf: hasSelfMarker(speaker),
          text,
          ...(startIso !== undefined ? { startIso } : {}),
        };
        current.segments.push(segment);
      }
      // Unrecognized lines (e.g. the H1 source header) are ignored.
    }
    flushCurrent();
  }

  return inputs;
}

/**
 * AES-256-GCM encrypt / decrypt primitives for the secure-store
 * module.
 *
 * Issue #690 (PR 1/4) — pure primitives, no I/O.
 *
 * Sealed envelope format
 * ----------------------
 * A "sealed" buffer is the canonical on-disk shape for a single
 * encrypted blob. It contains the salt used to derive the key from
 * the user's passphrase, so a caller who has the passphrase + the
 * sealed buffer can decrypt without any external metadata.
 *
 *   [VERSION:1][SALT:16][IV:12][AUTHTAG:16][CIPHERTEXT:...]
 *
 *   - VERSION (1 byte): envelope format version. Currently 1. Future
 *     versions can change the layout (e.g. variable salt length, an
 *     algorithm identifier byte) by bumping this byte.
 *   - SALT (16 bytes): KDF salt. Persisted with the ciphertext so the
 *     same passphrase can re-derive the key on read.
 *   - IV (12 bytes): GCM nonce. Must be unique per (key, ciphertext)
 *     pair. We generate it fresh from `randomBytes` on every encrypt
 *     call. Reusing an IV with the same key destroys GCM's
 *     confidentiality and authenticity guarantees.
 *   - AUTHTAG (16 bytes): GCM authentication tag. Tampering with any
 *     byte of (salt | iv | tag | ciphertext) causes decryption to
 *     fail with an auth-tag mismatch.
 *   - CIPHERTEXT (variable): the encrypted payload.
 *
 * The salt is stored alongside the ciphertext (rather than only in a
 * separate metadata file) so an individual encrypted blob is
 * self-contained for diagnostics and recovery. The metadata file
 * (see `metadata.ts`) records the *canonical* salt + KDF params for a
 * store; the per-blob salt is expected to match the metadata salt in
 * normal operation, but the format does not require it — a future PR
 * could rotate per-blob salts if desired.
 *
 * AAD support
 * -----------
 * Callers can pass associated authenticated data (AAD) — typically a
 * file path or namespace tag — that is authenticated but not
 * encrypted. AAD must be supplied identically on encrypt and decrypt;
 * a mismatch causes auth-tag failure. AAD is NOT serialized into the
 * envelope; the caller is responsible for re-supplying it on decrypt.
 */

import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

/** Current envelope format version. */
export const ENVELOPE_VERSION = 1 as const;

/** GCM nonce length. 96 bits is the NIST-recommended size for AES-GCM. */
export const IV_LENGTH = 12;

/** GCM authentication tag length. 16 bytes (128 bits) — the maximum. */
export const AUTH_TAG_LENGTH = 16;

/** Salt length carried in the envelope. Must match KDF_SALT_LENGTH. */
export const ENVELOPE_SALT_LENGTH = 16;

/** Required key length for AES-256. */
export const AES_KEY_LENGTH = 32;

/** Byte offsets of each envelope field (for clarity at call sites). */
export const ENVELOPE_LAYOUT = Object.freeze({
  version: 0,
  salt: 1,
  iv: 1 + ENVELOPE_SALT_LENGTH,
  authTag: 1 + ENVELOPE_SALT_LENGTH + IV_LENGTH,
  ciphertext: 1 + ENVELOPE_SALT_LENGTH + IV_LENGTH + AUTH_TAG_LENGTH,
});

/** Minimum envelope size: header + zero-length ciphertext. */
export const ENVELOPE_HEADER_SIZE = ENVELOPE_LAYOUT.ciphertext;

export interface EncryptOptions {
  /**
   * Optional associated data — authenticated but not encrypted.
   * Caller must supply the same value on decrypt.
   */
  aad?: Uint8Array;
  /**
   * Override the per-call IV. Strongly discouraged outside of tests:
   * GCM is catastrophically broken if an IV is reused under the same
   * key. Production callers should always let the cipher generate a
   * fresh random IV.
   */
  iv?: Uint8Array;
}

export interface DecryptOptions {
  /** Same AAD that was supplied to `encrypt`. */
  aad?: Uint8Array;
}

/**
 * Validate that a key is a 32-byte buffer suitable for AES-256.
 */
function assertAesKey(key: Uint8Array): void {
  if (!(key instanceof Uint8Array)) {
    throw new Error("key must be a Uint8Array");
  }
  if (key.length !== AES_KEY_LENGTH) {
    throw new Error(
      `AES-256-GCM requires a ${AES_KEY_LENGTH}-byte key, got ${key.length}`,
    );
  }
}

/**
 * Encrypt `plaintext` under `key` and return a sealed envelope buffer.
 *
 * @param key 32-byte AES-256 key (from `deriveKey`).
 * @param salt 16-byte KDF salt to embed in the envelope. The caller is
 *   responsible for using the same salt that was passed to the KDF.
 * @param plaintext the bytes to encrypt.
 * @param options optional `aad` / `iv` overrides.
 */
export function seal(
  key: Uint8Array,
  salt: Uint8Array,
  plaintext: Uint8Array,
  options: EncryptOptions = {},
): Buffer {
  assertAesKey(key);
  if (!(salt instanceof Uint8Array) || salt.length !== ENVELOPE_SALT_LENGTH) {
    throw new Error(
      `salt must be ${ENVELOPE_SALT_LENGTH} bytes, got ${salt?.length ?? "non-buffer"}`,
    );
  }
  if (!(plaintext instanceof Uint8Array)) {
    throw new Error("plaintext must be a Uint8Array");
  }
  let iv: Uint8Array;
  if (options.iv) {
    if (options.iv.length !== IV_LENGTH) {
      throw new Error(`iv must be ${IV_LENGTH} bytes, got ${options.iv.length}`);
    }
    iv = options.iv;
  } else {
    iv = randomBytes(IV_LENGTH);
  }

  const cipher = createCipheriv("aes-256-gcm", Buffer.from(key), Buffer.from(iv), {
    authTagLength: AUTH_TAG_LENGTH,
  });
  // Codex P1: bind the envelope header (version + salt) into AAD so
  // flipping the salt or version on a sealed envelope triggers an
  // auth failure on open. Without this, callers using a metadata-
  // derived store key would still decrypt successfully even after
  // the per-blob salt was tampered with — silently desynchronizing
  // per-blob salt from metadata/recovery logic. Caller-supplied AAD
  // is appended after the header so existing AAD usage stays intact.
  const headerAad = buildHeaderAad(salt);
  const finalAad = options.aad
    ? Buffer.concat([headerAad, Buffer.from(options.aad)])
    : headerAad;
  cipher.setAAD(finalAad);
  const ciphertext = Buffer.concat([cipher.update(Buffer.from(plaintext)), cipher.final()]);
  const authTag = cipher.getAuthTag();
  if (authTag.length !== AUTH_TAG_LENGTH) {
    // Defensive: Node always produces 16 bytes when authTagLength is 16.
    throw new Error(`unexpected auth tag length: ${authTag.length}`);
  }

  const envelope = Buffer.alloc(ENVELOPE_HEADER_SIZE + ciphertext.length);
  envelope.writeUInt8(ENVELOPE_VERSION, ENVELOPE_LAYOUT.version);
  Buffer.from(salt).copy(envelope, ENVELOPE_LAYOUT.salt);
  Buffer.from(iv).copy(envelope, ENVELOPE_LAYOUT.iv);
  authTag.copy(envelope, ENVELOPE_LAYOUT.authTag);
  ciphertext.copy(envelope, ENVELOPE_LAYOUT.ciphertext);
  return envelope;
}

/** Parsed view of a sealed envelope. Useful for inspection in tests. */
export interface ParsedEnvelope {
  version: number;
  salt: Buffer;
  iv: Buffer;
  authTag: Buffer;
  ciphertext: Buffer;
}

/**
 * Parse a sealed envelope into its component fields without
 * decrypting. Throws on malformed input. The returned buffers are
 * sub-views (not copies) — do not mutate.
 */
export function parseEnvelope(envelope: Uint8Array): ParsedEnvelope {
  if (!(envelope instanceof Uint8Array)) {
    throw new Error("envelope must be a Uint8Array");
  }
  if (envelope.length < ENVELOPE_HEADER_SIZE) {
    throw new Error(
      `envelope too short: need ≥ ${ENVELOPE_HEADER_SIZE} bytes, got ${envelope.length}`,
    );
  }
  const buf = Buffer.from(envelope.buffer, envelope.byteOffset, envelope.byteLength);
  const version = buf.readUInt8(ENVELOPE_LAYOUT.version);
  if (version !== ENVELOPE_VERSION) {
    throw new Error(
      `unsupported envelope version: ${version} (this build supports ${ENVELOPE_VERSION})`,
    );
  }
  return {
    version,
    salt: buf.subarray(ENVELOPE_LAYOUT.salt, ENVELOPE_LAYOUT.salt + ENVELOPE_SALT_LENGTH),
    iv: buf.subarray(ENVELOPE_LAYOUT.iv, ENVELOPE_LAYOUT.iv + IV_LENGTH),
    authTag: buf.subarray(
      ENVELOPE_LAYOUT.authTag,
      ENVELOPE_LAYOUT.authTag + AUTH_TAG_LENGTH,
    ),
    ciphertext: buf.subarray(ENVELOPE_LAYOUT.ciphertext),
  };
}

/**
 * Decrypt a sealed envelope and return the plaintext.
 *
 * Throws on:
 *   - malformed envelope (wrong length, wrong version);
 *   - wrong key (auth-tag mismatch);
 *   - tampered ciphertext / iv / auth tag (auth-tag mismatch);
 *   - mismatched AAD (auth-tag mismatch).
 *
 * The same error class is intentional: from the caller's standpoint
 * "wrong passphrase" and "tampered ciphertext" should both be
 * non-recoverable failures.
 */
export function open(
  key: Uint8Array,
  envelope: Uint8Array,
  options: DecryptOptions = {},
): Buffer {
  assertAesKey(key);
  const parsed = parseEnvelope(envelope);
  const decipher = createDecipheriv("aes-256-gcm", Buffer.from(key), parsed.iv, {
    authTagLength: AUTH_TAG_LENGTH,
  });
  decipher.setAuthTag(parsed.authTag);
  // Codex P1: header (version + salt) is bound at seal time.
  // Reconstruct it identically so a tampered salt fails auth.
  const headerAad = buildHeaderAad(parsed.salt);
  const finalAad = options.aad
    ? Buffer.concat([headerAad, Buffer.from(options.aad)])
    : headerAad;
  decipher.setAAD(finalAad);
  // `final()` throws if the auth tag doesn't validate.
  return Buffer.concat([decipher.update(parsed.ciphertext), decipher.final()]);
}

/**
 * Build the canonical header AAD: a single byte version followed by
 * the per-blob salt. Binds the immutable envelope header into AES-GCM
 * authentication so tampering with either value triggers auth failure
 * on open (codex P1 on PR #718).
 */
function buildHeaderAad(salt: Uint8Array): Buffer {
  const out = Buffer.alloc(1 + ENVELOPE_SALT_LENGTH);
  out.writeUInt8(ENVELOPE_VERSION, 0);
  Buffer.from(salt).copy(out, 1);
  return out;
}

/**
 * Generate a fresh random salt of the canonical envelope length.
 * Convenience wrapper so callers don't reach into `node:crypto`.
 */
export function generateSalt(): Buffer {
  return randomBytes(ENVELOPE_SALT_LENGTH);
}

import { constants } from "node:fs";
import { lstat, open, readFile, realpath } from "node:fs/promises";
import path from "node:path";
import { assertPathInsideRoot } from "../utils/path-containment.js";

export async function readStoreFileBuffer(filePath: string, memoryDir: string): Promise<Buffer> {
  const root = path.resolve(memoryDir);
  const entities = path.join(root, "entities");
  const target = path.resolve(filePath);
  const relative = path.relative(entities, target);
  if (relative === ".." || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative)) {
    return readFile(filePath);
  }
  const handle = await open(target, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0) | (constants.O_NONBLOCK ?? 0));
  try {
    for (let parent = path.dirname(target); ; parent = path.dirname(parent)) {
      const info = await lstat(parent);
      if (info.isSymbolicLink() || !info.isDirectory()) {
        throw new Error(`Refusing unsafe entity directory: ${parent}.`);
      }
      if (parent === root) break;
    }
    const [opened, entry, realRoot, realEntities, realTarget] = await Promise.all([
      handle.stat(), lstat(target), realpath(root), realpath(entities), realpath(target),
    ]);
    if (!opened.isFile() || entry.isSymbolicLink() || !entry.isFile()
      || opened.dev !== entry.dev || opened.ino !== entry.ino
      || realEntities !== path.join(realRoot, "entities")) {
      throw new Error(`Refusing unsafe entity file: ${filePath}.`);
    }
    assertPathInsideRoot(realEntities, realTarget, filePath);
    return await handle.readFile();
  } finally {
    await handle.close();
  }
}


/**
 * Atomic-replacement-tolerant variant: entity writes ship as temp-file +
 * rename, so an open/lstat identity mismatch during a concurrent write is an
 * ordinary race, not tampering. Retry a bounded number of times with fresh
 * containment checks before surfacing the mismatch as unsafe.
 */
export async function readStoreFileBufferTolerant(filePath: string, memoryDir: string, attempts = 3): Promise<Buffer> {
  for (let attempt = 0; ; attempt += 1) {
    try {
      return await readStoreFileBuffer(filePath, memoryDir);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      const identityRace = /unsafe entity (?:file|directory)/.test(message);
      if (!identityRace || attempt >= attempts - 1) throw err;
    }
  }
}

/**
 * Temporal validity helpers (issue #680).
 *
 * `valid_at` / `invalid_at` are explicit ISO 8601 timestamps that mark when a
 * fact begins and ends being authoritative.  These helpers centralize the
 * read-time defaulting rules so every call site (recall filter, supersession
 * write, tests) agrees on the canonical semantics:
 *
 *   - `effectiveValidAt(fm)` — the moment this fact starts being true.
 *     Falls back to `created` when `valid_at` is absent so legacy memories
 *     written before #680 still participate in `as_of` filtering without
 *     a backfill migration.
 *   - `effectiveInvalidAt(fm)` — the moment this fact stops being true.
 *     Returns `undefined` when no `invalid_at` is set; supersession logic
 *     populates it on the older fact when a newer one replaces it.
 *   - `isValidAsOf(fm, asOfMs)` — true when the fact was authoritative at
 *     `asOfMs` (a numeric timestamp in ms).  Half-open interval semantics:
 *     `valid_at <= asOf < invalid_at`.  Strings are parsed via
 *     `Date.parse()` so timezone-suffixed ISO strings compare correctly
 *     (CLAUDE.md gotcha — never compare ISO strings lexicographically).
 *
 * Boundary case: when `invalid_at === asOf`, the fact is treated as NOT
 * valid (the upper bound is exclusive), which matches the supersession
 * model — at the instant a successor's `valid_at` fires, the predecessor
 * is no longer authoritative.
 */
import type { MemoryFrontmatter } from "./types.js";

export function effectiveValidAt(fm: Pick<MemoryFrontmatter, "valid_at" | "created">): string {
  // `created` is required on every memory (see types.ts), so the fallback
  // chain always terminates.  Trimming guards against whitespace-only
  // overrides written by legacy tooling.
  const explicit = fm.valid_at?.trim();
  if (explicit && explicit.length > 0) return explicit;
  return fm.created;
}

export function effectiveInvalidAt(
  fm: Pick<MemoryFrontmatter, "invalid_at" | "supersededAt" | "status">,
): string | undefined {
  const explicit = fm.invalid_at?.trim();
  if (explicit && explicit.length > 0) return explicit;
  // Cursor Medium rounds 1+2 on PR #713: legacy data written before
  // #680 has `status: superseded` and `supersededAt` populated, but
  // no `invalid_at`. With the new `as_of` filter bypassing the
  // supersession status check, those legacy predecessors would
  // otherwise be treated as "always valid" and surface alongside
  // their successors at every historical pin. Fall back to
  // `supersededAt` so the half-open `[valid_at, invalid_at)`
  // interval still terminates for legacy supersedes without
  // requiring a backfill migration.
  //
  // BOUNDARY APPROXIMATION: `supersededAt` is when the supersession
  // write fired, which may post-date the successor's true
  // `valid_at` (consolidation runs on its own cadence). So the
  // legacy predecessor stays visible from `valid_at` through
  // `supersededAt` rather than the tighter `valid_at` through
  // successor-`valid_at` window. We accept this intentionally: the
  // alternative — successor-aware coordination — would require
  // threading the successor through every call site, and "show the
  // legacy fact a bit too long" is a clear win over "drop legacy
  // facts entirely from `as_of`". New data (post-#680) writes
  // `invalid_at` directly and is unaffected.
  if (fm.status === "superseded") {
    const legacy = fm.supersededAt?.trim();
    if (legacy && legacy.length > 0) return legacy;
  }
  return undefined;
}

/**
 * Returns true when the fact was authoritative at `asOfMs` (parsed
 * milliseconds since epoch).  Half-open semantics: a fact is valid in
 * `[valid_at, invalid_at)`.
 *
 * If `valid_at` cannot be parsed, the fact is conservatively treated as
 * NOT valid at the requested point — we never silently default a corrupt
 * timestamp to "always true" because that would let bad data leak past
 * the historical filter (CLAUDE.md gotcha #34: distinguish empty from
 * malformed).
 */
export function isValidAsOf(
  fm: Pick<
    MemoryFrontmatter,
    | "valid_at"
    | "invalid_at"
    | "created"
    | "supersededAt"
    | "status"
    | "eventTimeSource"
  >,
  asOfMs: number,
): boolean {
  if (!Number.isFinite(asOfMs)) return true;
  // Open-start bi-temporal interval (#1578 r3): an extracted end-only bound
  // (eventTimeSource "extracted", no valid_at, has invalid_at) is true from
  // the indefinite past. Without this, effectiveValidAt falls back to
  // `created` and a historical as_of before ingestion hides a fact that was
  // actually true up until invalid_at (chatgpt-codex thread on
  // orchestrator.ts:15533). Gated on eventTimeSource so legacy memories
  // (no bi-temporal provenance) keep the created-anchor fallback.
  const explicitValidAt = fm.valid_at?.trim();
  if (
    (!explicitValidAt || explicitValidAt.length === 0) &&
    fm.eventTimeSource === "extracted"
  ) {
    const invalidAt = effectiveInvalidAt(fm);
    if (invalidAt !== undefined) {
      const invalidAtMs = Date.parse(invalidAt);
      if (Number.isFinite(invalidAtMs)) return invalidAtMs > asOfMs;
    }
  }
  const validAtMs = Date.parse(effectiveValidAt(fm));
  if (!Number.isFinite(validAtMs)) return false;
  if (validAtMs > asOfMs) return false;
  const invalidAt = effectiveInvalidAt(fm);
  if (invalidAt === undefined) return true;
  const invalidAtMs = Date.parse(invalidAt);
  // Unparseable invalid_at — conservatively keep the fact (we can read
  // valid_at, so we know the fact was at some point true; corrupt
  // invalid_at is not a reason to hide it).
  if (!Number.isFinite(invalidAtMs)) return true;
  // Half-open: at exactly invalid_at, the fact is no longer valid.
  return invalidAtMs > asOfMs;
}

/**
 * Bi-temporal injection filter (issue #1578).
 *
 * Returns `true` when the fact's event-time interval has already ended before
 * `nowMs` — i.e. it is no longer *true in the world* and should leave the
 * default injection candidate set (it remains findable by explicit search
 * and `as_of` queries, mirroring the lifecycle-filter escape-hatch principle
 * in AGENTS.md §16).  Gated by `temporalBiTemporal`; the escape hatch
 * `temporalExpiredInInjection` re-admits expired facts when a deployment
 * prefers the older always-inject behavior.
 *
 * Semantics: a fact is expired-now when `invalid_at` is present and
 * `invalid_at <= nowMs` (the exclusive upper bound has passed).  Absent
 * `invalid_at` means "still valid" — never expired.  This is the
 * status-orthogonal complement of `isValidAsOf` for the wall-clock instant:
 * an `active` memory can be validity-expired, and a `superseded` one can
 * still be validity-valid within its historical window (issue pitfall: the
 * filter is status-orthogonal).
 */
export function isValidityExpiredNow(
  fm: Pick<MemoryFrontmatter, "invalid_at">,
  nowMs: number,
): boolean {
  if (!Number.isFinite(nowMs)) return false;
  const invalidAt = fm.invalid_at?.trim();
  if (!invalidAt || invalidAt.length === 0) return false;
  const invalidAtMs = Date.parse(invalidAt);
  // Unparseable invalid_at — conservatively keep the fact (do not filter on
  // corrupt data; the as_of path already handles malformed bounds).
  if (!Number.isFinite(invalidAtMs)) return false;
  // Half-open interval end has passed: [valid_at, invalid_at) ended.
  return invalidAtMs <= nowMs;
}

/**
 * Parse and validate an `as_of` value supplied at an input boundary
 * (CLI flag, HTTP query param, MCP field).  Returns parsed milliseconds
 * on success; throws a `RangeError` with a helpful message on malformed
 * input.  CLAUDE.md rule 51 — never silently default invalid input.
 */
export function parseAsOfTimestamp(raw: unknown): number {
  if (typeof raw !== "string" || raw.trim().length === 0) {
    throw new RangeError(
      `as_of must be a non-empty ISO 8601 timestamp string (got: ${typeof raw === "string" ? `"${raw}"` : typeof raw})`,
    );
  }
  const ms = Date.parse(raw);
  if (!Number.isFinite(ms)) {
    throw new RangeError(
      `as_of must be a parseable ISO 8601 timestamp (got: "${raw}")`,
    );
  }
  return ms;
}

/**
 * Durable drain claims for the extraction buffer (`remnic buffer drain`).
 *
 * A claim is the atomic handover of one session's buffered turns from the
 * live buffer (daemon or CLI process) to a drain worker, so extraction can
 * run out of process without a live buffer owner resurrecting or losing the
 * turns. Files under `<stateDir>/buffer/drain/`:
 *
 *   s-<sha256(key)>.json        claim content: { key, entry, claimedAt }
 *                               — the turns NOT yet extracted. Renamed into
 *                               place from the session file (atomic on one
 *                               filesystem), rewritten atomically as chunks
 *                               drain.
 *   s-<sha256(key)>.lease.json  { ownerId, pid, acquiredAt, heartbeatAt,
 *                               leaseMs } — created with exclusive-create so
 *                               exactly one drainer holds a key.
 *
 * Invariants (see the buffer-drain PR for the full protocol):
 *   - At every instant the claim content file holds exactly the turns whose
 *     extraction is not durably finished, so a kill at any point loses
 *     nothing and the next run resumes.
 *   - A live buffer owner that must persist a claimed session hands its
 *     in-memory entry INTO the claim (merge, identity-deduped) instead of
 *     writing a session file — it can never resurrect claimed turns.
 *   - Claims are idempotent: re-claiming, double-draining, and two
 *     concurrent drainers are all safe (per-key mutation lock + exclusive
 *     lease; the lock also fences lease takeover and progress writes).
 *
 * All content reads/writes go through the storage's secure file I/O
 * (`BufferFileIo`); only lease/existence checks touch raw paths, and claim
 * rewrites serialize on a cross-process held file lock.
 */

import { hostname } from "node:os";
import { z } from "zod";
import { existsSync } from "node:fs";
import { mkdir, readdir, rename, unlink, writeFile } from "node:fs/promises";
import path from "node:path";

import { bufferSessionFileName, type BufferFileIo } from "./buffer-session-files.js";
import { bufferTurnsEqual, subtractBufferTurns } from "../buffer-turn-helpers.js";
import { log } from "../logger.js";
import { withHeldFileLock } from "../utils/serialize-mutations.js";
import type { BufferEntryState, BufferTurn } from "../types.js";

/** Result of persisting one session's entry. */
export interface BufferSessionSaveOutcome {
  /** "saved": the session file holds the entry. "handed_over": the entry moved into a drain claim. */
  status: "saved" | "handed_over";
  /** Turns a drain already extracted (claim tombstone): the owner subtracts them from its copy. */
  drainedTurns?: BufferTurn[];
}

export interface DrainLease {
  ownerId: string;
  pid: number;
  /** Host the owner runs on: a takeover may only judge liveness on that host. */
  host: string;
  acquiredAt: string;
  heartbeatAt: string;
  leaseMs: number;
}

export interface DrainClaimFile {
  key: string;
  entry: BufferEntryState;
  claimedAt: string;
  /**
   * Turns the drain already extracted. Non-empty means the session was
   * drained and the claim is a TOMBSTONE: a live buffer owner subtracts
   * these from its (possibly stale) copy instead of writing them back, so
   * drained turns can never be resurrected.
   */
  drained?: BufferTurn[];
  /** Same tombstone for turns the drain extracted from `retainedTurns`. */
  drainedRetained?: BufferTurn[];
}

export type ClaimFromSessionOutcome = "claimed" | "empty" | "already_claimed";
export type AdoptOutcome = "adopted" | "busy";
export type AckOutcome = "acked" | "not_empty" | "busy";

export interface DrainClaimListing {
  key: string;
  turnCount: number;
  leased: boolean;
  leaseExpired: boolean;
}

/** Lock while a claim is read-modify-written; released on settle. */
const CLAIM_LOCK_STALE_MS = 120_000;
const CLAIM_LOCK_MAX_WAIT_MS = 120_000;

function emptyEntry(): BufferEntryState {
  return { turns: [], lastExtractionAt: null, extractionCount: 0 };
}

/** Identity-dedupe `incoming` turns into `existing` (they are the same turns a
 * live owner still held after claiming; only genuinely NEW turns append). */
function mergeTurns<T>(existing: T[], incoming: readonly T[], isEqual: (a: T, b: T) => boolean): T[] {
  const merged = [...existing];
  for (const turn of incoming) {
    if (merged.some((kept) => isEqual(kept, turn))) continue;
    merged.push(turn);
  }
  return merged;
}

function mergeEntries(claim: DrainClaimFile, incoming: BufferEntryState): DrainClaimFile {
  const entry = emptyEntry();
  // Turns already extracted stay out of the pending entry even when the
  // owner's incoming copy is stale and still carries them (either tombstone
  // list counts — a turn in either one left the claim for good).
  const gone = [...(claim.drained ?? []), ...(claim.drainedRetained ?? [])];
  entry.turns = mergeTurns(
    subtractBufferTurns(claim.entry.turns, gone),
    subtractBufferTurns(incoming.turns, gone),
    bufferTurnsEqual,
  );
  const retained = [
    ...subtractBufferTurns(claim.entry.retainedTurns ?? [], gone),
    ...subtractBufferTurns(incoming.retainedTurns ?? [], gone),
  ];
  // SAFETY: an empty accumulator of the same element type.
  const dedupedRetained = mergeTurns([] as typeof retained, retained, bufferTurnsEqual);
  if (dedupedRetained.length > 0) entry.retainedTurns = dedupedRetained;
  const stamps = [claim.entry.lastExtractionAt, incoming.lastExtractionAt].filter(
    (value): value is string => value !== null && value !== undefined,
  );
  entry.lastExtractionAt = stamps.sort().at(-1) ?? null;
  entry.extractionCount = Math.max(claim.entry.extractionCount, incoming.extractionCount);
  return { ...claim, entry };
}

/**
 * Is the lease owner still running? Only decidable on the owner's host; a
 * lease from another host counts as alive (its expiry decides).
 */
function isOwnerAlive(lease: DrainLease): boolean {
  if (lease.host !== hostname()) return true;
  if (!Number.isInteger(lease.pid) || lease.pid <= 0) return true;
  try {
    process.kill(lease.pid, 0);
    return true;
  } catch (err) {
    // EPERM: the process exists but belongs to another user.
    // SAFETY: the value comes from this module's own write path; the shape is checked above.
    return (err as NodeJS.ErrnoException)?.code === "EPERM";
  }
}

function isLeaseExpired(lease: DrainLease, now = Date.now()): boolean {
  const heartbeat = Date.parse(lease.heartbeatAt);
  return !Number.isFinite(heartbeat) || now - heartbeat > lease.leaseMs;
}

const claimBodySchema = z.object({
  key: z.string().min(1),
  entry: z.object({
    turns: z.array(z.unknown()),
    retainedTurns: z.array(z.unknown()).optional(),
    lastExtractionAt: z.string().nullable().optional(),
    extractionCount: z.number().optional(),
  }).optional(),
  turns: z.array(z.unknown()).optional(),
  retainedTurns: z.array(z.unknown()).optional(),
  lastExtractionAt: z.string().nullable().optional(),
  extractionCount: z.number().optional(),
  claimedAt: z.string().optional(),
  drained: z.array(z.unknown()).optional(),
  drainedRetained: z.array(z.unknown()).optional(),
});

function parseBody(raw: string): DrainClaimFile | null {
  let body: z.infer<typeof claimBodySchema>;
  try {
    body = claimBodySchema.parse(JSON.parse(raw));
  } catch {
    return null;
  }
  // Two on-disk shapes, one format: a claim born from rename keeps the flat
  // session-file shape ({key, turns, ...}) until its first rewrite, which
  // nests under `entry`. Accept both.
  const source = body.entry && Array.isArray(body.entry.turns) ? body.entry : body;
  if (!Array.isArray(source.turns)) return null;
  const entry = emptyEntry();
  // SAFETY: the schema parsed these as an array of unknown; the claim file
  // is written only by this module (BufferSessionFiles.save), so the entries
  // are BufferTurn values.
  // SAFETY: the claim file is written only by this module, so the parsed
  // turn arrays hold BufferTurn values.
  // SAFETY: the value comes from this module's own write path; the shape is checked above.
  entry.turns = source.turns as BufferTurn[];
  if (source.retainedTurns) {
    // SAFETY: same boundary as the turns above (this module writes the file).
    entry.retainedTurns = source.retainedTurns as BufferTurn[];
  }
  entry.lastExtractionAt = source.lastExtractionAt ?? null;
  entry.extractionCount = Number.isFinite(source.extractionCount) ? Number(source.extractionCount) : 0;
  const claim: DrainClaimFile = {
    key: body.key,
    entry,
    claimedAt: body.claimedAt ?? new Date().toISOString(),
  };
  if (Array.isArray(body.drained)) {
    // SAFETY: same boundary as the turns above (this module writes the file).
    claim.drained = body.drained as BufferTurn[];
  }
  if (Array.isArray(body.drainedRetained)) {
    // SAFETY: same boundary as the turns above (this module writes the file).
    claim.drainedRetained = body.drainedRetained as BufferTurn[];
  }
  return claim;
}

const leaseSchema = z.object({
  ownerId: z.string().min(1),
  pid: z.number().optional(),
  host: z.string().optional(),
  acquiredAt: z.string().optional(),
  heartbeatAt: z.string(),
  leaseMs: z.number(),
});

function parseLease(raw: string): DrainLease | null {
  let lease: z.infer<typeof leaseSchema>;
  try {
    lease = leaseSchema.parse(JSON.parse(raw));
  } catch {
    return null;
  }
  return {
    ownerId: lease.ownerId,
    pid: lease.pid ?? 0,
    host: lease.host ?? "",
    acquiredAt: lease.acquiredAt ?? lease.heartbeatAt,
    heartbeatAt: lease.heartbeatAt,
    leaseMs: lease.leaseMs,
  };
}

export class BufferDrainClaims {
  constructor(
    private readonly stateDir: string,
    private readonly io: BufferFileIo,
  ) {}

  private get dir(): string {
    return path.join(this.stateDir, "buffer", "drain");
  }

  private fileFor(key: string): string {
    return path.join(this.dir, bufferSessionFileName(key));
  }

  private leaseFileFor(key: string): string {
    return `${this.fileFor(key)}.lease.json`;
  }

  private lockFileFor(key: string): string {
    return `${this.fileFor(key)}.lock`;
  }

  /** Sync existence check for hot-path gates (`SmartBuffer.isSessionClaimed`). */
  isClaimed(key: string): boolean {
    return existsSync(this.fileFor(key));
  }

  /** Test + CLI seam: the lease file path for direct inspection. */
  leasePathForTest(key: string): string {
    return this.leaseFileFor(key);
  }

  private async readClaimBody(key: string): Promise<DrainClaimFile | null> {
    try {
      return parseBody(await this.io.read(this.fileFor(key)));
    } catch {
      return null;
    }
  }

  /** The claim content for `key`, or null when the key is not claimed. */
  load(key: string): Promise<DrainClaimFile | null> {
    return this.readClaimBody(key);
  }

  private async writeClaimBody(key: string, claim: DrainClaimFile): Promise<void> {
    await mkdir(this.dir, { recursive: true });
    await this.io.write(this.fileFor(key), JSON.stringify({ ...claim, key }));
  }

  private async readLease(key: string): Promise<DrainLease | null> {
    try {
      return parseLease(await this.io.read(this.leaseFileFor(key)));
    } catch {
      return null;
    }
  }

  private async writeLease(key: string, lease: DrainLease): Promise<void> {
    await mkdir(this.dir, { recursive: true });
    await this.io.write(this.leaseFileFor(key), JSON.stringify(lease));
  }

  /**
   * Atomically move a session's persisted file into a claim. The rename is
   * the handover: after it settles the turns exist ONLY as a claim, so no
   * crash window can lose them or leave them in both places. Callers that
   * lose the race (`already_claimed`) simply skip the key.
   *
   * The whole handover runs under the claim's mutation lock, so a claim
   * create can never land on top of an existing claim (POSIX rename would
   * silently replace it) and the lease write cannot race an adopter.
   */
  async claimFromSessionFile(key: string, lease: DrainLease): Promise<ClaimFromSessionOutcome> {
    await mkdir(this.dir, { recursive: true });
    const sessionPath = path.join(this.stateDir, "buffer", bufferSessionFileName(key));
    if (existsSync(sessionPath)) {
      // Advisory pre-read: an empty live session belongs to its owner, not
      // the drain. A turn landing between this read and the rename is fine —
      // the rename moves whatever is there and the claim drains it.
      try {
        const seeded = parseBody(await this.io.read(sessionPath));
        if (seeded && seeded.entry.turns.length === 0 && (seeded.entry.retainedTurns?.length ?? 0) === 0) {
          return "empty";
        }
      } catch {
        // Unreadable live file: proceed with the rename and let the claim
        // path report it loudly, like the loader skips corrupt files.
      }
    }
    return await withHeldFileLock(
      this.lockFileFor(key),
      { staleMs: CLAIM_LOCK_STALE_MS, maxWaitMs: CLAIM_LOCK_MAX_WAIT_MS },
      async (acquired) => {
        if (!acquired) return "already_claimed";
        // Under the lock the claim check is authoritative: an existing claim
        // keeps its content and its lease; the session file stays with its
        // owner (their next save merges into the claim).
        if (this.isClaimed(key)) return "already_claimed";
        try {
          await rename(sessionPath, this.fileFor(key));
        } catch (err) {
          // The session file is gone: either it never existed, or another
          // drainer claimed it first.
          if (!existsSync(sessionPath)) {
            if (this.isClaimed(key)) return "already_claimed";
            return "empty";
          }
          throw err;
        }
        const claim = await this.readClaimBody(key);
        if (!claim || (claim.entry.turns.length === 0 && (claim.entry.retainedTurns?.length ?? 0) === 0)) {
          // Empty content: nothing to drain. Delete the moved file so the
          // empty entry keeps living with its owner, not as a stale claim.
          await unlink(this.fileFor(key)).catch(() => {});
          return "empty";
        }
        await this.writeLease(key, lease);
        return "claimed";
      },
    );
  }

  /**
   * Take over a claim whose lease is missing, expired, or whose owner died.
   * The whole judgement runs under the claim's mutation lock and re-reads
   * the lease inside it, so exactly one concurrent adopter wins: the loser
   * re-reads the winner's fresh lease and reports "busy" instead of
   * unlinking it. A lease whose owner died is taken over in the same call.
   */
  async adopt(key: string, lease: DrainLease): Promise<AdoptOutcome> {
    if (!this.isClaimed(key)) return "busy";
    return await withHeldFileLock(
      this.lockFileFor(key),
      { staleMs: CLAIM_LOCK_STALE_MS, maxWaitMs: CLAIM_LOCK_MAX_WAIT_MS },
      async (acquired) => {
        if (!acquired) return "busy";
        const existing = await this.readLease(key);
        if (existing && !isLeaseExpired(existing)) {
          if (existing.ownerId === lease.ownerId) {
            // The same drainer already holds it: renew the lease.
            await this.writeLease(key, { ...existing, heartbeatAt: new Date().toISOString(), leaseMs: lease.leaseMs });
            return "adopted";
          }
          if (isOwnerAlive(existing)) return "busy";
          // The owner died without releasing the claim (killed worker):
          // take it over now instead of waiting for the lease to expire.
          await unlink(this.leaseFileFor(key)).catch(() => {});
        } else if (existing) {
          // Expired lease: clear it before the exclusive create. We hold the
          // lock, so no concurrent adopter can interleave its own
          // unlink/create between these steps.
          await unlink(this.leaseFileFor(key)).catch(() => {});
        }
        try {
          await writeFile(this.leaseFileFor(key), JSON.stringify(lease), { flag: "wx" });
        } catch (err) {
          // The lease file exists: another drainer took it first.
          if (existsSync(this.leaseFileFor(key))) return "busy";
          throw err;
        }
        return "adopted";
      },
    );
  }

  /**
   * Merge a live owner's in-memory entry INTO the claim (the handover path a
   * buffer owner takes instead of persisting a claimed session). Serialized
   * against drainer progress writes on the same lock.
   */
  async mergeIntoClaim(key: string, incoming: BufferEntryState): Promise<void> {
    await withHeldFileLock(this.lockFileFor(key), { staleMs: CLAIM_LOCK_STALE_MS, maxWaitMs: CLAIM_LOCK_MAX_WAIT_MS }, async (acquired) => {
      if (!acquired) {
        // Never fall back to a session-file write behind a held claim lock:
        // that would resurrect claimed turns. Fail so the owner's save stays
        // pending and retries (SmartBuffer keeps pending state on failure).
        throw new Error(`buffer drain claim for ${key} is busy; retrying the save later`);
      }
      const claim = await this.readClaimBody(key);
      if (!claim) {
        // The claim vanished (acked between the isClaimed check and now):
        // nothing to hand over; the drain already owns everything.
        return;
      }
      await this.writeClaimBody(key, mergeEntries(claim, incoming));
    });
  }

  /** Drainer progress: replace the claim content with what is left to do.
   *
   * Fenced: `ownerId` must still match the claim's lease (checked under the
   * same lock), so a drainer that lost its lease cannot write progress that
   * would restore turns the new owner already extracted.
   *
   * `seen` is the entry the drainer LOADED (its snapshot of the claim). Only
   * turns that were in that snapshot and are absent from BOTH of the
   * drainer's lists were actually extracted and move to the tombstones — a
   * turn the drainer moved into `entry.retainedTurns` is retained for retry,
   * not extracted. Turns a live owner merged into the claim afterwards stay
   * pending. Without `seen` the pre-existing behavior is kept (every claim
   * turn missing from `entry` counts as extracted).
   */
  async writeEntry(key: string, ownerId: string, entry: BufferEntryState, seen?: BufferEntryState): Promise<void> {
    await withHeldFileLock(this.lockFileFor(key), { staleMs: CLAIM_LOCK_STALE_MS, maxWaitMs: CLAIM_LOCK_MAX_WAIT_MS }, async (acquired) => {
      if (!acquired) throw new Error(`buffer drain claim for ${key} is busy; progress write skipped`);
      const lease = await this.readLease(key);
      if (!lease || lease.ownerId !== ownerId) {
        throw new Error(`buffer drain claim for ${key} is no longer owned by ${ownerId}; progress write skipped`);
      }
      const claim = await this.readClaimBody(key);
      if (!claim) return;
      const seenTurns = seen?.turns ?? claim.entry.turns;
      const seenRetained = seen?.retainedTurns ?? claim.entry.retainedTurns ?? [];
      const entryRetained = entry.retainedTurns ?? [];
      // Still held by the drainer: in its remaining turns OR retained for retry.
      const kept = (turn: BufferTurn): boolean =>
        entry.turns.some((held) => bufferTurnsEqual(held, turn)) || entryRetained.some((held) => bufferTurnsEqual(held, turn));
      // Progress: the snapshot turns that vanished from the entry were extracted.
      const drained = [...(claim.drained ?? [])];
      for (const turn of claim.entry.turns) {
        const extracted =
          seenTurns.some((snapshot) => bufferTurnsEqual(snapshot, turn)) && !kept(turn);
        if (!extracted) continue;
        if (drained.some((gone) => bufferTurnsEqual(gone, turn))) continue;
        drained.push(turn);
      }
      const drainedRetained = [...(claim.drainedRetained ?? [])];
      for (const turn of claim.entry.retainedTurns ?? []) {
        const extracted =
          seenRetained.some((snapshot) => bufferTurnsEqual(snapshot, turn)) && !kept(turn);
        if (!extracted) continue;
        if (drained.some((gone) => bufferTurnsEqual(gone, turn)) || drainedRetained.some((gone) => bufferTurnsEqual(gone, turn))) continue;
        drainedRetained.push(turn);
      }
      // Turns merged in after the drainer loaded stay pending, in extraction
      // order behind the drainer's own remainder.
      const late = claim.entry.turns.filter(
        (turn) =>
          !seenTurns.some((snapshot) => bufferTurnsEqual(snapshot, turn)) && !kept(turn),
      );
      const next: BufferEntryState = { ...entry, turns: [...entry.turns, ...late] };
      const lateRetained = (claim.entry.retainedTurns ?? []).filter(
        (turn) =>
          !seenRetained.some((snapshot) => bufferTurnsEqual(snapshot, turn)) && !kept(turn),
      );
      if (lateRetained.length > 0) next.retainedTurns = mergeTurns(entryRetained, lateRetained, bufferTurnsEqual);
      await this.writeClaimBody(key, { ...claim, entry: next, drained, drainedRetained });
    });
  }

  /** Extend the lease. "lost" means another drainer took the claim over.
   * Serialized on the claim lock so a stale heartbeat can never overwrite a
   * new owner's lease mid-takeover; a contended lock just skips this tick
   * (usually the drainer's own progress write holds it). */
  async heartbeat(key: string, ownerId: string, leaseMs: number): Promise<"ok" | "lost"> {
    return await withHeldFileLock(this.lockFileFor(key), { staleMs: CLAIM_LOCK_STALE_MS, maxWaitMs: CLAIM_LOCK_MAX_WAIT_MS }, async (acquired) => {
      if (!acquired) return "ok";
      const lease = await this.readLease(key);
      if (!lease || lease.ownerId !== ownerId) return "lost";
      await this.writeLease(key, { ...lease, heartbeatAt: new Date().toISOString(), leaseMs });
      return "ok";
    });
  }

  /** Give the key back (content stays; the next run resumes it). */
  async releaseLease(key: string, ownerId: string): Promise<void> {
    const lease = await this.readLease(key);
    if (!lease || lease.ownerId !== ownerId) return;
    await unlink(this.leaseFileFor(key)).catch(() => {});
  }

  /**
   * Finish a claim: only its owner may ack, and only when nothing is left to
   * extract. Non-empty claims stay (deferred content is never dropped here).
   */
  async ack(key: string, ownerId: string): Promise<AckOutcome> {
    const lease = await this.readLease(key);
    if (!lease || lease.ownerId !== ownerId) return "busy";
    const claim = await this.readClaimBody(key);
    if (!claim) {
      await unlink(this.leaseFileFor(key)).catch(() => {});
      return "acked";
    }
    if (claim.entry.turns.length > 0 || (claim.entry.retainedTurns?.length ?? 0) > 0) return "not_empty";
    // Keep the (empty) claim file as a TOMBSTONE: a live buffer owner that
    // still holds a stale copy subtracts the drained turns instead of
    // writing them back. The owner consumes the tombstone on its next save.
    await unlink(this.leaseFileFor(key)).catch(() => {});
    return "acked";
  }

  /** The turns a drain already extracted for `key` (tombstone content). */
  async drainedTurns(key: string): Promise<BufferTurn[]> {
    const claim = await this.readClaimBody(key);
    return claim?.drained ?? [];
  }

  /**
   * Is the drain for `key` FINISHED (acked): the claim holds extracted turns
   * and nothing pending, and the drainer dropped its lease. A claim with
   * partial progress or a live lease is still being drained — its owner must
   * merge into it, never release it.
   */
  async isDrained(key: string): Promise<boolean> {
    const claim = await this.readClaimBody(key);
    if (!claim) return false;
    if ((claim.drained?.length ?? 0) === 0 && (claim.drainedRetained?.length ?? 0) === 0) return false;
    if (claim.entry.turns.length > 0 || (claim.entry.retainedTurns?.length ?? 0) > 0) return false;
    return (await this.readLease(key)) === null;
  }

  /** Drop the claim file entirely (its owner consumed the tombstone). */
  async release(key: string): Promise<void> {
    await unlink(this.fileFor(key)).catch(() => {});
    await unlink(this.leaseFileFor(key)).catch(() => {});
  }

  /** Every claim with its lease state (CLI scan + summaries). */
  async list(): Promise<DrainClaimListing[]> {
    let names: string[];
    try {
      names = (await readdir(this.dir)).filter((name) => name.endsWith(".json") && !name.endsWith(".lease.json"));
    } catch (err) {
      // SAFETY: the value comes from this module's own write path; the shape is checked above.
      if ((err as NodeJS.ErrnoException)?.code === "ENOENT") return [];
      throw err;
    }
    const out: DrainClaimListing[] = [];
    for (const name of names) {
      const claim = await this.readClaimBodyByKey(name);
      if (!claim) continue;
      const lease = await this.readLease(claim.key);
      out.push({
        key: claim.key,
        turnCount: claim.entry.turns.length + (claim.entry.retainedTurns?.length ?? 0),
        leased: lease !== null,
        leaseExpired: lease !== null ? isLeaseExpired(lease) : true,
      });
    }
    return out;
  }

  /**
   * Paged listing for bounded periodic scans: at most `limit` claims with
   * pending turns, starting AFTER `afterName` (a raw entry name returned as
   * `nextCursor` by a previous page — file-name order is stable, so a
   * rotating cursor visits every claim fairly without ever materializing
   * the whole directory's bodies). Names only skip; bodies are read lazily
   * per entry and only for the page.
   */
  async listPage(afterName: string | undefined, limit: number): Promise<{ entries: DrainClaimListing[]; nextCursor?: string }> {
    let names: string[];
    try {
      names = (await readdir(this.dir)).filter((name) => name.endsWith(".json") && !name.endsWith(".lease.json")).sort();
    } catch (err) {
      if ((err as NodeJS.ErrnoException)?.code === "ENOENT") return { entries: [] };
      throw err;
    }
    const start = afterName === undefined ? 0 : names.findIndex((name) => name > afterName);
    const out: DrainClaimListing[] = [];
    // The cursor is the LAST CONSUMED entry name: the next page starts
    // strictly after it, so the first unconsumed name is never skipped.
    // Returning the first unconsumed name instead would make every page
    // boundary permanently skip one claim.
    let cursor: string | undefined;
    for (let index = start < 0 ? names.length : start; index < names.length; index += 1) {
      const name = names[index]!;
      if (out.length >= limit) break;
      const claim = await this.readClaimBodyByKey(name);
      if (!claim) continue;
      const lease = await this.readLease(claim.key);
      out.push({
        key: claim.key,
        turnCount: claim.entry.turns.length + (claim.entry.retainedTurns?.length ?? 0),
        leased: lease !== null,
        leaseExpired: lease !== null ? isLeaseExpired(lease) : true,
      });
      cursor = name;
    }
    return { entries: out, nextCursor: cursor };
  }

  private async readClaimBodyByKey(name: string): Promise<DrainClaimFile | null> {
    try {
      return parseBody(await this.io.read(path.join(this.dir, name)));
    } catch (err) {
      log.debug(`buffer drain: skipping unreadable claim file ${name}: ${err instanceof Error ? err.message : String(err)}`);
      return null;
    }
  }
}

import { readdir } from "node:fs/promises";
import type { Dirent } from "node:fs";
import path from "node:path";

import { stripAttributesSuffix } from "../structured-attributes.js";
import type { MemoryFile } from "../types.js";
import { isErrnoCode } from "../utils/errno.js";
import { isMacOsReplicationJunkBasename } from "../utils/macos-replication-junk.js";

export interface SupersessionAuditLookup {
  correctionsDir: string;
  readMemoryByPath(filePath: string): Promise<MemoryFile | null>;
}

export async function hasSupersessionAudit(
  lookup: SupersessionAuditLookup,
  oldMemoryId: string,
  newMemoryId: string,
  auditBody: string,
  structuredAttributes?: Record<string, string>
): Promise<boolean> {
  let entries: Dirent[];
  try {
    entries = await readdir(lookup.correctionsDir, { withFileTypes: true });
  } catch (error) {
    if (isErrnoCode(error, "ENOENT")) return false;
    throw error;
  }

  for (const entry of entries) {
    if (isMacOsReplicationJunkBasename(entry.name)) continue;
    if (!entry.isFile() || !entry.name.endsWith(".md")) continue;
    const memory = await lookup.readMemoryByPath(path.join(lookup.correctionsDir, entry.name));
    if (
      memory?.frontmatter.category === "correction" &&
      (memory.frontmatter.sourceMemoryId === oldMemoryId ||
        (memory.frontmatter.sourceMemoryId === undefined && memory.frontmatter.lineage?.includes(oldMemoryId))) &&
      memory.frontmatter.lineage?.includes(newMemoryId) &&
      stripAttributesSuffix(memory.content) === auditBody &&
      (structuredAttributes === undefined ||
        Object.entries(structuredAttributes).every(
          ([key, value]) => memory.frontmatter.structuredAttributes?.[key] === value
        ))
    ) {
      return true;
    }
  }
  return false;
}

