const OFFLINE_SYNC_BUFFER_LIMIT_BYTES = 1_048_576;
const OFFLINE_SYNC_STAGE_READ_BYTES = 64 * 1024;
const OFFLINE_SYNC_FRONTMATTER_DELIMITER = Buffer.from("\n---\n", "utf8");

const CASED_CHARACTER = /\p{Cased}/u;
const CASE_IGNORABLE_CHARACTER = /\p{Case_Ignorable}/u;

type StreamedOfflineSyncIdentity = {
  identityHash: string;
};

type PreparedOfflineSyncChunks = {
  after: MemoryFile | null;
  chunks: AsyncIterable<Buffer>;
  stagePath?: string;
  streamedIdentity?: StreamedOfflineSyncIdentity;
};

type ExplicitContentNormalizerSink = {
  write: (chunk: string) => void;
  beginConditionalSigma: () => void;
  resolveConditionalSigma: (useFinalSigma: boolean) => void;
};

function createExplicitContentNormalizer(sink: ExplicitContentNormalizerSink): {
  push: (text: string) => void;
  finish: () => void;
} {
  let started = false;
  let pendingSpace = false;
  let output = "";
  let precededByCased = false;
  let pendingSigma = false;
  const flush = () => {
    if (output.length > 0) {
      sink.write(output);
      output = "";
    }
  };
  const emit = (text: string) => {
    for (const character of text) {
      if (/\s/u.test(character)) {
        if (started) pendingSpace = true;
        continue;
      }
      if (pendingSpace) {
        output += " ";
        pendingSpace = false;
      }
      output += character;
      started = true;
      if (output.length >= OFFLINE_SYNC_STAGE_READ_BYTES) flush();
    }
  };
  const resolveSigma = (followedByCased: boolean) => {
    flush();
    sink.resolveConditionalSigma(!followedByCased);
    pendingSigma = false;
  };
  const push = (text: string) => {
    for (const character of text) {
      const caseIgnorable = CASE_IGNORABLE_CHARACTER.test(character);
      const cased = CASED_CHARACTER.test(character);
      if (pendingSigma) {
        if (caseIgnorable) {
          emit(character.toLowerCase());
          continue;
        }
        resolveSigma(cased);
      }
      if (character === "Σ" && precededByCased) {
        flush();
        sink.beginConditionalSigma();
        pendingSigma = true;
        precededByCased = true;
        continue;
      }
      emit(character.toLowerCase());
      if (!caseIgnorable) precededByCased = cased;
    }
  };
  return {
    push,
    finish() {
      if (pendingSigma) resolveSigma(false);
      flush();
    },
  };
}

async function forEachStagedTextChunk(
  stagePath: string,
  offset: number,
  onText: (text: string) => void,
  key: Buffer | null,
  memoryDir: string
): Promise<void> {
  const decoder = new TextDecoder("utf-8");
  let remaining = offset;
  for await (const chunk of readMaybeEncryptedFileFromChunks(stagePath, key, memoryDir)) {
    const textChunk = remaining >= chunk.length ? null : chunk.subarray(remaining);
    remaining = Math.max(0, remaining - chunk.length);
    if (textChunk === null || textChunk.length === 0) continue;
    const text = decoder.decode(textChunk, { stream: true });
    if (text.length > 0) onText(text);
  }
  const finalText = decoder.decode();
  if (finalText.length > 0) onText(finalText);
}

async function findStagedBodyOffset(stagePath: string, key: Buffer | null, memoryDir: string): Promise<number | null> {
  let scannedBytes = 0;
  let tail = Buffer.alloc(0);
  for await (const chunk of readMaybeEncryptedFileFromChunks(stagePath, key, memoryDir)) {
    const window = tail.length > 0 ? Buffer.concat([tail, chunk]) : chunk;
    const windowStart = scannedBytes - tail.length;
    for (let searchFrom = 0; ; ) {
      const delimiterStart = window.indexOf(OFFLINE_SYNC_FRONTMATTER_DELIMITER, searchFrom);
      if (delimiterStart < 0) break;
      if (windowStart + delimiterStart >= 4) {
        return windowStart + delimiterStart + OFFLINE_SYNC_FRONTMATTER_DELIMITER.length;
      }
      searchFrom = delimiterStart + 1;
    }
    scannedBytes += chunk.length;
    const tailLength = Math.min(OFFLINE_SYNC_FRONTMATTER_DELIMITER.length - 1, window.length);
    tail = Buffer.from(window.subarray(window.length - tailLength));
  }
  return null;
}

async function readStagedPrefix(
  stagePath: string,
  byteLimit: number,
  key: Buffer | null,
  memoryDir: string
): Promise<Buffer> {
  const chunks: Buffer[] = [];
  let bytesRead = 0;
  for await (const chunk of readMaybeEncryptedFileFromChunks(stagePath, key, memoryDir)) {
    const length = Math.min(chunk.length, byteLimit - bytesRead);
    if (length > 0) chunks.push(chunk.subarray(0, length));
    bytesRead += length;
    if (bytesRead >= byteLimit) break;
  }
  return Buffer.concat(chunks, bytesRead);
}

export type OfflineSyncMemoryParser = (filePath: string, content: Buffer) => MemoryFile | null;

export function parseTombstoneBlockedOfflineSyncMemory(
  filePath: string,
  content: Buffer,
  memoryDir: string,
  parseFrontmatter: (raw: string) => { frontmatter: MemoryFrontmatter; content: string } | null,
  normalizeFrontmatterForPath: (frontmatter: MemoryFrontmatter, pathRel: string, content?: string) => MemoryFrontmatter,
  toMemoryPathRel: (baseDir: string, filePath: string) => string
): MemoryFile | null {
  const parsed = parseFrontmatter(content.toString("utf8"));
  if (!parsed) return null;
  return {
    path: filePath,
    frontmatter: normalizeFrontmatterForPath(parsed.frontmatter, toMemoryPathRel(memoryDir, filePath), parsed.content),
    content: parsed.content,
  };
}

export abstract class TombstoneBlockedCaptureIndexHost {
  private tombstoneBlockedCaptureIndex: TombstoneBlockedCaptureIndex | null = null;
  protected abstract tombstoneBlockedCaptureIndexOptions(): TombstoneBlockedCaptureIndexOptions;
  protected abstract writeStorageSecureFile(
    filePath: string,
    content: string | Buffer,
    forceEncrypt?: boolean
  ): Promise<void>;
  protected abstract assertManagedStoragePath(filePath: string, method: string): string;
  protected abstract notifyCatalogWriteForPath(filePath: string): void;
  protected abstract readMemoryByPath(filePath: string): Promise<MemoryFile | null>;
  protected abstract invalidateAllMemoriesCache(): void;
  protected abstract invalidateKnowledgeIndexCache(): void;
  protected abstract invalidateColdMemoriesCache(): void;
  protected abstract bumpArtifactWriteVersion(): number;
  protected abstract bumpMemoryStatusVersion(): void;
  protected abstract bumpMemoryCorpusVersion(): void;
  protected abstract markFactHashIndexNotAuthoritative(): void;
  /** #2837: durable unlink plus deletion-revision record, WITHOUT the CAS
   * shard sweep — the concrete {@link deleteManagedStorageFile} composes the
   * two so every deletion funnel (invalidation, maintenance purge, archive
   * move, offline sync) sweeps. */
  protected abstract deleteManagedStorageFileDurable(filePath: string, deletionMtimeMs?: number | null): Promise<boolean>;
  protected abstract writeManagedStorageFile(filePath: string, write: () => Promise<void>): Promise<void>;

  /** #2813 (P1 C, #2807): reserve the target's next durable CAS revision
   * token as a two-phase receipt transaction — a PENDING write-ahead
   * marker under the mutation's path lock, published COMMITTED only after
   * the durable file write lands. Receipt identity lives in the per-target
   * sidecar, never in public `frontmatter.updated`. The default host keeps
   * no receipt identity; StorageManager records it. */
  protected async beginDurableMemoryRevision(_pathname: string, _expectedContent?: string | Buffer | null): Promise<CasRevisionTransaction | undefined> {
    return undefined;
  }

  /** #2837 (shard cleanup): after a managed memory file is durably deleted,
   * sweep its per-target CAS receipt shard so orphan shards cannot grow
   * forever. The sweep runs under the shard's own lock and is best-effort —
   * the memory file is already gone, so a sweep failure logs and never
   * fails the delete. The sweeper is a second CasRevisionHost over the same
   * memory dir; the host is stateless and every mutation serializes through
   * the sidecar's file locks, so it shares the same shard files
   * StorageManager's own host operates on. */
  private deletedMemoryShardSweeper: CasRevisionHost | null = null;

  protected async deleteManagedStorageFile(filePath: string, deletionMtimeMs?: number | null): Promise<boolean> {
    const deleted = await this.deleteManagedStorageFileDurable(filePath, deletionMtimeMs);
    if (!deleted) return false;
    if (this.deletedMemoryShardSweeper === null) {
      this.deletedMemoryShardSweeper = new CasRevisionHost(this.tombstoneBlockedCaptureIndexOptions().memoryDir);
    }
    await this.deletedMemoryShardSweeper.sweepShardAfterDeletion(filePath);
    return true;
  }

  private async writeStorageSecureFileChunks(filePath: string, chunks: AsyncIterable<Buffer>): Promise<void> {
    const options = this.tombstoneBlockedCaptureIndexOptions();
    await writeMaybeEncryptedFileFromChunks(
      filePath,
      chunks,
      options.secureStoreWriteKeyProvider(),
      {},
      options.memoryDir
    );
    this.notifyCatalogWriteForPath(filePath);
  }

  protected getTombstoneBlockedCaptureIndex(): TombstoneBlockedCaptureIndex {
    if (this.tombstoneBlockedCaptureIndex === null) {
      this.tombstoneBlockedCaptureIndex = new TombstoneBlockedCaptureIndex(this.tombstoneBlockedCaptureIndexOptions());
    }
    return this.tombstoneBlockedCaptureIndex;
  }
  async withTombstoneBlockedCaptureWriteLock<T>(
    task: () => Promise<T>,
    identity?: string | readonly string[]
  ): Promise<T> {
    return await this.getTombstoneBlockedCaptureIndex().withCaptureWriteLock(task, identity);
  }

  /** Read selected memories while their mutation locks remain held. */
  async readMemorySnapshotsIfUnchanged(expected: readonly MemoryFile[]): Promise<MemoryFile[] | null> {
    return await this.withMemorySnapshotsIfUnchanged(expected, async (memories) => memories);
  }

  async withMemorySnapshotsIfUnchanged<T>(
    expected: readonly MemoryFile[],
    task: (memories: MemoryFile[]) => Promise<T>
  ): Promise<T | null> {
    if (expected.length === 0) return await task([]);
    const pathnames = [...new Set(expected.map((memory) => memory.path))];
    if (pathnames.length !== expected.length) return null;
    return await this.withTombstoneBlockedCaptureWriteLock(async () => {
      const current = await Promise.all(pathnames.map((pathname) => this.readMemoryByPath(pathname)));
      for (let index = 0; index < expected.length; index += 1) {
        const actual = current[index];
        const snapshot = expected[index];
        if (
          !actual ||
          !snapshot ||
          actual.frontmatter.id !== snapshot.frontmatter.id ||
          invalidationCommitFingerprint(actual) !== invalidationCommitFingerprint(snapshot)
        ) {
          return null;
        }
      }
      return await task(current as MemoryFile[]);
    }, pathnames.map(buildCapturePathLockIdentity));
  }

  protected async withTombstoneBlockedCaptureWriteLockAndHashes<T>(
    task: () => Promise<T>,
    identity: string | readonly string[] | undefined,
    identityHashes: readonly string[]
  ): Promise<T> {
    return await this.getTombstoneBlockedCaptureIndex().withCaptureWriteLockAndHashes(task, identity, identityHashes);
  }

  private async writeTombstoneBlockedMutation(
    blocked: boolean,
    pathname: string,
    fileContent: string,
    identity: string | readonly string[],
    updateIndex: (rebuildMarker?: string, current?: MemoryFile | null) => Promise<void>,
    beforeIndexUpdate?: () => Promise<void>,
    coordinate = false,
    shouldMintRevision?: (current: MemoryFile | null) => boolean
  ): Promise<string | undefined> {
    const host: TombstoneBlockedMutationHost = {
      readCurrent: () => this.readMemoryByPath(pathname),
      isBlocked: (memory) => this.isTombstoneBlockedMemory(memory),
      isQueuedReview: (memory) => isQueuedReviewMemory(memory),
      memoryIdentity: (memory) => this.offlineSyncMemoryIdentity(memory),
      prepareWrite: () => this.getTombstoneBlockedCaptureIndex().prepareWrite(),
      commitWrite: (marker) => this.getTombstoneBlockedCaptureIndex().commitWrite(marker),
      discardWrite: (marker) => this.getTombstoneBlockedCaptureIndex().discardWrite(marker),
      markUntrusted: () => this.getTombstoneBlockedCaptureIndex().markUntrusted(),
      writeStorageSecureFile: (target, content) => this.writeStorageSecureFile(target, content),
      withCaptureWriteLock: (task, lockIdentity) => this.withTombstoneBlockedCaptureWriteLock(task, lockIdentity),
      logWarning: (message) => log.warn(message),
      beginDurableMemoryRevision: (targetPath, expectedContent) =>
        this.beginDurableMemoryRevision(targetPath, expectedContent),
    };
    return await runTombstoneBlockedMutation(host, {
      blocked,
      pathname,
      fileContent,
      identity,
      updateIndex,
      beforeIndexUpdate,
      coordinate,
      shouldMintRevision,
    });
  }

  protected async writeTombstoneBlockedMemory(
    pathname: string,
    fileContent: string,
    frontmatter: MemoryFrontmatter,
    content: string,
    beforeIndexUpdate?: () => Promise<void>
  ): Promise<void> {
    await this.writeTombstoneBlockedMutation(
      tombstoneBlocked(frontmatter),
      pathname,
      fileContent,
      [
        buildCapturePathLockIdentity(pathname),
        buildExplicitCaptureDedupKey(content, frontmatter.category, frontmatter.sourceConnector),
      ],
      (rebuildMarker) =>
        this.getTombstoneBlockedCaptureIndex().addWrittenMemory(pathname, frontmatter, content, rebuildMarker),
      beforeIndexUpdate
    );
  }

  protected async withTombstoneBlockedMemoryPathLock<T>(
    pathname: string,
    task: (current: MemoryFile | null) => Promise<T>,
    additionalPathnames: readonly string[] = []
  ): Promise<T> {
    let lockIdentities = [pathname, ...additionalPathnames].map(buildCapturePathLockIdentity);
    for (;;) {
      let retryIdentity: string | undefined;
      let result: T | undefined;
      await this.withTombstoneBlockedCaptureWriteLock(async () => {
        const current = await this.readMemoryByPath(pathname);
        if (current !== null) {
          const currentIdentity = this.offlineSyncMemoryIdentity(current);
          if (!lockIdentities.includes(currentIdentity)) {
            retryIdentity = currentIdentity;
            return;
          }
        }
        result = await task(current);
      }, lockIdentities);
      if (retryIdentity !== undefined) {
        lockIdentities = [...new Set([...lockIdentities, retryIdentity])];
        continue;
      }
      return result!;
    }
  }

  protected async writeTombstoneBlockedChunk(
    pathname: string,
    fileContent: string,
    frontmatter: MemoryFrontmatter,
    content: string,
    findDuplicate: () => Promise<MemoryFile | null>,
    afterWrite: (current: MemoryFile | null) => Promise<void>
  ): Promise<string> {
    const incomingIdentity = buildExplicitCaptureDedupKey(content, frontmatter.category, frontmatter.sourceConnector);
    let lockIdentities = [buildCapturePathLockIdentity(pathname), incomingIdentity];
    for (;;) {
      let retryIdentity: string | undefined;
      let result = frontmatter.id;
      await this.withTombstoneBlockedCaptureWriteLock(async () => {
        const current = await this.readMemoryByPath(pathname);
        if (current !== null) {
          const currentIdentity = this.offlineSyncMemoryIdentity(current);
          if (!lockIdentities.includes(currentIdentity)) {
            retryIdentity = currentIdentity;
            return;
          }
        }
        if (tombstoneBlocked(frontmatter)) {
          const duplicate = await findDuplicate();
          if (duplicate) {
            result = duplicate.frontmatter.id;
            return;
          }
        }
        await this.writeTombstoneBlockedMemory(pathname, fileContent, frontmatter, content);
        await afterWrite(current);
      }, lockIdentities);
      if (retryIdentity === undefined) return result;
      lockIdentities = [...new Set([...lockIdentities, retryIdentity])];
    }
  }

  protected async writeTombstoneBlockedUpdate(
    before: MemoryFile,
    fileContent: string,
    frontmatter: MemoryFrontmatter,
    content: string,
    beforeIndexUpdate?: () => Promise<void>
  ): Promise<string | undefined> {
    return await this.writeTombstoneBlockedMutation(
      tombstoneBlocked(before.frontmatter) || tombstoneBlocked(frontmatter),
      before.path,
      fileContent,
      [
        buildCapturePathLockIdentity(before.path),
        this.offlineSyncMemoryIdentity(before),
        buildExplicitCaptureDedupKey(content, frontmatter.category, frontmatter.sourceConnector),
      ],
      (rebuildMarker, current) =>
        this.getTombstoneBlockedCaptureIndex().syncUpdatedMemory(
          current ?? before,
          frontmatter,
          content,
          rebuildMarker
        ),
      beforeIndexUpdate,
      true,
      () => true
    );
  }

  protected async writeTombstoneBlockedFrontmatter(
    before: MemoryFile,
    fileContent: string,
    frontmatter: MemoryFrontmatter,
    beforeIndexUpdate?: () => Promise<void>
  ): Promise<string | undefined> {
    return await this.writeTombstoneBlockedMutation(
      tombstoneBlocked(before.frontmatter) || tombstoneBlocked(frontmatter),
      before.path,
      fileContent,
      [
        buildCapturePathLockIdentity(before.path),
        this.offlineSyncMemoryIdentity(before),
        buildExplicitCaptureDedupKey(before.content, frontmatter.category, frontmatter.sourceConnector),
      ],
      (rebuildMarker, current) =>
        this.getTombstoneBlockedCaptureIndex().syncUpdatedFrontmatter(current ?? before, frontmatter, rebuildMarker),
      beforeIndexUpdate,
      true,
      (current) => isSemanticFrontmatterChange((current ?? before).frontmatter, frontmatter)
    );
  }


  private isTombstoneBlockedMemory(memory: MemoryFile | null): memory is MemoryFile {
    return memory !== null && memory.frontmatter.status === "pending_review" && Boolean(memory.frontmatter.blockedBy);
  }

  private offlineSyncMemoryIdentity(memory: MemoryFile): string {
    return buildExplicitCaptureDedupKey(
      memory.content,
      memory.frontmatter.category,
      memory.frontmatter.sourceConnector
    );
  }
  private async isDuplicateTombstoneBlockedOfflineSync(
    target: string,
    incoming: MemoryFile,
    streamedIdentity?: StreamedOfflineSyncIdentity
  ): Promise<boolean> {
    const before = await this.readMemoryByPath(target);
    const duplicate = streamedIdentity
      ? true
      : await this.getTombstoneBlockedCaptureIndex().has(
          incoming.content,
          incoming.frontmatter.category,
          incoming.frontmatter.sourceConnector
        );
    if (!duplicate) return false;
    const incomingIdentity = streamedIdentity?.identityHash ?? this.offlineSyncMemoryIdentity(incoming);
    const options = this.tombstoneBlockedCaptureIndexOptions();
    const existing = [...(await options.readAllMemories()), ...(await options.readAllColdMemories())];
    const exactMatch = existing.some(
      (memory) =>
        this.isTombstoneBlockedMemory(memory) &&
        (streamedIdentity ? captureIdentityHash(memory) : this.offlineSyncMemoryIdentity(memory)) === incomingIdentity
    );
    if (!exactMatch) return false;
    if (before === null) return true;
    if (!this.isTombstoneBlockedMemory(before)) return false;
    const beforeIdentity = streamedIdentity ? captureIdentityHash(before) : this.offlineSyncMemoryIdentity(before);
    if (beforeIdentity !== incomingIdentity) return false;
    return streamedIdentity
      ? isDeepStrictEqual(before.frontmatter, incoming.frontmatter)
      : before.content === incoming.content && isDeepStrictEqual(before.frontmatter, incoming.frontmatter);
  }

  private async invalidateAfterOfflineSyncMutation(
    filePath: string,
    ownedMarker?: string,
    archiveChanged = true,
    blockedKeySetMayHaveChanged = true
  ): Promise<void> {
    this.invalidateAllMemoriesCache();
    this.invalidateKnowledgeIndexCache();
    this.markFactHashIndexNotAuthoritative();
    if (filePath.includes(`${path.sep}cold${path.sep}`)) {
      this.invalidateColdMemoriesCache();
    }
    if (blockedKeySetMayHaveChanged) {
      await this.rebuildTombstoneBlockedCaptureAfterInvalidationForPath(filePath, ownedMarker);
    } else if (ownedMarker !== undefined) {
      // The index only holds tombstone-blocked explicit-capture keys, so a
      // write where neither side is blocked cannot have changed it. Rebuilding
      // here re-reads the whole corpus per replicated file — measured 15-31s
      // per write against a ~190k-file corpus, which turns a boot-scale
      // `converge apply` into a multi-week run. Clear the committed marker and
      // keep the index as-is.
      try {
        await this.getTombstoneBlockedCaptureIndex().clearCommittedWriteMarker(ownedMarker);
      } catch (err) {
        this.getTombstoneBlockedCaptureIndex().markUntrusted();
        log.warn(`storage.offlineSyncFile committed write succeeded; marker cleanup failed: ${err}`);
      }
    }
    if (filePath.includes(`${path.sep}artifacts${path.sep}`)) {
      this.bumpArtifactWriteVersion();
    }
    const memoryDir = this.tombstoneBlockedCaptureIndexOptions().memoryDir;
    archiveMutation.bumpArchiveMutationForPath(memoryDir, archiveChanged, filePath);
    this.bumpMemoryStatusVersion();
  }

  protected async runTombstoneBlockedArchive(
    memory: MemoryFile,
    task: (current: MemoryFile, markDurable: () => void) => Promise<string | null>
  ): Promise<string | null> {
    let archivedPath: string | null = null;
    const archived = await this.runTombstoneBlockedInvalidation(memory, async (current, rebuildMarker, markDurable) => {
      let archiveDurable = false;
      const markArchiveDurable = () => {
        archiveDurable = true;
        markDurable();
      };
      archivedPath = await task(current, markArchiveDurable);
      if (rebuildMarker !== undefined && (archivedPath !== null || archiveDurable)) {
        await this.rebuildTombstoneBlockedCaptureAfterInvalidation(rebuildMarker);
      } else if (rebuildMarker !== undefined) {
        const index = this.getTombstoneBlockedCaptureIndex();
        try {
          await index.discardWrite(rebuildMarker);
        } catch {
          index.markUntrusted();
        }
      }
      return archivedPath !== null;
    });
    return archived ? archivedPath : null;
  }

  protected async runTombstoneBlockedInvalidation(
    memory: MemoryFile,
    task: (current: MemoryFile, rebuildMarker: string | undefined, markDurable: () => void) => Promise<boolean>,
    propagateErrors = false,
    coordinate = false
  ): Promise<boolean> {
    let lockIdentities = [
      buildCapturePathLockIdentity(memory.path),
      ...(coordinate || this.isTombstoneBlockedMemory(memory) || isQueuedReviewMemory(memory)
        ? [this.offlineSyncMemoryIdentity(memory)]
        : []),
    ];
    for (;;) {
      const attempt = async () => {
        const options = this.tombstoneBlockedCaptureIndexOptions();
        const current =
          (await this.readMemoryByPath(memory.path)) ??
          (await options.readAllMemories()).find((candidate) => candidate.frontmatter.id === memory.frontmatter.id) ??
          (await options.readAllColdMemories()).find((candidate) => candidate.frontmatter.id === memory.frontmatter.id);
        if (!current) return { result: false };
        const blocked = this.isTombstoneBlockedMemory(current);
        const queuedReview = isQueuedReviewMemory(current);
        if (blocked || queuedReview) {
          const currentIdentity = this.offlineSyncMemoryIdentity(current);
          if (!lockIdentities.includes(currentIdentity)) return { retryIdentity: currentIdentity };
        }
        const blockedIndex = blocked ? this.getTombstoneBlockedCaptureIndex() : null;
        let rebuildMarker: string | undefined;
        let durable = false;
        try {
          if (blockedIndex) rebuildMarker = await blockedIndex.prepareWrite();
          const result = await task(current, rebuildMarker, () => {
            durable = true;
          });
          if (!result && rebuildMarker && !durable && blockedIndex) {
            try {
              await blockedIndex.discardWrite(rebuildMarker);
            } catch {
              blockedIndex.markUntrusted();
            }
          }
          return { result };
        } catch (error) {
          if (rebuildMarker && !durable && blockedIndex) {
            try {
              await blockedIndex.discardWrite(rebuildMarker);
            } catch {
              blockedIndex.markUntrusted();
            }
          }
          if (propagateErrors) throw error;
          return { result: false };
        }
      };
      const result = await this.withTombstoneBlockedCaptureWriteLock(attempt, lockIdentities);
      if (result.retryIdentity !== undefined) {
        lockIdentities = [...new Set([...lockIdentities, result.retryIdentity])];
        continue;
      }
      return result.result;
    }
  }
  async deleteMemoryForMaintenance(
    memory: MemoryFile,
    shouldDelete: (current: MemoryFile) => boolean = () => true
  ): Promise<MemoryFile | null> {
    let deleted: MemoryFile | null = null;
    const removed = await this.runTombstoneBlockedInvalidation(
      memory,
      async (current, rebuildMarker, markDurable) => {
        if (!shouldDelete(current)) return false;
        if (!(await this.deleteManagedStorageFile(current.path))) return false;
        markDurable();
        deleted = current;
        const memoryDir = this.tombstoneBlockedCaptureIndexOptions().memoryDir;
        archiveMutation.bumpArchiveMutationForPath(memoryDir, true, current.path);
        markProjectedMemoryPathInvalid(memoryDir, current.frontmatter.id);
        this.invalidateAllMemoriesCache();
        if (current.path.includes(`${path.sep}cold${path.sep}`)) {
          this.invalidateColdMemoriesCache();
        }
        await this.rebuildTombstoneBlockedCaptureAfterInvalidation(rebuildMarker);
        this.bumpMemoryCorpusVersion();
        this.bumpMemoryStatusVersion();
        return true;
      },
      true,
      true
    );
    return removed ? deleted : null;
  }

  protected async runTombstoneBlockedOfflineSyncMutation(
    target: string,
    after: MemoryFile | null,
    write: () => Promise<boolean | void>,
    coordinate = false,
    streamedIdentity?: StreamedOfflineSyncIdentity
  ): Promise<void> {
    for (;;) {
      const before = await this.readMemoryByPath(target);
      const targetIdentity = before === null ? undefined : this.offlineSyncMemoryIdentity(before);
      const afterIdentity = after === null || streamedIdentity ? undefined : this.offlineSyncMemoryIdentity(after);
      const mustCoordinate =
        coordinate || targetIdentity !== undefined || afterIdentity !== undefined || streamedIdentity !== undefined;
      const identities = [
        ...(mustCoordinate ? [buildCapturePathLockIdentity(target)] : []),
        ...(targetIdentity === undefined ? [] : [targetIdentity]),
        ...(afterIdentity === undefined ? [] : [afterIdentity]),
      ];
      let retryIdentity: string | undefined;
      const mutate = async (): Promise<void> => {
        const current = await this.readMemoryByPath(target);
        if (current !== null) {
          const currentIdentity = this.offlineSyncMemoryIdentity(current);
          if (currentIdentity !== targetIdentity) {
            retryIdentity = currentIdentity;
            return;
          }
        }
        if (
          this.isTombstoneBlockedMemory(after) &&
          (await this.isDuplicateTombstoneBlockedOfflineSync(target, after, streamedIdentity))
        ) {
          return;
        }
        const affectsBlockedIndex =
          coordinate || this.isTombstoneBlockedMemory(current) || this.isTombstoneBlockedMemory(after);
        const marker = affectsBlockedIndex ? await this.getTombstoneBlockedCaptureIndex().prepareWrite() : undefined;
        let durable = false;
        try {
          const changed = await write();
          durable = true;
          if (marker) {
            try {
              await this.getTombstoneBlockedCaptureIndex().commitWrite(marker);
            } catch (err) {
              this.getTombstoneBlockedCaptureIndex().markUntrusted();
              log.warn(`storage.offlineSyncFile committed write marker failed: ${err}`);
            }
          }
          await this.invalidateAfterOfflineSyncMutation(
            target,
            marker,
            changed !== false,
            this.isTombstoneBlockedMemory(current) || this.isTombstoneBlockedMemory(after)
          );
        } catch (err) {
          if (marker && !durable) {
            try {
              await this.getTombstoneBlockedCaptureIndex().discardWrite(marker);
            } catch (cleanupError) {
              this.getTombstoneBlockedCaptureIndex().markUntrusted();
              log.warn(`storage.offlineSyncFile failed to clear write marker: ${cleanupError}`);
            }
          }
          throw err;
        }
      };
      if (!mustCoordinate) {
        await mutate();
      } else if (streamedIdentity) {
        await this.withTombstoneBlockedCaptureWriteLockAndHashes(mutate, identities, [streamedIdentity.identityHash]);
      } else {
        await this.withTombstoneBlockedCaptureWriteLock(mutate, identities);
      }
      if (retryIdentity !== undefined) continue;
      return;
    }
  }

  protected async writeTombstoneBlockedOfflineSyncFile(target: string, content: Buffer): Promise<void> {
    const options = this.tombstoneBlockedCaptureIndexOptions();
    const after = options.parseMemory?.(target, content) ?? null;
    await withRawEntityPageMutation(path.dirname(options.stateDir), target, async () => {
      await this.runTombstoneBlockedOfflineSyncMutation(target, after, () =>
        this.writeManagedStorageFile(target, () => this.writeStorageSecureFile(target, content))
      );
    });
  }

  private async prepareTombstoneBlockedOfflineSyncChunks(
    target: string,
    chunks: AsyncIterable<Buffer>
  ): Promise<PreparedOfflineSyncChunks> {
    const parseMemory = this.tombstoneBlockedCaptureIndexOptions().parseMemory;
    if (!parseMemory) return { after: null, chunks };

    const iterator = chunks[Symbol.asyncIterator]();
    const buffered: Buffer[] = [];
    let bufferedBytes = 0;
    let firstOverflow: Buffer | undefined;
    for (;;) {
      const next = await iterator.next();
      if (next.done) break;
      if (bufferedBytes + next.value.length > OFFLINE_SYNC_BUFFER_LIMIT_BYTES) {
        firstOverflow = next.value;
        break;
      }
      bufferedBytes += next.value.length;
      buffered.push(next.value);
    }
    const overflow = firstOverflow;
    if (overflow === undefined) {
      let after: MemoryFile | null = null;
      try {
        after = parseMemory(target, Buffer.concat(buffered));
      } catch {
        after = null;
      }
      const replay = (async function* (): AsyncIterable<Buffer> {
        for (const chunk of buffered) yield chunk;
      })();
      return { after, chunks: replay };
    }

    const options = this.tombstoneBlockedCaptureIndexOptions();
    const stagePath = path.join(
      options.stateDir,
      "tombstone-blocked-capture",
      "offline-sync-staging",
      `${randomUUID()}.stage`
    );
    const stagedChunks = (async function* (): AsyncIterable<Buffer> {
      for (const chunk of buffered) yield chunk;
      yield overflow;
      for (;;) {
        const next = await iterator.next();
        if (next.done) break;
        yield next.value;
      }
    })();
    try {
      await writeMaybeEncryptedFileFromChunks(
        stagePath,
        stagedChunks,
        options.secureStoreWriteKeyProvider(),
        { atomic: false },
        options.memoryDir
      );
      return await this.describeStagedOfflineSyncChunks(target, stagePath, parseMemory);
    } catch (err) {
      await unlink(stagePath).catch(() => {});
      throw err;
    }
  }

  private async describeStagedOfflineSyncChunks(
    target: string,
    stagePath: string,
    parseMemory: OfflineSyncMemoryParser
  ): Promise<PreparedOfflineSyncChunks> {
    const options = this.tombstoneBlockedCaptureIndexOptions();
    const key = options.secureStoreKeyProvider();
    const bodyOffset = await findStagedBodyOffset(stagePath, key, options.memoryDir);
    if (bodyOffset === null) {
      return { after: null, chunks: this.readStagedOfflineSyncChunks(stagePath), stagePath };
    }
    const prefix = await readStagedPrefix(stagePath, bodyOffset, key, options.memoryDir);
    let after: MemoryFile | null = null;
    try {
      after = parseMemory(target, prefix.subarray(0, bodyOffset));
    } catch {
      after = null;
    }
    if (after === null) {
      return { after: null, chunks: this.readStagedOfflineSyncChunks(stagePath), stagePath };
    }
    const streamedIdentity = await this.computeStagedOfflineSyncIdentity(stagePath, bodyOffset, after);
    return {
      after,
      chunks: this.readStagedOfflineSyncChunks(stagePath),
      stagePath,
      streamedIdentity,
    };
  }

  private async computeStagedOfflineSyncIdentity(
    stagePath: string,
    bodyOffset: number,
    after: MemoryFile
  ): Promise<StreamedOfflineSyncIdentity> {
    let normalizedLength = 0;
    const countNormalizer = createExplicitContentNormalizer({
      write: (chunk) => {
        normalizedLength += chunk.length;
      },
      beginConditionalSigma: () => {
        normalizedLength += 1;
      },
      resolveConditionalSigma: () => {},
    });
    const options = this.tombstoneBlockedCaptureIndexOptions();
    const key = options.secureStoreKeyProvider();
    await forEachStagedTextChunk(stagePath, bodyOffset, (text) => countNormalizer.push(text), key, options.memoryDir);
    countNormalizer.finish();

    const category = after.frontmatter.category;
    const connector = after.frontmatter.sourceConnector?.trim() ?? "";
    const encode = (label: string, value: string): string => `${label} ${value.length} ${value}`;
    const identityPrefix = [
      encode("category", category),
      encode("connector", connector),
      `content ${normalizedLength} `,
    ].join(" ");
    let identityHash = createHash("sha256");
    let normalSigmaIdentityHash: Hash | undefined;
    identityHash.update(identityPrefix);
    const identityNormalizer = createExplicitContentNormalizer({
      write: (chunk) => {
        identityHash.update(chunk);
        normalSigmaIdentityHash?.update(chunk);
      },
      beginConditionalSigma: () => {
        normalSigmaIdentityHash = identityHash.copy().update("σ");
        identityHash.update("ς");
      },
      resolveConditionalSigma: (useFinalSigma) => {
        if (!useFinalSigma) {
          if (normalSigmaIdentityHash === undefined) throw new Error("conditional sigma hash state is missing");
          identityHash = normalSigmaIdentityHash;
        }
        normalSigmaIdentityHash = undefined;
      },
    });
    await forEachStagedTextChunk(
      stagePath,
      bodyOffset,
      (text) => identityNormalizer.push(text),
      key,
      options.memoryDir
    );
    identityNormalizer.finish();
    return {
      identityHash: identityHash.digest("hex"),
    };
  }

  private async *readStagedOfflineSyncChunks(stagePath: string): AsyncIterable<Buffer> {
    const options = this.tombstoneBlockedCaptureIndexOptions();
    for await (const chunk of readMaybeEncryptedFileFromChunks(
      stagePath,
      options.secureStoreKeyProvider(),
      options.memoryDir
    )) {
      yield chunk;
    }
  }

  protected async writeTombstoneBlockedOfflineSyncFileChunks(
    target: string,
    chunks: AsyncIterable<Buffer>
  ): Promise<void> {
    const coordinate = this.getTombstoneBlockedCaptureIndex().shouldRebuildAfterInvalidationForPath(target);
    const prepared: PreparedOfflineSyncChunks = coordinate
      ? await this.prepareTombstoneBlockedOfflineSyncChunks(target, chunks)
      : { after: null, chunks };
    const streamedIdentity = prepared.streamedIdentity;
    const baseDir = path.dirname(this.tombstoneBlockedCaptureIndexOptions().stateDir);
    try {
      await withRawEntityPageMutation(baseDir, target, async () => {
        await this.runTombstoneBlockedOfflineSyncMutation(
          target,
          prepared.after,
          () => this.writeManagedStorageFile(target, () => this.writeStorageSecureFileChunks(target, prepared.chunks)),
          coordinate,
          streamedIdentity
        );
      });
    } finally {
      if (prepared.stagePath !== undefined) await unlink(prepared.stagePath).catch(() => {});
    }
  }

  async writeOfflineSyncFile(filePath: string, content: Buffer): Promise<void> {
    const target = this.assertManagedStoragePath(filePath, "storage.writeOfflineSyncFile");
    await this.writeTombstoneBlockedOfflineSyncFile(target, content);
    await this.requestSyncReconcileIfMigrationPath(target);
  }

  async writeOfflineSyncFileChunks(filePath: string, chunks: AsyncIterable<Buffer>): Promise<void> {
    const target = this.assertManagedStoragePath(filePath, "storage.writeOfflineSyncFileChunks");
    await this.writeTombstoneBlockedOfflineSyncFileChunks(target, chunks);
    await this.requestSyncReconcileIfMigrationPath(target);
  }

  /**
   * Opaque replicated bytes can restore legacy memory references or entity
   * relationship targets. Other sync traffic must not request reconciliation.
   */
  private async requestSyncReconcileIfMigrationPath(target: string): Promise<void> {
    const stateDir = this.tombstoneBlockedCaptureIndexOptions().stateDir;
    if (!pathMayCarryEntityRefs(path.dirname(stateDir), target)) return;
    await requestEntityCanonicalIdReconcile(stateDir);
  }

  async deleteOfflineSyncFile(filePath: string, deletionMtimeMs?: number | null): Promise<void> {
    const target = this.assertManagedStoragePath(filePath, "storage.deleteOfflineSyncFile");
    await this.deleteTombstoneBlockedOfflineSyncFile(target, deletionMtimeMs);
    await this.requestSyncReconcileIfMigrationPath(target);
  }

  protected async deleteTombstoneBlockedOfflineSyncFile(
    target: string,
    deletionMtimeMs?: number | null
  ): Promise<void> {
    const stateDir = this.tombstoneBlockedCaptureIndexOptions().stateDir;
    await withRawEntityPageMutation(path.dirname(stateDir), target, async () => {
      await this.runTombstoneBlockedOfflineSyncMutation(target, null, async () => {
        return await this.deleteManagedStorageFile(target, deletionMtimeMs);
      });
    });
  }

  async checkTombstoneBlockedExplicitCapture(
    ...args: [string, string, string?]
  ): Promise<{ has: boolean; authoritative: boolean }> {
    return this.getTombstoneBlockedCaptureIndex().check(...args);
  }

  async hasTombstoneBlockedExplicitCapture(...args: [string, string, string?]): Promise<boolean> {
    return this.getTombstoneBlockedCaptureIndex().has(...args);
  }

  async isTombstoneBlockedExplicitCaptureIndexAuthoritative(): Promise<boolean> {
    return this.getTombstoneBlockedCaptureIndex().isAuthoritative();
  }

  protected async rebuildTombstoneBlockedCaptureAfterInvalidationForPath(
    filePath: string,
    ownedMarker?: string
  ): Promise<void> {
    const index = this.getTombstoneBlockedCaptureIndex();
    if (index.shouldRebuildAfterInvalidationForPath(filePath)) {
      await this.rebuildTombstoneBlockedCaptureAfterInvalidation(ownedMarker);
    }
  }
  protected async rebuildTombstoneBlockedCaptureAfterInvalidation(ownedMarker?: string): Promise<void> {
    await this.getTombstoneBlockedCaptureIndex().rebuildAfterInvalidation(ownedMarker);
  }
}

import { createHash } from "node:crypto";
import { z } from "zod";

import { normalizeNamespaceIdentity } from "../namespaces/identity.js";
import { parseIsoOffsetTimestamp } from "../utils/iso-timestamp.js";

export const SUPPORT_PASSPORT_CARD_CATEGORIES = [
  "communication",
  "environment",
  "transitions",
  "sensory",
  "regulation",
  "interests",
  "other",
] as const;

export const SUPPORT_PASSPORT_CARD_STATUSES = [
  "pending_review",
  "active",
  "rejected",
  "superseded",
  "archived",
] as const;

export const SupportPassportCardCategorySchema = z.enum(SUPPORT_PASSPORT_CARD_CATEGORIES);
export const SupportPassportCardStatusSchema = z.enum(SUPPORT_PASSPORT_CARD_STATUSES);
export const SupportPassportCardTitleSchema = z
  .string()
  .trim()
  .min(1)
  .max(80)
  .refine((title) => !title.includes("]") && !title.includes("\n") && !title.includes("\r"), {
    message: "card titles cannot contain closing brackets or line breaks",
  });

const IsoTimestampSchema = z
  .string()
  .datetime({ offset: true })
  .refine((value) => parseIsoOffsetTimestamp(value) !== null, {
    message: "timestamps must be valid ISO 8601 values",
  });
export const SupportPassportNamespaceSchema = z
  .string()
  .min(1)
  .refine((namespace) => namespace === normalizeNamespaceIdentity(namespace), {
    message: "namespaces must be canonical",
  });
export const SupportPassportMemoryIdSchema = z
  .string()
  .trim()
  .min(1)
  .max(128)
  .regex(/^[A-Za-z0-9._:-]+$/);
export const SUPPORT_PASSPORT_SOURCE_MEMORY_ID_MAX_LENGTH = 512;
export const SupportPassportSourceMemoryIdSchema = z
  .string()
  .trim()
  .min(1)
  .max(SUPPORT_PASSPORT_SOURCE_MEMORY_ID_MAX_LENGTH);

export const SupportPassportCardSchema = z
  .object({
    cardId: SupportPassportMemoryIdSchema,
    title: SupportPassportCardTitleSchema,
    statement: z.string().trim().min(1).max(500),
    category: SupportPassportCardCategorySchema,
    status: SupportPassportCardStatusSchema,
    updatedAt: IsoTimestampSchema,
    reviewBy: IsoTimestampSchema,
    revision: z.string().regex(/^[a-f0-9]{64}$/),
  })
  .strict();

export const SupportPassportCardListSchema = z
  .array(SupportPassportCardSchema)
  .max(100)
  .superRefine((cards, ctx) => {
    const seen = new Set<string>();
    for (const [index, card] of cards.entries()) {
      if (seen.has(card.cardId)) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: "card IDs must be unique",
          path: [index, "cardId"],
        });
      }
      seen.add(card.cardId);
    }
  });

export const SupportPassportListCardsInputSchema = z
  .object({
    principal: z.string().trim().min(1).max(512),
  })
  .strict();

export const SupportPassportManualDraftInputSchema = z
  .object({
    principal: z.string().trim().min(1).max(512),
    title: SupportPassportCardTitleSchema,
    statement: z.string().trim().min(1).max(500),
    category: SupportPassportCardCategorySchema,
    reviewBy: IsoTimestampSchema,
  })
  .strict();

export const SupportPassportCardMutationInputSchema = z
  .object({
    principal: z.string().trim().min(1).max(512),
    cardId: SupportPassportMemoryIdSchema,
    expectedRevision: z.string().regex(/^[a-f0-9]{64}$/),
    reasonCode: z
      .string()
      .trim()
      .min(1)
      .max(64)
      .regex(/^[a-z0-9-]+$/)
      .optional(),
  })
  .strict();

export const SupportPassportReplaceCardInputSchema = SupportPassportCardMutationInputSchema.extend({
  title: SupportPassportCardTitleSchema,
  statement: z.string().trim().min(1).max(500),
  category: SupportPassportCardCategorySchema,
  reviewBy: IsoTimestampSchema,
}).strict();

export type SupportPassportCard = z.infer<typeof SupportPassportCardSchema>;
export type SupportPassportCardCategory = z.infer<typeof SupportPassportCardCategorySchema>;
export type SupportPassportCardStatus = z.infer<typeof SupportPassportCardStatusSchema>;
export type SupportPassportManualDraftInput = z.input<typeof SupportPassportManualDraftInputSchema>;
export type SupportPassportCardMutationInput = z.input<typeof SupportPassportCardMutationInputSchema>;
export type SupportPassportReplaceCardInput = z.input<typeof SupportPassportReplaceCardInputSchema>;

type RevisionFields = Omit<SupportPassportCard, "revision">;

export function computeSupportPassportCardRevision(fields: RevisionFields): string {
  const canonicalFields = {
    cardId: fields.cardId,
    category: fields.category,
    reviewBy: fields.reviewBy,
    statement: fields.statement,
    status: fields.status,
    title: fields.title,
    updatedAt: fields.updatedAt,
  };
  return createHash("sha256").update(JSON.stringify(canonicalFields)).digest("hex");
}

// Tag filtering helpers for memory recall (issue #689).
//
// Tags are free-form labels stored on each memory's frontmatter (see
// `storage.ts`). Recall callers can filter the result set down to memories
// that match a set of tags using `any` (default) or `all` semantics.
//
// This module is intentionally small and pure. The actual filter is applied
// at the access-service seam after `serializeRecallResults` hydrates each
// result's tags from frontmatter, so we don't have to touch QMD or thread
// tag-aware metadata through orchestrator internals for v1.
//
// Comparison is case-sensitive exact match — same form storage uses for tags.

import type { RecallFilterTrace } from "./recall-xray.js";

export type TagMatchMode = "any" | "all";

const TAG_MATCH_VALUES: ReadonlyArray<TagMatchMode> = ["any", "all"];

/**
 * Coerce a caller-supplied `tagMatch` value to the allowed enum.
 *
 * - `undefined` / `null` → `undefined` (caller didn't ask).
 * - Valid string → narrowed `TagMatchMode`.
 * - Invalid string → throws (CLAUDE.md rule 51 — never silently default).
 */
export function parseTagMatch(value: unknown): TagMatchMode | undefined {
  if (value === undefined || value === null) return undefined;
  if (typeof value !== "string") {
    throw new Error(
      `tagMatch must be a string (one of: ${TAG_MATCH_VALUES.join(", ")})`,
    );
  }
  const trimmed = value.trim();
  if (trimmed.length === 0) return undefined;
  if (trimmed !== "any" && trimmed !== "all") {
    throw new Error(
      `invalid tagMatch value: ${value} (expected one of: ${TAG_MATCH_VALUES.join(", ")})`,
    );
  }
  return trimmed;
}

/**
 * Coerce a caller-supplied `tags` value into a clean string[].
 *
 * Accepts `string[]` and discards non-string / empty entries. Returns
 * `undefined` when no usable tags remain so downstream callers can treat
 * "no filter" and "empty filter" identically.
 */
export function normalizeTags(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const out: string[] = [];
  const seen = new Set<string>();
  for (const entry of value) {
    if (typeof entry !== "string") continue;
    const trimmed = entry.trim();
    if (trimmed.length === 0) continue;
    if (seen.has(trimmed)) continue;
    seen.add(trimmed);
    out.push(trimmed);
  }
  return out.length > 0 ? out : undefined;
}

export interface TagFilterInput {
  tags: string[] | undefined;
  tagMatch: TagMatchMode | undefined;
}

export interface TagFilterDecision {
  /** Whether the candidate's tags satisfy the filter. */
  admitted: boolean;
}

/**
 * Decide whether a single result's tags satisfy the filter.
 *
 * `any` (default) admits when the result has at least one of the filter
 * tags. `all` admits only when every filter tag is present on the result.
 * Returns `admitted: true` whenever no filter tags are configured.
 */
export function evaluateTagFilter(
  candidateTags: string[] | undefined,
  filter: TagFilterInput,
): TagFilterDecision {
  const filterTags = filter.tags;
  if (!filterTags || filterTags.length === 0) {
    return { admitted: true };
  }
  const tags = Array.isArray(candidateTags) ? candidateTags : [];
  const tagSet = new Set(tags);
  const mode: TagMatchMode = filter.tagMatch ?? "any";
  if (mode === "all") {
    for (const t of filterTags) {
      if (!tagSet.has(t)) return { admitted: false };
    }
    return { admitted: true };
  }
  for (const t of filterTags) {
    if (tagSet.has(t)) return { admitted: true };
  }
  return { admitted: false };
}

export interface TaggedResult {
  tags: string[];
}

/**
 * Apply the tag filter to an array of recall results.
 *
 * Returns `{results, trace}`:
 *  - `results` is the filtered array (or the original when no filter).
 *  - `trace` is a `RecallFilterTrace` capturing how many candidates were
 *    seen vs admitted, suitable for surfacing in X-ray output.
 *
 * `trace` is `null` when no filter tags were configured so callers can
 * skip emitting an empty trace entry.
 */
export function applyTagFilter<T extends TaggedResult>(
  results: T[],
  filter: TagFilterInput,
): { results: T[]; trace: RecallFilterTrace | null } {
  const filterTags = filter.tags;
  if (!filterTags || filterTags.length === 0) {
    return { results, trace: null };
  }
  const mode: TagMatchMode = filter.tagMatch ?? "any";
  const admitted: T[] = [];
  for (const r of results) {
    if (evaluateTagFilter(r.tags, filter).admitted) {
      admitted.push(r);
    }
  }
  const trace: RecallFilterTrace = {
    name: "tag-filter",
    considered: results.length,
    admitted: admitted.length,
    reason: `tags=${filterTags.join(",")} match=${mode}`,
  };
  return { results: admitted, trace };
}

/**
 * GitContextResolver — pure module for detecting the git project + branch
 * a session is operating in.
 *
 * Introduced by issue #569 (coding-agent project/branch-scoped namespaces).
 *
 * This module is deliberately pure:
 *   - no orchestrator references
 *   - no config side-effects
 *   - no namespace wiring
 *
 * Downstream slices (PR 2+ of #569) wire `resolveGitContext` into the
 * `NamespaceResolver` / `Orchestrator` so that memories are scoped to a
 * detected project / branch without leaking across repos.
 *
 * CLAUDE.md rule 17 (expand `~`): the `rootPath` returned here is always an
 * absolute, tilde-expanded path. Callers must not re-expand.
 *
 * CLAUDE.md rule 51 (reject invalid input): `cwd` must be an absolute path
 * and must exist. `resolveGitContext` returns `null` — rather than throwing —
 * when the directory is not inside a git worktree, because being outside a
 * repo is a normal runtime state (e.g. agent opened in a scratch dir).
 */
import path from "node:path";

import { abortError } from "../abort-error.js";
import { launchProcess, launchProcessSync } from "../runtime/child-process.js";
import { expandTildePath } from "../utils/path.js";

// Re-export so existing callers / tests that imported `expandTildePath` from
// this module keep working. CLAUDE.md #17 requires consistent `~` expansion
// across every user-facing path input; the canonical implementation now
// lives in `utils/path.ts`.
export { expandTildePath };

// ──────────────────────────────────────────────────────────────────────────
// Public types
// ──────────────────────────────────────────────────────────────────────────

export interface GitContext {
  /**
   * Stable identifier for the project. Derived from `git remote get-url origin`
   * when an origin remote is configured, otherwise from the repo root path.
   *
   * Formatted as `origin:<hex>` or `root:<hex>` so that the source is visible
   * to operators (see `remnic doctor`, issue #569 acceptance criteria).
   */
  projectId: string;
  /**
   * Current branch, e.g. `main`, `feat/foo`. `null` only in detached-HEAD
   * state (e.g. rebase in progress). Callers should treat `null` as "no
   * branch-scope overlay applies" without erroring.
   */
  branch: string | null;
  /**
   * Absolute path to the repository root (the directory containing `.git`).
   * Tilde-expanded per CLAUDE.md #17.
   */
  rootPath: string;
  /**
   * Best-effort default branch (usually `main` or `master`). Derived from the
   * `refs/remotes/origin/HEAD` symbolic ref. `null` when not available (e.g.
   * fresh clone without a default branch symref, or no origin remote).
   */
  defaultBranch: string | null;
}

export interface GitInvokeOptions {
  abortSignal?: AbortSignal;
  timeoutMs?: number;
}

export interface GitInvokeResult {
  stdout: string;
  exitCode: number;
}

/**
 * Run `git <args>` with `cwd` as the working directory. Implementations
 * should return non-zero exit codes rather than throwing for command failure.
 */
export interface GitInvoker {
  (
    cwd: string,
    args: string[],
    options?: GitInvokeOptions,
  ): GitInvokeResult | Promise<GitInvokeResult>;
}

export interface SyncGitInvoker {
  (cwd: string, args: string[]): GitInvokeResult;
}

// ──────────────────────────────────────────────────────────────────────────
// Default git invoker — spawns real `git` via the shared child-process helper
// ──────────────────────────────────────────────────────────────────────────

const DEFAULT_GIT_TIMEOUT_MS = 2_000;

export function defaultGitInvokerSync(): SyncGitInvoker {
  return (cwd: string, args: string[]) => {
    const result = launchProcessSync("git", args, {
      cwd,
      encoding: "utf-8",
      timeout: DEFAULT_GIT_TIMEOUT_MS,
      shell: false,
    });
    if (result.error) return { stdout: "", exitCode: 127 };
    return {
      stdout: typeof result.stdout === "string" ? result.stdout : "",
      exitCode: typeof result.status === "number" ? result.status : 1,
    };
  };
}

export function defaultGitInvoker(): GitInvoker {
  return (cwd, args, options = {}) => {
    if (options.abortSignal?.aborted) {
      throw options.abortSignal.reason instanceof Error
        ? options.abortSignal.reason
        : abortError("git context resolution aborted");
    }

    const child = launchProcess("git", args, {
      cwd,
      encoding: "utf-8",
      shell: false,
      stdio: ["ignore", "pipe", "ignore"],
    });
    const { promise, resolve, reject } = Promise.withResolvers<GitInvokeResult>();
    let stdout = "";
    let settled = false;
    let timer: NodeJS.Timeout | undefined;

    const cleanup = (): void => {
      clearTimeout(timer);
      options.abortSignal?.removeEventListener("abort", onAbort);
    };
    const finish = (result: GitInvokeResult): void => {
      if (settled) return;
      settled = true;
      cleanup();
      resolve(result);
    };
    const fail = (error: Error): void => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(error);
    };
    const onAbort = (): void => {
      child.kill("SIGTERM");
      fail(
        options.abortSignal?.reason instanceof Error
          ? options.abortSignal.reason
          : abortError("git context resolution aborted"),
      );
    };

    child.stdout?.setEncoding("utf-8");
    child.stdout?.on("data", (chunk: string | Buffer) => {
      stdout += chunk.toString();
    });
    child.once("error", () => finish({ stdout: "", exitCode: 127 }));
    child.once("close", (exitCode: number | null) => {
      finish({ stdout, exitCode: typeof exitCode === "number" ? exitCode : 1 });
    });
    options.abortSignal?.addEventListener("abort", onAbort, { once: true });

    const timeoutMs = Math.max(
      1,
      Math.min(DEFAULT_GIT_TIMEOUT_MS, options.timeoutMs ?? DEFAULT_GIT_TIMEOUT_MS),
    );
    timer = setTimeout(() => {
      child.kill("SIGTERM");
      finish({ stdout: "", exitCode: 124 });
    }, timeoutMs);
    if (options.abortSignal?.aborted) onAbort();
    return promise;
  };
}

// ──────────────────────────────────────────────────────────────────────────
// Stable hashing
// ──────────────────────────────────────────────────────────────────────────

/**
 * Non-cryptographic stable hash. Used only to derive a deterministic
 * `projectId` from either the origin URL or the root path. The hash does not
 * need to be collision-resistant against adversarial input — it is purely a
 * namespace discriminator.
 *
 * Uses FNV-1a 32-bit so we don't pull in `node:crypto` for a simple bucket
 * key. Output is lowercase hex, zero-padded to 8 characters.
 */
export function stableHash(input: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, "0");
}

// ──────────────────────────────────────────────────────────────────────────
// Origin URL normalization
// ──────────────────────────────────────────────────────────────────────────

/**
 * Normalize a git remote URL so that equivalent SSH / HTTPS forms of the
 * same repo produce the same `projectId`. Handles:
 *   - `git@github.com:foo/bar.git`  → `github.com/foo/bar`
 *   - `https://github.com/foo/bar`  → `github.com/foo/bar`
 *   - `https://github.com/foo/bar.git` → `github.com/foo/bar`
 *   - `ssh://git@github.com/foo/bar` → `github.com/foo/bar`
 *   - `ssh://git@github.com:2222/foo/bar` → `github.com/foo/bar` (port stripped)
 *
 * Case-insensitive (remote hostnames and most repo paths on major forges are
 * case-insensitive in practice).
 */
export function normalizeOriginUrl(rawUrl: string): string {
  let url = rawUrl.trim();
  if (!url) return "";

  // Strip trailing `.git` case-insensitively — the whole result is
  // lowercased at the end, so `.GIT` / `.Git` must be treated the same as
  // `.git`. Previously the `.endsWith(".git")` check let `.GIT` leak
  // through and appear in the output.
  if (/\.git$/i.test(url)) url = url.slice(0, -4);

  // Windows drive-letter local path (e.g. `C:/repos/app`): detect here
  // so the scp matcher below can accept single-character SSH host aliases
  // (`h:foo/bar` from `.ssh/config`). A drive letter is exactly one ASCII
  // letter followed by `:/` or `:\`; SSH aliases never have a slash
  // immediately after the colon.
  if (/^[A-Za-z]:[\\/]/.test(url)) {
    return url.toLowerCase();
  }

  // Protocol-prefixed: ssh://, https://, http://, git://, file://
  // Must be tried FIRST so that scp-style detection below doesn't
  // incorrectly swallow an ssh:// URL that happens to contain `:port/`.
  //
  // Matches:
  //   1: host — bracketed IPv6 `[2001:db8::1]`, plain host with no `:` / `/`,
  //      OR empty (for `file:///path` which has no host component).
  //   2: port (optional) — preserved in the output so two repos on the same
  //      host under different ports get distinct project namespaces.
  //      Losing the port risked false-coalescing separate repos on custom
  //      SSH mesh setups.
  //   3: path (optional)
  const protoMatch =
    /^[a-z][a-z0-9+.-]*:\/\/(?:[^@/]+@)?(\[[^\]]+\]|[^/:]*)(?::(\d+))?(\/.*)?$/i.exec(url);
  if (protoMatch) {
    let host = protoMatch[1] ?? "";
    // Detect IPv6 via the bracketed input form BEFORE stripping brackets,
    // so that when we later re-attach a port we can preserve the
    // `[host]:port` boundary. Without the brackets, `host:2222` is
    // ambiguous with a longer bare IPv6 address like `2001:db8::1:2222`.
    const wasBracketed =
      host.startsWith("[") && host.endsWith("]");
    if (wasBracketed) host = host.slice(1, -1);
    const port = protoMatch[2];
    const repoPath = (protoMatch[3] ?? "").replace(/^\/+/, "");
    const hostPort = port
      ? wasBracketed
        ? `[${host}]:${port}`
        : `${host}:${port}`
      : host;
    // For protocols without a host component (file:///path), fall back to
    // a stable prefix so distinct local paths don't collapse to "/path".
    const prefix = hostPort.length > 0 ? hostPort : "localhost";
    return `${prefix}/${repoPath}`.toLowerCase();
  }

  // scp-like syntax: [user@]host:path. Protocol-prefixed URLs (`scheme://`)
  // are handled above, so the scp branch below guards against them: a
  // matched `host` of `scheme` followed by a path starting with `//` is
  // a protocol URL that fell through and must NOT be parsed here.
  // `user@` is optional — git also accepts userless scp forms like
  // `host:org/repo`. Valid scp paths may start with digits (e.g.
  // `git@host:123/repo.git`), so no numeric guard is needed: port-bearing
  // URLs have the `://` prefix and match the protocol branch above before
  // reaching here.
  //
  // Windows drive letters were filtered above, so single-character SSH
  // host aliases (`h:foo/bar`) are accepted here.
  //
  // Bracketed IPv6 (`[2001:db8::1]`) is supported: the host alternative
  // matches the bracketed literal up to `]` without splitting on internal
  // `:`. Brackets are stripped in the normalised form so the scp and
  // `ssh://` forms of the same IPv6 remote produce identical projectIds.
  const scpMatch =
    /^(?:([^@\s/]+)@)?(\[[^\]]+\]|[^:@\s/]+):(.+)$/.exec(url);
  if (scpMatch) {
    let host = scpMatch[2] ?? "";
    if (host.startsWith("[") && host.endsWith("]")) host = host.slice(1, -1);
    const repoPath = scpMatch[3] ?? "";
    // Reject protocol-like leftovers (e.g. `file:///path` where the scp
    // regex greedily matched `file` as host and `///path` as path).
    if (repoPath.startsWith("//")) {
      return url.toLowerCase();
    }
    return `${host}/${repoPath.replace(/^\/+/, "")}`.toLowerCase();
  }

  // Fallback: use raw lowercased
  return url.toLowerCase();
}

// ──────────────────────────────────────────────────────────────────────────
// Resolver
// ──────────────────────────────────────────────────────────────────────────

export interface ResolveGitContextOptions {
  /** Inject a git invoker (tests). Defaults to spawning real `git`. */
  invoker?: GitInvoker;
  abortSignal?: AbortSignal;
  /** Absolute epoch deadline shared with the extraction lifecycle. */
  deadlineMs?: number;
  /** Injectable clock for deadline tests. */
  now?: () => number;
}

/**
 * Detect the git project + branch for `cwd`.
 *
 * Returns `null` when `cwd` is invalid, outside a worktree, or git is
 * unavailable. Unexpected command failures also resolve to `null`.
 *
 * Caller cancellation and an exhausted deadline reject so lifecycle callers
 * can stop promptly instead of treating an interrupted probe as "not a repo".
 */
export async function resolveGitContext(
  cwd: string,
  options: ResolveGitContextOptions = {},
): Promise<GitContext | null> {
  // Wrap the whole body so the documented "Never throws" contract is
  // enforced. Possible throw sites include:
  //   - `expandTildePath` → `resolveHomeDir()` → `os.homedir()` when HOME
  //     is unset (e.g. minimal containers)
  //   - a custom `options.invoker` that raises instead of returning a
  //     non-zero exitCode
  //   - any future helper added to this chain
  // All of those map to "not in a repo" / `null`.
  try {
    // Validate input: must be a non-empty string.
    if (typeof cwd !== "string" || cwd.length === 0) return null;

    // Expand `~` per CLAUDE.md #17, then require absolute path.
    const expanded = expandTildePath(cwd);
    if (!path.isAbsolute(expanded)) return null;

    const invoker = options.invoker ?? defaultGitInvoker();
    const now = options.now ?? Date.now;
    const invoke = async (probeCwd: string, args: string[]): Promise<GitInvokeResult> => {
      if (options.abortSignal?.aborted) {
        throw options.abortSignal.reason instanceof Error
          ? options.abortSignal.reason
          : abortError("git context resolution aborted");
      }
      const remainingMs =
        options.deadlineMs === undefined ? DEFAULT_GIT_TIMEOUT_MS : options.deadlineMs - now();
      if (remainingMs <= 0) throw abortError("git context resolution deadline exceeded");
      return invoker(probeCwd, args, {
        abortSignal: options.abortSignal,
        timeoutMs: Math.min(DEFAULT_GIT_TIMEOUT_MS, remainingMs),
      });
    };

    // 1. Locate the repo root.
    const topLevel = await invoke(expanded, ["rev-parse", "--show-toplevel"]);
    if (topLevel.exitCode !== 0) return null;
    const rootPath = topLevel.stdout.trim();
    if (!rootPath) return null;

    // 2. Current branch. `--abbrev-ref HEAD` returns `HEAD` in detached
    //    state, which we normalize to `null`. On a fresh `git init` the
    //    HEAD ref is unborn and `--abbrev-ref HEAD` fails, but
    //    `symbolic-ref HEAD` still returns the target branch. Fall back
    //    so newly-initialized repos get a sensible branch name.
    const branchResult = await invoke(rootPath, ["rev-parse", "--abbrev-ref", "HEAD"]);
    let branch: string | null = null;
    if (branchResult.exitCode === 0) {
      const raw = branchResult.stdout.trim();
      branch = raw && raw !== "HEAD" ? raw : null;
    } else {
      const unbornRef = await invoke(rootPath, ["symbolic-ref", "--quiet", "HEAD"]);
      if (unbornRef.exitCode === 0) {
        const raw = unbornRef.stdout.trim();
        const prefix = "refs/heads/";
        if (raw.startsWith(prefix)) {
          const candidate = raw.slice(prefix.length);
          if (candidate) branch = candidate;
        }
      }
    }

    // 3. Origin URL — optional. Used to derive a stable `projectId`.
    const originResult = await invoke(rootPath, ["remote", "get-url", "origin"]);
    let projectId: string;
    if (originResult.exitCode === 0) {
      const normalized = normalizeOriginUrl(originResult.stdout);
      projectId = normalized ? `origin:${stableHash(normalized)}` : `root:${stableHash(rootPath)}`;
    } else {
      projectId = `root:${stableHash(rootPath)}`;
    }

    // 4. Default branch — best effort.
    const headRef = await invoke(rootPath, ["symbolic-ref", "--quiet", "refs/remotes/origin/HEAD"]);
    let defaultBranch: string | null = null;
    if (headRef.exitCode === 0) {
      const raw = headRef.stdout.trim();
      const prefix = "refs/remotes/origin/";
      if (raw.startsWith(prefix)) {
        const candidate = raw.slice(prefix.length);
        if (candidate) defaultBranch = candidate;
      }
    }

    return {
      projectId,
      branch,
      rootPath,
      defaultBranch,
    };
  } catch {
    if (options.abortSignal?.aborted) {
      throw options.abortSignal.reason instanceof Error
        ? options.abortSignal.reason
        : abortError("git context resolution aborted");
    }
    if (options.deadlineMs !== undefined && (options.now ?? Date.now)() >= options.deadlineMs) {
      throw abortError("git context resolution deadline exceeded");
    }
    return null;
  }
}

/**
 * Location interval math (issue #2044).
 *
 * Pure, deterministic helpers over UTC ISO-8601 instants: half-open
 * [start, end) day windows (reusing the DST-correct activity day-window), IANA
 * local-day bucketing, overlap, observation→segment dwell, and dominant-place
 * selection with stable tie-breaking. No IO, no clocks, no randomness.
 */

import { activityDayWindow, isValidActivityDate } from "../activity/digest.js";
import type { LocationObservation, LocationPlace, LocationSegment } from "./types.js";

export function isValidLocationDate(date: string): boolean {
  return isValidActivityDate(date);
}

/** Half-open [start, end) UTC ISO bounds of a local day. */
export function locationDayWindow(date: string, timezone: string): { startUtc: string; endUtc: string } {
  if (!isValidActivityDate(date)) {
    throw new RangeError(`Invalid location date "${date}"; expected a real YYYY-MM-DD day.`);
  }
  return activityDayWindow(date, timezone);
}

function assertFiniteInstant(iso: string, what: string): number {
  const ms = Date.parse(iso);
  if (typeof iso !== "string" || !Number.isFinite(ms)) {
    throw new RangeError(`${what} must be a UTC ISO-8601 instant; got "${String(iso)}"`);
  }
  return ms;
}

/** The IANA local calendar day (YYYY-MM-DD) an instant falls in. */
export function localDayKey(instantUtc: string, timezone: string): string {
  assertFiniteInstant(instantUtc, "instantUtc");
  return new Intl.DateTimeFormat("en-CA", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(new Date(instantUtc));
}

function compareObservations(a: LocationObservation, b: LocationObservation): number {
  if (a.observedAtUtc !== b.observedAtUtc) {
    return a.observedAtUtc < b.observedAtUtc ? -1 : 1;
  }
  // Total comparator (§12): equal-key observations fall back to place id so
  // ordering — and therefore dwell attribution — is deterministic.
  if (a.place.id !== b.place.id) {
    return a.place.id < b.place.id ? -1 : 1;
  }
  return 0;
}

/** Bucket observations into their IANA local days, sorted within each day. */
export function bucketObservationsByDay(
  observations: readonly LocationObservation[],
  timezone: string,
): Map<string, LocationObservation[]> {
  const buckets = new Map<string, LocationObservation[]>();
  for (const observation of observations) {
    assertFiniteInstant(observation.observedAtUtc, "observation observedAtUtc");
    const key = localDayKey(observation.observedAtUtc, timezone);
    const bucket = buckets.get(key);
    if (bucket === undefined) buckets.set(key, [observation]);
    else bucket.push(observation);
  }
  for (const bucket of buckets.values()) bucket.sort(compareObservations);
  return buckets;
}

/** Overlap in ms of two half-open intervals; 0 when disjoint. */
export function intervalOverlapMs(
  a: { startUtc: string; endUtc: string },
  b: { startUtc: string; endUtc: string },
): number {
  const overlap =
    Math.min(Date.parse(a.endUtc), Date.parse(b.endUtc)) - Math.max(Date.parse(a.startUtc), Date.parse(b.startUtc));
  return Math.max(0, overlap);
}

function placeForSegment(place: LocationPlace, retainCoordinates: boolean): LocationPlace {
  if (retainCoordinates || place.latitude === undefined || place.longitude === undefined) {
    return place;
  }
  return {
    id: place.id,
    label: place.label,
    ...(place.kind === undefined ? {} : { kind: place.kind }),
  };
}

/**
 * Derive place-visit segments from a day's observations: each observation
 * covers [its instant, the next observation's instant ∩ window end). The last
 * observation is capped by the window end, so dwell never crosses the day
 * boundary. Out-of-window observations are a provider contract violation and
 * are rejected loudly rather than silently reshaping the day. Coordinates are
 * stripped unless `retainCoordinates` is set.
 */
export function observationSegments(
  observations: readonly LocationObservation[],
  window: { startUtc: string; endUtc: string },
  options: { retainCoordinates: boolean },
): LocationSegment[] {
  const startMs = assertFiniteInstant(window.startUtc, "window startUtc");
  const endMs = assertFiniteInstant(window.endUtc, "window endUtc");
  if (startMs >= endMs) {
    throw new RangeError("location window must satisfy startUtc < endUtc");
  }
  const ordered = [...observations].sort(compareObservations);
  const segments: LocationSegment[] = [];
  for (let index = 0; index < ordered.length; index += 1) {
    const current = ordered[index]!;
    const currentMs = Date.parse(current.observedAtUtc);
    if (currentMs < startMs || currentMs >= endMs) {
      throw new RangeError(
        `location observation at "${current.observedAtUtc}" falls outside the requested [${window.startUtc}, ${window.endUtc}) window`,
      );
    }
    const nextMs =
      index + 1 < ordered.length ? Date.parse(ordered[index + 1]!.observedAtUtc) : endMs;
    const segmentEndMs = Math.min(nextMs, endMs);
    if (currentMs >= segmentEndMs) continue;
    segments.push({
      startUtc: new Date(currentMs).toISOString(),
      endUtc: new Date(segmentEndMs).toISOString(),
      place: placeForSegment(current.place, options.retainCoordinates),
      ...(current.confidence !== undefined ? { confidence: current.confidence } : {}),
    });
  }
  return segments;
}

/** Total time a place was occupied (union of its segment intervals, ms). */
export interface PlaceDuration {
  place: LocationPlace;
  totalMs: number;
  /** Earliest segment start contributing to this place's total. */
  firstStartUtc: string;
}

function unionIntervalMs(segments: readonly LocationSegment[]): number {
  // Merge overlapping [start, end) intervals per place so two providers
  // observing the same visit do not double-count its duration.
  const bounds = segments
    .map((segment) => ({ start: Date.parse(segment.startUtc), end: Date.parse(segment.endUtc) }))
    .sort((a, b) => (a.start !== b.start ? a.start - b.start : a.end - b.end));
  let total = 0;
  let sweepStart: number | null = null;
  let sweepEnd = 0;
  for (const bound of bounds) {
    if (sweepStart === null || bound.start > sweepEnd) {
      if (sweepStart !== null) total += sweepEnd - sweepStart;
      sweepStart = bound.start;
      sweepEnd = bound.end;
    } else if (bound.end > sweepEnd) {
      sweepEnd = bound.end;
    }
  }
  if (sweepStart !== null) total += sweepEnd - sweepStart;
  return total;
}

/** Per-place totals across every segment given (multi-source safe). */
export function placeDurations(segments: readonly LocationSegment[]): PlaceDuration[] {
  const byPlace = new Map<string, { place: LocationPlace; segments: LocationSegment[]; firstStartUtc: string }>();
  for (const segment of segments) {
    const existing = byPlace.get(segment.place.id);
    if (existing === undefined) {
      byPlace.set(segment.place.id, { place: segment.place, segments: [segment], firstStartUtc: segment.startUtc });
      continue;
    }
    existing.segments.push(segment);
    if (segment.startUtc < existing.firstStartUtc) existing.firstStartUtc = segment.startUtc;
    // Two providers may label the same place id differently; keep the
    // lexicographically smallest label so rendering stays deterministic.
    if (segment.place.label < existing.place.label) existing.place = segment.place;
  }
  const durations: PlaceDuration[] = [...byPlace.values()].map((entry) => ({
    place: entry.place,
    totalMs: unionIntervalMs(entry.segments),
    firstStartUtc: entry.firstStartUtc,
  }));
  durations.sort((a, b) => {
    if (a.place.id !== b.place.id) return a.place.id < b.place.id ? -1 : 1;
    return 0;
  });
  return durations;
}

export interface DominantPlaceResult {
  place: LocationPlace;
  totalMs: number;
}

/**
 * The place with the longest total occupancy. Ties are stable and
 * deterministic: earlier first start wins, then the lexicographically smaller
 * place id — never insertion order.
 */
export function dominantPlace(segments: readonly LocationSegment[]): DominantPlaceResult | null {
  const durations = placeDurations(segments);
  let best: PlaceDuration | null = null;
  for (const duration of durations) {
    if (best === null) {
      best = duration;
      continue;
    }
    if (duration.totalMs !== best.totalMs) {
      if (duration.totalMs > best.totalMs) best = duration;
      continue;
    }
    if (duration.firstStartUtc !== best.firstStartUtc) {
      if (duration.firstStartUtc < best.firstStartUtc) best = duration;
      continue;
    }
    if (duration.place.id < best.place.id) best = duration;
  }
  return best === null ? null : { place: best.place, totalMs: best.totalMs };
}

/**
 * Core location matcher (issue #2046) — the ONE place that decides whether a
 * memory or wearable conversation gets provider location context.
 *
 * Pure and deterministic: no IO, no clocks, no randomness. Inputs are UTC
 * ISO-8601 instants and half-open [start, end) intervals everywhere.
 *
 * Rules (issue #2046 / umbrella #2043 decision D):
 * 1. A valid memory interval is required — derived ONLY from the memory's own
 *   bi-temporal frontmatter (`valid_at` / `observedAt` / `invalid_at`), never
 *   from wall-clock time or message order. Untimed memories stay untagged.
 * 2. Intervals longer than 24h describe long-lived facts, not events at a
 *   place; they stay untagged.
 * 3. A place is tagged only when it is DOMINANT (strictly the longest overlap
 *   among candidate places; ties are conflicts and leave the memory untagged)
 *   and meets `minimumOverlapSeconds` and `minimumConfidence`.
 * 4. Only resolved named places participate (`kind` home/work/poi): transit
 *   legs and unnamed visits never tag a memory.
 * 5. No address is ever inferred from text, coordinates, IP, or proximity —
 *   only provider-supplied place metadata is echoed, and coordinates only
 *   when `retainCoordinates` is enabled.
 *
 * Provider-owned metadata contract: the tag is `location:<stable-place-slug>`
 * and the opaque provider place id lives in structured attributes. Every
 * field the matcher writes is provider-owned; a memory that carries
 * location-ish metadata WITHOUT the `locationSource` marker is treated as
 * manual/user-authored and is never touched.
 */

import { TAG_LIMITS, STRUCTURED_ATTRIBUTE_LIMITS } from "../write-envelope.js";
import type { LocationPlace, LocationSegment } from "./types.js";

/** Maximum memory span eligible for location tagging. */
export const LOCATION_MATCH_MAX_MEMORY_SPAN_MS = 24 * 60 * 60 * 1000;

/** Prefix of provider-owned location tags. */
export const LOCATION_TAG_PREFIX = "location:";

/** Structured-attribute keys owned by the tagging pipeline (never manual). */
export const LOCATION_ATTRIBUTE_KEYS = [
  "locationSource",
  "locationPlaceId",
  "locationPlace",
  "locationConfidence",
  "locationVisitStart",
  "locationVisitEnd",
  "locationLatitude",
  "locationLongitude",
] as const;

/** Place kinds eligible for tagging: resolved, named places only. */
const TAGGABLE_PLACE_KINDS: Record<string, true> = { home: true, work: true, poi: true };

export interface LocationTagPolicy {
  minimumOverlapSeconds: number;
  minimumConfidence: number;
  retainCoordinates: boolean;
}

/** The memory side of a match: a half-open interval, or a single instant. */
export type MemoryLocationWindow =
  | { kind: "interval"; startUtc: string; endUtc: string }
  | { kind: "instant"; atUtc: string };

/** Why a window was rejected before matching. */
export type WindowRejectReason = "untimed" | "span-too-long";

export interface WindowResult {
  window?: MemoryLocationWindow;
  /** Local days (YYYY-MM-DD in the tag policy timezone) the window touches. */
  days?: string[];
  rejected?: WindowRejectReason;
}

/**
 * Derive the match window from a memory's own frontmatter. `validAt` (the
 * event start; assumed copies carry the ingestion anchor) opens the window;
 * `invalid_at` closes it. An end-only memory (no start bound) is untimed.
 */
export function memoryLocationWindow(
  frontmatter: { valid_at?: string; observedAt?: string; invalid_at?: string },
  localDay: (instantUtc: string) => string,
): WindowResult {
  const start = frontmatter.valid_at ?? frontmatter.observedAt;
  if (start === undefined || Number.isNaN(Date.parse(start))) {
    return { rejected: "untimed" };
  }
  const end = frontmatter.invalid_at;
  if (end === undefined || Number.isNaN(Date.parse(end)) || Date.parse(end) <= Date.parse(start)) {
    return { window: { kind: "instant", atUtc: start }, days: [localDay(start)] };
  }
  if (Date.parse(end) - Date.parse(start) > LOCATION_MATCH_MAX_MEMORY_SPAN_MS) {
    return { rejected: "span-too-long" };
  }
  // The interval is half-open [start, end): its last instant is end-1ms, so a
  // memory ending exactly at local midnight never touches the next day.
  const lastInstant = new Date(Date.parse(end) - 1).toISOString();
  const days = [localDay(start)];
  const endDay = localDay(lastInstant);
  if (endDay !== days[0]) days.push(endDay);
  return { window: { kind: "interval", startUtc: start, endUtc: end }, days };
}

/** One source's segments for a day, keyed by the configured source id. */
export interface LocationSourceSegments {
  sourceId: string;
  segments: LocationSegment[];
}

export interface LocationMatch {
  sourceId: string;
  place: LocationPlace;
  /** Overlap (ms) with the window — interval mode; see `visitMs` otherwise. */
  overlapMs: number;
  /** Total dwell (ms) of the dominant place inside the window's day(s). */
  visitMs: number;
  /** Minimum contributing segment confidence, when any source reported one. */
  confidence?: number;
  /** Envelope [start, end) of the segments that produced the match. */
  visitStartUtc: string;
  visitEndUtc: string;
}

export type MatchOutcome =
  | { status: "matched"; match: LocationMatch }
  | { status: "unmatched"; reason: "no-overlap" | "ambiguous" | "below-minimum-overlap" | "below-minimum-confidence" };

interface PlaceAccumulator {
  sourceId: string;
  place: LocationPlace;
  overlapMs: number;
  visitMs: number;
  confidence: number | undefined;
  startUtc: string;
  endUtc: string;
}

function overlapMsOf(
  window: MemoryLocationWindow,
  segment: { startUtc: string; endUtc: string },
): number {
  if (window.kind === "instant") {
    const at = Date.parse(window.atUtc);
    return at >= Date.parse(segment.startUtc) && at < Date.parse(segment.endUtc) ? 1 : 0;
  }
  return Math.max(
    0,
    Math.min(Date.parse(window.endUtc), Date.parse(segment.endUtc)) -
      Math.max(Date.parse(window.startUtc), Date.parse(segment.startUtc)),
  );
}

/**
 * The dominant qualifying place for a window, across every source's
 * segments. Deterministic: strict overlap comparison, ties (conflicts) are
 * rejected, and equal-place contributions merge across sources.
 */
export function matchDominantPlace(
  window: MemoryLocationWindow,
  sources: readonly LocationSourceSegments[],
  policy: LocationTagPolicy,
): MatchOutcome {
  const byPlace = new Map<string, PlaceAccumulator>();
  for (const source of sources) {
    for (const segment of source.segments) {
      if (TAGGABLE_PLACE_KINDS[segment.place.kind ?? ""] !== true) continue;
      const overlap = overlapMsOf(window, segment);
      if (overlap <= 0) continue;
      const duration = Date.parse(segment.endUtc) - Date.parse(segment.startUtc);
      const existing = byPlace.get(segment.place.id);
      if (existing === undefined) {
        byPlace.set(segment.place.id, {
          sourceId: source.sourceId,
          place: segment.place,
          overlapMs: overlap,
          visitMs: duration,
          confidence: segment.confidence,
          startUtc: segment.startUtc,
          endUtc: segment.endUtc,
        });
        continue;
      }
      // Same place from another source (or a revisit): accumulate.
      existing.overlapMs += overlap;
      existing.visitMs += duration;
      existing.confidence =
        existing.confidence === undefined
          ? segment.confidence
          : segment.confidence === undefined
            ? existing.confidence
            : Math.min(existing.confidence, segment.confidence);
      if (segment.startUtc < existing.startUtc) existing.startUtc = segment.startUtc;
      if (segment.endUtc > existing.endUtc) existing.endUtc = segment.endUtc;
    }
  }
  if (byPlace.size === 0) return { status: "unmatched", reason: "no-overlap" };

  let best: PlaceAccumulator | null = null;
  let tie = false;
  for (const candidate of byPlace.values()) {
    if (best === null || candidate.overlapMs > best.overlapMs) {
      best = candidate;
      tie = false;
      continue;
    }
    if (candidate.overlapMs === best.overlapMs) tie = true;
  }
  if (best === null || tie) return { status: "unmatched", reason: "ambiguous" };

  const overlapForThreshold = window.kind === "instant" ? best.visitMs : best.overlapMs;
  if (policy.minimumOverlapSeconds > 0 && overlapForThreshold < policy.minimumOverlapSeconds * 1000) {
    return { status: "unmatched", reason: "below-minimum-overlap" };
  }
  if (best.confidence !== undefined && best.confidence < policy.minimumConfidence) {
    return { status: "unmatched", reason: "below-minimum-confidence" };
  }
  return {
    status: "matched",
    match: {
      sourceId: best.sourceId,
      place: best.place,
      overlapMs: best.overlapMs,
      visitMs: best.visitMs,
      ...(best.confidence !== undefined ? { confidence: best.confidence } : {}),
      visitStartUtc: best.startUtc,
      visitEndUtc: best.endUtc,
    },
  };
}

/** Deterministic tag slug for a provider place id (`reitti:place:7` → `reitti-place-7`). */
export function locationTagSlug(placeId: string): string {
  const slug = placeId
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    // The collapse above leaves at most one dash at each edge, so single-char
    // strips are complete. The old /^-+|-+$/ alternation backtracked
    // quadratically on unsanitized dash runs (CodeQL js/polynomial-redos);
    // single-character anchors are linear.
    .replace(/^-/, "")
    .replace(/-$/, "");
  return slug.slice(0, TAG_LIMITS.maxTagLength - LOCATION_TAG_PREFIX.length);
}

/** The provider-owned tag for a matched place. */
export function locationTagForPlace(placeId: string): string {
  return `${LOCATION_TAG_PREFIX}${locationTagSlug(placeId)}`;
}

function boundedAttributeValue(value: string): string {
  return value.slice(0, STRUCTURED_ATTRIBUTE_LIMITS.maxValueLength);
}

/** Provider-owned structured attributes describing a match. */
export function locationAttributesForMatch(
  match: LocationMatch,
  policy: LocationTagPolicy,
): Record<string, string> {
  const attributes: Record<string, string> = {
    locationSource: match.sourceId,
    locationPlaceId: boundedAttributeValue(match.place.id),
    locationPlace: boundedAttributeValue(match.place.label),
    ...(match.confidence !== undefined ? { locationConfidence: match.confidence.toFixed(3) } : {}),
    locationVisitStart: match.visitStartUtc,
    locationVisitEnd: match.visitEndUtc,
  };
  if (policy.retainCoordinates && match.place.latitude !== undefined && match.place.longitude !== undefined) {
    attributes.locationLatitude = String(match.place.latitude);
    attributes.locationLongitude = String(match.place.longitude);
  }
  return attributes;
}

export interface LocationUpdatePlan {
  /** Patch for `writeMemoryFrontmatter`; absent when nothing changes. */
  patch?: { tags: string[]; structuredAttributes: Record<string, string> };
  /** Outcome for reporting. */
  outcome:
    | "tagged"
    | "updated"
    | "removed"
    | "unchanged"
    | "manual-metadata"
    | "unmatched"
    | "untimed"
    | "span-too-long";
}

function frontmatterHasLocationMetadata(
  frontmatter: { tags?: string[]; structuredAttributes?: Record<string, string> },
): boolean {
  if ((frontmatter.tags ?? []).some((tag) => tag.startsWith(LOCATION_TAG_PREFIX))) return true;
  return Object.keys(frontmatter.structuredAttributes ?? {}).some((key) =>
    (LOCATION_ATTRIBUTE_KEYS as readonly string[]).includes(key),
  );
}

function isProviderOwned(frontmatter: { structuredAttributes?: Record<string, string> }): boolean {
  const source = frontmatter.structuredAttributes?.locationSource;
  return typeof source === "string" && source.length > 0;
}

/**
 * Plan the provider-owned update for one memory: a match adds/replaces ONLY
 * provider-owned fields; a lost match removes them (corrected observations);
 * manual location metadata (no `locationSource` marker) always wins and is
 * never touched. Unrelated tags and attributes survive every path.
 */
export function planLocationUpdate(
  frontmatter: { tags?: string[]; structuredAttributes?: Record<string, string> },
  outcome: MatchOutcome,
  policy: LocationTagPolicy,
): LocationUpdatePlan {
  if (frontmatterHasLocationMetadata(frontmatter) && !isProviderOwned(frontmatter)) {
    return { outcome: "manual-metadata" };
  }
  const tags = [...(frontmatter.tags ?? [])];
  const attributes = { ...(frontmatter.structuredAttributes ?? {}) };
  const providerTagIndex = tags.findIndex((tag) => tag.startsWith(LOCATION_TAG_PREFIX));
  const stripProviderFields = (): void => {
    if (providerTagIndex >= 0) tags.splice(providerTagIndex, 1);
    for (const key of LOCATION_ATTRIBUTE_KEYS) delete attributes[key];
  };

  if (outcome.status !== "matched") {
    if (!isProviderOwned(frontmatter)) return { outcome: "unmatched" };
    if (providerTagIndex < 0 && !("locationPlaceId" in attributes)) {
      return { outcome: "unchanged" };
    }
    stripProviderFields();
    return { patch: { tags, structuredAttributes: attributes }, outcome: "removed" };
  }

  const desiredTag = locationTagForPlace(outcome.match.place.id);
  const desiredAttributes = locationAttributesForMatch(outcome.match, policy);
  if (tags.length >= TAG_LIMITS.maxTags && providerTagIndex < 0) {
    // Full tag budget with no provider slot to reuse — leave the memory alone.
    return { outcome: "unchanged" };
  }
  const alreadyCurrent =
    providerTagIndex >= 0 &&
    tags[providerTagIndex] === desiredTag &&
    LOCATION_ATTRIBUTE_KEYS.every((key) => {
      const want = desiredAttributes[key];
      const have = attributes[key];
      return want === undefined ? have === undefined : have === want;
    });
  if (alreadyCurrent) return { outcome: "unchanged" };

  if (providerTagIndex >= 0) tags[providerTagIndex] = desiredTag;
  else tags.push(desiredTag);
  for (const key of LOCATION_ATTRIBUTE_KEYS) delete attributes[key];
  Object.assign(attributes, desiredAttributes);
  const wasProviderOwned = isProviderOwned(frontmatter);
  return {
    patch: { tags, structuredAttributes: attributes },
    outcome: wasProviderOwned ? "updated" : "tagged",
  };
}

/**
 * Location day-file + sync-state store (issue #2044).
 *
 * Day documents live at `<memoryDir>/locations/<YYYY-MM-DD>.md` — OUTSIDE the
 * memory scan roots (facts/, entities/, …) so raw location history never
 * surfaces as a memory in recall or governance passes, and INSIDE the QMD
 * collection root so the markdown stays full-text searchable once an index
 * update runs. Per-source sync state lives at
 * `<memoryDir>/state/locations/sync.json` and is written only after the day
 * document is durable (see pipeline.ts).
 *
 * Both writes are atomic (temp file + rename) and containment-checked: a
 * symlinked `locations/` root or day file is rejected even when it resolves
 * inside the memory dir (AGENTS.md pattern #3), and a path that escapes the
 * memory dir is refused outright.
 */

import { createHash } from "node:crypto";
import { lstat, mkdir, readFile, readdir, realpath } from "node:fs/promises";
import path from "node:path";

import { writeFileAtomically } from "../maintenance/atomic-file.js";
import { pathIsInside } from "../utils/path-containment.js";
import { isErrnoCode } from "../utils/errno.js";
import { isValidLocationDate, placeDurations } from "./intervals.js";
import type { LocationSegment } from "./types.js";

export const LOCATIONS_DIR_NAME = "locations";
export const LOCATION_DAY_KIND = "location-day";
export const LOCATION_DAY_FORMAT_VERSION = 1;

/** Cap on remembered day payloads per source (~3 months of days). */
const MAX_TRACKED_LOCATION_DAYS = 90;

const DAY_FILE_NAME_PATTERN = /^\d{4}-\d{2}-\d{2}\.md$/;

// Serializes state load→mutate→save sections per state file so two sources
// syncing concurrently cannot lose-update each other's entries.
const stateLocks = new Map<string, Promise<unknown>>();

function withStateLock<T>(key: string, fn: () => Promise<T>): Promise<T> {
  const prior = stateLocks.get(key) ?? Promise.resolve();
  const next = prior.then(fn, fn);
  const tail = next.then(
    () => undefined,
    () => undefined,
  );
  stateLocks.set(key, tail);
  void tail.then(() => {
    if (stateLocks.get(key) === tail) stateLocks.delete(key);
  });
  return next;
}

export function locationDayFilePath(memoryDir: string, date: string): string {
  if (!isValidLocationDate(date)) {
    // Never interpolate an unvalidated date into a filesystem path (a `../`
    // would escape <memoryDir>/locations/). Reject loudly.
    throw new RangeError(`Invalid location date "${date}"; expected a real YYYY-MM-DD day.`);
  }
  return path.join(memoryDir, LOCATIONS_DIR_NAME, `${date}.md`);
}

export function locationSyncStateFilePath(memoryDir: string): string {
  return path.join(memoryDir, "state", "locations", "sync.json");
}

/** A source's derived day payload, kept in sync state for multi-source merges. */
export interface LocationSourceDayPayload {
  observationCount: number;
  segments: LocationSegment[];
  providerDisplayName?: string;
}

export interface LocationSourceSyncState {
  lastSyncedAtUtc?: string;
  days?: Record<string, LocationSourceDayPayload>;
}

export interface LocationSyncStateFile {
  version: 1;
  sources: Record<string, LocationSourceSyncState>;
}

export function emptyLocationSyncState(): LocationSyncStateFile {
  return { version: 1, sources: {} };
}

export async function loadLocationSyncState(memoryDir: string): Promise<LocationSyncStateFile> {
  let raw: string;
  try {
    raw = await readFile(locationSyncStateFilePath(memoryDir), "utf-8");
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return emptyLocationSyncState();
    throw err;
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    // A corrupt state file must not brick syncing forever; treat it as a cold
    // start. The worst case is re-syncing days already on disk, and the day
    // file's contentHash makes that rewrite idempotent.
    return emptyLocationSyncState();
  }
  if (
    typeof parsed !== "object" ||
    parsed === null ||
    Array.isArray(parsed) ||
    typeof (parsed as LocationSyncStateFile).sources !== "object" ||
    (parsed as LocationSyncStateFile).sources === null
  ) {
    return emptyLocationSyncState();
  }
  return { version: 1, sources: (parsed as LocationSyncStateFile).sources };
}

export async function saveLocationSyncState(
  memoryDir: string,
  state: LocationSyncStateFile,
): Promise<void> {
  await mkdir(path.dirname(locationSyncStateFilePath(memoryDir)), { recursive: true, mode: 0o700 });
  await writeFileAtomically(
    locationSyncStateFilePath(memoryDir),
    `${JSON.stringify(state, null, 2)}\n`,
  );
}

function pruneSourceDays(source: LocationSourceSyncState): void {
  const days = source.days;
  if (days === undefined) return;
  const keys = Object.keys(days).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  for (const key of keys.slice(0, Math.max(0, keys.length - MAX_TRACKED_LOCATION_DAYS))) {
    delete days[key];
  }
}

/**
 * Record one source's completed day sync. Runs the whole read-modify-write
 * under the per-directory state lock so concurrent sources cannot clobber
 * each other, and prunes day payloads beyond the retention cap.
 */
export async function updateLocationSourceDay(
  memoryDir: string,
  sourceId: string,
  date: string,
  payload: LocationSourceDayPayload,
  completedAtUtc: string,
): Promise<LocationSyncStateFile> {
  if (!isValidLocationDate(date)) {
    throw new RangeError(`Invalid location date "${date}"; expected a real YYYY-MM-DD day.`);
  }
  return withStateLock(locationSyncStateFilePath(memoryDir), async () => {
    const state = await loadLocationSyncState(memoryDir);
    const source = state.sources[sourceId] ?? {};
    const days = source.days ?? {};
    days[date] = payload;
    source.days = days;
    source.lastSyncedAtUtc = completedAtUtc;
    state.sources[sourceId] = source;
    for (const candidate of Object.values(state.sources)) pruneSourceDays(candidate);
    await saveLocationSyncState(memoryDir, state);
    return state;
  });
}
/** Frontmatter persisted on a rendered day document. */
export interface LocationDayMeta {
  kind: typeof LOCATION_DAY_KIND;
  date: string;
  timezone: string;
  formatVersion: number;
  sources: string[];
  observationCount: number;
  /** SHA-256 of the rendered body (rebuild idempotency). */
  contentHash: string;
}

/** A parsed day document (frontmatter + rendered body). */
export interface LocationDayDocument {
  meta: LocationDayMeta;
  body: string;
}

/** The per-source view a day document is composed from. */
export interface LocationDaySourceEntry extends LocationSourceDayPayload {
  /** Provider display name for the timeline heading; falls back to the id. */
  providerDisplayName?: string;
}

export function hashLocationBody(body: string): string {
  return createHash("sha256").update(body, "utf8").digest("hex");
}

function clockHhMm(iso: string, timezone: string): string {
  return new Intl.DateTimeFormat("en-GB", {
    timeZone: timezone,
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  }).format(new Date(iso));
}

function formatDuration(ms: number): string {
  const totalMinutes = Math.round(ms / 60_000);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  if (hours <= 0) return `${minutes}m`;
  return `${hours}h ${String(minutes).padStart(2, "0")}m`;
}

/** Collapse whitespace and strip markdown emphasis/backticks from a label. */
function safeLabel(label: string): string {
  return label.replace(/\s+/g, " ").replace(/[`*_]/g, "").trim();
}

function formatPlaceLabel(segment: LocationSegment): string {
  const label = safeLabel(segment.place.label);
  return segment.place.kind === undefined ? label : `${label} (${segment.place.kind})`;
}

function formatCoordinates(segment: LocationSegment): string {
  if (segment.place.latitude === undefined || segment.place.longitude === undefined) return "";
  return ` @ ${segment.place.latitude.toFixed(4)},${segment.place.longitude.toFixed(4)}`;
}

export function composeLocationDayBody(
  date: string,
  timezone: string,
  sources: Record<string, LocationDaySourceEntry>,
): string {
  const lines: string[] = [`# Location day — ${date} (${timezone})`, ""];
  const allSegments: LocationSegment[] = [];
  let observationCount = 0;
  for (const entry of Object.values(sources)) {
    allSegments.push(...entry.segments);
    observationCount += entry.observationCount;
  }

  lines.push("## Summary", "");
  if (observationCount === 0) {
    lines.push("No location observations recorded.", "");
  } else {
    const durations = placeDurations(allSegments).sort((a, b) => b.totalMs - a.totalMs);
    lines.push(
      `- Places visited: ${durations.length}`,
      ...durations.map(
        (duration) => `- ${safeLabel(duration.place.label)}: ${formatDuration(duration.totalMs)}`,
      ),
      "",
    );
  }

  const sourceIds = Object.keys(sources).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  for (const sourceId of sourceIds) {
    const entry = sources[sourceId]!;
    lines.push(`## Timeline — ${safeLabel(entry.providerDisplayName ?? sourceId)}`, "");
    if (entry.segments.length === 0) {
      lines.push("No observations.", "");
      continue;
    }
    for (const segment of entry.segments) {
      lines.push(
        `- ${clockHhMm(segment.startUtc, timezone)}–${clockHhMm(segment.endUtc, timezone)} — ${formatPlaceLabel(segment)}${formatCoordinates(segment)}`,
      );
    }
    lines.push("");
  }
  return `${lines.join("\n").trimEnd()}\n`;
}

export function composeLocationDayMeta(
  date: string,
  timezone: string,
  sources: Record<string, LocationDaySourceEntry>,
  body: string,
): LocationDayMeta {
  let observationCount = 0;
  for (const entry of Object.values(sources)) observationCount += entry.observationCount;
  return {
    kind: LOCATION_DAY_KIND,
    date,
    timezone,
    formatVersion: LOCATION_DAY_FORMAT_VERSION,
    sources: Object.keys(sources).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)),
    observationCount,
    contentHash: hashLocationBody(body),
  };
}

function frontmatterScalar(key: string, value: string | number): string {
  return `${key}: ${typeof value === "number" ? value : JSON.stringify(value)}`;
}

function frontmatterList(key: string, values: readonly string[]): string[] {
  if (values.length === 0) return [`${key}: []`];
  const lines = [`${key}:`];
  for (const value of values) lines.push(`  - ${JSON.stringify(value)}`);
  return lines;
}

export function serializeLocationDay(meta: LocationDayMeta, body: string): string {
  const lines: string[] = ["---"];
  lines.push(frontmatterScalar("kind", meta.kind));
  lines.push(frontmatterScalar("date", meta.date));
  lines.push(frontmatterScalar("timezone", meta.timezone));
  lines.push(frontmatterScalar("formatVersion", meta.formatVersion));
  lines.push(...frontmatterList("sources", meta.sources));
  lines.push(frontmatterScalar("observationCount", meta.observationCount));
  lines.push(frontmatterScalar("contentHash", meta.contentHash));
  lines.push("---", "", body);
  return lines.join("\n");
}

function parseScalar(raw: string): string {
  try {
    const parsed = JSON.parse(raw);
    return typeof parsed === "string" ? parsed : raw;
  } catch {
    return raw;
  }
}

/** A day document's frontmatter, parsed for idempotency checks and status. */
export interface LocationDaySummary {
  date: string;
  timezone: string;
  sources: string[];
  observationCount: number;
  contentHash: string;
}

/**
 * Parse a day document's frontmatter. Returns null when the content is not a
 * location day document (wrong kind, missing frontmatter) so callers can
 * distinguish a foreign file from a corrupt one.
 */
export function parseLocationDaySummary(raw: string): LocationDaySummary | null {
  if (!raw.startsWith("---\n")) return null;
  const closeIndex = raw.indexOf("\n---\n", 4);
  if (closeIndex === -1) return null;
  const scalars: Record<string, string> = {};
  const lists: Record<string, string[]> = {};
  let currentList: string | null = null;
  for (const line of raw.slice(4, closeIndex).split("\n")) {
    const listItem = /^ {2}- (.*)$/.exec(line);
    if (listItem !== null && currentList !== null) {
      lists[currentList]!.push(parseScalar(listItem[1]!));
      continue;
    }
    currentList = null;
    const separator = line.indexOf(":");
    if (separator === -1) continue;
    const key = line.slice(0, separator);
    const value = line.slice(separator + 1).trim();
    if (value === "" || value === "[]") {
      lists[key] = [];
      currentList = key;
      continue;
    }
    if (value.startsWith("[")) {
      lists[key] = [parseScalar(value)];
      currentList = key;
      continue;
    }
    scalars[key] = value;
  }
  if (scalars.kind === undefined || parseScalar(scalars.kind) !== LOCATION_DAY_KIND) return null;
  if (scalars.date === undefined || scalars.contentHash === undefined) return null;
  return {
    date: parseScalar(scalars.date),
    timezone: scalars.timezone === undefined ? "UTC" : parseScalar(scalars.timezone),
    sources: lists.sources ?? [],
    observationCount: scalars.observationCount === undefined ? 0 : Number(scalars.observationCount) || 0,
    contentHash: parseScalar(scalars.contentHash),
  };
}

// ── Containment-checked day-file IO ─────────────────────────────────────────

async function assertNotSymlink(target: string, kind: "directory" | "day file"): Promise<void> {
  let stat: { isSymbolicLink(): boolean };
  try {
    stat = await lstat(target);
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return;
    throw err;
  }
  if (stat.isSymbolicLink()) {
    throw new Error(
      `locations ${kind} '${path.basename(target)}' is a symbolic link — refusing to follow it even when it resolves inside the memory dir (AGENTS.md pattern #3)`,
    );
  }
}

async function assertNoEscape(rootReal: string, candidate: string): Promise<void> {
  let candidateReal: string;
  try {
    candidateReal = await realpath(candidate);
  } catch {
    return;
  }
  if (!pathIsInside(rootReal, candidateReal)) {
    throw new Error(
      "location day path resolves outside the memory dir — refusing to follow a symlink/traversal (AGENTS.md pattern #3)",
    );
  }
}

async function assertDayPathContained(memoryDir: string, targetPath: string): Promise<void> {
  let rootReal: string;
  try {
    rootReal = await realpath(memoryDir);
  } catch {
    rootReal = path.resolve(memoryDir);
  }
  const locationsDir = path.join(memoryDir, LOCATIONS_DIR_NAME);
  await assertNoEscape(rootReal, locationsDir);
  await assertNoEscape(rootReal, targetPath);
  // Reject a symlinked locations root or day file outright — even when the
  // link resolves inside the memory dir (aliasing / tampering) — before IO.
  await assertNotSymlink(locationsDir, "directory");
  await assertNotSymlink(targetPath, "day file");
}

/**
 * Idempotently persist a day document: skip the write when the on-disk
 * contentHash already matches. The write is atomic and containment-checked;
 * the caller (pipeline) advances sync state only after this resolves.
 */
export async function writeLocationDay(
  memoryDir: string,
  date: string,
  serialized: string,
): Promise<boolean> {
  const target = locationDayFilePath(memoryDir, date);
  await assertDayPathContained(memoryDir, target);
  try {
    if ((await readFile(target, "utf-8")) === serialized) return false;
  } catch (err) {
    if (!isErrnoCode(err, "ENOENT")) throw err;
  }
  await mkdir(path.dirname(target), { recursive: true, mode: 0o700 });
  await writeFileAtomically(target, serialized);
  return true;
}

/** Read a stored day document's raw markdown; null when absent. */
export async function readLocationDay(memoryDir: string, date: string): Promise<string | null> {
  const target = locationDayFilePath(memoryDir, date);
  await assertDayPathContained(memoryDir, target);
  try {
    return await readFile(target, "utf-8");
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return null;
    throw err;
  }
}

/** List dates that have a stored day document, newest first. */
export async function listLocationDayDates(memoryDir: string): Promise<string[]> {
  const locationsDir = path.join(memoryDir, LOCATIONS_DIR_NAME);
  await assertDayPathContained(memoryDir, locationsDir);
  let entries: string[];
  try {
    entries = await readdir(locationsDir);
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return [];
    throw err;
  }
  const dates = entries
    .filter((entry) => DAY_FILE_NAME_PATTERN.test(entry))
    .map((entry) => entry.slice(0, -3));
  dates.sort((a, b) => (a > b ? -1 : a < b ? 1 : 0));
  return dates;
}

import type {
  CompressionGuidelineOptimizerActionSummary,
  CompressionGuidelineOptimizerEventCounts,
  CompressionGuidelineOptimizerRuleUpdate,
  CompressionGuidelineOptimizerState,
  MemoryActionEvent,
  MemoryActionOutcome,
  MemoryActionType,
} from "./types.js";

export interface CompressionGuidelineCandidate {
  generatedAt: string;
  sourceWindow: {
    from: string;
    to: string;
  };
  eventCounts: CompressionGuidelineOptimizerEventCounts;
  actionSummaries: CompressionGuidelineOptimizerActionSummary[];
  ruleUpdates: CompressionGuidelineOptimizerRuleUpdate[];
  guidelineVersion: number;
  optimizerVersion: number;
}

export interface CompressionSemanticRuleRefinement {
  action: MemoryActionType;
  delta?: number;
  confidence?: "low" | "medium" | "high";
  note?: string;
}

export interface CompressionSemanticRefinementResult {
  updates: CompressionSemanticRuleRefinement[];
}

export interface CompressionSemanticRefinementOptions {
  enabled: boolean;
  timeoutMs: number;
  runRefinement?: (
    candidate: CompressionGuidelineCandidate,
  ) => Promise<CompressionSemanticRefinementResult | null>;
}

const MAX_DELTA = 0.15;
const SPARSE_SAMPLE = 5;

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function parseRecallQuality(reason: string | undefined): "good" | "poor" | "unknown" {
  if (!reason) return "unknown";
  const text = reason.toLowerCase();
  if (/\bunresolved\b|\b(?:not|never|no|without)\s+(?:yet\s+)?resolved\b/.test(text)) {
    return "poor";
  }
  if (/(recall[_\s-]?good|quality[:=]\s*(good|high)|\bimprov(?:e|ed|ing)\b|\bresolved\b)/.test(text)) {
    return "good";
  }
  if (/(recall[_\s-]?poor|quality[:=]\s*(poor|low)|\bdegrad(?:e|ed|ing)\b|\bmiss(?:ed|ing)\b|\birrelevant\b)/.test(text)) {
    return "poor";
  }
  return "unknown";
}

function nextGuidelineVersion(previousState: CompressionGuidelineOptimizerState | null): number {
  if (!previousState) return 1;
  return Math.max(1, previousState.guidelineVersion + 1);
}

function nextOptimizerVersion(previousState: CompressionGuidelineOptimizerState | null): number {
  if (!previousState) return 1;
  return Math.max(1, previousState.version + 1);
}

function roundDelta(value: number): number {
  return Math.round(value * 1000) / 1000;
}

function confidenceForDelta(delta: number): "low" | "medium" | "high" {
  const magnitude = Math.abs(delta);
  return magnitude >= 0.09 ? "high" : magnitude >= 0.04 ? "medium" : "low";
}

function directionForDelta(delta: number): "increase" | "decrease" | "hold" {
  return delta > 0 ? "increase" : delta < 0 ? "decrease" : "hold";
}

export function computeCompressionGuidelineCandidate(
  events: MemoryActionEvent[],
  options: {
    generatedAtIso?: string;
    previousState?: CompressionGuidelineOptimizerState | null;
  } = {},
): CompressionGuidelineCandidate {
  const generatedAt = options.generatedAtIso ?? new Date().toISOString();
  const previousState = options.previousState ?? null;
  const effectiveEvents = events.filter((event) => event.dryRun !== true);
  const totalCounts: CompressionGuidelineOptimizerEventCounts = {
    total: effectiveEvents.length,
    applied: 0,
    skipped: 0,
    failed: 0,
  };

  const actionMap = new Map<MemoryActionType, CompressionGuidelineOptimizerActionSummary>();
  let windowFrom = effectiveEvents[0]?.timestamp ?? generatedAt;
  let windowTo = effectiveEvents[0]?.timestamp ?? generatedAt;

  for (const event of effectiveEvents) {
    if (event.timestamp < windowFrom) windowFrom = event.timestamp;
    if (event.timestamp > windowTo) windowTo = event.timestamp;
    totalCounts[event.outcome] += 1;

    let summary = actionMap.get(event.action);
    if (!summary) {
      summary = {
        action: event.action,
        total: 0,
        outcomes: { applied: 0, skipped: 0, failed: 0 },
        quality: { good: 0, poor: 0, unknown: 0 },
      };
      actionMap.set(event.action, summary);
    }

    summary.total += 1;
    summary.outcomes[event.outcome] += 1;
    const quality = parseRecallQuality(event.reason);
    summary.quality[quality] += 1;
  }

  const actionSummaries = [...actionMap.values()].sort((a, b) => {
    if (b.total !== a.total) return b.total - a.total;
    return a.action.localeCompare(b.action);
  });

  const ruleUpdates = actionSummaries.map((summary): CompressionGuidelineOptimizerRuleUpdate => {
    const notes: string[] = [];
    if (summary.total < SPARSE_SAMPLE) {
      notes.push("Sparse sample size; holding baseline policy.");
      return {
        action: summary.action,
        delta: 0,
        direction: "hold",
        confidence: "low",
        notes,
      };
    }

    const successRate = summary.outcomes.applied / summary.total;
    const failureRate = summary.outcomes.failed / summary.total;
    const qualitySeen = summary.quality.good + summary.quality.poor;
    const qualitySignal = qualitySeen > 0
      ? (summary.quality.good - summary.quality.poor) / qualitySeen
      : 0;
    const rawDelta = clamp((successRate - failureRate) * 0.12 + qualitySignal * 0.06, -MAX_DELTA, MAX_DELTA);
    const delta = roundDelta(rawDelta);

    const direction = directionForDelta(delta);
    if (direction === "decrease" && summary.outcomes.failed > summary.outcomes.applied) {
      notes.push("Failures exceed applied outcomes; conservative down-adjustment.");
    } else if (direction === "increase" && summary.quality.good > summary.quality.poor) {
      notes.push("Good recall quality markers support this action.");
    } else if (direction === "decrease" && summary.quality.poor > summary.quality.good) {
      notes.push("Poor recall quality markers exceed good markers.");
    } else {
      notes.push("Outcomes are stable; keep bounded adjustments.");
    }

    const confidence = confidenceForDelta(delta);
    return {
      action: summary.action,
      delta,
      direction,
      confidence,
      notes,
    };
  });

  return {
    generatedAt,
    sourceWindow: {
      from: effectiveEvents.length > 0 ? windowFrom : generatedAt,
      to: effectiveEvents.length > 0 ? windowTo : generatedAt,
    },
    eventCounts: totalCounts,
    actionSummaries,
    ruleUpdates,
    guidelineVersion: nextGuidelineVersion(previousState),
    optimizerVersion: nextOptimizerVersion(previousState),
  };
}

export async function refineCompressionGuidelineCandidateSemantically(
  baseline: CompressionGuidelineCandidate,
  options: CompressionSemanticRefinementOptions,
): Promise<CompressionGuidelineCandidate> {
  if (!options.enabled) return baseline;
  if (typeof options.runRefinement !== "function") return baseline;

  const timeoutMs = Math.max(1, Math.floor(options.timeoutMs));
  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  const timeout = new Promise<CompressionSemanticRefinementResult | null>((resolve) => {
    timeoutId = setTimeout(() => resolve(null), timeoutMs);
  });

  const refinementPromise = options.runRefinement(baseline).catch(() => null);

  let refinement: CompressionSemanticRefinementResult | null = null;
  try {
    refinement = await Promise.race([refinementPromise, timeout]);
  } catch {
    if (timeoutId) clearTimeout(timeoutId);
    return baseline;
  }
  if (timeoutId) clearTimeout(timeoutId);
  if (!refinement || !Array.isArray(refinement.updates) || refinement.updates.length === 0) {
    return baseline;
  }

  const updatesByAction = new Map<MemoryActionType, CompressionSemanticRuleRefinement>();
  for (const update of refinement.updates) {
    if (!update || typeof update.action !== "string") continue;
    updatesByAction.set(update.action, update);
  }

  let changed = false;
  const ruleUpdates = baseline.ruleUpdates.map((rule) => {
    const patch = updatesByAction.get(rule.action);
    if (!patch) return rule;

    const nextDelta =
      typeof patch.delta === "number" && Number.isFinite(patch.delta)
        ? roundDelta(clamp(patch.delta, -MAX_DELTA, MAX_DELTA))
        : rule.delta;
    const nextConfidence = patch.confidence ?? confidenceForDelta(nextDelta);
    const nextDirection = directionForDelta(nextDelta);
    const nextNotes =
      typeof patch.note === "string" && patch.note.trim().length > 0
        ? [patch.note.trim()]
        : rule.notes;

    if (
      nextDelta !== rule.delta ||
      nextDirection !== rule.direction ||
      nextConfidence !== rule.confidence ||
      nextNotes.join("\n") !== rule.notes.join("\n")
    ) {
      changed = true;
    }

    return {
      ...rule,
      delta: nextDelta,
      direction: nextDirection,
      confidence: nextConfidence,
      notes: nextNotes,
    };
  });

  if (!changed) return baseline;
  return {
    ...baseline,
    ruleUpdates,
  };
}

export function renderCompressionGuidelinesMarkdown(candidate: CompressionGuidelineCandidate): string {
  const actionLines =
    candidate.actionSummaries.length === 0
      ? ["- (none)"]
      : candidate.actionSummaries.map((item) => `- ${item.action}: ${item.total}`);
  const outcomeLines: string[] = [
    `- applied: ${candidate.eventCounts.applied}`,
    `- skipped: ${candidate.eventCounts.skipped}`,
    `- failed: ${candidate.eventCounts.failed}`,
  ];
  const updateLines =
    candidate.ruleUpdates.length === 0
      ? ["- No telemetry events available yet. Keep defaults conservative and gather action data first."]
      : candidate.ruleUpdates.map((update) => {
          const sign = update.delta > 0 ? "+" : "";
          return `- ${update.action}: ${update.direction} (${sign}${update.delta.toFixed(3)}, confidence=${update.confidence}) — ${update.notes.join(" ")}`;
        });

  return [
    "# Compression Guidelines",
    "",
    `Generated: ${candidate.generatedAt}`,
    `Source events analyzed: ${candidate.eventCounts.total}`,
    `Source window: ${candidate.sourceWindow.from} -> ${candidate.sourceWindow.to}`,
    `Guideline version: ${candidate.guidelineVersion}`,
    "",
    "## Action Distribution",
    ...actionLines,
    "",
    "## Outcome Distribution",
    ...outcomeLines,
    "",
    "## Suggested Guidelines",
    ...updateLines,
    "",
  ].join("\n");
}

export function buildCompressionGuidelinesMarkdown(
  events: MemoryActionEvent[],
  generatedAtIso: string = new Date().toISOString(),
  previousState: CompressionGuidelineOptimizerState | null = null,
): string {
  const candidate = computeCompressionGuidelineCandidate(events, {
    generatedAtIso,
    previousState,
  });
  return renderCompressionGuidelinesMarkdown(candidate);
}

