import { log } from "../logger.js";
import {
  reportSearchDegradation,
  type SearchBackend,
  type SearchExecutionOptions,
  type SearchQueryOptions,
  type SearchResult,
} from "./port.js";

export interface RemoteSearchBackendOptions {
  baseUrl: string;
  apiKey?: string;
  timeoutMs?: number;
}

/**
 * HTTP REST search backend adapter.
 *
 * Delegates search to a remote service. Maintenance methods are no-ops
 * (remote backends manage their own indexing).
 */
export class RemoteSearchBackend implements SearchBackend {
  private readonly baseUrl: string;
  private readonly apiKey?: string;
  private readonly timeoutMs: number;
  private available = false;

  constructor(opts: RemoteSearchBackendOptions) {
    let url = opts.baseUrl;
    while (url.endsWith("/")) url = url.slice(0, -1);
    this.baseUrl = url;
    this.apiKey = opts.apiKey;
    this.timeoutMs = opts.timeoutMs ?? 30_000;
  }

  async probe(): Promise<boolean> {
    try {
      const res = await fetch(`${this.baseUrl}/health`, {
        method: "GET",
        headers: this.headers(),
        signal: AbortSignal.timeout(this.timeoutMs),
      });
      this.available = res.ok;
      return this.available;
    } catch (err) {
      log.debug(`RemoteSearchBackend probe failed: ${err}`);
      this.available = false;
      return false;
    }
  }

  isAvailable(): boolean {
    return this.available;
  }

  debugStatus(): string {
    return `backend=remote available=${this.available} baseUrl=${this.baseUrl}`;
  }

  async search(
    query: string,
    collection?: string,
    maxResults?: number,
    _options?: SearchQueryOptions,
    execution?: SearchExecutionOptions,
  ): Promise<SearchResult[]> {
    return this.post("/search/deep", { query, collection, maxResults }, execution);
  }

  async searchGlobal(query: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    return this.post("/search/deep", { query, maxResults }, execution);
  }

  async bm25Search(query: string, collection?: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    return this.post("/search/bm25", { query, collection, maxResults }, execution);
  }

  async vectorSearch(query: string, collection?: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    return this.post("/search/vector", { query, collection, maxResults }, execution);
  }

  async hybridSearch(query: string, collection?: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    return this.post("/search/hybrid", { query, collection, maxResults }, execution);
  }

  async update(_execution?: SearchExecutionOptions): Promise<void> {}
  /** The remote service owns its own indexing, so there is no local re-index that could be left incomplete. */
  async updateCompleted(_execution?: SearchExecutionOptions): Promise<boolean> {
    return true;
  }
  async updateCollection(_collection: string, _execution?: SearchExecutionOptions): Promise<void> {}
  async embed(): Promise<void> {}
  async embedCollection(_collection: string): Promise<void> {}

  async ensureCollection(
    _memoryDir: string,
    _collectionOrExecution?: string | SearchExecutionOptions,
    _execution?: SearchExecutionOptions,
  ): Promise<"skipped"> {
    return "skipped";
  }

  private headers(): Record<string, string> {
    const h: Record<string, string> = { "Content-Type": "application/json" };
    if (this.apiKey) {
      h["Authorization"] = `Bearer ${this.apiKey}`;
    }
    return h;
  }

  private async post(
    endpoint: string,
    body: Record<string, unknown>,
    execution?: SearchExecutionOptions,
  ): Promise<SearchResult[]> {
    if (!this.available) {
      reportSearchDegradation(execution, {
        backend: "remote",
        code: "backend_unavailable",
      });
      return [];
    }
    try {
      const res = await fetch(`${this.baseUrl}${endpoint}`, {
        method: "POST",
        headers: this.headers(),
        body: JSON.stringify(body),
        signal: execution?.signal
          ? AbortSignal.any([execution.signal, AbortSignal.timeout(this.timeoutMs)])
          : AbortSignal.timeout(this.timeoutMs),
      });
      if (!res.ok) {
        log.debug(`RemoteSearchBackend ${endpoint} returned ${res.status}`);
        reportSearchDegradation(execution, {
          backend: "remote",
          code: "remote_error",
          detail: `HTTP ${res.status}`,
        });
        return [];
      }
      const data = await res.json();
      if (!Array.isArray(data)) {
        reportSearchDegradation(execution, {
          backend: "remote",
          code: "remote_error",
          detail: "invalid response body",
        });
        return [];
      }
      return data as SearchResult[];
    } catch (err) {
      log.debug(`RemoteSearchBackend ${endpoint} failed: ${err}`);
      reportSearchDegradation(execution, {
        backend: "remote",
        code: "remote_error",
        detail: err instanceof Error ? err.name : typeof err,
      });
      return [];
    }
  }
}

import { log } from "../logger.js";
import {
  reportSearchDegradation,
  resolveEnsureCollectionArgs,
  type SearchBackend,
  type SearchExecutionOptions,
  type SearchQueryOptions,
  type SearchResult,
} from "./port.js";
import type { EmbedHelper, EmbedProviderIdentity, EmbedWithProviderResult } from "./embed-helper.js";
import { scanMemoryDir } from "./document-scanner.js";
import { isSearchAborted, throwIfSearchAborted } from "./abort.js";

export interface LanceDbBackendOptions {
  dbPath: string;
  collection: string;
  embedHelper: EmbedHelper;
  memoryDir: string;
  embeddingDimension: number;
}

/**
 * LanceDB search backend — embedded hybrid FTS+vector with RRF reranking.
 *
 * Uses @lancedb/lancedb for native Arrow-backed storage.
 * One table per collection. Supports full-text, vector, and hybrid search.
 */
export class LanceDbBackend implements SearchBackend {
  private readonly dbPath: string;
  private readonly collection: string;
  private readonly embedHelper: EmbedHelper;
  private readonly memoryDir: string;
  private readonly embeddingDimension: number;
  private available = false;
  private db: any = null;
  private lanceModule: any = null;
  private readonly vectorProviderCompatibility = new WeakMap<
    object,
    { providerIdentity: EmbedProviderIdentity; compatible: boolean }
  >();

  constructor(opts: LanceDbBackendOptions) {
    this.dbPath = opts.dbPath;
    this.collection = opts.collection;
    this.embedHelper = opts.embedHelper;
    this.memoryDir = opts.memoryDir;
    this.embeddingDimension = opts.embeddingDimension;
  }

  async probe(): Promise<boolean> {
    try {
      await this.ensureDb();
      this.available = true;
      return true;
    } catch (err) {
      log.debug(`LanceDbBackend probe failed: ${err}`);
      this.available = false;
      return false;
    }
  }

  isAvailable(): boolean {
    return this.available;
  }

  debugStatus(): string {
    return `backend=lancedb available=${this.available} dbPath=${this.dbPath}`;
  }

  async search(
    query: string,
    _collection?: string,
    maxResults?: number,
    _options?: SearchQueryOptions,
    execution?: SearchExecutionOptions,
  ): Promise<SearchResult[]> {
    return this.hybridSearch(query, _collection, maxResults, execution);
  }

  async searchGlobal(query: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    const limit = maxResults ?? 10;
    if (!this.available) return [];

    try {
      throwIfSearchAborted(execution, "LanceDbBackend global search aborted");
      const db = await this.ensureDb();
      const tableNames = await db.tableNames();
      const allResults: SearchResult[] = [];

      for (const name of tableNames) {
        throwIfSearchAborted(execution, "LanceDbBackend global search aborted");
        try {
          const table = await db.openTable(name);
          const results = await this.searchTable(table, query, "hybrid", limit, execution);
          allResults.push(...results);
        } catch {
          // Skip tables that fail
        }
      }

      allResults.sort((a, b) => b.score - a.score);
      return allResults.slice(0, limit);
    } catch (err) {
      log.debug(`LanceDbBackend searchGlobal failed: ${err}`);
      return [];
    }
  }

  async bm25Search(query: string, collection?: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    if (isSearchAborted(execution)) return [];
    const table = await this.ensureTableForCollection(collection ?? this.collection);
    if (isSearchAborted(execution)) return [];
    if (!table) return [];
    return this.searchTable(table, query, "fts", maxResults ?? 10, execution);
  }

  async vectorSearch(query: string, collection?: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    if (isSearchAborted(execution)) return [];
    const table = await this.ensureTableForCollection(collection ?? this.collection);
    if (isSearchAborted(execution)) return [];
    if (!table) return [];
    return this.searchTable(table, query, "vector", maxResults ?? 10, execution);
  }

  async hybridSearch(query: string, collection?: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    if (isSearchAborted(execution)) return [];
    const table = await this.ensureTableForCollection(collection ?? this.collection);
    if (isSearchAborted(execution)) return [];
    if (!table) return [];
    return this.searchTable(table, query, "hybrid", maxResults ?? 10, execution);
  }

  async update(execution?: SearchExecutionOptions): Promise<void> {
    await this.updateCollection(this.collection, execution);
  }

  async updateCollection(collection: string, execution?: SearchExecutionOptions): Promise<void> {
    await this.updateCollectionFromDir(collection, this.memoryDir, execution);
  }

  async updateCollectionFromDir(collection: string, memoryDir: string, execution?: SearchExecutionOptions): Promise<void> {
    await this.refreshCollection(collection, memoryDir, execution);
  }

  async updateCompleted(execution?: SearchExecutionOptions): Promise<boolean> {
    try {
      return await this.refreshCollection(this.collection, this.memoryDir, execution);
    } catch (err) {
      log.debug(`LanceDbBackend update did not complete: ${err}`);
      return false;
    }
  }

  /** Brings the collection up to date; true only when it ran to completion (false: aborted, unavailable, skipped or failed). */
  private async refreshCollection(collection: string, memoryDir: string, execution?: SearchExecutionOptions): Promise<boolean> {
    if (isSearchAborted(execution)) return false;
    let table = await this.ensureTableForCollection(collection);
    if (isSearchAborted(execution)) return false;
    if (!table) return false;

    const docs = await scanMemoryDir(memoryDir);
    if (isSearchAborted(execution)) return false;
    if (docs.length === 0) {
      // Clear stale data when no docs remain
      try {
        const db = await this.ensureDb();
        await db.dropTable(collection).catch(() => {});
        if (collection === this.collection) this.table = null;
        return true;
      } catch {
        // Best-effort cleanup
      }
      return false;
    }

    const embeddingProviderIdentity = this.embedHelper.getProviderIdentity();
    const existingVectors = new Map<string, {
      vector: number[];
      providerIdentity?: string;
    }>();
    const vectorProviderColumnState = await this.tableVectorProviderColumnState(table);
    if (vectorProviderColumnState === "missing") {
      table = await this.recreateTableForCollection(collection);
      if (isSearchAborted(execution)) return false;
      if (!table) return false;
    } else if (vectorProviderColumnState === "present") {
      try {
        const existingRows = await table.query().select(["docid", "vector", "vectorProvider"]).toArray();
        for (const row of existingRows ?? []) {
          if (isSearchAborted(execution)) return false;
          const docid = row.docid;
          if (typeof docid !== "string") continue;
          const vector = row.vector;
          if (!vector || typeof vector !== "object") continue;
          existingVectors.set(docid, {
            vector: Array.from(vector as ArrayLike<number>),
            providerIdentity: typeof row.vectorProvider === "string" ? row.vectorProvider : undefined,
          });
        }
      } catch {
        log.debug("LanceDbBackend skipped refresh after vector preservation failed");
        return false;
      }
    } else {
      log.debug("LanceDbBackend skipped vector preservation after vectorProvider probe failed");
      return false;
    }

    const rows = docs.map((d) => {
      const existing = existingVectors.get(d.docid);
      const canPreserveVector =
        existing &&
        this.isCompatibleStoredVector(existing.vector) &&
        (!embeddingProviderIdentity ||
          existing.providerIdentity === embeddingProviderIdentity);
      return {
        docid: d.docid,
        path: d.path,
        content: d.content,
        snippet: d.snippet,
        vector: canPreserveVector
          ? existing.vector
          : new Array(this.embeddingDimension).fill(0),
        vectorProvider: canPreserveVector
          ? existing.providerIdentity ?? ""
          : "",
      };
    });

    try {
      if (isSearchAborted(execution)) return false;
      await table.add(rows, { mode: "overwrite" });
      this.rememberVectorProviderCompatibility(
        table,
        embeddingProviderIdentity,
        rows.length > 0 && rows.every((row) => row.vectorProvider === embeddingProviderIdentity),
      );
      if (isSearchAborted(execution)) return false;
      // FTS index on the content column.
      await this.createFtsIndex(table);
      if (collection === this.collection) this.table = table;
      return true;
    } catch (err) {
      log.debug(`LanceDbBackend update failed: ${err}`);
      return false;
    }
  }

  async embed(): Promise<void> {
    await this.embedCollection(this.collection);
  }

  async embedCollection(collection: string): Promise<void> {
    if (!this.embedHelper.isAvailable()) return;

    const table = await this.ensureTableForCollection(collection);
    if (!table) return;

    try {
      const embeddingProviderIdentity = this.embedHelper.getProviderIdentity();
      const allRows = await table.query().select(["docid", "content", "vector", "vectorProvider"]).toArray();
      const needsEmbed = allRows.filter((row: any) => {
        if (embeddingProviderIdentity && row.vectorProvider !== embeddingProviderIdentity) {
          return true;
        }
        return !this.isCompatibleStoredVector(row.vector);
      });

      if (needsEmbed.length === 0) {
        this.rememberVectorProviderCompatibility(table, embeddingProviderIdentity, true);
        return;
      }

      let rowsToEmbed = needsEmbed;
      let embedResult = await this.embedHelper.embedBatchWithProvider(
        rowsToEmbed.map((row: any) => row.content as string),
      );
      if (!embedResult) return;
      if (
        embeddingProviderIdentity &&
        embedResult.providerIdentity !== embeddingProviderIdentity
      ) {
        const effectiveProviderIdentity = embedResult.providerIdentity;
        const originalDocids = new Set(rowsToEmbed.map((row: any) => row.docid));
        const effectiveNeedsEmbed = allRows.filter((row: any) => (
          row.vectorProvider !== effectiveProviderIdentity ||
          !this.isCompatibleStoredVector(row.vector)
        ));
        const sameRows =
          effectiveNeedsEmbed.length === rowsToEmbed.length &&
          effectiveNeedsEmbed.every((row: any) => originalDocids.has(row.docid));
        if (!sameRows) {
          const effectiveTexts = effectiveNeedsEmbed.map((row: any) => row.content as string);
          const effectiveEmbedResult = await this.embedHelper.embedBatchWithProvider(effectiveTexts);
          if (effectiveEmbedResult) {
            rowsToEmbed = effectiveNeedsEmbed;
            embedResult = effectiveEmbedResult;
          }
        }
      }
      const { vectors, providerIdentity } = embedResult;

      let allEmbedded = true;
      for (let i = 0; i < rowsToEmbed.length; i++) {
        const vec = vectors[i];
        if (!this.isExpectedDimensionVector(vec)) {
          allEmbedded = false;
          continue;
        }
        const docid = rowsToEmbed[i].docid;
        await table.update({
          where: `docid = '${docid.replace(/'/g, "''")}'`,
          values: { vector: vec, vectorProvider: providerIdentity },
        });
      }
      if (allEmbedded) {
        this.rememberVectorProviderCompatibility(table, providerIdentity, true);
      } else {
        this.rememberVectorProviderCompatibility(table, providerIdentity, false);
      }
    } catch (err) {
      log.debug(`LanceDbBackend embed failed: ${err}`);
    }
  }

  async ensureCollection(
    _memoryDir: string,
    collectionOrExecution?: string | SearchExecutionOptions,
    execution?: SearchExecutionOptions,
  ): Promise<"present" | "missing" | "unknown" | "skipped"> {
    const { collection, execution: effectiveExecution } = resolveEnsureCollectionArgs(
      collectionOrExecution,
      execution,
    );
    if (isSearchAborted(effectiveExecution)) return "skipped";
    try {
      await this.ensureTableForCollection(collection ?? this.collection);
      return "present";
    } catch {
      return "missing";
    }
  }

  private table: any = null;

  private get lanceIndex(): any {
    return this.lanceModule.Index ?? this.lanceModule.default?.Index;
  }

  private async ensureDb(): Promise<any> {
    if (this.db) return this.db;
    if (!this.lanceModule) {
      this.lanceModule = await import("@lancedb/lancedb");
    }
    const connect = this.lanceModule.connect ?? this.lanceModule.default?.connect;
    this.db = await connect(this.dbPath);
    return this.db;
  }

  private async ensureTableForCollection(collection: string): Promise<any> {
    // For the default collection, use the cached instance
    if (collection === this.collection) return this.ensureTable();

    const db = await this.ensureDb();
    const tables = await db.tableNames();

    if (tables.includes(collection)) {
      return await db.openTable(collection);
    }

    // Create empty table with schema
    const emptyRow = {
      docid: "__placeholder__",
      path: "",
      content: "",
      snippet: "",
      vector: new Array(this.embeddingDimension).fill(0),
      vectorProvider: "",
    };
    const newTable = await db.createTable(collection, [emptyRow]);
    await this.createFtsIndex(newTable);
    try {
      await newTable.delete("docid = '__placeholder__'");
    } catch {
      // May fail if delete isn't supported on empty-ish tables
    }
    return newTable;
  }

  private async recreateTableForCollection(collection: string): Promise<any> {
    const db = await this.ensureDb();
    try {
      await db.dropTable(collection).catch(() => {});
    } catch {
      // Best-effort legacy schema migration; table creation below may still recover.
    }
    if (collection === this.collection) this.table = null;
    return this.ensureTableForCollection(collection);
  }

  private async tableVectorProviderColumnState(table: any): Promise<"present" | "missing" | "unknown"> {
    try {
      await table.query().select(["vectorProvider"]).toArray();
      return "present";
    } catch (err) {
      if (isMissingVectorProviderColumnError(err)) {
        return "missing";
      }
      log.debug(`LanceDbBackend vectorProvider column probe failed: ${err}`);
      return "unknown";
    }
  }

  private async ensureTable(): Promise<any> {
    if (this.table) return this.table;

    const db = await this.ensureDb();
    const tables = await db.tableNames();

    if (tables.includes(this.collection)) {
      this.table = await db.openTable(this.collection);
      return this.table;
    }

    // Create empty table with schema
    const emptyRow = {
      docid: "__placeholder__",
      path: "",
      content: "",
      snippet: "",
      vector: new Array(this.embeddingDimension).fill(0),
      vectorProvider: "",
    };
    this.table = await db.createTable(this.collection, [emptyRow]);
    // Create FTS index on content column
    await this.createFtsIndex(this.table);
    // Remove placeholder row
    try {
      await this.table.delete("docid = '__placeholder__'");
    } catch {
      // May fail if delete isn't supported on empty-ish tables
    }
    return this.table;
  }

  /**
   * Create the FTS index on the content column with the default tokenizer.
   *
   * Known limitation (issue #2187): tantivy's default tokenizer does not
   * segment space-free scripts (CJK/Thai), so lexical recall over those
   * scripts is near zero here. LanceDB's `baseTokenizer: "ngram"` option is
   * not script-aware — it would n-gram English content too, degrading
   * precision and bloating the index — so no CJK-capable configuration is
   * available in the current @lancedb/lancedb API. Non-English lexical recall
   * on this backend rides on the vector tier instead. See
   * docs/search-backends.md ("Non-English content").
   */
  private async createFtsIndex(table: any): Promise<void> {
    try {
      await table.createIndex("content", { config: this.lanceIndex.fts() });
    } catch {
      // FTS index creation may fail on some platforms — degrade gracefully
    }
  }

  private async searchTable(
    table: any,
    query: string,
    mode: "fts" | "vector" | "hybrid",
    limit: number,
    execution?: SearchExecutionOptions,
  ): Promise<SearchResult[]> {
    try {
      throwIfSearchAborted(execution, `LanceDbBackend ${mode} search aborted`);
      if (mode === "fts") {
        const results = await table.search(query, "fts").limit(limit).toArray();
        throwIfSearchAborted(execution, `LanceDbBackend ${mode} search aborted`);
        return this.mapRows(results);
      }

      if (mode === "vector") {
        const embedResult = await this.resolveCompatibleQueryEmbedding(table, query, execution);
        throwIfSearchAborted(execution, `LanceDbBackend ${mode} search aborted`);
        if (!embedResult) {
          // Fall back to FTS
          const results = await table.search(query, "fts").limit(limit).toArray();
          throwIfSearchAborted(execution, `LanceDbBackend ${mode} search aborted`);
          return this.mapRows(results);
        }
        const results = await table.search(embedResult.vector).limit(limit).toArray();
        throwIfSearchAborted(execution, `LanceDbBackend ${mode} search aborted`);
        return this.mapRows(results);
      }

      // hybrid — try FTS+vector with RRF reranking
      const embedResult = await this.resolveCompatibleQueryEmbedding(table, query, execution);
      throwIfSearchAborted(execution, `LanceDbBackend ${mode} search aborted`);
      if (!embedResult) {
        const results = await table.search(query, "fts").limit(limit).toArray();
        throwIfSearchAborted(execution, `LanceDbBackend ${mode} search aborted`);
        return this.mapRows(results);
      }

      try {
        const results = await table
          .search(query, "hybrid")
          .vector(embedResult.vector)
          .limit(limit)
          .toArray();
        throwIfSearchAborted(execution, `LanceDbBackend ${mode} search aborted`);
        return this.mapRows(results);
      } catch {
        // Hybrid may not be supported in all LanceDB versions — fall back to vector
        const results = await table.search(embedResult.vector).limit(limit).toArray();
        throwIfSearchAborted(execution, `LanceDbBackend ${mode} search aborted`);
        return this.mapRows(results);
      }
    } catch (err) {
      log.debug(`LanceDbBackend search (${mode}) failed: ${err}`);
      if (!isSearchAborted(execution)) {
        reportSearchDegradation(execution, {
          backend: "lancedb",
          code: "backend_error",
          detail: err instanceof Error ? err.name : typeof err,
        });
      }
      return [];
    }
  }

  private async resolveCompatibleQueryEmbedding(
    table: any,
    query: string,
    execution?: SearchExecutionOptions,
  ): Promise<EmbedWithProviderResult | null> {
    const embedResult = await this.embedHelper.embedWithProvider(query, { signal: execution?.signal });
    throwIfSearchAborted(execution, "LanceDbBackend query embedding aborted");
    if (!embedResult || !this.isExpectedDimensionVector(embedResult.vector)) return null;

    const storedProviderIdentity = await this.findCompatibleStoredVectorProvider(table, execution);
    if (!storedProviderIdentity) {
      this.rememberVectorProviderCompatibility(table, embedResult.providerIdentity, false);
      return null;
    }
    if (storedProviderIdentity === embedResult.providerIdentity) return embedResult;

    const fallbackEmbed = await this.embedQueryWithStoredFallbackProvider(query, storedProviderIdentity, execution);
    throwIfSearchAborted(execution, "LanceDbBackend fallback query embedding aborted");
    if (
      fallbackEmbed &&
      fallbackEmbed.providerIdentity === storedProviderIdentity &&
      this.isExpectedDimensionVector(fallbackEmbed.vector)
    ) {
      return fallbackEmbed;
    }

    this.rememberVectorProviderCompatibility(table, embedResult.providerIdentity, false);
    return null;
  }

  private async embedQueryWithStoredFallbackProvider(
    query: string,
    providerIdentity: EmbedProviderIdentity,
    execution?: SearchExecutionOptions,
  ): Promise<EmbedWithProviderResult | null> {
    const embedWithIdentity = (this.embedHelper as unknown as {
      embedWithFallbackProviderIdentity?: (
        text: string,
        identity: EmbedProviderIdentity,
        options?: { signal?: AbortSignal },
      ) => Promise<EmbedWithProviderResult | null>;
    }).embedWithFallbackProviderIdentity;
    if (typeof embedWithIdentity !== "function") return null;
    return embedWithIdentity.call(this.embedHelper, query, providerIdentity, { signal: execution?.signal });
  }

  private async findCompatibleStoredVectorProvider(
    table: any,
    execution?: SearchExecutionOptions,
  ): Promise<EmbedProviderIdentity | null> {
    try {
      const cached = this.vectorProviderCompatibility.get(table);
      if (cached?.compatible) return cached.providerIdentity;
      const rows = await table.query().select(["vector", "vectorProvider"]).toArray();
      let providerIdentity: EmbedProviderIdentity | null = null;
      let compatible = rows.length > 0;
      for (const row of rows ?? []) {
        throwIfSearchAborted(execution, "LanceDbBackend vector provider check aborted");
        if (
          typeof row.vectorProvider !== "string" ||
          row.vectorProvider.length === 0 ||
          !this.isCompatibleStoredVector(row.vector)
        ) {
          compatible = false;
          break;
        }
        if (providerIdentity && row.vectorProvider !== providerIdentity) {
          compatible = false;
          break;
        }
        providerIdentity = row.vectorProvider as EmbedProviderIdentity;
      }
      if (compatible && providerIdentity) {
        this.vectorProviderCompatibility.set(table, {
          providerIdentity,
          compatible: true,
        });
        return providerIdentity;
      }
      return null;
    } catch (err) {
      if (isSearchAborted(execution)) throw err;
      log.debug(`LanceDbBackend stored vector provider check failed: ${err}`);
      return null;
    }
  }

  private mapRows(rows: any[]): SearchResult[] {
    return (rows ?? [])
      .filter((row) => row.docid && row.docid !== "__placeholder__")
      .map((row) => ({
        docid: row.docid ?? "",
        path: row.path ?? "",
        snippet: row.snippet ?? row.content?.slice(0, 200) ?? "",
        score: row._relevance_score ?? (row._distance != null ? 1 / (1 + (row._distance ?? 0)) : 0.5),
      }));
  }

  private async tableHasCompatibleVectors(
    table: any,
    providerIdentity: EmbedProviderIdentity,
    execution?: SearchExecutionOptions,
  ): Promise<boolean> {
    try {
      const cached = this.vectorProviderCompatibility.get(table);
      if (cached?.providerIdentity === providerIdentity) return cached.compatible;
      const rows = await table.query().select(["vector", "vectorProvider"]).toArray();
      let compatible = rows.length > 0;
      for (const row of rows ?? []) {
        throwIfSearchAborted(execution, "LanceDbBackend vector provider check aborted");
        if (
          row.vectorProvider !== providerIdentity ||
          !this.isCompatibleStoredVector(row.vector)
        ) {
          compatible = false;
          break;
        }
      }
      this.vectorProviderCompatibility.set(table, { providerIdentity, compatible });
      return compatible;
    } catch (err) {
      if (isSearchAborted(execution)) throw err;
      log.debug(`LanceDbBackend vector provider check failed: ${err}`);
      return false;
    }
  }

  private rememberVectorProviderCompatibility(
    table: unknown,
    providerIdentity: EmbedProviderIdentity | null,
    compatible: boolean,
  ): void {
    if (!table || typeof table !== "object") return;
    if (!providerIdentity) {
      this.vectorProviderCompatibility.delete(table);
      return;
    }
    this.vectorProviderCompatibility.set(table, { providerIdentity, compatible });
  }

  private isExpectedDimensionVector(vector: number[] | null | undefined): vector is number[] {
    return Array.isArray(vector) && vector.length === this.embeddingDimension;
  }

  private isCompatibleStoredVector(vector: unknown): boolean {
    if (!vector || typeof vector !== "object") return false;
    const arr = Array.from(vector as ArrayLike<number>);
    return (
      arr.length === this.embeddingDimension &&
      arr.every((value) => Number.isFinite(value)) &&
      arr.some((value) => value !== 0)
    );
  }
}

function isMissingVectorProviderColumnError(err: unknown): boolean {
  const message = err instanceof Error ? err.message : String(err);
  return /\bvectorProvider\b/i.test(message) &&
    /\b(column|field|schema|missing|not found|not exist|does not exist|unknown)\b/i.test(message);
}

import { log } from "../logger.js";
import {
  reportSearchDegradation,
  resolveEnsureCollectionArgs,
  type SearchBackend,
  type SearchExecutionOptions,
  type SearchQueryOptions,
  type SearchResult,
} from "./port.js";
import { scanMemoryDir } from "./document-scanner.js";
import { isSearchAborted, throwIfSearchAborted } from "./abort.js";

export interface MeilisearchBackendOptions {
  host: string;
  apiKey?: string;
  collection: string;
  timeoutMs?: number;
  autoIndex?: boolean;
  memoryDir?: string;
}

/**
 * Meilisearch search backend — server-based SDK client.
 *
 * Requires a running Meilisearch instance. Uses the official `meilisearch` SDK.
 * When `autoIndex` is true, update() pushes docs from the local memory directory.
 */
export class MeilisearchBackend implements SearchBackend {
  private readonly host: string;
  private readonly apiKey?: string;
  private readonly collection: string;
  private readonly timeoutMs: number;
  private readonly autoIndex: boolean;
  private readonly memoryDir?: string;
  private available = false;
  private client: any = null;
  private meiliModule: any = null;

  constructor(opts: MeilisearchBackendOptions) {
    this.host = opts.host;
    this.apiKey = opts.apiKey;
    this.collection = opts.collection;
    this.timeoutMs = opts.timeoutMs ?? 30_000;
    this.autoIndex = opts.autoIndex ?? false;
    this.memoryDir = opts.memoryDir;
  }

  async probe(): Promise<boolean> {
    try {
      const client = await this.ensureClient();
      await client.health();
      this.available = true;
      return true;
    } catch (err) {
      log.debug(`MeilisearchBackend probe failed: ${err}`);
      this.available = false;
      return false;
    }
  }

  isAvailable(): boolean {
    return this.available;
  }

  debugStatus(): string {
    return `backend=meilisearch available=${this.available} host=${this.host}`;
  }

  async search(
    query: string,
    collection?: string,
    maxResults?: number,
    _options?: SearchQueryOptions,
    execution?: SearchExecutionOptions,
  ): Promise<SearchResult[]> {
    if (isSearchAborted(execution)) return [];
    // Try hybrid first; fall back to plain FTS only if hybrid throws (e.g. no embedder configured)
    try {
      return await this.doSearch(query, maxResults ?? 10, { hybrid: { semanticRatio: 0.5, embedder: "default" } }, collection, true, execution);
    } catch {
      if (isSearchAborted(execution)) return [];
      return this.bm25Search(query, collection, maxResults, execution);
    }
  }

  async searchGlobal(query: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    const limit = maxResults ?? 10;
    if (!this.available) return [];

    try {
      throwIfSearchAborted(execution, "MeilisearchBackend global search aborted");
      const client = await this.ensureClient();
      const indexes = await client.getIndexes();
      throwIfSearchAborted(execution, "MeilisearchBackend global search aborted");
      const queries = (indexes.results ?? []).map((idx: any) => ({
        indexUid: idx.uid,
        q: query,
        limit,
        showRankingScore: true,
      }));
      if (queries.length === 0) return [];

      const multiResult = await client.multiSearch({ queries });
      throwIfSearchAborted(execution, "MeilisearchBackend global search aborted");
      const allResults: SearchResult[] = [];
      for (const result of multiResult.results ?? []) {
        allResults.push(...this.mapHits(result.hits ?? []));
      }
      allResults.sort((a, b) => b.score - a.score);
      return allResults.slice(0, limit);
    } catch (err) {
      log.debug(`MeilisearchBackend searchGlobal failed: ${err}`);
      return [];
    }
  }

  async bm25Search(query: string, collection?: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    return this.doSearch(query, maxResults ?? 10, undefined, collection, false, execution);
  }

  async vectorSearch(query: string, collection?: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    return this.doSearch(query, maxResults ?? 10, { hybrid: { semanticRatio: 1.0, embedder: "default" } }, collection, false, execution);
  }

  async hybridSearch(query: string, collection?: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    return this.doSearch(query, maxResults ?? 10, { hybrid: { semanticRatio: 0.5, embedder: "default" } }, collection, false, execution);
  }

  async update(execution?: SearchExecutionOptions): Promise<void> {
    await this.updateCollection(this.collection, execution);
  }

  async updateCollection(collection: string, execution?: SearchExecutionOptions): Promise<void> {
    if (!this.memoryDir) return;
    await this.updateCollectionFromDir(collection, this.memoryDir, execution);
  }

  async updateCollectionFromDir(collection: string, memoryDir: string, execution?: SearchExecutionOptions): Promise<void> {
    await this.refreshCollection(collection, memoryDir, execution);
  }

  async updateCompleted(execution?: SearchExecutionOptions): Promise<boolean> {
    // autoIndex is off by default: the Meilisearch server is managed outside Remnic and
    // nothing is pushed by configuration, so there is no re-index that could be left incomplete.
    if (!this.autoIndex) return true;
    if (!this.memoryDir) return false;
    return this.refreshCollection(this.collection, this.memoryDir, execution);
  }

  /** Brings the collection up to date; true only when it ran to completion (false: aborted, unavailable, skipped or failed). */
  private async refreshCollection(collection: string, memoryDir: string, execution?: SearchExecutionOptions): Promise<boolean> {
    if (!this.autoIndex) return false;
    if (!this.available) return false;
    if (isSearchAborted(execution)) return false;

    try {
      const ensured = await this.ensureCollection(memoryDir, collection, execution);
      if (ensured === "skipped" || ensured === "missing") return false;
      const client = await this.ensureClient();
      if (isSearchAborted(execution)) return false;
      const docs = await scanMemoryDir(memoryDir);
      if (isSearchAborted(execution)) return false;
      const index = client.index(collection);

      const meilDocs = docs.map((d) => ({
        id: d.docid,
        path: d.path,
        content: d.content,
        snippet: d.snippet,
      }));

      // Upsert current docs and wait for the task to complete
      if (isSearchAborted(execution)) return false;
      const addTask = await index.addDocuments(meilDocs, { primaryKey: "id" });
      // waitForTask resolves with a failed or canceled task and rejects only on timeout.
      const added = await client.waitForTask(addTask.taskUid, { timeOutMs: this.timeoutMs });
      if (added.status !== "succeeded") {
        log.debug(`MeilisearchBackend add task finished with status ${added.status}`);
        return false;
      }
      if (isSearchAborted(execution)) return false;

      // Remove docs that no longer exist on disk (paginated to handle large indexes)
      const currentIds = new Set(docs.map((d) => d.docid));
      try {
        const PAGE_SIZE = 1000;
        let offset = 0;
        let staleIds: string[] = [];
        let hasMore = true;
        while (hasMore) {
          if (isSearchAborted(execution)) return false;
          const page = await index.getDocuments({ limit: PAGE_SIZE, offset, fields: ["id"] });
          const results = page.results ?? [];
          for (const doc of results) {
            const id = doc.id as string;
            if (!currentIds.has(id)) staleIds.push(id);
          }
          offset += results.length;
          hasMore = results.length === PAGE_SIZE;
        }
        if (staleIds.length > 0) {
          if (isSearchAborted(execution)) return false;
          const delTask = await index.deleteDocuments(staleIds);
          // The deletion is part of completion: a stale document left searchable is not an
          // up-to-date index, and waitForTask resolves failed/canceled tasks without throwing.
          const deleted = await client.waitForTask(delTask.taskUid, { timeOutMs: this.timeoutMs });
          if (deleted.status !== "succeeded") {
            log.debug(`MeilisearchBackend stale-document deletion finished with status ${deleted.status}`);
            return false;
          }
        }
      } catch (err) {
        log.debug(`MeilisearchBackend stale-document deletion failed: ${err}`);
        return false;
      }
      return true;
    } catch (err) {
      log.debug(`MeilisearchBackend update failed: ${err}`);
      return false;
    }
  }

  async embed(): Promise<void> {
    // Meilisearch handles its own embedding when configured with an embedder
  }

  async embedCollection(collection: string): Promise<void> {
    // Meilisearch handles its own embedding when configured with an embedder
    // The collection parameter is accepted for interface compliance but Meilisearch
    // manages embeddings server-side per index (collection).
  }

  async ensureCollection(
    _memoryDir: string,
    collectionOrExecution?: string | SearchExecutionOptions,
    execution?: SearchExecutionOptions,
  ): Promise<"present" | "missing" | "unknown" | "skipped"> {
    const { collection, execution: effectiveExecution } = resolveEnsureCollectionArgs(
      collectionOrExecution,
      execution,
    );
    if (!this.available) return "skipped";
    if (isSearchAborted(effectiveExecution)) return "skipped";
    const targetCollection = collection ?? this.collection;
    try {
      const client = await this.ensureClient();
      if (isSearchAborted(effectiveExecution)) return "skipped";
      try {
        await client.getIndex(targetCollection);
        return "present";
      } catch (err) {
        if (!isMeilisearchIndexNotFoundError(err)) {
          log.debug(
            `MeilisearchBackend collection check unavailable for "${targetCollection}" (will not skip update): ${
              err instanceof Error ? err.message : String(err)
            }`,
          );
          return "unknown";
        }
        // Index doesn't exist — create it
        if (isSearchAborted(effectiveExecution)) return "skipped";
        const createTask = await client.createIndex(targetCollection, { primaryKey: "id" });
        if (isSearchAborted(effectiveExecution)) return "skipped";
        if (createTask?.taskUid !== undefined && createTask?.taskUid !== null) {
          await client.waitForTask(createTask.taskUid, { timeOutMs: this.timeoutMs });
        }
        return "present";
      }
    } catch (err) {
      log.debug(
        `MeilisearchBackend collection check failed for "${targetCollection}" (will not disable updates): ${
          err instanceof Error ? err.message : String(err)
        }`,
      );
      return "unknown";
    }
  }

  private async ensureClient(): Promise<any> {
    if (this.client) return this.client;
    if (!this.meiliModule) {
      this.meiliModule = await import("meilisearch");
    }
    const MeiliSearch = this.meiliModule.MeiliSearch ?? this.meiliModule.default?.MeiliSearch;
    this.client = new MeiliSearch({
      host: this.host,
      apiKey: this.apiKey,
      timeout: this.timeoutMs,
    });
    return this.client;
  }

  private async doSearch(
    query: string,
    limit: number,
    extra?: Record<string, unknown>,
    collection?: string,
    rethrow = false,
    execution?: SearchExecutionOptions,
  ): Promise<SearchResult[]> {
    if (!this.available) return [];
    if (isSearchAborted(execution)) return [];
    try {
      const client = await this.ensureClient();
      throwIfSearchAborted(execution, "MeilisearchBackend search aborted");
      const index = client.index(collection ?? this.collection);
      const result = await index.search(query, { limit, showRankingScore: true, ...extra });
      throwIfSearchAborted(execution, "MeilisearchBackend search aborted");
      return this.mapHits(result.hits ?? []);
    } catch (err) {
      log.debug(`MeilisearchBackend search failed: ${err}`);
      if (rethrow) throw err;
      if (!isSearchAborted(execution)) {
        reportSearchDegradation(execution, {
          backend: "meilisearch",
          code: "backend_error",
          detail: err instanceof Error ? err.name : typeof err,
        });
      }
      return [];
    }
  }

  private mapHits(hits: any[]): SearchResult[] {
    return hits.map((hit) => ({
      docid: hit.id ?? "",
      path: hit.path ?? "",
      snippet: hit._formatted?.content ?? hit.snippet ?? hit.content?.slice(0, 200) ?? "",
      score: hit._rankingScore ?? 0.5,
    }));
  }
}

function isMeilisearchIndexNotFoundError(err: unknown): boolean {
  if (!err || typeof err !== "object") {
    return false;
  }
  const record = err as Record<string, unknown>;
  const code = typeof record.code === "string" ? record.code.toLowerCase() : "";
  const type = typeof record.type === "string" ? record.type.toLowerCase() : "";
  const status =
    typeof record.status === "number"
      ? record.status
      : typeof record.statusCode === "number"
        ? record.statusCode
        : undefined;
  const message = err instanceof Error
    ? err.message.toLowerCase()
    : typeof record.message === "string"
      ? record.message.toLowerCase()
      : "";

  return (
    code === "index_not_found"
    || type === "index_not_found"
    || status === 404
    || message.includes("index_not_found")
    || /index .*not found/.test(message)
    || /index .*does not exist/.test(message)
  );
}

import path from "node:path";
import { mkdir, readdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { log } from "../logger.js";
import {
  reportSearchDegradation,
  resolveEnsureCollectionArgs,
  type SearchBackend,
  type SearchExecutionOptions,
  type SearchQueryOptions,
  type SearchResult,
} from "./port.js";
 import type { EmbedHelper, EmbedProviderIdentity, EmbedWithProviderResult } from "./embed-helper.js";
 import { scanMemoryDir } from "./document-scanner.js";
 import { isSearchAborted, throwIfSearchAborted } from "./abort.js";
import {
  containsNonLegacyTokenizerChars,
  createCjkCapableTokenizer,
  ORAMA_CJK_TOKENIZER_LANGUAGE,
} from "./orama-cjk-tokenizer.js";

 export interface OramaBackendOptions {
   dbPath: string;
   collection: string;
   embedHelper: EmbedHelper;
   memoryDir: string;
   embeddingDimension: number;
  /**
   * Segment space-free scripts (CJK/Thai) in the lexical index. Default
   * `true`; `false` restores the stock English-only tokenizer (issue #2187).
   */
  cjkSegmentationEnabled?: boolean;
 }


const ORAMA_COLLECTION_FILENAME_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

function pathIsInside(parent: string, child: string): boolean {
  const relative = path.relative(parent, child);
  return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative));
}

export function resolveOramaCollectionDbFilePath(dbPath: string, collection: string): string {
  if (!ORAMA_COLLECTION_FILENAME_PATTERN.test(collection)) {
    throw new Error(
      `Invalid Orama collection name ${JSON.stringify(collection)}. ` +
        "Collection names must match [A-Za-z0-9][A-Za-z0-9._-]*.",
    );
  }
  const resolvedDbPath = path.resolve(dbPath);
  const filePath = path.resolve(resolvedDbPath, `${collection}.msp`);
  if (!pathIsInside(resolvedDbPath, filePath)) {
    throw new Error(
      `Invalid Orama collection path for ${JSON.stringify(collection)}: resolved outside dbPath.`,
    );
  }
  return filePath;
}

/**
 * Orama search backend — embedded hybrid FTS+vector, pure JS.
 *
 * Uses @orama/orama for full-text search with optional vector support.
 * Persists data to JSON files via @orama/plugin-data-persistence.
 */
export class OramaBackend implements SearchBackend {
  private readonly dbPath: string;
  private readonly collection: string;
  private readonly embedHelper: EmbedHelper;
  private readonly memoryDir: string;
  private readonly embeddingDimension: number;
  private readonly cjkSegmentationEnabled: boolean;
  private available = false;
  private db: any = null;
  private oramaModule: any = null;
  private persistModule: any = null;
  private readonly vectorProviderCompatibility = new WeakMap<
    object,
    { providerIdentity: EmbedProviderIdentity; compatible: boolean }
  >();

  constructor(opts: OramaBackendOptions) {
    this.dbPath = opts.dbPath;
    this.collection = opts.collection;
    this.embedHelper = opts.embedHelper;
    this.memoryDir = opts.memoryDir;
    this.embeddingDimension = opts.embeddingDimension;
    this.cjkSegmentationEnabled = opts.cjkSegmentationEnabled !== false;
  }

  async probe(): Promise<boolean> {
    try {
      await this.ensureModules();
      await this.ensureDb();
      this.available = true;
      return true;
    } catch (err) {
      log.debug(`OramaBackend probe failed: ${err}`);
      this.available = false;
      return false;
    }
  }

  isAvailable(): boolean {
    return this.available;
  }

  debugStatus(): string {
    return `backend=orama available=${this.available} dbPath=${this.dbPath}`;
  }

  async search(
    query: string,
    _collection?: string,
    maxResults?: number,
    _options?: SearchQueryOptions,
    execution?: SearchExecutionOptions,
  ): Promise<SearchResult[]> {
    return this.hybridSearch(query, _collection, maxResults, execution);
  }

  async searchGlobal(query: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    const limit = maxResults ?? 10;
    if (!this.available) return [];
    try {
      throwIfSearchAborted(execution, "OramaBackend global search aborted");
      const files = await this.listDbFiles();
      const allResults: SearchResult[] = [];
      for (const file of files) {
        throwIfSearchAborted(execution, "OramaBackend global search aborted");
        const db = await this.loadDbFromFile(file);
        if (!db) continue;
        const results = await this.searchDb(db, query, "hybrid", limit, execution);
        allResults.push(...results);
      }
      allResults.sort((a, b) => b.score - a.score);
      return allResults.slice(0, limit);
    } catch (err) {
      log.debug(`OramaBackend searchGlobal failed: ${err}`);
      return [];
    }
  }

  /**
   * Full-text (FTS) search only. With the stock tokenizer this cannot match
   * space-free CJK/Thai text lexically — hybrid or vector search provides
   * the fallback for those scripts (issue #2187).
   */
  async bm25Search(query: string, collection?: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    if (isSearchAborted(execution)) return [];
    const db = await this.ensureDbForCollection(collection ?? this.collection);
    if (isSearchAborted(execution)) return [];
    if (!db) return [];
    return this.searchDb(db, query, "fulltext", maxResults ?? 10, execution);
  }

  async vectorSearch(query: string, collection?: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    if (isSearchAborted(execution)) return [];
    const db = await this.ensureDbForCollection(collection ?? this.collection);
    if (isSearchAborted(execution)) return [];
    if (!db) return [];
    return this.searchDb(db, query, "vector", maxResults ?? 10, execution);
  }

  async hybridSearch(query: string, collection?: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]> {
    if (isSearchAborted(execution)) return [];
    const db = await this.ensureDbForCollection(collection ?? this.collection);
    if (isSearchAborted(execution)) return [];
    if (!db) return [];
    return this.searchDb(db, query, "hybrid", maxResults ?? 10, execution);
  }

  async update(execution?: SearchExecutionOptions): Promise<void> {
    await this.updateCollection(this.collection, execution);
  }

  async updateCollection(collection: string, execution?: SearchExecutionOptions): Promise<void> {
    await this.updateCollectionFromDir(collection, this.memoryDir, execution);
  }

  async updateCollectionFromDir(collection: string, memoryDir: string, execution?: SearchExecutionOptions): Promise<void> {
    await this.refreshCollection(collection, memoryDir, execution);
  }

  async updateCompleted(execution?: SearchExecutionOptions): Promise<boolean> {
    try {
      return await this.refreshCollection(this.collection, this.memoryDir, execution);
    } catch (err) {
      log.debug(`OramaBackend update did not complete: ${err}`);
      return false;
    }
  }

  /** Brings the collection up to date; true only when it ran to completion (false: aborted, unavailable, skipped or failed). */
  private async refreshCollection(collection: string, memoryDir: string, execution?: SearchExecutionOptions): Promise<boolean> {
    if (isSearchAborted(execution)) return false;
    const db = await this.ensureDbForCollection(collection);
    if (isSearchAborted(execution)) return false;
    if (!db) return false;
    const { search: oramaSearch, insert, remove, count, getByID } = this.oramaModule;

    const docs = await scanMemoryDir(memoryDir);
    if (isSearchAborted(execution)) return false;
    const docMap = new Map(docs.map((d) => [d.docid, d]));
    const { update: oramaUpdate } = this.oramaModule;

    const embeddingProviderIdentity = this.embedHelper.getProviderIdentity();
    let allRowsCompatible = !!embeddingProviderIdentity && docs.length > 0;
    // Get existing docs to diff — map user doc ID → { internalId, vector }
    const existingDocs = new Map<string, {
      internalId: string;
      vector?: number[];
      vectorProvider?: string;
    }>();
    const existingCount = await count(db);
    if (existingCount > 0) {
      const allHits = await oramaSearch(db, {
        term: "",
        limit: existingCount + 100,
      });
      for (const hit of allHits.hits) {
        if (isSearchAborted(execution)) return false;
        const storedDocument =
          typeof getByID === "function"
            ? await getByID(db, hit.id)
            : hit.document;
        const document = storedDocument ?? hit.document ?? {};
        if (!docMap.has(document.id)) {
          await remove(db, hit.id);
        } else {
          existingDocs.set(document.id, {
            internalId: hit.id,
            vector: this.normalizeStoredVector(document.vector) ?? undefined,
            vectorProvider:
              typeof document.vectorProvider === "string"
                ? document.vectorProvider
                : undefined,
          });
        }
      }
    }

    // Insert new docs, update existing ones (preserving vectors since update is remove+insert)
    for (const doc of docs) {
      if (isSearchAborted(execution)) return false;
      const existing = existingDocs.get(doc.docid);
      if (existing) {
        const payload: Record<string, unknown> = {
          id: doc.docid,
          path: doc.path,
          content: doc.content,
          snippet: doc.snippet,
        };
        const preservesCompatibleProvider =
          !!embeddingProviderIdentity &&
          existing.vectorProvider === embeddingProviderIdentity;
        if (preservesCompatibleProvider) {
          if (this.isCompatibleStoredVector(existing.vector)) {
            payload.vector = existing.vector;
            payload.vectorProvider = existing.vectorProvider ?? "";
          } else {
            payload.vector = this.zeroVector();
            payload.vectorProvider = "";
            allRowsCompatible = false;
          }
        } else if (!embeddingProviderIdentity && this.isCompatibleStoredVector(existing.vector)) {
          payload.vector = existing.vector;
          payload.vectorProvider = existing.vectorProvider ?? "";
          allRowsCompatible = false;
        } else {
          payload.vector = this.zeroVector();
          payload.vectorProvider = "";
          allRowsCompatible = false;
        }
        try {
          await oramaUpdate(db, existing.internalId, payload);
        } catch {
          allRowsCompatible = false;
          // Update failed — skip and continue with remaining docs
        }
      } else {
        allRowsCompatible = false;
        try {
          await insert(db, {
            id: doc.docid,
            path: doc.path,
            content: doc.content,
            snippet: doc.snippet,
            vector: this.zeroVector(),
            vectorProvider: "",
          });
        } catch {
          allRowsCompatible = false;
          // Duplicate id edge case — skip
        }
      }
    }

    if (isSearchAborted(execution)) return false;
    await this.persistDbForCollection(db, collection);
    this.rememberVectorProviderCompatibility(
      db,
      embeddingProviderIdentity,
      allRowsCompatible,
    );
    return true;
  }

  async embed(): Promise<void> {
    await this.embedCollection(this.collection);
  }

  async embedCollection(collection: string): Promise<void> {
    if (!this.embedHelper.isAvailable()) return;

    const db = await this.ensureDbForCollection(collection);
    if (!db) return;
    const { search: oramaSearch, update: oramaUpdate, count } = this.oramaModule;

    const existingCount = await count(db);
    if (existingCount === 0) return;

    const embeddingProviderIdentity = this.embedHelper.getProviderIdentity();
    // Find docs without vectors or with vectors from a different provider.
    const allHits = await oramaSearch(db, { term: "", limit: existingCount + 100 });
    const needsEmbed = allHits.hits.filter((h: any) => {
      const vector = this.normalizeStoredVector(h.document?.vector);
      return (
        (embeddingProviderIdentity &&
          h.document?.vectorProvider !== embeddingProviderIdentity) ||
        !this.isCompatibleStoredVector(vector)
      );
    });

    if (needsEmbed.length === 0) {
      this.rememberVectorProviderCompatibility(db, embeddingProviderIdentity, true);
      return;
    }

    let rowsToEmbed = needsEmbed;
    let embedResult = await this.embedHelper.embedBatchWithProvider(
      rowsToEmbed.map((h: any) => h.document.content as string),
    );
    if (!embedResult) return;
    if (
      embeddingProviderIdentity &&
      embedResult.providerIdentity !== embeddingProviderIdentity
    ) {
      const effectiveProviderIdentity = embedResult.providerIdentity;
      const originalIds = new Set(rowsToEmbed.map((h: any) => h.id));
      const effectiveNeedsEmbed = allHits.hits.filter((h: any) => {
        const vector = this.normalizeStoredVector(h.document?.vector);
        return (
          h.document?.vectorProvider !== effectiveProviderIdentity ||
          !this.isCompatibleStoredVector(vector)
        );
      });
      const sameRows =
        effectiveNeedsEmbed.length === rowsToEmbed.length &&
        effectiveNeedsEmbed.every((h: any) => originalIds.has(h.id));
      if (!sameRows) {
        const effectiveTexts = effectiveNeedsEmbed.map((h: any) => h.document.content as string);
        const effectiveEmbedResult = await this.embedHelper.embedBatchWithProvider(effectiveTexts);
        if (effectiveEmbedResult) {
          rowsToEmbed = effectiveNeedsEmbed;
          embedResult = effectiveEmbedResult;
        }
      }
    }
    const { vectors, providerIdentity } = embedResult;

    let allEmbedded = true;
    for (let i = 0; i < rowsToEmbed.length; i++) {
      const vec = vectors[i];
      if (!this.isExpectedDimensionVector(vec)) {
        allEmbedded = false;
        continue;
      }
      // Orama update is remove+insert — must include all fields to avoid data loss
      const doc = rowsToEmbed[i].document;
      await oramaUpdate(db, rowsToEmbed[i].id, {
        id: doc.id,
        path: doc.path,
        content: doc.content,
        snippet: doc.snippet,
        vector: vec,
        vectorProvider: providerIdentity,
      });
    }

    await this.persistDbForCollection(db, collection);
    if (allEmbedded) {
      this.rememberVectorProviderCompatibility(db, providerIdentity, true);
    } else {
      this.rememberVectorProviderCompatibility(db, providerIdentity, false);
    }
  }

  async ensureCollection(
    _memoryDir: string,
    collectionOrExecution?: string | SearchExecutionOptions,
    execution?: SearchExecutionOptions,
  ): Promise<"present" | "missing" | "unknown" | "skipped"> {
    const { collection, execution: effectiveExecution } = resolveEnsureCollectionArgs(
      collectionOrExecution,
      execution,
    );
    if (isSearchAborted(effectiveExecution)) return "skipped";
    try {
      await this.ensureModules();
      await this.ensureDbForCollection(collection ?? this.collection);
      return "present";
    } catch {
      return "missing";
    }
  }

  private async ensureModules(): Promise<void> {
    if (this.oramaModule && this.persistModule) return;
    this.oramaModule = await import("@orama/orama");
    this.persistModule = await import("@orama/plugin-data-persistence");
  }

  private async ensureDb(): Promise<any> {
    if (this.db) return this.db;
    await this.ensureModules();

    await mkdir(this.dbPath, { recursive: true });
    const filePath = this.dbFilePath(this.collection);

    let raw: string;
    try {
      raw = await readFile(filePath, "utf-8");
    } catch {
      // No existing DB — create fresh
      this.db = await this.createDb();
      return this.db;
    }

    this.db = await this.applyTokenizerVersion(
      await this.migrateLegacyVectorProviderSchema(
        await this.persistModule.restore("json", raw),
        this.collection,
      ),
      this.collection,
    );
    return this.db;
  }

  private async ensureDbForCollection(collection: string): Promise<any> {
    // For the default collection, use the cached instance
    if (collection === this.collection) return this.ensureDb();

    await this.ensureModules();
    await mkdir(this.dbPath, { recursive: true });
    const filePath = this.dbFilePath(collection);

    let raw: string;
    try {
      raw = await readFile(filePath, "utf-8");
    } catch {
      // No existing DB — create fresh
      return await this.createDb();
    }

    return await this.applyTokenizerVersion(
      await this.migrateLegacyVectorProviderSchema(
        await this.persistModule.restore("json", raw),
        collection,
      ),
      collection,
    );
  }

  private async createDb(): Promise<any> {
    const { create } = this.oramaModule;
    const schema: Record<string, string> = {
      id: "string",
      path: "string",
      content: "string",
      snippet: "string",
      vectorProvider: "string",
      vector: `vector[${this.embeddingDimension}]`,
    };
    if (!this.cjkSegmentationEnabled) {
      return await create({ schema });
    }
    return await create({
      schema,
      components: { tokenizer: createCjkCapableTokenizer(this.oramaModule) },
    });
  }

  /**
   * Attach the CJK-capable tokenizer to a restored index and rebuild the
   * full-text index when it predates CJK tokenization. Orama persists
   * `tokenizer.language` with the index, so a marker other than
   * `ORAMA_CJK_TOKENIZER_LANGUAGE` identifies an index whose terms were
   * produced by the stock English tokenizer. Corpora whose content the stock
   * tokenizer and this tokenizer treat identically (pure legacy Latin) need
   * no re-indexing — only the version marker is rewritten for them.
   */
  private async applyTokenizerVersion(db: any, collection: string): Promise<any> {
    const persistedLanguage =
      db?.tokenizer?.language && typeof db.tokenizer.language === "string"
        ? db.tokenizer.language
        : "";
    if (this.cjkSegmentationEnabled) {
      db.tokenizer = createCjkCapableTokenizer(this.oramaModule);
      if (persistedLanguage === ORAMA_CJK_TOKENIZER_LANGUAGE) return db;
    } else {
      // Segmentation disabled: a database persisted under the CJK tokenizer
      // keeps its CJK terms unless it is re-indexed under the stock one, so
      // downgrade it instead of returning it unchanged (issue #2187 round 2).
      if (persistedLanguage !== ORAMA_CJK_TOKENIZER_LANGUAGE) return db;
      db.tokenizer = this.oramaModule.components.tokenizer.createTokenizer({ language: "english" });
    }


    try {
      const { search: oramaSearch, count, update: oramaUpdate } = this.oramaModule;
      const existingCount = await count(db);
      if (existingCount === 0) {
        await this.persistDbForCollection(db, collection);
        return db;
      }
      const allHits = await oramaSearch(db, { term: "", limit: existingCount + 100 });
      const hits = allHits.hits ?? [];
      const hasNonLegacyContent = hits.some((hit: any) => {
        const doc = this.getStoredDocument(db, hit);
        // Orama full-text queries every string field by default, so every
        // indexed string field gates the rebuild — non-Latin text that only
        // rides in snippet/path/id would otherwise keep stale terms
        // (issue #2187 review round 2).
        for (const field of [doc.content, doc.snippet, doc.path, doc.id, doc.vectorProvider]) {
          if (typeof field === "string" && containsNonLegacyTokenizerChars(field)) return true;
        }
        return false;
      });
      if (hasNonLegacyContent) {
        // Re-index every document in place (Orama update is remove+insert,
        // so content is re-tokenized; vectors are carried through). A single
        // failing document must not block the rest of the corpus: it keeps
        // its pre-upgrade terms, which is no worse than before the upgrade.
        for (const hit of hits) {
          try {
            const doc = this.getStoredDocument(db, hit);
            const vector = this.getStoredVector(db, hit, doc);
            await oramaUpdate(db, hit.id, {
              id: typeof doc.id === "string" && doc.id.length > 0 ? doc.id : String(hit.id),
              path: typeof doc.path === "string" ? doc.path : "",
              content: typeof doc.content === "string" ? doc.content : "",
              snippet:
                typeof doc.snippet === "string"
                  ? doc.snippet
                  : typeof doc.content === "string"
                    ? doc.content.slice(0, 200)
                    : "",
              vectorProvider: typeof doc.vectorProvider === "string" ? doc.vectorProvider : "",
              vector: vector ?? this.zeroVector(),
            });
          } catch (docErr) {
            log.debug(
              `OramaBackend tokenizer-version re-index skipped document ${hit.id} in ${collection}: ${docErr}`,
            );
          }
        }
      }
      await this.persistDbForCollection(db, collection);
    } catch (err) {
      log.debug(`OramaBackend tokenizer-version rebuild for ${collection} failed: ${err}`);
    }
    return db;
  }

  private async migrateLegacyVectorProviderSchema(db: any, collection: string): Promise<any> {
    const { search: oramaSearch, count, insert } = this.oramaModule;
    const existingCount = await count(db);
    if (existingCount === 0) {
      const migrated = await this.createDb();
      await this.persistDbForCollection(migrated, collection);
      return migrated;
    }

    const allHits = await oramaSearch(db, { term: "", limit: existingCount + 100 });
    const hits = allHits.hits ?? [];
    const needsMigration = hits.some((hit: any) =>
      typeof hit.document?.vectorProvider !== "string"
    );
    if (!needsMigration) return db;

    const migrated = await this.createDb();
    for (const hit of hits) {
      const doc = this.getStoredDocument(db, hit);
      const vector = this.getStoredVector(db, hit, doc);
      const payload: Record<string, unknown> = {
        id: typeof doc.id === "string" && doc.id.length > 0 ? doc.id : String(hit.id),
        path: typeof doc.path === "string" ? doc.path : "",
        content: typeof doc.content === "string" ? doc.content : "",
        snippet:
          typeof doc.snippet === "string"
            ? doc.snippet
            : typeof doc.content === "string"
              ? doc.content.slice(0, 200)
              : "",
        vectorProvider:
          typeof doc.vectorProvider === "string" ? doc.vectorProvider : "",
      };
      if (vector) {
        payload.vector = vector;
      } else {
        payload.vector = this.zeroVector();
      }
      await insert(migrated, payload);
    }
    await this.persistDbForCollection(migrated, collection);
    return migrated;
  }

  private async persistDbForCollection(db: any, collection: string): Promise<void> {
    const data = await this.persistModule.persist(db, "json");
    const filePath = this.dbFilePath(collection);
    await mkdir(path.dirname(filePath), { recursive: true });
    const tempPath = path.join(
      path.dirname(filePath),
      `.${path.basename(filePath)}.${process.pid}.${Date.now()}.${Math.random().toString(16).slice(2)}.tmp`,
    );
    try {
      await writeFile(tempPath, data, "utf-8");
      await rename(tempPath, filePath);
    } catch (err) {
      await rm(tempPath, { force: true }).catch(() => undefined);
      throw err;
    }
  }

  private dbFilePath(collection: string): string {
    return resolveOramaCollectionDbFilePath(this.dbPath, collection);
  }

  private async listDbFiles(): Promise<string[]> {
    try {
      const entries = await readdir(this.dbPath);
      return entries
        .filter((e) => e.endsWith(".msp"))
        .map((e) => path.join(this.dbPath, e));
    } catch {
      return [];
    }
  }

  private async loadDbFromFile(filePath: string): Promise<any> {
    try {
      await this.ensureModules();
      const raw = await readFile(filePath, "utf-8");
      const collection = path.basename(filePath, ".msp");
      return await this.applyTokenizerVersion(
        await this.migrateLegacyVectorProviderSchema(
          await this.persistModule.restore("json", raw),
          collection,
        ),
        collection,
      );
    } catch (err) {
      log.debug(`OramaBackend failed to load ${filePath}: ${err}`);
      return null;
    }
  }

  private async searchDb(
    db: any,
    query: string,
    mode: "fulltext" | "vector" | "hybrid",
    limit: number,
    execution?: SearchExecutionOptions,
  ): Promise<SearchResult[]> {
    const { search: oramaSearch } = this.oramaModule;

    try {
      throwIfSearchAborted(execution, `OramaBackend ${mode} search aborted`);
      let searchParams: any;

      if (mode === "fulltext") {
        searchParams = { term: query, limit };
      } else if (mode === "vector") {
        const embedResult = await this.resolveCompatibleQueryEmbedding(db, query, execution);
        throwIfSearchAborted(execution, `OramaBackend ${mode} search aborted`);
        if (!embedResult) {
          // Fall back to fulltext if no embeddings available
          searchParams = { term: query, limit };
        } else {
          searchParams = { mode: "vector", vector: { value: embedResult.vector, property: "vector" }, limit };
        }
      } else {
        // hybrid
        const embedResult = await this.resolveCompatibleQueryEmbedding(db, query, execution);
        throwIfSearchAborted(execution, `OramaBackend ${mode} search aborted`);
        if (!embedResult) {
          searchParams = { term: query, limit };
        } else {
          searchParams = { mode: "hybrid", term: query, vector: { value: embedResult.vector, property: "vector" }, limit };
        }
      }

      throwIfSearchAborted(execution, `OramaBackend ${mode} search aborted`);
      const result = await oramaSearch(db, searchParams);
      throwIfSearchAborted(execution, `OramaBackend ${mode} search aborted`);
      return (result.hits ?? []).map((hit: any) => ({
        docid: hit.document?.id ?? "",
        path: hit.document?.path ?? "",
        snippet: hit.document?.snippet ?? hit.document?.content?.slice(0, 200) ?? "",
        score: hit.score ?? 0,
      }));
    } catch (err) {
      log.debug(`OramaBackend search (${mode}) failed: ${err}`);
      if (!isSearchAborted(execution)) {
        reportSearchDegradation(execution, {
          backend: "orama",
          code: "backend_error",
          detail: err instanceof Error ? err.name : typeof err,
        });
      }
      return [];
    }
  }

  private async resolveCompatibleQueryEmbedding(
    db: any,
    query: string,
    execution?: SearchExecutionOptions,
  ): Promise<EmbedWithProviderResult | null> {
    const embedResult = await this.embedHelper.embedWithProvider(query, { signal: execution?.signal });
    throwIfSearchAborted(execution, "OramaBackend query embedding aborted");
    if (!embedResult || !this.isExpectedDimensionVector(embedResult.vector)) return null;

    const storedProviderIdentity = await this.findCompatibleStoredVectorProvider(db, execution);
    if (!storedProviderIdentity) {
      this.rememberVectorProviderCompatibility(db, embedResult.providerIdentity, false);
      return null;
    }
    if (storedProviderIdentity === embedResult.providerIdentity) return embedResult;

    const fallbackEmbed = await this.embedQueryWithStoredFallbackProvider(query, storedProviderIdentity, execution);
    throwIfSearchAborted(execution, "OramaBackend fallback query embedding aborted");
    if (
      fallbackEmbed &&
      fallbackEmbed.providerIdentity === storedProviderIdentity &&
      this.isExpectedDimensionVector(fallbackEmbed.vector)
    ) {
      return fallbackEmbed;
    }

    this.rememberVectorProviderCompatibility(db, embedResult.providerIdentity, false);
    return null;
  }

  private async embedQueryWithStoredFallbackProvider(
    query: string,
    providerIdentity: EmbedProviderIdentity,
    execution?: SearchExecutionOptions,
  ): Promise<EmbedWithProviderResult | null> {
    const embedWithIdentity = (this.embedHelper as unknown as {
      embedWithFallbackProviderIdentity?: (
        text: string,
        identity: EmbedProviderIdentity,
        options?: { signal?: AbortSignal },
      ) => Promise<EmbedWithProviderResult | null>;
    }).embedWithFallbackProviderIdentity;
    if (typeof embedWithIdentity !== "function") return null;
    return embedWithIdentity.call(this.embedHelper, query, providerIdentity, { signal: execution?.signal });
  }

  private async findCompatibleStoredVectorProvider(
    db: any,
    execution?: SearchExecutionOptions,
  ): Promise<EmbedProviderIdentity | null> {
    const { search: oramaSearch, count } = this.oramaModule;
    try {
      const cached = this.vectorProviderCompatibility.get(db);
      if (cached?.compatible) return cached.providerIdentity;
      const existingCount = await count(db);
      if (existingCount === 0) return null;
      const allHits = await oramaSearch(db, {
        term: "",
        limit: existingCount + 100,
        properties: ["vectorProvider"],
      });
      let providerIdentity: EmbedProviderIdentity | null = null;
      let compatible = (allHits.hits ?? []).length > 0;
      for (const hit of allHits.hits ?? []) {
        throwIfSearchAborted(execution, "OramaBackend vector provider check aborted");
        const doc = this.getStoredDocument(db, hit);
        if (
          typeof doc.vectorProvider !== "string" ||
          doc.vectorProvider.length === 0 ||
          !this.isCompatibleStoredVector(this.getStoredVector(db, hit, doc))
        ) {
          compatible = false;
          break;
        }
        if (providerIdentity && doc.vectorProvider !== providerIdentity) {
          compatible = false;
          break;
        }
        providerIdentity = doc.vectorProvider as EmbedProviderIdentity;
      }
      if (compatible && providerIdentity) {
        this.vectorProviderCompatibility.set(db, {
          providerIdentity,
          compatible: true,
        });
        return providerIdentity;
      }
      return null;
    } catch (err) {
      if (isSearchAborted(execution)) throw err;
      log.debug(`OramaBackend stored vector provider check failed: ${err}`);
      return null;
    }
  }

  private async dbHasCompatibleVectors(
    db: any,
    providerIdentity: EmbedProviderIdentity,
    execution?: SearchExecutionOptions,
  ): Promise<boolean> {
    const { search: oramaSearch, count } = this.oramaModule;
    try {
      const cached = this.vectorProviderCompatibility.get(db);
      if (cached?.providerIdentity === providerIdentity) return cached.compatible;
      const existingCount = await count(db);
      if (existingCount === 0) return false;
      const allHits = await oramaSearch(db, {
        term: "",
        limit: existingCount + 100,
        properties: ["vectorProvider"],
      });
      let compatible = (allHits.hits ?? []).length > 0;
      for (const hit of allHits.hits ?? []) {
        throwIfSearchAborted(execution, "OramaBackend vector provider check aborted");
        const doc = this.getStoredDocument(db, hit);
        if (
          doc.vectorProvider !== providerIdentity ||
          !this.isCompatibleStoredVector(this.getStoredVector(db, hit, doc))
        ) {
          compatible = false;
          break;
        }
      }
      this.vectorProviderCompatibility.set(db, { providerIdentity, compatible });
      return compatible;
    } catch (err) {
      if (isSearchAborted(execution)) throw err;
      log.debug(`OramaBackend vector provider check failed: ${err}`);
      return false;
    }
  }

  private rememberVectorProviderCompatibility(
    db: unknown,
    providerIdentity: EmbedProviderIdentity | null,
    compatible: boolean,
  ): void {
    if (!db || typeof db !== "object") return;
    if (!providerIdentity) {
      this.vectorProviderCompatibility.delete(db);
      return;
    }
    this.vectorProviderCompatibility.set(db, { providerIdentity, compatible });
  }

  private getStoredDocument(db: any, hit: any): Record<string, unknown> {
    const internalId = this.getInternalDocumentId(db, hit);
    const internalDoc =
      internalId !== undefined && internalId !== null
        ? db?.data?.docs?.docs?.[String(internalId)]
        : undefined;
    if (internalDoc && typeof internalDoc === "object") {
      return internalDoc as Record<string, unknown>;
    }
    return hit?.document && typeof hit.document === "object"
      ? hit.document as Record<string, unknown>
      : {};
  }

  private getStoredVector(db: any, hit: any, doc: Record<string, unknown>): number[] | null {
    const documentVector = this.normalizeStoredVector(doc.vector);
    if (documentVector) return documentVector;
    const internalId = this.getInternalDocumentId(db, hit);
    if (internalId === undefined || internalId === null) return null;
    const vectorEntry = db?.data?.index?.vectorIndexes?.vector?.node?.vectors?.get?.(internalId);
    const vector = Array.isArray(vectorEntry) ? vectorEntry[1] : vectorEntry;
    return this.normalizeStoredVector(vector);
  }

  private getInternalDocumentId(db: any, hit: any): unknown {
    const publicId =
      typeof hit?.id === "string"
        ? hit.id
        : typeof hit?.document?.id === "string"
          ? hit.document.id
          : undefined;
    return publicId && typeof db?.internalDocumentIDStore?.idToInternalId?.get === "function"
      ? db.internalDocumentIDStore.idToInternalId.get(publicId)
      : undefined;
  }

  private isExpectedDimensionVector(vector: number[] | null | undefined): vector is number[] {
    return Array.isArray(vector) && vector.length === this.embeddingDimension;
  }

  private isCompatibleStoredVector(vector: unknown): vector is number[] {
    if (!vector || typeof vector !== "object") return false;
    const arr = Array.from(vector as ArrayLike<number>);
    return (
      arr.length === this.embeddingDimension &&
      arr.every((value) => Number.isFinite(value)) &&
      arr.some((value) => value !== 0)
    );
  }

  private zeroVector(): number[] {
    return Array.from({ length: this.embeddingDimension }, () => 0);
  }

  private normalizeStoredVector(vector: unknown): number[] | null {
    const values =
      Array.isArray(vector)
        ? vector
        : ArrayBuffer.isView(vector) && !(vector instanceof DataView)
          ? Array.from(vector as unknown as ArrayLike<unknown>)
          : null;
    if (!values || values.length !== this.embeddingDimension) return null;
    const normalized = values.map((value) => Number(value));
    return normalized.every((value) => Number.isFinite(value)) ? normalized : null;
  }
}

import { log } from "../logger.js";
import {
  resolveMemoryLifecycleCapabilities,
  resolveLocalLlmCapabilities,
} from "../capabilities.js";
import type { PluginConfig } from "../types.js";
import { isAbortError } from "../abort-error.js";
import { withTimeoutSignal } from "./abort.js";
import { resolvePipelineProcessingCapabilities } from "../capabilities.js";
import {
  getHostEmbeddingProvider,
  type HostEmbeddingProvider,
  type HostEmbeddingInputType,
  normalizeHostEmbeddingVector,
} from "../host-embedding-provider.js";

type ProviderConfig = {
  type: "openai" | "local" | "host";
  model: string;
  endpoint?: string;
  headers?: Record<string, string>;
  hostProvider?: HostEmbeddingProvider;
};

type HostEmbeddingScopeConfig = PluginConfig & {
  /**
   * Internal namespace-router metadata. Host adapters register providers at
   * the root memoryDir while namespace backends operate under scoped dirs.
   */
  hostEmbeddingProviderScope?: string;
};

type EmbedHelperOptions = {
  /** Backend-local vector schema dimension for host-provider validation. */
  hostEmbeddingExpectedDimension?: number;
};

export type EmbedProviderIdentity = `${ProviderConfig["type"]}:${string}`;

export type EmbedWithProviderResult = {
  vector: number[];
  providerIdentity: EmbedProviderIdentity;
};

export type EmbedBatchWithProviderResult = {
  vectors: (number[] | null)[];
  providerIdentity: EmbedProviderIdentity;
};

const DEFAULT_OPENAI_MODEL = "text-embedding-3-small";
const DEFAULT_PROVIDER_CACHE_TTL_MS = 250;

/**
 * Standalone embedding helper for search backend adapters.
 *
 * NOTE: This intentionally duplicates provider resolution from EmbeddingFallback.
 * EmbeddingFallback is tightly integrated with the plugin lifecycle (telemetry,
 * rate-limit backoff, provider rotation). This class is a lightweight standalone
 * utility used by LanceDB/Orama backends which operate outside plugin context.
 * Merging them would break the port/adapter separation between search and plugin layers.
 */
export class EmbedHelper {
  private cachedProvider: ProviderConfig | null | undefined;
  private cachedProviderAt = 0;
  private providerCacheTtlMs = DEFAULT_PROVIDER_CACHE_TTL_MS;

  constructor(
    private readonly config: PluginConfig,
    private readonly options: EmbedHelperOptions = {},
  ) {}

  /**
   * Whether an embedding provider is available.
   * Re-resolves periodically so late host-provider registration is visible
   * without repeatedly probing provider state on every hot-path call.
   */
  isAvailable(): boolean {
    return this.getProvider() !== null;
  }

  /**
   * Embed a single text string. Returns null if no provider is available.
   */
  async embed(text: string, options: { signal?: AbortSignal } = {}): Promise<number[] | null> {
    return (await this.embedWithProvider(text, options))?.vector ?? null;
  }

  async embedWithProvider(
    text: string,
    options: { signal?: AbortSignal } = {},
  ): Promise<EmbedWithProviderResult | null> {
    const provider = this.getProvider();
    if (!provider) return null;
    const result = await this.callEmbed(text, provider, options.signal, "query");
    if (result) {
      return {
        vector: result,
        providerIdentity: providerIdentity(provider),
      };
    }
    if (provider.type !== "host") return null;
    const fallbackProvider = this.resolveProvider({ includeHost: false });
    if (!fallbackProvider) return null;
    const fallbackResult = await this.callEmbed(text, fallbackProvider, options.signal, "query");
    return fallbackResult
      ? {
          vector: fallbackResult,
          providerIdentity: providerIdentity(fallbackProvider),
        }
      : null;
  }

  async embedWithFallbackProviderIdentity(
    text: string,
    identity: EmbedProviderIdentity,
    options: { signal?: AbortSignal } = {},
  ): Promise<EmbedWithProviderResult | null> {
    const provider = this.resolveFallbackProviderForIdentity(identity);
    if (!provider) return null;
    const result = await this.callEmbed(text, provider, options.signal, "query");
    return result
      ? {
          vector: result,
          providerIdentity: providerIdentity(provider),
        }
      : null;
  }

  /**
   * Embed a batch of texts. Returns an array parallel to input; entries are null on failure.
   */
  async embedBatch(
    texts: string[],
    batchSize = 32,
    options: { signal?: AbortSignal } = {},
  ): Promise<(number[] | null)[]> {
    return (await this.embedBatchWithProvider(texts, batchSize, options))?.vectors ?? texts.map(() => null);
  }

  async embedBatchWithProvider(
    texts: string[],
    batchSize = 32,
    options: { signal?: AbortSignal } = {},
  ): Promise<EmbedBatchWithProviderResult | null> {
    const provider = this.getProvider();
    if (!provider) return null;

    if (provider.type === "host") {
      const hostResults = await this.embedAllWithProvider(texts, batchSize, provider, options);
      if (!hostResults.some((result) => result === null)) {
        return {
          vectors: hostResults,
          providerIdentity: providerIdentity(provider),
        };
      }
      const fallbackProvider = this.resolveProvider({ includeHost: false });
      if (!fallbackProvider) {
        return {
          vectors: hostResults,
          providerIdentity: providerIdentity(provider),
        };
      }
      const fallbackResults = await this.embedAllWithProvider(texts, batchSize, fallbackProvider, options);
      return {
        vectors: fallbackResults,
        providerIdentity: providerIdentity(fallbackProvider),
      };
    }

    return {
      vectors: await this.embedAllWithProvider(texts, batchSize, provider, options),
      providerIdentity: providerIdentity(provider),
    };
  }

  getProviderIdentity(): EmbedProviderIdentity | null {
    const provider = this.getProvider();
    return provider ? providerIdentity(provider) : null;
  }

  private async embedAllWithProvider(
    texts: string[],
    batchSize: number,
    provider: ProviderConfig,
    options: { signal?: AbortSignal } = {},
  ): Promise<(number[] | null)[]> {
    const results: (number[] | null)[] = new Array(texts.length).fill(null);
    for (let i = 0; i < texts.length; i += batchSize) {
      const batch = texts.slice(i, i + batchSize);
      const batchResults =
        provider.type === "host" && provider.hostProvider?.embedBatch
          ? await this.callHostEmbedBatch(batch, provider.hostProvider, options.signal)
          : await Promise.all(
              batch.map((t) => this.callEmbed(t, provider, options.signal, "document")),
            );
      for (let j = 0; j < batchResults.length; j++) {
        results[i + j] = batchResults[j];
      }
    }
    return results;
  }

  private getProvider(): ProviderConfig | null {
    const now = Date.now();
    if (
      this.cachedProvider !== undefined &&
      now - this.cachedProviderAt < this.providerCacheTtlMs
    ) {
      return this.cachedProvider;
    }
    this.cachedProvider = this.resolveProvider();
    this.cachedProviderAt = now;
    return this.cachedProvider;
  }

  private resolveProvider(options: { includeHost?: boolean } = {}): ProviderConfig | null {
    if (!resolveMemoryLifecycleCapabilities(this.config).embeddingFallback) return null;

    if (
      options.includeHost !== false &&
      resolvePipelineProcessingCapabilities(this.config).hostEmbeddingProvider !== false
    ) {
      const hostProvider = this.resolveHostEmbeddingProvider();
      if (hostProvider) {
        return {
          type: "host",
          model: hostProvider.model || hostProvider.id,
          hostProvider,
        };
      }
    }

    const preferred = this.config.embeddingFallbackProvider;
    const providers = preferred === "auto" ? ["openai", "local"] : [preferred];

    for (const p of providers) {
      if (p === "openai") {
        const provider = this.createOpenAiProvider();
        if (provider) return provider;
      }

      if (p === "local") {
        const provider = this.createLocalProvider();
        if (provider) return provider;
      }
    }

    return null;
  }

  private resolveFallbackProviderForIdentity(identity: EmbedProviderIdentity): ProviderConfig | null {
    if (!resolveMemoryLifecycleCapabilities(this.config).embeddingFallback) return null;
    const separator = identity.indexOf(":");
    if (separator <= 0 || separator === identity.length - 1) return null;
    const type = identity.slice(0, separator);
    const model = identity.slice(separator + 1);

    if (type === "openai") {
      const provider = this.createOpenAiProvider();
      return provider && provider.model === model ? provider : null;
    }
    if (type === "local") {
      const provider = this.createLocalProvider();
      return provider && provider.model === model ? provider : null;
    }
    return null;
  }

  private createOpenAiProvider(): ProviderConfig | null {
    if (!this.config.openaiApiKey) return null;
    const baseUrl = this.config.openaiBaseUrl ?? "https://api.openai.com/v1";
    return {
      type: "openai",
      model: DEFAULT_OPENAI_MODEL,
      endpoint: `${baseUrl.replace(/\/$/, "")}/embeddings`,
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${this.config.openaiApiKey}`,
      },
    };
  }

  private createLocalProvider(): ProviderConfig | null {
    if (!resolveLocalLlmCapabilities(this.config).localLlm || !this.config.localLlmUrl) return null;
    const base = this.config.localLlmUrl.replace(/\/$/, "");
    const endpoint = /\/v1$/i.test(base) ? `${base}/embeddings` : `${base}/v1/embeddings`;
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      ...(this.config.localLlmHeaders ?? {}),
    };
    if (this.config.localLlmApiKey && this.config.localLlmAuthHeader !== false) {
      headers.Authorization = `Bearer ${this.config.localLlmApiKey}`;
    }
    return {
      type: "local",
      model:
        this.config.embeddingFallbackModel ||
        this.config.localLlmModel ||
        DEFAULT_OPENAI_MODEL,
      endpoint,
      headers,
    };
  }

  private resolveHostEmbeddingProvider(): HostEmbeddingProvider | undefined {
    const scopedConfig = this.config as HostEmbeddingScopeConfig;
    const scopes = [
      scopedConfig.memoryDir,
      scopedConfig.hostEmbeddingProviderScope,
    ].filter((scope): scope is string => typeof scope === "string" && scope.trim().length > 0);

    for (const scope of new Set(scopes)) {
      const provider = getHostEmbeddingProvider(scope);
      if (provider) return provider;
    }
    return undefined;
  }

  private async callEmbed(
    input: string,
    provider: ProviderConfig,
    signal?: AbortSignal,
    inputType: HostEmbeddingInputType = "document",
  ): Promise<number[] | null> {
    if (provider.type === "host") {
      return this.callHostEmbed(input, provider.hostProvider, signal, inputType);
    }
    if (!provider.endpoint || !provider.headers) return null;
    try {
      const res = await fetch(provider.endpoint, {
        method: "POST",
        headers: provider.headers,
        body: JSON.stringify({
          model: provider.model,
          input: input.slice(0, 8000),
          encoding_format: "float",
        }),
        signal: withTimeoutSignal(signal, 30_000),
      });
      if (!res.ok) {
        log.debug(`EmbedHelper request failed: ${provider.type} ${res.status}`);
        return null;
      }
      const payload = (await res.json()) as any;
      const vector = payload?.data?.[0]?.embedding;
      return normalizeHttpEmbeddingVector(vector);
    } catch (err) {
      if (isAbortError(err)) throw err;
      log.debug(`EmbedHelper error: ${err}`);
      return null;
    }
  }

  private async callHostEmbed(
    input: string,
    provider: HostEmbeddingProvider | undefined,
    signal?: AbortSignal,
    inputType: HostEmbeddingInputType = "document",
  ): Promise<number[] | null> {
    if (!provider) return null;
    try {
      const vector = await provider.embed(input.slice(0, 8000), {
        signal: withTimeoutSignal(signal, 30_000),
        inputType,
      });
      return this.normalizeHostEmbeddingVector(vector);
    } catch (err) {
      if (isAbortError(err)) throw err;
      log.debug(`EmbedHelper host provider error: ${err}`);
      return null;
    }
  }

  private async callHostEmbedBatch(
    inputs: string[],
    provider: HostEmbeddingProvider,
    signal?: AbortSignal,
  ): Promise<(number[] | null)[]> {
    try {
      const vectors = await provider.embedBatch?.(
        inputs.map((input) => input.slice(0, 8000)),
        {
          signal: withTimeoutSignal(signal, 30_000),
          inputType: "document",
        },
      );
      if (!Array.isArray(vectors)) return inputs.map(() => null);
      return inputs.map((_, index) => this.normalizeHostEmbeddingVector(vectors[index]));
    } catch (err) {
      if (isAbortError(err)) throw err;
      log.debug(`EmbedHelper host provider batch error: ${err}`);
      return inputs.map(() => null);
    }
  }

  private normalizeHostEmbeddingVector(value: unknown): number[] | null {
    const vector = normalizeHostEmbeddingVector(value);
    if (!vector) return null;
    const expectedDimension = this.resolveHostEmbeddingExpectedDimension();
    if (expectedDimension !== null && vector.length !== expectedDimension) {
      return null;
    }
    return vector;
  }

  private resolveHostEmbeddingExpectedDimension(): number | null {
    const value = this.options.hostEmbeddingExpectedDimension;
    return typeof value === "number" && Number.isInteger(value) && value > 0
      ? value
      : null;
  }
}

function providerIdentity(provider: ProviderConfig): EmbedProviderIdentity {
  return `${provider.type}:${provider.model}`;
}

function normalizeHttpEmbeddingVector(vector: unknown): number[] | null {
  if (!Array.isArray(vector)) return null;
  const normalized: number[] = [];
  for (const component of vector) {
    if (typeof component !== "number" || !Number.isFinite(component)) {
      return null;
    }
    normalized.push(component);
  }
  return normalized;
}

import { fileURLToPath } from "node:url";
import path from "node:path";
import { log } from "../logger.js";
import type { ConversationChunk } from "./chunker.js";
import type { ConversationSearchResult } from "./search.js";
import { launchProcess } from "../runtime/child-process.js";

export interface FaissAdapterConfig {
  memoryDir: string;
  scriptPath?: string;
  pythonBin?: string;
  modelId: string;
  indexDir: string;
  upsertTimeoutMs: number;
  searchTimeoutMs: number;
  healthTimeoutMs: number;
  maxBatchSize: number;
  maxSearchK: number;
  spawnFn?: typeof launchProcess;
}

export interface FaissHealthResult {
  ok: boolean;
  status: "ok" | "degraded" | "error";
  indexPath: string;
  message?: string;
  manifest?: {
    version: number;
    modelId: string;
    normalizedModelId: string;
    dimension: number;
    chunkCount: number;
    updatedAt: string;
    lastSuccessfulRebuildAt: string;
  };
}

export interface FaissInspectResult extends FaissHealthResult {
  metadata: {
    chunkCount: number;
    hasIndex: boolean;
    hasMetadata: boolean;
    hasManifest: boolean;
  };
}

type SidecarCommand = "upsert" | "search" | "health" | "inspect" | "rebuild";

export class FaissAdapterError extends Error {
  constructor(message: string, readonly code: "timeout" | "non_zero_exit" | "malformed_output") {
    super(message);
    this.name = "FaissAdapterError";
  }
}

interface SidecarResult {
  ok?: boolean;
  error?: string;
  upserted?: number;
  rebuilt?: number;
  status?: "ok" | "degraded" | "error";
  manifest?: {
    version?: number;
    modelId?: string;
    normalizedModelId?: string;
    dimension?: number;
    chunkCount?: number;
    updatedAt?: string;
    lastSuccessfulRebuildAt?: string;
  };
  results?: Array<{
    path: string;
    snippet: string;
    score: number;
  }>;
  metadata?: {
    chunkCount?: number;
    hasIndex?: boolean;
    hasMetadata?: boolean;
    hasManifest?: boolean;
  };
}

function parseSidecarManifest(result: SidecarResult): FaissHealthResult["manifest"] | undefined {
  const manifest = result.manifest;
  if (
    !manifest ||
    typeof manifest.version !== "number" ||
    typeof manifest.modelId !== "string" ||
    typeof manifest.normalizedModelId !== "string" ||
    typeof manifest.dimension !== "number" ||
    typeof manifest.chunkCount !== "number" ||
    typeof manifest.updatedAt !== "string" ||
    typeof manifest.lastSuccessfulRebuildAt !== "string"
  ) {
    return undefined;
  }

  return {
    version: manifest.version,
    modelId: manifest.modelId,
    normalizedModelId: manifest.normalizedModelId,
    dimension: manifest.dimension,
    chunkCount: manifest.chunkCount,
    updatedAt: manifest.updatedAt,
    lastSuccessfulRebuildAt: manifest.lastSuccessfulRebuildAt,
  };
}

export function resolveDefaultFaissScriptPath(fromModuleUrl: string = import.meta.url): string {
  const currentFile = fileURLToPath(fromModuleUrl);
  const moduleDir = path.dirname(currentFile);

  // Source runtime: src/conversation-index/faiss-adapter.ts
  if (moduleDir.endsWith(`${path.sep}conversation-index`)) {
    return path.resolve(moduleDir, "..", "..", "scripts", "faiss_index.py");
  }

  // Bundled runtime: dist/index.js (or neighboring dist chunks)
  return path.resolve(moduleDir, "..", "scripts", "faiss_index.py");
}

export class FaissConversationIndexAdapter {
  private readonly pythonBin: string;
  private readonly scriptPath: string;
  private readonly indexPath: string;
  private readonly maxBatchSize: number;
  private readonly spawnFn: typeof launchProcess;

  constructor(private readonly config: FaissAdapterConfig) {
    if (!Number.isInteger(config.maxBatchSize) || config.maxBatchSize <= 0) {
      throw new RangeError("FAISS maxBatchSize must be a positive integer");
    }
    this.pythonBin = config.pythonBin && config.pythonBin.trim().length > 0 ? config.pythonBin.trim() : "python3";
    this.scriptPath = config.scriptPath && config.scriptPath.trim().length > 0
      ? config.scriptPath.trim()
      : resolveDefaultFaissScriptPath();
    this.indexPath = path.isAbsolute(config.indexDir)
      ? config.indexDir
      : path.join(config.memoryDir, config.indexDir);
    this.maxBatchSize = config.maxBatchSize;
    this.spawnFn = config.spawnFn ?? launchProcess;
  }

  async upsertChunks(
    chunks: ConversationChunk[],
    options: { retentionCutoffMs?: number } = {},
  ): Promise<number> {
    let totalUpserted = 0;
    for (let offset = 0; offset < chunks.length; offset += this.maxBatchSize) {
      const batch = chunks.slice(offset, offset + this.maxBatchSize);
      if (batch.length === 0) continue;
      const payload = {
        modelId: this.config.modelId,
        indexPath: this.indexPath,
        chunks: batch.map((chunk) => ({
          id: chunk.id,
          sessionKey: chunk.sessionKey,
          text: chunk.text,
          startTs: chunk.startTs,
          endTs: chunk.endTs,
        })),
        ...(typeof options.retentionCutoffMs === "number" &&
        Number.isFinite(options.retentionCutoffMs)
          ? { retentionCutoffMs: options.retentionCutoffMs }
          : {}),
      };
      const result = await this.runCommand("upsert", payload, this.config.upsertTimeoutMs);
      const upserted = result.upserted;
      if (typeof upserted !== "number" || !Number.isFinite(upserted)) {
        throw new FaissAdapterError("FAISS sidecar produced malformed upsert response", "malformed_output");
      }
      totalUpserted += Math.max(0, Math.floor(upserted));
    }
    return totalUpserted;
  }

  async searchChunks(query: string, topK: number): Promise<ConversationSearchResult[]> {
    const requestedTopK = Number.isFinite(topK) ? Math.floor(topK) : 0;
    const boundedTopK = this.config.maxSearchK > 0
      ? Math.max(0, Math.min(requestedTopK, this.config.maxSearchK))
      : 0;
    if (boundedTopK <= 0 || query.trim().length === 0) return [];
    const payload = {
      modelId: this.config.modelId,
      indexPath: this.indexPath,
      query,
      topK: boundedTopK,
    };
    const result = await this.runCommand("search", payload, this.config.searchTimeoutMs);
    if (!Array.isArray(result.results)) {
      throw new FaissAdapterError("FAISS sidecar produced malformed search response", "malformed_output");
    }
    const rows = result.results;
    return rows
      .filter((row) =>
        row &&
        typeof row.path === "string" &&
        typeof row.snippet === "string" &&
        typeof row.score === "number"
      )
      .map((row) => ({ path: row.path, snippet: row.snippet, score: row.score }));
  }

  async health(): Promise<FaissHealthResult> {
    const payload = {
      modelId: this.config.modelId,
      indexPath: this.indexPath,
    };
    const result = await this.runCommand("health", payload, this.config.healthTimeoutMs);
    if (result.status !== "ok" && result.status !== "degraded" && result.status !== "error") {
      throw new FaissAdapterError("FAISS sidecar produced malformed health response", "malformed_output");
    }
    return {
      ok: result.ok === true,
      status: result.status,
      indexPath: this.indexPath,
      message: typeof result.error === "string" && result.error.length > 0 ? result.error : undefined,
      manifest: parseSidecarManifest(result),
    };
  }

  async inspect(): Promise<FaissInspectResult> {
    const payload = {
      modelId: this.config.modelId,
      indexPath: this.indexPath,
    };
    const result = await this.runCommand("inspect", payload, this.config.healthTimeoutMs);
    if (result.status !== "ok" && result.status !== "degraded" && result.status !== "error") {
      throw new FaissAdapterError("FAISS sidecar produced malformed inspect response", "malformed_output");
    }
    return {
      ok: result.ok === true,
      status: result.status,
      indexPath: this.indexPath,
      message: typeof result.error === "string" && result.error.length > 0 ? result.error : undefined,
      manifest: parseSidecarManifest(result),
      metadata: {
        chunkCount:
          result.metadata && typeof result.metadata.chunkCount === "number"
            ? result.metadata.chunkCount
            : 0,
        hasIndex: result.metadata?.hasIndex === true,
        hasMetadata: result.metadata?.hasMetadata === true,
        hasManifest: result.metadata?.hasManifest === true,
      },
    };
  }

  async rebuildChunks(chunks: ConversationChunk[]): Promise<number> {
    const rebuildPayload = {
      modelId: this.config.modelId,
      indexPath: this.indexPath,
      chunks: chunks.map((chunk) => ({
        id: chunk.id,
        sessionKey: chunk.sessionKey,
        text: chunk.text,
        startTs: chunk.startTs,
        endTs: chunk.endTs,
      })),
    };
    const result = await this.runCommand("rebuild", rebuildPayload, this.config.upsertTimeoutMs);
    const rebuilt = result.rebuilt;
    if (typeof rebuilt !== "number" || !Number.isFinite(rebuilt)) {
      throw new FaissAdapterError("FAISS sidecar produced malformed rebuild response", "malformed_output");
    }
    const rebuildCount = Math.floor(rebuilt);
    if (rebuildCount !== chunks.length) {
      throw new FaissAdapterError(
        `FAISS sidecar rebuilt ${rebuildCount} chunk(s), expected ${chunks.length}`,
        "malformed_output",
      );
    }
    return rebuildCount;
  }

  private async runCommand(command: SidecarCommand, payload: object, timeoutMs: number): Promise<SidecarResult> {
    const args = [this.scriptPath, command];
    const child = this.spawnFn(this.pythonBin, args, {
      stdio: ["pipe", "pipe", "pipe"],
    });
    if (!child.stdin || !child.stdout || !child.stderr) {
      throw new FaissAdapterError(
        `FAISS sidecar missing stdio pipes (${command})`,
        "non_zero_exit",
      );
    }
    const stdinPipe = child.stdin;
    const stdoutPipe = child.stdout;
    const stderrPipe = child.stderr;

    const stdoutChunks: Buffer[] = [];
    const stderrChunks: Buffer[] = [];
    let timedOut = false;

    const timer = timeoutMs > 0
      ? setTimeout(() => {
        timedOut = true;
        child.kill("SIGKILL");
      }, timeoutMs)
      : undefined;

    stdoutPipe.on("data", (chunk: Buffer | string) => {
      stdoutChunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
    });
    stderrPipe.on("data", (chunk: Buffer | string) => {
      stderrChunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
    });

    let code: number | null;
    try {
      stdinPipe.write(JSON.stringify(payload));
      stdinPipe.end();

      code = await new Promise<number | null>((resolve, reject) => {
        const rejectAsProcessError = (err: unknown) => {
          const msg = err instanceof Error ? err.message : String(err);
          reject(new FaissAdapterError(`FAISS sidecar stream/process error (${command}): ${msg}`, "non_zero_exit"));
        };
        child.once("error", rejectAsProcessError);
        stdinPipe.once("error", rejectAsProcessError);
        child.once("close", (exitCode) => resolve(exitCode));
      });
    } catch (err) {
      if (err instanceof FaissAdapterError) throw err;
      const msg = err instanceof Error ? err.message : String(err);
      throw new FaissAdapterError(`FAISS sidecar stream/process error (${command}): ${msg}`, "non_zero_exit");
    } finally {
      if (timer) clearTimeout(timer);
    }

    const stdout = Buffer.concat(stdoutChunks).toString("utf-8").trim();
    const stderr = Buffer.concat(stderrChunks).toString("utf-8").trim();

    if (timedOut) {
      throw new FaissAdapterError(
        `FAISS sidecar command timed out (${command}, ${timeoutMs}ms)`,
        "timeout",
      );
    }
    if (code !== 0) {
      throw new FaissAdapterError(
        `FAISS sidecar exited non-zero (${command}, code=${code ?? "null"})${stderr ? `: ${stderr}` : ""}`,
        "non_zero_exit",
      );
    }
    if (stdout.length === 0) {
      throw new FaissAdapterError(
        `FAISS sidecar produced empty output (${command})`,
        "malformed_output",
      );
    }

    let parsed: SidecarResult;
    try {
      parsed = JSON.parse(stdout) as SidecarResult;
    } catch {
      throw new FaissAdapterError(
        `FAISS sidecar produced malformed JSON (${command})`,
        "malformed_output",
      );
    }

    if (parsed.ok === false) {
      const message = typeof parsed.error === "string" && parsed.error.length > 0
        ? parsed.error
        : `FAISS sidecar command failed (${command})`;
      throw new FaissAdapterError(message, "non_zero_exit");
    }
    if (parsed.ok !== true) {
      throw new FaissAdapterError(
        `FAISS sidecar produced malformed success envelope (${command})`,
        "malformed_output",
      );
    }

    return parsed;
  }
}

export async function failOpenFaissHealth(
  adapter: FaissConversationIndexAdapter | undefined,
): Promise<FaissHealthResult> {
  if (!adapter) {
    return { ok: false, status: "error", indexPath: "", message: "adapter-unavailable" };
  }
  try {
    return await adapter.health();
  } catch (err) {
    log.debug(`faiss adapter health failed (fail-open): ${err}`);
    return { ok: false, status: "error", indexPath: "", message: "adapter-error" };
  }
}

import type { SearchBackend, SearchExecutionOptions } from "../search/port.js";
import type { ConversationChunk } from "./chunker.js";
import { failOpenFaissHealth, type FaissConversationIndexAdapter } from "./faiss-adapter.js";
import {
  rebuildConversationChunksFailOpen,
  upsertConversationChunksFailOpen,
} from "./indexer.js";
import { searchConversationIndex, searchConversationIndexFaissFailOpen, type ConversationSearchResult } from "./search.js";

type CollectionState = "missing" | "unknown" | "present" | "skipped";

export interface ConversationQmdRuntime extends SearchBackend {
  isAvailable(): boolean;
  probe(): Promise<boolean>;
  ensureCollection(baseDir: string): Promise<CollectionState>;
  update(execution?: SearchExecutionOptions): Promise<void>;
  updateCollection(collection: string, execution?: SearchExecutionOptions): Promise<void>;
