  message?: string;
  metadata: {
    chunkCount: number | null;
    qmdAvailable?: boolean;
    debugStatus?: string;
    hasIndex?: boolean;
    hasMetadata?: boolean;
    hasManifest?: boolean;
    manifest?: {
