    };
  };
}

export interface ConversationIndexBackendInitResult {
  enabled: boolean;
  logLevel: "info" | "warn" | "debug";
  message: string;
}

export interface ConversationIndexBackend {
  readonly kind: "qmd" | "faiss";
  initialize(): Promise<ConversationIndexBackendInitResult>;
  search(query: string, maxResults: number): Promise<ConversationSearchResult[]>;
  update(
    chunks: ConversationChunk[],
    options: { embed: boolean; retentionCutoffMs?: number },
  ): Promise<{ embedded: boolean }>;
  rebuild(chunks: ConversationChunk[], options: { embed: boolean }): Promise<{ embedded: boolean; rebuilt: boolean }>;
  health(): Promise<ConversationIndexBackendHealth>;
  inspect(): Promise<ConversationIndexBackendInspection>;
}

export function createConversationIndexBackend(options: {
  enabled: boolean;
  backend: "qmd" | "faiss";
  getQmd?: () => ConversationQmdRuntime | undefined;
  getFaiss?: () => FaissConversationIndexAdapter | undefined;
  qmd?: ConversationQmdRuntime;
  faiss?: FaissConversationIndexAdapter;
  collectionDir: string;
}): ConversationIndexBackend | undefined {
  if (!options.enabled) return undefined;
  const getQmd = options.getQmd ?? (() => options.qmd);
  const getFaiss = options.getFaiss ?? (() => options.faiss);
  if (options.backend === "faiss") {
    return createFaissBackend(getFaiss);
  }
  return createQmdBackend(getQmd, options.collectionDir);
}

function createQmdBackend(
  getQmd: () => ConversationQmdRuntime | undefined,
  collectionDir: string,
): ConversationIndexBackend {
  return {
    kind: "qmd",
    async initialize() {
      const qmd = getQmd();
      if (!qmd) {
        return {
          enabled: true,
          logLevel: "warn",
          message: "Conversation index QMD: not available search backend disabled or unsupported",
        };
      }

      const available = await qmd.probe();
      if (!available) {
        return {
          enabled: true,
          logLevel: "warn",
          message: `Conversation index QMD: not available ${qmd.debugStatus()}`,
        };
      }

      const collectionState = await qmd.ensureCollection(collectionDir);
      if (collectionState === "missing") {
        return {
          enabled: false,
          logLevel: "warn",
          message: "Conversation index collection missing; disabling conversation semantic recall for this runtime",
        };
      }
      if (collectionState === "unknown") {
        return {
          enabled: true,
          logLevel: "warn",
          message: "Conversation index collection check unavailable; keeping conversation semantic recall enabled for fail-open behavior",
        };
      }
      if (collectionState === "skipped") {
        return {
          enabled: true,
          logLevel: "debug",
          message: "Conversation index collection check skipped in daemon-only mode",
        };
      }

      return {
        enabled: true,
        logLevel: "info",
        message: `Conversation index QMD: available ${qmd.debugStatus()}`,
      };
    },
    async search(query: string, maxResults: number) {
      const qmd = getQmd();
      if (!qmd || !qmd.isAvailable()) return [];
      return searchConversationIndex(qmd, query, maxResults);
    },
    async update(_chunks: ConversationChunk[], options: { embed: boolean; retentionCutoffMs?: number }) {
      const qmd = getQmd();
      if (!qmd || !qmd.isAvailable()) return { embedded: false };
      await qmd.update();
      if (options.embed) {
        await qmd.embed();
        return { embedded: true };
      }
      return { embedded: false };
    },
    async rebuild(_chunks: ConversationChunk[], options: { embed: boolean }) {
      const qmd = getQmd();
      if (!qmd || !qmd.isAvailable()) return { embedded: false, rebuilt: false };
      await qmd.update();
      if (options.embed) {
        await qmd.embed();
        return { embedded: true, rebuilt: true };
      }
      return { embedded: false, rebuilt: true };
    },
    async health() {
      const qmd = getQmd();
      let qmdAvailable = !!qmd?.isAvailable();
      if (!qmdAvailable && qmd) {
        try {
          qmdAvailable = await qmd.probe();
        } catch {
          qmdAvailable = false;
        }
      }

      return {
        backend: "qmd",
        status: qmdAvailable ? "ok" : "degraded",
        qmdAvailable,
      };
    },
    async inspect() {
      const qmd = getQmd();
      let qmdAvailable = !!qmd?.isAvailable();
      if (!qmdAvailable && qmd) {
        try {
          qmdAvailable = await qmd.probe();
        } catch {
          qmdAvailable = false;
        }
      }

      return {
        backend: "qmd",
        status: qmdAvailable ? "ok" : "degraded",
        available: qmdAvailable,
        indexPath: collectionDir,
        supportsIncrementalUpdate: true,
        message: qmd ? undefined : "Conversation index QMD runtime unavailable",
        metadata: {
          chunkCount: null,
          qmdAvailable,
          debugStatus: qmd?.debugStatus(),
        },
      };
    },
  };
}

function createFaissBackend(
  getFaiss: () => FaissConversationIndexAdapter | undefined,
): ConversationIndexBackend {
  return {
    kind: "faiss",
    async initialize() {
      const health = await failOpenFaissHealth(getFaiss());
      return health.status === "ok"
        ? {
            enabled: true,
            logLevel: "info",
            message: `Conversation index FAISS: available (status=${health.status})`,
          }
        : {
            enabled: true,
            logLevel: "warn",
            message: `Conversation index FAISS: degraded (${health.message ?? health.status})`,
          };
    },
    async search(query: string, maxResults: number) {
      return searchConversationIndexFaissFailOpen(getFaiss(), query, maxResults);
    },
    async update(chunks: ConversationChunk[], options: { embed: boolean; retentionCutoffMs?: number }) {
      await upsertConversationChunksFailOpen(getFaiss(), chunks, {
        retentionCutoffMs: options.retentionCutoffMs,
      });
      return { embedded: false };
    },
    async rebuild(chunks: ConversationChunk[], _options: { embed: boolean }) {
      const result = await rebuildConversationChunksFailOpen(getFaiss(), chunks);
      return {
        embedded: false,
        rebuilt: result.skipped !== true && result.rebuilt === chunks.length,
      };
    },
    async health() {
      const faiss = await failOpenFaissHealth(getFaiss());
      return {
        backend: "faiss",
        status: faiss.status === "ok" ? "ok" : "degraded",
        message: faiss.message,
        faiss,
      };
    },
    async inspect() {
      const adapter = getFaiss();
      if (!adapter) {
        return {
          backend: "faiss",
          status: "degraded",
          available: false,
          indexPath: "",
          supportsIncrementalUpdate: true,
          message: "Conversation index FAISS runtime unavailable",
          metadata: {
            chunkCount: 0,
            hasIndex: false,
            hasMetadata: false,
            hasManifest: false,
          },
        };
      }

      try {
        const inspection = await adapter.inspect();
        return {
          backend: "faiss",
          status: inspection.status === "ok" ? "ok" : "degraded",
          available: inspection.status === "ok",
          indexPath: inspection.indexPath,
          supportsIncrementalUpdate: true,
          message: inspection.message,
          metadata: {
            chunkCount: inspection.metadata.chunkCount,
            hasIndex: inspection.metadata.hasIndex,
            hasMetadata: inspection.metadata.hasMetadata,
            hasManifest: inspection.metadata.hasManifest,
            manifest: inspection.manifest,
          },
        };
      } catch (err) {
        const fallback = await failOpenFaissHealth(adapter);
        return {
          backend: "faiss",
          status: "degraded",
          available: false,
          indexPath: fallback.indexPath,
          supportsIncrementalUpdate: true,
          message: fallback.message ?? String(err),
          metadata: {
            chunkCount: fallback.manifest?.chunkCount ?? 0,
            hasIndex: false,
            hasMetadata: false,
            hasManifest: !!fallback.manifest,
            manifest: fallback.manifest,
          },
        };
      }
    },
  };
}

import type { CodexCliReasoningEffort } from "./types.js";

export interface CodexCliFallbackMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

export interface CodexCliFallbackConfig {
  apiKey?: string | Record<string, unknown>;
  executable?: unknown;
  codexCliExecutable?: unknown;
  reasoningEffort?: unknown;
  codexCliReasoningEffort?: unknown;
  retryOptions?: {
    timeoutMs?: unknown;
  };
}

export interface CodexCliFallbackOptions {
  timeoutMs?: number;
  signal?: AbortSignal;
}

export interface CodexCliFallbackResult {
  content: string;
  usage?: {
    inputTokens?: number;
    outputTokens?: number;
    totalTokens?: number;
  };
}

export interface CodexCliFallbackRequest {
  config: CodexCliFallbackConfig;
  modelId: string;
  messages: CodexCliFallbackMessage[];
  options: CodexCliFallbackOptions;
}

export type CodexCliFallbackRunner = (
  request: CodexCliFallbackRequest,
) => Promise<CodexCliFallbackResult>;

const VALID_CODEX_CLI_REASONING_EFFORTS = new Set<CodexCliReasoningEffort>([
  "low",
  "medium",
  "high",
  "xhigh",
]);

let processRunner: CodexCliFallbackRunner | undefined;

/**
 * True when a process-local Codex CLI transport is registered. Lets a default
 * runner (codex-subscription) register only when no host/benchmark runner has
 * claimed the seam, so explicit registrations always win.
 */
export function isCodexCliFallbackRunnerRegistered(): boolean {
  return processRunner !== undefined;
}

/** Current process-local Codex CLI runner, if any. */
export function getCodexCliFallbackRunnerForProcess(): CodexCliFallbackRunner | undefined {
  return processRunner;
}

/**
 * Registers the process-local Codex CLI transport. Core itself stays free of
 * child_process here; hosts and benchmark runtimes opt in, and the
 * codex-subscription module registers a subprocess runner on demand.
 */
export function setCodexCliFallbackRunnerForProcess(
  runner: CodexCliFallbackRunner | undefined,
): () => void {
  const previous = processRunner;
  processRunner = runner;
  return () => {
    processRunner = previous;
  };
}

export async function callCodexCliFallback(
  config: CodexCliFallbackConfig,
  modelId: string,
  messages: CodexCliFallbackMessage[],
  options: CodexCliFallbackOptions = {},
  runner: CodexCliFallbackRunner | undefined = processRunner,
): Promise<CodexCliFallbackResult> {
  if (!runner) {
    throw new Error(
      'codex-cli fallback transport is not registered; install a runner with setCodexCliFallbackRunnerForProcess() before using api: "codex-cli"',
    );
  }

  return await runner({
    config: normalizeCodexCliFallbackConfig(config),
    modelId: normalizeCodexCliModel(modelId),
    messages,
    options: normalizeCodexCliFallbackOptions(options),
  });
}

function normalizeCodexCliFallbackConfig(
  config: CodexCliFallbackConfig,
): CodexCliFallbackConfig {
  return {
    ...config,
    ...(config.executable !== undefined
      ? { executable: normalizeOptionalString(config.executable, "codex-cli executable") }
      : {}),
    ...(config.codexCliExecutable !== undefined
      ? { codexCliExecutable: normalizeOptionalString(config.codexCliExecutable, "codex-cli executable") }
      : {}),
    ...(config.reasoningEffort !== undefined
      ? { reasoningEffort: normalizeCodexCliReasoningEffort(config.reasoningEffort) }
      : {}),
    ...(config.codexCliReasoningEffort !== undefined
      ? { codexCliReasoningEffort: normalizeCodexCliReasoningEffort(config.codexCliReasoningEffort) }
      : {}),
    ...(config.retryOptions?.timeoutMs !== undefined
      ? { retryOptions: { timeoutMs: normalizeCodexCliTimeoutMs(config.retryOptions.timeoutMs) } }
      : {}),
  };
}

function normalizeCodexCliFallbackOptions(
  options: CodexCliFallbackOptions,
): CodexCliFallbackOptions {
  return {
    ...(options.timeoutMs !== undefined
      ? { timeoutMs: normalizeCodexCliTimeoutMs(options.timeoutMs) }
      : {}),
    ...(options.signal ? { signal: options.signal } : {}),
  };
}

function normalizeOptionalString(value: unknown, label: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new Error(`${label} must be a non-empty string`);
  }
  return value.trim();
}

function normalizeCodexCliModel(value: string): string {
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    throw new Error("codex-cli model must be a non-empty string");
  }
  return trimmed;
}

function normalizeCodexCliReasoningEffort(value: unknown): CodexCliReasoningEffort {
  if (typeof value !== "string") {
    throw new Error("codex-cli reasoningEffort must be one of low, medium, high, xhigh");
  }
  const normalized = value.trim().toLowerCase();
  if (VALID_CODEX_CLI_REASONING_EFFORTS.has(normalized as CodexCliReasoningEffort)) {
    return normalized as CodexCliReasoningEffort;
  }
  throw new Error("codex-cli reasoningEffort must be one of low, medium, high, xhigh");
}

export function normalizeCodexCliTimeoutMs(value: unknown): number {
  const parsed = typeof value === "number"
    ? value
    : typeof value === "string" && value.trim().length > 0
      ? Number(value)
      : NaN;
  if (!Number.isFinite(parsed) || !Number.isInteger(parsed) || parsed <= 0) {
    throw new Error("codex-cli timeoutMs must be a positive integer");
  }
  return parsed;
}

export const __codexCliFallbackTestHooks = {
  setRunCodexCliForTest: setCodexCliFallbackRunnerForProcess,
};

import path from "node:path";
import { lstat, readdir, readFile, realpath } from "node:fs/promises";
import { RECALL_FALLBACK_DIRS } from "../utils/category-dir.js";
import { assertPathInsideRoot } from "../utils/path-containment.js";
import { isErrnoCode } from "../utils/errno.js";
import { isMacOsReplicationJunkBasename } from "../utils/macos-replication-junk.js";

export interface IndexableDocument {
  /** Memory ID from frontmatter or filename stem */
  docid: string;
  /** Absolute file path */
  path: string;
  /** Markdown body (no YAML frontmatter) */
  content: string;
  /** First ~200 chars for display */
  snippet: string;
}

/**
 * Parse YAML frontmatter from a markdown string.
 * Returns the frontmatter key-value pairs and body, or null if no frontmatter block.
 */
function parseFrontmatter(raw: string): { data: Record<string, string>; body: string } | null {
  // Support both LF and CRLF line endings
  const normalized = raw.replace(/\r\n/g, "\n");
  const match = normalized.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!match) return null;

  const fmBlock = match[1];
  const body = (match[2] ?? "").trim();
  const data: Record<string, string> = {};

  for (const line of fmBlock.split("\n")) {
    const colonIdx = line.indexOf(":");
    if (colonIdx === -1) continue;
    const key = line.slice(0, colonIdx).trim();
    const value = line.slice(colonIdx + 1).trim();
    data[key] = value;
  }

  return { data, body };
}

/**
 * Recursively scan a directory for `.md` files and return IndexableDocuments.
 */
async function scanDir(dir: string, memoryRootReal: string): Promise<IndexableDocument[]> {
  const docs: IndexableDocument[] = [];
  try {
    const dirStat = await lstat(dir);
    if (dirStat.isSymbolicLink()) {
      throw new Error(`Refusing to scan symlinked memory category directory: ${dir}`);
    }
    if (!dirStat.isDirectory()) {
      const error = new Error(`Memory category path is not a directory: ${dir}`) as NodeJS.ErrnoException;
      error.code = "ENOTDIR";
      throw error;
    }
    assertPathInsideRoot(memoryRootReal, await realpath(dir), dir);

    const entries = await readdir(dir, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isSymbolicLink()) continue;
      // QMD's indexer already skips hidden paths. This scanner is the
      // non-QMD index input and must ignore the same Finder metadata.
      if (isMacOsReplicationJunkBasename(entry.name)) continue;
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        assertPathInsideRoot(memoryRootReal, await realpath(fullPath), fullPath);
        const sub = await scanDir(fullPath, memoryRootReal);
        docs.push(...sub);
      } else if (entry.name.endsWith(".md")) {
        try {
          assertPathInsideRoot(memoryRootReal, await realpath(fullPath), fullPath);
          const raw = await readFile(fullPath, "utf-8");
          const parsed = parseFrontmatter(raw);
          const body = parsed ? parsed.body : raw.trim();
          const docid = parsed?.data.id || path.basename(entry.name, ".md");
          docs.push({
            docid,
            path: fullPath,
            content: body,
            snippet: body.slice(0, 200),
          });
        } catch {
          // Skip unreadable files
        }
      }
    }
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) {
      // Optional category directories may not exist yet.
      return docs;
    }
    throw err;
  }
  return docs;
}

/**
 * Scan every recall category subdir of memoryDir for indexable markdown
 * documents. The directory set is derived from `RECALL_FALLBACK_DIRS`
 * (utils/category-dir.ts → ALL_CATEGORY_DIRS minus non-recall queue dirs) —
 * the single source of truth — so adding a new category never requires
 * touching this scanner. Non-QMD backends (Orama / Meilisearch / LanceDB)
 * build their index through this helper; deriving from RECALL_FALLBACK_DIRS
 * keeps them in parity with writeMemory's category-dir routing (issue #1546)
 * and the QMD filesystem-fallback corpus. reasoning-traces/ and the other
 * category dirs are covered automatically (issue #564 PR 3 no longer needs a
 * hand-maintained list). scanDir tolerates missing dirs (ENOENT), so category
 * dirs that do not exist yet are skipped.
 */
export async function scanMemoryDir(memoryDir: string): Promise<IndexableDocument[]> {
  let memoryRootReal: string;
  try {
    memoryRootReal = await realpath(memoryDir);
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) {
      return [];
    }
    throw err;
  }
  const perDir = await Promise.all(
    RECALL_FALLBACK_DIRS.map((dir) => scanDir(path.join(memoryDir, dir), memoryRootReal)),
  );
  return perDir.flat();
}

import { throwIfAborted } from "../abort-error.js";
import type { SearchExecutionOptions } from "./port.js";

export function isSearchAborted(execution?: SearchExecutionOptions): boolean {
  return execution?.signal?.aborted === true;
}

export function throwIfSearchAborted(
  execution?: SearchExecutionOptions,
  message = "search operation aborted",
): void {
  throwIfAborted(execution?.signal, message);
}

export function withTimeoutSignal(signal: AbortSignal | undefined, timeoutMs: number): AbortSignal {
  const timeoutSignal = AbortSignal.timeout(timeoutMs);
  return signal ? AbortSignal.any([signal, timeoutSignal]) : timeoutSignal;
}

import { expandUnsegmentableRecallNGrams, isUnsegmentableRecallChar } from "../recall-tokenization.js";

/**
 * Language marker persisted inside Orama index files (`.msp`). Orama persists
 * `tokenizer.language` with the index, so this doubles as the tokenization
 * version: `OramaBackend` detects any other marker on restore and rebuilds
 * the full-text index (issue #2187). Bump the suffix whenever tokenization
 * changes.
 */
export const ORAMA_CJK_TOKENIZER_LANGUAGE = "english+cjk-v1";

/** Minimal structural surface of `@orama/orama` this module consumes. */
export interface OramaTokenizerComponents {
  components: {
    tokenizer: {
      createTokenizer: (config: { language: string }) => OramaTokenizer;
    };
  };
}

export interface OramaTokenizer {
  language: string;
  normalizationCache: Map<string, string>;
  tokenize: (raw: string, language?: string, prop?: string, withCache?: boolean) => string[];
}

const THAI_SCRIPT_CHAR = /[\p{Script=Thai}]/u;
const WORD_CHAR = /[\p{L}\p{N}\p{M}]/u;
const COMBINING_MARK = /\p{M}/u;
const WHITESPACE_CHAR = /\s/u;
/**
 * Chars the stock English tokenizer keeps inside a token. Input made only of
 * these (plus whitespace) is delegated to the stock tokenizer byte-for-byte so
 * existing English indexes stay term-compatible.
 */
const LEGACY_TOKENIZER_CHAR = /[A-Za-zàèéìòóù0-9_'-]/u;

/**
 * Space-free scripts: CJK per the shared recall segmentation strategy, plus
 * Thai. Runs in these scripts are indexed as character n-grams so phrase
 * queries match without word boundaries.
 */
export function isSpaceFreeScriptChar(char: string): boolean {
  return isUnsegmentableRecallChar(char) || THAI_SCRIPT_CHAR.test(char);
}

/**
 * True when tokenizing the value differs from the stock English tokenizer —
 * i.e. the value contains characters outside the stock keep-set that this
 * tokenizer still indexes as token material: word characters (whole-word
 * non-ASCII scripts), combining marks (attached to runs), and space-free
 * scripts (CJK/Thai n-grams). Symbols and punctuation that are separators in
 * BOTH tokenizers do not count. `OramaBackend` uses this to decide whether a
 * stale pre-CJK index needs re-indexing on upgrade.
 */
export function containsNonLegacyTokenizerChars(value: string): boolean {
  for (const ch of value) {
    if (LEGACY_TOKENIZER_CHAR.test(ch) || WHITESPACE_CHAR.test(ch)) continue;
    if (WORD_CHAR.test(ch) || COMBINING_MARK.test(ch) || isSpaceFreeScriptChar(ch)) {
      return true;
    }
  }
  return false;
}

/**
 * Orama tokenizer component that segments space-free scripts (CJK, Thai).
 *
 * - CJK/Thai runs expand to the same n-gram set the recall query-side
 *   tokenizer (`recall-tokenization.ts`) produces, so index-side and
 *   query-side tokens agree.
 * - Other non-Latin scripts (Hangul, Cyrillic, Greek, Arabic, ...) are kept
 *   as whole words instead of being dropped by the English splitter.
 * - Legacy Latin content tokenizes exactly like the stock English tokenizer;
 *   content with other characters keeps every stock token and additionally
 *   indexes non-ASCII words whole (e.g. "über" adds "über" beside "ber").
 */
export function createCjkCapableTokenizer(oramaModule: OramaTokenizerComponents): OramaTokenizer {
  const base = oramaModule.components.tokenizer.createTokenizer({ language: "english" });

  const tokenize = (raw: string, _language?: string, prop?: string, withCache?: boolean): string[] => {
    if (typeof raw !== "string") return [];
    const normalized = raw.normalize("NFC");

    if (!containsNonLegacyTokenizerChars(normalized)) {
      return base.tokenize(normalized, "english", prop, withCache);
    }

    // The stock tokenizer treats every non-legacy char as a separator, so its
    // output over the raw input already carries the legacy-Latin tokens
    // (e.g. the "nebula-472" in "Nebula-472 東京都庁").
    const tokens = base.tokenize(normalized, "english", prop, withCache);
    const seen = new Set(tokens);

    const pushToken = (token: string) => {
      if (token && !seen.has(token)) {
        seen.add(token);
        tokens.push(token);
      }
    };

    let spaceFreeRun = "";
    let wordRun = "";
    const flushSpaceFreeRun = () => {
      if (!spaceFreeRun) return;
      for (const token of expandUnsegmentableRecallNGrams(spaceFreeRun)) {
        pushToken(token);
      }
      spaceFreeRun = "";
    };
    const flushWordRun = () => {
      if (!wordRun) return;
      pushToken(wordRun.toLowerCase());
      wordRun = "";
    };

    for (const ch of normalized) {
      if (isSpaceFreeScriptChar(ch)) {
        flushWordRun();
        spaceFreeRun += ch;
      } else if (COMBINING_MARK.test(ch)) {
        if (spaceFreeRun) spaceFreeRun += ch;
        else if (wordRun) wordRun += ch;
      } else if (WORD_CHAR.test(ch) && !LEGACY_TOKENIZER_CHAR.test(ch)) {
        flushSpaceFreeRun();
        wordRun += ch;
      } else {
        flushSpaceFreeRun();
        flushWordRun();
      }
    }
    flushSpaceFreeRun();
    flushWordRun();

    return tokens;
  };

  return {
    language: ORAMA_CJK_TOKENIZER_LANGUAGE,
    normalizationCache: base.normalizationCache,
    tokenize,
  };
}

export type HostEmbeddingInputType =
  | "query"
  | "document"
  | "semantic"
  | "classification"
  | "clustering";

export interface HostEmbeddingProvider {
  id: string;
  model?: string;
  dimensions?: number;
  embed(
    text: string,
    options?: { signal?: AbortSignal; inputType?: HostEmbeddingInputType },
  ): Promise<ArrayLike<number> | null>;
  embedBatch?(
    texts: string[],
    options?: { signal?: AbortSignal; inputType?: HostEmbeddingInputType },
  ): Promise<Array<ArrayLike<number> | null>>;
  close?: () => Promise<void> | void;
}

const HOST_EMBEDDING_PROVIDERS_KEY = Symbol.for(
  "remnic.hostEmbeddingProviders",
);

function providerMap(): Map<string, HostEmbeddingProvider> {
  const store = globalThis as Record<PropertyKey, unknown>;
  const existing = store[HOST_EMBEDDING_PROVIDERS_KEY];
  if (existing instanceof Map) {
    return existing as Map<string, HostEmbeddingProvider>;
  }
  const created = new Map<string, HostEmbeddingProvider>();
  store[HOST_EMBEDDING_PROVIDERS_KEY] = created;
  return created;
}

export function registerHostEmbeddingProvider(
  scope: string,
  provider: HostEmbeddingProvider,
): () => void {
  const key = normalizeScope(scope);
  const providers = providerMap();
  const previous = providers.get(key);
  if (previous && previous !== provider) {
    void previous.close?.();
  }
  providers.set(key, provider);
  return () => {
    const providers = providerMap();
    if (providers.get(key) === provider) {
      providers.delete(key);
      void provider.close?.();
    }
  };
}

export function getHostEmbeddingProvider(
  scope: string,
): HostEmbeddingProvider | undefined {
  return providerMap().get(normalizeScope(scope));
}

export function clearHostEmbeddingProvidersForTest(): void {
  providerMap().clear();
}

export function normalizeHostEmbeddingVector(value: unknown): number[] | null {
  if (!Array.isArray(value) && (!ArrayBuffer.isView(value) || value instanceof DataView)) {
    return null;
  }
  const vector = Array.from(value as unknown as ArrayLike<unknown>);
  return vector.length > 0 &&
    vector.every((component): component is number => {
      return typeof component === "number" && Number.isFinite(component);
    })
    ? vector
    : null;
}

function normalizeScope(scope: string): string {
  const normalized = typeof scope === "string" ? scope.trim() : "";
  return normalized || "default";
}

import { lstat, mkdir, writeFile } from "node:fs/promises";
import type { Stats } from "node:fs";
import { createHash } from "node:crypto";
import path from "node:path";
import { log } from "../logger.js";
import type { FaissConversationIndexAdapter } from "./faiss-adapter.js";
import type { ConversationChunk } from "./chunker.js";

const MAX_PATH_COMPONENT_LENGTH = 200;

function sanitizePathComponent(
  value: string,
  fallback: string,
  opts: { lowercase?: boolean } = {},
): string {
  const raw = typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
  const normalized = opts.lowercase ? raw.toLowerCase() : raw;
  const sanitized = normalized
    .replace(/[^a-zA-Z0-9._-]+/g, "_")
    .slice(0, MAX_PATH_COMPONENT_LENGTH);
  if (!sanitized || sanitized === "." || sanitized === "..") {
    return fallback;
  }
  return sanitized;
}

export function sanitizeSessionKey(sessionKey: string): string {
  const raw = typeof sessionKey === "string" && sessionKey.trim().length > 0
    ? sessionKey.trim()
    : "";
  const safe = sanitizePathComponent(raw, "unknown-session", { lowercase: true });
  if (!raw) return safe;
  const suffix = `-${createHash("sha256").update(raw).digest("hex").slice(0, 12)}`;
  return `${safe.slice(0, MAX_PATH_COMPONENT_LENGTH - suffix.length)}${suffix}`;
}

function sanitizeChunkId(id: string): string {
  return sanitizePathComponent(id, "chunk");
}

function yamlQuotedScalar(value: string): string {
  return JSON.stringify(value);
}

function datePathComponent(startTs: string): string {
  const match = typeof startTs === "string"
    ? /^(\d{4})-(\d{2})-(\d{2})T/.exec(startTs)
    : null;
  if (!match) {
    throw new Error("invalid conversation chunk start timestamp");
  }
  const date = new Date(startTs);
  if (!Number.isFinite(date.getTime())) {
    throw new Error("invalid conversation chunk start timestamp");
  }
  const [, year, month, day] = match;
  if (
    date.getUTCFullYear() !== Number(year) ||
    date.getUTCMonth() + 1 !== Number(month) ||
    date.getUTCDate() !== Number(day)
  ) {
    throw new Error("invalid conversation chunk start timestamp");
  }
  return date.toISOString().slice(0, 10);
}

function resolveInsideRoot(rootDir: string, candidate: string): string {
  const root = path.resolve(rootDir);
  const resolved = path.resolve(candidate);
  const rel = path.relative(root, resolved);
  if (
    rel === "" ||
    (rel !== ".." && !rel.startsWith(`..${path.sep}`) && !path.isAbsolute(rel))
  ) {
    return resolved;
  }
  throw new Error("conversation chunk path escapes index root");
}

async function lstatIfExists(candidate: string): Promise<Stats | undefined> {
  try {
    return await lstat(candidate);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return undefined;
    throw err;
  }
}

async function rejectSymlinkIfExists(candidate: string): Promise<void> {
  const stat = await lstatIfExists(candidate);
  if (stat?.isSymbolicLink()) {
    throw new Error("conversation chunk path contains symlink");
  }
}

async function rejectExistingSymlinksInPath(baseDir: string, candidate: string): Promise<void> {
  const base = path.resolve(baseDir);
  const resolved = path.resolve(candidate);

  let current = base;
  while (current !== path.dirname(current)) {
    const stat = await lstatIfExists(current);
    if (stat) {
      if (stat.isSymbolicLink()) {
        throw new Error("conversation chunk path contains symlink");
      }
      break;
    }
    current = path.dirname(current);
  }

  const relative = path.relative(base, resolved);
  if (relative === "") return;

  current = base;
  for (const part of relative.split(path.sep)) {
    current = path.join(current, part);
    const stat = await lstatIfExists(current);
    if (!stat) return;
    if (stat.isSymbolicLink()) {
      throw new Error("conversation chunk path contains symlink");
    }
  }
}

async function rejectExistingSymlinkAncestors(
  rootDir: string,
  candidate: string,
): Promise<void> {
  const root = path.resolve(rootDir);
  const resolved = resolveInsideRoot(root, candidate);
  await rejectExistingSymlinksInPath(root, resolved);
}

export async function writeConversationChunks(
  rootDir: string,
  chunks: ConversationChunk[],
): Promise<string[]> {
  const written: string[] = [];
  const root = path.resolve(rootDir);
  await rejectExistingSymlinksInPath(root, root);
  await mkdir(root, { recursive: true });
  await rejectExistingSymlinksInPath(root, root);

  for (const c of chunks) {
    const safe = sanitizeSessionKey(c.sessionKey);
    const date = datePathComponent(c.startTs);
    const dir = resolveInsideRoot(root, path.join(root, safe, date));
    await rejectExistingSymlinkAncestors(root, dir);
    await mkdir(dir, { recursive: true });
    await rejectExistingSymlinkAncestors(root, dir);
    const fp = resolveInsideRoot(root, path.join(dir, `${sanitizeChunkId(c.id)}.md`));
    await rejectExistingSymlinkAncestors(root, path.dirname(fp));
    await rejectSymlinkIfExists(fp);
    const content =
      `---\n` +
      `kind: conversation_chunk\n` +
      `sessionKey: ${yamlQuotedScalar(c.sessionKey)}\n` +
      `startTs: ${yamlQuotedScalar(c.startTs)}\n` +
      `endTs: ${yamlQuotedScalar(c.endTs)}\n` +
      `---\n\n` +
      c.text +
      "\n";
    await writeFile(fp, content, "utf-8");
    written.push(fp);
  }
  return written;
}

export interface ConversationChunkUpsertResult {
  upserted: number;
  skipped: boolean;
  reason?: "adapter-unavailable" | "adapter-error";
}

export interface ConversationChunkRebuildResult {
  rebuilt: number;
  skipped: boolean;
  reason?: "adapter-unavailable" | "adapter-error";
}

export async function upsertConversationChunksFailOpen(
  adapter: FaissConversationIndexAdapter | undefined,
  chunks: ConversationChunk[],
  options: { retentionCutoffMs?: number } = {},
): Promise<ConversationChunkUpsertResult> {
  if (!adapter) {
    return { upserted: 0, skipped: true, reason: "adapter-unavailable" };
  }
  try {
    const upserted = await adapter.upsertChunks(chunks, options);
    return { upserted, skipped: false };
  } catch (err) {
    log.debug(`conversation index FAISS upsert failed (fail-open): ${err}`);
    return { upserted: 0, skipped: true, reason: "adapter-error" };
  }
}

export async function rebuildConversationChunksFailOpen(
  adapter: FaissConversationIndexAdapter | undefined,
  chunks: ConversationChunk[],
): Promise<ConversationChunkRebuildResult> {
  if (!adapter) {
    return { rebuilt: 0, skipped: true, reason: "adapter-unavailable" };
  }
  try {
    const rebuilt = await adapter.rebuildChunks(chunks);
    return { rebuilt, skipped: false };
  } catch (err) {
    log.debug(`conversation index FAISS rebuild failed (fail-open): ${err}`);
    return { rebuilt: 0, skipped: true, reason: "adapter-error" };
  }
}

import { log } from "../logger.js";
import type { SearchBackend } from "../search/port.js";
import type { FaissConversationIndexAdapter } from "./faiss-adapter.js";

export interface ConversationSearchResult {
  path: string;
  snippet: string;
  score: number;
}

export async function searchConversationIndex(
  qmd: SearchBackend,
  query: string,
  maxResults: number,
): Promise<ConversationSearchResult[]> {
  try {
    const results = await qmd.search(query, undefined, maxResults);
    return results.map((r) => ({ path: r.path, snippet: r.snippet, score: r.score }));
  } catch (err) {
    log.debug(`conversation index search failed: ${err}`);
    return [];
  }
}

export async function searchConversationIndexFaissFailOpen(
  adapter: FaissConversationIndexAdapter | undefined,
  query: string,
  maxResults: number,
): Promise<ConversationSearchResult[]> {
  if (!adapter) return [];
  try {
    return await adapter.searchChunks(query, maxResults);
  } catch (err) {
    log.debug(`conversation index FAISS search failed (fail-open): ${err}`);
    return [];
  }
}
